  // ==========================================
  // 2. INDEXEDDB RECEIPT STORAGE LAYER
  // ==========================================
  const DB_NAME = isDemoMode() ? 'FinlandShowcaseReceiptsDB' : 'FinanceTrackerReceiptsDB';
  const DB_VERSION = 1;
  const STORE_NAME = 'receipts';

  function openReceiptDB() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);
      request.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'expenseId' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  const CLOUD_VAULT_REPO = 'omgorigold-maker/finland-vault';
  const CLOUD_VAULT_API_BASE = 'https://api.github.com/repos/' + CLOUD_VAULT_REPO + '/contents';

  function parseCandidateCloudKey(rawInput) {
    const str = String(rawInput || '').trim();
    if (!str) return '';
    try {
      if (str.includes('cloud_key=')) {
        const match = str.match(/[?&#]cloud_key=([^&#\s]+)/);
        if (match && match[1]) return decodeURIComponent(match[1]).trim();
      }
    } catch (e) {}
    return str;
  }

  function extractCloudVaultKeyFromUrl() {
    try {
      if (!window.location) return '';
      let foundKey = '';
      if (window.location.search) {
        const urlParams = new URLSearchParams(window.location.search);
        const ck = urlParams.get('cloud_key');
        if (ck) {
          foundKey = ck.trim();
          urlParams.delete('cloud_key');
          const restSearch = urlParams.toString();
          const cleanUrl = window.location.pathname + (restSearch ? '?' + restSearch : '') + (window.location.hash || '');
          if (window.history && typeof window.history.replaceState === 'function') {
            window.history.replaceState({}, document.title, cleanUrl);
          }
        }
      }
      if (window.location.hash && window.location.hash.includes('cloud_key=')) {
        const rawHash = window.location.hash.slice(1);
        if (rawHash.startsWith('cloud_key=')) {
          foundKey = decodeURIComponent(rawHash.slice('cloud_key='.length)).trim();
          const cleanUrl = window.location.pathname + (window.location.search || '');
          if (window.history && typeof window.history.replaceState === 'function') {
            window.history.replaceState({}, document.title, cleanUrl);
          }
        } else if (rawHash.includes('&cloud_key=')) {
          const [tabPart, keyPart] = rawHash.split('&cloud_key=');
          foundKey = decodeURIComponent((keyPart || '').split('&')[0]).trim();
          const cleanUrl = window.location.pathname + (window.location.search || '') + (tabPart ? '#' + tabPart : '');
          if (window.history && typeof window.history.replaceState === 'function') {
            window.history.replaceState({}, document.title, cleanUrl);
          }
        }
      }
      if (foundKey) {
        localStorage.setItem('vault_cloud_gh_token', foundKey);
        localStorage.setItem('vault_auth_token', foundKey);
        localStorage.removeItem('finland_local_unpushed_dirty');
        return foundKey;
      }
    } catch (e) {}
    try {
      return localStorage.getItem('vault_cloud_gh_token') || '';
    } catch (e) {
      return '';
    }
  }

  function isCloudVaultHost() {
    try {
      if (typeof window !== 'undefined' && window.__FINLAND_DEMO_MODE__) {
        return false;
      }
      if (window.location && window.location.pathname && window.location.pathname.indexOf('finland-showcase') !== -1) {
        return false;
      }
      if (window.location && window.location.hostname && window.location.hostname.endsWith('github.io')) {
        return true;
      }
      if (localStorage.getItem('vault_force_cloud_mode') === '1') {
        return true;
      }
    } catch (e) {}
    return false;
  }

  function utf8ToBase64(str) {
    try {
      const bytes = new TextEncoder().encode(str);
      let binary = '';
      const chunkSize = 0x8000;
      for (let i = 0; i < bytes.length; i += chunkSize) {
        binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize));
      }
      return btoa(binary);
    } catch (e) {
      return btoa(unescape(encodeURIComponent(str)));
    }
  }

  function base64ToUtf8(b64) {
    const clean = String(b64 || '').replace(/\s+/g, '');
    try {
      const binary = atob(clean);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
      }
      return new TextDecoder().decode(bytes);
    } catch (e) {
      return decodeURIComponent(escape(atob(clean)));
    }
  }

  function normalizeVaultPayloadKeys(rawObj) {
    if (!rawObj || typeof rawObj !== 'object') return {};
    const legacyPrefix = ['vault', 'spend_'].join('');
    const out = {};
    Object.keys(rawObj).forEach(k => {
      if (k.startsWith(legacyPrefix)) {
        const newKey = 'finland_' + k.slice(legacyPrefix.length);
        if (out[newKey] === undefined) {
          out[newKey] = rawObj[k];
        }
      } else {
        out[k] = rawObj[k];
      }
    });
    return out;
  }

  function scrutinizeAndMergeVaultPayload(existingData, incomingData) {
    const existing = normalizeVaultPayloadKeys(existingData);
    const incoming = normalizeVaultPayloadKeys(incomingData);

    const reqEpoch = existing._restore_epoch ? String(existing._restore_epoch) : '';
    if (reqEpoch && String(incoming._restore_epoch || '') !== reqEpoch) {
      return {
        rejected: true,
        response: {
          status: 'ignored_stale_epoch',
          saved_at: existing._last_synced || '',
          _restore_epoch: reqEpoch
        }
      };
    }

    const merged = Object.assign({}, existing);
    const arrayCollectionKeys = new Set([
      'finland_expenses_v2',
      'finland_subscriptions_v2',
      'finland_notes_v1',
      'finland_studio_docs_v1',
      'finland_debts_v1',
      'finland_wishlist_v1'
    ]);

    for (const [k, v] of Object.entries(incoming)) {
      if (k === '_last_synced') continue;
      if (typeof v === 'string') {
        const stripped = v.trim();
        const existingVal = existing[k];
        if ((stripped === '[]' || stripped === '{}' || stripped === '') && typeof existingVal === 'string' && existingVal.trim() !== '' && existingVal.trim() !== '[]' && existingVal.trim() !== '{}') {
          if (stripped === '[]') {
            try {
              const parsedExisting = JSON.parse(existingVal);
              if (Array.isArray(parsedExisting) && parsedExisting.length <= 1) {
                merged[k] = v;
                continue;
              }
            } catch (e) {}
          }
          continue;
        }
        if (arrayCollectionKeys.has(k) && typeof existingVal === 'string' && existingVal.trim().startsWith('[')) {
          try {
            const existingArr = JSON.parse(existingVal);
            const incomingArr = JSON.parse(v);
            if (Array.isArray(existingArr) && Array.isArray(incomingArr)) {
              if (existingArr.length - incomingArr.length > 1 && !incoming._allow_bulk_delete) {
                const getWiseKey = (item) => {
                  if (!item || typeof item !== 'object') return '';
                  if (item.wise_id) return String(item.wise_id);
                  const idStr = String(item.id || '');
                  return idStr.startsWith('exp_wise_') ? idStr.split('_').pop() : '';
                };
                const incomingIds = new Set(incomingArr.map(item => item && item.id).filter(Boolean));
                const incomingWiseKeys = new Set(incomingArr.map(getWiseKey).filter(Boolean));
                const preserved = incomingArr.slice();
                for (const oldItem of existingArr) {
                  const wKey = getWiseKey(oldItem);
                  if (oldItem && oldItem.id && !incomingIds.has(oldItem.id) && (!wKey || !incomingWiseKeys.has(wKey))) {
                    preserved.push(oldItem);
                    incomingIds.add(oldItem.id);
                    if (wKey) incomingWiseKeys.add(wKey);
                  }
                }
                merged[k] = JSON.stringify(preserved);
                continue;
              }
            }
          } catch (e) {}
        }
        if (k === 'finland_budget_data_v1' && typeof existingVal === 'string' && existingVal.trim().startsWith('{')) {
          try {
            const existingBudget = JSON.parse(existingVal);
            const incomingBudget = JSON.parse(v);
            if (existingBudget && typeof existingBudget === 'object' && incomingBudget && typeof incomingBudget === 'object') {
              let modifiedBudget = false;
              for (const arrField of ['projects', 'leads', 'incomes', 'categories', 'poSavedTemplates']) {
                const exList = existingBudget[arrField];
                const inList = incomingBudget[arrField];
                if (Array.isArray(exList) && exList.length > 0 && (!Array.isArray(inList) || exList.length - inList.length > 1)) {
                  incomingBudget[arrField] = exList;
                  modifiedBudget = true;
                }
              }
              if (existingBudget.poDefaultTemplate && !incomingBudget.poDefaultTemplate) {
                incomingBudget.poDefaultTemplate = existingBudget.poDefaultTemplate;
                modifiedBudget = true;
              }
              if (modifiedBudget) {
                merged[k] = JSON.stringify(incomingBudget);
                continue;
              }
            }
          } catch (e) {}
        }
      }
      merged[k] = v;
    }

    merged._last_synced = new Date().toISOString();
    return { rejected: false, merged };
  }

  // Install transparent Cloud Vault Fetch Bridge when hosted on github.io (or forced cloud mode)
  (function installCloudVaultFetchBridge() {
    if (typeof window === 'undefined' || typeof window.fetch !== 'function') return;
    extractCloudVaultKeyFromUrl();
    const nativeFetch = window.fetch.bind(window);

    function makeJsonResponse(obj, status = 200) {
      return new Response(JSON.stringify(obj), {
        status,
        headers: { 'Content-Type': 'application/json' }
      });
    }

    async function ghApiFetch(repoPath, options = {}) {
      const ghToken = extractCloudVaultKeyFromUrl() || getVaultAuthToken();
      if (!ghToken) {
        return { ok: false, status: 401, json: async () => ({ status: 'error', message: 'Missing Cloud Vault Key' }) };
      }
      const sep = repoPath.includes('?') ? '&' : '?';
      const url = CLOUD_VAULT_API_BASE + '/' + repoPath.replace(/^\/+/, '') + (options.method && options.method !== 'GET' ? '' : sep + '_t=' + Date.now());
      const headers = Object.assign({
        'Authorization': 'Bearer ' + ghToken,
        'Accept': 'application/vnd.github.v3+json',
        'X-GitHub-Api-Version': '2022-11-28'
      }, options.headers || {});
      return nativeFetch(url, Object.assign({}, options, { headers, cache: 'no-store' }));
    }

    async function readGhJsonFile(repoPath) {
      const res = await ghApiFetch(repoPath, { method: 'GET' });
      if (res.status === 401 || res.status === 403) return { status: 401, data: null, sha: null };
      if (res.status === 404) return { status: 404, data: null, sha: null };
      if (!res.ok) return { status: res.status, data: null, sha: null };
      const meta = await res.json();
      const sha = meta && meta.sha ? meta.sha : null;
      let rawText = '';
      if (meta && meta.content) {
        rawText = base64ToUtf8(meta.content);
      } else {
        const rawRes = await ghApiFetch(repoPath, {
          method: 'GET',
          headers: { 'Accept': 'application/vnd.github.v3.raw' }
        });
        if (!rawRes.ok) return { status: rawRes.status, data: null, sha };
        rawText = await rawRes.text();
      }
      return { status: 200, data: JSON.parse(rawText || '{}'), sha };
    }

    async function writeGhJsonFile(repoPath, jsonObj, sha, commitMsg) {
      const contentStr = JSON.stringify(jsonObj, null, 2);
      const bodyObj = {
        message: commitMsg || ('sync(cloud): update ' + repoPath),
        content: utf8ToBase64(contentStr)
      };
      if (sha) bodyObj.sha = sha;
      return ghApiFetch(repoPath, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(bodyObj)
      });
    }

    window.fetch = async function(input, init = {}) {
      const urlStr = typeof input === 'string' ? input : (input && input.url ? input.url : String(input));
      if (isDemoMode() && urlStr.includes('/api/')) {
        return makeJsonResponse({ status: 'ok', mode: 'showcase-demo', ids: [] }, 200);
      }
      if (!isCloudVaultHost() || !urlStr.includes('/api/')) {
        return nativeFetch(input, init);
      }

      const method = String((init && init.method) || (input && input.method) || 'GET').toUpperCase();
      let apiPath = urlStr;
      try {
        if (urlStr.startsWith('http')) {
          apiPath = new URL(urlStr).pathname;
        } else {
          apiPath = urlStr.split('?')[0];
        }
      } catch (e) {}

      if (apiPath === '/api/status' || apiPath === '/api/status/') {
        return makeJsonResponse({ status: 'ok', service: 'finland-cloud-vault', mode: 'github-cloud' }, 200);
      }

      if (apiPath === '/api/auth/local-token' || apiPath === '/api/auth/local-token/') {
        const tk = extractCloudVaultKeyFromUrl();
        if (tk) return makeJsonResponse({ status: 'ok', token: tk }, 200);
        return makeJsonResponse({ status: 'error', message: 'Cloud key required' }, 403);
      }

      if (apiPath === '/api/auth/verify' || apiPath === '/api/auth/verify/') {
        try {
          const bodyObj = init && init.body ? JSON.parse(init.body) : {};
          const rawCandidate = String(bodyObj.pin || bodyObj.token || '').trim();
          const candidate = parseCandidateCloudKey(rawCandidate);
          if (candidate) {
            localStorage.setItem('vault_cloud_gh_token', candidate);
            localStorage.setItem('vault_auth_token', candidate);
            localStorage.removeItem('finland_local_unpushed_dirty');
            const testRes = await readGhJsonFile('vault_data.json');
            if (testRes.status === 200) {
              return makeJsonResponse({ status: 'ok', token: candidate }, 200);
            }
            localStorage.removeItem('vault_cloud_gh_token');
            localStorage.removeItem('vault_auth_token');
          }
        } catch (e) {}
        return makeJsonResponse({ status: 'error', message: 'Invalid Cloud Vault Key or Pairing Link. Copy your Pairing Link or Cloud Key from Settings → Data & Vault on an unlocked Mac.' }, 401);
      }

      if (apiPath === '/api/vault' || apiPath === '/api/vault/') {
        if (method === 'GET') {
          const current = await readGhJsonFile('vault_data.json');
          if (current.status === 401) return makeJsonResponse({ status: 'error', message: 'Unauthorized' }, 401);
          if (current.status !== 200 || !current.data) return makeJsonResponse({}, current.status === 404 ? 200 : current.status);
          return makeJsonResponse(current.data, 200);
        }
        if (method === 'POST') {
          const incoming = init && init.body ? JSON.parse(init.body) : {};
          const current = await readGhJsonFile('vault_data.json');
          if (current.status === 401) return makeJsonResponse({ status: 'error', message: 'Unauthorized' }, 401);
          const existing = current.data || {};
          const scrutiny = scrutinizeAndMergeVaultPayload(existing, incoming);
          if (scrutiny.rejected) {
            return makeJsonResponse(scrutiny.response, 200);
          }
          const putRes = await writeGhJsonFile(
            'vault_data.json',
            scrutiny.merged,
            current.sha,
            'backup(cloud-web): scrutinized vault sync [' + scrutiny.merged._last_synced + ']'
          );
          if (!putRes.ok) {
            return makeJsonResponse({ status: 'error', message: 'Cloud write conflict, retrying on next sync' }, putRes.status);
          }
          return makeJsonResponse({ status: 'ok', saved_at: scrutiny.merged._last_synced }, 200);
        }
      }

      if (apiPath === '/api/attachments-list' || apiPath === '/api/attachments-list/') {
        const res = await ghApiFetch('attachments', { method: 'GET' });
        if (!res.ok) return makeJsonResponse({ ids: [] }, 200);
        const list = await res.json();
        const ids = Array.isArray(list)
          ? list.filter(item => item && item.name && item.name.endsWith('.json')).map(item => item.name.slice(0, -5))
          : [];
        return makeJsonResponse({ ids }, 200);
      }

      if (apiPath.startsWith('/api/attachments/')) {
        const tail = apiPath.slice('/api/attachments/'.length).replace(/\/+$/, '');
        const isRaw = tail.endsWith('/raw');
        const rawId = decodeURIComponent(isRaw ? tail.slice(0, -4) : tail);
        const safeId = rawId.replace(/[^a-zA-Z0-9_\-\.]/g, '_');
        const repoFile = 'attachments/' + safeId + '.json';

        if (method === 'GET') {
          const attRes = await readGhJsonFile(repoFile);
          if (attRes.status !== 200 || !attRes.data) {
            return makeJsonResponse({ status: 'not_found' }, 404);
          }
          if (isRaw && attRes.data.data) {
            const r = await nativeFetch(attRes.data.data);
            const blob = await r.blob();
            return new Response(blob, {
              status: 200,
              headers: { 'Content-Type': attRes.data.mimeType || blob.type || 'application/octet-stream' }
            });
          }
          return makeJsonResponse(attRes.data, 200);
        }

        if (method === 'POST') {
          const payload = init && init.body ? JSON.parse(init.body) : {};
          const existingAtt = await readGhJsonFile(repoFile);
          const putRes = await writeGhJsonFile(
            repoFile,
            payload,
            existingAtt.sha,
            'backup(attachment): ' + safeId
          );
          return makeJsonResponse({ status: putRes.ok ? 'ok' : 'error' }, putRes.ok ? 200 : putRes.status);
        }

        if (method === 'DELETE') {
          const existingAtt = await readGhJsonFile(repoFile);
          if (existingAtt.status === 404 || !existingAtt.sha) {
            return makeJsonResponse({ status: 'ok' }, 200);
          }
          const delRes = await ghApiFetch(repoFile, {
            method: 'DELETE',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              message: 'delete(attachment): ' + safeId,
              sha: existingAtt.sha
            })
          });
          return makeJsonResponse({ status: delRes.ok ? 'ok' : 'error' }, delRes.ok ? 200 : delRes.status);
        }
      }

      return nativeFetch(input, init);
    };
  })();

  function getVaultEndpoint(path = '/api/vault') {
    if (window.location && window.location.protocol && window.location.protocol.startsWith('http')) {
      return path;
    }
    return 'http://localhost:8000' + path;
  }

  function getAttachmentEndpoint(id) {
    if (window.location && window.location.protocol && window.location.protocol.startsWith('http')) {
      return '/api/attachments/' + encodeURIComponent(id);
    }
    return 'http://localhost:8000/api/attachments/' + encodeURIComponent(id);
  }

  function getVaultAuthToken() {
    try {
      extractCloudVaultKeyFromUrl();
      const urlParams = new URLSearchParams(window.location.search);
      const urlToken = urlParams.get('token');
      if (urlToken) {
        localStorage.setItem('vault_auth_token', urlToken);
        const cleanUrl = window.location.pathname + window.location.hash;
        window.history.replaceState({}, document.title, cleanUrl);
        return urlToken;
      }
    } catch (e) {}
    return localStorage.getItem('vault_auth_token') || localStorage.getItem('vault_cloud_gh_token') || '';
  }

  function getAuthHeaders(extra = {}) {
    const headers = { 'Content-Type': 'application/json', ...extra };
    const token = getVaultAuthToken();
    if (token) {
      headers['X-Vault-Token'] = token;
    }
    return headers;
  }

  function confirmAction(optionsOrMessage, extraOptions = {}) {
    return new Promise((resolve) => {
      const modal = document.getElementById('globalConfirmModal');
      if (!modal) {
        const msg = typeof optionsOrMessage === 'string' ? optionsOrMessage : (optionsOrMessage?.message || optionsOrMessage?.title || 'Are you sure?');
        resolve(window.confirm(msg));
        return;
      }

      let title = 'Are you sure?';
      let message = 'Please confirm if you want to proceed.';
      let confirmText = 'Confirm';
      let cancelText = 'Cancel';
      let type = 'danger'; // 'danger' | 'warning' | 'primary'

      if (typeof optionsOrMessage === 'string') {
        const str = optionsOrMessage.trim();
        title = str;
        if (/delete|remove|clear/i.test(str)) {
          type = 'danger';
          confirmText = /remove/i.test(str) ? 'Remove' : 'Delete';
          message = 'This action cannot be undone.';
        } else if (/convert/i.test(str)) {
          type = 'warning';
          confirmText = 'Convert';
          message = 'You can convert it back anytime.';
        } else {
          type = 'primary';
          confirmText = 'Confirm';
          message = 'Please confirm if you want to proceed.';
        }
      } else if (typeof optionsOrMessage === 'object' && optionsOrMessage !== null) {
        title = optionsOrMessage.title || title;
        message = optionsOrMessage.message || message;
        confirmText = optionsOrMessage.confirmText || confirmText;
        cancelText = optionsOrMessage.cancelText || cancelText;
        type = optionsOrMessage.type || type;
      }

      if (extraOptions) {
        if (extraOptions.title) title = extraOptions.title;
        if (extraOptions.message) message = extraOptions.message;
        if (extraOptions.confirmText) confirmText = extraOptions.confirmText;
        if (extraOptions.cancelText) cancelText = extraOptions.cancelText;
        if (extraOptions.type) type = extraOptions.type;
      }

      // Configure elements
      const iconBox = document.getElementById('globalConfirmIconBox');
      const titleEl = document.getElementById('globalConfirmTitle');
      const messageEl = document.getElementById('globalConfirmMessage');
      const okBtn = document.getElementById('globalConfirmOkBtn');
      const cancelBtn = document.getElementById('globalConfirmCancelBtn');

      if (titleEl) titleEl.textContent = title;
      if (messageEl) messageEl.textContent = message;

      if (iconBox) {
        if (type === 'danger') {
          iconBox.className = 'w-10 h-10 rounded-2xl bg-rose-50 text-rose-600 border border-rose-200/70 flex items-center justify-center shrink-0';
          iconBox.innerHTML = '<i data-lucide="trash-2" class="w-5 h-5"></i>';
        } else if (type === 'warning') {
          iconBox.className = 'w-10 h-10 rounded-2xl bg-amber-50 text-amber-600 border border-amber-200/70 flex items-center justify-center shrink-0';
          iconBox.innerHTML = '<i data-lucide="arrow-left-right" class="w-5 h-5"></i>';
        } else {
          iconBox.className = 'w-10 h-10 rounded-2xl bg-indigo-50 text-indigo-600 border border-indigo-200/70 flex items-center justify-center shrink-0';
          iconBox.innerHTML = '<i data-lucide="help-circle" class="w-5 h-5"></i>';
        }
      }

      if (okBtn) {
        okBtn.textContent = confirmText;
        if (type === 'danger') {
          okBtn.className = 'flex-1 py-2 px-3 bg-rose-600 hover:bg-rose-500 active:scale-95 text-white font-bold text-xs rounded-xl transition-all cursor-pointer shadow-xs shadow-rose-600/20';
        } else if (type === 'warning') {
          okBtn.className = 'flex-1 py-2 px-3 bg-amber-600 hover:bg-amber-500 active:scale-95 text-white font-bold text-xs rounded-xl transition-all cursor-pointer shadow-xs shadow-amber-600/20';
        } else {
          okBtn.className = 'flex-1 py-2 px-3 bg-indigo-600 hover:bg-indigo-500 active:scale-95 text-white font-bold text-xs rounded-xl transition-all cursor-pointer shadow-xs shadow-indigo-600/20';
        }
      }

      if (cancelBtn) cancelBtn.textContent = cancelText;

      if (window.lucide && typeof window.lucide.createIcons === 'function') {
        window.lucide.createIcons();
      }

      let isSettled = false;
      const cleanup = (result) => {
        if (isSettled) return;
        isSettled = true;
        modal.classList.add('hidden');
        modal.classList.remove('flex');
        modal.removeEventListener('click', handleBackdrop);
        window.removeEventListener('keydown', handleKey, true);
        if (okBtn) okBtn.onclick = null;
        if (cancelBtn) cancelBtn.onclick = null;
        resolve(result);
      };

      const handleBackdrop = (e) => {
        if (e.target === modal || !e.target.closest('#globalConfirmModal .modal-card')) {
          cleanup(false);
        }
      };

      const handleKey = (e) => {
        if (e.key === 'Escape') {
          e.preventDefault();
          e.stopPropagation();
          cleanup(false);
        } else if (e.key === 'Enter') {
          e.preventDefault();
          e.stopPropagation();
          cleanup(true);
        }
      };

      if (okBtn) okBtn.onclick = (e) => { e.preventDefault(); cleanup(true); };
      if (cancelBtn) cancelBtn.onclick = (e) => { e.preventDefault(); cleanup(false); };
      modal.addEventListener('click', handleBackdrop);
      window.addEventListener('keydown', handleKey, true);

      modal.classList.remove('hidden');
      modal.classList.add('flex');
      if (cancelBtn) cancelBtn.focus();
    });
  }


  function showVaultAuthModal(forceShow = false) {
    if (isDemoMode()) {
      hideVaultAuthModal();
      return;
    }
    if (!forceShow && !isCloudVaultHost()) {
      hideVaultAuthModal();
      return;
    }
    const modal = document.getElementById('vaultAuthModal');
    if (modal) {
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }
    const input = document.getElementById('vaultAuthPinInput');
    if (input) {
      setTimeout(() => {
        try { input.focus(); } catch (e) {}
      }, 60);
    }
    if (window.lucide) {
      try { window.lucide.createIcons(); } catch (e) {}
    }
  }

  function hideVaultAuthModal() {
    const modal = document.getElementById('vaultAuthModal');
    if (modal) {
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }
    const err = document.getElementById('vaultAuthErrorMsg');
    if (err) err.classList.add('hidden');
  }

  function lockCurrentBrowserSession() {
    try {
      localStorage.removeItem('vault_cloud_gh_token');
      localStorage.removeItem('vault_auth_token');
      localStorage.removeItem('finland_local_unpushed_dirty');
      Object.values(STORAGE_KEYS).forEach(k => {
        if (typeof k === 'string' && k.startsWith('finland_')) {
          localStorage.removeItem(k);
        }
      });
    } catch (e) {}
    state.expenses = [];
    state.subscriptions = [];
    state.debts = [];
    state.wishlist = [];
    state.notes = [];
    state.documents = [];
    if (state.budget) {
      state.budget.projects = [];
      state.budget.leads = [];
      state.budget.miscIncome = [];
    }
    try {
      closeForwardingModal();
      renderDashboard();
      renderSidebarSubscriptionCalendar();
    } catch (e) {}
    showVaultAuthModal(true);
  }

  async function tryAutoLocalAuth() {
    try {
      const res = await fetch(getVaultEndpoint('/api/auth/local-token'));
      if (res.ok) {
        const data = await res.json();
        if (data && data.token) {
          localStorage.setItem('vault_auth_token', data.token);
          if (data.cloud_key) {
            localStorage.setItem('vault_cloud_gh_token', data.cloud_key);
          }
          return true;
        }
      }
    } catch (e) {}
    return false;
  }

  function isValidAttachmentPayload(att) {
    if (!att || typeof att.data !== 'string') return false;
    const trimmed = att.data.trim();
    if (trimmed.length < 24) return false;
    if (trimmed.startsWith('data:')) {
      const commaIdx = trimmed.indexOf(',');
      if (commaIdx === -1 || trimmed.slice(commaIdx + 1).trim().length < 8) return false;
    }
    return true;
  }

  async function postAttachmentToServer(expenseId, fileData) {
    if (!isValidAttachmentPayload(fileData)) return false;
    const payloadStr = JSON.stringify({
      id: expenseId,
      type: fileData.type,
      mimeType: fileData.mimeType,
      fileName: fileData.fileName || 'receipt',
      data: fileData.data
    });
    try {
      let res = await fetch(getAttachmentEndpoint(expenseId), {
        method: 'POST',
        headers: getAuthHeaders(),
        body: payloadStr
      });
      if (res.status === 401) {
        const authed = await tryAutoLocalAuth();
        if (authed) {
          res = await fetch(getAttachmentEndpoint(expenseId), {
            method: 'POST',
            headers: getAuthHeaders(),
            body: payloadStr
          });
        }
      }
      return !!(res && res.ok);
    } catch (e) {
      return false;
    }
  }

  async function saveReceiptAttachment(expenseId, fileData) {
    if (!isValidAttachmentPayload(fileData)) {
      console.warn('Rejected invalid or empty attachment payload for:', expenseId);
      return false;
    }
    let savedLocal = false;
    try {
      const db = await openReceiptDB();
      await new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        store.put({
          expenseId: expenseId,
          type: fileData.type, // 'image', 'pdf', 'eml', 'text'
          mimeType: fileData.mimeType,
          fileName: fileData.fileName || 'receipt',
          data: fileData.data, // base64 or text
          savedAt: new Date().toISOString()
        });
        tx.oncomplete = () => resolve(true);
        tx.onerror = () => reject(tx.error);
      });
      savedLocal = true;
    } catch (e) {
      console.warn('Could not save receipt to IndexedDB:', e);
    }

    // Persist attachment durably to local vault server & mirror folders
    const savedServer = await postAttachmentToServer(expenseId, fileData);

    return savedLocal || savedServer;
  }

  async function getReceiptAttachment(expenseId) {
    // 1. Try local IndexedDB first
    try {
      const db = await openReceiptDB();
      const local = await new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const req = store.get(expenseId);
        req.onsuccess = () => resolve(req.result || null);
        req.onerror = () => reject(req.error);
      });
      if (isValidAttachmentPayload(local)) return local;
    } catch (e) {
      console.warn('Could not get receipt from IndexedDB:', e);
    }

    // 2. Fetch from sync server if missing or invalid in local browser
    try {
      let res = await fetch(getAttachmentEndpoint(expenseId), {
        headers: getAuthHeaders()
      });
      if (res.status === 401) {
        const authed = await tryAutoLocalAuth();
        if (authed) {
          res = await fetch(getAttachmentEndpoint(expenseId), {
            headers: getAuthHeaders()
          });
        }
      }
      if (res && res.ok) {
        const remote = await res.json();
        if (isValidAttachmentPayload(remote)) {
          // Cache in local IndexedDB
          try {
            const db = await openReceiptDB();
            const tx = db.transaction(STORE_NAME, 'readwrite');
            tx.objectStore(STORE_NAME).put({
              expenseId: expenseId,
              type: remote.type,
              mimeType: remote.mimeType,
              fileName: remote.fileName || 'receipt',
              data: remote.data,
              savedAt: new Date().toISOString()
            });
          } catch (e) {}
          return remote;
        }
      }
    } catch (e) {}

    return null;
  }

  async function deleteReceiptAttachment(expenseId) {
    try {
      const db = await openReceiptDB();
      await new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        store.delete(expenseId);
        tx.oncomplete = () => resolve(true);
        tx.onerror = () => reject(tx.error);
      });
    } catch (e) {
      console.warn('Could not delete receipt from IndexedDB:', e);
    }

    try {
      fetch(getAttachmentEndpoint(expenseId), {
        method: 'DELETE',
        headers: getAuthHeaders()
      }).catch(() => {});
    } catch (e) {}
  }

  // Multi-document Tax Receipt & Invoice Repository for Subscriptions & Monthly Bills
  async function saveSubReceiptAttachment(receiptDoc) {
    try {
      const db = await openReceiptDB();
      await new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        store.put(receiptDoc);
        tx.oncomplete = () => resolve(true);
        tx.onerror = () => reject(tx.error);
      });
    } catch (e) {
      console.warn('Could not save sub receipt to IndexedDB:', e);
    }

    // Broadcast attachment to sync server with auth
    if (receiptDoc && receiptDoc.expenseId) {
      try {
        fetch(getAttachmentEndpoint(receiptDoc.expenseId), {
          method: 'POST',
          headers: getAuthHeaders(),
          body: JSON.stringify({
            id: receiptDoc.expenseId,
            expenseId: receiptDoc.expenseId,
            subId: receiptDoc.subId || null,
            monthKey: receiptDoc.monthKey || null,
            savedAt: receiptDoc.savedAt || Date.now(),
            type: receiptDoc.type,
            mimeType: receiptDoc.mimeType,
            fileName: receiptDoc.fileName || 'receipt',
            data: receiptDoc.data
          })
        }).catch(() => {});
      } catch (e) {}
    }

    return true;
  }

  async function getSubReceiptAttachments(subId) {
    let localItems = [];
    try {
      const db = await openReceiptDB();
      localItems = await new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const req = store.getAll();
        req.onsuccess = () => {
          const all = req.result || [];
          resolve(all.filter(r => r.subId === subId));
        };
        req.onerror = () => reject(req.error);
      });
    } catch (e) {
      console.warn('Could not query sub receipts from IndexedDB:', e);
    }

    // Fall back to server for any taxReceipts metadata not yet cached in local IndexedDB (e.g. secondary device)
    try {
      const sub = (state.subscriptions || []).find(s => s.id === subId);
      const metaList = (sub && Array.isArray(sub.taxReceipts)) ? sub.taxReceipts : [];
      const localIds = new Set(localItems.map(r => r.expenseId || r.id));
      for (const tr of metaList) {
        if (!tr || !tr.id || localIds.has(tr.id)) continue;
        const remote = await getReceiptAttachment(tr.id);
        if (remote && remote.data) {
          const hydrated = {
            ...remote,
            expenseId: tr.id,
            subId: subId,
            monthKey: remote.monthKey || tr.monthKey || '',
            fileName: remote.fileName || tr.fileName || 'receipt',
            type: remote.type || tr.type || 'pdf',
            savedAt: remote.savedAt || tr.savedAt || Date.now()
          };
          localItems.push(hydrated);
          localIds.add(tr.id);
          try {
            const db = await openReceiptDB();
            const tx = db.transaction(STORE_NAME, 'readwrite');
            tx.objectStore(STORE_NAME).put(hydrated);
          } catch (e) {}
        }
      }
    } catch (e) {}

    return localItems;
  }

  async function deleteSubReceiptAttachment(receiptId) {
    try {
      const db = await openReceiptDB();
      await new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        store.delete(receiptId);
        tx.oncomplete = () => resolve(true);
        tx.onerror = () => reject(tx.error);
      });
    } catch (e) {
      console.warn('Could not delete sub receipt from IndexedDB:', e);
    }

    try {
      fetch(getAttachmentEndpoint(receiptId), {
        method: 'DELETE',
        headers: getAuthHeaders()
      }).catch(() => {});
    } catch (e) {}

    return true;
  }

  // ==========================================
  // 3. STATE MANAGEMENT
  // ==========================================
