  function addOrUpdateExpense(expenseData) {
    if (expenseData.id) {
      const idx = state.expenses.findIndex(e => e.id === expenseData.id);
      if (idx !== -1) {
        // Deep merge: protect attachment metadata from being wiped on edit!
        const existing = state.expenses[idx];
        state.expenses[idx] = {
          ...existing,
          ...expenseData,
          hasAttachment: expenseData.hasAttachment !== undefined ? expenseData.hasAttachment : (existing.hasAttachment || false),
          attachmentType: expenseData.attachmentType !== undefined ? expenseData.attachmentType : (existing.attachmentType || null),
          attachmentFileName: expenseData.attachmentFileName !== undefined ? expenseData.attachmentFileName : (existing.attachmentFileName || ''),
          noReceiptNeeded: expenseData.isBusiness ? false : (expenseData.noReceiptNeeded !== undefined ? expenseData.noReceiptNeeded : (existing.noReceiptNeeded || false))
        };
      } else {
        state.expenses.unshift(expenseData);
      }
    } else {
      expenseData.id = 'exp_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4);
      if (expenseData.isBusiness) expenseData.noReceiptNeeded = false;
      state.expenses.unshift(expenseData);
    }
    saveExpenses();

    if (expenseData.isSubscription || expenseData.category === 'Subscriptions') {
      registerOrUpdateSubscription(expenseData);
    }

    populateMonthFilterOptions();
    renderDashboard();
    updateNeedsToPayBadge();
  }

  async function deleteExpense(id) {
    const item = state.expenses.find(e => e.id === id);
    if (!item) return;

    if (await confirmAction(`Are you sure you want to delete "${item.title}" and its attached receipt?`)) {
      if (item.wise_id) {
        try {
          const rawIgnored = localStorage.getItem('finland_wise_deleted_ids_v1') || '[]';
          const ignoredList = JSON.parse(rawIgnored);
          if (!ignoredList.includes(item.wise_id)) {
            ignoredList.push(item.wise_id);
            localStorage.setItem('finland_wise_deleted_ids_v1', JSON.stringify(ignoredList));
          }
        } catch (e) {}
      }
      state.expenses = state.expenses.filter(e => e.id !== id);
      await deleteReceiptAttachment(id);

      // Two-Way Sync: If this was a subscription expense, update the subscription's paid status for that month if no other payment remains in that month (never delete the recurring commitment itself)
      if (item.isSubscription || item.category === 'Subscriptions' || item.category === 'Monthly Expenses' || item.subscriptionId || item.generatedFromSubId) {
        const expMonth = item.date ? item.date.slice(0, 7) : null;
        const normItemTitle = normalizeServiceName(item.title);
        const sub = (state.subscriptions || []).find(s =>
          s.id === item.subscriptionId ||
          s.id === item.generatedFromSubId ||
          (normItemTitle && normalizeServiceName(s.name) === normItemTitle)
        );
        if (sub && expMonth) {
          const remainingInMonth = (state.expenses || []).some(e => {
            if (!e.date || !e.date.startsWith(expMonth)) return false;
            if (e.subscriptionId === sub.id || e.generatedFromSubId === sub.id) return true;
            const normExp = normalizeServiceName(e.title || '');
            return normItemTitle && normExp === normItemTitle;
          });
          if (!remainingInMonth && sub.manualPaidMonths && sub.manualPaidMonths[expMonth] === true) {
            sub.manualPaidMonths[expMonth] = false;
            saveSubscriptions();
          }
        }
      }

      saveExpenses();
      populateMonthFilterOptions();
      renderDashboard();
      if (state.currentTab === 'subscriptions') renderSubscriptionsView();
      updateNeedsToPayBadge();
    }
  }

  function updateExpenseCategory(id, newCategory) {
    const item = state.expenses.find(e => e.id === id);
    if (!item) return;
    const oldCat = item.category;
    item.category = newCategory;
    if (newCategory === 'Subscriptions' || newCategory === 'Monthly Expenses') {
      item.isSubscription = true;
      registerOrUpdateSubscription(item);
    } else if ((oldCat === 'Subscriptions' || oldCat === 'Monthly Expenses') && newCategory !== 'Subscriptions' && newCategory !== 'Monthly Expenses') {
      item.isSubscription = false;
      const expMonth = item.date ? item.date.slice(0, 7) : null;
      const normItemTitle = normalizeServiceName(item.title);
      const sub = (state.subscriptions || []).find(s =>
        s.id === item.subscriptionId ||
        s.id === item.generatedFromSubId ||
        (normItemTitle && normalizeServiceName(s.name) === normItemTitle)
      );
      if (sub && expMonth) {
        const remainingInMonth = (state.expenses || []).some(e => {
          if (e.id === id || !e.date || !e.date.startsWith(expMonth)) return false;
          if (!e.isSubscription && e.category !== 'Subscriptions' && e.category !== 'Monthly Expenses') return false;
          if (e.subscriptionId === sub.id || e.generatedFromSubId === sub.id) return true;
          const normExp = normalizeServiceName(e.title || '');
          return normItemTitle && normExp === normItemTitle;
        });
        if (!remainingInMonth && sub.manualPaidMonths && sub.manualPaidMonths[expMonth] === true) {
          sub.manualPaidMonths[expMonth] = false;
          saveSubscriptions();
        }
      }
    }
    saveExpenses();
    renderDashboard();
    if (state.currentTab === 'subscriptions') renderSubscriptionsView();
    showToast('Category Updated', `${item.title} moved from ${oldCat} to ${newCategory}`, 'success');
  }

  function toggleExpenseBusinessTag(id) {
    const item = state.expenses.find(e => e.id === id);
    if (!item) return;
    item.isBusiness = !item.isBusiness;
    saveExpenses();
    renderDashboard();
    const statusMsg = item.isBusiness ? 'Tagged as Business Expense 💼' : 'Removed from Business Expenses';
    showToast('Business Tag', `${item.title}: ${statusMsg}`, 'success');
  }

