    document.getElementById('partialDebtPaidText').textContent = formatMoney(paidAmt, debtCur);
    document.getElementById('partialDebtRemainingText').textContent = formatMoney(remainingAmt, debtCur);
    document.getElementById('partialPayCurrencyBadge').textContent = debtCur;

    const amtInput = document.getElementById('partialPayAmount');
