  // Tax Invoices & Receipts Vault for Subscriptions
  function formatMonthLabel(key) {
    if (!key || key === 'ALL' || key === 'all') return 'All Months';
    const parts = key.split('-');
    if (parts.length < 2) return key;
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10);
    if (isNaN(y) || isNaN(m)) return key;
    return new Date(y, m - 1, 1).toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  }

  function formatMonthShort(key) {
    if (!key || key === 'ALL' || key === 'all') return 'All';
    const parts = key.split('-');
    if (parts.length < 2) return key;
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10);
    if (isNaN(y) || isNaN(m)) return key;
    return new Date(y, m - 1, 1).toLocaleDateString('en-US', { month: 'short' });
  }

  function getSubReceiptMonthKey(doc) {
    if (doc && doc.monthKey) return doc.monthKey;
    const name = ((doc && doc.fileName) || '').toLowerCase();
    const months = [
      { key: '-01', matches: ['jan', 'january'] },
      { key: '-02', matches: ['feb', 'february'] },
      { key: '-03', matches: ['mar', 'march'] },
      { key: '-04', matches: ['apr', 'april'] },
      { key: '-05', matches: ['may'] },
      { key: '-06', matches: ['jun', 'june'] },
      { key: '-07', matches: ['jul', 'july'] },
      { key: '-08', matches: ['aug', 'august'] },
      { key: '-09', matches: ['sep', 'sept', 'september'] },
      { key: '-10', matches: ['oct', 'october'] },
      { key: '-11', matches: ['nov', 'november'] },
      { key: '-12', matches: ['dec', 'december'] }
    ];
    const yearMatch = name.match(/20\d\d/);
    const yr = yearMatch ? yearMatch[0] : (doc && doc.savedAt ? doc.savedAt.slice(0, 4) : '2026');
    for (const m of months) {
      if (m.matches.some(term => name.includes(term))) {
        return `${yr}${m.key}`;
      }
    }
    if (doc && doc.savedAt) return doc.savedAt.slice(0, 7);
    return state.selectedMonth && state.selectedMonth !== 'ALL' ? state.selectedMonth : new Date().toISOString().slice(0, 7);
  }

  function setupSubReceiptModalMonthSelect(subId, currentMonth) {
    const select = document.getElementById('subReceiptModalMonthSelect');
    if (!select) return;

    const options = [];
    const now = new Date();
    const curYear = now.getFullYear();
    const curMonth = now.getMonth();

    for (let i = -12; i <= 2; i++) {
      const d = new Date(curYear, curMonth + i, 1);
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      const label = d.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
      options.push({ key, label });
    }

    options.reverse();

    select.innerHTML = `
      <option value="ALL">All Months (Complete Archive)</option>
      ${options.map(o => `<option value="${o.key}" ${o.key === currentMonth ? 'selected' : ''}>${o.label}</option>`).join('')}
    `;

    select.value = currentMonth || 'ALL';

    select.onchange = (e) => {
      state.activeSubReceiptsMonth = e.target.value;
      updateSubReceiptUploadPrompt();
      renderSubReceiptsList(subId);
    };

    updateSubReceiptUploadPrompt();
  }

  function updateSubReceiptUploadPrompt() {
    const promptEl = document.getElementById('subReceiptUploadPrompt');
    if (!promptEl) return;
    const m = state.activeSubReceiptsMonth;
    if (!m || m === 'ALL') {
      promptEl.textContent = 'Upload Invoice to Repository';
    } else {
      promptEl.textContent = `Upload Invoice for ${formatMonthLabel(m)}`;
    }
  }

  async function openSubReceiptsModal(subId, requestedMonthKey = null) {
    state.activeSubReceiptsId = subId;
    const sub = state.subscriptions.find(s => s.id === subId);
    if (!sub) return;

    const targetMonth = requestedMonthKey || (state.selectedMonth && state.selectedMonth !== 'ALL' ? state.selectedMonth : new Date().toISOString().slice(0, 7));
    state.activeSubReceiptsMonth = targetMonth;

    const modal = document.getElementById('subReceiptsModal');
    const titleEl = document.getElementById('subReceiptsModalTitle');
    const subtitleEl = document.getElementById('subReceiptsModalSubtitle');

    if (titleEl) titleEl.textContent = `${sub.name} — Tax Invoices & Receipts`;
    if (subtitleEl) subtitleEl.textContent = `${formatMoney(sub.amount, sub.currency)} / ${sub.billingCycle || 'mo'} • All files saved offline for tax deduction`;

    setupSubReceiptModalMonthSelect(subId, targetMonth);

    await renderSubReceiptsList(subId);

    if (modal) {
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }
    lucide.createIcons();
  }

