  async function renderSubReceiptsList(subId) {
    const container = document.getElementById('subReceiptsListContainer');
    const summaryEl = document.getElementById('subReceiptsCountSummary');
    if (!container) return;

    const sub = state.subscriptions.find(s => s.id === subId);
    if (!sub) return;

    const docs = await getSubReceiptAttachments(subId);
    if (docs && docs.length > 0) {
      const existingMap = new Map((sub.taxReceipts || []).map(r => [r.id || r.expenseId, r]));
      docs.forEach(d => {
        const id = d.expenseId || d.id;
        existingMap.set(id, {
          id: id,
          fileName: d.fileName,
          savedAt: d.savedAt,
          type: d.type,
          monthKey: d.monthKey || getSubReceiptMonthKey(d)
        });
      });
      sub.taxReceipts = Array.from(existingMap.values());
      saveSubscriptions();
    }

    const activeMonth = state.activeSubReceiptsMonth || (state.selectedMonth && state.selectedMonth !== 'ALL' ? state.selectedMonth : new Date().toISOString().slice(0, 7));
    const isAllTime = activeMonth === 'ALL';

    const filteredDocs = isAllTime
      ? docs
      : docs.filter(d => (d.monthKey || getSubReceiptMonthKey(d)) === activeMonth);

    if (summaryEl) {
      if (isAllTime) {
        summaryEl.textContent = `${docs.length} total invoice${docs.length === 1 ? '' : 's'} stored across all months`;
      } else {
        const monthLabel = formatMonthLabel(activeMonth);
        summaryEl.textContent = `${filteredDocs.length} invoice${filteredDocs.length === 1 ? '' : 's'} for ${monthLabel} (${docs.length} total in archive)`;
      }
    }

    if (filteredDocs.length === 0) {
      const monthLabel = formatMonthLabel(activeMonth);
      container.innerHTML = `
        <div class="py-8 text-center text-slate-400 bg-slate-50/70 rounded-2xl border border-dashed border-slate-200">
          <i data-lucide="receipt" class="w-8 h-8 mx-auto text-slate-400 mb-2"></i>
          <p class="text-xs font-semibold text-slate-700">No invoice attached for ${monthLabel}</p>
          <p class="text-[11px] text-slate-400 mt-0.5">Drop an invoice below to link it to ${monthLabel}.</p>
          ${docs.length > 0 ? `
            <div class="mt-3 pt-3 border-t border-slate-200/60 text-xs">
              <span class="text-slate-500 font-medium">You have ${docs.length} invoice(s) in other months.</span>
              <button type="button" class="text-emerald-700 hover:text-emerald-800 font-semibold underline ml-1 cursor-pointer" onclick="document.getElementById('subReceiptModalMonthSelect').value='ALL'; document.getElementById('subReceiptModalMonthSelect').dispatchEvent(new Event('change'));">View All Months</button>
            </div>
          ` : ''}
        </div>
      `;
      lucide.createIcons();
      return;
    }

    container.innerHTML = filteredDocs.map(doc => {
      const isImg = doc.type === 'image' || doc.type === 'image_url';
      const isPdf = doc.type === 'pdf';
      const icon = isImg ? 'image' : (isPdf ? 'file-text' : 'mail');
      const docMonth = doc.monthKey || getSubReceiptMonthKey(doc);
      const docMonthLabel = formatMonthLabel(docMonth);
      const dateStr = doc.savedAt ? new Date(doc.savedAt).toLocaleDateString() : 'Recent';

      return `
        <div class="flex items-center justify-between p-3 bg-white hover:bg-slate-50 border border-slate-200/90 rounded-2xl transition-all">
          <div class="flex items-center gap-3 min-w-0">
            <div class="w-9 h-9 rounded-xl ${isPdf ? 'bg-rose-50 text-rose-600' : (isImg ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600')} flex items-center justify-center shrink-0">
              <i data-lucide="${icon}" class="w-4 h-4"></i>
            </div>
            <div class="min-w-0">
              <div class="text-xs font-bold text-slate-900 truncate" title="${escapeHtml(doc.fileName)}">${escapeHtml(doc.fileName)}</div>
              <div class="text-[10px] text-slate-400 flex items-center gap-2 mt-0.5 flex-wrap">
                <span class="px-2 py-0.5 rounded-full font-bold bg-emerald-50 text-emerald-700 border border-emerald-200/60">${docMonthLabel}</span>
                <span class="uppercase font-semibold">${doc.type}</span>
                <span>• Saved ${dateStr}</span>
              </div>
            </div>
          </div>

          <div class="flex items-center gap-1 shrink-0">
            <button class="view-sub-doc-btn px-2.5 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-semibold flex items-center gap-1 cursor-pointer" data-id="${doc.expenseId}">
              <i data-lucide="eye" class="w-3.5 h-3.5"></i>
              <span>View</span>
            </button>
            <button class="del-sub-doc-btn p-1.5 hover:bg-rose-50 text-slate-400 hover:text-rose-600 rounded-lg transition-colors cursor-pointer" data-id="${doc.expenseId}" title="Delete tax receipt">
              <i data-lucide="trash-2" class="w-4 h-4"></i>
            </button>
          </div>
        </div>
      `;
    }).join('');

    container.querySelectorAll('.view-sub-doc-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const docId = btn.getAttribute('data-id');
        const target = docs.find(d => d.expenseId === docId);
        if (target) {
          openReceiptViewerDirect({
            type: target.type,
            data: target.data,
            fileName: target.fileName,
            title: `${sub.name} — Tax Invoice (${formatMonthLabel(target.monthKey || getSubReceiptMonthKey(target))})`
          });
        }
      });
    });

    container.querySelectorAll('.del-sub-doc-btn').forEach(btn => {
      btn.addEventListener('click', async () => {
        const docId = btn.getAttribute('data-id');
        if (await confirmAction('Delete this tax invoice/receipt from this subscription?')) {
          await deleteSubReceiptAttachment(docId);
          if (sub && Array.isArray(sub.taxReceipts)) {
            sub.taxReceipts = sub.taxReceipts.filter(r => (r.id || r.expenseId) !== docId);
            saveSubscriptions();
          }

          // Unlink or update any matching expense
          const linkedExp = (state.expenses || []).find(e => e.receiptId === docId);
          if (linkedExp) {
            const expMonth = (linkedExp.date || '').slice(0, 7);
            const remainingRec = (sub.taxReceipts || []).find(r => (r.monthKey || getSubReceiptMonthKey(r)) === expMonth && (r.id || r.expenseId) !== docId);
            if (remainingRec) {
              linkedExp.receiptId = remainingRec.id;
              linkedExp.attachmentFileName = remainingRec.fileName;
              linkedExp.attachmentType = remainingRec.type || 'pdf';
            } else {
              linkedExp.hasAttachment = false;
              delete linkedExp.receiptId;
              delete linkedExp.attachmentFileName;
              delete linkedExp.attachmentType;
            }
            saveExpenses();
            renderDashboard();
          }

          await renderSubReceiptsList(subId);
          showToast('Document Deleted', 'Tax invoice removed.', 'info');
        }
      });
    });

    lucide.createIcons();
  }
  function getReportPeriodExpenses() {
    const isAllTime = (!state.selectedMonth || state.selectedMonth === 'ALL' || state.selectedMonth === 'all');
    return (state.expenses || []).filter(e => {
      if (!e || e.isIncome || e.type === 'income' || e.category === 'Income') return false;
      if (isAllTime) return true;
      return (e.date || '').startsWith(state.selectedMonth);
    });
  }

  function getReportPeriodIncomes() {
    const isAllTime = (!state.selectedMonth || state.selectedMonth === 'ALL' || state.selectedMonth === 'all');
    const received = getAllReceivedPayments().filter(inc => {
      if (!inc) return false;
      if (isAllTime) return true;
      return (inc.date || '').startsWith(state.selectedMonth);
    });
    const seenIds = new Set(received.map(r => r.id));
    (state.expenses || []).forEach(e => {
      if (!e || !(e.isIncome || e.type === 'income' || e.category === 'Income')) return;
      if (!isAllTime && !(e.date || '').startsWith(state.selectedMonth)) return;
      if (!seenIds.has(e.id)) {
        seenIds.add(e.id);
        received.push(e);
      }
    });
    return received;
  }

  function getReportPendingReceivables(cur) {
    let pendingReceivables = 0;
    const projects = (state.budget && Array.isArray(state.budget.projects)) ? state.budget.projects : [];
    projects.forEach(p => {
      if (!p || p.status === 'paid' || p.status === 'cancelled') return;
      const totalFee = parseFloat(p.amount !== undefined ? p.amount : p.fee) || 0;
      let paidSoFar = p.paidAmount !== undefined ? (parseFloat(p.paidAmount) || 0) : 0;
      if (!p.paidAmount && Array.isArray(p.payments)) {
        paidSoFar = p.payments.reduce((acc, pay) => {
          const pCur = pay.currency || p.currency || 'EUR';
          const pAmt = parseFloat(pay.amount) || 0;
          const cAmt = pay.creditedAmount !== undefined ? parseFloat(pay.creditedAmount) : (pCur === (p.currency || 'EUR') ? pAmt : convertCurrency(pAmt, pCur, p.currency || 'EUR'));
          return acc + cAmt;
        }, 0);
      }
      const remaining = Math.max(0, totalFee - paidSoFar);
      pendingReceivables += convertCurrency(remaining, p.currency || cur, cur);
    });

    const incomes = (state.budget && Array.isArray(state.budget.incomes)) ? state.budget.incomes : [];
    incomes.forEach(inc => {
      if (!inc || !isMiscIncomeExpected(inc)) return;
      const amt = parseFloat(inc.amount) || 0;
      if (amt > 0) {
        pendingReceivables += convertCurrency(amt, inc.currency || cur, cur);
      }
    });
    return pendingReceivables;
  }

  function renderCharts() {
    renderReportCategoryBreakdown();
  }

  // ==========================================
  // REPORTS VIEW & FINANCIAL ANALYTICS ENGINE
  // ==========================================
  function renderReportsView() {
    if (typeof reconcileSubscriptionReceiptsWithExpenses === 'function') {
      try { reconcileSubscriptionReceiptsWithExpenses(); } catch (e) {}
    }
    renderReportsHeader();
    renderReportCategoryBreakdown();
    renderReportCashFlow();
    renderReportTaxDeductions();
    renderReportOverheadRunway();
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function renderReportsHeader() {
    const cur = state.displayCurrency || 'EUR';
    const otherCurs = ['EUR', 'USD', 'ILS'].filter(c => c !== cur);
    const isAllTime = (!state.selectedMonth || state.selectedMonth === 'ALL' || state.selectedMonth === 'all');
    const periodLabel = isAllTime ? 'All Time' : formatMonthLabel(state.selectedMonth);

    const periodBadgeEl = document.getElementById('reportsHeaderPeriodBadge');
    if (periodBadgeEl) periodBadgeEl.textContent = periodLabel;

    const subtitleEl = document.getElementById('reportsHeaderSubtitle');
    if (subtitleEl) {
      subtitleEl.textContent = 'Spending breakdown, tax receipts & accounting export';
    }

    const periodExpenses = getReportPeriodExpenses();
    const periodIncomes = getReportPeriodIncomes();

    let totalSpend = 0;
    let bizTotal = 0;
    let bizCount = 0;
    let bizMissingCount = 0;

    periodExpenses.forEach(e => {
      const amt = convertCurrency(parseFloat(e.amount) || 0, e.currency || cur, cur);
      totalSpend += amt;
      if (e.isBusiness) {
        bizTotal += amt;
        bizCount++;
        if (!e.hasAttachment) bizMissingCount++;
      }
    });

    let totalInflow = 0;
    periodIncomes.forEach(inc => {
      totalInflow += convertCurrency(parseFloat(inc.amount) || 0, inc.currency || cur, cur);
    });

    // Tile 1: Total Income
    const netAmtEl = document.getElementById('reportsHeaderNetAmount');
    if (netAmtEl) {
      netAmtEl.textContent = formatMoney(totalInflow, cur);
      netAmtEl.className = 'text-xl font-bold text-slate-900 mt-0.5 font-mono whitespace-nowrap';
    }
    const netBadgeEl = document.getElementById('reportsHeaderNetBadge');
    if (netBadgeEl) {
      netBadgeEl.className = 'text-[10px] text-slate-600 bg-slate-100 px-1.5 py-0.5 rounded font-medium whitespace-nowrap';
      netBadgeEl.textContent = `${periodIncomes.length} ${periodIncomes.length === 1 ? 'payment' : 'payments'}`;
    }
    const netEquivEl = document.getElementById('reportsHeaderNetEquiv');
    if (netEquivEl) {
      const eq1 = convertCurrency(totalInflow, cur, otherCurs[0]);
      const eq2 = convertCurrency(totalInflow, cur, otherCurs[1]);
      netEquivEl.textContent = `≈ ${formatMoney(eq1, otherCurs[0])} • ${formatMoney(eq2, otherCurs[1])}`;
    }

    // Tile 2: Total Expenses
    const spendAmtEl = document.getElementById('reportsHeaderSpendAmount');
    if (spendAmtEl) spendAmtEl.textContent = formatMoney(totalSpend, cur);
    const spendCountBadgeEl = document.getElementById('reportsHeaderSpendCountBadge');
    if (spendCountBadgeEl) {
      spendCountBadgeEl.textContent = `${periodExpenses.length} ${periodExpenses.length === 1 ? 'item' : 'items'}`;
    }
    const spendEquivEl = document.getElementById('reportsHeaderSpendEquiv');
    if (spendEquivEl) {
      const eq1 = convertCurrency(totalSpend, cur, otherCurs[0]);
      const eq2 = convertCurrency(totalSpend, cur, otherCurs[1]);
      spendEquivEl.textContent = `≈ ${formatMoney(eq1, otherCurs[0])} • ${formatMoney(eq2, otherCurs[1])}`;
    }

    // Tile 3: Tax Expenses
    const taxAmtEl = document.getElementById('reportsHeaderTaxAmount');
    if (taxAmtEl) taxAmtEl.textContent = formatMoney(bizTotal, cur);
    const taxBadgeEl = document.getElementById('reportsHeaderTaxBadge');
    if (taxBadgeEl) {
      if (bizCount === 0) {
        taxBadgeEl.className = 'text-[10px] text-slate-600 bg-slate-100 px-1.5 py-0.5 rounded font-medium whitespace-nowrap';
        taxBadgeEl.textContent = '0 receipts';
      } else if (bizMissingCount === 0) {
        taxBadgeEl.className = 'text-[10px] text-emerald-700 bg-emerald-50 px-1.5 py-0.5 rounded font-medium whitespace-nowrap';
        taxBadgeEl.textContent = `${bizCount} / ${bizCount} receipts`;
      } else {
        taxBadgeEl.className = 'text-[10px] text-amber-700 bg-amber-50 px-1.5 py-0.5 rounded font-medium whitespace-nowrap';
        taxBadgeEl.textContent = `${bizMissingCount} missing`;
      }
    }
    const taxEquivEl = document.getElementById('reportsHeaderTaxEquiv');
    if (taxEquivEl) {
      const eq1 = convertCurrency(bizTotal, cur, otherCurs[0]);
      const eq2 = convertCurrency(bizTotal, cur, otherCurs[1]);
      taxEquivEl.textContent = `≈ ${formatMoney(eq1, otherCurs[0])} • ${formatMoney(eq2, otherCurs[1])}`;
    }

    // Missing receipts badge on Accounting ZIP button (checks all business expenses that would be exported)
    const missingBtnBadge = document.getElementById('reportsHeaderMissingBadge');
    if (missingBtnBadge) {
      const allBizMissing = (state.expenses || []).filter(e => e && e.isBusiness && !e.isIncome && !e.hasAttachment).length;
      if (allBizMissing > 0) {
        missingBtnBadge.textContent = `${allBizMissing}`;
        missingBtnBadge.classList.remove('hidden');
      } else {
        missingBtnBadge.classList.add('hidden');
      }
    }
  }

  // 0. Report: Spending by Category (Decoupled from Transactions Tab Filters)
  function renderReportCategoryBreakdown() {
    const primaryCur = state.displayCurrency || 'EUR';
    const isAllTime = (!state.selectedMonth || state.selectedMonth === 'ALL' || state.selectedMonth === 'all');
    const periodLabel = isAllTime ? 'All Time' : formatMonthLabel(state.selectedMonth);
    const periodExpenses = getReportPeriodExpenses();

    const periodLblEl = document.getElementById('reportCategoryPeriodLabel');
    if (periodLblEl) periodLblEl.textContent = periodLabel;

    const categoryTotals = {};
    const categoryCounts = {};
    periodExpenses.forEach(item => {
      const cat = item.category || 'Other';
      const inPrimary = convertCurrency(parseFloat(item.amount) || 0, item.currency || primaryCur, primaryCur);
      categoryTotals[cat] = (categoryTotals[cat] || 0) + inPrimary;
      categoryCounts[cat] = (categoryCounts[cat] || 0) + 1;
    });

    const catLabels = Object.keys(categoryTotals);
    const catData = Object.values(categoryTotals);
    const totalSpend = catData.reduce((a, b) => a + b, 0);

    const footerSubEl = document.getElementById('reportCategoryFooterSub');
    if (footerSubEl) {
      footerSubEl.textContent = periodExpenses.length > 0
        ? `${periodExpenses.length} ${periodExpenses.length === 1 ? 'item' : 'items'} • ${formatMoney(totalSpend, primaryCur)}`
        : '0 items';
    }

    const noCatEl = document.getElementById('noCategoryData');
    const catCanvas = document.getElementById('categoryChart');
    const breakdownList = document.getElementById('reportsCategoryBreakdownList');

    if (state.categoryChartInstance) {
      state.categoryChartInstance.destroy();
      state.categoryChartInstance = null;
    }

    if (breakdownList) {
      if (catData.length === 0) {
        breakdownList.innerHTML = `<div class="p-6 text-center text-slate-400">No expenses for ${escapeHtml(periodLabel)}.</div>`;
      } else {
        const sortedCats = catLabels.map((cat, i) => ({
          name: cat,
          amount: catData[i],
          count: categoryCounts[cat] || 0,
          percentage: totalSpend > 0 ? ((catData[i] / totalSpend) * 100) : 0,
          color: getCategoryColor(cat)
        })).sort((a, b) => b.amount - a.amount);

        breakdownList.innerHTML = sortedCats.map(item => `
          <div class="px-4 py-2.5 flex items-center justify-between hover:bg-slate-50/60 transition-colors">
            <div class="flex items-center gap-2.5 min-w-0">
              <span class="w-2.5 h-2.5 rounded-full shrink-0" style="background-color: ${item.color};"></span>
              <span class="font-semibold text-slate-800 truncate">${escapeHtml(item.name)}</span>
              <span class="px-1.5 py-0.5 text-[10px] font-medium bg-slate-100 text-slate-500 rounded shrink-0">${item.count}</span>
            </div>
            <div class="flex items-center gap-6 font-mono shrink-0">
              <span class="font-bold text-slate-900 whitespace-nowrap">${formatMoney(item.amount, primaryCur)}</span>
              <span class="w-10 text-right text-slate-500 font-semibold whitespace-nowrap">${item.percentage.toFixed(0)}%</span>
            </div>
          </div>
        `).join('');
      }
    }

    if (catData.length === 0) {
      if (noCatEl) noCatEl.classList.remove('hidden');
      if (catCanvas) catCanvas.classList.add('hidden');
    } else {
      if (noCatEl) noCatEl.classList.add('hidden');
      if (catCanvas) catCanvas.classList.remove('hidden');

      const bgColors = catLabels.map(cat => getCategoryColor(cat));

      const centerTextPlugin = {
        id: 'centerTextPlugin',
        beforeDraw: function(chart) {
          const { width, height, ctx } = chart;
          ctx.save();
          const centerX = width / 2;
          const centerY = height / 2;

          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';

          ctx.font = '500 11px Plus Jakarta Sans, sans-serif';
          ctx.fillStyle = '#64748b';
          ctx.fillText('Total', centerX, centerY - 11);

          ctx.font = '700 16px JetBrains Mono, monospace';
          ctx.fillStyle = '#0f172a';
          ctx.fillText(formatMoney(totalSpend, primaryCur), centerX, centerY + 9);

          ctx.restore();
        }
      };

      if (typeof Chart !== 'undefined' && catCanvas) {
        state.categoryChartInstance = new Chart(catCanvas, {
          type: 'doughnut',
          data: {
            labels: catLabels,
            datasets: [{
              data: catData,
              backgroundColor: bgColors,
              borderColor: '#ffffff',
              borderWidth: 2,
              hoverOffset: 4
            }]
          },
          plugins: [centerTextPlugin],
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              legend: {
                display: false
              },
              tooltip: {
                callbacks: {
                  label: function (context) {
                    const val = context.parsed;
                    const pct = totalSpend > 0 ? Math.round((val / totalSpend) * 100) : 0;
                    return ` ${context.label}: ${formatMoney(val, primaryCur)} (${pct}%)`;
                  }
                }
              }
            },
            cutout: '74%'
          }
        });
      }
    }
  }

  // 1. Report: Income vs. Expenses (6-Month Window)
  function renderReportCashFlow() {
    const canvas = document.getElementById('reportCashflowChart');
    const noDataEl = document.getElementById('noCashflowData');
    const statsEl = document.getElementById('reportCashflowSummaryStats');
    const windowBadgeEl = document.getElementById('reportCashflowWindowBadge');
    if (!canvas) return;

    if (state.cashflowChartInstance) {
      state.cashflowChartInstance.destroy();
      state.cashflowChartInstance = null;
    }

    const cur = state.displayCurrency || 'EUR';
    const isAllTime = (!state.selectedMonth || state.selectedMonth === 'ALL' || state.selectedMonth === 'all');
    let anchorDate = new Date();
    if (!isAllTime && /^\d{4}-\d{2}$/.test(state.selectedMonth)) {
      const [yStr, mStr] = state.selectedMonth.split('-');
      const y = parseInt(yStr, 10);
      const m = parseInt(mStr, 10);
      if (!isNaN(y) && !isNaN(m)) {
        anchorDate = new Date(y, m - 1, 1);
      }
    }

    const months = [];
    for (let i = 5; i >= 0; i--) {
      const d = new Date(anchorDate.getFullYear(), anchorDate.getMonth() - i, 1);
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      const label = d.toLocaleDateString('en-US', { month: 'short' });
      const fullLabel = d.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
      months.push({ key, label, fullLabel, income: 0, spending: 0 });
    }

    if (windowBadgeEl && months.length === 6) {
      windowBadgeEl.textContent = `${months[0].label} – ${months[5].fullLabel}`;
    }

    // Tally Income across the 6-month window
    const allIncomes = getAllReceivedPayments();
    const seenIncomeIds = new Set();
    allIncomes.forEach(inc => {
      if (!inc || !inc.date) return;
      seenIncomeIds.add(inc.id);
      const mKey = inc.date.slice(0, 7);
      const targetMonth = months.find(m => m.key === mKey);
      if (targetMonth) {
        targetMonth.income += convertCurrency(parseFloat(inc.amount) || 0, inc.currency || cur, cur);
      }
    });

    // Tally Spending (and any direct income entries in expenses) across the 6-month window
    (state.expenses || []).forEach(exp => {
      if (!exp || !exp.date) return;
      const mKey = exp.date.slice(0, 7);
      const targetMonth = months.find(m => m.key === mKey);
      if (!targetMonth) return;
      const amt = convertCurrency(parseFloat(exp.amount) || 0, exp.currency || cur, cur);
      if (exp.isIncome || exp.type === 'income' || exp.category === 'Income') {
        if (!seenIncomeIds.has(exp.id)) {
          targetMonth.income += amt;
        }
      } else {
        targetMonth.spending += amt;
      }
    });

    const totalInflow = months.reduce((acc, m) => acc + m.income, 0);
    const totalOutflow = months.reduce((acc, m) => acc + m.spending, 0);
    const netDelta = totalInflow - totalOutflow;

    if (statsEl) {
      statsEl.innerHTML = `
        <span class="text-slate-600 whitespace-nowrap">Income: <strong class="text-slate-900">${formatMoney(totalInflow, cur)}</strong></span>
        <span class="text-slate-300">•</span>
        <span class="text-slate-600 whitespace-nowrap">Expenses: <strong class="text-slate-900">${formatMoney(totalOutflow, cur)}</strong></span>
        <span class="text-slate-300">•</span>
        <span class="whitespace-nowrap ${netDelta >= 0 ? 'text-emerald-700' : 'text-rose-600'}">Net: <strong>${netDelta >= 0 ? '+' : ''}${formatMoney(netDelta, cur)}</strong></span>
      `;
    }

    const hasData = (totalInflow > 0 || totalOutflow > 0);
    if (!hasData) {
      if (noDataEl) noDataEl.classList.remove('hidden');
      canvas.classList.add('hidden');
      return;
    }

    if (noDataEl) noDataEl.classList.add('hidden');
    canvas.classList.remove('hidden');

    const labels = months.map(m => m.label);
    const incomeData = months.map(m => Math.round(m.income * 100) / 100);
    const spendingData = months.map(m => Math.round(m.spending * 100) / 100);

    if (typeof Chart === 'undefined') return;
    state.cashflowChartInstance = new Chart(canvas, {
      type: 'bar',
      data: {
        labels,
        datasets: [
          {
            type: 'bar',
            label: 'Income',
            data: incomeData,
            backgroundColor: '#10b981',
            borderRadius: 6,
            maxBarThickness: 24
          },
          {
            type: 'bar',
            label: 'Expenses',
            data: spendingData,
            backgroundColor: '#0f172a',
            borderRadius: 6,
            maxBarThickness: 24
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: true,
            position: 'top',
            labels: {
              boxWidth: 10,
              boxHeight: 10,
              usePointStyle: true,
              font: { size: 11, family: 'Inter, sans-serif' },
              color: '#64748b'
            }
          },
          tooltip: {
            callbacks: {
              label: (ctx) => ` ${ctx.dataset.label}: ${formatMoney(ctx.raw, cur)}`
            }
          }
        },
        scales: {
          x: {
            grid: { display: false },
            ticks: { color: '#64748b', font: { size: 11 } }
          },
          y: {
            grid: { color: 'rgba(226, 232, 240, 0.6)' },
            ticks: {
              color: '#64748b',
              font: { size: 10 },
              callback: (v) => formatMoney(v, cur)
            }
          }
        }
      }
    });
  }

  // 2. Report: Tax Receipts
  function renderReportTaxDeductions() {
    const cur = state.displayCurrency || 'EUR';
    const isAllTime = (!state.selectedMonth || state.selectedMonth === 'ALL' || state.selectedMonth === 'all');
    const monthExpenses = getReportPeriodExpenses();

    let businessTotal = 0;
    let personalTotal = 0;
    let businessReceiptsCount = 0;
    let businessTotalCount = 0;
    let missingTaxReceiptsCount = 0;
    const missingBizItems = [];
    const businessCategoryMap = {};

    monthExpenses.forEach(e => {
      const amt = convertCurrency(parseFloat(e.amount) || 0, e.currency || cur, cur);
      if (e.isBusiness) {
        businessTotal += amt;
        businessTotalCount++;
        const cat = e.category || 'Business';
        businessCategoryMap[cat] = (businessCategoryMap[cat] || 0) + amt;
        if (e.hasAttachment) {
          businessReceiptsCount++;
        } else {
          missingTaxReceiptsCount++;
          missingBizItems.push(e);
        }
      } else {
        personalTotal += amt;
      }
    });

    const totalSpend = businessTotal + personalTotal;
    const deductiblePct = totalSpend > 0 ? ((businessTotal / totalSpend) * 100).toFixed(0) : 0;
    const receiptHealthPct = businessTotalCount > 0 ? ((businessReceiptsCount / businessTotalCount) * 100).toFixed(0) : 100;

    // Metric Text Elements
    const dedTotalEl = document.getElementById('reportDeductibleTotal');
    if (dedTotalEl) dedTotalEl.textContent = formatMoney(businessTotal, cur);
    const dedPctEl = document.getElementById('reportDeductiblePercent');
    if (dedPctEl) dedPctEl.textContent = `${deductiblePct}% of ${isAllTime ? 'total' : "month's"} spend`;

    const rCountEl = document.getElementById('reportTaxReceiptCount');
    if (rCountEl) rCountEl.textContent = `${businessReceiptsCount} / ${businessTotalCount}`;
    const rPctEl = document.getElementById('reportTaxReceiptPercent');
    if (rPctEl) rPctEl.textContent = `${receiptHealthPct}% ready`;

    const rMissEl = document.getElementById('reportMissingTaxReceipts');
    if (rMissEl) rMissEl.textContent = `${missingTaxReceiptsCount}`;

    const rMissCardEl = document.getElementById('reportMissingTaxCard');
    if (rMissCardEl) {
      if (missingTaxReceiptsCount > 0) {
        rMissCardEl.className = 'bg-amber-50/60 hover:bg-amber-50 border border-amber-200/80 rounded-xl p-3 transition-colors cursor-pointer';
        rMissCardEl.title = 'Click to view missing receipts';
        rMissCardEl.onclick = () => showMissingReceiptsWarning(missingBizItems);
      } else {
        rMissCardEl.className = 'bg-slate-50/70 border border-slate-100 rounded-xl p-3 transition-colors';
        rMissCardEl.title = '';
        rMissCardEl.onclick = null;
      }
    }

    // Header Badge
    const healthBadgeEl = document.getElementById('reportTaxHealthBadge');
    if (healthBadgeEl) {
      if (businessTotalCount === 0) {
        healthBadgeEl.innerHTML = `<span class="px-2 py-0.5 text-[10px] font-semibold bg-slate-50 text-slate-500 rounded-full border border-slate-200/80 whitespace-nowrap">0 items</span>`;
        healthBadgeEl.onclick = null;
      } else if (missingTaxReceiptsCount === 0) {
        healthBadgeEl.innerHTML = `<span class="px-2 py-0.5 text-[10px] font-semibold bg-emerald-50 text-emerald-700 rounded-full border border-emerald-200/80 whitespace-nowrap">All Attached</span>`;
        healthBadgeEl.onclick = null;
      } else {
        healthBadgeEl.innerHTML = `<button type="button" class="px-2 py-0.5 text-[10px] font-semibold bg-amber-50 hover:bg-amber-100 text-amber-800 rounded-full border border-amber-200/80 cursor-pointer transition-colors whitespace-nowrap">${missingTaxReceiptsCount} Missing</button>`;
        healthBadgeEl.onclick = () => showMissingReceiptsWarning(missingBizItems);
      }
    }

    // Tax Categories List
    const catListEl = document.getElementById('reportTaxCategoryList');
    if (catListEl) {
      const sortedCats = Object.entries(businessCategoryMap).sort((a, b) => b[1] - a[1]);
      if (sortedCats.length === 0) {
        catListEl.innerHTML = `<div class="p-4 text-center text-slate-400 text-xs">No tax expenses for this period.</div>`;
      } else {
        catListEl.innerHTML = sortedCats.map(([cat, amt]) => {
          const col = getCategoryColor(cat);
          const pct = businessTotal > 0 ? ((amt / businessTotal) * 100).toFixed(0) : 0;
          return `
            <div class="px-3.5 py-2.5 flex items-center justify-between hover:bg-slate-50/60 transition-colors">
              <div class="flex items-center gap-2 min-w-0">
                <span class="w-2.5 h-2.5 rounded-full shrink-0" style="background-color: ${col};"></span>
                <span class="font-medium text-slate-800 truncate">${escapeHtml(cat)}</span>
              </div>
              <div class="flex items-center gap-3 font-mono shrink-0">
                <span class="font-bold text-slate-900 whitespace-nowrap">${formatMoney(amt, cur)}</span>
                <span class="w-9 text-right text-slate-400 font-semibold text-[10px] whitespace-nowrap">${pct}%</span>
              </div>
            </div>
          `;
        }).join('');
      }
    }

    if (state.taxChartInstance) {
      state.taxChartInstance.destroy();
      state.taxChartInstance = null;
    }
  }

  // 3. Report: Fixed Bills vs. Everyday Spending
  function renderReportOverheadRunway() {
    const cur = state.displayCurrency || 'EUR';
    const isAllTime = (!state.selectedMonth || state.selectedMonth === 'ALL' || state.selectedMonth === 'all');
    const periodExpenses = getReportPeriodExpenses();

    // Split actual period expenses into Fixed Bills vs. Everyday so Fixed + Everyday === Total Expenses
    let fixedPeriodOverhead = 0;
    let discretionarySpend = 0;
    periodExpenses.forEach(e => {
      const amt = convertCurrency(parseFloat(e.amount) || 0, e.currency || cur, cur);
      if (isFlexibleExpense(e)) {
        discretionarySpend += amt;
      } else {
        fixedPeriodOverhead += amt;
      }
    });

    const totalOperationalBurn = fixedPeriodOverhead + discretionarySpend;
    const fixedRatio = totalOperationalBurn > 0 ? Math.round((fixedPeriodOverhead / totalOperationalBurn) * 100) : 0;
    const discRatio = totalOperationalBurn > 0 ? Math.max(0, 100 - fixedRatio) : 0;

    // Calculate Daily Avg across the period based on actual expense months
    let daysInPeriod = 30;
    const now = new Date();
    const thisMonthKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    if (isAllTime) {
      const expMonths = new Set();
      periodExpenses.forEach(e => {
        if (e && e.date && e.date.length >= 7) expMonths.add(e.date.slice(0, 7));
      });
      daysInPeriod = Math.max(1, expMonths.size) * 30;
    } else if (/^\d{4}-\d{2}$/.test(state.selectedMonth)) {
      const [yrStr, moStr] = String(state.selectedMonth).split('-');
      const yr = parseInt(yrStr, 10);
      const mo = parseInt(moStr, 10);
      if (!isNaN(yr) && !isNaN(mo)) {
        if (state.selectedMonth === thisMonthKey) {
          daysInPeriod = Math.max(1, now.getDate());
        } else {
          daysInPeriod = new Date(yr, mo, 0).getDate() || 30;
        }
      }
    }
    const dailyAvg = totalOperationalBurn / Math.max(1, daysInPeriod);

    // Update UI elements
    const fixedTitleEl = document.getElementById('reportFixedOverheadTitle');
    if (fixedTitleEl) fixedTitleEl.textContent = 'Fixed Bills';
    const fixedAmtEl = document.getElementById('reportFixedOverheadAmount');
    if (fixedAmtEl) fixedAmtEl.textContent = formatMoney(fixedPeriodOverhead, cur);
    const fixedRatioEl = document.getElementById('reportFixedOverheadRatio');
    if (fixedRatioEl) fixedRatioEl.textContent = `${fixedRatio}% of spend`;

    const discAmtEl = document.getElementById('reportDiscretionaryAmount');
    if (discAmtEl) discAmtEl.textContent = formatMoney(discretionarySpend, cur);
    const discRatioEl = document.getElementById('reportDiscretionaryRatio');
    if (discRatioEl) discRatioEl.textContent = `${discRatio}% of spend`;

    const runwayMoEl = document.getElementById('reportRunwayMonths');
    if (runwayMoEl) runwayMoEl.textContent = formatMoney(dailyAvg, cur);
    const runwayPendEl = document.getElementById('reportRunwayPending');
    if (runwayPendEl) runwayPendEl.textContent = `Per day (${daysInPeriod}d)`;

    // Visual Progress Bar
    const fixedBar = document.getElementById('reportOverheadFixedBar');
    const discBar = document.getElementById('reportOverheadDiscretionaryBar');
    if (fixedBar) fixedBar.style.width = `${fixedRatio}%`;
    if (discBar) discBar.style.width = `${discRatio}%`;

    const fixedBarLbl = document.getElementById('reportFixedBarLabel');
    if (fixedBarLbl) fixedBarLbl.textContent = `${formatMoney(fixedPeriodOverhead, cur)} (${fixedRatio}%)`;
    const discBarLbl = document.getElementById('reportDiscretionaryBarLabel');
    if (discBarLbl) discBarLbl.textContent = `${formatMoney(discretionarySpend, cur)} (${discRatio}%)`;

    // Split Badge
    const runwayBadge = document.getElementById('reportOverheadRunwayBadge');
    if (runwayBadge) {
      runwayBadge.innerHTML = `<span class="px-2 py-0.5 text-[10px] font-semibold bg-slate-50 text-slate-600 rounded-full border border-slate-200/80 whitespace-nowrap">${fixedRatio}% Fixed • ${discRatio}% Everyday</span>`;
    }
  }

  function exportReportsCsv() {
    const periodExpenses = getReportPeriodExpenses();
    if (periodExpenses.length === 0) {
      alert('No expenses found for this period to export.');
      return;
    }

    const headers = ['ID', 'Date', 'Title', 'Category', 'Is Subscription', 'Business / Tax', 'Has Receipt File', 'Original Amount', 'Currency', 'USD Equivalent', 'EUR Equivalent', 'ILS Equivalent', 'Payment Method', 'Notes'];
    const rows = periodExpenses.map(item => {
      const amt = parseFloat(item.amount) || 0;
      const tri = getTriCurrencyValues(amt, item.currency);
      return [
        `"${item.id}"`,
        `"${item.date || ''}"`,
        `"${(item.title || '').replace(/"/g, '""')}"`,
        `"${(item.category || 'Other').replace(/"/g, '""')}"`,
        item.isSubscription ? '"Yes"' : '"No"',
        item.isBusiness ? '"Yes"' : '"No"',
        item.hasAttachment ? '"Yes"' : '"No"',
        amt.toFixed(2),
        `"${item.currency || 'EUR'}"`,
        tri.USD.toFixed(2),
        tri.EUR.toFixed(2),
        tri.ILS.toFixed(2),
        `"${(item.paymentMethod || '').replace(/"/g, '""')}"`,
        `"${(item.notes || '').replace(/"/g, '""')}"`
      ].join(',');
    });

    const csvContent = [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    const periodSlug = (!state.selectedMonth || state.selectedMonth === 'ALL' || state.selectedMonth === 'all') ? 'all_time' : state.selectedMonth;
    a.download = `finland_expenses_${periodSlug}_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

  async function resolveReportExpenseAttachment(item) {
    if (!item) return null;
    let attachment = await getReceiptAttachment(item.id);
    if ((!attachment || !attachment.data) && item.attachment && item.attachment.data) {
      attachment = item.attachment;
    }
    if ((!attachment || !attachment.data) && item.receiptId) {
      attachment = await getReceiptAttachment(item.receiptId);
    }
    if (!attachment || !attachment.data) {
      const linkedSub = typeof findMatchingSubscriptionForExpense === 'function' ? findMatchingSubscriptionForExpense(item) : null;
      if (linkedSub && Array.isArray(linkedSub.taxReceipts) && linkedSub.taxReceipts.length > 0) {
        const expMonth = (item.date || '').slice(0, 7);
        const subRec = linkedSub.taxReceipts.find(r => (r.monthKey || getSubReceiptMonthKey(r)) === expMonth) || linkedSub.taxReceipts[linkedSub.taxReceipts.length - 1];
        if (subRec && (subRec.id || subRec.expenseId)) {
          attachment = await getReceiptAttachment(subRec.id || subRec.expenseId);
        }
      }
    }
    return attachment;
  }

  async function exportReportsAccountingZip() {
    if (typeof reconcileSubscriptionReceiptsWithExpenses === 'function') {
      try { reconcileSubscriptionReceiptsWithExpenses(); } catch (e) {}
    }

    const bizExpenses = (state.expenses || []).filter(e => e && e.isBusiness && !e.isIncome && e.type !== 'income' && e.category !== 'Income');
    if (bizExpenses.length === 0) {
      alert('No business expenses found to export.\n\nYou can mark any expense as a business expense by clicking "+ Business" or checking "Business Expense" in the Add/Edit form.');
      return;
    }

    const missingReceipts = bizExpenses.filter(e => !e.hasAttachment);
    if (missingReceipts.length > 0) {
      showMissingReceiptsWarning(missingReceipts);
      return;
    }

    showToast('Preparing Bundle...', `Gathering ${bizExpenses.length} business expenses & receipts for accountant...`, 'info');

    const headers = [
      'Item #',
      'Date',
      'Merchant / Provider',
      'Category',
      'Original Amount',
      'Currency',
      'USD Equivalent',
      'EUR Equivalent',
      'ILS Equivalent',
      'Payment Method',
      'Is Subscription',
      'Receipt File Attached',
      'Receipt Filename in ZIP',
      'Notes / Purpose'
    ];

    const rows = [];
    let receiptFilesCount = 0;
    const zip = (typeof JSZip !== 'undefined') ? new JSZip() : null;
    const receiptsFolder = zip ? zip.folder('receipts_and_invoices') : null;

    for (let i = 0; i < bizExpenses.length; i++) {
      const item = bizExpenses[i];
      const itemNum = i + 1;
      const amt = parseFloat(item.amount) || 0;
      const tri = getTriCurrencyValues(amt, item.currency);
      let receiptZipName = 'None';

      if (item.hasAttachment) {
        try {
          const attachment = await resolveReportExpenseAttachment(item);
          if (attachment && attachment.data && receiptsFolder) {
            const ext = attachment.type === 'pdf' ? 'pdf' : (attachment.type === 'image' ? 'png' : 'txt');
            const safeTitle = (item.title || 'Receipt').replace(/[^a-zA-Z0-9_-]/g, '_');
            receiptZipName = `${String(itemNum).padStart(3, '0')}_${item.date || 'no-date'}_${safeTitle}.${ext}`;

            if (attachment.data.startsWith('data:')) {
              const base64Data = attachment.data.split(',')[1];
              receiptsFolder.file(receiptZipName, base64Data, { base64: true });
            } else {
              receiptsFolder.file(receiptZipName, attachment.data);
            }
            receiptFilesCount++;
          }
        } catch (e) {
          console.warn('Error archiving receipt for accounting export:', e);
        }
      }

      rows.push([
        itemNum,
        `"${item.date || ''}"`,
        `"${(item.title || '').replace(/"/g, '""')}"`,
        `"${(item.category || '').replace(/"/g, '""')}"`,
        amt.toFixed(2),
        `"${item.currency || 'EUR'}"`,
        tri.USD.toFixed(2),
        tri.EUR.toFixed(2),
        tri.ILS.toFixed(2),
        `"${(item.paymentMethod || 'Credit Card').replace(/"/g, '""')}"`,
        item.isSubscription ? '"Yes"' : '"No"',
        item.hasAttachment ? '"Yes"' : '"No (Missing)"',
        `"${receiptZipName}"`,
        `"${(item.notes || '').replace(/"/g, '""')}"`
      ].join(','));
    }

    const csvContent = [headers.join(','), ...rows].join('\n');
    const dateStamp = new Date().toISOString().split('T')[0];

    if (zip) {
      zip.file(`Business_Expenses_Ledger_${dateStamp}.csv`, csvContent);

      const totalUSD = bizExpenses.reduce((acc, cur) => acc + convertCurrency(parseFloat(cur.amount) || 0, cur.currency, 'USD'), 0);
      const totalEUR = bizExpenses.reduce((acc, cur) => acc + convertCurrency(parseFloat(cur.amount) || 0, cur.currency, 'EUR'), 0);
      const totalILS = bizExpenses.reduce((acc, cur) => acc + convertCurrency(parseFloat(cur.amount) || 0, cur.currency, 'ILS'), 0);

      const summaryNote = `BUSINESS EXPENSES ACCOUNTING PACKAGE
========================================
Generated: ${new Date().toLocaleString()}
Application: Finland Private Vault

Total Business Records: ${bizExpenses.length}
Total Receipts Attached: ${receiptFilesCount}
Missing Receipts: ${bizExpenses.length - receiptFilesCount}

TOTAL BUSINESS SPEND (MULTI-CURRENCY TOTALS):
- Total in USD: $${totalUSD.toFixed(2)}
- Total in EUR: €${totalEUR.toFixed(2)}
- Total in ILS: ₪${totalILS.toFixed(2)}

FOLDER CONTENTS:
1. Business_Expenses_Ledger_${dateStamp}.csv - Complete spreadsheet of all deductible transactions.
2. receipts_and_invoices/ - High-resolution digital receipts, invoices, and photos numbered to match the CSV items.
`;
      zip.file('ACCOUNTING_SUMMARY.txt', summaryNote);

      const zipBlob = await zip.generateAsync({ type: 'blob' });
      const zipUrl = URL.createObjectURL(zipBlob);
      const downloadLink = document.createElement('a');
      downloadLink.href = zipUrl;
      downloadLink.download = `Business_Accounting_Bundle_${dateStamp}.zip`;
      downloadLink.click();
      URL.revokeObjectURL(zipUrl);

      showToast('Accounting Bundle Exported!', `Generated ZIP with CSV ledger + ${receiptFilesCount} receipts!`, 'success');
    } else {
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Business_Expenses_Ledger_${dateStamp}.csv`;
      a.click();
      URL.revokeObjectURL(url);
      showToast('Exported Business CSV', `Exported ${bizExpenses.length} business records.`, 'success');
    }
  }

  function setupReportsListeners() {
    const exportCsvBtn = document.getElementById('reportsExportCsvBtn');
    if (exportCsvBtn) {
      exportCsvBtn.addEventListener('click', () => {
        exportReportsCsv();
      });
    }

    const exportAccBtn = document.getElementById('reportsExportAccountingBtn');
    if (exportAccBtn) {
      exportAccBtn.addEventListener('click', () => {
        exportReportsAccountingZip();
      });
    }

    const netCard = document.getElementById('reportsHeaderNetCard');
    if (netCard) {
      netCard.addEventListener('click', () => {
        const target = document.getElementById('widget-reports-cashflow');
        if (target && typeof target.scrollIntoView === 'function') {
          target.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
      });
    }

    const spendCard = document.getElementById('reportsHeaderSpendCard');
    if (spendCard) {
      spendCard.addEventListener('click', () => {
        const target = document.getElementById('widget-reports-category');
        if (target && typeof target.scrollIntoView === 'function') {
          target.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
      });
    }

    const taxCard = document.getElementById('reportsHeaderTaxCard');
    if (taxCard) {
      taxCard.addEventListener('click', () => {
        const periodBizMissing = getReportPeriodExpenses().filter(e => e.isBusiness && !e.hasAttachment);
        if (periodBizMissing.length > 0) {
          showMissingReceiptsWarning(periodBizMissing);
        } else {
          const target = document.getElementById('widget-reports-tax');
          if (target && typeof target.scrollIntoView === 'function') {
            target.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
          }
        }
      });
    }
  }

  // ==========================================
  // 14. QUICK CONVERTER WIDGET
  // ==========================================
  function updateQuickConverter() {
    const inputAmt = parseFloat(document.getElementById('quickCalcAmount')?.value) || 0;
    const fromCur = document.getElementById('quickCalcCurrency')?.value || 'USD';

    const usdVal = convertCurrency(inputAmt, fromCur, 'USD');
    const eurVal = convertCurrency(inputAmt, fromCur, 'EUR');
    const ilsVal = convertCurrency(inputAmt, fromCur, 'ILS');

    document.getElementById('quickCalcResUsd').textContent = `$${usdVal.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    document.getElementById('quickCalcResEur').textContent = `€${eurVal.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    document.getElementById('quickCalcResIls').textContent = `₪${ilsVal.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  }

  function updateFormLiveConversionPreview() {
    const amt = parseFloat(document.getElementById('expenseAmount')?.value) || 0;
    const cur = document.getElementById('expenseCurrency')?.value || 'USD';
    const previewEl = document.getElementById('formConversionValues');

    if (amt <= 0) {
      previewEl.textContent = 'Enter amount to see live rates';
      return;
    }

    const tri = getTriCurrencyValues(amt, cur);
    previewEl.innerHTML = `
      <span>€${tri.EUR.toFixed(2)} EUR</span> •
      <span>₪${tri.ILS.toFixed(2)} ILS</span> •
      <span>$${tri.USD.toFixed(2)} USD</span>
    `;
  }

  // ==========================================
  // 15. MODALS & FORMS HANDLERS
  // ==========================================
  function updateModalNoReceiptUI() {
    const isBiz = document.getElementById('expenseIsBusiness') ? document.getElementById('expenseIsBusiness').checked : false;
    const attachedView = document.getElementById('modalReceiptAttachedView');
    const hasAtt = attachedView ? !attachedView.classList.contains('hidden') : false;
    const container = document.getElementById('modalNoReceiptNeededContainer');
    const statusBadge = document.getElementById('modalReceiptStatusBadge');
    const label = document.getElementById('modalToggleNoReceiptNeededLabel');
    const btn = document.getElementById('modalToggleNoReceiptNeededBtn');

    if (isBiz || hasAtt) {
      if (container) container.classList.add('hidden');
      state.modalNoReceiptNeeded = false;
      return;
    }

    if (container) container.classList.remove('hidden');

    if (state.modalNoReceiptNeeded) {
      if (statusBadge) {
        statusBadge.textContent = 'No receipt needed (Waived)';
        statusBadge.className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-slate-100 text-slate-600 border border-slate-200';
      }
      if (label) label.textContent = 'Receipt marked not needed — Click to require receipt again';
      if (btn) {
        btn.className = 'w-full py-1.5 px-3 border border-amber-200 bg-amber-50/70 hover:bg-amber-100/70 rounded-lg text-xs text-amber-900 font-medium flex items-center justify-center gap-1.5 transition-all cursor-pointer';
      }
    } else {
      if (statusBadge && !hasAtt) {
        statusBadge.textContent = 'No receipt attached';
        statusBadge.className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-slate-200 text-slate-700';
      }
      if (label) label.textContent = "Don't need a receipt for this (remove from missing counter)";
      if (btn) {
        btn.className = 'w-full py-1.5 px-3 border border-slate-200 hover:border-slate-300 bg-white hover:bg-slate-50 rounded-lg text-xs text-slate-600 font-medium flex items-center justify-center gap-1.5 transition-all cursor-pointer';
      }
    }
  }

  function setTransactionModalType(type) {
    const isIncome = type === 'income';
    const typeInput = document.getElementById('transactionType');
    if (typeInput) typeInput.value = isIncome ? 'income' : 'expense';

    const expBtn = document.getElementById('transTypeExpenseBtn');
    const incBtn = document.getElementById('transTypeIncomeBtn');
    if (expBtn && incBtn) {
      if (isIncome) {
        incBtn.className = 'flex-1 py-1.5 px-3 rounded-xl bg-emerald-600 text-white shadow-2xs transition-all flex items-center justify-center gap-1.5 cursor-pointer font-bold';
        expBtn.className = 'flex-1 py-1.5 px-3 rounded-xl text-slate-600 hover:text-slate-900 transition-all flex items-center justify-center gap-1.5 cursor-pointer font-semibold';
      } else {
        expBtn.className = 'flex-1 py-1.5 px-3 rounded-xl bg-white text-slate-900 shadow-2xs transition-all flex items-center justify-center gap-1.5 cursor-pointer font-bold';
        incBtn.className = 'flex-1 py-1.5 px-3 rounded-xl text-slate-600 hover:text-slate-900 transition-all flex items-center justify-center gap-1.5 cursor-pointer font-semibold';
      }
    }

    const modalTitle = document.getElementById('expenseModalTitle');
    const titleLabel = document.getElementById('expenseTitleLabel');
    const titleInput = document.getElementById('expenseTitle');
    const dateLabel = document.getElementById('expenseDateLabel');
    const submitBtn = document.getElementById('expenseSubmitBtn');
    const catContainer = document.getElementById('expenseCategory')?.closest('div');
    const bizRow = document.getElementById('expenseIsBusiness')?.closest('.flex');
    const subCard = document.getElementById('expenseIsSubscription')?.closest('.p-3');
    const noReceiptContainer = document.getElementById('modalNoReceiptNeededContainer');

    if (isIncome) {
      const isEditing = !!document.getElementById('editExpenseId')?.value;
      if (modalTitle) modalTitle.textContent = isEditing ? 'Edit Received Payment' : 'Record Received Payment';
      if (titleLabel) titleLabel.textContent = 'Client / Payer Source *';
      if (titleInput) titleInput.placeholder = 'e.g. Acme Corp, Design Client, Consulting';
      if (dateLabel) dateLabel.textContent = 'Received Date *';
      if (submitBtn) submitBtn.textContent = isEditing ? 'Save Payment' : 'Record Payment';
      if (catContainer) catContainer.style.display = 'none';
      if (bizRow) bizRow.style.display = 'none';
      if (subCard) subCard.style.display = 'none';
      if (noReceiptContainer) noReceiptContainer.style.display = 'none';
    } else {
      const isEditing = !!document.getElementById('editExpenseId')?.value;
      if (modalTitle) modalTitle.textContent = isEditing ? 'Edit Expense' : 'Add New Expense';
      if (titleLabel) titleLabel.textContent = 'Provider / Merchant Name *';
      if (titleInput) titleInput.placeholder = 'e.g. Midjourney, Netflix, Grocery shopping';
      if (dateLabel) dateLabel.textContent = 'Charge Date *';
      if (submitBtn) submitBtn.textContent = 'Save Expense';
      if (catContainer) catContainer.style.display = '';
      if (bizRow) bizRow.style.display = '';
      if (subCard) subCard.style.display = '';
      if (noReceiptContainer) noReceiptContainer.style.display = '';
    }
    lucide.createIcons();
  }

  function openEditIncomeModal(id) {
    const inc = (state.budget && Array.isArray(state.budget.incomes)) ? state.budget.incomes.find(i => i.id === id) : null;
    if (!inc) return;

    document.getElementById('editExpenseId').value = inc.id;
    setTransactionModalType('income');
    const switcher = document.getElementById('transactionTypeSwitcher');
    if (switcher) switcher.style.display = 'none';

    document.getElementById('expenseModalTitle').textContent = 'Edit Received Payment';
    const submitBtn = document.getElementById('expenseSubmitBtn');
    if (submitBtn) submitBtn.textContent = 'Save Payment';
    document.getElementById('expenseTitle').value = inc.title || inc.source || inc.client || '';
    document.getElementById('expenseAmount').value = inc.amount;
    document.getElementById('expenseCurrency').value = inc.currency || state.displayCurrency;
    document.getElementById('expenseDate').value = inc.date || new Date().toISOString().split('T')[0];
    document.getElementById('expensePaymentMethod').value = inc.method || inc.paymentMethod || 'Bank Transfer';
    document.getElementById('expenseNotes').value = inc.notes || '';

    const modalDelBtn = document.getElementById('modalDeleteExpenseBtn');
    if (modalDelBtn) {
      modalDelBtn.classList.remove('hidden');
      modalDelBtn.onclick = async () => {
        if (await confirmAction('Delete this received payment?')) {
          state.budget.incomes = state.budget.incomes.filter(i => i.id !== inc.id);
          saveBudget();
          renderDashboard();
          closeExpenseModal();
          showToast('Payment Deleted', 'Received payment removed.', 'info');
        }
      };
    }

    updateFormLiveConversionPreview();
    document.getElementById('expenseModal').classList.remove('hidden');
    document.getElementById('expenseModal').classList.add('flex');
    document.getElementById('expenseTitle').focus();
    lucide.createIcons();
  }

  function openAddExpenseModal() {
    syncCategoryDropdowns();
    const switcher = document.getElementById('transactionTypeSwitcher');
    if (switcher) switcher.style.display = 'flex';
    setTransactionModalType('expense');

    document.getElementById('expenseModalTitle').textContent = 'Add New Expense';
    document.getElementById('editExpenseId').value = '';
    document.getElementById('expenseTitle').value = '';
    document.getElementById('expenseAmount').value = '';
    document.getElementById('expenseCurrency').value = state.displayCurrency;
    document.getElementById('expenseCategory').value = 'Groceries';
    document.getElementById('expenseDate').value = new Date().toISOString().split('T')[0];
    document.getElementById('expenseIsBusiness').checked = false;
    document.getElementById('expenseIsSubscription').checked = false;
    const recOptions = document.getElementById('recurringExpenseOptions');
    if (recOptions) recOptions.classList.add('hidden');
    const recType = document.getElementById('expenseRecurringType');
    if (recType) recType.value = 'subscription';
    const recCycle = document.getElementById('expenseBillingCycle');
    const pmList = state.appPrefs?.paymentMethods || [];
    const defPmId = state.appPrefs?.defaultPaymentMethodId;
    const activePm = pmList.find(p => p.id === defPmId) || pmList.find(p => p.isDefault) || pmList[0];
    const defaultMethod = activePm ? activePm.name : (state.appPrefs?.defaultPaymentMethod || 'Credit Card');
    const defaultLast4 = activePm ? (activePm.last4 || '') : (state.appPrefs?.defaultCardLast4 || '');
    document.getElementById('expensePaymentMethod').value = defaultMethod;
    document.getElementById('expenseCardLast4').value = defaultLast4;
    document.getElementById('expenseNotes').value = '';
    state.pendingModalAttachment = null;
    state.modalNoReceiptNeeded = false;
    
    // Receipt section UI
    const statusBadge = document.getElementById('modalReceiptStatusBadge');
    if (statusBadge) {
      statusBadge.textContent = 'No receipt attached';
      statusBadge.className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-slate-200 text-slate-700';
    }
    const attachedView = document.getElementById('modalReceiptAttachedView');
    if (attachedView) attachedView.classList.add('hidden');

    const modalDelBtn = document.getElementById('modalDeleteExpenseBtn');
    if (modalDelBtn) modalDelBtn.classList.add('hidden');
    updateFormLiveConversionPreview();

    updateModalNoReceiptUI();
    document.getElementById('expenseModal').classList.remove('hidden');
    document.getElementById('expenseModal').classList.add('flex');
    document.getElementById('expenseTitle').focus();
    lucide.createIcons();
  }

  function openEditExpenseModal(id) {
    const item = state.expenses.find(e => e.id === id);
    if (!item) return;

    syncCategoryDropdowns();

    const switcher = document.getElementById('transactionTypeSwitcher');
    if (switcher) switcher.style.display = 'none';
    setTransactionModalType('expense');

    document.getElementById('expenseModalTitle').textContent = 'Edit Expense';
    document.getElementById('editExpenseId').value = item.id;
    document.getElementById('expenseTitle').value = item.title;
    document.getElementById('expenseAmount').value = item.amount;
    document.getElementById('expenseCurrency').value = item.currency;

    // Normalize legacy category aliases
    let catVal = item.category || 'Other';
    if (item.isSubscription || catVal === 'Subscriptions' || catVal === 'Monthly Expenses') {
      catVal = 'Monthly Expenses';
    } else if (catVal === 'Dining & Food') catVal = 'Dining';
    else if (catVal === 'Transportation') catVal = 'Transport';
    else if (catVal === 'Health & Medical') catVal = 'Health';

    document.getElementById('expenseCategory').value = catVal;
    document.getElementById('expenseDate').value = item.date;
    document.getElementById('expenseIsBusiness').checked = !!item.isBusiness;
    const isSub = !!item.isSubscription || catVal === 'Monthly Expenses';
    document.getElementById('expenseIsSubscription').checked = isSub;
    const recOptions = document.getElementById('recurringExpenseOptions');
    if (recOptions) {
      if (isSub) recOptions.classList.remove('hidden');
      else recOptions.classList.add('hidden');
    }
    const recType = document.getElementById('expenseRecurringType');
    if (recType) {
      const matchedSub = findMatchingSubscriptionForExpense(item);
      const subRecType = item.recurringType || (matchedSub ? matchedSub.recurringType : null);
      recType.value = subRecType || (isBasicRecurringCategory(item.category, item.title) ? 'basic_recurring' : 'subscription');
    }
    const recCycle = document.getElementById('expenseBillingCycle');
    if (recCycle) recCycle.value = item.billingCycle || 'monthly';
    document.getElementById('expensePaymentMethod').value = item.paymentMethod || 'Credit Card';
    document.getElementById('expenseCardLast4').value = item.cardLast4 || '';
    document.getElementById('expenseNotes').value = item.notes || '';
    state.pendingModalAttachment = null;
    state.modalNoReceiptNeeded = !item.isBusiness && !!item.noReceiptNeeded;
    
    // Receipt status UI in edit modal
    const statusBadge = document.getElementById('modalReceiptStatusBadge');
    const attachedView = document.getElementById('modalReceiptAttachedView');
    const fileNameEl = document.getElementById('modalReceiptFileName');
    const viewBtn = document.getElementById('modalViewAttachedReceiptBtn');
    const removeBtn = document.getElementById('modalRemoveAttachedReceiptBtn');

    if (item.hasAttachment) {
      if (statusBadge) {
        statusBadge.textContent = 'Receipt Attached ✓';
        statusBadge.className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-emerald-100 text-emerald-800 font-bold';
      }
      if (attachedView) attachedView.classList.remove('hidden');
      if (fileNameEl) fileNameEl.textContent = item.attachmentFileName || 'receipt_document';
      if (viewBtn) {
        viewBtn.onclick = () => openReceiptViewer(item.id);
      }
      if (removeBtn) {
        removeBtn.onclick = async () => {
          if (await confirmAction('Remove receipt document from this expense?')) {
            await deleteReceiptAttachment(item.id);
            item.hasAttachment = false;
            item.attachmentType = null;
            item.attachmentFileName = '';
            saveExpenses();
            renderDashboard();
            if (statusBadge) {
              statusBadge.textContent = 'No receipt attached';
              statusBadge.className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-slate-200 text-slate-700';
            }
            if (attachedView) attachedView.classList.add('hidden');
            showToast('Receipt Removed', 'Attachment unlinked from expense.', 'info');
          }
        };
      }
    } else {
      if (statusBadge) {
        statusBadge.textContent = 'No receipt attached';
        statusBadge.className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-slate-200 text-slate-700';
      }
      if (attachedView) attachedView.classList.add('hidden');
    }

    const modalDelBtn = document.getElementById('modalDeleteExpenseBtn');
    if (modalDelBtn) {
      modalDelBtn.classList.remove('hidden');
      modalDelBtn.onclick = () => {
        closeExpenseModal();
        deleteExpense(item.id);
      };
    }
    updateFormLiveConversionPreview();
    updateModalNoReceiptUI();

    document.getElementById('expenseModal').classList.remove('hidden');
    document.getElementById('expenseModal').classList.add('flex');
    lucide.createIcons();
  }

  function closeExpenseModal() {
    state.pendingModalAttachment = null;
    const modal = document.getElementById('expenseModal');
    if (modal) {
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }
  }



  // Voice & Speech Dictation Engine
  function initSpeechRecognition() {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      return null;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = true;
    recognition.lang = 'en-US';

    recognition.onstart = () => {
      state.isRecording = true;
      updateVoiceRecordingUI(true);
    };

    recognition.onresult = (event) => {
      let transcript = '';
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        transcript += event.results[i][0].transcript;
      }
      const inputEl = document.getElementById('naturalExpenseInput');
      if (inputEl) inputEl.value = transcript;
    };

    recognition.onerror = (event) => {
      console.warn('Speech recognition error:', event.error);
      state.isRecording = false;
      updateVoiceRecordingUI(false);
      let errorMsg = event.error;
      if (event.error === 'not-allowed') {
        errorMsg = 'Microphone permission blocked. Please allow microphone in macOS Settings / Browser Settings.';
      } else if (event.error === 'no-speech') {
        errorMsg = 'No speech detected. Please speak into your microphone or type your note.';
      }
      showToast('Mic Dictation', errorMsg, 'error');
    };

    recognition.onend = () => {
      const wasRecording = state.isRecording;
      state.isRecording = false;
      updateVoiceRecordingUI(false);
      const text = document.getElementById('naturalExpenseInput')?.value.trim();
      if (wasRecording && text) {
        // Auto transcribe once user stops speaking
        convertNaturalTextToExpense(text);
      }
    };

    return recognition;
  }

  function updateVoiceRecordingUI(recording) {
    const btn = document.getElementById('startVoiceRecordBtn');
    const label = document.getElementById('voiceRecordBtnLabel');
    const badge = document.getElementById('transcribeStatusBadge');
    const badgeText = document.getElementById('transcribeStatusText');

    if (recording) {
      if (btn) btn.classList.add('recording-pulse', 'bg-rose-600', 'text-white', 'border-rose-700');
      if (label) label.textContent = 'Listening... (Speak)';
      if (badge) {
        badge.classList.remove('hidden');
        badge.classList.add('flex');
      }
      if (badgeText) badgeText.textContent = 'Listening to your voice...';
    } else {
      if (btn) btn.classList.remove('recording-pulse', 'bg-rose-600', 'text-white', 'border-rose-700');
      if (label) label.textContent = 'Record Voice';
      if (badge) {
        badge.classList.add('hidden');
        badge.classList.remove('flex');
      }
    }
  }

  function toggleVoiceRecording() {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert('Speech recognition is not supported in this browser version. You can type or paste text into the box instead!');
      return;
    }

    if (!state.recognition) {
      state.recognition = initSpeechRecognition();
    }

    if (!state.recognition) return;

    if (state.isRecording) {
      state.recognition.stop();
      state.isRecording = false;
      updateVoiceRecordingUI(false);
    } else {
      try {
        state.recognition.start();
      } catch (e) {
        console.warn('Recognition start error:', e);
        // If already started or interrupted, recreate recognition instance
        state.recognition = initSpeechRecognition();
        try {
          state.recognition.start();
        } catch (err) {
          showToast('Mic Dictation', 'Could not access mic: ' + err.message, 'error');
        }
      }
    }
  }

  // Convert Natural Text (Voice or Typed) to Logged Expense
  async function convertNaturalTextToExpense(inputText) {
    const raw = (inputText || '').trim();
    if (!raw) return;

    try {
      showToast('Transcribing...', `Parsing: "${raw.substring(0, 35)}..."`, 'info');

      // Check if user toggled business checkbox in transcriber bar or mentioned business words
      const transcribeBizEl = document.getElementById('transcribeIsBusiness');
      const isExplicitBiz = transcribeBizEl ? transcribeBizEl.checked : false;
      const isTextBiz = /\b(business|work|client|company|tax|deductible|office|consulting)\b/i.test(raw);
      const isBusiness = isExplicitBiz || isTextBiz;

      let parsed = null;
      if (state.geminiApiKey) {
        try {
          parsed = await parseReceiptWithGemini(null, null, raw);
        } catch (e) {
          console.warn('Gemini parse fallback to heuristics:', e);
          parsed = parseReceiptWithHeuristics(raw);
        }
      } else {
        parsed = parseReceiptWithHeuristics(raw);
      }

      if (!parsed) {
        parsed = {
          merchantName: raw,
          amount: 0,
          currency: state.displayCurrency,
          category: 'Other',
          date: new Date().toISOString().split('T')[0]
        };
      }

      // Heuristically detect Shekels / NIS
      let currency = parsed.currency || state.displayCurrency;
      if (/nis|ils|shekel|shekels|ש"ח|שקלים/i.test(raw)) {
        currency = 'ILS';
      } else if (/euro|euros|eur|€/i.test(raw)) {
        currency = 'EUR';
      } else if (/dollar|dollars|bucks|usd|\$/i.test(raw)) {
        currency = 'USD';
      }

      // Extract amount from voice/text transcription
      let amt = 0;
      const voiceAmtMatch = raw.match(/(\d+(?:\.\d{1,2})?)\s*(?:dollars|bucks|euros|shekels|nis|ils|usd|eur|\$|€|₪)/i)
        || raw.match(/[$€₪]\s*(\d+(?:\.\d{1,2})?)/)
        || raw.match(/(?:for|paid|cost|spent|charged|total)\s+[$€₪]?\s*(\d+(?:\.\d{1,2})?)/i)
        || raw.match(/\b(\d+(?:\.\d{1,2})?)\b/);

      if (voiceAmtMatch && voiceAmtMatch[1]) {
        amt = parseFloat(voiceAmtMatch[1]);
      } else if (parsed.amount && parsed.amount > 0) {
        amt = parsed.amount;
      }

      // Extract merchant/title
      let merchant = parsed.merchantName;
      const forMatch = raw.match(/(?:for|at|to)\s+([A-Za-z0-9\s'._-]+?)(?:\s+(?:subscription|yesterday|today|last week|on|\$|\d|in)|$)/i);
      if (forMatch && forMatch[1] && forMatch[1].trim().length > 1) {
        merchant = forMatch[1].trim();
      } else if (!merchant || merchant === 'Receipt' || merchant === 'Midjourney' || merchant === 'Transcribed Expense') {
        const cleanTitle = raw
          .replace(/[$€₪]/g, '')
          .replace(/\b\d+(?:\.\d{1,2})?\b/g, '')
          .replace(/\b(dollars|bucks|euros|shekels|nis|ils|usd|eur|paid|spent|bought|for|subscription|monthly|business|work)\b/gi, '')
          .trim();
        if (cleanTitle.length > 1) {
          merchant = cleanTitle.charAt(0).toUpperCase() + cleanTitle.slice(1);
        } else {
          merchant = raw.substring(0, 30);
        }
      }

      // Detect category from raw text keywords
      let category = parsed.category || 'Other';
      if (/uber|lyft|taxi|train|bus|gas|fuel|parking|flight/i.test(raw)) {
        category = 'Transport';
      } else if (/restaurant|lunch|dinner|breakfast|cafe|coffee|starbucks|mcdonald|food|pizza|wolt/i.test(raw)) {
        category = 'Dining';
      } else if (/groceries|supermarket|market|shufersal|walmart|costco|trader joe/i.test(raw)) {
        category = 'Groceries';
      } else if (/pharmacy|doctor|dentist|health|medicine|super[\s-]?pharm/i.test(raw)) {
        category = 'Health';
      } else if (/rent|mortgage|apartment|home/i.test(raw)) {
        category = 'Housing';
      } else if (/electric|water|gas bill|internet|wifi|phone|cellcom|partner|bezeq/i.test(raw)) {
        category = 'Utilities';
      } else if (/movie|cinema|game|steam|playstation|xbox|concert|event/i.test(raw)) {
        category = 'Entertainment';
      } else if (/hotel|airbnb|booking|airline|flight|vacation/i.test(raw)) {
        category = 'Travel';
      } else if (/amazon|clothes|shopping|shoes|zara|nike|store/i.test(raw)) {
        category = 'Shopping';
      } else if (/subscription|sub|monthly|recurring|renew|netflix|spotify|openai|chatgpt|midjourney|claude/i.test(raw)) {
        category = 'Subscriptions';
      }

      const expenseId = 'exp_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4);
      const isSub = (parsed.isSubscription && parsed.isSubscription !== 'no') || /subscription|monthly|recurring/i.test(raw) || category === 'Subscriptions';

      // Detect payment method & card digits from raw voice/note text
      let paymentMethod = parsed.paymentMethod || 'Credit Card';
      let cardLast4 = parsed.cardLast4 || '';

      const voiceCardMatch = raw.match(/(?:ending in|card|visa|mastercard|amex|ending|x{2,}|[*•]{2,})\s*[:#]?\s*(\d{4})/i)
        || raw.match(/(?:visa|mc|amex|mastercard|credit|debit)[\s\S]{0,15}[*•x]{2,}(\d{4})/i)
        || raw.match(/\b[*•x]{2,}\s*(\d{4})\b/i);

      if (voiceCardMatch && voiceCardMatch[1]) {
        cardLast4 = voiceCardMatch[1];
      }

      if (/visa/i.test(raw)) paymentMethod = 'Visa';
      else if (/mastercard|mc/i.test(raw)) paymentMethod = 'Mastercard';
      else if (/amex|american express/i.test(raw)) paymentMethod = 'Amex';
      else if (/paypal/i.test(raw)) paymentMethod = 'PayPal';
      else if (/bit|paybox/i.test(raw)) paymentMethod = 'Bit / PayBox';
      else if (/bank transfer|wire/i.test(raw)) paymentMethod = 'Bank Transfer';
      else if (/cash/i.test(raw)) paymentMethod = 'Cash';
      else if (/debit/i.test(raw)) paymentMethod = 'Debit Card';

      const newExpense = {
        id: expenseId,
        title: merchant || 'Logged Expense',
        amount: amt > 0 ? amt : 10.00,
        currency: currency,
        category: category,
        date: parsed.date || new Date().toISOString().split('T')[0],
        isBusiness: isBusiness,
        isSubscription: isSub,
        billingCycle: isSub ? 'monthly' : 'onetime',
        paymentMethod: paymentMethod,
        cardLast4: cardLast4,
        notes: `Note: "${raw}"`,
        hasAttachment: false
      };

      addOrUpdateExpense(newExpense);

      const inputEl = document.getElementById('naturalExpenseInput');
      if (inputEl) inputEl.value = '';

      showToast(
        '✓ Transaction Logged!',
        `${newExpense.title} (${formatMoney(newExpense.amount, newExpense.currency)})${newExpense.isBusiness ? ' [💼 Business]' : ''} recorded!`,
        'success'
      );
    } catch (err) {
      console.error('convertNaturalTextToExpense error:', err);
      // Fallback: guaranteed minimal expense save
      const fallbackExpense = {
        id: 'exp_' + Date.now(),
        title: raw.substring(0, 35) || 'Quick Transaction',
        amount: 10.00,
        currency: state.displayCurrency || 'USD',
        category: 'Other',
        date: new Date().toISOString().split('T')[0],
        isBusiness: false,
        isSubscription: false,
        billingCycle: 'onetime',
        paymentMethod: 'Credit Card',
        cardLast4: '',
        notes: raw,
        hasAttachment: false
      };
      addOrUpdateExpense(fallbackExpense);
      const inputEl = document.getElementById('naturalExpenseInput');
      if (inputEl) inputEl.value = '';
      showToast('Logged!', `${fallbackExpense.title} added to ledger`, 'success');
    }
  }

