  // Quick Math Calculator
  let calcState = {
    current: '0',
    prev: null,
    op: null,
    resetNext: false
  };

  function updateCalcDisplay() {
    const curEl = document.getElementById('calcCurrentDisplay');
    const exprEl = document.getElementById('calcExprDisplay');
    if (curEl) curEl.textContent = calcState.current;
    if (exprEl) {
      if (calcState.prev !== null && calcState.op) {
        exprEl.textContent = `${calcState.prev} ${calcState.op}`;
      } else {
        exprEl.textContent = '';
      }
    }
  }

  function openCalculatorModal() {
    const m = document.getElementById('calculatorModal');
    if (m) {
      m.classList.remove('hidden');
      m.classList.add('flex');
      if (window.lucide) window.lucide.createIcons();
    }
  }

  function closeCalculatorModal() {
    const m = document.getElementById('calculatorModal');
    if (m) {
      m.classList.add('hidden');
      m.classList.remove('flex');
    }
  }

  function computeCalc(a, b, op) {
    const numA = parseFloat(a);
    const numB = parseFloat(b);
    if (isNaN(numA) || isNaN(numB)) return '0';
    let res = 0;
    if (op === '+') res = numA + numB;
    else if (op === '-') res = numA - numB;
    else if (op === '×' || op === '*') res = numA * numB;
    else if (op === '÷' || op === '/') {
      if (numB === 0) return 'Error';
      res = numA / numB;
    }
    // Round to avoid IEEE 754 precision issues like 0.1+0.2=0.30000000000000004
    return String(Math.round(res * 1e10) / 1e10);
  }

  function handleCalcInput(val) {
    if (val >= '0' && val <= '9') {
      if (calcState.resetNext || calcState.current === '0' || calcState.current === 'Error') {
        calcState.current = val;
        calcState.resetNext = false;
      } else {
        calcState.current += val;
      }
    } else if (val === '.') {
      if (calcState.resetNext || calcState.current === 'Error') {
        calcState.current = '0.';
        calcState.resetNext = false;
      } else if (!calcState.current.includes('.')) {
        calcState.current += '.';
      }
    } else if (val === 'C' || val === 'c') {
      calcState.current = '0';
      calcState.prev = null;
      calcState.op = null;
      calcState.resetNext = false;
    } else if (val === 'DEL' || val === 'Backspace') {
      if (calcState.resetNext || calcState.current === 'Error') {
        calcState.current = '0';
        calcState.resetNext = false;
      } else if (calcState.current.length > 1) {
        calcState.current = calcState.current.slice(0, -1);
      } else {
        calcState.current = '0';
      }
    } else if (val === '±') {
      if (calcState.current !== '0' && calcState.current !== 'Error') {
        calcState.current = calcState.current.startsWith('-') ? calcState.current.slice(1) : '-' + calcState.current;
      }
    } else if (val === '%') {
      if (calcState.current !== 'Error') {
        const num = parseFloat(calcState.current) || 0;
        calcState.current = String(num / 100);
      }
    } else if (val === '+' || val === '-' || val === '×' || val === '÷' || val === '*' || val === '/') {
      const standardOp = (val === '*' ? '×' : (val === '/' ? '÷' : val));
      if (calcState.op && calcState.prev !== null && !calcState.resetNext) {
        calcState.current = computeCalc(calcState.prev, calcState.current, calcState.op);
      }
      calcState.prev = calcState.current;
      calcState.op = standardOp;
      calcState.resetNext = true;
    } else if (val === '=' || val === 'Enter') {
      if (calcState.op && calcState.prev !== null) {
        calcState.current = computeCalc(calcState.prev, calcState.current, calcState.op);
        calcState.prev = null;
        calcState.op = null;
        calcState.resetNext = true;
      }
    }
    updateCalcDisplay();
  }

  // ==========================================
  // NAVIGATION & UI CUSTOMIZATION ENGINE
  // ==========================================
  function loadNavConfig() {
    try {
      const raw = localStorage.getItem(STORAGE_KEYS.NAV_CONFIG);
      if (raw) {
        const parsed = JSON.parse(raw);
        state.navConfig = {};
        Object.keys(DEFAULT_NAV_CONFIG).forEach(id => {
          state.navConfig[id] = {
            ...DEFAULT_NAV_CONFIG[id],
            ...(parsed[id] || {})
          };
        });
      } else {
        state.navConfig = JSON.parse(JSON.stringify(DEFAULT_NAV_CONFIG));
      }
    } catch (e) {
      state.navConfig = JSON.parse(JSON.stringify(DEFAULT_NAV_CONFIG));
    }

    try {
      const rawPrefs = localStorage.getItem(STORAGE_KEYS.APP_PREFS);
      if (rawPrefs) {
        state.appPrefs = { ...DEFAULT_APP_PREFS, ...JSON.parse(rawPrefs) };
      } else {
        state.appPrefs = { ...DEFAULT_APP_PREFS };
      }
    } catch (e) {
      state.appPrefs = { ...DEFAULT_APP_PREFS };
    }

    if (typeof window !== 'undefined' && (window.__FINLAND_DEMO_MODE__ || (window.location && window.location.pathname && window.location.pathname.indexOf('finland-showcase') !== -1))) {
      state.appPrefs = state.appPrefs || {};
      state.appPrefs.paymentMethods = [
        { id: 'pm_1', name: 'Wise Business Card', last4: '4242', isDefault: true },
        { id: 'pm_2', name: 'Studio Corporate Card', last4: '8820', isDefault: false },
        { id: 'pm_3', name: 'Bank Wire Transfer', last4: '', isDefault: false }
      ];
      state.appPrefs.defaultPaymentMethodId = 'pm_1';
    }
  }

  function saveNavConfig() {
    try {
      localStorage.setItem(STORAGE_KEYS.NAV_CONFIG, JSON.stringify(state.navConfig));
      localStorage.setItem(STORAGE_KEYS.APP_PREFS, JSON.stringify(state.appPrefs));
      triggerSafeVaultPush();
    } catch (e) {
      console.warn('Could not save navConfig:', e);
    }
  }

  function applyNavConfig(targetNavConfig, targetAppPrefs) {
    const navConfig = targetNavConfig || state.draftNavConfig || state.navConfig;
    const appPrefs = targetAppPrefs || state.draftAppPrefs || state.appPrefs;
    if (!navConfig) return;

    Object.keys(navConfig).forEach(navId => {
      const cfg = navConfig[navId];
      const btn = document.querySelector(`[data-nav-id="${navId}"]`);
      if (!btn) return;

      // 1. Visibility control
      if (cfg.visible === false) {
        btn.style.display = 'none';
      } else {
        btn.style.display = '';
      }

      // 2. Safe name label
      const container = btn.querySelector('.flex.items-center.gap-3') || btn;
      const labelEl = container.querySelector('span:not(.sidebar-drag-handle)');
      if (labelEl) {
        labelEl.textContent = cfg.name || cfg.defaultName;
      }

      // 3. Icon & Color
      const existingIcon = container.querySelector('i, svg');
      if (existingIcon) {
        const newIcon = document.createElement('i');
        newIcon.setAttribute('data-lucide', cfg.icon || cfg.defaultIcon);
        newIcon.className = 'w-4 h-4 shrink-0 transition-colors';
        if (cfg.color) {
          newIcon.style.color = cfg.color;
        }
        existingIcon.replaceWith(newIcon);
      }
    });

    // 4. Sidebar density preference
    const sidebarSections = document.querySelectorAll('.sidebar-nav-section');
    if (sidebarSections.length) {
      sidebarSections.forEach(sec => {
        if (appPrefs && appPrefs.sidebarDensity === 'compact') {
          sec.classList.add('space-y-0.5');
          sec.classList.remove('space-y-1');
        } else {
          sec.classList.remove('space-y-0.5');
          sec.classList.add('space-y-1');
        }
      });
    }

    if (typeof updateSidebarDividerVisibility === 'function') {
      updateSidebarDividerVisibility();
    }

    // Refresh icons
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    // Failsafe: if the currently active tab has been hidden, switch to the first visible tab
    if (state.currentTab && navConfig[state.currentTab] && navConfig[state.currentTab].visible === false) {
      const firstVisible = Object.values(navConfig).find(n => n.visible);
      if (firstVisible && window._ftSetActiveTab) {
        window._ftSetActiveTab(firstVisible.id);
      }
    }
  }

  function refreshLiveSettingsPreview() {
    applyNavConfig();
    renderSidebarSubscriptionCalendar();
    updateCurrencyButtonsUI();
    updateFloatingAddButtonUI();
    if (typeof syncPaymentMethodDropdowns === 'function') {
      syncPaymentMethodDropdowns();
    }
    renderDashboard();
    if (state.currentTab === 'wishlist') renderWishlistView();
    else if (state.currentTab === 'budget') renderBudgetView();
    else if (state.currentTab === 'subscriptions') renderSubscriptionsView();
    else if (state.currentTab === 'needs_to_pay') renderNeedsToPayView();
    else if (state.currentTab === 'notes') renderNotesView();
    else if (state.currentTab === 'calendar_plan') renderCalendarPlanView();
    else if (state.currentTab === 'project_followup') renderProjectFollowupView();
    else if (state.currentTab === 'reports') renderReportsView();
  }

  function updateFloatingAddButtonUI() {
    const fab = document.getElementById('openAddExpenseBtn');
    const searchInput = document.getElementById('expenseSearchInput');
    if (searchInput) {
      if (state.currentTab === 'calendar_plan') {
        searchInput.placeholder = 'Search calendar, plans, stepstones & notes...';
      } else {
        searchInput.placeholder = 'Search transactions...';
      }
    }
    if (!fab) return;
    if (state.currentTab === 'calendar_plan') {
      fab.style.display = '';
      fab.innerHTML = `<i data-lucide="calendar-plus" class="w-3.5 h-3.5 text-white stroke-[2.2]"></i><span>New Plan / Event</span>`;
      if (window.lucide && typeof window.lucide.createIcons === 'function') {
        try { window.lucide.createIcons(); } catch (e) {}
      }
      return;
    } else {
      fab.innerHTML = `<i data-lucide="plus" class="w-3.5 h-3.5 text-white stroke-[2.2]"></i><span>Add transaction</span>`;
      if (window.lucide && typeof window.lucide.createIcons === 'function') {
        try { window.lucide.createIcons(); } catch (e) {}
      }
    }
    const pref = state.appPrefs?.quickAddFabVisibility || 'all';
    if (pref === 'transactions') {
      if (state.currentTab === 'expenses') {
        fab.style.display = '';
      } else {
        fab.style.display = 'none';
      }
    } else {
      fab.style.display = '';
    }
  }

  function initCustomizeDraft() {
    state.draftNavConfig = JSON.parse(JSON.stringify(state.navConfig));
    state.draftAppPrefs = JSON.parse(JSON.stringify(state.appPrefs || {}));
    if (typeof window !== 'undefined' && (window.__FINLAND_DEMO_MODE__ || (window.location && window.location.pathname && window.location.pathname.indexOf('finland-showcase') !== -1))) {
      state.draftAppPrefs.paymentMethods = [
        { id: 'pm_1', name: 'Wise Business Card', last4: '4242', isDefault: true },
        { id: 'pm_2', name: 'Studio Corporate Card', last4: '8820', isDefault: false },
        { id: 'pm_3', name: 'Bank Wire Transfer', last4: '', isDefault: false }
      ];
      state.draftAppPrefs.defaultPaymentMethodId = 'pm_1';
    }
    delete state.draftResetSidebarOrder;
  }

  function renderCustomizeSettings() {
    const listEl = document.getElementById('customizeNavItemsList');
    if (!listEl) return;

    if (!state.draftNavConfig) {
      state.draftNavConfig = JSON.parse(JSON.stringify(state.navConfig));
    }
    if (!state.draftAppPrefs) {
      state.draftAppPrefs = JSON.parse(JSON.stringify(state.appPrefs || {}));
    }

    // Sync preference inputs
    const startupSelect = document.getElementById('prefDefaultStartupTab');
    if (startupSelect) {
      startupSelect.value = state.draftAppPrefs?.defaultStartupTab || 'expenses';
    }

    const densitySelect = document.getElementById('prefSidebarDensity');
    if (densitySelect) {
      densitySelect.value = state.draftAppPrefs?.sidebarDensity || 'comfortable';
    }

    // 1. Visual Calendar Preferences & Live Preview
    const currentWeekStart = state.draftAppPrefs?.calendarWeekStart || 'sunday';
    const currentDotColor = state.draftAppPrefs?.calendarDotColor || '#9333ea';
    const currentBillingStyle = state.draftAppPrefs?.calendarBillingStyle || 'badge';
    const currentTodayStyle = state.draftAppPrefs?.calendarTodayStyle || 'ring';
    const currentTodayColor = state.draftAppPrefs?.calendarTodayColor || '#f97315';
    const currentHeaderIconColor = state.draftAppPrefs?.calendarHeaderIconColor || '#9333ea';
    const currentAdjacentDays = state.draftAppPrefs?.calendarAdjacentDays || 'faded';
    const currentSummaryMode = state.draftAppPrefs?.calendarSummaryMode || 'count';

    // Option 1: Billing Style
    const prefCalBillingStyle = document.getElementById('prefCalBillingStyle');
    if (prefCalBillingStyle) {
      prefCalBillingStyle.value = currentBillingStyle;
      prefCalBillingStyle.onchange = (e) => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.calendarBillingStyle = e.target.value;
        refreshLiveSettingsPreview();
      };
    }

    // Option 2: Today Indicator Style & Color Swatches + Picker
    const prefCalTodayStyle = document.getElementById('prefCalTodayStyle');
    if (prefCalTodayStyle) {
      prefCalTodayStyle.value = currentTodayStyle;
      prefCalTodayStyle.onchange = (e) => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.calendarTodayStyle = e.target.value;
        refreshLiveSettingsPreview();
      };
    }

    const calTodayColorHidden = document.getElementById('prefCalTodayColor');
    if (calTodayColorHidden) calTodayColorHidden.value = currentTodayColor;

    const todayPaletteRow = document.getElementById('todayColorPaletteRow');
    if (todayPaletteRow) {
      const isPresetSelected = TODAY_INDICATOR_PALETTE.some(c => c.hex.toLowerCase() === currentTodayColor.toLowerCase());
      const swatchesHtml = TODAY_INDICATOR_PALETTE.map(c => {
        const isSelected = c.hex.toLowerCase() === currentTodayColor.toLowerCase();
        const activeClass = isSelected
          ? 'ring-2 ring-offset-1 ring-slate-800 scale-110 shadow-2xs z-10'
          : 'opacity-80 hover:opacity-100 hover:scale-105';
        return `
          <button type="button" class="w-4 h-4 sm:w-4.5 sm:h-4.5 rounded-full shrink-0 transition-all cursor-pointer shadow-2xs ${activeClass}" 
                  style="background-color: ${c.hex};" 
                  data-today-color="${c.hex}" 
                  title="${c.name} (${c.hex})">
          </button>
        `;
      }).join('');

      const customWheelActiveCls = !isPresetSelected
        ? 'ring-2 ring-offset-1 ring-slate-800 scale-110 shadow-2xs z-10'
        : 'opacity-85 hover:opacity-100 hover:scale-105';

      const toolsHtml = `
        <button type="button" id="todayColorEyedropperBtn" class="w-5 h-5 rounded-full bg-slate-100 hover:bg-slate-200 border border-slate-200/90 flex items-center justify-center text-slate-600 hover:text-slate-900 transition-all cursor-pointer shrink-0 shadow-2xs" title="Pick color from screen (Eyedropper)">
          <i data-lucide="pipette" class="w-2.5 h-2.5 pointer-events-none"></i>
        </button>
        <label class="relative w-4 h-4 sm:w-4.5 sm:h-4.5 rounded-full shrink-0 transition-all cursor-pointer shadow-2xs flex items-center justify-center ${customWheelActiveCls}"
               style="background: conic-gradient(from 0deg, #ef4444, #f97316, #eab308, #22c55e, #06b6d4, #3b82f6, #a855f7, #ec4899, #ef4444);"
               title="Custom Color Wheel (${escapeHtml(currentTodayColor)})">
          <input type="color" id="todayColorWheelInput" value="${escapeHtml(currentTodayColor)}" class="sr-only">
          ${!isPresetSelected ? `<span class="w-2 h-2 rounded-full border border-white shadow-2xs pointer-events-none" style="background-color: ${escapeHtml(currentTodayColor)};"></span>` : ''}
        </label>
      `;

      todayPaletteRow.innerHTML = swatchesHtml + toolsHtml;

      todayPaletteRow.querySelectorAll('[data-today-color]').forEach(btn => {
        btn.onclick = () => {
          const hex = btn.getAttribute('data-today-color');
          state.draftAppPrefs = state.draftAppPrefs || {};
          state.draftAppPrefs.calendarTodayColor = hex;
          renderCustomizeSettings();
          refreshLiveSettingsPreview();
        };
      });

      const wheelInput = document.getElementById('todayColorWheelInput');
      if (wheelInput) {
        wheelInput.oninput = (e) => {
          const hex = e.target.value;
          state.draftAppPrefs = state.draftAppPrefs || {};
          state.draftAppPrefs.calendarTodayColor = hex;
          const hiddenEl = document.getElementById('prefCalTodayColor');
          if (hiddenEl) hiddenEl.value = hex;
          refreshLiveSettingsPreview();
        };
        wheelInput.onchange = (e) => {
          const hex = e.target.value;
          state.draftAppPrefs = state.draftAppPrefs || {};
          state.draftAppPrefs.calendarTodayColor = hex;
          renderCustomizeSettings();
          refreshLiveSettingsPreview();
        };
      }

      const dropperBtn = document.getElementById('todayColorEyedropperBtn');
      if (dropperBtn) {
        dropperBtn.onclick = async () => {
          if (window.EyeDropper) {
            try {
              const eyeDropper = new window.EyeDropper();
              const result = await eyeDropper.open();
              if (result && result.sRGBHex) {
                state.draftAppPrefs = state.draftAppPrefs || {};
                state.draftAppPrefs.calendarTodayColor = result.sRGBHex;
                renderCustomizeSettings();
                refreshLiveSettingsPreview();
              }
            } catch (e) {}
          } else if (wheelInput) {
            wheelInput.click();
          }
        };
      }
    }

    // Option 2b: Calendar Title Icon Color Swatches + Picker
    const calHeaderIconColorHidden = document.getElementById('prefCalHeaderIconColor');
    if (calHeaderIconColorHidden) calHeaderIconColorHidden.value = currentHeaderIconColor;

    const headerIconPaletteRow = document.getElementById('calHeaderIconColorPaletteRow');
    if (headerIconPaletteRow) {
      const isIconPresetSelected = CAL_HEADER_ICON_PALETTE.some(c => c.hex.toLowerCase() === currentHeaderIconColor.toLowerCase());
      const iconSwatchesHtml = CAL_HEADER_ICON_PALETTE.map(c => {
        const isSelected = c.hex.toLowerCase() === currentHeaderIconColor.toLowerCase();
        const activeClass = isSelected
          ? 'ring-2 ring-offset-1 ring-slate-800 scale-110 shadow-2xs z-10'
          : 'opacity-80 hover:opacity-100 hover:scale-105';
        return `
          <button type="button" class="w-4 h-4 sm:w-4.5 sm:h-4.5 rounded-full shrink-0 transition-all cursor-pointer shadow-2xs ${activeClass}" 
                  style="background-color: ${c.hex};" 
                  data-header-icon-color="${c.hex}" 
                  title="${c.name} (${c.hex})">
          </button>
        `;
      }).join('');

      const iconCustomWheelActiveCls = !isIconPresetSelected
        ? 'ring-2 ring-offset-1 ring-slate-800 scale-110 shadow-2xs z-10'
        : 'opacity-85 hover:opacity-100 hover:scale-105';

      const iconToolsHtml = `
        <button type="button" id="calHeaderIconColorEyedropperBtn" class="w-5 h-5 rounded-full bg-slate-100 hover:bg-slate-200 border border-slate-200/90 flex items-center justify-center text-slate-600 hover:text-slate-900 transition-all cursor-pointer shrink-0 shadow-2xs" title="Pick color from screen (Eyedropper)">
          <i data-lucide="pipette" class="w-2.5 h-2.5 pointer-events-none"></i>
        </button>
        <label class="relative w-4 h-4 sm:w-4.5 sm:h-4.5 rounded-full shrink-0 transition-all cursor-pointer shadow-2xs flex items-center justify-center ${iconCustomWheelActiveCls}"
               style="background: conic-gradient(from 0deg, #ef4444, #f97316, #eab308, #22c55e, #06b6d4, #3b82f6, #a855f7, #ec4899, #ef4444);"
               title="Custom Color Wheel (${escapeHtml(currentHeaderIconColor)})">
          <input type="color" id="calHeaderIconColorWheelInput" value="${escapeHtml(currentHeaderIconColor)}" class="sr-only">
          ${!isIconPresetSelected ? `<span class="w-2 h-2 rounded-full border border-white shadow-2xs pointer-events-none" style="background-color: ${escapeHtml(currentHeaderIconColor)};"></span>` : ''}
        </label>
      `;

      headerIconPaletteRow.innerHTML = iconSwatchesHtml + iconToolsHtml;

      headerIconPaletteRow.querySelectorAll('[data-header-icon-color]').forEach(btn => {
        btn.onclick = () => {
          const hex = btn.getAttribute('data-header-icon-color');
          state.draftAppPrefs = state.draftAppPrefs || {};
          state.draftAppPrefs.calendarHeaderIconColor = hex;
          renderCustomizeSettings();
          refreshLiveSettingsPreview();
        };
      });

      const iconWheelInput = document.getElementById('calHeaderIconColorWheelInput');
      if (iconWheelInput) {
        iconWheelInput.oninput = (e) => {
          const hex = e.target.value;
          state.draftAppPrefs = state.draftAppPrefs || {};
          state.draftAppPrefs.calendarHeaderIconColor = hex;
          const hiddenEl = document.getElementById('prefCalHeaderIconColor');
          if (hiddenEl) hiddenEl.value = hex;
          refreshLiveSettingsPreview();
        };
        iconWheelInput.onchange = (e) => {
          const hex = e.target.value;
          state.draftAppPrefs = state.draftAppPrefs || {};
          state.draftAppPrefs.calendarHeaderIconColor = hex;
          renderCustomizeSettings();
          refreshLiveSettingsPreview();
        };
      }

      const iconDropperBtn = document.getElementById('calHeaderIconColorEyedropperBtn');
      if (iconDropperBtn) {
        iconDropperBtn.onclick = async () => {
          if (window.EyeDropper) {
            try {
              const eyeDropper = new window.EyeDropper();
              const result = await eyeDropper.open();
              if (result && result.sRGBHex) {
                state.draftAppPrefs = state.draftAppPrefs || {};
                state.draftAppPrefs.calendarHeaderIconColor = result.sRGBHex;
                renderCustomizeSettings();
                refreshLiveSettingsPreview();
              }
            } catch (e) {}
          } else if (iconWheelInput) {
            iconWheelInput.click();
          }
        };
      }
    }

    // Option 3: Adjacent Month Days
    const prefCalAdjacentDays = document.getElementById('prefCalAdjacentDays');
    if (prefCalAdjacentDays) {
      prefCalAdjacentDays.value = currentAdjacentDays;
      prefCalAdjacentDays.onchange = (e) => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.calendarAdjacentDays = e.target.value;
        refreshLiveSettingsPreview();
      };
    }

    // Option 4: Summary Counter Mode
    const prefCalSummaryMode = document.getElementById('prefCalSummaryMode');
    if (prefCalSummaryMode) {
      prefCalSummaryMode.value = currentSummaryMode;
      prefCalSummaryMode.onchange = (e) => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.calendarSummaryMode = e.target.value;
        refreshLiveSettingsPreview();
      };
    }

    const calWeekStartHidden = document.getElementById('prefCalWeekStart');
    if (calWeekStartHidden) calWeekStartHidden.value = currentWeekStart;

    const calDotColorHidden = document.getElementById('prefCalDotColor');
    if (calDotColorHidden) calDotColorHidden.value = currentDotColor;

    const sundayBtn = document.getElementById('prefCalWeekStartSundayBtn');
    const mondayBtn = document.getElementById('prefCalWeekStartMondayBtn');
    if (sundayBtn && mondayBtn) {
      if (currentWeekStart === 'sunday') {
        sundayBtn.className = 'py-1 px-3 rounded-lg text-xs font-bold transition-all cursor-pointer bg-white text-slate-900 shadow-2xs';
        mondayBtn.className = 'py-1 px-3 rounded-lg text-xs font-semibold text-slate-600 hover:text-slate-900 transition-all cursor-pointer';
      } else {
        mondayBtn.className = 'py-1 px-3 rounded-lg text-xs font-bold transition-all cursor-pointer bg-white text-slate-900 shadow-2xs';
        sundayBtn.className = 'py-1 px-3 rounded-lg text-xs font-semibold text-slate-600 hover:text-slate-900 transition-all cursor-pointer';
      }

      sundayBtn.onclick = () => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.calendarWeekStart = 'sunday';
        renderCustomizeSettings();
        refreshLiveSettingsPreview();
      };
      mondayBtn.onclick = () => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.calendarWeekStart = 'monday';
        renderCustomizeSettings();
        refreshLiveSettingsPreview();
      };
    }

    // Dot Color Swatches Row
    const paletteRow = document.getElementById('calColorPaletteRow');
    const colorBadge = document.getElementById('calColorNameBadge');
    if (paletteRow) {
      const activeColorObj = CUSTOMIZE_PALETTE.find(c => c.hex.toLowerCase() === currentDotColor.toLowerCase()) || { name: 'Custom', hex: currentDotColor };
      if (colorBadge) {
        colorBadge.textContent = activeColorObj.name;
        colorBadge.style.backgroundColor = `${currentDotColor}18`;
        colorBadge.style.color = currentDotColor;
      }

      paletteRow.innerHTML = CUSTOMIZE_PALETTE.map(c => {
        const isSelected = c.hex.toLowerCase() === currentDotColor.toLowerCase();
        const activeClass = isSelected
          ? 'ring-2 ring-offset-1 ring-slate-800 scale-110 shadow-2xs z-10'
          : 'opacity-80 hover:opacity-100 hover:scale-105';
        return `
          <button type="button" class="w-4 h-4 sm:w-4.5 sm:h-4.5 rounded-full shrink-0 transition-all cursor-pointer shadow-2xs ${activeClass}" 
                  style="background-color: ${c.hex};" 
                  data-cal-color="${c.hex}" 
                  data-cal-color-name="${c.name}" 
                  title="${c.name} (${c.hex})">
          </button>
        `;
      }).join('');

      paletteRow.querySelectorAll('[data-cal-color]').forEach(btn => {
        btn.onclick = () => {
          const hex = btn.getAttribute('data-cal-color');
          state.draftAppPrefs = state.draftAppPrefs || {};
          state.draftAppPrefs.calendarDotColor = hex;
          if (state.calendarPlan && state.calendarPlan.sources && state.calendarPlan.sources.bills) {
            state.calendarPlan.sources.bills.color = hex;
          }
          renderCustomizeSettings();
          refreshLiveSettingsPreview();
        };
      });
    }

    const showCalChk = document.getElementById('prefShowSidebarCalendar');
    if (showCalChk) {
      showCalChk.checked = state.draftAppPrefs?.showSidebarCalendar !== false;
      showCalChk.onchange = (e) => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.showSidebarCalendar = e.target.checked;
        refreshLiveSettingsPreview();
      };
    }

    // 2. Currencies Selector (Cap at 3)
    const selectedCurrencies = (state.draftAppPrefs?.displayedCurrencies && Array.isArray(state.draftAppPrefs.displayedCurrencies) && state.draftAppPrefs.displayedCurrencies.length > 0)
      ? state.draftAppPrefs.displayedCurrencies
      : ['EUR', 'ILS', 'USD'];

    const countBadge = document.getElementById('prefCurrenciesSelectedCount');
    if (countBadge) {
      countBadge.textContent = `${selectedCurrencies.length} / 3`;
      if (selectedCurrencies.length === 3) {
        countBadge.className = 'text-[10px] font-mono font-bold px-2.5 py-0.5 rounded-full bg-indigo-50 border border-indigo-200 text-indigo-700';
      } else {
        countBadge.className = 'text-[10px] font-mono font-bold px-2.5 py-0.5 rounded-full bg-slate-100 border border-slate-200 text-slate-700';
      }
    }

    const curGrid = document.getElementById('prefCurrenciesSelectorGrid');
    if (curGrid) {
      curGrid.innerHTML = ALL_SUPPORTED_CURRENCIES.map(c => {
        const isChecked = selectedCurrencies.includes(c.code);
        const activeBg = isChecked 
          ? 'bg-indigo-50/80 border-indigo-300 text-indigo-950 font-bold shadow-2xs' 
          : 'bg-white hover:bg-slate-50 border-slate-200 text-slate-600 font-medium';
        const checkIcon = isChecked
          ? `<i data-lucide="check" class="w-3 h-3 text-indigo-600 stroke-[3] ml-auto shrink-0"></i>`
          : '';
        return `
          <label class="flex items-center gap-1.5 px-3 py-2 rounded-xl border text-xs cursor-pointer transition-all ${activeBg}">
            <input type="checkbox" class="sr-only pref-currency-checkbox" data-currency="${c.code}" ${isChecked ? 'checked' : ''}>
            <span class="font-mono text-xs text-indigo-600 font-bold">${c.symbol}</span>
            <span class="text-xs truncate">${c.code}</span>
            ${checkIcon}
          </label>
        `;
      }).join('');

      curGrid.querySelectorAll('.pref-currency-checkbox').forEach(chk => {
        chk.onchange = (e) => {
          const code = chk.getAttribute('data-currency');
          let currentList = [...(state.draftAppPrefs?.displayedCurrencies || ['EUR', 'ILS', 'USD'])];
          if (chk.checked) {
            if (currentList.length >= 3) {
              chk.checked = false;
              showToast('Currency Limit', 'You can display up to 3 active currencies at once.', 'alert');
              return;
            }
            if (!currentList.includes(code)) currentList.push(code);
          } else {
            if (currentList.length <= 1) {
              chk.checked = true;
              showToast('Minimum Currency', 'At least 1 display currency must remain selected.', 'alert');
              return;
            }
            currentList = currentList.filter(x => x !== code);
          }
          state.draftAppPrefs = state.draftAppPrefs || {};
          state.draftAppPrefs.displayedCurrencies = currentList;
          renderCustomizeSettings();
          refreshLiveSettingsPreview();
        };
      });
    }

    // 3. Default Display Currency on Launch
    const defStartupCur = document.getElementById('prefDefaultStartupCurrency');
    if (defStartupCur) {
      defStartupCur.innerHTML = selectedCurrencies.map(code => {
        const sym = CURRENCY_SYMBOLS[code] || code;
        return `<option value="${code}">${code} (${sym})</option>`;
      }).join('');
      defStartupCur.value = selectedCurrencies.includes(state.draftAppPrefs?.defaultStartupCurrency)
        ? state.draftAppPrefs.defaultStartupCurrency
        : selectedCurrencies[0];
      defStartupCur.onchange = (e) => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.defaultStartupCurrency = e.target.value;
        refreshLiveSettingsPreview();
      };
    }

    // 4. Number Format / Locale
    const numLocaleSelect = document.getElementById('prefNumberFormatLocale');
    if (numLocaleSelect) {
      numLocaleSelect.value = state.draftAppPrefs?.numberFormatLocale || 'standard';
      numLocaleSelect.onchange = (e) => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.numberFormatLocale = e.target.value;
        refreshLiveSettingsPreview();
      };
    }

    // 6. Personal Payment Methods Manager & Default Selection
    if (!state.draftAppPrefs.paymentMethods || !Array.isArray(state.draftAppPrefs.paymentMethods) || state.draftAppPrefs.paymentMethods.length === 0) {
      state.draftAppPrefs.paymentMethods = [
        { id: 'pm_1', name: 'Visa', last4: '4022', isDefault: true },
        { id: 'pm_2', name: 'Mastercard', last4: '1289', isDefault: false },
        { id: 'pm_3', name: 'Bank Transfer', last4: '', isDefault: false }
      ];
      state.draftAppPrefs.defaultPaymentMethodId = 'pm_1';
    }

    const pmList = state.draftAppPrefs.paymentMethods;
    let defPmId = state.draftAppPrefs.defaultPaymentMethodId || (pmList[0] ? pmList[0].id : '');

    const defPmSelect = document.getElementById('prefDefaultPaymentMethodId');
    if (defPmSelect) {
      defPmSelect.innerHTML = pmList.map(pm => {
        const last4Text = pm.last4 ? ` (•••• ${pm.last4})` : '';
        return `<option value="${pm.id}">${escapeHtml(pm.name)}${last4Text}</option>`;
      }).join('');
      defPmSelect.value = defPmId;
      defPmSelect.onchange = (e) => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.defaultPaymentMethodId = e.target.value;
        state.draftAppPrefs.paymentMethods.forEach(pm => {
          pm.isDefault = (pm.id === e.target.value);
        });
        renderCustomizeSettings();
        refreshLiveSettingsPreview();
      };
    }

    const pmCountBadge = document.getElementById('prefPaymentMethodsCount');
    if (pmCountBadge) {
      pmCountBadge.textContent = `${pmList.length} saved`;
    }

    const pmListContainer = document.getElementById('prefPaymentMethodsList');
    if (pmListContainer) {
      pmListContainer.innerHTML = pmList.map(pm => {
        const isDef = (pm.id === defPmId);
        const last4Label = pm.last4 ? `<span class="font-mono text-[11px] bg-slate-100 text-slate-700 px-1.5 py-0.5 rounded border border-slate-200/80">•••• ${escapeHtml(pm.last4)}</span>` : '<span class="text-[10px] text-slate-400">Account / Cash</span>';
        const defaultBadge = isDef
          ? `<span class="text-[9px] font-bold px-1.5 py-0.5 rounded bg-emerald-50 text-emerald-700 border border-emerald-200">Default</span>`
          : `<button type="button" class="text-[10px] text-slate-400 hover:text-indigo-600 font-medium hover:underline set-default-pm-btn cursor-pointer" data-id="${pm.id}">Make Default</button>`;

        return `
          <div class="payment-method-item flex items-center justify-between gap-2 p-2 bg-slate-50/70 hover:bg-slate-50 border border-slate-200/80 rounded-xl transition-all cursor-grab active:cursor-grabbing group select-none" data-pm-id="${escapeHtml(pm.id)}">
            <div class="flex items-center gap-2 min-w-0">
              <div class="p-1 text-slate-300 group-hover:text-slate-500 pm-drag-handle transition-colors">
                <i data-lucide="grip-vertical" class="w-3.5 h-3.5"></i>
              </div>
              <div class="w-6 h-6 rounded-lg bg-white border border-slate-200/90 flex items-center justify-center text-slate-600 shrink-0">
                <i data-lucide="${pm.name.toLowerCase().includes('bank') ? 'landmark' : 'credit-card'}" class="w-3 h-3"></i>
              </div>
              <div class="min-w-0 flex items-center gap-1.5">
                <span class="text-xs font-semibold text-slate-900 truncate">${escapeHtml(pm.name)}</span>
                ${last4Label}
              </div>
            </div>
            <div class="flex items-center gap-2 shrink-0">
              ${defaultBadge}
              <button type="button" class="p-1 text-slate-300 hover:text-rose-600 rounded-lg hover:bg-rose-50 transition-colors cursor-pointer delete-pm-btn" data-id="${pm.id}" title="Remove payment method">
                <i data-lucide="trash-2" class="w-3 h-3"></i>
              </button>
            </div>
          </div>
        `;
      }).join('');

      pmListContainer.querySelectorAll('.set-default-pm-btn').forEach(btn => {
        btn.onclick = (e) => {
          e.stopPropagation();
          const id = btn.getAttribute('data-id');
          state.draftAppPrefs = state.draftAppPrefs || {};
          state.draftAppPrefs.defaultPaymentMethodId = id;
          state.draftAppPrefs.paymentMethods.forEach(pm => {
            pm.isDefault = (pm.id === id);
          });
          renderCustomizeSettings();
          refreshLiveSettingsPreview();
        };
      });

      pmListContainer.querySelectorAll('.delete-pm-btn').forEach(btn => {
        btn.onclick = (e) => {
          e.stopPropagation();
          const id = btn.getAttribute('data-id');
          if (pmList.length <= 1) {
            showToast('Minimum Method', 'You must keep at least 1 saved payment method.', 'alert');
            return;
          }
          state.draftAppPrefs = state.draftAppPrefs || {};
          state.draftAppPrefs.paymentMethods = state.draftAppPrefs.paymentMethods.filter(pm => pm.id !== id);
          if (state.draftAppPrefs.defaultPaymentMethodId === id && state.draftAppPrefs.paymentMethods[0]) {
            state.draftAppPrefs.defaultPaymentMethodId = state.draftAppPrefs.paymentMethods[0].id;
            state.draftAppPrefs.paymentMethods[0].isDefault = true;
          }
          renderCustomizeSettings();
          refreshLiveSettingsPreview();
        };
      });

      // Initialize Sortable for Payment Methods
      if (typeof Sortable !== 'undefined') {
        if (state.paymentMethodsSortableInstance) {
          state.paymentMethodsSortableInstance.destroy();
        }
        state.paymentMethodsSortableInstance = new Sortable(pmListContainer, {
          animation: 200,
          handle: '.pm-drag-handle, .payment-method-item',
          filter: 'button, input, a',
          preventOnFilter: false,
          ghostClass: 'opacity-40',
          chosenClass: 'bg-indigo-50/60',
          onEnd: () => {
            const currentDraft = state.draftAppPrefs?.paymentMethods || [];
            const newOrder = [];
            pmListContainer.querySelectorAll('[data-pm-id]').forEach(el => {
              const pid = el.getAttribute('data-pm-id');
              const found = currentDraft.find(p => p.id === pid);
              if (found) newOrder.push(found);
            });
            if (newOrder.length === currentDraft.length) {
              state.draftAppPrefs.paymentMethods = newOrder;
              // Also update the Default Payment Method dropdown order to match
              const defSelect = document.getElementById('prefDefaultPaymentMethodId');
              if (defSelect) {
                const curSelVal = defSelect.value;
                defSelect.innerHTML = newOrder.map(pm => 
                  `<option value="${escapeHtml(pm.id)}">${escapeHtml(pm.name)}${pm.last4 ? ` (•••• ${escapeHtml(pm.last4)})` : ''}</option>`
                ).join('');
                if (curSelVal) defSelect.value = curSelVal;
              }
              refreshLiveSettingsPreview();
            }
          }
        });
      }
    }

    // Add button handler
    const addPmBtn = document.getElementById('addNewPaymentMethodBtn');
    const newPmNameInp = document.getElementById('newPaymentMethodName');
    const newPmLast4Inp = document.getElementById('newPaymentMethodLast4');
    if (addPmBtn && newPmNameInp && !addPmBtn._hasListener) {
      addPmBtn._hasListener = true;
      addPmBtn.onclick = () => {
        const name = newPmNameInp.value.trim();
        const last4 = (newPmLast4Inp?.value || '').trim().slice(0, 4);
        if (!name) {
          showToast('Payment Name Required', 'Please enter a name like Visa, Amex, or Bank Account.', 'alert');
          return;
        }
        const newId = 'pm_' + Date.now();
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.paymentMethods = state.draftAppPrefs.paymentMethods || [];
        state.draftAppPrefs.paymentMethods.push({
          id: newId,
          name: name,
          last4: last4,
          isDefault: state.draftAppPrefs.paymentMethods.length === 0
        });
        if (state.draftAppPrefs.paymentMethods.length === 1) {
          state.draftAppPrefs.defaultPaymentMethodId = newId;
        }
        newPmNameInp.value = '';
        if (newPmLast4Inp) newPmLast4Inp.value = '';
        renderCustomizeSettings();
        refreshLiveSettingsPreview();
        showToast('Method Added', `Added ${name} to payment methods.`, 'success');
      };
    }

    // 7. Advance Alert Days
    const alertDaysSelect = document.getElementById('prefAdvanceAlertDays');
    if (alertDaysSelect) {
      alertDaysSelect.value = String(state.draftAppPrefs?.advanceAlertDays || 7);
      alertDaysSelect.onchange = (e) => {
        state.draftAppPrefs = state.draftAppPrefs || {};
        state.draftAppPrefs.advanceAlertDays = parseInt(e.target.value, 10) || 7;
        refreshLiveSettingsPreview();
      };
    }

    // Get current order from sidebarNavList or default keys
    const sidebarNavList = document.getElementById('sidebarNavList');
    let orderedIds = [];
    if (sidebarNavList) {
      sidebarNavList.querySelectorAll('[data-nav-id]').forEach(el => {
        const nid = el.getAttribute('data-nav-id');
        if (state.draftNavConfig[nid]) orderedIds.push(nid);
      });
    }
    // Preserve any in-progress input edits into draft before re-rendering
    const existingInputs = listEl.querySelectorAll('.nav-name-input');
    if (existingInputs.length) {
      existingInputs.forEach(inp => {
        const nid = inp.getAttribute('data-id');
        const val = inp.value.trim();
        if (state.draftNavConfig[nid] && val) {
          state.draftNavConfig[nid].name = val;
        }
      });
    }

    if (!orderedIds.length) {
      orderedIds = Object.keys(state.draftNavConfig);
    }

    listEl.innerHTML = orderedIds.map(id => {
      const item = state.draftNavConfig[id];
      if (!item) return '';

      const selectedColor = item.color || item.defaultColor || '#10b981';
      const swatchesHtml = CUSTOMIZE_PALETTE.map(c => {
        const isSelected = (item.color || '').toLowerCase() === c.hex.toLowerCase();
        const activeClass = isSelected 
          ? 'ring-2 ring-offset-2 ring-slate-800 scale-110 shadow-xs z-10' 
          : 'opacity-70 hover:opacity-100 hover:scale-105';
        return `
          <button type="button" class="w-3.5 h-3.5 rounded-full transition-all cursor-pointer ${activeClass}" 
                  style="background-color: ${c.hex};" 
                  data-nav-id="${id}" 
                  data-color="${c.hex}" 
                  title="${c.name} (${c.hex})">
          </button>
        `;
      }).join('');

      return `
        <div class="bg-white hover:bg-slate-50/70 border border-slate-200/80 rounded-xl px-3 py-2 flex items-center gap-2.5 transition-all shadow-2xs" data-customize-row="${id}">
          <!-- Visibility Toggle (Compact) -->
          <label class="relative inline-flex items-center cursor-pointer shrink-0" title="${item.visible ? 'Visible in sidebar' : 'Hidden from sidebar'}">
            <input type="checkbox" class="sr-only peer nav-visibility-toggle" data-id="${id}" ${item.visible ? 'checked' : ''}>
            <div class="w-7 h-4 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-3 peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-3 after:w-3 after:transition-all peer-checked:bg-emerald-500"></div>
          </label>

          <!-- Icon Selector Button (Sleek) -->
          <button type="button" class="w-7 h-7 rounded-lg bg-slate-50 hover:bg-slate-100 border border-slate-200/90 shadow-2xs flex items-center justify-center transition-all cursor-pointer shrink-0 open-icon-picker-btn" data-id="${id}" title="Click to choose icon">
            <i data-lucide="${item.icon || item.defaultIcon}" class="w-3.5 h-3.5" style="color: ${selectedColor};"></i>
          </button>

          <!-- Safe Name Input (Clean, compact) -->
          <div class="flex-1 min-w-0">
            <input type="text" class="w-full bg-slate-50/80 hover:bg-slate-50 focus:bg-white border border-transparent hover:border-slate-200 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 rounded-lg px-2.5 py-1 text-xs font-semibold text-slate-800 placeholder-slate-400 focus:outline-none transition-all nav-name-input" data-id="${id}" value="${escapeHtml(item.name || item.defaultName)}" placeholder="${item.defaultName}">
          </div>

          <!-- Color Swatches (Streamlined inline row) -->
          <div class="flex items-center gap-1.5 shrink-0 px-1 py-0.5">
            ${swatchesHtml}
          </div>

          <!-- Reset Item Button (Subtle) -->
          <button type="button" class="p-1 text-slate-300 hover:text-slate-600 rounded-lg hover:bg-slate-100 transition-colors shrink-0 reset-nav-item-btn" data-id="${id}" title="Reset ${item.defaultName} to default">
            <i data-lucide="rotate-ccw" class="w-3 h-3"></i>
          </button>
        </div>
      `;
    }).join('');

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    // Attach event listeners for each row in draft mode (no immediate save or apply)
    // 1. Visibility Toggles
    listEl.querySelectorAll('.nav-visibility-toggle').forEach(chk => {
      chk.addEventListener('change', (e) => {
        const id = e.target.getAttribute('data-id');
        const isChecked = e.target.checked;
        
        // Safety rule: at least 1 nav item must remain visible
        if (!isChecked) {
          const visibleCount = Object.values(state.draftNavConfig).filter(n => n.visible).length;
          if (visibleCount <= 1) {
            e.target.checked = true;
            showToast('Menu Minimum', 'At least one section must remain visible in the menu.', 'alert');
            return;
          }
        }

        if (state.draftNavConfig[id]) {
          state.draftNavConfig[id].visible = isChecked;
          applyNavConfig();
        }
      });
    });

    // 2. Safe Name Inputs
    listEl.querySelectorAll('.nav-name-input').forEach(input => {
      input.addEventListener('input', (e) => {
        const id = e.target.getAttribute('data-id');
        const val = e.target.value.trim();
        if (state.draftNavConfig[id]) {
          state.draftNavConfig[id].name = val || state.draftNavConfig[id].defaultName;
          applyNavConfig();
        }
      });
    });

    // 3. Color Swatches
    listEl.querySelectorAll('[data-color]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = btn.getAttribute('data-nav-id');
        const color = btn.getAttribute('data-color');
        if (state.draftNavConfig[id]) {
          state.draftNavConfig[id].color = color;
          renderCustomizeSettings();
          applyNavConfig();
        }
      });
    });

    // 4. Open Icon Picker
    listEl.querySelectorAll('.open-icon-picker-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = btn.getAttribute('data-id');
        openIconPicker(id);
      });
    });

    // 5. Reset Item Button
    listEl.querySelectorAll('.reset-nav-item-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = btn.getAttribute('data-id');
        if (DEFAULT_NAV_CONFIG[id] && state.draftNavConfig) {
          state.draftNavConfig[id] = { ...DEFAULT_NAV_CONFIG[id] };
          renderCustomizeSettings();
          applyNavConfig();
          showToast('Draft Reset', `Restored ${state.draftNavConfig[id].defaultName} in draft`, 'info');
        }
      });
    });
  }

  function openIconPicker(navId) {
    state.activeIconPickerNavId = navId;
    const modal = document.getElementById('iconPickerModal');
    const title = document.getElementById('iconPickerModalTitle');
    if (!modal) return;

    const navSource = state.draftNavConfig || state.navConfig;
    const item = navSource[navId];
    if (title && item) {
      title.textContent = `Choose Icon for "${item.name || item.defaultName}"`;
    }

    renderIconPickerGrid();
    modal.classList.remove('hidden');
    modal.classList.add('flex');
  }

  function closeIconPicker() {
    state.activeIconPickerNavId = null;
    const modal = document.getElementById('iconPickerModal');
    if (modal) {
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }
  }

  function renderIconPickerGrid() {
    const gridEl = document.getElementById('iconPickerGrid');
    if (!gridEl) return;

    const navSource = state.draftNavConfig || state.navConfig;
    const currentNav = state.activeIconPickerNavId ? navSource[state.activeIconPickerNavId] : null;
    const currentIcon = currentNav ? (currentNav.icon || currentNav.defaultIcon) : '';
    const currentColor = currentNav ? (currentNav.color || currentNav.defaultColor) : '#6366f1';

    gridEl.innerHTML = CURATED_ICONS.map(icon => {
      const isSelected = icon === currentIcon;
      const borderClass = isSelected 
        ? 'border-indigo-500 bg-indigo-50/70 text-indigo-700 ring-2 ring-indigo-500/20 shadow-xs' 
        : 'border-slate-200/80 bg-white hover:border-slate-300 hover:bg-slate-50 text-slate-700';

      return `
        <button type="button" class="flex items-center justify-center h-12 w-full rounded-2xl border ${borderClass} transition-all cursor-pointer group icon-select-btn" data-icon="${icon}" title="${icon}">
          <i data-lucide="${icon}" class="w-5 h-5 transition-transform group-hover:scale-115" style="color: ${isSelected ? currentColor : 'currentColor'};"></i>
        </button>
      `;
    }).join('');

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    gridEl.querySelectorAll('.icon-select-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const selectedIcon = btn.getAttribute('data-icon');
        if (state.activeIconPickerNavId && state.draftNavConfig && state.draftNavConfig[state.activeIconPickerNavId]) {
          state.draftNavConfig[state.activeIconPickerNavId].icon = selectedIcon;
          renderCustomizeSettings();
          applyNavConfig();
          closeIconPicker();
        }
      });
    });
  }

  function updateSettingsModalFooterUI() {
    const custPanel = document.getElementById('settingsPanelCustomize');
    const prefPanel = document.getElementById('settingsPanelPreferences');
    const isActionableTab = (custPanel && !custPanel.classList.contains('hidden')) || (prefPanel && !prefPanel.classList.contains('hidden'));
    const cancelBtn = document.getElementById('cancelCustomizeBtn');
    const saveBtn = document.getElementById('saveCustomizeBtn');
    const closeBtn = document.getElementById('closeSettingsGeneralBtn');

    if (isActionableTab) {
      if (cancelBtn) cancelBtn.classList.remove('hidden');
      if (saveBtn) saveBtn.classList.remove('hidden');
      if (closeBtn) closeBtn.classList.add('hidden');
    } else {
      if (cancelBtn) cancelBtn.classList.add('hidden');
      if (saveBtn) saveBtn.classList.add('hidden');
      if (closeBtn) closeBtn.classList.remove('hidden');
    }
  }

  function switchSettingsSubTab(tabName) {
    if (tabName === 'help') tabName = 'datavault';
    const prefBtn = document.getElementById('settingsTabPreferencesBtn');
    const custBtn = document.getElementById('settingsTabCustomizeBtn');
    const vaultBtn = document.getElementById('settingsTabDataVaultBtn');
    const helpBtn = document.getElementById('settingsTabHelpBtn');

    const prefPanel = document.getElementById('settingsPanelPreferences');
    const custPanel = document.getElementById('settingsPanelCustomize');
    const vaultPanel = document.getElementById('settingsPanelDataVault');
    const helpPanel = document.getElementById('settingsPanelHelp');

    const activeBtnClass = 'flex-1 py-1.5 px-2.5 rounded-xl bg-white text-slate-900 shadow-2xs transition-all flex items-center justify-center gap-1.5 cursor-pointer font-bold whitespace-nowrap';
    const inactiveBtnClass = 'flex-1 py-1.5 px-2.5 rounded-xl text-slate-600 hover:text-slate-900 transition-all flex items-center justify-center gap-1.5 cursor-pointer whitespace-nowrap';

    if (prefBtn) prefBtn.className = (tabName === 'preferences') ? activeBtnClass : inactiveBtnClass;
    if (custBtn) custBtn.className = (tabName === 'customize') ? activeBtnClass : inactiveBtnClass;
    if (vaultBtn) vaultBtn.className = (tabName === 'datavault') ? activeBtnClass : inactiveBtnClass;
    if (helpBtn) helpBtn.className = (tabName === 'help') ? activeBtnClass : inactiveBtnClass;

    if (prefPanel) prefPanel.classList.toggle('hidden', tabName !== 'preferences');
    if (custPanel) custPanel.classList.toggle('hidden', tabName !== 'customize');
    if (vaultPanel) vaultPanel.classList.toggle('hidden', tabName !== 'datavault');
    if (helpPanel) helpPanel.classList.toggle('hidden', tabName !== 'help');

    if (tabName === 'customize') {
      renderCustomizeSettings();
    } else if (tabName === 'datavault') {
      updateVaultSyncStatusUI();
      populateHelpVaultLiveStats();
    }
    updateSettingsModalFooterUI();
  }

  function updateVaultSyncStatusUI() {
    const statusBadge = document.getElementById('vaultSyncStatusBadge');
    const lastSyncLabel = document.getElementById('vaultLastSyncedLabel');
    if (!statusBadge && !lastSyncLabel) return;

    if (lastKnownVaultSyncTime) {
      try {
        const d = new Date(lastKnownVaultSyncTime);
        const timeStr = !isNaN(d.getTime()) ? d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : lastKnownVaultSyncTime;
        if (lastSyncLabel) lastSyncLabel.textContent = `Last Synced: Today at ${timeStr}`;
      } catch (e) {
        if (lastSyncLabel) lastSyncLabel.textContent = `Last Synced: ${lastKnownVaultSyncTime}`;
      }
    } else {
      if (lastSyncLabel) lastSyncLabel.textContent = 'Last Synced: Live local ledger active';
    }

    if (statusBadge) {
      statusBadge.innerHTML = `<span class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span><span>Connected</span>`;
      statusBadge.className = 'text-[10px] px-2.5 py-0.5 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200/80 font-bold flex items-center gap-1';
    }
  }

  function openSettingsModal(defaultTab = 'preferences') {
    const normalized = (defaultTab === 'help') ? 'datavault' : defaultTab;
    const tab = (typeof normalized === 'string' && ['preferences', 'customize', 'datavault'].includes(normalized))
      ? normalized
      : 'preferences';

    initCustomizeDraft();

    const apiKeyInput = document.getElementById('geminiApiKeyInput');
    if (apiKeyInput) apiKeyInput.value = state.geminiApiKey || '';

    // Snapshot pristine configuration to allow reverting if closed without saving
    state.settingsInitialSnapshot = {
      navConfig: JSON.parse(JSON.stringify(state.navConfig)),
      appPrefs: JSON.parse(JSON.stringify(state.appPrefs || {})),
      geminiApiKey: state.geminiApiKey || ''
    };

    updateVaultSyncStatusUI();
    populateHelpVaultLiveStats();
    switchSettingsSubTab(tab);
    renderCustomizeSettings();

    if (isDemoMode()) {
      const dataVaultPanel = document.getElementById('settingsPanelDataVault');
      if (dataVaultPanel) {
        const actionButtons = dataVaultPanel.querySelectorAll('button:not(.vault-info-trigger), input');
        actionButtons.forEach(btn => {
          btn.setAttribute('tabindex', '-1');
          btn.style.pointerEvents = 'none';
          btn.style.cursor = 'default';
          btn.style.opacity = '0.7';
        });
      }
    }

    document.getElementById('settingsModal').classList.remove('hidden');
    document.getElementById('settingsModal').classList.add('flex');
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function openSettingsCancelConfirmModal(onKeepEditing, onDiscard) {
    const confirmModal = document.getElementById('settingsCancelConfirmModal');
    if (!confirmModal) {
      if (confirm("Discard changes?")) onDiscard(); else if (typeof onKeepEditing === 'function') onKeepEditing();
      return;
    }
    const discardBtn = document.getElementById('settingsCancelConfirmYesBtn');
    const keepEditingBtn = document.getElementById('settingsCancelConfirmNoBtn');

    const handleBackdrop = (e) => {
      // Do not discard changes on accidental click outside the confirmation card
      if (e.target === confirmModal || !e.target.closest('#settingsCancelConfirmModal .modal-card')) {
        cleanup();
      }
    };

    const cleanup = () => {
      confirmModal.classList.add('hidden');
      confirmModal.classList.remove('flex');
      if (discardBtn) discardBtn.onclick = null;
      if (keepEditingBtn) keepEditingBtn.onclick = null;
      confirmModal.removeEventListener('click', handleBackdrop);
      window.removeEventListener('keydown', handleKey, true);
    };

    const handleKey = (e) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        cleanup(); // Esc closes the confirmation dialog without discarding changes (Keep editing)
      } else if (e.key === 'Enter') {
        e.preventDefault();
        e.stopPropagation();
        cleanup();
        onDiscard(); // Enter confirms Discard
      }
    };

    if (discardBtn) {
      discardBtn.onclick = (e) => {
        if (e) e.stopPropagation();
        cleanup();
        onDiscard(); // Discard changes
      };
    }
    if (keepEditingBtn) {
      keepEditingBtn.onclick = (e) => {
        if (e) e.stopPropagation();
        cleanup(); // Keep editing (just close confirmation modal)
      };
    }

    // Set timeout to attach backdrop click to prevent any event bleeding through
    setTimeout(() => {
      confirmModal.addEventListener('click', handleBackdrop);
    }, 50);
    window.addEventListener('keydown', handleKey, true);
    confirmModal.classList.remove('hidden');
    confirmModal.classList.add('flex');
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function closeSettingsModal(viaSave = false) {
    const isSaved = (viaSave === true);
    const modal = document.getElementById('settingsModal');
    if (!modal || modal.classList.contains('hidden')) return;

    const finalizeClose = () => {
      state.draftNavConfig = null;
      state.draftAppPrefs = null;
      state.settingsInitialSnapshot = null;
      delete state.draftResetSidebarOrder;
      closeIconPicker();
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    };

    // If not closed via Save button or Enter, check if there are changes and prompt user
    if (!isSaved && state.settingsInitialSnapshot) {
      const snapNav = JSON.stringify(state.settingsInitialSnapshot.navConfig);
      const snapPrefs = JSON.stringify(state.settingsInitialSnapshot.appPrefs);
      const curNav = JSON.stringify(state.draftNavConfig || state.navConfig);
      const curPrefs = JSON.stringify(state.draftAppPrefs || state.appPrefs || {});

      const curApiKey = (document.getElementById('geminiApiKeyInput')?.value || '').trim();
      const snapApiKey = (state.settingsInitialSnapshot.geminiApiKey || '').trim();

      const isDirty = (snapNav !== curNav || snapPrefs !== curPrefs || curApiKey !== snapApiKey || !!state.draftResetSidebarOrder);

      if (isDirty) {
        openSettingsCancelConfirmModal(
          // Option YES: User confirms "Save changes?" -> save & apply permanently
          () => {
            if (typeof window._ftHandleSaveCustomizations === 'function') {
              window._ftHandleSaveCustomizations();
            } else {
              finalizeClose();
            }
          },
          // Option CANCEL: User chooses Cancel -> discard & revert back to how it was
          () => {
            state.navConfig = JSON.parse(JSON.stringify(state.settingsInitialSnapshot.navConfig));
            state.appPrefs = JSON.parse(JSON.stringify(state.settingsInitialSnapshot.appPrefs));
            state.draftNavConfig = null;
            state.draftAppPrefs = null;
            delete state.draftResetSidebarOrder;
            const apiKeyInput = document.getElementById('geminiApiKeyInput');
            if (apiKeyInput) {
              apiKeyInput.value = state.settingsInitialSnapshot.geminiApiKey || '';
            }
            refreshLiveSettingsPreview();
            finalizeClose();
          }
        );
        return;
      } else {
        // Revert any staged draft state back to clean snapshot
        state.navConfig = JSON.parse(JSON.stringify(state.settingsInitialSnapshot.navConfig));
        state.appPrefs = JSON.parse(JSON.stringify(state.settingsInitialSnapshot.appPrefs));
        state.draftNavConfig = null;
        state.draftAppPrefs = null;
        delete state.draftResetSidebarOrder;
        refreshLiveSettingsPreview();
        finalizeClose();
        return;
      }
    }

    finalizeClose();
  }

