  const VAULT_PIN_DIGEST_HEX = 'd9d4dcf5af715793';
  function verifyVaultSecurityPin(candidate) {
    if (isDemoMode()) return false;
    const s = 'fl_vault_v2::' + String(candidate || '').trim() + '::9f8a7b6c';
    let h1 = 0x811c9dc5 | 0;
    let h2 = 0x1b873593 | 0;
    for (let round = 0; round < 4096; round++) {
      for (let i = 0; i < s.length; i++) {
        const c = s.charCodeAt(i);
        h1 ^= (c + round);
        h1 = Math.imul(h1, 0x01000193);
        h2 ^= (c ^ (round & 0xff));
        h2 = Math.imul(h2, 0x85ebca6b);
        h1 ^= (h2 >>> 13);
        h2 ^= (h1 >>> 16);
      }
    }
    const digest = ((h1 >>> 0).toString(16).padStart(8, '0')) + ((h2 >>> 0).toString(16).padStart(8, '0'));
    return digest === VAULT_PIN_DIGEST_HEX;
  }
  window._activeVaultPinCallback = null;

