  function downloadManualVaultBackup() {
    if (isDemoMode()) return;
    try {
      const payload = {
        _exported_at: new Date().toISOString(),
        _restore_epoch: localStorage.getItem('finland_restore_epoch') || new Date().toISOString()
      };
      Object.values(STORAGE_KEYS).forEach(k => {
        if (typeof k === 'string' && k.startsWith('finland_')) {
          const val = localStorage.getItem(k);
          if (val !== null && val !== undefined) {
            payload[k] = val;
          }
        }
      });
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      const dateStr = new Date().toISOString().slice(0, 10);
      a.href = url;
      a.download = `finland_vault_backup_${dateStr}.json`;
      document.body.appendChild(a);
      a.click();
      setTimeout(() => {
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }, 200);
      if (typeof showToast === 'function') {
        showToast('Downloaded full Finland backup (.json)');
      }
    } catch (e) {}
  }

