  function exportToCsv() {
    if (isDemoMode()) return;
    const filtered = getFilteredExpenses();
    if (filtered.length === 0) {
      alert('No expenses found to export.');
      return;
    }

    const headers = ['ID', 'Date', 'Title', 'Category', 'Is Subscription', 'Has Receipt File', 'Original Amount', 'Currency', 'USD Equivalent', 'EUR Equivalent', 'ILS Equivalent', 'Payment Method', 'Notes'];
    
    const rows = filtered.map(item => {
      const tri = getTriCurrencyValues(item.amount, item.currency);
      return [
        `"${item.id}"`,
        `"${item.date}"`,
        `"${(item.title || '').replace(/"/g, '""')}"`,
        `"${item.category}"`,
        item.isSubscription ? '"Yes"' : '"No"',
        item.hasAttachment ? '"Yes"' : '"No"',
        item.amount.toFixed(2),
        `"${item.currency}"`,
        tri.USD.toFixed(2),
        tri.EUR.toFixed(2),
        tri.ILS.toFixed(2),
        `"${(item.paymentMethod || '').replace(/"/g, '""')}"`,
        `"${(item.notes || '').replace(/"/g, '""')}"`
      ].join(',');
    });

    const csvContent = [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `finance_tracker_expenses_${state.selectedMonth}_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

