    document.getElementById('expenseForm').addEventListener('submit', (e) => {
      e.preventDefault();
      const transType = document.getElementById('transactionType')?.value || 'expense';
      const id = document.getElementById('editExpenseId').value;
      const title = document.getElementById('expenseTitle').value.trim();
      const amount = parseFloat(document.getElementById('expenseAmount').value);
      const currency = document.getElementById('expenseCurrency').value;
      const category = document.getElementById('expenseCategory').value;
      const date = document.getElementById('expenseDate').value;
      const isBusiness = document.getElementById('expenseIsBusiness').checked;
      const isSubscription = document.getElementById('expenseIsSubscription').checked;
      const recurringType = isSubscription ? (document.getElementById('expenseRecurringType')?.value || 'subscription') : undefined;
      const billingCycle = isSubscription ? (document.getElementById('expenseBillingCycle')?.value || 'monthly') : 'monthly';
      const paymentMethod = document.getElementById('expensePaymentMethod').value;
      const cardLast4 = document.getElementById('expenseCardLast4').value.trim();
      const notes = document.getElementById('expenseNotes').value.trim();

      // Whenever an expense is recurring / in Monthly Expenses, automatically categorize it as Monthly Expenses
      const finalCategory = isSubscription ? 'Monthly Expenses' : category;

      if (!title || isNaN(amount) || amount <= 0 || !date) {
        alert('Please fill in all required fields with valid values.');
        return;
      }

      if (transType === 'income') {
        if (!state.budget) state.budget = {};
        if (!Array.isArray(state.budget.incomes)) state.budget.incomes = [];

        if (id) {
          const idx = state.budget.incomes.findIndex(i => i.id === id);
          if (idx !== -1) {
            state.budget.incomes[idx] = {
              ...state.budget.incomes[idx],
              title,
              amount,
              currency,
              date,
              method: paymentMethod,
              notes
            };
          } else {
            state.budget.incomes.unshift({
              id,
              title,
              amount,
              currency,
              date,
              method: paymentMethod,
              notes
            });
          }
        } else {
          state.budget.incomes.unshift({
            id: 'inc_' + Date.now(),
            title,
            amount,
            currency,
            date,
            method: paymentMethod,
            notes: notes || 'Direct received payment'
          });
        }

        saveBudget();
        renderDashboard();
        closeExpenseModal();
        showToast('Payment Recorded! 💰', `+${formatMoney(amount, currency)} from ${title} saved!`, 'success');
        return;
      }

      let hasAttachment = undefined;
      let attachmentType = undefined;
      let attachmentFileName = undefined;

      const expenseId = id || ('exp_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4));

      if (!id && state.pendingModalAttachment) {
        hasAttachment = true;
        attachmentType = state.pendingModalAttachment.type;
        attachmentFileName = state.pendingModalAttachment.fileName;
        saveReceiptAttachment(expenseId, state.pendingModalAttachment);
        state.pendingModalAttachment = null;
      }

      addOrUpdateExpense({
        id: expenseId,
        title,
        amount,
        currency,
        category: finalCategory,
        date,
        isBusiness,
        isSubscription,
        recurringType,
        billingCycle,
        paymentMethod,
        cardLast4,
        notes,
        hasAttachment,
        attachmentType,
        attachmentFileName,
        noReceiptNeeded: !isBusiness && !!state.modalNoReceiptNeeded
      });

      closeExpenseModal();
      showToast('Expense Saved', `${title} (${formatMoney(amount, currency)}) recorded!`, 'success');
    });

