  function saveNeedsToPayCardOrder() {
    try {
      const debtsList = document.getElementById('standaloneDebtsList');
      if (!debtsList) return;
      const orderedIds = [];
      debtsList.querySelectorAll('[data-id]').forEach(el => {
        orderedIds.push(el.getAttribute('data-id'));
      });
      if (orderedIds.length > 0 && Array.isArray(state.debts)) {
        state.debts.sort((a, b) => {
          const idxA = orderedIds.indexOf(a.id);
          const idxB = orderedIds.indexOf(b.id);
          if (idxA === -1 && idxB === -1) return 0;
          if (idxA === -1) return 1;
          if (idxB === -1) return -1;
          return idxA - idxB;
        });
        saveDebts();
      }
    } catch (e) {
      console.warn('Could not save debts card order:', e);
    }
  }

