  function initWishlistSortables() {
    if (typeof Sortable === 'undefined') return;

    // Destroy existing instances
    (state.wishlistSortableInstances || []).forEach(inst => inst && inst.destroy());
    state.wishlistSortableInstances = [];

    // 1. Wishlist Metric boxes reordering
    const metricsBar = document.getElementById('wishlistMetricsBar');
    if (metricsBar) {
      const wbInst = new Sortable(metricsBar, {
        animation: 200,
        filter: 'button, input, select, textarea, a',
        preventOnFilter: false,
        ghostClass: 'sortable-ghost',
        chosenClass: 'sortable-chosen',
        dragClass: 'sortable-drag',
        onEnd: () => {
          saveWishlistLayout();
        }
      });
      state.wishlistSortableInstances.push(wbInst);
    }

    // 2. Wishlist item cards reordering for Subscriptions
    const subsGrid = document.getElementById('wishlistSubsGrid');
    if (subsGrid) {
      const wsInst = new Sortable(subsGrid, {
        animation: 200,
        draggable: '.wishlist-card',
        filter: 'button, input, select, textarea, a',
        preventOnFilter: false,
        ghostClass: 'sortable-ghost',
        chosenClass: 'sortable-chosen',
        dragClass: 'sortable-drag',
        onEnd: () => {
          saveWishlistCardOrder();
        }
      });
      state.wishlistSortableInstances.push(wsInst);
    }

    // 3. Wishlist item cards reordering for Items & Services
    const otherGrid = document.getElementById('wishlistOtherGrid');
    if (otherGrid) {
      const woInst = new Sortable(otherGrid, {
        animation: 200,
        draggable: '.wishlist-card',
        filter: 'button, input, select, textarea, a',
        preventOnFilter: false,
        ghostClass: 'sortable-ghost',
        chosenClass: 'sortable-chosen',
        dragClass: 'sortable-drag',
        onEnd: () => {
          saveWishlistCardOrder();
        }
      });
      state.wishlistSortableInstances.push(woInst);
    }

    applySavedWishlistLayout();
  }

