  const CATEGORY_EMOJI_MAP = {
    'subscriptions': '📱',
    'utilities': '💡',
    'housing': '🏠',
    'groceries': '🛒',
    'dining': '🍽️',
    'shopping': '🛍️',
    'transport': '🚗',
    'transportation': '🚗',
    'entertainment': '🎟️',
    'health': '💊',
    'medical': '💊',
    'travel': '✈️',
    'personal': '✨',
    'education': '📚',
    'fitness': '🏋️',
    'gym': '🏋️',
    'coffee': '☕',
    'work': '💼',
    'gifts': '🎁',
    'savings': '🐷',
    'tech': '💻',
    'phone': '📱',
    'pets': '🐾',
    'other': '📦'
  };

  function getCategoryEmoji(category) {
    if (!category) return '🏷️';
    const clean = category.toLowerCase().trim();
    if (CATEGORY_EMOJI_MAP[clean]) return CATEGORY_EMOJI_MAP[clean];
    for (const [k, emoji] of Object.entries(CATEGORY_EMOJI_MAP)) {
      if (clean.includes(k)) return emoji;
    }
    return '🏷️';
  }

  function getAllCategoriesList() {
    const fixed = [
      { name: 'Monthly Expenses', emoji: '🗓️', label: 'Monthly Expenses' },
      { name: 'Utilities', emoji: '💡', label: 'Bills & Utilities' }
    ];

    const budgetCats = (state.budget && Array.isArray(state.budget.categories)) 
      ? state.budget.categories 
      : DEFAULT_BUDGET_CATEGORIES;

    const list = [...fixed];
    const seen = new Set(fixed.map(f => f.name.toLowerCase()));

    budgetCats.forEach(c => {
      if (!c || !c.name) return;
      const lower = c.name.toLowerCase();
      if (!seen.has(lower)) {
        seen.add(lower);
        list.push({
          name: c.name,
          emoji: getCategoryEmoji(c.name),
          label: c.name,
          color: c.color,
          icon: c.icon
        });
      }
    });

    // Also include any custom category currently recorded in state.expenses
    (state.expenses || []).forEach(e => {
      if (!e || !e.category) return;
      const lower = e.category.toLowerCase().trim();
      if (lower === 'unassigned' || lower === 'uncategorized') return;
      if (!seen.has(lower)) {
        seen.add(lower);
        list.push({
          name: e.category,
          emoji: getCategoryEmoji(e.category),
          label: e.category
        });
      }
    });

    return list;
  }

  function syncCategoryDropdowns() {
    const all = getAllCategoriesList();

    // 1. Expense Modal Category Select (#expenseCategory)
    const expSelect = document.getElementById('expenseCategory');
    if (expSelect) {
      const curVal = expSelect.value;
      expSelect.innerHTML = all.map(c => 
        `<option value="${escapeHtml(c.name)}">${escapeHtml(c.label || c.name)}</option>`
      ).join('');
      if (curVal && all.some(c => c.name.toLowerCase() === curVal.toLowerCase())) {
        expSelect.value = curVal;
      }
    }

    // Sync Payment Methods in Expense & Subscription Modals
    syncPaymentMethodDropdowns();
    initQuickAddPaymentMethodModal();

    // 2. Transactions Filter Category Select (#filterCategory)
    const filterSelect = document.getElementById('filterCategory');
    if (filterSelect) {
      const curVal = filterSelect.value || 'ALL';
      let optionsHtml = `
        <option value="ALL">All Categories</option>
        <option value="Income">Received Payments</option>
      `;
      all.forEach(c => {
        // Exclude Monthly Expenses and Housing from the filter category dropdown
        if (c.name === 'Monthly Expenses' || c.name === 'Housing') return;
        const displayLabel = (c.name === 'Utilities') ? 'Bills & Utilities' : (c.label || c.name);
        optionsHtml += `<option value="${escapeHtml(c.name)}">${escapeHtml(displayLabel)}</option>`;
        if (c.name === 'Utilities') {
          optionsHtml += `<option value="Subscriptions">Subscriptions</option>`;
        }
      });
      filterSelect.innerHTML = optionsHtml;
      if (curVal) filterSelect.value = curVal;
    }

    // 3. Budget Log Modal Custom Category Dropdown with Lucide Icons
    renderBudgetLogCustomDropdown();
  }

  function renderBudgetLogCustomDropdown() {
    const menu = document.getElementById('budgetLogCategoryDropdownMenu');
    const nameEl = document.getElementById('budgetLogSelectedCatName');
    const iconBox = document.getElementById('budgetLogSelectedCatIconBox');
    const iconEl = document.getElementById('budgetLogSelectedCatIcon');
    const hiddenSelect = document.getElementById('budgetLogCategorySelect');
    if (!menu) return;

    const activeCat = state.activeBudgetLogCat || 'Groceries';
    const budgetCats = (state.budget && Array.isArray(state.budget.categories) && state.budget.categories.length > 0)
      ? state.budget.categories
      : DEFAULT_BUDGET_CATEGORIES;

    const currentObj = budgetCats.find(c => c.name.toLowerCase() === activeCat.toLowerCase()) || budgetCats[0];
    const curColor = (currentObj && currentObj.color) || getCategoryColor(activeCat);
    const curIcon = (currentObj && currentObj.icon) || getCategoryLucideIcon(activeCat);

    if (nameEl) nameEl.textContent = (currentObj && currentObj.name) || activeCat;
    if (iconBox) {
      iconBox.style.color = curColor;
    }
    if (iconEl) {
      iconEl.setAttribute('data-lucide', curIcon);
    }
    if (hiddenSelect) {
      hiddenSelect.innerHTML = budgetCats.map(c => 
        `<option value="${escapeHtml(c.name)}">${escapeHtml(c.name)}</option>`
      ).join('');
      hiddenSelect.value = (currentObj && currentObj.name) || activeCat;
    }

    menu.innerHTML = budgetCats.map(c => {
      const isSelected = c.name.toLowerCase() === activeCat.toLowerCase();
      const color = c.color || getCategoryColor(c.name);
      const icon = c.icon || getCategoryLucideIcon(c.name);
      return `
        <button type="button" class="budget-log-cat-opt w-full flex items-center justify-between px-2.5 py-1.5 rounded-xl hover:bg-slate-50 transition-colors text-left cursor-pointer group ${isSelected ? 'bg-indigo-50/70 text-indigo-950 font-bold' : 'text-slate-700 font-medium'}" data-cat="${escapeHtml(c.name)}">
          <div class="flex items-center gap-2.5 min-w-0">
            <div class="w-6 h-6 rounded-lg flex items-center justify-center shrink-0 shadow-2xs border border-black/5 transition-transform group-hover:scale-105" style="background-color: ${color}18; color: ${color};">
              <i data-lucide="${icon}" class="w-3.5 h-3.5"></i>
            </div>
            <span class="text-xs truncate">${escapeHtml(c.name)}</span>
          </div>
          ${isSelected ? '<i data-lucide="check" class="w-3.5 h-3.5 text-indigo-600 shrink-0"></i>' : ''}
        </button>
      `;
    }).join('');

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function syncPaymentMethodDropdowns() {
    const pmList = (state.appPrefs?.paymentMethods && Array.isArray(state.appPrefs.paymentMethods) && state.appPrefs.paymentMethods.length > 0)
      ? state.appPrefs.paymentMethods
      : DEFAULT_APP_PREFS.paymentMethods;

    const buildOptions = (currentVal) => {
      let html = '';
      pmList.forEach(pm => {
        const last4Text = pm.last4 ? ` (•••• ${escapeHtml(pm.last4)})` : '';
        html += `<option value="${escapeHtml(pm.name)}" data-last4="${escapeHtml(pm.last4 || '')}">${escapeHtml(pm.name)}${last4Text}</option>`;
      });
      // Fallback standard options (excluding specific card brands like Visa, Mastercard, Amex)
      const standardMethods = ['Bank Transfer', 'Cash', 'PayPal', 'Bit / PayBox', 'Other'];
      standardMethods.forEach(sm => {
        if (!pmList.some(p => p.name.toLowerCase() === sm.toLowerCase())) {
          html += `<option value="${escapeHtml(sm)}" data-last4="">${escapeHtml(sm)}</option>`;
        }
      });
      // Prompt option at the end of the list to quickly add a new method
      html += `<option value="__ADD_NEW__" class="font-bold text-indigo-600">➕ Add New Payment Method...</option>`;
      return html;
    };

    // 1. Expense modal payment method
    const expPmSelect = document.getElementById('expensePaymentMethod');
    if (expPmSelect) {
      const curVal = expPmSelect.value;
      expPmSelect.innerHTML = buildOptions(curVal);
      if (curVal && curVal !== '__ADD_NEW__') expPmSelect.value = curVal;

      if (!expPmSelect._pmListenerAttached) {
        expPmSelect._pmListenerAttached = true;
        expPmSelect.addEventListener('change', () => {
          if (expPmSelect.value === '__ADD_NEW__') {
            openQuickAddPaymentMethodModal('expense');
            return;
          }
          expPmSelect._lastSelectedVal = expPmSelect.value;
          const selectedOpt = expPmSelect.options[expPmSelect.selectedIndex];
          const last4Input = document.getElementById('expenseCardLast4');
          if (last4Input && selectedOpt) {
            const dataLast4 = selectedOpt.getAttribute('data-last4') || '';
            last4Input.value = dataLast4;
          }
        });
      }
      expPmSelect._lastSelectedVal = expPmSelect.value;
    }

    // 2. Subscription modal payment method
    const subPmSelect = document.getElementById('subFormPaymentMethod');
    if (subPmSelect) {
      const curVal = subPmSelect.value;
      subPmSelect.innerHTML = buildOptions(curVal);
      if (curVal && curVal !== '__ADD_NEW__') subPmSelect.value = curVal;

      if (!subPmSelect._pmListenerAttached) {
        subPmSelect._pmListenerAttached = true;
        subPmSelect.addEventListener('change', () => {
          if (subPmSelect.value === '__ADD_NEW__') {
            openQuickAddPaymentMethodModal('subscription');
            return;
          }
          subPmSelect._lastSelectedVal = subPmSelect.value;
          const selectedOpt = subPmSelect.options[subPmSelect.selectedIndex];
          const last4Input = document.getElementById('subFormCardLast4');
          if (last4Input && selectedOpt) {
            const dataLast4 = selectedOpt.getAttribute('data-last4') || '';
            last4Input.value = dataLast4;
          }
        });
      }
      subPmSelect._lastSelectedVal = subPmSelect.value;
    }
  }

  let quickAddPmTargetContext = null;

  function openQuickAddPaymentMethodModal(target = 'expense') {
    quickAddPmTargetContext = target;
    const modal = document.getElementById('quickAddPaymentMethodModal');
    if (!modal) return;
    const nameInp = document.getElementById('quickAddPmName');
    const last4Inp = document.getElementById('quickAddPmLast4');
    if (nameInp) nameInp.value = '';
    if (last4Inp) last4Inp.value = '';
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    if (nameInp) nameInp.focus();
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function closeQuickAddPaymentMethodModal() {
    const modal = document.getElementById('quickAddPaymentMethodModal');
    if (!modal) return;
    modal.classList.add('hidden');
    modal.classList.remove('flex');

    // Revert target select from '__ADD_NEW__' to previous valid selection if user cancelled
    if (quickAddPmTargetContext === 'expense') {
      const expSelect = document.getElementById('expensePaymentMethod');
      if (expSelect && expSelect.value === '__ADD_NEW__') {
        expSelect.value = expSelect._lastSelectedVal || expSelect.options[0]?.value || '';
      }
    } else if (quickAddPmTargetContext === 'subscription') {
      const subSelect = document.getElementById('subFormPaymentMethod');
      if (subSelect && subSelect.value === '__ADD_NEW__') {
        subSelect.value = subSelect._lastSelectedVal || subSelect.options[0]?.value || '';
      }
    }
    quickAddPmTargetContext = null;
  }

  function initQuickAddPaymentMethodModal() {
    const modal = document.getElementById('quickAddPaymentMethodModal');
    const closeBtn = document.getElementById('closeQuickAddPmModalBtn');
    const cancelBtn = document.getElementById('cancelQuickAddPmBtn');
    const form = document.getElementById('quickAddPmForm');

    if (closeBtn) closeBtn.onclick = closeQuickAddPaymentMethodModal;
    if (cancelBtn) cancelBtn.onclick = closeQuickAddPaymentMethodModal;
    if (modal) {
      modal.onclick = (e) => {
        if (e.target === modal) closeQuickAddPaymentMethodModal();
      };
    }

    if (form && !form._hasSubmitListener) {
      form._hasSubmitListener = true;
      form.onsubmit = (e) => {
        e.preventDefault();
        const nameInp = document.getElementById('quickAddPmName');
        const last4Inp = document.getElementById('quickAddPmLast4');
        const name = (nameInp?.value || '').trim();
        const last4 = (last4Inp?.value || '').trim().slice(0, 4);

        if (!name) {
          alert('Please enter a payment method name.');
          return;
        }

        const newPm = {
          id: 'pm_' + Date.now(),
          name: name,
          last4: last4,
          isDefault: false
        };

        if (!state.appPrefs) state.appPrefs = { ...DEFAULT_APP_PREFS };
        if (!Array.isArray(state.appPrefs.paymentMethods)) state.appPrefs.paymentMethods = [];
        state.appPrefs.paymentMethods.push(newPm);

        // Save preferences to local storage and sync
        try {
          localStorage.setItem(STORAGE_KEYS.APP_PREFS, JSON.stringify(state.appPrefs));
          triggerSafeVaultPush();
        } catch (err) {}

        // Re-sync all dropdowns
        syncPaymentMethodDropdowns();

        // Select the newly added payment method in the active modal
        if (quickAddPmTargetContext === 'expense') {
          const expSelect = document.getElementById('expensePaymentMethod');
          if (expSelect) {
            expSelect.value = newPm.name;
            expSelect._lastSelectedVal = newPm.name;
          }
          const expLast4 = document.getElementById('expenseCardLast4');
          if (expLast4) expLast4.value = newPm.last4;
        } else if (quickAddPmTargetContext === 'subscription') {
          const subSelect = document.getElementById('subFormPaymentMethod');
          if (subSelect) {
            subSelect.value = newPm.name;
            subSelect._lastSelectedVal = newPm.name;
          }
          const subLast4 = document.getElementById('subFormCardLast4');
          if (subLast4) subLast4.value = newPm.last4;
        }

        showToast('Payment Method Saved', `Added "${name}${last4 ? ' (•••• ' + last4 + ')' : ''}" to your payment methods.`, 'success');
        modal.classList.add('hidden');
        modal.classList.remove('flex');
        quickAddPmTargetContext = null;
      };
    }
  }

  function normalizeExpenseCategories() {
    let modified = false;
    (state.expenses || []).forEach(exp => {
      if (exp.isSubscription || exp.subscriptionId || exp.generatedFromSubId || exp.category === 'Subscriptions') {
        if (exp.category !== 'Monthly Expenses') {
          exp.category = 'Monthly Expenses';
          modified = true;
        }
      } else if (exp.category === 'Dining & Food') {
        exp.category = 'Dining';
        modified = true;
      } else if (exp.category === 'Transportation') {
        exp.category = 'Transport';
        modified = true;
      } else if (exp.category === 'Health & Medical') {
        exp.category = 'Health';
        modified = true;
      }
    });
    if (modified) {
      saveExpenses();
    }
  }

  function openBudgetCategoryLogModal(targetCat) {
    if (!targetCat) {
      const cats = (state.budget && Array.isArray(state.budget.categories) && state.budget.categories.length > 0)
        ? state.budget.categories
        : DEFAULT_BUDGET_CATEGORIES;
      targetCat = cats[0].name;
    }

    state.activeBudgetLogCat = targetCat;
    state.budgetLogFilter = 'all';
    state.budgetLogSearchQuery = '';

    syncCategoryDropdowns();

    const searchInput = document.getElementById('budgetLogSearchInput');
    if (searchInput) searchInput.value = '';

    renderBudgetCategoryLogModalList();

    const modal = document.getElementById('budgetCategoryLogModal');
    if (modal) {
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function closeBudgetCategoryLogModal() {
    const modal = document.getElementById('budgetCategoryLogModal');
    if (modal) {
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }
    state.activeBudgetLogCat = null;
    renderBudgetView();
  }

  function renderBudgetCategoryLogModalList() {
    const modal = document.getElementById('budgetCategoryLogModal');
    if (!modal) return;

    const cat = state.activeBudgetLogCat || 'Groceries';
    const cur = state.displayCurrency;
    const monthKey = getBudgetMonthKey();
    const isAllTime = (!monthKey || monthKey === 'ALL' || monthKey === 'all');

    // 1. Header info
    const titleEl = document.getElementById('budgetLogModalTitle');
    const subtitleEl = document.getElementById('budgetLogModalSubtitle');
    const catAvatar = document.getElementById('budgetLogCatAvatar');
    const catIcon = document.getElementById('budgetLogCatIcon');
    const catSelect = document.getElementById('budgetLogCategorySelect');

    const catObj = (state.budget && Array.isArray(state.budget.categories))
      ? state.budget.categories.find(c => c.name.toLowerCase() === cat.toLowerCase())
      : null;
    const catColor = (catObj && catObj.color) || getCategoryColor(cat);
    const catIconName = (catObj && catObj.icon) || getCategoryLucideIcon(cat);

    if (catAvatar) {
      catAvatar.style.backgroundColor = `${catColor}18`;
      catAvatar.style.color = catColor;
      catAvatar.style.borderColor = `${catColor}40`;
    }
    if (catIcon) {
      catIcon.setAttribute('data-lucide', catIconName);
    }

    renderBudgetLogCustomDropdown();

    // 2. Fetch expenses for this month
    const monthExpenses = (state.expenses || []).filter(exp => {
      if (exp.isSubscription) return false;
      if (exp.isIncome || exp.type === 'income' || exp.category === 'Income') return false;
      if (!exp.date) return false;
      if (isAllTime) return true;
      return exp.date.startsWith(monthKey);
    });

    // Helper: is this expense unassigned?
    // Unassigned means it has no category, or category is 'unassigned', 'uncategorized', or empty
    const isUnassignedExpense = (e) => {
      const c = (e.category || '').trim().toLowerCase();
      return !c || c === 'unassigned' || c === 'uncategorized';
    };

    // Helper: is this expense logged in this specific category?
    const isThisCatExpense = (e) => {
      const c = (e.category || '').trim().toLowerCase();
      return c === cat.toLowerCase().trim();
    };

    // 1. inCatExpenses: expenses currently logged in THIS category
    const inCatExpenses = monthExpenses.filter(isThisCatExpense);

    // 2. availableExpenses: expenses that are unassigned and available to be logged
    const availableExpenses = monthExpenses.filter(isUnassignedExpense);

    // Visible: logged in this category + available unassigned (strictly excludes expenses logged in other categories!)
    const visibleExpenses = [...inCatExpenses, ...availableExpenses];

    const inCatCount = inCatExpenses.length;
    const availableCount = availableExpenses.length;
    const totalVisibleCount = visibleExpenses.length;

    const totalCatSpent = inCatExpenses.reduce((sum, e) => {
      return sum + convertCurrency(parseFloat(e.amount) || 0, e.currency, cur);
    }, 0);

    if (subtitleEl) {
      const monthDisplay = isAllTime 
        ? 'All Time' 
        : new Date(monthKey + '-01T00:00:00').toLocaleDateString(undefined, { month: 'long', year: 'numeric' });
      subtitleEl.textContent = `${monthDisplay} • ${inCatCount} ${inCatCount === 1 ? 'purchase' : 'purchases'} logged • ${availableCount} available`;
    }

    // Update filter pills text
    const filterAllBtn = document.getElementById('budgetLogFilterAllBtn');
    const filterLoggedBtn = document.getElementById('budgetLogFilterLoggedBtn');
    const filterOtherBtn = document.getElementById('budgetLogFilterOtherBtn');
    if (filterAllBtn) filterAllBtn.textContent = `All (${totalVisibleCount})`;
    if (filterLoggedBtn) filterLoggedBtn.textContent = `Logged (${inCatCount})`;
    if (filterOtherBtn) filterOtherBtn.textContent = `Available (${availableCount})`;

    // Update active filter pill styling
    const currentFilter = state.budgetLogFilter || 'all';
    [
      { btn: filterAllBtn, id: 'all' },
      { btn: filterLoggedBtn, id: 'logged' },
      { btn: filterOtherBtn, id: 'other' }
    ].forEach(item => {
      if (!item.btn) return;
      if (item.id === currentFilter) {
        item.btn.className = 'budget-log-filter-pill px-2.5 py-1 rounded-lg font-semibold bg-white text-slate-900 shadow-2xs transition-all cursor-pointer';
      } else {
        item.btn.className = 'budget-log-filter-pill px-2.5 py-1 rounded-lg font-medium text-slate-600 hover:text-slate-900 transition-all cursor-pointer';
      }
    });

    // Update footer summary
    const footerSummary = document.getElementById('budgetLogFooterSummary');
    if (footerSummary) {
      let summaryText = `${inCatCount} ${inCatCount === 1 ? 'purchase' : 'purchases'} • ${formatMoney(totalCatSpent, cur)} logged to ${cat}`;
      if (availableCount > 0) {
        summaryText += ` • ${availableCount} available to log`;
      }
      footerSummary.textContent = summaryText;
    }

    // 3. Filter list by search query and filter mode
    const q = (state.budgetLogSearchQuery || '').toLowerCase().trim();
    let displayList = visibleExpenses.filter(e => {
      const isLogged = isThisCatExpense(e);

      if (currentFilter === 'logged' && !isLogged) return false;
      if ((currentFilter === 'other' || currentFilter === 'available') && isLogged) return false;

      if (q) {
        const titleMatch = (e.title || '').toLowerCase().includes(q);
        const notesMatch = (e.notes || '').toLowerCase().includes(q);
        const catMatch = (e.category || '').toLowerCase().includes(q);
        const amtMatch = String(e.amount || '').includes(q);
        if (!titleMatch && !notesMatch && !catMatch && !amtMatch) return false;
      }
      return true;
    });

    // Sort newest first
    displayList.sort((a, b) => (b.date || '').localeCompare(a.date || ''));

    const listEl = document.getElementById('budgetLogExpensesList');
    const emptyEl = document.getElementById('budgetLogEmptyState');
    const emptyTitleEl = document.getElementById('budgetLogEmptyTitle');
    const emptyDescEl = document.getElementById('budgetLogEmptyDesc');
    if (!listEl) return;

    if (displayList.length === 0) {
      listEl.innerHTML = '';
      if (emptyEl) {
        emptyEl.classList.remove('hidden');
        if (emptyTitleEl && emptyDescEl) {
          if (currentFilter === 'logged') {
            emptyTitleEl.textContent = `No purchases logged to ${cat} yet`;
            emptyDescEl.textContent = `Switch to "Available" or "All" to assign unlogged purchases to ${cat}.`;
          } else if (currentFilter === 'other' || currentFilter === 'available') {
            emptyTitleEl.textContent = `No unassigned expenses available`;
            emptyDescEl.textContent = `All purchases this month are already logged into budget categories.`;
          } else if (q) {
            emptyTitleEl.textContent = `No matching transactions found`;
            emptyDescEl.textContent = `No transactions match "${escapeHtml(q)}".`;
          } else {
            emptyTitleEl.textContent = `No transactions found`;
            emptyDescEl.textContent = `There are no purchases logged to ${cat} or available to log.`;
          }
        }
      }
      return;
    }
    if (emptyEl) emptyEl.classList.add('hidden');

    listEl.innerHTML = displayList.map(exp => {
      const isLogged = isThisCatExpense(exp);
      const expAmt = parseFloat(exp.amount) || 0;
      const formattedAmt = formatMoney(expAmt, exp.currency);
      const convertedAmt = (exp.currency !== cur) ? ` (${formatMoney(convertCurrency(expAmt, exp.currency, cur), cur)})` : '';
      const expDateStr = exp.date ? new Date(exp.date + 'T00:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : '';

      return `
        <div class="flex items-center justify-between p-3 rounded-2xl border transition-all ${isLogged ? 'bg-emerald-50/40 border-emerald-200/80 shadow-2xs' : 'bg-white hover:bg-slate-50/80 border-slate-200/80'}">
          <div class="flex items-center gap-3 min-w-0 pr-2">
            <!-- Icon/Date Pill -->
            <div class="w-10 h-10 rounded-xl flex flex-col items-center justify-center shrink-0 border ${isLogged ? 'bg-emerald-100/60 border-emerald-300 text-emerald-800' : 'bg-slate-50 border-slate-200 text-slate-500'}">
              <span class="text-[9px] font-bold uppercase tracking-tight leading-none">${expDateStr.split(' ')[0] || 'EXP'}</span>
              <span class="text-xs font-black leading-tight mt-0.5">${expDateStr.split(' ')[1] || ''}</span>
            </div>

            <div class="min-w-0">
              <div class="flex items-center gap-2">
                <span class="font-bold text-xs sm:text-sm text-slate-900 truncate">${escapeHtml(exp.title || 'Untitled Expense')}</span>
                ${isLogged 
                  ? `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100/80 text-emerald-800 border border-emerald-200/80 shrink-0">✓ In ${escapeHtml(cat)}</span>`
                  : `<span class="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-slate-100 text-slate-600 border border-slate-200/80 shrink-0 truncate max-w-[120px]">Available</span>`
                }
              </div>
              <div class="text-[11px] text-slate-400 mt-0.5 flex items-center gap-2">
                <span>${exp.paymentMethod || 'Card'}${exp.cardLast4 ? ' •• ' + exp.cardLast4 : ''}</span>
                ${exp.notes ? `<span>• <span class="italic text-slate-500 truncate max-w-[160px]">${escapeHtml(exp.notes)}</span></span>` : ''}
              </div>
            </div>
          </div>

          <div class="flex items-center gap-3 shrink-0">
            <div class="text-right">
              <div class="font-mono font-bold text-xs sm:text-sm text-slate-900">-${formattedAmt}</div>
              ${convertedAmt ? `<div class="text-[10px] text-slate-400 font-mono">${convertedAmt}</div>` : ''}
            </div>

            ${isLogged 
              ? `<button type="button" class="budget-log-toggle-btn px-2.5 py-1.5 rounded-xl text-xs font-semibold bg-emerald-100 hover:bg-rose-50 text-emerald-800 hover:text-rose-700 border border-emerald-300 hover:border-rose-200 transition-all flex items-center gap-1 cursor-pointer group/btn" data-id="${exp.id}" title="Currently in ${escapeHtml(cat)}. Click to remove.">
                  <i data-lucide="check" class="w-3.5 h-3.5 group-hover/btn:hidden"></i>
                  <i data-lucide="x" class="w-3.5 h-3.5 hidden group-hover/btn:inline-block"></i>
                  <span class="group-hover/btn:hidden">Logged</span>
                  <span class="hidden group-hover/btn:inline-block">Remove</span>
                </button>`
              : `<button type="button" class="budget-log-toggle-btn px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 hover:bg-indigo-700 active:scale-95 text-white shadow-2xs transition-all flex items-center gap-1 cursor-pointer" data-id="${exp.id}" title="Log into ${escapeHtml(cat)}">
                  <i data-lucide="plus" class="w-3.5 h-3.5"></i>
                  <span>Log</span>
                </button>`
            }
          </div>
        </div>
      `;
    }).join('');

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function monthKeyFromDate(d) {
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
  }

  function getBudgetMonthKey() {
    return state.selectedMonth || monthKeyFromDate(new Date());
  }

  function shiftMonthKey(key, delta) {
    if (key === 'ALL' || !key) key = monthKeyFromDate(new Date());
    const [y, m] = key.split('-').map(Number);
    return monthKeyFromDate(new Date(y, m - 1 + delta, 1));
  }

  function getMonthContext(monthKey) {
    if (!monthKey || monthKey === 'ALL' || monthKey === 'all') {
      return {
        daysInMonth: 30,
        daysElapsed: 30,
        daysLeft: 0,
        isCurrent: false,
        isFuture: false
      };
    }
    const [y, m] = monthKey.split('-').map(Number);
    const daysInMonth = new Date(y, m, 0).getDate();
    const now = new Date();
    const curKey = monthKeyFromDate(now);
    const isCurrent = monthKey === curKey;
    const isFuture = monthKey > curKey;
    const daysElapsed = isCurrent ? now.getDate() : (isFuture ? 0 : daysInMonth);
    return {
      daysInMonth,
      daysElapsed,
      daysLeft: isCurrent ? Math.max(1, daysInMonth - now.getDate() + 1) : (isFuture ? daysInMonth : 0),
      isCurrent,
      isFuture
    };
  }

  function isFlexibleExpense(exp) {
    if (!exp || exp.isIncome || exp.type === 'income' || exp.category === 'Income') return false;
    return !exp.isSubscription && !FIXED_CATEGORIES.includes(exp.category);
  }

  function getActiveBudgetMonthsList(monthKey) {
    if (monthKey && monthKey !== 'ALL' && monthKey !== 'all') {
      return [monthKey];
    }
    const monthsSet = new Set();
    (state.expenses || []).forEach(e => {
      if (e && e.date && e.date.length >= 7) monthsSet.add(e.date.slice(0, 7));
    });
    (state.budget && state.budget.incomes || []).forEach(inc => {
      if (inc && inc.date && inc.date.length >= 7) monthsSet.add(inc.date.slice(0, 7));
    });
    (state.budget && state.budget.projects || []).forEach(p => {
      if (!p) return;
      const pm = getProjectRespectiveMonth(p);
      if (pm) monthsSet.add(pm);
      if (p.dueDate && p.dueDate.length >= 7) monthsSet.add(p.dueDate.slice(0, 7));
      if (Array.isArray(p.payments)) {
        p.payments.forEach(pay => {
          if (pay && pay.date && pay.date.length >= 7) monthsSet.add(pay.date.slice(0, 7));
        });
      }
    });
    if (monthsSet.size === 0) {
      monthsSet.add(new Date().toISOString().slice(0, 7));
    }
    return Array.from(monthsSet);
  }

  function getMonthlyFixedCommitments(cur, monthKey) {
    let total = 0;
    const isAll = (!monthKey || monthKey === 'ALL' || monthKey === 'all');
    const activeMonths = getActiveBudgetMonthsList(monthKey);

    activeMonths.forEach(mKey => {
      (state.subscriptions || []).forEach(sub => {
        if (!isSubscriptionCountedInMonth(sub, mKey)) return;
        const v = convertCurrency(parseFloat(sub.amount) || 0, sub.currency || 'EUR', cur);
        total += sub.billingCycle === 'yearly' ? v / 12 : v;
      });
    });

    // Include one-off (non-subscription) expenses categorized under FIXED_CATEGORIES
    // so they are never silently dropped between Fixed Bills and Everyday Flexible Spend
    (state.expenses || []).forEach(exp => {
      if (!exp || exp.isSubscription || exp.isIncome || exp.type === 'income' || exp.category === 'Income') return;
      if (!FIXED_CATEGORIES.includes(exp.category)) return;
      if (!exp.date || (!isAll && !exp.date.startsWith(monthKey))) return;
      total += convertCurrency(parseFloat(exp.amount) || 0, exp.currency || 'EUR', cur);
    });

    return total;
  }

  function findCategoryStats(stats, catName) {
    if (!stats || !catName) return { total: 0, count: 0, dates: [] };
    if (stats[catName]) return stats[catName];
    const lower = String(catName).toLowerCase().trim();
    for (const k in stats) {
      if (k.toLowerCase().trim() === lower) return stats[k];
    }
    return { total: 0, count: 0, dates: [] };
  }

  function getFlexibleStats(monthKey, cur) {
    const byCat = {};
    const isAll = (!monthKey || monthKey === 'ALL' || monthKey === 'all');
    (state.expenses || []).forEach(exp => {
      if (!exp.date || (!isAll && !exp.date.startsWith(monthKey)) || !isFlexibleExpense(exp)) return;
      const cat = exp.category || 'Other';
      if (!byCat[cat]) byCat[cat] = { category: cat, total: 0, count: 0, dates: [] };
      const expCur = exp.currency || 'EUR';
      byCat[cat].total += convertCurrency(parseFloat(exp.amount) || 0, expCur, cur);
      byCat[cat].count += 1;
      byCat[cat].dates.push(exp.date);
    });
    return byCat;
  }

  function getHistoricalAverages(monthKey, cur) {
    const totals = {};
    let monthsWithData = 0;
    for (let i = 1; i <= 3; i++) {
      const key = shiftMonthKey(monthKey, -i);
      const hasAny = (state.expenses || []).some(e => e.date && e.date.startsWith(key) && isFlexibleExpense(e));
      if (!hasAny) continue;
      monthsWithData++;
      const stats = getFlexibleStats(key, cur);
      Object.values(stats).forEach(s => {
        if (!totals[s.category]) totals[s.category] = { total: 0, count: 0, months: 0 };
        totals[s.category].total += s.total;
        totals[s.category].count += s.count;
        if (s.total > 0) totals[s.category].months += 1;
      });
    }
    const avgs = {};
    if (monthsWithData > 0) {
      Object.keys(totals).forEach(cat => {
        const catMonths = Math.max(1, totals[cat].months || monthsWithData);
        avgs[cat] = {
          monthly: totals[cat].total / catMonths,
          tripsPerMonth: totals[cat].count / catMonths
        };
      });
    }
    return { avgs, monthsWithData };
  }

  function averageGapDays(dates) {
    const uniq = [...new Set(dates)].sort();
    if (uniq.length < 2) return null;
    const first = new Date(uniq[0]);
    const last = new Date(uniq[uniq.length - 1]);
    return Math.round((last - first) / 86400000 / (uniq.length - 1) * 10) / 10;
  }

  function getCategoryBudgetSummary(monthKey, cur, stats) {
    const configuredCategories = state.budget.categories || [];
    let totalBudgetLimit = 0;
    let totalSpentInBudgeted = 0;
    let budgetedCategoriesCount = 0;
    const totalAllEverydaySpent = Object.values(stats || {}).reduce((s, c) => s + (c.total || 0), 0);
    const monthsMultiplier = (!monthKey || monthKey === 'ALL' || monthKey === 'all')
      ? Math.max(1, getActiveBudgetMonthsList(monthKey).length)
      : 1;

    const seenCats = new Set();
    configuredCategories.forEach(catObj => {
      const cat = catObj.name;
      if (!cat) return;
      const catKey = cat.toLowerCase().trim();
      if (seenCats.has(catKey)) return;
      seenCats.add(catKey);

      const rawLimit = (catObj.limit !== undefined && parseFloat(catObj.limit) > 0)
        ? parseFloat(catObj.limit)
        : ((state.budget.categoryBudgets && state.budget.categoryBudgets[cat] > 0) ? parseFloat(state.budget.categoryBudgets[cat]) : 0);
      const limitCurrency = catObj.currency || state.budget.incomeCurrency || 'EUR';
      const targetBudget = rawLimit > 0 ? convertCurrency(rawLimit, limitCurrency, cur) * monthsMultiplier : 0;
      const s = findCategoryStats(stats, cat);

      if (targetBudget > 0) {
        totalBudgetLimit += targetBudget;
        totalSpentInBudgeted += s.total;
        budgetedCategoriesCount++;
      }
    });

    return {
      totalBudgetLimit,
      totalSpentInBudgeted,
      budgetedCategoriesCount,
      totalAllEverydaySpent
    };
  }

  function getSurvivalFoodBaseline(cur, stats, avgs) {
    const categories = (state.budget && Array.isArray(state.budget.categories)) ? state.budget.categories : [];

    // 1. Look for configured category matching groceries, food, supermarket, essentials
    const foodCat = categories.find(c => {
      const name = (c.name || '').toLowerCase();
      return /grocer|food|supermarket|essentials/i.test(name);
    });

    if (foodCat) {
      const catName = foodCat.name;
      const rawLimit = (foodCat.limit !== undefined && parseFloat(foodCat.limit) > 0)
        ? parseFloat(foodCat.limit)
        : ((state.budget.categoryBudgets && state.budget.categoryBudgets[catName] > 0) ? parseFloat(state.budget.categoryBudgets[catName]) : 0);

      // If user configured a budget limit, that is their planned monthly food baseline!
      if (rawLimit > 0) {
        const limitCur = foodCat.currency || state.budget.incomeCurrency || 'EUR';
        return convertCurrency(rawLimit, limitCur, cur);
      }

      // Check historical 3-month average
      const a = avgs && (avgs[catName] || Object.entries(avgs).find(([k]) => k.toLowerCase() === catName.toLowerCase())?.[1]);
      if (a && a.monthly > 0) {
        return a.monthly;
      }

      // Check current month spending
      const s = findCategoryStats(stats, catName);
      if (s && s.total > 0) {
        return s.total;
      }
    }

    // 2. If no configured category matched, check if any category in stats matches
    for (const catName in (stats || {})) {
      if (/grocer|food|supermarket|essentials/i.test(catName)) {
        const s = stats[catName];
        if (s && s.total > 0) return s.total;
      }
    }

    // 3. Fallback: if historical average has any food category
    if (avgs) {
      for (const catName in avgs) {
        if (/grocer|food|supermarket|essentials/i.test(catName)) {
          if (avgs[catName].monthly > 0) return avgs[catName].monthly;
        }
      }
    }

    return 0;
  }

  // Shrink all Budget tile grey descriptions to one shared size where every line fits fully (no truncation)
  function fitBudgetTileText() {
    const ids = ['budgetIncomeEquiv', 'budgetPendingEquiv', 'budgetFixedEquiv', 'budgetCategoryEquiv', 'budgetLeftEquiv'];
    const els = ids.map(id => document.getElementById(id)).filter(el => el && el.offsetParent !== null);
    if (!els.length) return;
    const MAX = 10, MIN = 8.5;
    let size = MAX;
    const apply = s => els.forEach(el => el.style.setProperty('font-size', s + 'px', 'important'));
    apply(size);
    while (size > MIN && els.some(el => el.scrollWidth > el.clientWidth + 0.5)) {
      size = Math.round((size - 0.25) * 100) / 100;
      apply(size);
    }
  }

  // Render main Freelancer Budget & Cash Flow view
  function renderBudgetView() {
    if (!document.getElementById('viewBudget')) return;
    const cur = state.displayCurrency;
    const monthKey = getBudgetMonthKey();
    const isAllTime = (!monthKey || monthKey === 'ALL' || monthKey === 'all');
    const ctx = getMonthContext(monthKey);
    const otherCurs = ['EUR', 'ILS', 'USD'].filter(c => c !== cur);
    const eq = v => `≈ ${formatMoney(convertCurrency(v, cur, otherCurs[0]), otherCurs[0])} • ${formatMoney(convertCurrency(v, cur, otherCurs[1]), otherCurs[1])}`;
    const setText = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };

    // 1. Calculate Cash Flow: Collected Income vs Pending Receivables
    // A. Collected Income: from logged incomes + project payments made in this month or All Time
    let projectCollected = 0;
    let miscCollected = 0;
    let paymentCount = 0;
    let pendingReceivables = 0;
    let pendingCount = 0;

    // Check project payments
    (state.budget.projects || []).forEach(p => {
      const projCur = p.currency || 'EUR';
      if (Array.isArray(p.payments) && p.payments.length > 0) {
        p.payments.forEach(pay => {
          if (isAllTime || (pay.date && pay.date.startsWith(monthKey))) {
            projectCollected += convertCurrency(parseFloat(pay.amount) || 0, pay.currency || projCur, cur);
            paymentCount++;
          }
        });
      } else if (p.status === 'paid') {
        const pd = getProjectPaidDate(p);
        if (isAllTime || (pd && pd.startsWith(monthKey))) {
          projectCollected += convertCurrency(parseFloat(p.amount !== undefined ? p.amount : p.fee) || 0, projCur, cur);
          paymentCount++;
        }
      } else if (parseFloat(p.paidAmount) > 0) {
        const pd = getProjectPaidDate(p);
        if (isAllTime || (pd && pd.startsWith(monthKey))) {
          projectCollected += convertCurrency(parseFloat(p.paidAmount) || 0, projCur, cur);
          paymentCount++;
        }
      }
    });

    // Check ad-hoc direct incomes
    (state.budget.incomes || []).forEach(inc => {
      if (isAllTime || (inc.date && inc.date.startsWith(monthKey))) {
        const amt = parseFloat(inc.amount) || 0;
        if (isMiscIncomeExpected(inc)) {
          pendingReceivables += convertCurrency(amt, inc.currency || 'EUR', cur);
          pendingCount++;
        } else {
          miscCollected += convertCurrency(amt, inc.currency || 'EUR', cur);
          paymentCount++;
        }
      }
    });

    // Check any direct incomes in state.expenses (e.g. from bank import or legacy entries)
    (state.expenses || []).forEach(exp => {
      if (exp && (exp.isIncome || exp.category === 'Income' || exp.type === 'income')) {
        if (exp.isDirectIncome || exp.isProjectPayment) return;
        if (isAllTime || (exp.date && exp.date.startsWith(monthKey))) {
          miscCollected += convertCurrency(parseFloat(exp.amount) || 0, exp.currency || 'EUR', cur);
          paymentCount++;
        }
      }
    });

    const collectedIncome = projectCollected + miscCollected;

    // B. Pending Receivables due this month (or open pending projects)
    (state.budget.projects || []).forEach(p => {
      const totalAmt = parseFloat(p.amount !== undefined ? p.amount : p.fee) || 0;
      const paidAmt = parseFloat(p.paidAmount) || 0;
      const unpaid = Math.max(0, totalAmt - paidAmt);
      if (unpaid > 0 && p.status !== 'paid') {
        if (projectPaymentMatchesMonth(p, monthKey)) {
          pendingReceivables += convertCurrency(unpaid, p.currency || 'EUR', cur);
          pendingCount++;
        }
      }
    });

    // C. Fixed Commitments & Freelance Tax Reserve
    const fixedBills = getMonthlyFixedCommitments(cur, monthKey);
    const curTax = (state.budget && state.budget.taxReservePercent !== undefined && state.budget.taxReservePercent !== null)
      ? parseInt(state.budget.taxReservePercent, 10)
      : 0;
    const taxRate = isNaN(curTax) ? 0 : Math.max(0, curTax);
    const taxReserve = (collectedIncome * (taxRate / 100));
    const totalReserved = fixedBills + taxReserve;

    // D. Everyday Living Expenses & Category Budgets
    const stats = getFlexibleStats(monthKey, cur);
    const flexibleSpent = Object.values(stats).reduce((s, c) => s + c.total, 0);
    const catSummary = getCategoryBudgetSummary(monthKey, cur, stats);
    const totalBudgetLimit = catSummary.totalBudgetLimit;
    const totalSpentInBudgeted = catSummary.totalSpentInBudgeted;
    const totalAllEverydaySpent = catSummary.totalAllEverydaySpent;

    // Effective living deduction factoring in category budget limit:
    // If limits are configured, reserve the budget limit (or actual spend if over budget)
    // plus any unbudgeted spending. If no limits are set, deduct flexibleSpent.
    const reservedForBudgeted = Math.max(totalBudgetLimit, totalSpentInBudgeted);
    const unbudgetedSpent = Math.max(0, totalAllEverydaySpent - totalSpentInBudgeted);
    const categoryBudgetDeduction = totalBudgetLimit > 0
      ? (reservedForBudgeted + unbudgetedSpent)
      : flexibleSpent;

    // E. Safe to Spend (Cash In Hand basis factoring in Bills, Tax & Category Budget)
    const safeLeftForLiving = collectedIncome - totalReserved - categoryBudgetDeduction;
    const perDaySafe = ctx.daysLeft > 0 ? (safeLeftForLiving / ctx.daysLeft) : 0;

    // Projected if all pending invoices clear:
    const projectedCollected = collectedIncome + pendingReceivables;
    const projectedTax = projectedCollected * (taxRate / 100);
    const projectedLeftForLiving = projectedCollected - (fixedBills + projectedTax) - categoryBudgetDeduction;

    // Update 5 Metric Tiles
    setText('budgetIncomePrimary', formatMoney(collectedIncome, cur));
    setText('budgetIncomeEquiv', `Proj ${formatMoney(projectCollected, cur)} • Misc ${formatMoney(miscCollected, cur)}`);
    setText('budgetCollectedTag', paymentCount > 0 ? `${paymentCount} paid` : 'In Hand');

    setText('budgetPendingPrimary', formatMoney(pendingReceivables, cur));
    setText('budgetPendingEquiv', `Total w/ paid: ${formatMoney(projectedCollected, cur)}`);
    setText('budgetPendingTag', pendingCount > 0 ? `${pendingCount} open` : 'None Due');

    setText('budgetFixedPrimary', formatMoney(totalReserved, cur));
    setText('budgetFixedEquiv', `Bills ${formatMoney(fixedBills, cur)} • Tax ${formatMoney(taxReserve, cur)}`);
    setText('budgetTaxRateTag', `${taxRate}% Tax`);

    // Box 4: Budget Spending (Everyday Spend vs Limit)
    const boxPrimary = document.getElementById('budgetCategoryPrimary');
    const boxLimit = document.getElementById('budgetCategoryLimit');
    const boxTag = document.getElementById('budgetCategoryTag');
    const boxEquiv = document.getElementById('budgetCategoryEquiv');
    if (boxPrimary && boxLimit) {
      if (totalBudgetLimit > 0) {
        boxPrimary.textContent = formatMoney(totalSpentInBudgeted, cur);
        boxLimit.innerHTML = `<span class="text-slate-300 font-normal">/</span><span>${formatMoney(totalBudgetLimit, cur)}</span>`;
        const diff = totalBudgetLimit - totalSpentInBudgeted;
        const rawPct = Math.round((totalSpentInBudgeted / totalBudgetLimit) * 100);
        if (boxTag) {
          boxTag.textContent = `${rawPct}% used`;
          boxTag.className = diff < 0
            ? 'text-[10px] text-rose-700 bg-rose-50 px-1.5 py-0.5 rounded font-medium shrink-0'
            : `text-[10px] ${rawPct > 80 ? 'text-amber-700 bg-amber-50' : 'text-indigo-700 bg-indigo-50'} px-1.5 py-0.5 rounded font-medium shrink-0`;
        }
        if (boxEquiv) {
          boxEquiv.textContent = diff < 0
            ? `${formatMoney(Math.abs(diff), cur)} over budget`
            : `${formatMoney(diff, cur)} remaining`;
          boxEquiv.className = diff < 0
            ? 'text-[10px] text-rose-600 font-mono mt-1 whitespace-normal leading-tight font-semibold'
            : 'text-[10px] text-slate-400 font-mono mt-1 whitespace-normal leading-tight';
        }
      } else {
        boxPrimary.textContent = formatMoney(totalAllEverydaySpent, cur);
        boxLimit.innerHTML = `<span class="text-slate-300 font-normal">/</span><span class="text-xs sm:text-sm font-semibold">No budget</span>`;
        if (boxTag) {
          boxTag.textContent = '0% set';
          boxTag.className = 'text-[10px] text-slate-600 bg-slate-100 px-1.5 py-0.5 rounded font-medium shrink-0';
        }
        if (boxEquiv) {
          boxEquiv.textContent = `${catSummary.budgetedCategoriesCount} categories tracked`;
          boxEquiv.className = 'text-[10px] text-slate-400 font-mono mt-1 whitespace-normal leading-tight';
        }
      }
    }

    // Box 5: Safe to Spend
    const leftEl = document.getElementById('budgetLeftPrimary');
    if (leftEl) {
      leftEl.textContent = formatMoney(safeLeftForLiving, cur);
      leftEl.className = `text-lg sm:text-xl font-bold mt-0.5 font-mono ${safeLeftForLiving < 0 ? 'text-rose-600' : 'text-slate-900'}`;
    }
    const leftTag = document.getElementById('budgetLeftTag');
    if (leftTag) {
      if (safeLeftForLiving < 0) {
        leftTag.textContent = 'Deficit';
        leftTag.className = 'text-[10px] text-rose-700 bg-rose-50 px-1.5 py-0.5 rounded font-medium shrink-0';
      } else {
        leftTag.textContent = 'In Hand';
        leftTag.className = 'text-[10px] text-emerald-700 bg-emerald-50 px-1.5 py-0.5 rounded font-medium shrink-0';
      }
    }
    const leftEqEl = document.getElementById('budgetLeftEquiv');
    if (leftEqEl) {
      if (ctx.daysLeft > 0 && safeLeftForLiving > 0) {
        leftEqEl.textContent = `≈ ${formatMoney(perDaySafe, cur)}/day (${ctx.daysLeft}d left)`;
      } else if (pendingReceivables > 0) {
        leftEqEl.textContent = `If invoices clear: ${formatMoney(projectedLeftForLiving, cur)}`;
      } else {
        leftEqEl.textContent = eq(safeLeftForLiving);
      }
      leftEqEl.className = 'text-[10px] text-slate-400 font-mono mt-1 whitespace-nowrap';
    }

    // Fit grey descriptions after all renderers (incl. renderCategoryBudgetsList) have written text
    setTimeout(fitBudgetTileText, 0);
    if (!window.__budgetFitResizeBound) {
      window.__budgetFitResizeBound = true;
      window.addEventListener('resize', fitBudgetTileText);
    }

    // Cash-Flow Allocation Bar
    const bar = document.getElementById('budgetFlowBar');
    const flowText = document.getElementById('budgetFlowText');
    const runwayText = document.getElementById('budgetRunwayText');
    if (bar) {
      if (collectedIncome > 0) {
        const totalObligations = fixedBills + taxReserve + categoryBudgetDeduction;
        const isDeficit = safeLeftForLiving < 0;

        if (!isDeficit) {
          // Normal/Surplus: All commitments fit within collected income
          const fP = Math.max(0, (fixedBills / collectedIncome) * 100);
          const tP = Math.max(0, (taxReserve / collectedIncome) * 100);
          const xP = Math.max(0, (categoryBudgetDeduction / collectedIncome) * 100);
          const lP = Math.max(0, 100 - fP - tP - xP);
          bar.innerHTML = `
            <div class="h-full bg-slate-400" style="width:${fP}%" title="Fixed Bills (${Math.round(fP)}%)"></div>
            ${taxRate > 0 ? `<div class="h-full bg-blue-500" style="width:${tP}%" title="Tax Reserve (${Math.round(tP)}%)"></div>` : ''}
            <div class="h-full bg-slate-700" style="width:${xP}%" title="Category Budget (${Math.round(xP)}%)"></div>
            <div class="h-full bg-emerald-400" style="width:${lP}%" title="Surplus (${Math.round(lP)}%)"></div>`;

          if (flowText) {
            const parts = [];
            parts.push(`<span class="text-slate-500">Bills: ${Math.round(fP)}%</span>`);
            if (taxRate > 0) parts.push(`<span class="text-blue-600">Tax (${taxRate}%): ${Math.round(tP)}%</span>`);
            if (categoryBudgetDeduction > 0) parts.push(`<span class="text-slate-700">Category Budget: ${Math.round(xP)}%</span>`);
            parts.push(`<span class="text-emerald-500">Surplus: +${formatMoney(safeLeftForLiving, cur)} (${Math.round(lP)}%)</span>`);
            flowText.innerHTML = parts.join(' <span class="text-slate-300">•</span> ');
          }
        } else {
          // Deficit: Commitments exceed collected income
          const denom = totalObligations > 0 ? totalObligations : collectedIncome;
          const fP = (fixedBills / denom) * 100;
          const tP = (taxReserve / denom) * 100;
          const xP = (categoryBudgetDeduction / denom) * 100;
          bar.innerHTML = `
            <div class="h-full bg-slate-400" style="width:${fP}%" title="Fixed Bills (${Math.round(fP)}% of commitments)"></div>
            ${taxRate > 0 ? `<div class="h-full bg-blue-500" style="width:${tP}%" title="Tax Reserve (${Math.round(tP)}% of commitments)"></div>` : ''}
            <div class="h-full bg-slate-700" style="width:${xP}%" title="Category Budget (${Math.round(xP)}% of commitments)"></div>`;

          if (flowText) {
            const billsPct = Math.round((fixedBills / collectedIncome) * 100);
            const catPct = Math.round((categoryBudgetDeduction / collectedIncome) * 100);
            const parts = [];
            parts.push(`<span class="text-slate-500">Bills: ${billsPct}%</span>`);
            if (taxRate > 0) parts.push(`<span class="text-blue-600">Tax (${taxRate}%): ${Math.round((taxReserve / collectedIncome) * 100)}%</span>`);
            if (categoryBudgetDeduction > 0) parts.push(`<span class="text-slate-700">Category Budget: ${catPct}%</span>`);
            parts.push(`<span class="text-red-500">Deficit: -${formatMoney(Math.abs(safeLeftForLiving), cur)}</span>`);
            flowText.innerHTML = parts.join(' <span class="text-slate-300">•</span> ');
          }
        }
      } else {
        bar.innerHTML = '<div class="h-full bg-slate-200 w-full"></div>';
        if (flowText) {
          flowText.textContent = pendingReceivables > 0 
            ? `No cash deposited yet this month. ${formatMoney(pendingReceivables, cur)} pending in invoices.`
            : 'Add upcoming client projects or log income to track your cash flow split.';
        }
      }
    }

    // Survival Baseline Calculation
    if (runwayText) {
      const { avgs } = getHistoricalAverages(monthKey, cur);
      const foodBaseline = getSurvivalFoodBaseline(cur, stats, avgs);
      const monthlyFixedBills = isAllTime
        ? (fixedBills / Math.max(1, getActiveBudgetMonthsList(monthKey).length))
        : fixedBills;
      const survivalBaseline = monthlyFixedBills + foodBaseline;
      const desc = foodBaseline > 0
        ? `(Rent & bills ${formatMoney(monthlyFixedBills, cur)} + food ${formatMoney(foodBaseline, cur)})`
        : `(Rent, utilities & fixed commitments)`;
      runwayText.innerHTML = `Survival baseline: <strong class="font-mono font-bold text-slate-800">${formatMoney(survivalBaseline, cur)}/mo</strong> ${desc}`;
    }

    // ---------------------------------------------------------
    // 2. Render Freelance Projects & Invoices
    // ---------------------------------------------------------
    renderFreelanceProjectsList(monthKey, cur);

    // ---------------------------------------------------------
    // 2.5 Render Misc Income (Gifts, Odd Jobs, etc.)
    // ---------------------------------------------------------
    renderMiscIncomeList(monthKey, cur);

    // ---------------------------------------------------------
    // 3. Render Category Budgets & Everyday Patterns
    // ---------------------------------------------------------
    renderCategoryBudgetsList(monthKey, cur, stats, ctx);

    lucide.createIcons();
  }

  // Render Projects List
  function renderFreelanceProjectsList(monthKey, cur) {
    const list = document.getElementById('freelanceProjectsGrid');
    const empty = document.getElementById('freelanceProjectsEmpty');
    const countBadge = document.getElementById('budgetProjectsCount');
    if (!list) return;

    const allProjects = state.budget.projects || [];
    const filter = state.freelanceFilter || 'all';

    // 1. Filter by respective payment month or All Time
    const inMonthProjects = allProjects.filter(p => projectPaymentMatchesMonth(p, monthKey));

    // 2. Filter by status (all, pending, paid)
    const filtered = inMonthProjects.filter(p => {
      const totalAmt = parseFloat(p.amount !== undefined ? p.amount : p.fee) || 0;
      const paidAmt = parseFloat(p.paidAmount) || 0;
      const remainingAmt = Math.max(0, totalAmt - paidAmt);
      const isPaid = p.status === 'paid' || remainingAmt <= 0;
      if (filter === 'pending') return !isPaid;
      if (filter === 'paid') return isPaid;
      return true;
    });

    if (countBadge) countBadge.textContent = String(inMonthProjects.length);

    if (filtered.length === 0) {
      list.innerHTML = '';
      if (empty) {
        empty.classList.remove('hidden');
        const emptyLabel = empty.querySelector('p.text-sm');
        if (emptyLabel) {
          const isAllTime = (!monthKey || monthKey === 'ALL' || monthKey === 'all');
          let periodLabel = 'All Time';
          if (!isAllTime) {
            const [y, m] = monthKey.split('-').map(Number);
            periodLabel = new Date(y, m - 1, 1).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
          }
          emptyLabel.textContent = `No freelance projects found for ${periodLabel}`;
        }
      }
      return;
    }
    if (empty) empty.classList.add('hidden');

    list.innerHTML = filtered.map(p => {
      const totalAmt = parseFloat(p.amount !== undefined ? p.amount : p.fee) || 0;
      const paidAmt = parseFloat(p.paidAmount) || 0;
      const remainingAmt = Math.max(0, totalAmt - paidAmt);
      const percentPaid = totalAmt > 0 ? Math.min(100, Math.round((paidAmt / totalAmt) * 100)) : 0;
      const isPaid = p.status === 'paid' || remainingAmt <= 0;
      const isPartial = paidAmt > 0 && !isPaid;
      const paidDate = getProjectPaidDate(p);

      // Multi-currency conversions
      const projCur = p.currency || 'EUR';
      const otherCurs = ['EUR', 'ILS', 'USD'].filter(c => c !== projCur);
      const targetCur1 = (cur !== projCur) ? cur : otherCurs[0];
      const targetCur2 = (cur !== projCur) ? otherCurs.find(c => c !== cur) : otherCurs[1];
      const equivHtml = `≈ ${formatMoney(convertCurrency(totalAmt, projCur, targetCur1), targetCur1)} • ${formatMoney(convertCurrency(totalAmt, projCur, targetCur2), targetCur2)}`;

      const statusBadge = isPaid
        ? '<span class="px-2 py-0.5 text-[10px] font-semibold bg-emerald-50 text-emerald-700 rounded-full border border-emerald-200">Paid in Full</span>'
        : isPartial
        ? `<span class="px-2 py-0.5 text-[10px] font-semibold bg-amber-50 text-amber-700 rounded-full border border-amber-200">${percentPaid}% Paid</span>`
        : p.status === 'invoiced'
        ? '<span class="px-2 py-0.5 text-[10px] font-semibold bg-blue-50 text-blue-700 rounded-full border border-blue-200">Invoiced</span>'
        : '<span class="px-2 py-0.5 text-[10px] font-semibold bg-slate-100 text-slate-700 rounded-full border border-slate-200">In Progress</span>';

      const dateFooter = isPaid
        ? `<div class="flex items-center gap-1.5 text-[11px] text-emerald-600 font-medium">
            <i data-lucide="calendar-check-2" class="w-3.5 h-3.5 text-emerald-600 shrink-0"></i>
            <span>Paid: ${escapeHtml(paidDate || p.dueDate || 'Settled')}</span>
          </div>`
        : `<div class="flex items-center gap-1.5 text-[11px] text-amber-600 font-medium">
            <i data-lucide="calendar" class="w-3.5 h-3.5 text-amber-600 shrink-0"></i>
            <span>${p.paymentDueDate || (p.proformaInvoice && p.proformaInvoice.validUntil) ? 'Payment Due ' + escapeHtml(getProjectPaymentDueDate(p)) : 'Due ' + escapeHtml(p.dueDate ? p.dueDate : 'No date set')}</span>
          </div>`;

      const invLabel = p.invoiceNumber ? `<span class="px-1.5 py-0.2 bg-slate-100 text-slate-600 rounded text-[10px] font-mono">#${escapeHtml(p.invoiceNumber)}</span>` : '';
      const recLabel = p.receiptNumber ? `<span class="px-1.5 py-0.2 bg-emerald-50 text-emerald-700 rounded text-[10px] font-mono">Rec #${escapeHtml(p.receiptNumber)}</span>` : '';

      return `
        <div class="bg-white border border-slate-200/80 rounded-2xl p-4 shadow-2xs hover:border-slate-300 transition-all flex flex-col justify-between gap-3 group cursor-grab active:cursor-grabbing select-none" data-id="${p.id}">
          <div>
            <div class="flex items-start justify-between gap-2">
              <div class="min-w-0 flex-1">
                <div class="flex items-center gap-1.5 flex-wrap">
                  <h4 class="font-bold text-sm text-slate-900 truncate">${escapeHtml(p.client || 'Client')}</h4>
                  ${invLabel}
                  ${recLabel}
                </div>
                <p class="text-xs text-slate-500 truncate mt-0.5">${escapeHtml(p.description || p.title || 'Freelance Project')}</p>
              </div>

              <div class="flex items-center gap-1 shrink-0">
                <button class="edit-freelance-proj-btn text-slate-400 hover:text-slate-700 p-1 rounded-lg hover:bg-slate-100 transition-colors cursor-pointer" data-id="${p.id}" title="Edit Project">
                  <i data-lucide="edit-3" class="w-3.5 h-3.5"></i>
                </button>
                <button class="delete-freelance-proj-btn text-slate-300 hover:text-rose-600 p-1 rounded-lg hover:bg-rose-50 transition-colors cursor-pointer" data-id="${p.id}" title="Delete Project">
                  <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                </button>
                <i data-lucide="grip-vertical" class="w-3.5 h-3.5 text-slate-300 hover:text-slate-500 transition-colors cursor-grab active:cursor-grabbing card-drag-handle ml-0.5" title="Drag to reorder"></i>
              </div>
            </div>

            <!-- Amount & Payment Status -->
            <div class="mt-2.5 space-y-1.5">
              <div class="flex items-baseline justify-between gap-2">
                <div class="flex items-baseline gap-2 flex-wrap min-w-0">
                  <span class="font-mono text-xl font-bold text-slate-900">${formatMoney(totalAmt, projCur)}</span>
                  ${projCur !== cur ? `
                    <span class="text-xs font-mono font-bold text-slate-600 bg-slate-100 border border-slate-200/80 px-2 py-0.5 rounded-lg" title="Converted to ${cur} at current exchange rate">
                      ≈ ${formatMoney(convertCurrency(totalAmt, projCur, cur), cur)}
                    </span>
                  ` : ''}
                </div>
                ${statusBadge}
              </div>

              <!-- Progress bar for payment -->
              <div class="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                <div class="h-full rounded-full transition-all duration-300 ${isPaid ? 'bg-emerald-500' : isPartial ? 'bg-amber-500' : 'bg-slate-300'}" style="width: ${percentPaid}%"></div>
              </div>

              <div class="flex items-center justify-between text-[11px] text-slate-400 pt-0.5 gap-2">
                <span class="whitespace-nowrap shrink-0">${isPaid ? 'Fully settled' : (paidAmt > 0 ? `Paid ${formatMoney(paidAmt, projCur)} • Left ${formatMoney(remainingAmt, projCur)}` : `Left: ${formatMoney(remainingAmt, projCur)}`)}</span>
                <span class="font-mono shrink-0">${equivHtml}</span>
              </div>
            </div>
          </div>

          <!-- Card Footer: Due/Paid Date, Invoice Attachment & Payment Action -->
          <div class="pt-2.5 border-t border-slate-100 flex items-center justify-between gap-2">
            ${dateFooter}

            <div class="flex items-center gap-1.5 flex-wrap">
              ${(p.hasProformaDoc || p.proformaInvoice)
                ? `<button class="view-project-proforma-btn px-2 py-1 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-lg text-xs font-medium border border-indigo-200/80 flex items-center gap-1 transition-all cursor-pointer" data-id="${p.id}" title="View Proforma Invoice">
                    <i data-lucide="file-text" class="w-3 h-3 text-indigo-600"></i>
                    <span>Proforma</span>
                  </button>`
                : ''
              }
              ${(p.hasInvoiceDoc || p.hasReceiptDoc) 
                ? `<button class="view-project-invoice-btn px-2 py-1 bg-blue-50 hover:bg-blue-100 text-blue-700 rounded-lg text-xs font-medium border border-blue-200/80 flex items-center gap-1 transition-all cursor-pointer" data-id="${p.id}" title="View Attached Receipt Document">
                    <i data-lucide="paperclip" class="w-3 h-3 text-blue-600"></i>
                    <span>Receipt</span>
                  </button>`
                : ''
              }
              ${(isPaid || paidAmt > 0) && (!p.hasInvoiceDoc && !p.hasReceiptDoc && !p.hasProformaDoc)
                ? `<button class="attach-project-invoice-btn px-2 py-1 hover:bg-slate-50 text-slate-400 hover:text-slate-600 rounded-lg text-xs font-medium flex items-center gap-1 transition-all cursor-pointer" data-id="${p.id}" title="Attach receipt document or PDF">
                    <i data-lucide="upload" class="w-3 h-3"></i>
                    <span>Attach</span>
                  </button>`
                : ''
              }

              ${!isPaid
                ? `<button class="log-project-payment-btn px-3 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-semibold shadow-2xs flex items-center gap-1 transition-all cursor-pointer" data-id="${p.id}" title="Record incoming payment from client">
                    <i data-lucide="arrow-down-left" class="w-3 h-3"></i>
                    <span>Log Payment</span>
                  </button>`
                : ''
              }
            </div>
          </div>
        </div>
      `;
    }).join('');
    initSortableFreelanceProjects();
  }

  // SortableJS Drag & Drop for Freelance Projects (like Needa Pay)
  function initSortableFreelanceProjects() {
    const grid = document.getElementById('freelanceProjectsGrid');
    if (!grid || typeof Sortable === 'undefined') return;
    if (state.freelanceProjectsSortableInstance) {
      state.freelanceProjectsSortableInstance.destroy();
    }
    state.freelanceProjectsSortableInstance = new Sortable(grid, {
      animation: 200,
      filter: 'button, input, select, textarea, a, .view-project-invoice-btn, .view-project-proforma-btn, .attach-project-invoice-btn, .log-project-payment-btn, .edit-freelance-proj-btn, .delete-freelance-proj-btn',
      preventOnFilter: false,
      ghostClass: 'sortable-ghost',
      chosenClass: 'sortable-chosen',
      dragClass: 'sortable-drag',
      onEnd: () => {
        saveFreelanceProjectsOrder();
      }
    });
  }

  function saveFreelanceProjectsOrder() {
    try {
      const projGrid = document.getElementById('freelanceProjectsGrid');
      if (!projGrid) return;
      const orderedIds = [];
      Array.from(projGrid.children).forEach(el => {
        const id = el.getAttribute('data-id');
        if (id && !orderedIds.includes(id)) {
          orderedIds.push(id);
        }
      });
      if (orderedIds.length > 0 && Array.isArray(state.budget.projects)) {
        const projectMap = new Map();
        state.budget.projects.forEach(p => {
          if (p && p.id && !projectMap.has(p.id)) {
            projectMap.set(p.id, p);
          }
        });
        const reordered = [];
        orderedIds.forEach(id => {
          if (projectMap.has(id)) {
            reordered.push(projectMap.get(id));
            projectMap.delete(id);
          }
        });
        // Append any projects that were not in the DOM (e.g. filtered view)
        projectMap.forEach(p => reordered.push(p));
        state.budget.projects = reordered;
        saveBudget();
      }
    } catch (e) {
      console.warn('Could not save freelance projects order:', e);
    }
  }

  // Render Misc Income List (Gifts, Odd Jobs, Side Gigs, Windfalls)
  function renderMiscIncomeList(monthKey, cur) {
    const list = document.getElementById('miscIncomeGrid');
    const empty = document.getElementById('miscIncomeEmpty');
    const countBadge = document.getElementById('budgetMiscIncomeCount');
    const totalPill = document.getElementById('budgetMiscIncomeTotalPill');
    if (!list) return;

    const allIncomes = (state.budget && Array.isArray(state.budget.incomes)) ? state.budget.incomes : [];
    const isAllTime = (!monthKey || monthKey === 'ALL' || monthKey === 'all');

    // Filter by month
    const inMonthIncomes = allIncomes.filter(inc => {
      if (isAllTime) return true;
      return inc.date && inc.date.startsWith(monthKey);
    });

    if (countBadge) countBadge.textContent = String(inMonthIncomes.length);

    // Calculate total for this period
    let receivedInPeriod = 0;
    let expectedInPeriod = 0;
    inMonthIncomes.forEach(inc => {
      const amt = parseFloat(inc.amount) || 0;
      const converted = convertCurrency(amt, inc.currency || 'EUR', cur);
      if (isMiscIncomeExpected(inc)) {
        expectedInPeriod += converted;
      } else {
        receivedInPeriod += converted;
      }
    });

    if (totalPill) {
      if (inMonthIncomes.length > 0 && (receivedInPeriod > 0 || expectedInPeriod > 0)) {
        if (receivedInPeriod > 0 && expectedInPeriod > 0) {
          totalPill.innerHTML = `+${formatMoney(receivedInPeriod, cur)} <span class="text-amber-600 font-medium text-[11px]">(+${formatMoney(expectedInPeriod, cur)} expected)</span>`;
        } else if (receivedInPeriod > 0) {
          totalPill.textContent = `+${formatMoney(receivedInPeriod, cur)}`;
        } else {
          totalPill.innerHTML = `<span class="text-amber-600 font-medium">+${formatMoney(expectedInPeriod, cur)} expected</span>`;
        }
        totalPill.classList.remove('hidden');
      } else {
        totalPill.classList.add('hidden');
      }
    }

    if (inMonthIncomes.length === 0) {
      list.innerHTML = '';
      if (empty) {
        empty.classList.remove('hidden');
        const emptyLabel = empty.querySelector('p.text-sm');
        if (emptyLabel) {
          let periodLabel = 'All Time';
          if (!isAllTime) {
            const [y, m] = monthKey.split('-').map(Number);
            periodLabel = new Date(y, m - 1, 1).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
          }
          emptyLabel.textContent = `No misc income found for ${periodLabel}`;
        }
      }
      return;
    }

    if (empty) empty.classList.add('hidden');

    list.innerHTML = inMonthIncomes.map(inc => {
      const amt = parseFloat(inc.amount) || 0;
      const incCur = inc.currency || 'EUR';
      const incType = inc.type || inc.category || 'Gift';
      const isExpected = isMiscIncomeExpected(inc);

      // Multi-currency conversions
      const otherCurs = ['EUR', 'ILS', 'USD'].filter(c => c !== incCur);
      const targetCur1 = (cur !== incCur) ? cur : otherCurs[0];
      const targetCur2 = (cur !== incCur) ? otherCurs.find(c => c !== cur) : otherCurs[1];
      const equivHtml = `≈ ${formatMoney(convertCurrency(amt, incCur, targetCur1), targetCur1)} • ${formatMoney(convertCurrency(amt, incCur, targetCur2), targetCur2)}`;

      // Tag styling based on type
      let typeBg = 'bg-emerald-50 text-emerald-700 border-emerald-200/60';
      if (incType === 'Odd Job' || incType === 'Side Gig') {
        typeBg = 'bg-blue-50 text-blue-700 border-blue-200/60';
      } else if (incType === 'Reimbursement') {
        typeBg = 'bg-amber-50 text-amber-700 border-amber-200/60';
      } else if (incType === 'Bonus / Windfall') {
        typeBg = 'bg-purple-50 text-purple-700 border-purple-200/60';
      }

      return `
        <div class="bg-white border border-slate-200/80 rounded-2xl p-4 shadow-2xs hover:border-slate-300 transition-all flex flex-col justify-between gap-3 group" data-id="${escapeHtml(inc.id)}">
          <div>
            <div class="flex items-start justify-between gap-2">
              <div class="min-w-0 flex-1">
                <div class="flex items-center gap-1.5 flex-wrap">
                  <h4 class="font-bold text-sm text-slate-900 truncate">${escapeHtml(inc.title || 'Income Source')}</h4>
                  <span class="px-2 py-0.5 text-[10px] font-semibold rounded-full border ${typeBg}">${escapeHtml(incType)}</span>
                  ${isExpected ? `<span class="px-2 py-0.5 text-[10px] font-bold rounded-full border bg-amber-50 text-amber-700 border-amber-200/70 flex items-center gap-1"><i data-lucide="clock" class="w-3 h-3 text-amber-600"></i> Expected</span>` : ''}
                </div>
                ${inc.notes ? `<p class="text-xs text-slate-500 truncate mt-0.5">${escapeHtml(inc.notes)}</p>` : ''}
              </div>

              <div class="flex items-center gap-1 shrink-0">
                <button class="edit-misc-income-btn text-slate-400 hover:text-slate-700 p-1 rounded-lg hover:bg-slate-100 transition-colors cursor-pointer" data-id="${escapeHtml(inc.id)}" title="Edit Income">
                  <i data-lucide="edit-3" class="w-3.5 h-3.5"></i>
                </button>
                <button class="delete-misc-income-btn text-slate-300 hover:text-rose-600 p-1 rounded-lg hover:bg-rose-50 transition-colors cursor-pointer" data-id="${escapeHtml(inc.id)}" title="Delete Income">
                  <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                </button>
              </div>
            </div>

            <!-- Amount display -->
            <div class="mt-2.5 space-y-1.5">
              <div class="flex items-baseline justify-between gap-2">
                <div class="flex items-baseline gap-2 flex-wrap min-w-0">
                  <span class="font-mono text-xl font-bold text-slate-900">+${formatMoney(amt, incCur)}</span>
                  ${incCur !== cur ? `
                    <span class="text-xs font-mono font-bold text-emerald-700 bg-emerald-50 border border-emerald-200/80 px-2 py-0.5 rounded-lg" title="Converted to ${cur} at current exchange rate">
                      ≈ +${formatMoney(convertCurrency(amt, incCur, cur), cur)}
                    </span>
                  ` : ''}
                </div>
              </div>

              <div class="flex items-center justify-between text-[11px] text-slate-400 pt-0.5 gap-2">
                <span class="whitespace-nowrap shrink-0">${inc.method ? escapeHtml(inc.method) : 'Direct'}</span>
                <span class="font-mono shrink-0">${equivHtml}</span>
              </div>
            </div>
          </div>

          <!-- Card Footer: Status & Actions -->
          <div class="pt-2.5 border-t border-slate-100 flex items-center justify-between gap-2 text-xs">
            ${isExpected ? `
              <div class="flex items-center gap-1.5 text-[11px] text-amber-700 font-medium bg-amber-50 px-2 py-0.5 rounded-lg border border-amber-200/80">
                <i data-lucide="clock" class="w-3.5 h-3.5 text-amber-600 shrink-0"></i>
                <span>Expected: ${escapeHtml(inc.date || 'Pending')}</span>
              </div>
              <button type="button" class="mark-misc-income-received-btn text-[11px] font-semibold text-emerald-700 hover:text-emerald-800 bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 px-2 py-0.5 rounded-lg transition-colors cursor-pointer flex items-center gap-1" data-id="${escapeHtml(inc.id)}">
                <i data-lucide="check" class="w-3 h-3"></i>
                <span>Mark Received</span>
              </button>
            ` : `
              <div class="flex items-center gap-1.5 text-[11px] text-emerald-700 font-medium bg-emerald-50 px-2 py-0.5 rounded-lg border border-emerald-200/80">
                <i data-lucide="calendar-check" class="w-3.5 h-3.5 text-emerald-600 shrink-0"></i>
                <span>Received: ${escapeHtml(inc.date || 'Recorded')}</span>
              </div>
            `}
          </div>
        </div>
      `;
    }).join('');
    lucide.createIcons();
  }

  // Render Category Budgets List (Customizable Categories & Icons)
  function renderCategoryBudgetsList(monthKey, cur, stats, ctx) {
    const list = document.getElementById('budgetCategoryList');
    const empty = document.getElementById('budgetCategoryEmpty');
    const countBadge = document.getElementById('budgetCategoryCount');
    if (!list) return;

    const { avgs } = getHistoricalAverages(monthKey, cur);
    const configuredCategories = state.budget.categories || [];

    // Ensure all configured categories exist, plus any extra categories currently recorded in expenses
    const categoryNames = configuredCategories.map(c => (c.name || '').toLowerCase());
    Object.keys(stats).forEach(cat => {
      if (!categoryNames.includes(cat.toLowerCase()) && !FIXED_CATEGORIES.includes(cat)) {
        const existingLimit = (state.budget.categoryBudgets && state.budget.categoryBudgets[cat] !== undefined)
          ? parseFloat(state.budget.categoryBudgets[cat]) || 0
          : 0;
        configuredCategories.push({
          id: 'cat_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4),
          name: cat,
          icon: getCategoryLucideIcon(cat),
          color: getCategoryColor(cat),
          limit: existingLimit,
          currency: state.budget.incomeCurrency || 'EUR'
        });
        categoryNames.push(cat.toLowerCase());
      }
    });

    if (countBadge) countBadge.textContent = String(configuredCategories.length);

    // Calculate total expected monthly spend according to category budgets & actual spent in total
    const catSummary = getCategoryBudgetSummary(monthKey, cur, stats);
    const { totalBudgetLimit, totalSpentInBudgeted, budgetedCategoriesCount, totalAllEverydaySpent } = catSummary;

    // Update Category Budget Overview Card and Header Pill
    const totalSpentEl = document.getElementById('catBudgetTotalSpent');
    const totalLimitEl = document.getElementById('catBudgetTotalLimit');
    const totalSubtitleEl = document.getElementById('catBudgetTotalSubtitle');
    const remBadge = document.getElementById('catBudgetRemainingBadge');
    const pctBadge = document.getElementById('catBudgetPercentBadge');
    const progBar = document.getElementById('catBudgetProgressBar');
    const pacingText = document.getElementById('catBudgetPacingText');
    const breakdownText = document.getElementById('catBudgetBreakdownText');

    if (totalSpentEl && totalLimitEl) {
      if (totalBudgetLimit > 0) {
        totalSpentEl.textContent = formatMoney(totalSpentInBudgeted, cur);
        totalLimitEl.textContent = ' / ' + formatMoney(totalBudgetLimit, cur);
        if (totalSubtitleEl) totalSubtitleEl.textContent = 'spent of budget';

        const diff = totalBudgetLimit - totalSpentInBudgeted;
        const pct = Math.min(100, Math.round((totalSpentInBudgeted / totalBudgetLimit) * 100));
        const rawPct = Math.round((totalSpentInBudgeted / totalBudgetLimit) * 100);

        if (remBadge) {
          if (diff < 0) {
            remBadge.textContent = `${formatMoney(Math.abs(diff), cur)} over budget`;
            remBadge.className = 'px-3 py-1.5 rounded-xl text-xs font-semibold font-mono bg-rose-50 text-rose-700 border border-rose-200/80 shadow-2xs';
          } else {
            remBadge.textContent = `${formatMoney(diff, cur)} remaining`;
            const badgeColor = pct > 80 ? 'bg-amber-50 text-amber-700 border-amber-200/80' : 'bg-emerald-50 text-emerald-700 border-emerald-200/80';
            remBadge.className = `px-3 py-1.5 rounded-xl text-xs font-semibold font-mono ${badgeColor} border shadow-2xs`;
          }
        }

        if (pctBadge) {
          pctBadge.textContent = `${rawPct}% used`;
        }

        if (progBar) {
          progBar.style.width = `${pct}%`;
          progBar.style.backgroundColor = diff < 0 ? '#e11d48' : (pct > 80 ? '#d97706' : '#4f46e5');
        }

        if (pacingText) {
          if (ctx.isCurrent && ctx.daysElapsed > 0) {
            const projected = (totalSpentInBudgeted / ctx.daysElapsed) * ctx.daysInMonth;
            pacingText.innerHTML = `<span>Pacing for <strong>~${formatMoney(projected, cur)}</strong> by month end (${ctx.daysElapsed}/${ctx.daysInMonth} days)</span>`;
          } else {
            pacingText.innerHTML = `<span>${budgetedCategoriesCount} active category budget${budgetedCategoriesCount === 1 ? '' : 's'}</span>`;
          }
        }

        if (breakdownText) {
          const unbudgetedSpent = Math.max(0, totalAllEverydaySpent - totalSpentInBudgeted);
          if (unbudgetedSpent > 0.01) {
            breakdownText.innerHTML = `<span>Total everyday spend: <strong class="text-slate-700 font-mono">${formatMoney(totalAllEverydaySpent, cur)}</strong> (+${formatMoney(unbudgetedSpent, cur)} unbudgeted)</span>`;
          } else {
            breakdownText.innerHTML = `<span>${budgetedCategoriesCount} of ${configuredCategories.length} categories budgeted</span>`;
          }
        }

        // 5-Tile Grid Box 4: Category Budget
        const boxPrimary = document.getElementById('budgetCategoryPrimary');
        const boxLimit = document.getElementById('budgetCategoryLimit');
        const boxTag = document.getElementById('budgetCategoryTag');
        const boxEquiv = document.getElementById('budgetCategoryEquiv');

        if (boxPrimary && boxLimit) {
          boxPrimary.textContent = formatMoney(totalSpentInBudgeted, cur);
          boxLimit.innerHTML = `<span class="text-slate-300 font-normal">/</span><span>${formatMoney(totalBudgetLimit, cur)}</span>`;
          if (boxTag) {
            if (diff < 0) {
              boxTag.textContent = `${rawPct}% used`;
              boxTag.className = 'text-[10px] text-rose-700 bg-rose-50 px-1.5 py-0.5 rounded font-medium shrink-0';
            } else {
              boxTag.textContent = `${rawPct}% used`;
              const tagColor = pct > 80 ? 'text-amber-700 bg-amber-50' : 'text-indigo-700 bg-indigo-50';
              boxTag.className = `text-[10px] ${tagColor} px-1.5 py-0.5 rounded font-medium shrink-0`;
            }
          }
          if (boxEquiv) {
            if (diff < 0) {
              boxEquiv.textContent = `${formatMoney(Math.abs(diff), cur)} over budget`;
              boxEquiv.className = 'text-[10px] text-rose-600 font-mono mt-1 whitespace-normal leading-tight font-semibold';
            } else {
              boxEquiv.textContent = `${formatMoney(diff, cur)} remaining`;
              boxEquiv.className = 'text-[10px] text-slate-400 font-mono mt-1 whitespace-normal leading-tight';
            }
          }
        }
      } else {
        totalSpentEl.textContent = formatMoney(totalAllEverydaySpent, cur);
        totalLimitEl.textContent = ' / No budget set';
        if (totalSubtitleEl) totalSubtitleEl.textContent = 'spent this month';

        if (remBadge) {
          remBadge.textContent = 'No limits configured';
          remBadge.className = 'px-3 py-1.5 rounded-xl text-xs font-semibold font-mono bg-slate-100 text-slate-500 border border-slate-200 shadow-2xs';
        }
        if (pctBadge) {
          pctBadge.textContent = '0% set';
        }
        if (progBar) {
          progBar.style.width = '0%';
        }
        if (pacingText) {
          pacingText.innerHTML = `<span>Set monthly limits on your categories to track expected spending</span>`;
        }
        if (breakdownText) {
          breakdownText.innerHTML = `<span>${configuredCategories.length} categories tracked</span>`;
        }

        // 5-Tile Grid Box 4: No Budget
        const boxPrimary = document.getElementById('budgetCategoryPrimary');
        const boxLimit = document.getElementById('budgetCategoryLimit');
        const boxTag = document.getElementById('budgetCategoryTag');
        const boxEquiv = document.getElementById('budgetCategoryEquiv');

        if (boxPrimary && boxLimit) {
          boxPrimary.textContent = formatMoney(totalAllEverydaySpent, cur);
          boxLimit.innerHTML = `<span class="text-slate-300 font-normal">/</span><span class="text-xs sm:text-sm font-semibold">No budget</span>`;
          if (boxTag) {
            boxTag.textContent = '0% set';
            boxTag.className = 'text-[10px] text-slate-600 bg-slate-100 px-1.5 py-0.5 rounded font-medium shrink-0';
          }
          if (boxEquiv) {
            boxEquiv.textContent = `${configuredCategories.length} categories tracked`;
            boxEquiv.className = 'text-[10px] text-slate-400 font-mono mt-1 whitespace-normal leading-tight';
          }
        }
      }
    }

    if (configuredCategories.length === 0) {
      list.innerHTML = '';
      if (empty) empty.classList.remove('hidden');
      return;
    }
    if (empty) empty.classList.add('hidden');

    const monthsMultiplier = (!monthKey || monthKey === 'ALL' || monthKey === 'all')
      ? Math.max(1, getActiveBudgetMonthsList(monthKey).length)
      : 1;

    list.innerHTML = configuredCategories.map(catObj => {
      const cat = catObj.name;
      const icon = catObj.icon || getCategoryLucideIcon(cat);
      const color = catObj.color || getCategoryColor(cat);
      const s = findCategoryStats(stats, cat);
      const a = avgs[cat] || (avgs && Object.entries(avgs).find(([k]) => k.toLowerCase() === (cat || '').toLowerCase())?.[1]);
      const rawLimit = (catObj.limit !== undefined && parseFloat(catObj.limit) > 0)
        ? parseFloat(catObj.limit)
        : ((state.budget.categoryBudgets && state.budget.categoryBudgets[cat] > 0) ? parseFloat(state.budget.categoryBudgets[cat]) : 0);
      const limitCurrency = catObj.currency || state.budget.incomeCurrency || 'EUR';
      const targetBudget = rawLimit > 0 ? convertCurrency(rawLimit, limitCurrency, cur) * monthsMultiplier : 0;
      const avgTrip = s.count > 0 ? s.total / s.count : 0;
      const gap = averageGapDays(s.dates);
      const projected = ctx.isCurrent && ctx.daysElapsed > 0 ? (s.total / ctx.daysElapsed) * ctx.daysInMonth : s.total;

      // Budget Progress
      let pct = 0;
      let barColor = color;
      let statusText = '';
      if (targetBudget > 0) {
        pct = Math.min(100, Math.round((s.total / targetBudget) * 100));
        const diff = targetBudget - s.total;
        if (diff < 0) {
          barColor = '#e11d48'; // red
          statusText = `<span class="text-rose-600 font-semibold font-mono">${formatMoney(Math.abs(diff), cur)} over budget</span>`;
        } else {
          barColor = pct > 80 ? '#d97706' : '#059669'; // amber or emerald
          statusText = `<span class="text-slate-500 font-mono">${formatMoney(diff, cur)} remaining</span>`;
        }
      } else {
        pct = a && a.monthly > 0 ? Math.min(100, Math.round((s.total / a.monthly) * 100)) : 0;
        statusText = `<span class="text-slate-400">No target set</span>`;
      }

      // Frequency string (ideal for Supermarket trips!)
      const freqBits = [];
      if (s.count > 0) {
        freqBits.push(`${s.count} ${s.count === 1 ? 'trip' : 'trips'}`);
        freqBits.push(`avg ${formatMoney(avgTrip, cur)}`);
      }
      if (gap) freqBits.push(`every ~${gap}d`);

      return `
        <div class="category-card bg-white border border-slate-200/80 rounded-2xl p-4 shadow-2xs hover:border-slate-300 transition-all flex flex-col justify-between gap-3 group relative cursor-grab active:cursor-grabbing min-h-[180px]" data-category-name="${escapeHtml(cat)}">
          <div>
            <div class="flex items-start justify-between gap-2">
              <div class="flex items-center gap-2.5 min-w-0">
                <!-- Clickable icon trigger -->
                <button type="button" class="edit-category-trigger w-9 h-9 rounded-xl flex items-center justify-center shrink-0 hover:ring-2 hover:ring-indigo-300 hover:scale-105 transition-all cursor-pointer shadow-2xs border border-black/5" style="background-color:${color}15;color:${color};" data-cat="${escapeHtml(cat)}" title="Click to customize name & icon">
                  <i data-lucide="${icon}" class="w-4 h-4"></i>
                </button>
                <div class="min-w-0">
                  <div class="flex items-center gap-1.5">
                    <h4 class="font-semibold text-sm text-slate-900 truncate">${escapeHtml(cat)}</h4>
                    <button type="button" class="edit-category-trigger text-slate-300 hover:text-indigo-600 p-0.5 rounded cursor-pointer transition-colors" data-cat="${escapeHtml(cat)}" title="Edit category name & icon">
                      <i data-lucide="pencil" class="w-3 h-3"></i>
                    </button>
                    <i data-lucide="grip-vertical" class="w-3.5 h-3.5 text-slate-300 hover:text-slate-500 transition-colors cursor-grab active:cursor-grabbing ml-0.5 shrink-0" title="Drag to reorder category"></i>
                  </div>
                  <div class="text-[11px] text-slate-400 truncate">${freqBits.length > 0 ? freqBits.join(' • ') : '0 purchases this month'}</div>
                </div>
              </div>
              <button class="budget-quick-cat-btn text-xs font-medium text-slate-500 hover:text-slate-900 px-2.5 py-1 rounded-xl bg-slate-50 hover:bg-slate-100 border border-slate-200/80 transition-colors cursor-pointer shrink-0" data-cat="${escapeHtml(cat)}" title="Log a ${escapeHtml(cat)} expense">+ Log</button>
            </div>

            <!-- Spending vs Budget -->
            <div class="mt-2.5 space-y-1.5">
              <div class="flex items-baseline justify-between gap-2">
                <div>
                  <span class="font-mono text-xl font-bold text-slate-900">${formatMoney(s.total, cur)}</span>
                  ${targetBudget > 0 ? `<span class="text-xs text-slate-400 font-mono"> / ${formatMoney(targetBudget, cur)}</span>` : '<span class="text-xs text-slate-400"> spent</span>'}
                </div>
                <div class="text-[11px] font-medium">${statusText}</div>
              </div>

              <!-- Visual progress bar -->
              <div class="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                <div class="h-full rounded-full transition-all duration-300" style="width:${pct}%;background-color:${barColor};"></div>
              </div>

              <!-- Pacing analysis -->
              <div class="flex items-center justify-between text-[11px] text-slate-400 pt-0.5">
                ${ctx.isCurrent && s.count > 0 
                  ? `<span>Pacing for ~${formatMoney(projected, cur)}</span>` 
                  : `<span>${a ? `Past avg: ${formatMoney(a.monthly, cur)}` : 'Keep logging to see trend'}</span>`}
                ${targetBudget > 0 
                  ? `<span class="font-mono">${pct}% used</span>` 
                  : (a ? `<span class="font-mono">~${Math.round(a.tripsPerMonth)}×/mo</span>` : '')}
              </div>
            </div>
          </div>

          <!-- Card Footer CTA -->
          <div class="pt-2 border-t border-slate-100 flex items-center justify-between gap-2 text-[11px]">
            <button type="button" class="edit-category-trigger text-slate-400 hover:text-indigo-600 cursor-pointer flex items-center gap-1 transition-colors" data-cat="${escapeHtml(cat)}" title="Customize name & icon">
              <i data-lucide="sliders" class="w-3 h-3"></i>
              <span>Customize</span>
            </button>
            <button class="inline-set-budget-btn text-indigo-600 hover:text-indigo-800 font-semibold cursor-pointer" data-cat="${escapeHtml(cat)}" data-val="${targetBudget}">
              ${targetBudget > 0 ? 'Edit Limit' : '+ Set Limit'}
            </button>
          </div>
        </div>
      `;
    }).join('');

    // Append the New Category creation box right next to the last category box
    const addCategoryCardHtml = `
      <div id="newCategoryCardBtn" class="bg-white border-2 border-dashed border-slate-200/90 hover:border-indigo-400 rounded-2xl p-4 shadow-2xs hover:shadow-xs transition-all flex flex-col items-center justify-center text-center gap-2.5 cursor-pointer group min-h-[180px] hover:bg-indigo-50/20" title="Create a new budget category">
        <div class="w-12 h-12 rounded-2xl bg-slate-50 group-hover:bg-indigo-50 text-slate-400 group-hover:text-indigo-600 border border-slate-200/70 group-hover:border-indigo-200 flex items-center justify-center transition-all group-hover:scale-110 shadow-2xs">
          <i data-lucide="plus" class="w-6 h-6 stroke-[2.2]"></i>
        </div>
        <div>
          <h4 class="font-semibold text-sm text-slate-700 group-hover:text-indigo-900 transition-colors">New Category</h4>
          <p class="text-[11px] text-slate-400 mt-0.5">Custom name &amp; icon</p>
        </div>
      </div>
    `;

    list.innerHTML = list.innerHTML + addCategoryCardHtml;
    initSortableCategories();
  }

  function initSortableCategories() {
    const list = document.getElementById('budgetCategoryList');
    if (!list || typeof Sortable === 'undefined') return;
    if (state.categorySortableInstance) {
      state.categorySortableInstance.destroy();
    }
    state.categorySortableInstance = new Sortable(list, {
      animation: 250,
      handle: '.category-card',
      filter: '#newCategoryCardBtn, button, a, input, label, select, .edit-category-trigger, .budget-quick-cat-btn, .inline-set-budget-btn',
      preventOnFilter: false,
      ghostClass: 'sortable-ghost',
      chosenClass: 'sortable-chosen',
      dragClass: 'sortable-drag',
      onEnd: () => {
        saveCategoriesOrderFromDOM();
      }
    });
  }

  function saveCategoriesOrderFromDOM() {
    const list = document.getElementById('budgetCategoryList');
    if (!list) return;
    const names = Array.from(list.querySelectorAll('[data-category-name]')).map(el => el.getAttribute('data-category-name'));
    if (!names.length) return;

    const currentCats = (state.budget && Array.isArray(state.budget.categories))
      ? state.budget.categories
      : JSON.parse(JSON.stringify(DEFAULT_BUDGET_CATEGORIES));

    const catMap = new Map();
    currentCats.forEach(c => {
      if (c && c.name) catMap.set(c.name.toLowerCase().trim(), c);
    });

    const newOrder = [];
    names.forEach(name => {
      const key = (name || '').toLowerCase().trim();
      const found = catMap.get(key);
      if (found) {
        newOrder.push(found);
        catMap.delete(key);
      }
    });

    // Append any remaining categories
    catMap.forEach(c => newOrder.push(c));

    state.budget.categories = newOrder;
    saveBudget();
    syncCategoryDropdowns();
  }

  function hidePaymentModal() {
    const modalPayment = document.getElementById('logProjectPaymentModal');
    if (modalPayment) {
      modalPayment.classList.add('hidden');
      modalPayment.classList.remove('flex');
    }
  }

  function updatePaymentConversionPreview() {
    const projId = (document.getElementById('paymentProjectId') || {}).value;
    const proj = (state.budget.projects || []).find(p => p.id === projId);
    if (!proj) return;
    const projCur = proj.currency || state.displayCurrency || 'EUR';
    const payCurSelect = document.getElementById('paymentCurrency');
    const payCur = payCurSelect ? payCurSelect.value : projCur;
    const amtInput = document.getElementById('paymentAmount');
    const payAmt = parseFloat(amtInput ? amtInput.value : 0) || 0;
    const previewEl = document.getElementById('paymentConvertedPreview');
    if (!previewEl) return;

    if (payCur !== projCur && payAmt > 0) {
      const credAmt = convertCurrency(payAmt, payCur, projCur);
      previewEl.textContent = `≈ ${formatMoney(credAmt, projCur)} toward project fee`;
      previewEl.classList.remove('hidden');
    } else {
      previewEl.classList.add('hidden');
      previewEl.textContent = '';
    }
  }

  function openRecordPaymentModal(proj) {
    const modalPayment = document.getElementById('logProjectPaymentModal');
    if (!modalPayment || !proj) return;
    const total = parseFloat(proj.amount !== undefined ? proj.amount : proj.fee) || 0;
    const unpaid = Math.max(0, total - (parseFloat(proj.paidAmount) || 0));
    const projIdInput = document.getElementById('paymentProjectId');
    if (projIdInput) projIdInput.value = proj.id;
    const subtitle = document.getElementById('paymentModalProjectSubtitle');
    if (subtitle) subtitle.textContent = `Record payment from "${proj.client || 'Client'}"`;
    const cur = state.displayCurrency || 'EUR';
    const projCur = proj.currency || cur;
    const unpaidText = (projCur !== cur && unpaid > 0)
      ? `${formatMoney(unpaid, projCur)} (≈ ${formatMoney(convertCurrency(unpaid, projCur, cur), cur)})`
      : formatMoney(unpaid, projCur);
    const unpaidEl = document.getElementById('paymentModalUnpaidText');
    if (unpaidEl) unpaidEl.textContent = unpaidText;
    const curBadge = document.getElementById('paymentModalCurrencyBadge');
    if (curBadge) curBadge.textContent = projCur;
    const curSelect = document.getElementById('paymentCurrency');
    if (curSelect) {
      curSelect.value = projCur;
      curSelect.dataset.prevCur = projCur;
    }
    const amtInput = document.getElementById('paymentAmount');
    if (amtInput) amtInput.value = unpaid > 0 ? unpaid.toFixed(2) : '';
    const dateInput = document.getElementById('paymentDate');
    if (dateInput) dateInput.value = new Date().toISOString().split('T')[0];
    const notesInput = document.getElementById('paymentNotes');
    if (notesInput) notesInput.value = (unpaid > 0 && unpaid === total) ? 'Full payment' : 'Milestone deposit';

    updatePaymentConversionPreview();

    modalPayment.classList.remove('hidden');
    modalPayment.classList.add('flex');
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
    if (amtInput) amtInput.focus();
  }

  // Module-scoped project modal helpers
  let resetProjectForm, showProjectModal, hideProjectModal;

  // Setup all event listeners for the Freelancer Budget & Cash Flow module
  function setupBudgetListeners() {
    const byId = id => document.getElementById(id);
    const tabBtn = byId('sidebarTabBudget');
    if (!tabBtn) return;

    state.freelanceFilter = 'all';

    // 1. Freelance Project Filter Pills
    document.querySelectorAll('.project-filter-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.project-filter-btn').forEach(b => {
          b.classList.remove('bg-white', 'text-slate-900', 'shadow-2xs');
          b.classList.add('text-slate-500');
        });
        btn.classList.add('bg-white', 'text-slate-900', 'shadow-2xs');
        btn.classList.remove('text-slate-500');
        state.freelanceFilter = btn.getAttribute('data-filter') || 'all';
        renderFreelanceProjectsList(getBudgetMonthKey(), state.displayCurrency);
        lucide.createIcons();
      });
    });

    // 2. Category Budget Box Jump
    const catBox = byId('budgetCategoryBox');
    if (catBox) {
      catBox.addEventListener('click', () => {
        const target = byId('categoryBudgetOverviewCard') || byId('budgetCategoryList');
        if (target) {
          target.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      });
    }

    // 3. Add Project Modal open/close
    const openAddProj = byId('openAddProjectBtn');
    const emptyAddProj = byId('emptyAddProjectBtn');
    const modalProj = byId('freelanceProjectModal');
    const closeProjModal = byId('closeFreelanceProjectModalBtn');
    const cancelProjModal = byId('cancelFreelanceProjectBtn');

    resetProjectForm = () => {
      byId('freelanceProjectId').value = '';
      byId('freelanceClient').value = '';
      byId('freelanceProjectTitle').value = '';
      byId('freelanceAmount').value = '';
      byId('freelanceCurrency').value = state.displayCurrency;
      if (byId('freelanceReceiptNumber')) byId('freelanceReceiptNumber').value = '';
      byId('freelanceInvoiceNumber').value = '';
      const nowIsoDate = new Date().toISOString().split('T')[0];
      let defaultProjDate = nowIsoDate;
      if (state.selectedMonth && state.selectedMonth !== 'ALL' && state.selectedMonth !== 'all') {
        if (!nowIsoDate.startsWith(state.selectedMonth)) {
          defaultProjDate = `${state.selectedMonth}-15`;
        }
      }
      byId('freelanceDueDate').value = defaultProjDate;
      byId('freelanceStatus').value = 'invoiced';
      byId('freelanceNotes').value = '';
      state.pendingProjectAttachment = null;
      state.pendingProjectProformaAttachment = null;
      state.projectDocRemoved = false;
      state.projectProformaRemoved = false;

      const paidDateContainer = byId('freelancePaidDateContainer');
      const paidDateInput = byId('freelancePaidDate');
      if (paidDateContainer) paidDateContainer.classList.add('hidden');
      if (paidDateInput) paidDateInput.value = defaultProjDate;

      if (byId('freelanceProformaFileName')) byId('freelanceProformaFileName').textContent = '';
      if (byId('freelanceProformaStatusBadge')) {
        byId('freelanceProformaStatusBadge').textContent = 'No document attached';
        byId('freelanceProformaStatusBadge').className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-slate-200 text-slate-700';
      }
      if (byId('freelanceProformaAttachedView')) byId('freelanceProformaAttachedView').classList.add('hidden');
      if (byId('freelanceProformaUploadView')) byId('freelanceProformaUploadView').classList.remove('hidden');

      if (byId('freelanceDocFileName')) byId('freelanceDocFileName').textContent = '';
      byId('freelanceDocStatusBadge').textContent = 'No document attached';
      byId('freelanceDocStatusBadge').className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-slate-200 text-slate-700';
      byId('freelanceDocAttachedView').classList.add('hidden');
      byId('freelanceDocUploadView').classList.remove('hidden');
      byId('deleteFreelanceProjectBtn').classList.add('hidden');
      byId('freelanceModalTitle').textContent = 'Add Freelance Project / Invoice';
    };

    const statusSelect = byId('freelanceStatus');
    if (statusSelect) {
      statusSelect.addEventListener('change', (e) => {
        const paidDateContainer = byId('freelancePaidDateContainer');
        const paidDateInput = byId('freelancePaidDate');
        if (paidDateContainer) {
          if (e.target.value === 'paid') {
            paidDateContainer.classList.remove('hidden');
            if (paidDateInput && !paidDateInput.value) {
              paidDateInput.value = byId('freelanceDueDate').value || new Date().toISOString().split('T')[0];
            }
          } else {
            paidDateContainer.classList.add('hidden');
          }
        }
      });
    }

    showProjectModal = () => {
      if (modalProj) {
        modalProj.classList.remove('hidden');
        modalProj.classList.add('flex');
        lucide.createIcons();
        byId('freelanceClient').focus();
      }
    };

    hideProjectModal = () => {
      if (modalProj) {
        modalProj.classList.add('hidden');
        modalProj.classList.remove('flex');
      }
    };

    window.resetProjectForm = resetProjectForm;
    window.showProjectModal = showProjectModal;
    window.hideProjectModal = hideProjectModal;

    if (openAddProj) openAddProj.addEventListener('click', () => { resetProjectForm(); showProjectModal(); });
    if (emptyAddProj) emptyAddProj.addEventListener('click', () => { resetProjectForm(); showProjectModal(); });
    if (closeProjModal) closeProjModal.addEventListener('click', hideProjectModal);
    if (cancelProjModal) cancelProjModal.addEventListener('click', hideProjectModal);

    // Proforma Invoice Attachment inside Project Modal
    const uploadProformaBtn = byId('freelanceUploadProformaBtn');
    const proformaInput = byId('freelanceProformaFileInput');
    if (uploadProformaBtn && proformaInput) {
      uploadProformaBtn.addEventListener('click', () => proformaInput.click());
      proformaInput.addEventListener('change', (e) => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        const isImage = file.type.startsWith('image/');
        const isPdf = file.type === 'application/pdf' || file.name.endsWith('.pdf');
        reader.onload = (re) => {
          state.projectProformaRemoved = false;
          state.pendingProjectProformaAttachment = {
            type: isImage ? 'image' : isPdf ? 'pdf' : 'text',
            mimeType: file.type || 'application/octet-stream',
            fileName: file.name,
            data: re.target.result
          };
          if (byId('freelanceProformaFileName')) byId('freelanceProformaFileName').textContent = file.name;
          if (byId('freelanceProformaStatusBadge')) {
            byId('freelanceProformaStatusBadge').textContent = 'Attached';
            byId('freelanceProformaStatusBadge').className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-indigo-100 text-indigo-800';
          }
          if (byId('freelanceProformaAttachedView')) byId('freelanceProformaAttachedView').classList.remove('hidden');
          if (byId('freelanceProformaUploadView')) byId('freelanceProformaUploadView').classList.add('hidden');
        };
        if (isImage || isPdf) reader.readAsDataURL(file);
        else reader.readAsText(file);
        e.target.value = '';
      });
    }

    const removeProformaBtn = byId('freelanceRemoveProformaBtn');
    if (removeProformaBtn) {
      removeProformaBtn.addEventListener('click', async () => {
        state.pendingProjectProformaAttachment = null;
        state.projectProformaRemoved = true;
        const editId = byId('freelanceProjectId').value;
        if (editId) {
          await deleteReceiptAttachment(`${editId}_proforma`);
          const p = (state.budget.projects || []).find(x => x.id === editId);
          if (p) {
            p.hasProformaDoc = false;
            p.proformaDocName = '';
            delete p.proformaDoc;
          }
          saveBudget();
          renderBudgetView();
        }
        if (byId('freelanceProformaAttachedView')) byId('freelanceProformaAttachedView').classList.add('hidden');
        if (byId('freelanceProformaUploadView')) byId('freelanceProformaUploadView').classList.remove('hidden');
        if (byId('freelanceProformaStatusBadge')) {
          byId('freelanceProformaStatusBadge').textContent = 'No document attached';
          byId('freelanceProformaStatusBadge').className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-slate-200 text-slate-700';
        }
        if (byId('freelanceProformaFileName')) byId('freelanceProformaFileName').textContent = '';
      });
    }

    const viewProformaBtn = byId('freelanceViewProformaBtn');
    if (viewProformaBtn) {
      viewProformaBtn.addEventListener('click', async () => {
        if (state.pendingProjectProformaAttachment) {
          openReceiptViewerDirect({
            type: state.pendingProjectProformaAttachment.type,
            data: state.pendingProjectProformaAttachment.data,
            fileName: state.pendingProjectProformaAttachment.fileName,
            title: `Proforma: ${state.pendingProjectProformaAttachment.fileName}`
          });
        } else {
          const editId = byId('freelanceProjectId').value;
          if (editId) {
            await openReceiptViewer(`${editId}_proforma`);
          }
        }
      });
    }

    // Document Attachment inside Project Modal
    const uploadDocBtn = byId('freelanceUploadDocBtn');
    const docInput = byId('freelanceDocFileInput');
    if (uploadDocBtn && docInput) {
      uploadDocBtn.addEventListener('click', () => docInput.click());
      docInput.addEventListener('change', (e) => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        const isImage = file.type.startsWith('image/');
        const isPdf = file.type === 'application/pdf' || file.name.endsWith('.pdf');
        reader.onload = (re) => {
          state.projectDocRemoved = false;
          state.pendingProjectAttachment = {
            type: isImage ? 'image' : isPdf ? 'pdf' : 'text',
            mimeType: file.type || 'application/octet-stream',
            fileName: file.name,
            data: re.target.result
          };
          byId('freelanceDocFileName').textContent = file.name;
          byId('freelanceDocStatusBadge').textContent = 'Attached';
          byId('freelanceDocStatusBadge').className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-blue-100 text-blue-800';
          byId('freelanceDocAttachedView').classList.remove('hidden');
          byId('freelanceDocUploadView').classList.add('hidden');
        };
        if (isImage || isPdf) reader.readAsDataURL(file);
        else reader.readAsText(file);
        e.target.value = '';
      });
    }

    const removeDocBtn = byId('freelanceRemoveDocBtn');
    if (removeDocBtn) {
      removeDocBtn.addEventListener('click', async () => {
        state.pendingProjectAttachment = null;
        state.projectDocRemoved = true;
        const editId = byId('freelanceProjectId').value;
        if (editId) {
          await deleteReceiptAttachment(editId);
          await deleteReceiptAttachment(`${editId}_receipt`);
          await deleteReceiptAttachment(`${editId}_invoice`);
          const p = (state.budget.projects || []).find(x => x.id === editId);
          if (p) {
            p.hasInvoiceDoc = false;
            p.hasReceiptDoc = false;
            p.invoiceDocName = '';
            p.receiptDocName = '';
            delete p.invoiceDoc;
          }
          saveBudget();
          renderBudgetView();
        }
        byId('freelanceDocAttachedView').classList.add('hidden');
        byId('freelanceDocUploadView').classList.remove('hidden');
        byId('freelanceDocStatusBadge').textContent = 'No document attached';
        byId('freelanceDocStatusBadge').className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-slate-200 text-slate-700';
        if (byId('freelanceDocFileName')) byId('freelanceDocFileName').textContent = '';
      });
    }

    const viewDocBtn = byId('freelanceViewDocBtn');
    if (viewDocBtn) {
      viewDocBtn.addEventListener('click', async () => {
        if (state.pendingProjectAttachment) {
          openReceiptViewerDirect({
            type: state.pendingProjectAttachment.type,
            data: state.pendingProjectAttachment.data,
            fileName: state.pendingProjectAttachment.fileName,
            title: `Receipt: ${state.pendingProjectAttachment.fileName}`
          });
        } else {
          const editId = byId('freelanceProjectId').value;
          if (editId) {
            await openReceiptViewer(editId);
          }
        }
      });
    }

    // Submit Project Form
    const projForm = byId('freelanceProjectForm');
    if (projForm) {
      projForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const id = byId('freelanceProjectId').value || ('proj_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4));
        const client = byId('freelanceClient').value.trim();
        const description = byId('freelanceProjectTitle').value.trim();
        const amount = parseFloat(byId('freelanceAmount').value) || 0;
        const currency = byId('freelanceCurrency').value || 'EUR';
        const receiptNumber = byId('freelanceReceiptNumber') ? byId('freelanceReceiptNumber').value.trim() : '';
        const invoiceNumber = byId('freelanceInvoiceNumber').value.trim();
        const dueDate = byId('freelanceDueDate').value;
        const status = byId('freelanceStatus').value;
        const paidDateInput = byId('freelancePaidDate');
        let existing = (state.budget.projects || []).find(p => p.id === id);
        const paidDate = (status === 'paid')
          ? ((paidDateInput && paidDateInput.value) || (existing && existing.paidDate) || dueDate || new Date().toISOString().split('T')[0])
          : '';
        const notes = byId('freelanceNotes').value.trim();
        let hasDoc = existing ? (state.projectDocRemoved ? false : !!(existing.hasInvoiceDoc || existing.hasReceiptDoc)) : false;
        let hasReceiptDoc = existing ? (state.projectDocRemoved ? false : !!existing.hasReceiptDoc) : false;
        let receiptDocName = (hasReceiptDoc && existing) ? (existing.receiptDocName || '') : '';
        let hasProformaDoc = existing ? (state.projectProformaRemoved ? false : !!existing.hasProformaDoc) : false;
        let proformaDocName = (hasProformaDoc && existing) ? (existing.proformaDocName || '') : '';
        let invoiceDocName = (hasDoc && existing) ? (existing.invoiceDocName || existing.receiptDocName || '') : '';

        if (state.projectDocRemoved) {
          hasDoc = false;
          hasReceiptDoc = false;
          invoiceDocName = '';
          receiptDocName = '';
          if (existing) {
            existing.hasInvoiceDoc = false;
            existing.hasReceiptDoc = false;
            existing.invoiceDocName = '';
            existing.receiptDocName = '';
            delete existing.invoiceDoc;
          }
          await deleteReceiptAttachment(id);
          await deleteReceiptAttachment(`${id}_receipt`);
          await deleteReceiptAttachment(`${id}_invoice`);
        }

        if (state.projectProformaRemoved) {
          hasProformaDoc = false;
          proformaDocName = '';
          if (existing) {
            existing.hasProformaDoc = false;
            existing.proformaDocName = '';
            delete existing.proformaDoc;
          }
          await deleteReceiptAttachment(`${id}_proforma`);
        }

        // Save proforma attachment to IndexedDB if newly selected
        if (state.pendingProjectProformaAttachment) {
          await saveReceiptAttachment(`${id}_proforma`, state.pendingProjectProformaAttachment);
          hasProformaDoc = true;
          proformaDocName = state.pendingProjectProformaAttachment.fileName;
        }

        // Save receipt attachment to IndexedDB if newly selected
        if (state.pendingProjectAttachment) {
          await saveReceiptAttachment(id, state.pendingProjectAttachment);
          await saveReceiptAttachment(`${id}_receipt`, state.pendingProjectAttachment);
          hasDoc = true;
          hasReceiptDoc = true;
          invoiceDocName = state.pendingProjectAttachment.fileName;
          receiptDocName = state.pendingProjectAttachment.fileName;
        }

        const existingPayments = (existing && Array.isArray(existing.payments))
          ? existing.payments.map(pay => Object.assign({}, pay))
          : [];
        const existingTotalFee = existing ? (parseFloat(existing.amount !== undefined ? existing.amount : existing.fee) || 0) : 0;
        const wasPaid = existing ? (existing.status === 'paid' || ((parseFloat(existing.paidAmount) || 0) >= existingTotalFee && existingTotalFee > 0)) : false;

        let nextPaidAmount = 0;
        let nextPayments = existingPayments;
        const effectivePaidDate = paidDate || dueDate || new Date().toISOString().split('T')[0];

        if (status === 'paid') {
          nextPaidAmount = amount;
          if (nextPayments.length === 0) {
            nextPayments = [{ id: 'pay_init', amount, currency, creditedAmount: amount, date: effectivePaidDate, notes: 'Full fee' }];
          } else if (nextPayments.length === 1 && nextPayments[0].id === 'pay_init') {
            nextPayments[0] = Object.assign({}, nextPayments[0], {
              amount,
              currency,
              creditedAmount: amount,
              date: paidDate || nextPayments[0].date || effectivePaidDate
            });
          } else {
            const sumCredited = nextPayments.reduce((s, pay) => {
              const pAmt = parseFloat(pay.creditedAmount !== undefined ? pay.creditedAmount : pay.amount) || 0;
              return s + pAmt;
            }, 0);
            const diffRem = amount - sumCredited;
            if (diffRem > 0.01) {
              nextPayments.push({
                id: 'pay_' + Date.now(),
                amount: diffRem,
                currency,
                creditedAmount: diffRem,
                date: effectivePaidDate,
                notes: 'Balance settled'
              });
            }
          }
        } else {
          if (wasPaid) {
            // Reverted from paid to invoiced/expected: remove synthetic full-fee payment
            nextPayments = nextPayments.filter(pay => pay.id !== 'pay_init');
          }
          nextPaidAmount = nextPayments.reduce((s, pay) => {
            const pAmt = parseFloat(pay.creditedAmount !== undefined ? pay.creditedAmount : pay.amount) || 0;
            return s + pAmt;
          }, 0);
          // If reverting from paid and remaining manual payments still equal full amount, clear to 0 so it becomes unpaid
          if (wasPaid && nextPaidAmount >= amount) {
            nextPaidAmount = 0;
            nextPayments = [];
          }
        }

        const projectData = {
          id,
          client,
          title: description || (existing ? existing.title : ''),
          description: description || (existing ? existing.description : ''),
          amount,
          fee: amount,
          currency,
          receiptNumber,
          invoiceNumber,
          dueDate,
          status,
          paidDate: status === 'paid' ? effectivePaidDate : '',
          paidAmount: nextPaidAmount,
          notes,
          hasInvoiceDoc: hasDoc,
          hasReceiptDoc: hasReceiptDoc,
          hasProformaDoc,
          proformaDocName,
          invoiceDocName,
          receiptDocName,
          createdAt: (existing && existing.createdAt) ? existing.createdAt : new Date().toISOString(),
          steps: existing && Array.isArray(existing.steps) ? existing.steps : getInitialProjectSteps({ amount, status, hasProformaDoc, hasInvoiceDoc: hasDoc }),
          payments: nextPayments
        };

        if (existing) {
          if (!hasDoc) {
            delete existing.invoiceDoc;
            delete projectData.invoiceDoc;
          }
          if (!hasProformaDoc) {
            delete existing.proformaDoc;
            delete projectData.proformaDoc;
          }
          state.budget.projects = state.budget.projects.map(p => p.id === id ? Object.assign(p, projectData) : p);
          showToast('Project Updated', `${client} invoice details saved.`, 'success');
        } else {
          state.budget.projects.unshift(projectData);
          showToast('Project Added', `${client} added to freelance receivables.`, 'success');
        }

        saveBudget();
        hideProjectModal();
        renderBudgetView();
        renderProjectFollowupView();
      });
    }

    // Delete Project Button
    const deleteProjBtn = byId('deleteFreelanceProjectBtn');
    if (deleteProjBtn) {
      deleteProjBtn.addEventListener('click', async () => {
        const id = byId('freelanceProjectId').value;
        if (!id) return;
        if (await confirmAction('Delete this freelance project and remove its invoices?')) {
          state.budget.projects = (state.budget.projects || []).filter(p => p.id !== id);
          await deleteReceiptAttachment(id);
          await deleteReceiptAttachment(`${id}_proforma`);
          saveBudget();
          hideProjectModal();
          renderBudgetView();
          renderProjectFollowupView();
          showToast('Project Deleted', 'Project removed.', 'info');
        }
      });
    }

    // 4. Projects Grid Delegation (View Invoice, Attach, Edit, Delete, Log Payment)
    function openEditProjectModalById(id) {
      const proj = (state.budget.projects || []).find(p => p.id === id);
      if (!proj) return;
      resetProjectForm();
      byId('freelanceProjectId').value = proj.id;
      byId('freelanceClient').value = proj.client || '';
      byId('freelanceProjectTitle').value = proj.title || proj.description || '';
      const totalFee = parseFloat(proj.amount !== undefined ? proj.amount : proj.fee) || 0;
      const paidAmt = parseFloat(proj.paidAmount) || 0;
      const isPaidProj = proj.status === 'paid' || (paidAmt >= totalFee && totalFee > 0);
      byId('freelanceAmount').value = proj.amount !== undefined ? proj.amount : proj.fee;
      byId('freelanceCurrency').value = proj.currency || state.displayCurrency || 'EUR';
      if (byId('freelanceReceiptNumber')) byId('freelanceReceiptNumber').value = proj.receiptNumber || '';
      byId('freelanceInvoiceNumber').value = proj.invoiceNumber || '';
      byId('freelanceDueDate').value = proj.dueDate || '';
      const normalizedStatus = isPaidProj
        ? 'paid'
        : (proj.status === 'expected' ? 'expected' : 'invoiced');
      byId('freelanceStatus').value = normalizedStatus;
      byId('freelanceNotes').value = proj.notes || '';
      byId('freelanceModalTitle').textContent = `Edit "${proj.client}"`;
      byId('deleteFreelanceProjectBtn').classList.remove('hidden');

      const paidDateContainer = byId('freelancePaidDateContainer');
      const paidDateInput = byId('freelancePaidDate');
      if (paidDateContainer && paidDateInput) {
        if (isPaidProj) {
          paidDateContainer.classList.remove('hidden');
          paidDateInput.value = getProjectPaidDate(proj) || new Date().toISOString().split('T')[0];
        } else {
          paidDateContainer.classList.add('hidden');
          paidDateInput.value = proj.paidDate || proj.dueDate || new Date().toISOString().split('T')[0];
        }
      }
      if (proj.hasProformaDoc) {
        byId('freelanceProformaStatusBadge').textContent = 'Attached';
        byId('freelanceProformaStatusBadge').className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-indigo-100 text-indigo-800';
        byId('freelanceProformaAttachedView').classList.remove('hidden');
        byId('freelanceProformaUploadView').classList.add('hidden');
        byId('freelanceProformaFileName').textContent = 'Loading file...';
        getReceiptAttachment(`${proj.id}_proforma`).then(att => {
          if (att && att.fileName) {
            byId('freelanceProformaFileName').textContent = att.fileName;
          } else if (proj.proformaDocName) {
            byId('freelanceProformaFileName').textContent = proj.proformaDocName;
          } else {
            byId('freelanceProformaFileName').textContent = 'proforma.pdf';
          }
        }).catch(() => {
          byId('freelanceProformaFileName').textContent = 'proforma.pdf';
        });
      }
      const hasAnyReceiptDoc = !!(proj.hasInvoiceDoc || proj.hasReceiptDoc);
      if (hasAnyReceiptDoc) {
        byId('freelanceDocStatusBadge').textContent = 'Attached';
        byId('freelanceDocStatusBadge').className = 'text-[10px] font-semibold px-2 py-0.5 rounded-md bg-blue-100 text-blue-800';
        byId('freelanceDocAttachedView').classList.remove('hidden');
        byId('freelanceDocUploadView').classList.add('hidden');
        byId('freelanceDocFileName').textContent = 'Loading file...';
        (async () => {
          let att = await getReceiptAttachment(proj.id);
          if (!att || !att.data) att = await getReceiptAttachment(`${proj.id}_receipt`);
          if (!att || !att.data) att = await getReceiptAttachment(`${proj.id}_invoice`);
          if (att && att.fileName) {
            byId('freelanceDocFileName').textContent = att.fileName;
          } else if (proj.receiptDocName) {
            byId('freelanceDocFileName').textContent = proj.receiptDocName;
          } else if (proj.invoiceDocName) {
            byId('freelanceDocFileName').textContent = proj.invoiceDocName;
          } else if (proj.invoiceDoc && proj.invoiceDoc.fileName) {
            byId('freelanceDocFileName').textContent = proj.invoiceDoc.fileName;
          } else {
            byId('freelanceDocFileName').textContent = 'receipt.pdf';
          }
        })().catch(() => {
          byId('freelanceDocFileName').textContent = 'receipt.pdf';
        });
      }
      showProjectModal();
    }

    const projGrid = byId('freelanceProjectsGrid');
    if (projGrid) {
      projGrid.addEventListener('click', async (e) => {
        const card = e.target.closest('[data-id]');
        if (!card) return;
        const id = card.getAttribute('data-id');
        const proj = (state.budget.projects || []).find(p => p.id === id);
        if (!proj) return;

        // A. View Receipt / Invoice
        if (e.target.closest('.view-project-invoice-btn')) {
          await openReceiptViewer(id);
          return;
        }

        // A2. View Proforma Invoice
        if (e.target.closest('.view-project-proforma-btn')) {
          if (proj && proj.proformaInvoice) {
            openProjectProformaDocPage(id);
          } else {
            await openReceiptViewer(`${id}_proforma`);
          }
          return;
        }

        // B. Attach Invoice
        if (e.target.closest('.attach-project-invoice-btn')) {
          openEditProjectModalById(id);
          if (docInput) docInput.click();
          return;
        }

        // C. Edit Project
        if (e.target.closest('.edit-freelance-proj-btn')) {
          openEditProjectModalById(id);
          return;
        }

        // D. Delete Project
        if (e.target.closest('.delete-freelance-proj-btn')) {
          if (await confirmAction(`Delete project "${proj.client}"?`)) {
            state.budget.projects = state.budget.projects.filter(p => p.id !== id);
            await deleteReceiptAttachment(id);
            await deleteReceiptAttachment(`${id}_proforma`);
            saveBudget();
            renderBudgetView();
            showToast('Project Removed', `${proj.client} deleted.`, 'info');
          }
          return;
        }

        // E. Log Payment
        if (e.target.closest('.log-project-payment-btn')) {
          openRecordPaymentModal(proj);
          return;
        }
      });
    }

    // 5. Record Client Payment Modal
    const modalPayment = byId('logProjectPaymentModal');
    const closePayModal = byId('closeProjectPaymentModalBtn');
    const cancelPayModal = byId('cancelProjectPaymentBtn');
    const payForm = byId('projectPaymentForm');

    if (closePayModal) closePayModal.addEventListener('click', hidePaymentModal);
    if (cancelPayModal) cancelPayModal.addEventListener('click', hidePaymentModal);
    if (modalPayment) modalPayment.addEventListener('click', (e) => { if (e.target === modalPayment) hidePaymentModal(); });

    const payCurSelect = byId('paymentCurrency');
    if (payCurSelect) {
      payCurSelect.addEventListener('change', () => {
        const prevCur = payCurSelect.dataset.prevCur || 'EUR';
        const newCur = payCurSelect.value;
        const amtInput = byId('paymentAmount');
        if (amtInput && amtInput.value) {
          const curVal = parseFloat(amtInput.value) || 0;
          if (curVal > 0 && prevCur !== newCur) {
            amtInput.value = convertCurrency(curVal, prevCur, newCur).toFixed(2);
          }
        }
        payCurSelect.dataset.prevCur = newCur;
        updatePaymentConversionPreview();
      });
    }

    const payAmtInput = byId('paymentAmount');
    if (payAmtInput) {
      payAmtInput.addEventListener('input', updatePaymentConversionPreview);
    }

    if (payForm) {
      payForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const projId = byId('paymentProjectId').value;
        const proj = (state.budget.projects || []).find(p => p.id === projId);
        if (!proj) return;

        const payAmt = parseFloat(byId('paymentAmount').value) || 0;
        if (payAmt <= 0) {
          alert('Please enter a payment amount greater than zero.');
          return;
        }

        const payCur = byId('paymentCurrency') ? byId('paymentCurrency').value : (proj.currency || 'EUR');
        const projCur = proj.currency || 'EUR';
        const credAmt = (payCur === projCur) ? payAmt : convertCurrency(payAmt, payCur, projCur);

        const payDate = byId('paymentDate').value || new Date().toISOString().split('T')[0];
        const payNotes = byId('paymentNotes').value.trim() || 'Client payment';
        const method = byId('paymentMethod').value;

        // Record payment in project
        if (!Array.isArray(proj.payments)) proj.payments = [];
        proj.payments.push({
          id: 'pay_' + Date.now(),
          amount: payAmt,
          currency: payCur,
          creditedAmount: credAmt,
          date: payDate,
          method,
          notes: payNotes
        });

        proj.paidAmount = (parseFloat(proj.paidAmount) || 0) + credAmt;
        const totalFee = parseFloat(proj.amount !== undefined ? proj.amount : proj.fee) || 0;
        if (proj.paidAmount >= totalFee) {
          proj.paidDate = payDate;
          if (proj.status === 'draft') proj.status = 'invoiced';
        }

        if (Array.isArray(proj.steps)) {
          const depStep = proj.steps.find(s => s.id === 'step_deposit' || s.title.toLowerCase().includes('deposit'));
          if (depStep) {
            depStep.completed = true;
            if (!depStep.completedDate) depStep.completedDate = payDate;
          }
          if (proj.paidAmount >= totalFee) {
            const payStep = proj.steps.find(s => s.id === 'step_payment' || s.title.toLowerCase().includes('payment') || s.title.toLowerCase().includes('got money') || s.title.toLowerCase().includes('got final payment'));
            if (payStep) {
              payStep.completed = true;
              payStep.completedDate = payDate;
            }
          }
        }

        saveBudget();
        hidePaymentModal();
        renderBudgetView();
        renderProjectFollowupView();
        showToast('Payment Recorded! 💰', `+${formatMoney(payAmt, payCur)} deposited from ${proj.client}`, 'success');
      });
    }

    // 6. Misc Income Section & Modal Handlers
    const modalMiscIncome = byId('miscIncomeModal');
    const openAddMiscIncomeBtn = byId('openAddMiscIncomeBtn');
    const emptyAddMiscIncomeBtn = byId('emptyAddMiscIncomeBtn');
    const closeMiscIncomeModalBtn = byId('closeMiscIncomeModalBtn');
    const cancelMiscIncomeBtn = byId('cancelMiscIncomeBtn');
    const miscIncomeForm = byId('miscIncomeForm');
    const deleteMiscIncomeBtn = byId('deleteMiscIncomeBtn');
    const miscIncomeGrid = byId('miscIncomeGrid');
    const quickIncBtn = byId('openQuickIncomeBtn');

    const resetMiscIncomeForm = () => {
      if (!miscIncomeForm) return;
      miscIncomeForm.reset();
      byId('miscIncomeId').value = '';
      byId('miscIncomeDate').value = new Date().toISOString().split('T')[0];
      byId('miscIncomeCurrency').value = state.displayCurrency || 'EUR';
      byId('miscIncomeType').value = 'Gift';
      byId('miscIncomeMethod').value = 'Cash';
      byId('miscIncomeModalTitle').textContent = 'Log Misc Income';
      if (deleteMiscIncomeBtn) deleteMiscIncomeBtn.classList.add('hidden');
    };

    const showMiscIncomeModal = () => {
      if (modalMiscIncome) {
        modalMiscIncome.classList.remove('hidden');
        modalMiscIncome.classList.add('flex');
        lucide.createIcons();
        byId('miscIncomeTitle').focus();
      }
    };

    const hideMiscIncomeModal = () => {
      if (modalMiscIncome) {
        modalMiscIncome.classList.add('hidden');
        modalMiscIncome.classList.remove('flex');
      }
    };

    if (openAddMiscIncomeBtn) openAddMiscIncomeBtn.addEventListener('click', () => { resetMiscIncomeForm(); showMiscIncomeModal(); });
    if (emptyAddMiscIncomeBtn) emptyAddMiscIncomeBtn.addEventListener('click', () => { resetMiscIncomeForm(); showMiscIncomeModal(); });
    if (quickIncBtn) quickIncBtn.addEventListener('click', () => { resetMiscIncomeForm(); showMiscIncomeModal(); });
    if (closeMiscIncomeModalBtn) closeMiscIncomeModalBtn.addEventListener('click', hideMiscIncomeModal);
    if (cancelMiscIncomeBtn) cancelMiscIncomeBtn.addEventListener('click', hideMiscIncomeModal);

    if (miscIncomeForm) {
      miscIncomeForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const id = byId('miscIncomeId').value || ('inc_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4));
        const title = byId('miscIncomeTitle').value.trim();
        const amount = parseFloat(byId('miscIncomeAmount').value) || 0;
        const currency = byId('miscIncomeCurrency').value || 'EUR';
        const date = byId('miscIncomeDate').value || new Date().toISOString().split('T')[0];
        const type = byId('miscIncomeType').value || 'Gift';
        const method = byId('miscIncomeMethod').value || 'Cash';
        const notes = byId('miscIncomeNotes').value.trim();

        if (!title || amount <= 0) {
          alert('Please enter a valid source and an amount greater than zero.');
          return;
        }

        if (!state.budget) state.budget = {};
        if (!Array.isArray(state.budget.incomes)) state.budget.incomes = [];

        const existingIdx = state.budget.incomes.findIndex(i => i.id === id);
        const todayStr = new Date().toISOString().split('T')[0];
        const isFuture = date > todayStr;
        const incomeItem = {
          id,
          title,
          amount,
          currency,
          date,
          type,
          category: type,
          method,
          notes,
          status: isFuture ? 'expected' : (existingIdx !== -1 && state.budget.incomes[existingIdx]?.status === 'expected' && date <= todayStr ? 'received' : (existingIdx !== -1 && state.budget.incomes[existingIdx]?.status ? state.budget.incomes[existingIdx].status : 'received'))
        };

        if (existingIdx !== -1) {
          state.budget.incomes[existingIdx] = Object.assign(state.budget.incomes[existingIdx], incomeItem);
          showToast('Income Updated', `${title} details updated.`, 'success');
        } else {
          state.budget.incomes.unshift(incomeItem);
          showToast('Income Logged 💰', `+${formatMoney(amount, currency)} from ${title} recorded.`, 'success');
        }

        saveBudget();
        hideMiscIncomeModal();
        renderBudgetView();
      });
    }

    if (deleteMiscIncomeBtn) {
      deleteMiscIncomeBtn.addEventListener('click', async () => {
        const id = byId('miscIncomeId').value;
        if (!id) return;
        if (await confirmAction('Delete this misc income entry?')) {
          if (state.budget && Array.isArray(state.budget.incomes)) {
            state.budget.incomes = state.budget.incomes.filter(i => i.id !== id);
          }
          saveBudget();
          hideMiscIncomeModal();
          renderBudgetView();
          showToast('Income Deleted', 'Misc income entry removed.', 'info');
        }
      });
    }

    if (miscIncomeGrid) {
      miscIncomeGrid.addEventListener('click', async (e) => {
        const card = e.target.closest('[data-id]');
        if (!card) return;
        const id = card.getAttribute('data-id');
        const inc = (state.budget && Array.isArray(state.budget.incomes)) ? state.budget.incomes.find(i => i.id === id) : null;
        if (!inc) return;

        // Mark Received
        if (e.target.closest('.mark-misc-income-received-btn')) {
          const todayStr = new Date().toISOString().split('T')[0];
          inc.status = 'received';
          inc.date = todayStr;
          saveBudget();
          renderBudgetView();
          showToast('Payment Received 🎉', `"${inc.title}" marked as received today (${todayStr}).`, 'success');
          return;
        }

        // Edit
        if (e.target.closest('.edit-misc-income-btn')) {
          resetMiscIncomeForm();
          byId('miscIncomeId').value = inc.id;
          byId('miscIncomeTitle').value = inc.title || '';
          byId('miscIncomeType').value = inc.type || inc.category || 'Gift';
          byId('miscIncomeAmount').value = inc.amount;
          byId('miscIncomeCurrency').value = inc.currency || 'EUR';
          byId('miscIncomeDate').value = inc.date || '';
          byId('miscIncomeMethod').value = inc.method || 'Cash';
          byId('miscIncomeNotes').value = inc.notes || '';
          byId('miscIncomeModalTitle').textContent = `Edit "${inc.title}"`;
          if (deleteMiscIncomeBtn) deleteMiscIncomeBtn.classList.remove('hidden');
          showMiscIncomeModal();
          return;
        }

        // Delete
        if (e.target.closest('.delete-misc-income-btn')) {
          if (await confirmAction(`Delete misc income from "${inc.title}"?`)) {
            state.budget.incomes = state.budget.incomes.filter(i => i.id !== id);
            saveBudget();
            renderBudgetView();
            showToast('Income Deleted', 'Entry removed.', 'info');
          }
          return;
        }
      });
    }

    // 7. Edit / Customize Category Modal & Icon Picker
    const modalEditCategory = byId('editCategoryModal');
    const closeEditCategoryBtn = byId('closeEditCategoryModalBtn');
    const cancelEditCategoryBtn = byId('cancelEditCategoryBtn');
    const editCategoryForm = byId('editCategoryForm');
    const deleteCategoryBtn = byId('deleteCategoryBtn');
    const iconPickerGrid = byId('categoryIconPickerGrid');
    const colorPickerRow = byId('categoryColorPickerRow');

    const updateExpenseCategoryDropdown = () => {
      const select = byId('expenseCategory');
      if (!select) return;
      const curVal = select.value;
      const allCats = (state.budget && Array.isArray(state.budget.categories)) ? state.budget.categories : DEFAULT_BUDGET_CATEGORIES;
      const fixed = [
        { name: 'Monthly Expenses', label: '🗓️ Monthly Expenses' },
        { name: 'Utilities', label: '💡 Utilities & Bills' },
        { name: 'Housing', label: '🏠 Housing & Rent' }
      ];
      
      let html = fixed.map(f => `<option value="${f.name}">${f.label}</option>`).join('');
      allCats.forEach(c => {
        if (!['Subscriptions', 'Utilities', 'Housing'].includes(c.name)) {
          html += `<option value="${escapeHtml(c.name)}">${escapeHtml(c.name)}</option>`;
        }
      });
      select.innerHTML = html;
      if (curVal) select.value = curVal;
    };

    const renderIconPicker = (currentIcon) => {
      if (!iconPickerGrid) return;
      iconPickerGrid.innerHTML = BUDGET_CATEGORY_ICONS.map(item => {
        const isSelected = item.id === currentIcon;
        return `
          <button type="button" class="icon-pick-btn flex flex-col items-center justify-center p-2 rounded-xl transition-all cursor-pointer ${isSelected ? 'bg-indigo-600 text-white shadow-xs scale-105' : 'bg-white hover:bg-slate-100 text-slate-700 border border-slate-200/80'}" data-icon="${item.id}" data-label="${item.label}" title="${item.label}">
            <i data-lucide="${item.id}" class="w-4 h-4"></i>
            <span class="text-[9px] mt-1 truncate max-w-full font-medium ${isSelected ? 'text-indigo-100' : 'text-slate-500'}">${item.label}</span>
          </button>
        `;
      }).join('');
    };

    const renderColorPicker = (currentColor) => {
      if (!colorPickerRow) return;
      colorPickerRow.innerHTML = BUDGET_CATEGORY_COLORS.map(c => {
        const isSelected = c.toLowerCase() === (currentColor || '').toLowerCase();
        return `
          <button type="button" class="color-pick-btn w-6 h-6 rounded-full transition-all cursor-pointer ${isSelected ? 'ring-2 ring-offset-2 ring-indigo-600 scale-110' : 'hover:scale-105 opacity-80 hover:opacity-100'}" style="background-color:${c};" data-color="${c}" title="${c}"></button>
        `;
      }).join('');
    };

    const updateEditCategoryPreview = (icon, color) => {
      const preview = byId('editCategoryHeaderPreview');
      const iconEl = byId('editCategoryHeaderIcon');
      if (preview) {
        preview.style.backgroundColor = `${color}18`;
        preview.style.color = color;
        preview.style.borderColor = `${color}40`;
      }
      if (iconEl) {
        iconEl.setAttribute('data-lucide', icon);
      }
      lucide.createIcons();
    };

    const showEditCategoryModal = (catName = '') => {
      if (!modalEditCategory) return;
      const isNew = !catName;
      const categories = state.budget.categories || [];
      const catObj = categories.find(c => c.name.toLowerCase() === catName.toLowerCase()) || {
        id: 'cat_' + Date.now(),
        name: '',
        icon: 'tag',
        color: '#6366f1',
        limit: 0
      };

      const limitCurrency = catObj.currency || state.budget.incomeCurrency || 'EUR';
      const cur = state.displayCurrency || 'EUR';
      const convertedLimit = catObj.limit > 0 ? (Math.round(convertCurrency(catObj.limit, limitCurrency, cur) * 100) / 100) : '';

      byId('editCategoryId').value = catObj.id || ('cat_' + Date.now());
      byId('editCategoryOriginalName').value = catName;
      byId('editCategoryNameInput').value = catObj.name || '';
      byId('editCategoryLimitInput').value = convertedLimit !== '' ? convertedLimit : '';
      byId('editCategoryIconValue').value = catObj.icon || 'tag';
      byId('editCategoryColorValue').value = catObj.color || '#6366f1';
      byId('editCategoryCurrencyBadge').textContent = cur;
      byId('editCategoryModalTitle').textContent = isNew ? 'Create New Category' : `Edit "${catObj.name}"`;

      if (deleteCategoryBtn) {
        if (!isNew && categories.length > 1) {
          deleteCategoryBtn.classList.remove('hidden');
        } else {
          deleteCategoryBtn.classList.add('hidden');
        }
      }

      const iconLabel = (BUDGET_CATEGORY_ICONS.find(i => i.id === catObj.icon) || {}).label || catObj.icon;
      if (byId('selectedIconLabel')) byId('selectedIconLabel').textContent = iconLabel;

      renderIconPicker(catObj.icon || 'tag');
      renderColorPicker(catObj.color || '#6366f1');
      updateEditCategoryPreview(catObj.icon || 'tag', catObj.color || '#6366f1');

      modalEditCategory.classList.remove('hidden');
      modalEditCategory.classList.add('flex');
      lucide.createIcons();
      byId('editCategoryNameInput').focus();
    };

    const hideEditCategoryModal = () => {
      if (modalEditCategory) {
        modalEditCategory.classList.add('hidden');
        modalEditCategory.classList.remove('flex');
      }
    };

    if (closeEditCategoryBtn) closeEditCategoryBtn.addEventListener('click', hideEditCategoryModal);
    if (cancelEditCategoryBtn) cancelEditCategoryBtn.addEventListener('click', hideEditCategoryModal);

    // Icon & Color Selection Delegation
    if (iconPickerGrid) {
      iconPickerGrid.addEventListener('click', (e) => {
        const btn = e.target.closest('.icon-pick-btn');
        if (!btn) return;
        const icon = btn.getAttribute('data-icon');
        const label = btn.getAttribute('data-label');
        byId('editCategoryIconValue').value = icon;
        if (byId('selectedIconLabel')) byId('selectedIconLabel').textContent = label;
        renderIconPicker(icon);
        updateEditCategoryPreview(icon, byId('editCategoryColorValue').value);
      });
    }

    if (colorPickerRow) {
      colorPickerRow.addEventListener('click', (e) => {
        const btn = e.target.closest('.color-pick-btn');
        if (!btn) return;
        const color = btn.getAttribute('data-color');
        byId('editCategoryColorValue').value = color;
        renderColorPicker(color);
        updateEditCategoryPreview(byId('editCategoryIconValue').value, color);
      });
    }

    // Save Category Form Handler
    if (editCategoryForm) {
      editCategoryForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const origName = byId('editCategoryOriginalName').value.trim();
        const newName = byId('editCategoryNameInput').value.trim();
        const icon = byId('editCategoryIconValue').value;
        const color = byId('editCategoryColorValue').value;
        const limitVal = parseFloat(byId('editCategoryLimitInput').value) || 0;
        const catId = byId('editCategoryId').value;

        if (!newName) {
          alert('Please enter a category name.');
          return;
        }

        if (!Array.isArray(state.budget.categories)) {
          state.budget.categories = JSON.parse(JSON.stringify(DEFAULT_BUDGET_CATEGORIES));
        }

        // Check duplicates if renaming
        const existingWithNewName = state.budget.categories.find(c => c.name.toLowerCase() === newName.toLowerCase() && c.name.toLowerCase() !== origName.toLowerCase());
        if (existingWithNewName) {
          alert(`A category named "${newName}" already exists. Please choose a different name.`);
          return;
        }

        const isRenaming = origName && origName.toLowerCase() !== newName.toLowerCase();

        const cur = state.displayCurrency || state.budget.incomeCurrency || 'EUR';

        if (origName) {
          // Editing existing category
          const found = state.budget.categories.find(c => c.name.toLowerCase() === origName.toLowerCase());
          if (found) {
            found.name = newName;
            found.icon = icon;
            found.color = color;
            found.limit = limitVal;
            found.currency = cur;
          } else {
            state.budget.categories.push({ id: catId, name: newName, icon, color, limit: limitVal, currency: cur });
          }

          // If renamed, update past expenses
          if (isRenaming) {
            (state.expenses || []).forEach(exp => {
              if ((exp.category || '').toLowerCase() === origName.toLowerCase()) {
                exp.category = newName;
              }
            });
            saveExpenses();
            if (state.budget.categoryBudgets) {
              delete state.budget.categoryBudgets[origName];
            }
          }
        } else {
          // Creating brand new category
          state.budget.categories.push({ id: catId, name: newName, icon, color, limit: limitVal, currency: cur });
        }

        if (!state.budget.categoryBudgets) state.budget.categoryBudgets = {};
        state.budget.categoryBudgets[newName] = limitVal;

        saveBudget();
        hideEditCategoryModal();
        syncCategoryDropdowns();
        renderBudgetInputs();
        renderBudgetView();
        showToast('Category Saved! ✨', `"${newName}" customized with chosen icon.`, 'success');
      });
    }

    // Delete Category Button Handler
    if (deleteCategoryBtn) {
      deleteCategoryBtn.addEventListener('click', async () => {
        const origName = byId('editCategoryOriginalName').value.trim();
        if (!origName) return;
        if (await confirmAction(`Delete the category "${origName}"? Any existing transactions will stay in your ledger.`)) {
          state.budget.categories = (state.budget.categories || []).filter(c => c.name.toLowerCase() !== origName.toLowerCase());
          if (state.budget.categoryBudgets) {
            delete state.budget.categoryBudgets[origName];
          }
          saveBudget();
          hideEditCategoryModal();
          syncCategoryDropdowns();
          renderBudgetInputs();
          renderBudgetView();
          showToast('Category Removed', `"${origName}" removed from budget envelopes.`, 'info');
        }
      });
    }

    // Buttons to open "+ New Category"
    const openAddCategoryBtn = byId('openAddCategoryBtn');
    if (openAddCategoryBtn) openAddCategoryBtn.addEventListener('click', () => showEditCategoryModal(''));
    const modalAddNewCatBtn = byId('modalAddNewCategoryBtn');
    if (modalAddNewCatBtn) modalAddNewCatBtn.addEventListener('click', () => {
      hideBudgetsModal();
      showEditCategoryModal('');
    });

    // 8. Adjust Budgets & Tax Modal
    const modalBudgets = byId('adjustCategoryBudgetsModal');
    const openBudgetsBtn = byId('openAdjustBudgetsBtn');
    const closeBudgetsBtn = byId('closeAdjustBudgetsModalBtn');
    const cancelBudgetsBtn = byId('cancelAdjustBudgetsBtn');
    const saveBudgetsBtn = byId('saveCategoryBudgetsBtn');
    const taxRange = byId('taxReserveRange');
    const taxNumInput = byId('taxReserveNumberInput');
    const taxDisplay = byId('taxReserveDisplayVal');
    const presetPillsContainer = byId('taxPresetPillsContainer');
    const autoCalcBtn = byId('autoCalculateBudgetsBtn');
    const modalAutoSuggestBtn = byId('modalAutoSuggestBudgetsBtn');

    const updateTaxDisplayAndPills = (val) => {
      const numVal = parseInt(val, 10);
      const safeVal = isNaN(numVal) ? 0 : Math.max(0, numVal);
      if (taxRange) taxRange.value = safeVal;
      if (taxNumInput) taxNumInput.value = safeVal;
      if (taxDisplay) taxDisplay.textContent = `${safeVal}%`;

      if (presetPillsContainer) {
        presetPillsContainer.querySelectorAll('.tax-preset-pill').forEach(btn => {
          const rate = parseInt(btn.getAttribute('data-rate'), 10);
          if (rate === safeVal) {
            btn.classList.add('bg-indigo-600', 'text-white', 'border-indigo-600');
            btn.classList.remove('bg-white', 'text-indigo-700', 'border-indigo-200');
          } else {
            btn.classList.remove('bg-indigo-600', 'text-white', 'border-indigo-600');
            btn.classList.add('bg-white', 'text-indigo-700', 'border-indigo-200');
          }
        });
      }
    };

    const renderBudgetInputs = () => {
      const container = byId('categoryBudgetInputsContainer');
      if (!container) return;
      const categories = state.budget.categories || [];
      const cur = state.displayCurrency;

      container.innerHTML = categories.map(catObj => {
        const cat = catObj.name;
        const rawVal = catObj.limit > 0 ? catObj.limit : (state.budget.categoryBudgets[cat] || 0);
        const limitCurrency = catObj.currency || state.budget.incomeCurrency || 'EUR';
        const convertedVal = rawVal > 0 ? (Math.round(convertCurrency(rawVal, limitCurrency, cur) * 100) / 100) : '';
        const color = catObj.color || getCategoryColor(cat);
        const icon = catObj.icon || getCategoryLucideIcon(cat);

        return `
          <div class="flex items-center justify-between gap-2 p-2 rounded-xl bg-slate-50 border border-slate-200/80 group">
            <div class="flex items-center gap-2 min-w-0 flex-1">
              <button type="button" class="modal-inline-edit-cat-btn w-6 h-6 rounded-lg flex items-center justify-center shrink-0 cursor-pointer hover:ring-2 hover:ring-indigo-300 transition-all" style="background-color:${color}20;color:${color};" data-cat="${escapeHtml(cat)}" title="Customize icon & name">
                <i data-lucide="${icon}" class="w-3.5 h-3.5"></i>
              </button>
              <span class="text-xs font-semibold text-slate-800 truncate">${escapeHtml(cat)}</span>
              <button type="button" class="modal-inline-edit-cat-btn text-slate-300 hover:text-indigo-600 p-0.5 cursor-pointer ml-auto shrink-0" data-cat="${escapeHtml(cat)}" title="Edit Name & Icon">
                <i data-lucide="edit-3" class="w-3 h-3"></i>
              </button>
            </div>
            <div class="flex items-center gap-1 shrink-0 w-24">
              <span class="text-xs text-slate-400 font-mono">${CURRENCY_SYMBOLS[cur] || cur}</span>
              <input type="number" step="any" min="0" placeholder="0" class="cat-budget-input w-full bg-white border border-slate-300 rounded-lg px-2 py-1 text-xs text-slate-900 font-mono text-right focus:outline-none" data-cat="${escapeHtml(cat)}" value="${convertedVal}">
            </div>
          </div>
        `;
      }).join('');
    };

    const showBudgetsModal = () => {
      if (!modalBudgets) return;
      const curTax = (state.budget && state.budget.taxReservePercent !== undefined && state.budget.taxReservePercent !== null)
        ? parseInt(state.budget.taxReservePercent, 10)
        : 0;
      const validTax = isNaN(curTax) ? 0 : Math.max(0, curTax);
      updateTaxDisplayAndPills(validTax);
      renderBudgetInputs();
      modalBudgets.classList.remove('hidden');
      modalBudgets.classList.add('flex');
      lucide.createIcons();
    };

    const hideBudgetsModal = () => {
      if (modalBudgets) {
        modalBudgets.classList.add('hidden');
        modalBudgets.classList.remove('flex');
      }
    };

    if (openBudgetsBtn) openBudgetsBtn.addEventListener('click', showBudgetsModal);
    if (closeBudgetsBtn) closeBudgetsBtn.addEventListener('click', hideBudgetsModal);
    if (cancelBudgetsBtn) cancelBudgetsBtn.addEventListener('click', hideBudgetsModal);

    if (modalBudgets) {
      modalBudgets.addEventListener('click', (e) => {
        const btn = e.target.closest('.modal-inline-edit-cat-btn');
        if (btn) {
          const cat = btn.getAttribute('data-cat');
          hideBudgetsModal();
          showEditCategoryModal(cat);
        }
      });
    }

    if (taxRange) {
      taxRange.addEventListener('input', () => {
        updateTaxDisplayAndPills(taxRange.value);
      });
    }

    if (taxNumInput) {
      taxNumInput.addEventListener('input', () => {
        const val = parseInt(taxNumInput.value, 10);
        const safeVal = isNaN(val) ? 0 : Math.max(0, val);
        if (taxRange) taxRange.value = safeVal;
        if (taxDisplay) taxDisplay.textContent = `${safeVal}%`;
        if (presetPillsContainer) {
          presetPillsContainer.querySelectorAll('.tax-preset-pill').forEach(btn => {
            const rate = parseInt(btn.getAttribute('data-rate'), 10);
            if (rate === safeVal) {
              btn.classList.add('bg-indigo-600', 'text-white', 'border-indigo-600');
              btn.classList.remove('bg-white', 'text-indigo-700', 'border-indigo-200');
            } else {
              btn.classList.remove('bg-indigo-600', 'text-white', 'border-indigo-600');
              btn.classList.add('bg-white', 'text-indigo-700', 'border-indigo-200');
            }
          });
        }
      });
      taxNumInput.addEventListener('blur', () => {
        if (taxNumInput.value === '' || isNaN(parseInt(taxNumInput.value, 10))) {
          taxNumInput.value = '0';
          updateTaxDisplayAndPills(0);
        }
      });
    }

    if (presetPillsContainer) {
      presetPillsContainer.addEventListener('click', (e) => {
        const btn = e.target.closest('.tax-preset-pill');
        if (!btn) return;
        const rate = parseInt(btn.getAttribute('data-rate'), 10);
        updateTaxDisplayAndPills(isNaN(rate) ? 0 : rate);
      });
    }

    if (saveBudgetsBtn) {
      saveBudgetsBtn.addEventListener('click', () => {
        const cur = state.displayCurrency || state.budget.incomeCurrency || 'EUR';
        if (!state.budget.categoryBudgets) state.budget.categoryBudgets = {};
        document.querySelectorAll('.cat-budget-input').forEach(input => {
          const cat = input.getAttribute('data-cat');
          const val = parseFloat(input.value) || 0;
          state.budget.categoryBudgets[cat] = val;
          const found = (state.budget.categories || []).find(c => (c.name || '').toLowerCase() === (cat || '').toLowerCase());
          if (found) {
            found.limit = val;
            found.currency = cur;
          } else {
            state.budget.categories.push({
              id: 'cat_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4),
              name: cat,
              icon: getCategoryLucideIcon(cat),
              color: getCategoryColor(cat),
              limit: val,
              currency: cur
            });
          }
        });
        let chosenTax = 0;
        if (taxNumInput && taxNumInput.value !== '') {
          const pt = parseInt(taxNumInput.value, 10);
          chosenTax = isNaN(pt) ? 0 : Math.max(0, pt);
        } else if (taxRange) {
          const pt = parseInt(taxRange.value, 10);
          chosenTax = isNaN(pt) ? 0 : Math.max(0, pt);
        }
        state.budget.taxReservePercent = chosenTax;
        saveBudget();
        hideBudgetsModal();
        renderBudgetView();
        showToast('Budgets Updated', `Category limits and ${chosenTax}% tax reserve saved.`, 'success');
      });
    }

    // Auto-calculate budgets based on past 3-month spending history + current month activity
    const executeAutoSuggestBudgets = () => {
      const cur = state.displayCurrency;
      const monthKey = getBudgetMonthKey();
      const targetMonth = (!monthKey || monthKey === 'ALL' || monthKey === 'all')
        ? monthKeyFromDate(new Date())
        : monthKey;
      const { avgs } = getHistoricalAverages(targetMonth, cur);
      const currentStats = getFlexibleStats(targetMonth, cur);
      if (!state.budget.categoryBudgets) state.budget.categoryBudgets = {};

      let count = 0;
      (state.budget.categories || []).forEach(catObj => {
        const cat = catObj.name;
        const a = avgs[cat] || (avgs && Object.entries(avgs).find(([k]) => k.toLowerCase() === (cat || '').toLowerCase())?.[1]);
        const curStat = findCategoryStats(currentStats, cat);
        const histMonthly = (a && a.monthly > 0) ? a.monthly : 0;
        const curMonthly = (curStat && curStat.total > 0) ? curStat.total : 0;
        const baseline = Math.max(histMonthly, curMonthly);
        if (baseline > 0) {
          // Baseline + 10% safety margin rounded up to nearest 10
          const suggested = Math.ceil((baseline * 1.10) / 10) * 10;
          catObj.limit = suggested;
          catObj.currency = cur;
          state.budget.categoryBudgets[cat] = suggested;
          count++;
        }
      });

      saveBudget();
      renderBudgetInputs();
      renderBudgetView();
      showToast('Smart Budgets Set! ✨', `Auto-calculated ${count} category budgets from your spending patterns.`, 'success');
    };

    if (autoCalcBtn) autoCalcBtn.addEventListener('click', executeAutoSuggestBudgets);
    if (modalAutoSuggestBtn) modalAutoSuggestBtn.addEventListener('click', executeAutoSuggestBudgets);

    // 8. Quick Log Purchase: opens window of this month's transactions
    const quickLogPurchaseModalBtn = byId('openQuickPurchaseModalBtn');
    if (quickLogPurchaseModalBtn) {
      quickLogPurchaseModalBtn.addEventListener('click', () => {
        openBudgetCategoryLogModal();
      });
    }

    // Inline category budget editor buttons on cards & category customization triggers
    const catList = byId('budgetCategoryList');
    if (catList) {
      catList.addEventListener('click', (e) => {
        // 0. New Category Card Button Box
        const addCard = e.target.closest('#newCategoryCardBtn');
        if (addCard) {
          showEditCategoryModal('');
          return;
        }

        // A. Customize category (name, icon, limit)
        const editTrigger = e.target.closest('.edit-category-trigger');
        if (editTrigger) {
          const cat = editTrigger.getAttribute('data-cat');
          showEditCategoryModal(cat);
          return;
        }

        // B. Quick log for category: opens window of this month's transactions to choose from
        const quickCatBtn = e.target.closest('.budget-quick-cat-btn');
        if (quickCatBtn) {
          const cat = quickCatBtn.getAttribute('data-cat');
          openBudgetCategoryLogModal(cat);
          return;
        }

        // C. Inline edit budget button
        const setBudgetBtn = e.target.closest('.inline-set-budget-btn');
        if (setBudgetBtn) {
          const cat = setBudgetBtn.getAttribute('data-cat');
          showEditCategoryModal(cat);
          return;
        }
      });
    }

    // Event listeners for Budget Category Log Expenses Modal
    const budgetLogContainer = document.getElementById('budgetLogExpensesContainer');
    if (budgetLogContainer) {
      budgetLogContainer.addEventListener('click', (e) => {
        const toggleBtn = e.target.closest('.budget-log-toggle-btn');
        if (!toggleBtn) return;
        const id = toggleBtn.getAttribute('data-id');
        const cat = state.activeBudgetLogCat || 'Groceries';
        const exp = (state.expenses || []).find(x => x.id === id);
        if (!exp) return;

        const eCat = (exp.category || '').trim().toLowerCase();
        const isCurrentlyLogged = (eCat === cat.toLowerCase().trim());

        if (isCurrentlyLogged) {
          // Unlog: revert to 'Unassigned'
          exp.category = 'Unassigned';
          saveExpenses();
          renderBudgetCategoryLogModalList();
          renderBudgetView();
          showToast('Removed from ' + cat, `"${exp.title}" is now unassigned.`, 'info');
        } else {
          // Log into this category
          exp.category = cat;
          saveExpenses();
          renderBudgetCategoryLogModalList();
          renderBudgetView();
          showToast('Logged to ' + cat + ' ✨', `"${exp.title}" (${formatMoney(exp.amount, exp.currency)}) logged to ${cat}.`, 'success');
        }
      });
    }

    const budgetLogSearchInp = document.getElementById('budgetLogSearchInput');
    if (budgetLogSearchInp) {
      budgetLogSearchInp.addEventListener('input', (e) => {
        state.budgetLogSearchQuery = e.target.value;
        renderBudgetCategoryLogModalList();
      });
    }

    document.querySelectorAll('.budget-log-filter-pill').forEach(btn => {
      btn.addEventListener('click', () => {
        state.budgetLogFilter = btn.getAttribute('data-filter') || 'all';
        renderBudgetCategoryLogModalList();
      });
    });

    const dropdownBtn = document.getElementById('budgetLogCategoryDropdownBtn');
    const dropdownMenu = document.getElementById('budgetLogCategoryDropdownMenu');
    if (dropdownBtn && dropdownMenu) {
      dropdownBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        dropdownMenu.classList.toggle('hidden');
        if (!dropdownMenu.classList.contains('hidden')) {
          renderBudgetLogCustomDropdown();
        }
      });

      dropdownMenu.addEventListener('click', (e) => {
        const optBtn = e.target.closest('.budget-log-cat-opt');
        if (!optBtn) return;
        const selectedCat = optBtn.getAttribute('data-cat');
        if (selectedCat) {
          state.activeBudgetLogCat = selectedCat;
          dropdownMenu.classList.add('hidden');
          renderBudgetCategoryLogModalList();
        }
      });

      document.addEventListener('click', (e) => {
        if (!dropdownBtn.contains(e.target) && !dropdownMenu.contains(e.target)) {
          dropdownMenu.classList.add('hidden');
        }
      });
    }

    const budgetLogCatDropdown = document.getElementById('budgetLogCategorySelect');
    if (budgetLogCatDropdown) {
      budgetLogCatDropdown.addEventListener('change', (e) => {
        state.activeBudgetLogCat = e.target.value;
        renderBudgetCategoryLogModalList();
      });
    }

    const budgetLogAddNewBtn = document.getElementById('budgetLogAddNewExpenseBtn');
    if (budgetLogAddNewBtn) {
      budgetLogAddNewBtn.addEventListener('click', () => {
        const cat = state.activeBudgetLogCat || 'Groceries';
        closeBudgetCategoryLogModal();
        openAddExpenseModal();
        const expCatSelect = document.getElementById('expenseCategory');
        if (expCatSelect) expCatSelect.value = cat;
      });
    }

    document.getElementById('closeBudgetCategoryLogModalBtn')?.addEventListener('click', closeBudgetCategoryLogModal);
    document.getElementById('doneBudgetCategoryLogModalBtn')?.addEventListener('click', closeBudgetCategoryLogModal);

    const budgetLogModal = document.getElementById('budgetCategoryLogModal');
    if (budgetLogModal) {
      budgetLogModal.addEventListener('click', (e) => {
        if (e.target === budgetLogModal) closeBudgetCategoryLogModal();
      });
    }

    // Re-render on currency switch
    document.querySelectorAll('.currency-toggle-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        if (state.currentTab === 'budget') renderBudgetView();
      });
    });
  }


