  function isGeneratedDocPlaceholderName(name) {
    if (!name || typeof name !== 'string') return true;
    const lower = name.trim().toLowerCase();
    return !lower || lower === 'proforma invoice' || lower === 'price quote / proposal' || lower === 'price offering & proposal' || lower === 'proposal & quote';
  }

  function getLeadQuoteAttachmentsList(lead) {
    if (!lead) return [];
    if (Array.isArray(lead.quoteAttachments) && lead.quoteAttachments.length > 0) {
      return lead.quoteAttachments;
    }
    const generatedTitle = (lead.priceOffering && lead.priceOffering.docTitle) ? String(lead.priceOffering.docTitle).trim().toLowerCase() : '';
    const docNameLower = typeof lead.quoteDocName === 'string' ? lead.quoteDocName.trim().toLowerCase() : '';
    if (lead.hasQuoteDoc && docNameLower && !isGeneratedDocPlaceholderName(lead.quoteDocName) && docNameLower !== generatedTitle) {
      return [{
        id: 'legacy_quote',
        attKey: `${lead.id}_quote`,
        fileName: lead.quoteDocName,
        attachedAt: null
      }];
    }
    return [];
  }

  function getProjectProformaAttachmentsList(proj) {
    if (!proj) return [];
    if (Array.isArray(proj.proformaAttachments) && proj.proformaAttachments.length > 0) {
      return proj.proformaAttachments;
    }
    const generatedTitle = (proj.proformaInvoice && proj.proformaInvoice.docTitle) ? String(proj.proformaInvoice.docTitle).trim().toLowerCase() : '';
    const docNameLower = typeof proj.proformaDocName === 'string' ? proj.proformaDocName.trim().toLowerCase() : '';
    if (proj.hasProformaAttachment || (proj.hasProformaDoc && docNameLower && !isGeneratedDocPlaceholderName(proj.proformaDocName) && docNameLower !== generatedTitle)) {
      return [{
        id: 'legacy_proforma',
        attKey: `${proj.id}_proforma`,
        fileName: proj.proformaDocName || 'proforma.pdf',
        attachedAt: null
      }];
    }
    return [];
  }

  function formatFollowupDocTimestamp(isoStr) {
    if (!isoStr) return '';
    try {
      const d = new Date(isoStr);
      if (isNaN(d.getTime())) return '';
      const datePart = d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
      const timePart = d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
      return `${datePart}, ${timePart}`;
    } catch (e) {
      return '';
    }
  }

  async function openFollowupAttachmentViewer(attKey, fallbackKey, titleText, fallbackFileName) {
    if (typeof getReceiptAttachment !== 'function') return;
    const expectedName = typeof fallbackFileName === 'string' ? fallbackFileName.trim().toLowerCase() : '';
    const isGenericExpected = !expectedName || ['proposal.pdf', 'proforma.pdf', 'brief.pdf', 'document.pdf', 'invoice.pdf', 'receipt.pdf'].includes(expectedName);
    const matchesExpectedName = (cand) => {
      if (!cand || !cand.data) return false;
      if (isGenericExpected) return true;
      const candName = typeof cand.fileName === 'string' ? cand.fileName.trim().toLowerCase() : '';
      return !candName || candName === expectedName;
    };

    const entityPrefixMatch = String(fallbackKey || attKey || '').match(/^((?:proj|lead)_[a-zA-Z0-9_]+?)_(?:quote|proforma|brief|invoice|receipt)(?:_|$)/);
    const entityId = entityPrefixMatch ? entityPrefixMatch[1] : '';

    // 1. Exact dedicated key lookup first
    let attachment = null;
    if (attKey) {
      const exact = await getReceiptAttachment(attKey);
      if (exact && exact.data) {
        if (!fallbackKey || attKey !== fallbackKey || matchesExpectedName(exact)) {
          attachment = exact;
        } else if (!expectedName) {
          attachment = exact;
        }
      }
    }

    // 2. If exact key was overwritten or missing, search known non-colliding sibling keys for the exact filename
    if ((!attachment || !attachment.data) && !isGenericExpected && entityId) {
      const siblingKeys = [
        `${entityId}_brief`,
        `${entityId}_quote`,
        `${entityId}_proforma`,
        `${entityId}_invoice`,
        `${entityId}_receipt`
      ];
      for (const sk of siblingKeys) {
        if (sk === attKey) continue;
        const cand = await getReceiptAttachment(sk);
        if (matchesExpectedName(cand)) {
          attachment = cand;
          break;
        }
      }
    }

    // 3. Only use shared fallbackKey if it actually matches the expected filename (prevents showing a newer file on an older row)
    if ((!attachment || !attachment.data) && fallbackKey && fallbackKey !== attKey) {
      const fb = await getReceiptAttachment(fallbackKey);
      if (matchesExpectedName(fb)) {
        attachment = fb;
      }
    }

    // 4. Legacy converted _proforma fallback only if filename matches
    if ((!attachment || !attachment.data) && fallbackKey && fallbackKey.endsWith('_quote')) {
      const legacyProf = await getReceiptAttachment(fallbackKey.replace(/_quote$/, '_proforma'));
      if (matchesExpectedName(legacyProf)) {
        attachment = legacyProf;
      }
    }

    if (!attachment || !attachment.data) {
      showToast('File Not Found', 'Could not find this specific file in storage.', 'warning');
      return;
    }

    // Self-heal dedicated key if we recovered the file from another slot
    if (attKey && fallbackKey && attKey !== fallbackKey && typeof saveReceiptAttachment === 'function') {
      saveReceiptAttachment(attKey, attachment).catch(() => {});
    }

    const resolvedName = fallbackFileName && !isGenericExpected ? fallbackFileName : (attachment.fileName || fallbackFileName || 'document.pdf');
    openReceiptViewerDirect({
      type: attachment.type || (String(resolvedName).toLowerCase().endsWith('.pdf') ? 'pdf' : 'image'),
      data: attachment.data,
      fileName: resolvedName,
      title: titleText || 'Attached Document'
    });
  }

  // Direct Document Upload & Remove
  async function handleDirectDocUpload(file, type, projectId) {
    if (!file || !projectId) return;
    const p = (state.budget.projects || []).find(x => x.id === projectId);
    if (!p) return;

    const isImage = file.type.startsWith('image/');
    const isPdf = file.type === 'application/pdf' || file.name.endsWith('.pdf');
    const docType = isImage ? 'image' : isPdf ? 'pdf' : 'text';

    const reader = new FileReader();
    reader.onload = async (re) => {
      const att = {
        type: docType,
        fileName: file.name,
        data: re.target.result,
        fileSize: file.size,
        mimeType: file.type
      };

      if (type === 'deposit_proforma') {
        if (!Array.isArray(p.depositProformaAttachments)) p.depositProformaAttachments = [];
        const existingList = p.depositProformaAttachments.map(x => Object.assign({}, x));
        const attId = 'dpatt_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4);
        const attKey = `${projectId}_deposit_proforma_${attId}`;
        await saveReceiptAttachment(attKey, att);
        await saveReceiptAttachment(`${projectId}_deposit_proforma`, att);
        existingList.unshift({
          id: attId,
          attKey,
          fileName: file.name,
          docType,
          attachedAt: new Date().toISOString()
        });
        p.depositProformaAttachments = existingList;
        p.hasDepositProformaAttachment = true;
        p.hasDepositProformaDoc = true;
        p.depositProformaDocName = file.name;
        showToast('Document Attached', `${file.name} saved to Deposit Proforma files.`, 'success');
      } else if (type === 'proforma') {
        const existingList = getProjectProformaAttachmentsList(p).map(x => Object.assign({}, x));
        // Migrate any legacy single-key item onto its own dedicated key BEFORE updating the shared key
        for (const item of existingList) {
          if (!item.attKey || item.attKey === `${projectId}_proforma`) {
            const migId = (item.id && item.id !== 'legacy_proforma') ? item.id : ('patt_mig_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4));
            const migKey = `${projectId}_proforma_${migId}`;
            const oldData = await getReceiptAttachment(`${projectId}_proforma`);
            if (oldData && oldData.data) {
              await saveReceiptAttachment(migKey, oldData);
            }
            item.id = migId;
            item.attKey = migKey;
          }
        }
        const attId = 'patt_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4);
        const attKey = `${projectId}_proforma_${attId}`;
        await saveReceiptAttachment(attKey, att);
        await saveReceiptAttachment(`${projectId}_proforma`, att);
        existingList.unshift({
          id: attId,
          attKey,
          fileName: file.name,
          docType,
          attachedAt: new Date().toISOString()
        });
        p.proformaAttachments = existingList;
        p.hasProformaAttachment = true;
        p.hasProformaDoc = true;
        p.proformaDocName = file.name;
        if (Array.isArray(p.steps)) {
          const s = p.steps.find(x => x.id === 'step_proforma' || x.title.toLowerCase().includes('proforma'));
          if (s) { s.completed = true; s.completedDate = new Date().toISOString().split('T')[0]; }
        }
        showToast('Document Attached', `${file.name} saved to Proforma Invoice files.`, 'success');
      } else if (type === 'invoice') {
        p.hasInvoiceDoc = true;
        p.invoiceDocName = file.name;
        await saveReceiptAttachment(`${projectId}_invoice`, att);
        await saveReceiptAttachment(projectId, att);
        if (Array.isArray(p.steps)) {
          const s = p.steps.find(x => x.id === 'step_work' || x.title.toLowerCase().includes('deliverable') || x.title.toLowerCase().includes('draft'));
          if (s && !s.completed) { s.completed = true; s.completedDate = new Date().toISOString().split('T')[0]; }
        }
        showToast('Document Attached', `${file.name} saved as Tax Invoice.`, 'success');
      } else if (type === 'receipt') {
        p.hasReceiptDoc = true;
        p.receiptDocName = file.name;
        const attKey = `${projectId}_receipt_${Date.now()}`;
        p.receiptAttKey = attKey;
        await saveReceiptAttachment(attKey, att);
        await saveReceiptAttachment(`${projectId}_receipt`, att);
        await saveReceiptAttachment(projectId, att);
        if (Array.isArray(p.steps)) {
          const s = p.steps.find(x => x.id === 'step_receipt' || x.title.toLowerCase().includes('receipt'));
          if (s) { s.completed = true; s.completedDate = new Date().toISOString().split('T')[0]; }
        }
        showToast('Document Attached', `${file.name} saved as Final Tax Receipt.`, 'success');
      }

      saveBudget();
      renderProjectDetailPage(p, state.displayCurrency);
      renderBudgetView();
    };
    reader.readAsDataURL(file);
  }

  async function removeDirectDoc(type, projectId, attId = null) {
    const p = (state.budget.projects || []).find(x => x.id === projectId);
    if (!p) return;
    if (!await confirmAction('Remove this attached document?')) return;

    if (type === 'deposit_proforma') {
      if (!Array.isArray(p.depositProformaAttachments)) p.depositProformaAttachments = [];
      const list = p.depositProformaAttachments;
      if (attId) {
        const target = list.find(x => x.id === attId);
        if (target && target.attKey && target.attKey !== `${projectId}_deposit_proforma`) {
          await deleteReceiptAttachment(target.attKey);
        }
        p.depositProformaAttachments = list.filter(x => x.id !== attId);
      } else {
        for (const item of list) {
          if (item.attKey) await deleteReceiptAttachment(item.attKey);
        }
        p.depositProformaAttachments = [];
      }
      if (!Array.isArray(p.depositProformaAttachments) || p.depositProformaAttachments.length === 0) {
        p.depositProformaAttachments = [];
        p.hasDepositProformaAttachment = false;
        delete p.depositProformaDocName;
        await deleteReceiptAttachment(`${projectId}_deposit_proforma`);
        p.hasDepositProformaDoc = !!(p.depositProforma || (Array.isArray(p.depositProformaExports) && p.depositProformaExports.length > 0));
      } else {
        p.hasDepositProformaAttachment = true;
        p.depositProformaDocName = p.depositProformaAttachments[0].fileName || 'deposit_proforma.pdf';
        const topAtt = p.depositProformaAttachments[0];
        if (topAtt && topAtt.attKey) {
          const topData = await getReceiptAttachment(topAtt.attKey);
          if (topData && topData.data) {
            await saveReceiptAttachment(`${projectId}_deposit_proforma`, topData);
          }
        }
      }
      showToast('Document Removed', 'Attached deposit proforma file removed.', 'info');
    } else if (type === 'proforma') {
      const list = getProjectProformaAttachmentsList(p);
      if (attId) {
        const target = list.find(x => x.id === attId);
        if (target && target.attKey && target.attKey !== `${projectId}_proforma`) {
          await deleteReceiptAttachment(target.attKey);
        }
        p.proformaAttachments = list.filter(x => x.id !== attId);
      } else {
        for (const item of list) {
          if (item.attKey) await deleteReceiptAttachment(item.attKey);
        }
        p.proformaAttachments = [];
      }
      if (!Array.isArray(p.proformaAttachments) || p.proformaAttachments.length === 0) {
        p.proformaAttachments = [];
        p.hasProformaAttachment = false;
        delete p.proformaDocName;
        await deleteReceiptAttachment(`${projectId}_proforma`);
        p.hasProformaDoc = !!(p.proformaInvoice || (Array.isArray(p.proformaExports) && p.proformaExports.length > 0));
      } else {
        p.hasProformaAttachment = true;
        p.proformaDocName = p.proformaAttachments[0].fileName || 'proforma.pdf';
        const topAtt = p.proformaAttachments[0];
        if (topAtt && topAtt.attKey) {
          const topData = await getReceiptAttachment(topAtt.attKey);
          if (topData && topData.data) {
            await saveReceiptAttachment(`${projectId}_proforma`, topData);
          }
        }
      }
      showToast('Document Removed', 'Attached proforma file removed.', 'info');
    } else if (type === 'invoice') {
      p.hasInvoiceDoc = false;
      delete p.invoiceDocName;
      await deleteReceiptAttachment(`${projectId}_invoice`);
      if (!p.hasReceiptDoc) await deleteReceiptAttachment(projectId);
      showToast('Document Removed', 'Tax invoice removed.', 'info');
    } else if (type === 'receipt') {
      p.hasReceiptDoc = false;
      p.hasInvoiceDoc = false;
      if (p.receiptAttKey) {
        await deleteReceiptAttachment(p.receiptAttKey);
        delete p.receiptAttKey;
      }
      delete p.receiptDocName;
      delete p.invoiceDocName;
      delete p.invoiceDoc;
      await deleteReceiptAttachment(`${projectId}_receipt`);
      await deleteReceiptAttachment(`${projectId}_invoice`);
      await deleteReceiptAttachment(projectId);
      showToast('Document Removed', 'Tax receipt removed.', 'info');
    }

    saveBudget();
    renderProjectDetailPage(p, state.displayCurrency);
    renderBudgetView();
  }

  function isProjectDone(p) {
    if (!p) return false;
    if (p.isDone === true || p.status === 'completed' || p.status === 'done') return true;
    if (p.isDone === false) return false;
    // For legacy projects that had status === 'paid':
    if (p.status === 'paid') {
      if (Array.isArray(p.steps) && p.steps.length > 0) {
        return p.steps.every(s => s.completed);
      }
      return true;
    }
    return false;
  }

  function isProjectWorkDone(p) {
    if (!p) return false;
    if (isProjectDone(p)) return true;
    return p.isWorkDone === true;
  }

  function healFollowupLiveData() {
    if (!state.budget) return;
    let mutated = false;

    if (state.budget.poDefaultTemplate) {
      const before = JSON.stringify(state.budget.poDefaultTemplate);
      sanitizePoTemplateData(state.budget.poDefaultTemplate);
      if (JSON.stringify(state.budget.poDefaultTemplate) !== before) mutated = true;
    }
    if (Array.isArray(state.budget.poSavedTemplates)) {
      const before = JSON.stringify(state.budget.poSavedTemplates);
      state.budget.poSavedTemplates.forEach(t => sanitizePoTemplateData(t));
      if (JSON.stringify(state.budget.poSavedTemplates) !== before) mutated = true;
    }

    const normalizePastTenseStepTitle = (rawTitle) => {
      if (!rawTitle || typeof rawTitle !== 'string') return rawTitle;
      const t = rawTitle.trim().toLowerCase();
      const map = {
        'price offering sent': 'Send price offering',
        'price quote sent': 'Send price quote',
        'price offering & proposal sent': 'Send price offering & proposal',
        'price offering & proposal': 'Send price offering & proposal',
        'sent price offering / quote': 'Send price offering / quote',
        'sent proforma invoice': 'Send proforma invoice',
        'deposit / upfront payment received': 'Receive deposit / upfront payment',
        'deposit received': 'Receive deposit',
        'first draft submitted': 'Submit first draft',
        'client revisions approved': 'Approve client revisions',
        'final delivery sent': 'Send final delivery',
        'got final payment': 'Receive final payment',
        'final payment': 'Receive final payment',
        'sent official tax receipt to client': 'Send official tax receipt to client',
        'sent official tax receipt': 'Send official tax receipt',
        'discovery call scheduled': 'Schedule discovery call',
        'sent portfolio & references': 'Send portfolio & references',
        'sent follow-up email': 'Send follow-up email',
        'agreed on scope & timeline': 'Agree on scope & timeline',
        'sent contract / agreement': 'Send contract / agreement'
      };
      return map[t] || rawTitle;
    };

    const defaultLeadStepDefs = [
      { id: 'lead_step_call', title: 'Initial discovery / briefing call', completed: false, isDefault: true },
      { id: 'lead_step_scope', title: 'Scope & deliverables outline', completed: false, isDefault: true },
      { id: 'lead_step_quote', title: 'Send price offering & proposal', completed: false, isDefault: true },
      { id: 'lead_step_followup', title: 'Follow-up with client', completed: false, isDefault: true }
    ];
    const projectOnlyIds = new Set(['step_proforma', 'step_deposit', 'step_work', 'step_payment', 'step_receipt']);
    const isProjectOnlyDefaultStep = (s) => {
      if (!s) return false;
      if (projectOnlyIds.has(s.id)) return true;
      const t = (s.title || '').toLowerCase();
      return t.includes('proforma invoice') ||
        t.includes('deposit / upfront payment') ||
        t.includes('project deliverables & client review') ||
        t.includes('got final payment') ||
        t.includes('receive final payment') ||
        t.includes('official tax receipt');
    };

    if (Array.isArray(state.budget.leads)) {
      state.budget.leads.forEach(lead => {
        if (!lead) return;
        const beforeLead = JSON.stringify(lead);

        if (Array.isArray(lead.steps)) {
          lead.steps.forEach(s => {
            if (s && s.title) {
              s.title = normalizePastTenseStepTitle(s.title);
            }
          });
        }

        if (Array.isArray(lead.steps) && lead.steps.some(s => !s.completed && isProjectOnlyDefaultStep(s))) {
          const filtered = lead.steps
            .filter(s => s && (s.completed || !isProjectOnlyDefaultStep(s)))
            .map((s, idx) => {
              const t = (s.title || '').toLowerCase();
              if (s.id === 'step_quote' || t === 'price offering sent' || t === 'send price offering') {
                return {
                  id: 'lead_step_quote',
                  title: 'Send price offering & proposal',
                  completed: !!s.completed,
                  completedDate: s.completedDate || null,
                  dueDate: s.dueDate || s.plannedDate || null,
                  isDefault: true
                };
              }
              return s;
            });
          const hasStandardLeadSteps = filtered.some(s =>
            s.id === 'lead_step_call' || s.id === 'lead_step_scope' || s.id === 'lead_step_followup' ||
            (s.title || '').toLowerCase().includes('discovery') || (s.title || '').toLowerCase().includes('follow-up with client')
          );
          if (!hasStandardLeadSteps) {
            const quoteStep = filtered.find(s => s.id === 'lead_step_quote' || (s.title || '').toLowerCase().includes('price offering'));
            const customSteps = filtered.filter(s => s !== quoteStep);
            lead.steps = defaultLeadStepDefs.map(def => {
              if (def.id === 'lead_step_quote' && quoteStep && quoteStep.completed) {
                return Object.assign({}, def, { completed: true, completedDate: quoteStep.completedDate || new Date().toISOString().split('T')[0] });
              }
              return Object.assign({}, def);
            }).concat(customSteps);
          } else {
            lead.steps = filtered;
          }
        }

        if (lead.priceOffering) {
          lead.hasQuoteDoc = true;
          const po = lead.priceOffering;
          if (po.validUntil === '2026-11-31') {
            po.validUntil = '2026-11-30';
            if (po.richText && po.richText.valid_until_val) {
              po.richText.valid_until_val = poWrapTextWithRichStyle(po.richText.valid_until_val, '2026-11-30', false);
            }
          }
          if (!po.labels || typeof po.labels !== 'object') po.labels = Object.assign({}, DEFAULT_PO_TEMPLATE.labels);
          if (!po.labels.issueDate || !String(po.labels.issueDate).trim()) {
            po.labels.issueDate = 'Date Issued';
            if (po.richText) {
              delete po.richText.label_issueDate;
              delete po.richText.label_issue_date;
            }
          }
          if (Array.isArray(po.items)) {
            if (po.richText && typeof po.richText === 'object') {
              Object.keys(po.richText).forEach(rk => {
                const m = rk.match(/^item_(desc|qty|rate|amount)_(\d+)$/);
                if (m && parseInt(m[2], 10) >= po.items.length) delete po.richText[rk];
              });
            }
            if (po.elementStyles && typeof po.elementStyles === 'object') {
              Object.keys(po.elementStyles).forEach(ek => {
                const m = ek.match(/^item_(desc|qty|rate|amount)_(\d+)$/);
                if (m && parseInt(m[2], 10) >= po.items.length) delete po.elementStyles[ek];
              });
            }
          }
          if (Array.isArray(po.sections)) {
            po.sections = po.sections.filter(s => {
              if (!s) return false;
              if (s.type === 'text' && (!s.title || s.title.trim() === '*') && (!s.content || !s.content.trim())) return false;
              if (s.type === 'custom' && (s.title || '').toLowerCase() === 'summary' && (!s.content || !s.content.trim())) return false;
              return true;
            });
            const ovIdx = po.sections.findIndex(s => s && (s.id === 'sec_overview' || s.type === 'overview'));
            const hasOvDiv = po.sections.some(s => s && s.id === 'sec_div_overview');
            if (ovIdx !== -1 && !hasOvDiv) {
              const nextSec = po.sections[ovIdx + 1];
              if (!nextSec || nextSec.type !== 'divider') {
                po.sections.splice(ovIdx + 1, 0, { id: 'sec_div_overview', type: 'divider', title: '', content: '' });
              }
            }
          }
          const leadAmt = parseFloat(lead.amount) || 0;
          if (Array.isArray(po.items) && po.items.length === 1 && leadAmt > 0 && Number(po.items[0].rate) !== leadAmt) {
            syncDraftSingleItemAmount(po, leadAmt, lead.currency);
          }
          if (!po.client || !po.projectTitle) {
            syncFollowupDocMetadataWithEntity(po, lead, po.client, po.projectTitle, false);
          }
        }

        if (JSON.stringify(lead) !== beforeLead) mutated = true;
      });
    }

    if (Array.isArray(state.budget.projects)) {
      state.budget.projects.forEach(proj => {
        if (!proj) return;
        const beforeProj = JSON.stringify(proj);

        if (!proj.title && proj.description) {
          proj.title = proj.description;
        }

        // Heal converted projects where Price Quotes (PO-...) were mistakenly placed into Proforma Invoice fields
        const hasPoExportsInProforma = Array.isArray(proj.proformaExports) && proj.proformaExports.some(exp =>
          exp && ((exp.refNo && String(exp.refNo).startsWith('PO-')) || (exp.docTitle && /quote|proposal|offering/i.test(exp.docTitle)))
        );
        const hasQuoteAttsInProforma = Array.isArray(proj.proformaAttachments) && proj.proformaAttachments.some(att =>
          att && att.fileName && /quote|po-|proposal/i.test(att.fileName)
        );
        if (hasPoExportsInProforma || hasQuoteAttsInProforma) {
          if (!Array.isArray(proj.quoteExports)) proj.quoteExports = [];
          if (Array.isArray(proj.proformaExports)) {
            const keepProformaExps = [];
            proj.proformaExports.forEach(exp => {
              if (exp && ((exp.refNo && String(exp.refNo).startsWith('PO-')) || (exp.docTitle && /quote|proposal|offering/i.test(exp.docTitle)))) {
                if (!proj.quoteExports.some(q => q && q.id === exp.id)) {
                  proj.quoteExports.push(exp);
                }
              } else if (exp) {
                keepProformaExps.push(exp);
              }
            });
            proj.proformaExports = keepProformaExps;
          }
          if (!Array.isArray(proj.quoteAttachments)) proj.quoteAttachments = [];
          if (Array.isArray(proj.proformaAttachments)) {
            const keepProformaAtts = [];
            proj.proformaAttachments.forEach(att => {
              if (att && att.fileName && /quote|po-|proposal/i.test(att.fileName)) {
                if (!proj.quoteAttachments.some(q => q && (q.id === att.id || q.fileName === att.fileName))) {
                  proj.quoteAttachments.push(att);
                }
              } else if (att) {
                keepProformaAtts.push(att);
              }
            });
            proj.proformaAttachments = keepProformaAtts;
          }
          if (!proj.priceOffering && proj.quoteExports.length > 0 && proj.quoteExports[0].data) {
            proj.priceOffering = JSON.parse(JSON.stringify(proj.quoteExports[0].data));
            proj.priceOffering._isProforma = false;
          }
          if (!Array.isArray(proj.depositProformaExports)) proj.depositProformaExports = [];
          if (!Array.isArray(proj.depositProformaAttachments)) proj.depositProformaAttachments = [];
          proj.hasDepositProformaDoc = !!(proj.depositProforma || proj.depositProformaExports.length > 0 || proj.depositProformaAttachments.length > 0);
          proj.depositProformaDocName = (proj.depositProformaAttachments[0] && proj.depositProformaAttachments[0].fileName) || (proj.depositProforma ? (proj.depositProforma.docTitle || 'Deposit Proforma Invoice (50%)') : '');
          proj.hasQuoteDoc = !!(proj.priceOffering || proj.quoteExports.length > 0 || proj.quoteAttachments.length > 0);
          proj.quoteDocName = (proj.quoteAttachments[0] && proj.quoteAttachments[0].fileName) || (proj.priceOffering && proj.priceOffering.docTitle) || '';
          proj.hasProformaAttachment = proj.proformaAttachments.length > 0;
          proj.hasProformaDoc = !!(proj.proformaInvoice || proj.proformaExports.length > 0 || proj.proformaAttachments.length > 0);
          proj.proformaDocName = proj.proformaAttachments.length > 0 ? proj.proformaAttachments[0].fileName : (proj.proformaInvoice ? (proj.proformaInvoice.docTitle || 'Proforma Invoice') : '');
        }

        if (proj.proformaInvoice && proj.proformaInvoice.validUntil && !proj.paymentDueDate) {
          proj.paymentDueDate = proj.proformaInvoice.validUntil;
        }

        // Heal legacy corrupted quote attachment keys where Client Brief was also listed inside Quote Attachments pointing to an overwritten _proforma key
        if (Array.isArray(proj.quoteAttachments) && proj.quoteAttachments.length > 0) {
          const briefLower = typeof proj.briefDocName === 'string' ? proj.briefDocName.trim().toLowerCase() : '';
          proj.quoteAttachments.forEach(att => {
            if (!att || !att.fileName) return;
            const fnLower = att.fileName.trim().toLowerCase();
            if (proj.hasBriefDoc && briefLower && fnLower === briefLower && (!att.attKey || att.attKey.includes('_proforma'))) {
              att.attKey = proj.briefAttKey || `${proj.id}_brief`;
            }
          });
          // Deduplicate identical attachment filenames pointing to the same key
          const seenAttSigs = new Set();
          proj.quoteAttachments = proj.quoteAttachments.filter(att => {
            if (!att) return false;
            const sig = `${(att.fileName || '').trim().toLowerCase()}::${att.attKey || ''}`;
            if (seenAttSigs.has(sig)) return false;
            seenAttSigs.add(sig);
            return true;
          });
        }

        // Restore Buzzer subtitle if accidentally cleared on open while matching latest export
        if (proj.priceOffering && !proj.priceOffering.docSubtitle && /buzzer/i.test(String(proj.client || '')) && Array.isArray(proj.quoteExports) && proj.quoteExports.length > 0 && proj.quoteExports[0].data && proj.quoteExports[0].data.docSubtitle) {
          const testDraft = JSON.parse(JSON.stringify(proj.priceOffering));
          testDraft.docSubtitle = proj.quoteExports[0].data.docSubtitle;
          if (proj.quoteExports[0].data.richText && proj.quoteExports[0].data.richText.doc_subtitle) {
            if (!testDraft.richText) testDraft.richText = {};
            testDraft.richText.doc_subtitle = proj.quoteExports[0].data.richText.doc_subtitle;
          }
          if (JSON.stringify(testDraft.items || []) === JSON.stringify(proj.quoteExports[0].data.items || [])) {
            proj.priceOffering.docSubtitle = proj.quoteExports[0].data.docSubtitle;
            if (proj.quoteExports[0].data.richText && proj.quoteExports[0].data.richText.doc_subtitle) {
              if (!proj.priceOffering.richText) proj.priceOffering.richText = {};
              proj.priceOffering.richText.doc_subtitle = proj.quoteExports[0].data.richText.doc_subtitle;
            }
            if (proj.quoteExports[0].data.signatures && (!Array.isArray(proj.priceOffering.signatures) || proj.priceOffering.signatures.length === 0)) {
              proj.priceOffering.signatures = JSON.parse(JSON.stringify(proj.quoteExports[0].data.signatures));
            }
          }
        }

        const projFee = parseFloat(proj.amount !== undefined ? proj.amount : proj.fee) || 0;
        const projPaid = parseFloat(proj.paidAmount) || 0;

        // Force-heal project fee if overwritten by template placeholder items or corrupted from approved quote
        if (proj.priceOffering && proj.priceOffering.total && !isNaN(parseFloat(proj.priceOffering.total))) {
          const poTot = parseFloat(proj.priceOffering.total);
          const hasPlaceholderItems = Array.isArray(proj.proformaInvoice?.items) && proj.proformaInvoice.items.some(it =>
            it && it.description && /\[PROJECT TITLE|COMPLETED CREATIVE SCOPE|DPI REFERENCE\]/i.test(it.description)
          );
          if ((poTot > 0 && (projFee === 1000 || hasPlaceholderItems)) || (/buzzer/i.test(String(proj.client || '')) && (proj.fee === 1000 || proj.amount === 1000 || proj.proformaInvoice?.total === 1000))) {
            proj.fee = poTot;
            proj.amount = poTot;
            if (proj.proformaInvoice && (proj.proformaInvoice.total === 1000 || hasPlaceholderItems)) {
              proj.proformaInvoice.total = poTot;
              if (Array.isArray(proj.priceOffering.items) && proj.priceOffering.items.length > 0) {
                proj.proformaInvoice.items = JSON.parse(JSON.stringify(proj.priceOffering.items));
                proj.proformaInvoice.subtotal = proj.priceOffering.subtotal;
                proj.proformaInvoice.discountPercent = proj.priceOffering.discountPercent;
                proj.proformaInvoice.taxPercent = proj.priceOffering.taxPercent;
              }
            }
            mutated = true;
          }
        }

        const isAlreadyPaidOrDone = proj.isDone === true || proj.status === 'paid' || proj.status === 'completed' || (projFee > 0 && projPaid >= projFee);

        if (Array.isArray(proj.steps)) {
          proj.steps.forEach(s => {
            if (s && s.title) {
              s.title = normalizePastTenseStepTitle(s.title);
            }
          });
        }

        if (proj.proformaInvoice) {
          proj.hasProformaDoc = true;
          const pi = proj.proformaInvoice;
          pi._isProforma = true;
          const projTitle = (proj.title || proj.description || '').trim();
          if (pi.docSubtitle === 'Print & Merch Design Bundle' && projTitle !== 'Print & Merch Design Bundle') {
            pi.docSubtitle = 'Preliminary Invoice / Advance Payment Request';
            if (pi.richText) delete pi.richText.doc_subtitle;
          }
          if (!pi.labels || pi.labels.reference === 'Reference #' || pi.labels.validUntil === 'Valid Until' || pi.labels.totalEstimate === 'Total Estimate' || !pi.labels.issueDate) {
            pi.labels = Object.assign({}, PROFORMA_DEFAULT_LABELS);
            if (pi.richText) {
              ['label_preparedFor', 'label_reference', 'label_issueDate', 'label_validUntil', 'label_totalEstimate', 'label_client', 'label_ref', 'label_issue_date', 'label_valid_until', 'label_total_investment'].forEach(k => delete pi.richText[k]);
            }
          }
          if (Array.isArray(pi.sections)) {
            const needsProformaSectionHeal =
              pi.sections.some(s => s && s.type === 'text' && (!s.title || s.title.trim() === '*') && (!s.content || !s.content.trim())) ||
              !pi.sections.some(s => s && s.type === 'terms' && (s.content || '').includes('IBAN:')) ||
              pi.sections.some(s => s && (s.type === 'overview' || s.type === 'scope') && !(s.content || '').trim());
            if (needsProformaSectionHeal) {
              pi.sections = buildProformaSectionsFromTemplate(pi.sections, pi.sections, proj);
            }
          }
          if (Array.isArray(pi.items) && pi.items.length === 1 && projFee > 0 && Number(pi.items[0].rate) !== projFee) {
            syncDraftSingleItemAmount(pi, projFee, proj.currency);
          }
          if (!pi.client || !pi.projectTitle) {
            syncFollowupDocMetadataWithEntity(pi, proj, pi.client, pi.projectTitle, false);
          }
        }

        if (JSON.stringify(proj) !== beforeProj) mutated = true;
      });
    }

    if (mutated) {
      saveBudget();
    }
  }

  function renderProjectFollowupView() {
    const view = document.getElementById('viewProjectFollowup');
    if (!view || view.classList.contains('hidden')) return;

    if (!state.budget) state.budget = {};
    if (!Array.isArray(state.budget.leads)) state.budget.leads = [];
    if (!Array.isArray(state.budget.projects)) state.budget.projects = [];

    healFollowupLiveData();

    const cur = state.displayCurrency || 'EUR';

    // If viewing a specific project's deposit proforma invoice
    if (state.activeDepositProformaProjectId) {
      const proj = (state.budget?.projects || []).find(p => p.id === state.activeDepositProformaProjectId);
      if (proj) {
        document.getElementById('projectFollowupOverview')?.classList.add('hidden');
        document.getElementById('projectDetailPage')?.classList.add('hidden');
        document.getElementById('leadDetailPage')?.classList.add('hidden');
        document.getElementById('priceOfferingDocPage')?.classList.remove('hidden');
        openProjectDepositProformaDocPage(state.activeDepositProformaProjectId);
        return;
      } else if (Array.isArray(state.budget?.projects) && state.budget.projects.length > 0) {
        state.activeDepositProformaProjectId = null;
      }
    }

    // If viewing a specific project's proforma invoice
    if (state.activeProformaProjectId) {
      const proj = (state.budget?.projects || []).find(p => p.id === state.activeProformaProjectId);
      if (proj) {
        document.getElementById('projectFollowupOverview')?.classList.add('hidden');
        document.getElementById('projectDetailPage')?.classList.add('hidden');
        document.getElementById('leadDetailPage')?.classList.add('hidden');
        document.getElementById('priceOfferingDocPage')?.classList.remove('hidden');
        openProjectProformaDocPage(state.activeProformaProjectId);
        return;
      } else if (Array.isArray(state.budget?.projects) && state.budget.projects.length > 0) {
        state.activeProformaProjectId = null;
      }
    }

    // If viewing a specific lead's or project's price offering document
    if (state.activePriceOfferingLeadId) {
      const lead = (state.budget?.leads || []).find(l => l.id === state.activePriceOfferingLeadId)
        || (state.budget?.projects || []).find(p => p.id === state.activePriceOfferingLeadId);
      if (lead) {
        document.getElementById('projectFollowupOverview')?.classList.add('hidden');
        document.getElementById('projectDetailPage')?.classList.add('hidden');
        document.getElementById('leadDetailPage')?.classList.add('hidden');
        document.getElementById('priceOfferingDocPage')?.classList.remove('hidden');
        openPriceOfferingDocPage(state.activePriceOfferingLeadId);
        return;
      } else if ((Array.isArray(state.budget?.leads) && state.budget.leads.length > 0) || (Array.isArray(state.budget?.projects) && state.budget.projects.length > 0)) {
        state.activePriceOfferingLeadId = null;
      }
    }

    // If viewing a specific project detail page
    if (state.activeFollowupProjectId) {
      const proj = (state.budget?.projects || []).find(p => p.id === state.activeFollowupProjectId);
      if (proj) {
        document.getElementById('projectFollowupOverview')?.classList.add('hidden');
        document.getElementById('projectDetailPage')?.classList.remove('hidden');
        document.getElementById('leadDetailPage')?.classList.add('hidden');
        document.getElementById('priceOfferingDocPage')?.classList.add('hidden');
        renderProjectDetailPage(proj, cur);
        if (window.lucide && typeof window.lucide.createIcons === 'function') {
          window.lucide.createIcons();
        }
        return;
      } else if (Array.isArray(state.budget?.projects) && state.budget.projects.length > 0) {
        state.activeFollowupProjectId = null;
        try {
          localStorage.removeItem('ft_active_followup_project');
          history.replaceState(null, '', '#project_followup');
        } catch (e) {}
      }
    }

    // If viewing a specific lead detail page
    if (state.activeFollowupLeadId) {
      const lead = (state.budget?.leads || []).find(l => l.id === state.activeFollowupLeadId);
      if (lead) {
        document.getElementById('projectFollowupOverview')?.classList.add('hidden');
        document.getElementById('projectDetailPage')?.classList.add('hidden');
        document.getElementById('priceOfferingDocPage')?.classList.add('hidden');
        document.getElementById('leadDetailPage')?.classList.remove('hidden');
        renderLeadDetailPage(lead, cur);
        if (window.lucide && typeof window.lucide.createIcons === 'function') {
          window.lucide.createIcons();
        }
        return;
      } else if (Array.isArray(state.budget?.leads) && state.budget.leads.length > 0) {
        state.activeFollowupLeadId = null;
        try {
          localStorage.removeItem('ft_active_followup_lead');
          history.replaceState(null, '', '#project_followup');
        } catch (e) {}
      }
    }

    document.getElementById('projectFollowupOverview')?.classList.remove('hidden');
    document.getElementById('projectDetailPage')?.classList.add('hidden');
    document.getElementById('leadDetailPage')?.classList.add('hidden');
    document.getElementById('priceOfferingDocPage')?.classList.add('hidden');
    const selectedMonth = state.selectedMonth || 'ALL';
    const isAllTime = (!selectedMonth || selectedMonth === 'ALL' || selectedMonth === 'all');

    const allLeads = state.budget.leads || [];
    const allProjects = state.budget.projects || [];

    const leads = isAllTime ? allLeads : allLeads.filter(l => leadMatchesMonth(l, selectedMonth));
    const projects = isAllTime ? allProjects : allProjects.filter(p => projectMatchesMonth(p, selectedMonth));

    // Calculate Summary Metrics
    let totalLeadsMoney = 0;
    leads.forEach(l => {
      const amt = parseFloat(l.amount) || 0;
      totalLeadsMoney += convertCurrency(amt, l.currency || cur, cur);
    });

    // Separate active ongoing projects vs finished projects
    const activeProjects = [];
    const completedProjects = [];
    let totalProjectsMoney = 0;
    let totalCompletedMoney = 0;
    let dueSoonCount = 0;
    let overdueCount = 0;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const fourteenDaysLater = new Date(today.getTime() + 14 * 86400000);

    projects.forEach(p => {
      const fee = parseFloat(p.amount !== undefined ? p.amount : p.fee) || 0;
      const paid = parseFloat(p.paidAmount) || 0;
      const feeConverted = convertCurrency(fee, p.currency || cur, cur);
      const done = isProjectDone(p);

      if (done) {
        completedProjects.push(p);
        totalCompletedMoney += feeConverted;
      } else {
        activeProjects.push(p);
        totalProjectsMoney += feeConverted;

        if (!isProjectWorkDone(p) && p.dueDate) {
          const d = new Date(p.dueDate + 'T00:00:00');
          if (!isNaN(d.getTime()) && d <= fourteenDaysLater) {
            dueSoonCount++;
            if (d < today) overdueCount++;
          }
        } else if (isProjectWorkDone(p) && paid < fee) {
          const payDue = getProjectPaymentDueDate(p);
          if (payDue) {
            const pd = new Date(payDue + 'T00:00:00');
            if (!isNaN(pd.getTime()) && pd <= fourteenDaysLater) {
              dueSoonCount++;
              if (pd < today) overdueCount++;
            }
          }
        }
      }
    });

    // Multi-currency equivalents for the summary tiles
    const otherCurs = ['EUR', 'ILS', 'USD'].filter(c => c !== cur);
    const targetCur1 = otherCurs[0];
    const targetCur2 = otherCurs[1];

    const leadsEquivEl = document.getElementById('followupSummaryLeadsEquiv');
    if (leadsEquivEl) {
      if (totalLeadsMoney > 0) {
        leadsEquivEl.textContent = `≈ ${formatMoney(convertCurrency(totalLeadsMoney, cur, targetCur1), targetCur1)} • ${formatMoney(convertCurrency(totalLeadsMoney, cur, targetCur2), targetCur2)}`;
        leadsEquivEl.classList.remove('hidden');
      } else {
        leadsEquivEl.classList.add('hidden');
      }
    }

    const projectsEquivEl = document.getElementById('followupSummaryProjectsEquiv');
    if (projectsEquivEl) {
      if (totalProjectsMoney > 0) {
        projectsEquivEl.textContent = `≈ ${formatMoney(convertCurrency(totalProjectsMoney, cur, targetCur1), targetCur1)} • ${formatMoney(convertCurrency(totalProjectsMoney, cur, targetCur2), targetCur2)}`;
        projectsEquivEl.classList.remove('hidden');
      } else {
        projectsEquivEl.classList.add('hidden');
      }
    }

    const completedEquivEl = document.getElementById('followupSummaryCompletedEquiv');
    if (completedEquivEl) {
      if (totalCompletedMoney > 0) {
        completedEquivEl.textContent = `≈ ${formatMoney(convertCurrency(totalCompletedMoney, cur, targetCur1), targetCur1)} • ${formatMoney(convertCurrency(totalCompletedMoney, cur, targetCur2), targetCur2)}`;
        completedEquivEl.classList.remove('hidden');
      } else {
        completedEquivEl.classList.add('hidden');
      }
    }

    // Populate summary strip
    const setTxt = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
    setTxt('followupSummaryLeadsCount', String(leads.length));
    setTxt('followupSummaryLeadsMoney', formatMoney(totalLeadsMoney, cur));
    setTxt('followupSummaryProjectsCount', String(activeProjects.length));
    setTxt('followupSummaryProjectsMoney', formatMoney(totalProjectsMoney, cur));
    setTxt('followupSummaryDueCount', String(dueSoonCount));
    setTxt('followupSummaryCompletedCount', String(completedProjects.length));
    setTxt('followupSummaryCompletedMoney', formatMoney(totalCompletedMoney, cur));

    setTxt('followupLeadsCountBadge', String(leads.length));
    const leadsPill = document.getElementById('followupLeadsMoneyPill');
    if (leadsPill) {
      if (totalLeadsMoney > 0) {
        leadsPill.textContent = `+${formatMoney(totalLeadsMoney, cur)}`;
        leadsPill.classList.remove('hidden');
      } else {
        leadsPill.classList.add('hidden');
      }
    }

    setTxt('followupProjectsCountBadge', String(activeProjects.length));
    const projectsPill = document.getElementById('followupProjectsMoneyPill');
    if (projectsPill) {
      if (totalProjectsMoney > 0) {
        projectsPill.textContent = `${formatMoney(totalProjectsMoney, cur)}`;
        projectsPill.classList.remove('hidden');
      } else {
        projectsPill.classList.add('hidden');
      }
    }

    // Section C: Finished Projects
    const completedSection = document.getElementById('followupCompletedSection');
    const completedBadge = document.getElementById('followupCompletedCountBadge');
    const completedPill = document.getElementById('followupCompletedMoneyPill');
    if (completedSection) {
      completedSection.classList.remove('hidden');
      if (completedBadge) completedBadge.textContent = String(completedProjects.length);
      if (completedPill) {
        if (totalCompletedMoney > 0) {
          completedPill.textContent = `${formatMoney(totalCompletedMoney, cur)}`;
          completedPill.classList.remove('hidden');
        } else {
          completedPill.classList.add('hidden');
        }
      }
    }

    // Render Lists
    renderFollowupLeadsList(leads, cur);
    renderFollowupProjectsList(activeProjects, completedProjects, cur);
    equalizeAndFitFollowupCards();

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function getFollowupAdaptiveTextClasses(clientStr, titleStr, nextStr) {
    const cLen = (clientStr || '').trim().length;
    const tLen = (titleStr || '').trim().length;
    const nLen = (nextStr || '').trim().length;

    let clientClass = 'text-xs leading-tight';
    if (cLen > 20) {
      clientClass = 'text-[10px] leading-tight';
    } else if (cLen > 15) {
      clientClass = 'text-[11px] leading-tight';
    }

    let titleClass = 'text-sm leading-snug';
    if (tLen > 46) {
      titleClass = 'text-xs leading-tight';
    } else if (tLen > 28) {
      titleClass = 'text-[13px] leading-tight';
    }

    let nextBoxClass = 'text-xs py-1.5 px-2.5';
    let nextTextClass = 'leading-snug';
    if (nLen > 75) {
      nextBoxClass = 'text-[9.5px] py-1 px-2';
      nextTextClass = 'leading-tight';
    } else if (nLen > 48) {
      nextBoxClass = 'text-[10px] py-1 px-2';
      nextTextClass = 'leading-tight';
    } else if (nLen > 30) {
      nextBoxClass = 'text-[11px] py-1 px-2';
      nextTextClass = 'leading-tight';
    }

    return { clientClass, titleClass, nextBoxClass, nextTextClass };
  }

  let followupResizeBound = false;
  function equalizeAndFitFollowupCards() {
    if (!followupResizeBound && typeof window !== 'undefined' && window.addEventListener) {
      followupResizeBound = true;
      window.addEventListener('resize', () => {
        if (typeof requestAnimationFrame === 'function') {
          requestAnimationFrame(runEqualizeAndFitFollowupCards);
        } else {
          runEqualizeAndFitFollowupCards();
        }
      });
    }
    runEqualizeAndFitFollowupCards();
    if (typeof requestAnimationFrame === 'function') {
      requestAnimationFrame(runEqualizeAndFitFollowupCards);
    }
  }

  function runEqualizeAndFitFollowupCards() {
    const page = document.getElementById('viewProjectFollowup');
    if (!page || page.classList.contains('hidden')) return;
    const overview = document.getElementById('projectFollowupOverview');
    if (overview && overview.classList.contains('hidden')) return;

    const cards = Array.from(page.querySelectorAll('.followup-uniform-card'));
    if (!cards.length) return;

    const contentCards = cards.filter(c => !c.classList.contains('add-card-box'));

    // Reset inline sizing so we measure clean natural dimensions
    cards.forEach(card => {
      card.style.height = 'auto';
      const topBlock = card.querySelector('.followup-card-top');
      const clientEl = card.querySelector('.followup-card-client');
      const nextBox = card.querySelector('.followup-next-step-box');
      const nextText = card.querySelector('.followup-next-step-text');
      const titleEl = card.querySelector('.followup-card-title');
      if (topBlock) {
        topBlock.style.minHeight = '';
      }
      if (clientEl) {
        clientEl.style.fontSize = '';
        clientEl.style.lineHeight = '';
        clientEl.style.letterSpacing = '';
      }
      if (nextBox) {
        nextBox.style.minHeight = '';
        nextBox.style.paddingTop = '';
        nextBox.style.paddingBottom = '';
        nextBox.style.paddingLeft = '';
        nextBox.style.paddingRight = '';
        nextBox.style.gap = '';
      }
      if (nextText) {
        nextText.style.fontSize = '';
        nextText.style.lineHeight = '';
        nextText.style.letterSpacing = '';
      }
      if (titleEl) {
        titleEl.style.fontSize = '';
        titleEl.style.lineHeight = '';
        titleEl.style.minHeight = '';
      }
    });

    // Step 1: Compact any multi-line client, title, or NEXT box so all cards stay sleek and compact
    const targetNextBoxMax = 34;
    contentCards.forEach(card => {
      const clientEl = card.querySelector('.followup-card-client');
      const nextBox = card.querySelector('.followup-next-step-box');
      const nextText = card.querySelector('.followup-next-step-text');
      const titleEl = card.querySelector('.followup-card-title');

      if (clientEl && clientEl.offsetHeight > 18) {
        clientEl.style.lineHeight = '1.15';
        clientEl.style.letterSpacing = '0.02em';
        let guard = 0;
        while (clientEl.offsetHeight > 18 && guard < 8) {
          guard++;
          const curClientSize = parseFloat(window.getComputedStyle(clientEl).fontSize) || 11;
          if (curClientSize <= 8.5) break;
          clientEl.style.fontSize = `${Math.max(8.5, curClientSize - 0.5)}px`;
        }
      }

      if (nextBox && nextText && nextBox.offsetHeight > targetNextBoxMax) {
        nextBox.style.paddingTop = '4px';
        nextBox.style.paddingBottom = '4px';
        nextBox.style.paddingLeft = '8px';
        nextBox.style.paddingRight = '8px';
        nextBox.style.gap = '5px';
        nextText.style.lineHeight = '1.15';
        nextText.style.letterSpacing = '-0.01em';
        let guard = 0;
        while (nextBox.offsetHeight > targetNextBoxMax && guard < 12) {
          guard++;
          const curSize = parseFloat(window.getComputedStyle(nextText).fontSize) || 10.5;
          if (curSize <= 8.5) break;
          nextText.style.fontSize = `${Math.max(8.5, curSize - 0.5)}px`;
        }
      }

      if (titleEl && titleEl.offsetHeight > 22) {
        titleEl.style.lineHeight = '1.15';
        let guard = 0;
        while (titleEl.offsetHeight > 22 && guard < 8) {
          guard++;
          const curTitleSize = parseFloat(window.getComputedStyle(titleEl).fontSize) || 13;
          if (curTitleSize <= 11) break;
          titleEl.style.fontSize = `${Math.max(11, curTitleSize - 0.5)}px`;
        }
      }
    });

    // Step 2: Equalize Top block height and NEXT box height so NEXT is centered at the exact same vertical position on every card
    let maxNextBoxH = 30;
    let maxTopH = 0;
    contentCards.forEach(card => {
      const topBlock = card.querySelector('.followup-card-top');
      const nextBox = card.querySelector('.followup-next-step-box');
      if (topBlock && topBlock.offsetHeight > maxTopH) {
        maxTopH = topBlock.offsetHeight;
      }
      if (nextBox && nextBox.offsetHeight > maxNextBoxH) {
        maxNextBoxH = nextBox.offsetHeight;
      }
    });

    contentCards.forEach(card => {
      const topBlock = card.querySelector('.followup-card-top');
      const nextBox = card.querySelector('.followup-next-step-box');
      if (topBlock && maxTopH > 0) topBlock.style.minHeight = `${maxTopH}px`;
      if (nextBox) nextBox.style.minHeight = `${maxNextBoxH}px`;
    });

    // Step 3: Synchronize exact outer card height across all cards (including + Add cards)
    let targetHeight = 0;
    contentCards.forEach(card => {
      if (card.offsetHeight > targetHeight) {
        targetHeight = card.offsetHeight;
      }
    });
    if (targetHeight < 140) targetHeight = 160;

    cards.forEach(card => {
      card.style.height = `${targetHeight}px`;
    });
  }

  function renderFollowupLeadsList(leads, cur) {
    const grid = document.getElementById('followupLeadsGrid');
    const empty = document.getElementById('followupLeadsEmpty');
    if (!grid) return;

    if (empty) empty.classList.add('hidden');

    const addLeadCardHtml = `
      <div id="newFollowupLeadCardBtn" class="followup-uniform-card bg-slate-50/50 hover:bg-white border border-dashed border-slate-300 hover:border-amber-400 rounded-2xl p-4 shadow-2xs hover:shadow-xs transition-colors transition-shadow flex flex-col items-center justify-center text-center gap-2.5 cursor-pointer group add-card-box" title="Add a new lead or inquiry">
        <div class="w-10 h-10 rounded-xl bg-white group-hover:bg-amber-50 text-slate-400 group-hover:text-amber-600 border border-slate-200 group-hover:border-amber-300 flex items-center justify-center transition-all group-hover:scale-105 shadow-2xs">
          <i data-lucide="plus" class="w-4 h-4 stroke-[2.2]"></i>
        </div>
        <div>
          <h4 class="font-semibold text-xs text-slate-700 group-hover:text-amber-900 transition-colors">Add Lead</h4>
          <p class="text-[10px] text-slate-400 mt-0.5">Inquiry, quote or idea</p>
        </div>
      </div>
    `;

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const cardsHtml = (leads || []).map(lead => {
      const amt = parseFloat(lead.amount) || 0;
      const leadCur = lead.currency || cur;
      const status = lead.status || 'Emailing';
      const tagConfig = getLeadTagConfig(status);
      const statusColor = tagConfig.badgeClass;

      let tagText = status;
      let tagClass = statusColor;

      if (lead.targetDate) {
        const d = new Date(lead.targetDate + 'T00:00:00');
        if (!isNaN(d.getTime())) {
          const diffDays = Math.round((d.getTime() - today.getTime()) / 86400000);
          if (diffDays < 0) {
            tagText = `Overdue ${Math.abs(diffDays)}d`;
            tagClass = 'bg-rose-50 text-rose-700 border-rose-200/70';
          } else if (diffDays === 0) {
            tagText = 'Due Today';
            tagClass = 'bg-amber-50 text-amber-700 border-amber-200/70';
          } else if (diffDays === 1) {
            tagText = 'Due Tomorrow';
            tagClass = 'bg-amber-50 text-amber-700 border-amber-200/70';
          }
        }
      }

      let dateStr = 'Recent';
      if (lead.createdAt) {
        const d = new Date(lead.createdAt);
        if (!isNaN(d.getTime())) {
          dateStr = d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
        }
      }

      const equivStr = (amt > 0 && leadCur !== cur)
        ? ` <span class="text-xs text-slate-400 font-normal font-mono">(≈ ${formatMoney(convertCurrency(amt, leadCur, cur), cur)})</span>`
        : '';

      // Next Action prompt
      const steps = Array.isArray(lead.steps) ? lead.steps : [
        { id: 'lead_step_call', title: 'Initial discovery / briefing call', completed: false },
        { id: 'lead_step_scope', title: 'Scope & deliverables outline', completed: false },
        { id: 'lead_step_quote', title: 'Send price offering & proposal', completed: false },
        { id: 'lead_step_followup', title: 'Follow-up with client', completed: false }
      ];
      const nextStep = steps.find(s => !s.completed);
      const completedCount = steps.filter(s => s.completed).length;
      const allDone = (steps.length > 0 && completedCount === steps.length);

      const clientLabel = lead.client || 'Client';
      const titleLabel = lead.title || 'Untitled Lead';
      const nextLabel = allDone
        ? 'All follow-up steps completed'
        : (nextStep ? nextStep.title : 'Click to add follow-up steps');
      const { clientClass, titleClass, nextBoxClass, nextTextClass } = getFollowupAdaptiveTextClasses(clientLabel, titleLabel, nextLabel);

      let nextStepHtml = '';
      if (allDone) {
        nextStepHtml = `
          <div class="followup-next-step-box w-full flex items-center gap-1.5 ${nextBoxClass} text-emerald-800 bg-emerald-50/70 border border-emerald-200/60 rounded-xl font-medium">
            <i data-lucide="check" class="w-3.5 h-3.5 text-emerald-600 shrink-0"></i>
            <span class="followup-next-step-text break-words ${nextTextClass}">All follow-up steps completed</span>
          </div>
        `;
      } else if (nextStep) {
        nextStepHtml = `
          <div class="followup-next-step-box w-full flex items-center gap-1.5 ${nextBoxClass} text-amber-900 bg-amber-50/80 border border-amber-200/70 rounded-xl font-medium">
            <span class="font-bold text-[10px] uppercase tracking-wider text-amber-600 shrink-0">Next:</span>
            <span class="followup-next-step-text break-words ${nextTextClass} flex-1">${escapeHtml(nextStep.title)}</span>
          </div>
        `;
      } else {
        nextStepHtml = `
          <div class="followup-next-step-box w-full flex items-center gap-1.5 ${nextBoxClass} text-slate-500 bg-slate-50 border border-slate-200/60 rounded-xl font-medium">
            <span class="followup-next-step-text break-words ${nextTextClass}">Click to add follow-up steps</span>
          </div>
        `;
      }

      return `
        <div class="followup-uniform-card relative bg-white border border-slate-200/80 hover:border-slate-300 rounded-2xl px-4 pt-3.5 pb-3 shadow-2xs hover:shadow-xs transition-colors transition-shadow flex flex-col justify-between group cursor-grab active:cursor-grabbing select-none open-lead-detail-btn" data-lead-id="${escapeHtml(lead.id)}">
          
          <!-- Bookmark Tag pinned to top ceiling -->
          <span class="absolute -top-px right-4 px-2.5 pt-1.5 pb-1 rounded-b-md text-[10px] font-medium border border-t-0 ${tagClass} shadow-2xs leading-none">${escapeHtml(tagText)}</span>

          <!-- Top Info Block -->
          <div class="followup-card-top space-y-1 shrink-0">
            <div>
              <div class="flex items-center justify-between gap-2 min-h-[16px] pr-16">
                <span class="followup-card-client ${clientClass} font-medium text-slate-400 uppercase tracking-wider break-words">${escapeHtml(clientLabel)}</span>
              </div>
              <h4 class="followup-card-title font-semibold ${titleClass} text-slate-800 mt-0.5 break-words group-hover:text-amber-600 transition-colors">${escapeHtml(titleLabel)}</h4>
            </div>

            <div class="flex items-baseline gap-2 pt-1 leading-none">
              <span class="font-mono text-sm font-bold text-slate-900 leading-none">${amt > 0 ? `~${formatMoney(amt, leadCur)}${equivStr}` : '<span class="text-xs text-slate-400 font-normal">No price set</span>'}</span>
            </div>
          </div>

          <!-- Centered Middle Block: Next Step Prompt -->
          <div class="flex-1 flex items-center py-2.5 min-h-0">
            ${nextStepHtml}
          </div>

          <!-- Bottom Footer -->
          <div class="pt-2.5 border-t border-slate-100 flex items-center justify-between gap-2 shrink-0">
            <button type="button" class="start-project-from-lead-btn cursor-pointer inline-flex items-center gap-1.5 px-2.5 py-1 rounded-xl bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white text-xs font-semibold shadow-2xs transition-all" data-id="${escapeHtml(lead.id)}">
              <i data-lucide="play" class="w-3 h-3 fill-white"></i>
              <span>Start Project</span>
            </button>

            <span class="text-xs font-medium text-slate-400 group-hover:text-amber-600 group-hover:translate-x-0.5 transition-all flex items-center gap-1">
              Open <span>→</span>
            </span>
          </div>
        </div>
      `;
    }).join('');

    grid.innerHTML = cardsHtml + addLeadCardHtml;
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    const addBox = document.getElementById('newFollowupLeadCardBtn');
    if (addBox) {
      addBox.addEventListener('click', () => openLeadModal(null));
    }

    initSortableFollowupLeads();
    equalizeAndFitFollowupCards();
  }

  function buildFollowupProjectCardHtml(p, cur, today, isCompleted) {
    const totalFee = parseFloat(p.amount !== undefined ? p.amount : p.fee) || 0;
    const paid = parseFloat(p.paidAmount) || 0;
    const remaining = Math.max(0, Math.round((totalFee - paid) * 100) / 100);
    const isDone = isCompleted || isProjectDone(p);
    const isPaid = (paid >= totalFee - 0.005 && totalFee > 0);
    const isHold = p.status === 'hold';
    const isDraft = p.status === 'draft';
    const projCur = p.currency || cur;

    // Multi-currency strings
    const totalFeeEquiv = (projCur !== cur && totalFee > 0)
      ? ` <span class="text-[10px] text-slate-400 font-normal font-mono">(≈ ${formatMoney(convertCurrency(totalFee, projCur, cur), cur)})</span>`
      : '';
    const remainingEquiv = (projCur !== cur && remaining > 0)
      ? ` <span class="text-[10px] text-slate-400 font-normal font-mono">(≈ ${formatMoney(convertCurrency(remaining, projCur, cur), cur)})</span>`
      : '';

    // Deadline calculation
    let deadlineBadge = '';
    const bookmarkBase = 'absolute -top-px right-4 px-2.5 pt-1.5 pb-1 rounded-b-md text-[10px] font-medium border border-t-0 shadow-2xs leading-none';
    if (isDone) {
      deadlineBadge = `<span class="${bookmarkBase} bg-emerald-50 text-emerald-700 border-emerald-200/70">Done</span>`;
    } else if (isHold) {
      deadlineBadge = `<span class="${bookmarkBase} bg-amber-50 text-amber-700 border-amber-200/70">On Hold</span>`;
    } else if (isProjectWorkDone(p) && !isPaid) {
      const payDue = p.paymentDueDate || (p.proformaInvoice && p.proformaInvoice.validUntil) || '';
      if (payDue) {
        const pd = new Date(payDue + 'T00:00:00');
        if (!isNaN(pd.getTime())) {
          const payDiff = Math.round((pd.getTime() - today.getTime()) / 86400000);
          if (payDiff < 0) {
            deadlineBadge = `<span class="${bookmarkBase} bg-rose-50 text-rose-700 border-rose-200/70">Pay Overdue ${Math.abs(payDiff)}d</span>`;
          } else if (payDiff === 0) {
            deadlineBadge = `<span class="${bookmarkBase} bg-purple-50 text-purple-700 border-purple-200/70">Pay Due Today</span>`;
          } else {
            deadlineBadge = `<span class="${bookmarkBase} bg-emerald-50 text-emerald-700 border-emerald-200/70">Work Done · Pay ${payDiff}d</span>`;
          }
        } else {
          deadlineBadge = `<span class="${bookmarkBase} bg-emerald-50 text-emerald-700 border-emerald-200/70">Work Done · Unpaid</span>`;
        }
      } else {
        deadlineBadge = `<span class="${bookmarkBase} bg-emerald-50 text-emerald-700 border-emerald-200/70">Work Done · Unpaid</span>`;
      }
    } else if (p.dueDate) {
      const d = new Date(p.dueDate + 'T00:00:00');
      if (!isNaN(d.getTime())) {
        const diffDays = Math.round((d.getTime() - today.getTime()) / 86400000);
        if (diffDays < 0) {
          deadlineBadge = `<span class="${bookmarkBase} bg-rose-50 text-rose-700 border-rose-200/70">Overdue ${Math.abs(diffDays)}d</span>`;
        } else if (diffDays === 0) {
          deadlineBadge = `<span class="${bookmarkBase} bg-sky-50 text-sky-800 border-sky-200/70">Due Today</span>`;
        } else if (diffDays === 1) {
          deadlineBadge = `<span class="${bookmarkBase} bg-sky-50 text-sky-800 border-sky-200/70">Due Tomorrow</span>`;
        } else {
          deadlineBadge = `<span class="${bookmarkBase} bg-sky-50 text-sky-800 border-sky-200/70">Due in ${diffDays}d</span>`;
        }
      }
    } else {
      deadlineBadge = isDraft
        ? `<span class="${bookmarkBase} bg-slate-100 text-slate-600 border-slate-200/70">Draft</span>`
        : `<span class="${bookmarkBase} bg-slate-100 text-slate-500 border-slate-200/60">No deadline</span>`;
    }

    // Next Action prompt
    const steps = Array.isArray(p.steps) ? p.steps : [];
    const nextStep = steps.find(s => !s.completed);
    const completedCount = steps.filter(s => s.completed).length;
    const progressPercent = steps.length > 0 ? Math.round((completedCount / steps.length) * 100) : (isDone ? 100 : 0);

    const clientLabel = p.client || 'Client';
    const titleLabel = p.title || p.description || 'Untitled Project';
    const nextLabel = isDone
      ? 'All steps finished & project completed'
      : (nextStep ? nextStep.title : 'Click to add project steps');
    const { clientClass, titleClass, nextBoxClass, nextTextClass } = getFollowupAdaptiveTextClasses(clientLabel, titleLabel, nextLabel);

    let nextStepHtml = '';
    if (isDone) {
      nextStepHtml = `
        <div class="followup-next-step-box w-full flex items-center gap-1.5 ${nextBoxClass} text-emerald-800 bg-emerald-50/70 border border-emerald-200/60 rounded-xl font-medium">
          <i data-lucide="check" class="w-3.5 h-3.5 text-emerald-600 shrink-0"></i>
          <span class="followup-next-step-text break-words ${nextTextClass}">All steps finished &amp; project completed</span>
        </div>
      `;
    } else if (nextStep) {
      nextStepHtml = `
        <div class="followup-next-step-box w-full flex items-center gap-1.5 ${nextBoxClass} text-sky-800 bg-sky-50/70 border border-sky-200/60 rounded-xl font-medium">
          <span class="font-bold text-[10px] uppercase tracking-wider text-sky-600 shrink-0">Next:</span>
          <span class="followup-next-step-text break-words ${nextTextClass} flex-1">${escapeHtml(nextStep.title)}</span>
        </div>
      `;
    } else {
      nextStepHtml = `
        <div class="followup-next-step-box w-full flex items-center gap-1.5 ${nextBoxClass} text-slate-600 bg-slate-50 border border-slate-200/60 rounded-xl font-medium">
          <span class="followup-next-step-text break-words ${nextTextClass}">Click to add project steps</span>
        </div>
      `;
    }

    const hoverBorder = isDone ? 'hover:border-emerald-300' : 'hover:border-sky-300';
    const groupHoverTitle = isDone ? 'group-hover:text-emerald-600' : 'group-hover:text-sky-600';
    const progressBarColor = isDone ? 'bg-emerald-500' : 'bg-sky-500';
    const arrowColor = isDone ? 'text-emerald-600' : 'text-sky-600';

    return `
      <div class="followup-uniform-card relative bg-white border border-slate-200/80 hover:border-slate-300 rounded-2xl px-4 pt-3.5 pb-3 shadow-2xs hover:shadow-xs transition-colors transition-shadow flex flex-col justify-between group cursor-grab active:cursor-grabbing select-none open-project-detail-btn" data-project-id="${escapeHtml(p.id)}">
        
        <!-- Bookmark Tag pinned to top ceiling -->
        ${deadlineBadge}

        <!-- Top Info Block -->
        <div class="followup-card-top space-y-1 shrink-0">
          <div>
            <div class="flex items-center justify-between gap-2 min-h-[16px] pr-16">
              <span class="followup-card-client ${clientClass} font-medium text-slate-400 uppercase tracking-wider break-words">${escapeHtml(clientLabel)}</span>
            </div>
            <h4 class="followup-card-title font-semibold ${titleClass} text-slate-800 mt-0.5 break-words ${groupHoverTitle} transition-colors">${escapeHtml(titleLabel)}</h4>
          </div>

          <!-- Money row without divider line -->
          <div class="flex items-baseline justify-between gap-2 pt-1 leading-none">
            <div class="leading-none">
              <span class="text-[10px] text-slate-400 uppercase font-semibold">Fee: </span>
              <span class="font-mono text-sm font-bold text-slate-900">${formatMoney(totalFee, projCur)}${totalFeeEquiv}</span>
            </div>
            <div class="text-right text-xs leading-none">
              ${remaining > 0 ? `
                <span class="text-slate-400">Left: </span>
                <span class="font-mono font-bold text-slate-700">${formatMoney(remaining, projCur)}${remainingEquiv}</span>
              ` : `
                <span class="font-semibold text-emerald-600">Fully Paid ✓</span>
              `}
            </div>
          </div>
        </div>

        <!-- Centered Middle Block: Next Step Prompt -->
        <div class="flex-1 flex items-center py-2.5 min-h-0">
          ${nextStepHtml}
        </div>

        <!-- Bottom: Steps Progress & Open Button -->
        <div class="pt-2.5 border-t border-slate-100 flex items-center justify-between text-xs text-slate-400 shrink-0">
          <div class="flex items-center gap-2">
            <div class="w-16 h-1.5 rounded-full bg-slate-100 overflow-hidden">
              <div class="h-full ${progressBarColor} rounded-full transition-all" style="width: ${progressPercent}%;"></div>
            </div>
            <span class="text-[11px] font-medium text-slate-500">${completedCount}/${steps.length} done</span>
          </div>

          <span class="text-xs font-medium text-slate-400 ${groupHoverTitle} group-hover:translate-x-0.5 transition-transform flex items-center gap-1">
            Open <span>→</span>
          </span>
        </div>
      </div>
    `;
  }

  function renderFollowupProjectsList(activeProjects, completedProjects, cur) {
    const grid = document.getElementById('followupProjectsGrid');
    const empty = document.getElementById('followupProjectsEmpty');
    const completedGrid = document.getElementById('followupCompletedGrid');

    if (empty) empty.classList.add('hidden');

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const addProjectCardHtml = `
      <div id="newFollowupProjectCardBtn" class="followup-uniform-card bg-slate-50/50 hover:bg-white border border-dashed border-slate-300 hover:border-sky-400 rounded-2xl p-4 shadow-2xs hover:shadow-xs transition-colors transition-shadow flex flex-col items-center justify-center text-center gap-2.5 cursor-pointer group add-card-box" title="Start a new ongoing project">
        <div class="w-10 h-10 rounded-xl bg-white group-hover:bg-sky-50 text-slate-400 group-hover:text-sky-600 border border-slate-200 group-hover:border-sky-300 flex items-center justify-center transition-all group-hover:scale-105 shadow-2xs">
          <i data-lucide="plus" class="w-4 h-4 stroke-[2.2]"></i>
        </div>
        <div>
          <h4 class="font-semibold text-xs text-slate-700 group-hover:text-sky-900 transition-colors">Add Project</h4>
          <p class="text-[10px] text-slate-400 mt-0.5">Start new ongoing job</p>
        </div>
      </div>
    `;

    const addCompletedCardHtml = `
      <div id="newFollowupCompletedCardBtn" class="followup-uniform-card bg-slate-50/50 hover:bg-white border border-dashed border-slate-300 hover:border-emerald-400 rounded-2xl p-4 shadow-2xs hover:shadow-xs transition-colors transition-shadow flex flex-col items-center justify-center text-center gap-2.5 cursor-pointer group add-card-box" title="Record a finished project">
        <div class="w-10 h-10 rounded-xl bg-white group-hover:bg-emerald-50 text-slate-400 group-hover:text-emerald-600 border border-slate-200 group-hover:border-emerald-300 flex items-center justify-center transition-all group-hover:scale-105 shadow-2xs">
          <i data-lucide="plus" class="w-4 h-4 stroke-[2.2]"></i>
        </div>
        <div>
          <h4 class="font-semibold text-xs text-slate-700 group-hover:text-emerald-900 transition-colors">Add Finished Project</h4>
          <p class="text-[10px] text-slate-400 mt-0.5">Record past delivered job</p>
        </div>
      </div>
    `;

    if (grid) {
      const cardsHtml = (activeProjects || []).map(p => buildFollowupProjectCardHtml(p, cur, today, false)).join('');
      grid.innerHTML = cardsHtml + addProjectCardHtml;

      const addBox = document.getElementById('newFollowupProjectCardBtn');
      if (addBox) {
        addBox.addEventListener('click', () => {
          if (typeof resetProjectForm === 'function') resetProjectForm();
          if (typeof showProjectModal === 'function') showProjectModal();
        });
      }
    }

    if (completedGrid) {
      const cardsHtml = (completedProjects || []).map(p => buildFollowupProjectCardHtml(p, cur, today, true)).join('');
      completedGrid.innerHTML = cardsHtml + addCompletedCardHtml;

      const addBox = document.getElementById('newFollowupCompletedCardBtn');
      if (addBox) {
        addBox.addEventListener('click', () => {
          if (typeof resetProjectForm === 'function') resetProjectForm();
          const statusEl = document.getElementById('freelanceStatus');
          if (statusEl) {
            statusEl.value = 'paid';
            statusEl.dispatchEvent(new Event('change'));
          }
          const titleEl = document.getElementById('freelanceModalTitle');
          if (titleEl) titleEl.textContent = 'Add Finished Project';
          if (typeof showProjectModal === 'function') showProjectModal();
        });
      }
    }

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    initSortableFollowupProjects();
    equalizeAndFitFollowupCards();
  }

