  // LEAD DETAIL PAGE (Adjusted for Inquiries)
  // ==========================================
  function openLeadDetailPage(leadId) {
    state.activeFollowupLeadId = leadId;
    state.activeFollowupProjectId = null;
    state.activePriceOfferingLeadId = null;
    state.activeProformaProjectId = null;
    try {
      localStorage.setItem('ft_active_followup_lead', leadId);
      localStorage.removeItem('ft_active_followup_project');
      history.replaceState(null, '', '#project_followup/lead:' + leadId);
      recordFinlandRoute('#project_followup/lead:' + leadId);
    } catch (e) {}
    const view = document.getElementById('viewProjectFollowup');
    if (view && view.classList.contains('hidden') && typeof switchTab === 'function') {
      switchTab('project_followup');
    }
    renderProjectFollowupView();
    if (typeof window.scrollTo === 'function') window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  function flushLeadDetailChanges() {
    const lead = (state.budget.leads || []).find(x => x.id === state.activeFollowupLeadId);
    if (!lead) return;
    const prevClient = lead.client;
    const prevTitle = lead.title;

    // 1. Commit Client Name if form is open or input has text
    const clientForm = document.getElementById('leadDetailClientNameEditForm');
    if (clientForm && !clientForm.classList.contains('hidden')) {
      const clientInput = document.getElementById('leadDetailClientNameInput');
      if (clientInput && clientInput.value.trim()) {
        lead.client = clientInput.value.trim();
      }
    }

    // 2. Commit Title if form is open or input has text
    const titleForm = document.getElementById('leadDetailTitleEditForm');
    if (titleForm && !titleForm.classList.contains('hidden')) {
      const titleInput = document.getElementById('leadDetailTitleInput');
      if (titleInput && titleInput.value.trim()) {
        lead.title = titleInput.value.trim();
      }
    }

    // 3. Commit Amount & Currency if form is open
    const amtForm = document.getElementById('leadDetailAmountEditForm');
    if (amtForm && !amtForm.classList.contains('hidden')) {
      const amtInput = document.getElementById('leadDetailAmountInput');
      const curSelect = document.getElementById('leadDetailCurrencySelect');
      if (amtInput) {
        const val = amtInput.value.trim();
        const newAmt = val === '' ? 0 : parseFloat(val);
        if (!isNaN(newAmt) && newAmt >= 0) {
          lead.amount = newAmt;
          if (curSelect) lead.currency = curSelect.value || state.displayCurrency;
          if (lead.priceOffering) {
            syncDraftSingleItemAmount(lead.priceOffering, newAmt, lead.currency);
          }
        }
      }
    }

    // 4. Commit Opportunity Stage Date if present
    const oppDate = document.getElementById('leadDetailOpportunityDateInput');
    if (oppDate && oppDate.value) lead.statusDate = oppDate.value;

    // 5. Commit Follow-up Date if form is open
    const dateForm = document.getElementById('leadDetailFollowupDateEditForm');
    if (dateForm && !dateForm.classList.contains('hidden')) {
      const dateInput = document.getElementById('leadDetailFollowupDateInput');
      if (dateInput) {
        lead.targetDate = dateInput.value || '';
      }
    }

    if (lead.priceOffering) {
      syncFollowupDocMetadataWithEntity(lead.priceOffering, lead, prevClient, prevTitle);
    }

    // 6. Commit all Notes textareas
    const noteTextareas = document.querySelectorAll('#leadDetailNotesContainer .lead-note-textarea');
    if (noteTextareas.length > 0) {
      if (!Array.isArray(lead.notesList)) lead.notesList = [];
      noteTextareas.forEach((ta, i) => {
        const val = ta.value;
        const noteId = ta.getAttribute('data-note-id');
        let item = lead.notesList.find(n => n.id === noteId);
        if (!item) {
          item = { id: noteId || ('note_' + Date.now() + '_' + i), text: val, date: '' };
          lead.notesList.push(item);
        } else {
          item.text = val;
        }
      });
      lead.notes = lead.notesList.map(n => n.text).filter(t => t && t.trim()).join('\n\n---\n\n');
    }

    // 7. Commit any step title inputs currently in progress
    const stepInputs = document.querySelectorAll('#leadDetailStepsContainer .lead-step-title-input');
    stepInputs.forEach(input => {
      const stepId = input.getAttribute('data-lead-step-id') || input.getAttribute('data-step-id');
      const s = (lead.steps || []).find(x => x.id === stepId);
      if (s && input.value.trim()) {
        s.title = input.value.trim();
      }
    });

    saveBudget();
  }

  function closeLeadDetailPage() {
    flushLeadDetailChanges();
    if (typeof goBackInFinland === 'function' && currentNavRoute && currentNavRoute.startsWith('#project_followup/lead:')) {
      if (goBackInFinland()) return;
    }
    state.activeFollowupLeadId = null;
    try {
      localStorage.removeItem('ft_active_followup_lead');
      history.replaceState(null, '', '#project_followup');
      recordFinlandRoute('#project_followup');
    } catch (e) {}
    renderProjectFollowupView();
  }

