  const COLOR_ALIASES = {
    rose: 'red',
    fuchsia: 'pink',
    violet: 'purple'
  };

  const DEFAULT_LEAD_TAG_DEFINITIONS = [
    { name: 'Emailing', defaultColor: 'amber' },
    { name: 'Quote Sent', defaultColor: 'blue' },
    { name: 'Waiting for Answer', defaultColor: 'purple' },
    { name: 'Negotiating', defaultColor: 'emerald' },
    { name: 'Passed / Lost', defaultColor: 'slate' }
  ];

  function resolveTagColor(tagName, fallbackColor = 'indigo') {
    if (!tagName) return TAG_COLOR_PALETTE[fallbackColor] || TAG_COLOR_PALETTE.indigo;
    const sLower = tagName.toLowerCase();
    if (state.budget && state.budget.leadTagColors && state.budget.leadTagColors[sLower]) {
      let cKey = state.budget.leadTagColors[sLower];
      if (COLOR_ALIASES[cKey]) cKey = COLOR_ALIASES[cKey];
      if (TAG_COLOR_PALETTE[cKey]) return TAG_COLOR_PALETTE[cKey];
    }
    if (state.budget && Array.isArray(state.budget.leadTags)) {
      const custom = state.budget.leadTags.find(t => (typeof t === 'object' && t && t.name && t.name.toLowerCase() === sLower));
      if (custom && custom.color) {
        const cKey = COLOR_ALIASES[custom.color] || custom.color;
        if (TAG_COLOR_PALETTE[cKey]) return TAG_COLOR_PALETTE[cKey];
      }
    }
    const def = DEFAULT_LEAD_TAG_DEFINITIONS.find(d => d.name.toLowerCase() === sLower || (d.name.toLowerCase().startsWith('passed') && sLower.startsWith('passed')));
    if (def) {
      const dColor = COLOR_ALIASES[def.defaultColor] || def.defaultColor;
      if (TAG_COLOR_PALETTE[dColor]) return TAG_COLOR_PALETTE[dColor];
    }
    const fColor = COLOR_ALIASES[fallbackColor] || fallbackColor;
    return TAG_COLOR_PALETTE[fColor] || TAG_COLOR_PALETTE.indigo;
  }

  function getAvailableLeadTags() {
    if (!state.budget) state.budget = {};
    if (!Array.isArray(state.budget.leadTags)) state.budget.leadTags = [];
    const defTags = DEFAULT_LEAD_TAG_DEFINITIONS.map(d => {
      const colorObj = resolveTagColor(d.name, d.defaultColor);
      return {
        name: d.name,
        color: colorObj.id,
        dotClass: colorObj.dotClass,
        textClass: colorObj.textClass,
        badgeClass: colorObj.badgeClass,
        isDefault: true
      };
    });
    const defNames = new Set(defTags.map(x => x.name.toLowerCase()));
    const customTags = state.budget.leadTags
      .map(t => {
        const name = typeof t === 'string' ? t : (t.name || '');
        if (!name) return null;
        const colorKey = (typeof t === 'object' && t.color) ? t.color : 'indigo';
        const colorObj = resolveTagColor(name, colorKey);
        return {
          id: (typeof t === 'object' && t.id) ? t.id : ('tag_' + name.toLowerCase()),
          name: name,
          color: colorObj.id,
          dotClass: colorObj.dotClass,
          textClass: colorObj.textClass,
          badgeClass: colorObj.badgeClass,
          isDefault: false
        };
      })
      .filter(Boolean)
      .filter(t => !defNames.has(t.name.toLowerCase()));
    return [...defTags, ...customTags];
  }

  function getLeadTagConfig(statusName) {
    if (!statusName) return getAvailableLeadTags()[0];
    const sLower = statusName.toLowerCase();
    const tags = getAvailableLeadTags();
    const found = tags.find(t => t.name.toLowerCase() === sLower || (t.name.toLowerCase().startsWith('passed') && sLower.startsWith('passed')));
    if (found) return found;
    const colorObj = resolveTagColor(statusName, 'indigo');
    return {
      name: statusName,
      color: colorObj.id,
      dotClass: colorObj.dotClass,
      textClass: colorObj.textClass,
      badgeClass: colorObj.badgeClass,
      isDefault: false
    };
  }

  let selectedNewCustomTagColor = 'indigo';

  function renderNewCustomTagColorPalette() {
    const container = document.getElementById('newCustomTagColorPalette');
    if (!container) return;
    const curColor = TAG_COLOR_PALETTE[selectedNewCustomTagColor] ? selectedNewCustomTagColor : 'indigo';
    container.innerHTML = Object.values(TAG_COLOR_PALETTE).map(c => `
      <button type="button" class="choose-new-tag-color-btn w-7 h-7 rounded-full ${c.dotClass} flex items-center justify-center hover:scale-115 transition-transform cursor-pointer shadow-2xs ${curColor === c.id ? (c.id === 'black' ? 'ring-2 ring-indigo-500 ring-offset-2 ring-offset-slate-50 scale-105' : 'ring-2 ring-slate-900 ring-offset-2 ring-offset-slate-50 scale-105') : 'hover:ring-1 hover:ring-black/20'}" data-color="${c.id}" title="${c.label}">
        ${curColor === c.id ? `<i data-lucide="check" class="w-3.5 h-3.5 ${(c.id === 'yellow' || c.id === 'lime') ? 'text-slate-900' : 'text-white'} stroke-[2.5]"></i>` : ''}
      </button>
    `).join('');
    const dot = document.getElementById('newTagActiveColorDot');
    if (dot) dot.className = `w-4 h-4 rounded-full ${TAG_COLOR_PALETTE[curColor].dotClass} shrink-0 shadow-2xs ring-1 ring-black/10`;
    const label = document.getElementById('newTagColorLabel');
    if (label) label.textContent = TAG_COLOR_PALETTE[curColor].label;
    const saveBtn = document.getElementById('saveCustomTagBtn');
    if (saveBtn) saveBtn.className = `px-2.5 py-1 rounded-lg ${TAG_COLOR_PALETTE[curColor].dotClass} hover:opacity-90 text-white font-semibold text-xs cursor-pointer shrink-0 shadow-2xs flex items-center gap-1 transition-all`;
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function renderLeadDetailPage(lead, cur) {
    if (!lead) return;
    const leadCur = lead.currency || cur;
    const amt = parseFloat(lead.amount) || 0;
    const status = lead.status || 'Emailing';

    const setTxt = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };

    // Client Name
    setTxt('leadDetailClientName', lead.client || 'Client');
    const clientWrapper = document.querySelector('#leadDetailPage .group\\/client');
    if (clientWrapper) clientWrapper.classList.remove('hidden');
    const clientForm = document.getElementById('leadDetailClientNameEditForm');
    if (clientForm) { clientForm.classList.add('hidden'); clientForm.classList.remove('flex'); }

    // Inquiry Title
    setTxt('leadDetailTitle', lead.title || 'Untitled Inquiry');
    const titleWrapper = document.querySelector('#leadDetailPage .group\\/title');
    if (titleWrapper) titleWrapper.classList.remove('hidden');
    const titleForm = document.getElementById('leadDetailTitleEditForm');
    if (titleForm) { titleForm.classList.add('hidden'); titleForm.classList.remove('flex'); }

    // Status Badge & Dropdown with Tags (Preserve rounded pill highlight design with outline)
    const allTags = getAvailableLeadTags();
    const activeTagConfig = getLeadTagConfig(status);

    const statusBadge = document.getElementById('leadDetailStatusBadge');
    const statusBadgeText = document.getElementById('leadDetailStatusBadgeText');
    if (statusBadge && statusBadgeText) {
      statusBadgeText.textContent = activeTagConfig.name || status;
      statusBadge.className = `px-2.5 py-0.5 rounded-full text-[10px] font-bold ${activeTagConfig.badgeClass} cursor-pointer hover:ring-2 hover:ring-amber-300 transition-all flex items-center gap-1 shadow-2xs leading-normal`;
    }

    // Populate Left-side Status Dropdown Tags List with interactive color change triggers
    const statusDropdown = document.getElementById('leadDetailStatusDropdown');
    const wasDropdownOpen = statusDropdown && !statusDropdown.classList.contains('hidden');

    const presetTagsList = document.getElementById('leadDetailPresetTagsList');
    if (presetTagsList) {
      presetTagsList.innerHTML = allTags.map(tag => {
        const isSelected = (tag.name.toLowerCase() === status.toLowerCase() || (tag.name.toLowerCase().startsWith('passed') && status.toLowerCase().startsWith('passed')));
        return `
          <div class="lead-tag-row group/tag rounded-xl transition-all" data-tag-name="${escapeHtml(tag.name)}">
            <div class="flex items-center justify-between px-2.5 py-1.5 rounded-xl transition-all ${isSelected ? 'bg-slate-100 font-bold shadow-2xs' : 'hover:bg-slate-50'}">
              <button type="button" class="set-lead-status-btn flex-1 text-left font-semibold flex items-center justify-between cursor-pointer mr-2 transition-colors ${tag.textClass}" data-status="${escapeHtml(tag.name)}" title="Set stage to ${escapeHtml(tag.name)}">
                <span class="truncate ${tag.textClass}">${escapeHtml(tag.name)}</span>
                ${isSelected ? `<i data-lucide="check" class="w-3.5 h-3.5 ${tag.textClass} ml-1.5 shrink-0 stroke-[2.5]"></i>` : ''}
              </button>
              <div class="flex items-center gap-1 shrink-0">
                <button type="button" class="lead-tag-color-trigger w-6 h-6 rounded-lg hover:bg-slate-200/60 text-slate-400 hover:text-slate-700 cursor-pointer transition-all flex items-center justify-center group-hover/tag:ring-1 group-hover/tag:ring-slate-300/60" data-tag-name="${escapeHtml(tag.name)}" title="Change color for ${escapeHtml(tag.name)}">
                  <span class="w-3.5 h-3.5 rounded-full ${tag.dotClass} block shadow-2xs hover:scale-125 transition-transform ring-2 ring-white"></span>
                </button>
                ${!tag.isDefault ? `
                  <button type="button" class="delete-lead-tag-btn w-5 h-5 rounded-md text-slate-300 hover:text-rose-500 hover:bg-rose-50 cursor-pointer opacity-0 group-hover/tag:opacity-100 transition-opacity flex items-center justify-center" data-tag-name="${escapeHtml(tag.name)}" title="Delete tag">
                    <i data-lucide="x" class="w-3 h-3"></i>
                  </button>
                ` : ''}
              </div>
            </div>

            <!-- Dedicated Sleek Inline Color Palette Drawer for this specific tag -->
            <div class="tag-color-palette-drawer hidden p-2.5 my-1.5 bg-slate-50/90 border border-slate-200/80 rounded-xl shadow-xs animate-scale-in">
              <div class="flex items-center justify-between pb-1.5 mb-1.5 border-b border-slate-200/60">
                <div class="flex items-center gap-1.5 min-w-0">
                  <span class="w-2.5 h-2.5 rounded-full ${tag.dotClass} shrink-0 ring-1 ring-black/10"></span>
                  <span class="text-[11px] font-semibold text-slate-600 truncate">Color: <span class="font-bold ${tag.textClass}">${escapeHtml(tag.name)}</span></span>
                </div>
                <button type="button" class="close-tag-palette-btn text-slate-400 hover:text-slate-700 p-0.5 rounded cursor-pointer transition-colors" title="Close">
                  <i data-lucide="x" class="w-3 h-3"></i>
                </button>
              </div>
              <div class="grid grid-cols-5 place-items-center gap-2 py-0.5">
                ${Object.values(TAG_COLOR_PALETTE).map(c => `
                  <button type="button" class="set-tag-color-btn w-7 h-7 rounded-full ${c.dotClass} flex items-center justify-center hover:scale-115 transition-transform cursor-pointer shadow-2xs ${tag.color === c.id ? (c.id === 'black' ? 'ring-2 ring-indigo-500 ring-offset-2 ring-offset-slate-50 scale-105' : 'ring-2 ring-slate-900 ring-offset-2 ring-offset-slate-50 scale-105') : 'hover:ring-1 hover:ring-black/20'}" data-tag-name="${escapeHtml(tag.name)}" data-color="${c.id}" title="${c.label}">
                    ${tag.color === c.id ? `<i data-lucide="check" class="w-3.5 h-3.5 ${(c.id === 'yellow' || c.id === 'lime') ? 'text-slate-900' : 'text-white'} stroke-[2.5]"></i>` : ''}
                  </button>
                `).join('')}
              </div>
              <div class="mt-1.5 pt-1 border-t border-slate-200/60 text-center">
                <span class="text-[10px] font-medium uppercase tracking-wider ${tag.textClass}">${TAG_COLOR_PALETTE[tag.color]?.label || 'Color'}</span>
              </div>
            </div>
          </div>
        `;
      }).join('');
    }

    if (statusDropdown && !wasDropdownOpen) statusDropdown.classList.add('hidden');
    const showAddBtn = document.getElementById('leadDetailShowAddTagBtn');
    if (showAddBtn) showAddBtn.classList.remove('hidden');
    const addTagForm = document.getElementById('addLeadCustomTagForm');
    if (addTagForm) { addTagForm.classList.add('hidden'); addTagForm.classList.remove('flex'); }

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    // Estimated Value Box & Form
    setTxt('leadDetailAmount', amt > 0 ? `~${formatMoney(amt, leadCur)}` : 'No price set');
    const amtEquivEl = document.getElementById('leadDetailAmountEquiv');
    if (amtEquivEl) {
      if (amt > 0) {
        const otherCurs = ['USD', 'ILS', 'EUR'].filter(c => c !== leadCur);
        const targetCur1 = otherCurs[0];
        const targetCur2 = otherCurs[1];
        const conv1 = formatMoney(convertCurrency(amt, leadCur, targetCur1), targetCur1);
        const conv2 = formatMoney(convertCurrency(amt, leadCur, targetCur2), targetCur2);
        amtEquivEl.textContent = `≈ ${conv1} • ${conv2}`;
        amtEquivEl.classList.remove('hidden');
      } else {
        amtEquivEl.textContent = 'Click to set';
        amtEquivEl.classList.remove('hidden');
      }
    }
    const amtDisplay = document.getElementById('leadDetailAmountDisplay');
    if (amtDisplay) amtDisplay.classList.remove('hidden');
    const amtForm = document.getElementById('leadDetailAmountEditForm');
    if (amtForm) { amtForm.classList.add('hidden'); amtForm.classList.remove('flex'); }
    const curSelect = document.getElementById('leadDetailCurrencySelect');
    if (curSelect) curSelect.value = leadCur;
    const amtInput = document.getElementById('leadDetailAmountInput');
    if (amtInput) amtInput.value = amt > 0 ? amt : '';

    // Opportunity Stage & Date Info (Fully Editable & Accurate Date)
    setTxt('leadDetailStageText', status);
    const stageTextEl = document.getElementById('leadDetailStageText');
    if (stageTextEl) {
      stageTextEl.className = `text-base font-bold ${activeTagConfig.textClass}`;
    }
    const stageDot = document.getElementById('leadDetailStageDot');
    if (stageDot) stageDot.remove();

    let stageDateStr = lead.statusDate;
    if (!stageDateStr && lead.createdAt) {
      stageDateStr = lead.createdAt.split('T')[0];
    }
    let stageDateDisplay = 'No date set';
    if (stageDateStr) {
      const d = new Date(stageDateStr + 'T00:00:00');
      if (!isNaN(d.getTime())) {
        stageDateDisplay = d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
      } else {
        stageDateDisplay = stageDateStr;
      }
    }
    setTxt('leadDetailAgeText', stageDateDisplay);

    const oppDisplay = document.getElementById('leadDetailOpportunityDisplay');
    const oppDateInput = document.getElementById('leadDetailOpportunityDateInput');
    if (oppDisplay) oppDisplay.classList.remove('hidden');
    if (oppDateInput) {
      oppDateInput.value = stageDateStr || new Date().toISOString().split('T')[0];
    }

    // Target Follow-up Date Box & Form
    const followupDisplay = document.getElementById('leadDetailFollowupDateDisplay');
    if (followupDisplay) followupDisplay.classList.remove('hidden');
    const followupForm = document.getElementById('leadDetailFollowupDateEditForm');
    if (followupForm) { followupForm.classList.add('hidden'); followupForm.classList.remove('flex'); }
    const followupInput = document.getElementById('leadDetailFollowupDateInput');
    if (followupInput) followupInput.value = lead.targetDate || '';

    const followupTextEl = document.getElementById('leadDetailFollowupDateText');
    const followupCountdownEl = document.getElementById('leadDetailFollowupCountdown');
    if (lead.targetDate) {
      const d = new Date(lead.targetDate + 'T00:00:00');
      if (!isNaN(d.getTime())) {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const diffDays = Math.round((d.getTime() - today.getTime()) / 86400000);
        if (followupTextEl) followupTextEl.textContent = d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
        if (followupCountdownEl) {
          if (diffDays < 0) {
            followupCountdownEl.textContent = `Overdue by ${Math.abs(diffDays)}d`;
            followupCountdownEl.className = 'text-[10px] font-bold text-rose-600 mt-0.5';
          } else if (diffDays === 0) {
            followupCountdownEl.textContent = 'Follow up Today';
            followupCountdownEl.className = 'text-[10px] font-bold text-amber-600 mt-0.5';
          } else if (diffDays === 1) {
            followupCountdownEl.textContent = 'Follow up Tomorrow';
            followupCountdownEl.className = 'text-[10px] font-semibold text-amber-600 mt-0.5';
          } else {
            followupCountdownEl.textContent = `in ${diffDays} days`;
            followupCountdownEl.className = 'text-[10px] font-semibold text-slate-500 mt-0.5';
          }
        }
      }
    } else {
      if (followupTextEl) followupTextEl.textContent = 'No date set';
      if (followupCountdownEl) {
        followupCountdownEl.textContent = 'Click to set';
        followupCountdownEl.className = 'text-[10px] font-semibold text-slate-400 mt-0.5';
      }
    }

    // Follow-up Steps Checklist
    if (!Array.isArray(lead.steps)) {
      lead.steps = [
        { id: 'lead_step_call', title: 'Initial discovery / briefing call', completed: false },
        { id: 'lead_step_scope', title: 'Scope & deliverables outline', completed: false },
        { id: 'lead_step_quote', title: 'Send price offering & proposal', completed: false },
        { id: 'lead_step_followup', title: 'Follow-up with client', completed: false }
      ];
    }
    const steps = lead.steps;
    const completedCount = steps.filter(s => s.completed).length;
    setTxt('leadDetailStepsProgressPill', `${completedCount} of ${steps.length}`);

    const stepsContainer = document.getElementById('leadDetailStepsContainer');
    if (stepsContainer) {
      if (steps.length === 0) {
        stepsContainer.innerHTML = `<div class="py-4 text-center text-xs text-slate-400 bg-slate-50/70 rounded-xl border border-dashed border-slate-200">No follow-up steps added yet. Click one of the quick steps below or add your own.</div>`;
      } else {
        stepsContainer.innerHTML = steps.map(step => {
          const stepDateVal = step.dueDate || step.plannedDate || (step.completed ? step.completedDate : '') || '';
          let dateFormatted = '';
          if (stepDateVal) {
            const sd = new Date(stepDateVal + 'T00:00:00');
            dateFormatted = !isNaN(sd.getTime()) ? sd.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) : stepDateVal;
          }
          return `
            <div class="flex items-center justify-between p-2 rounded-xl border ${step.completed ? 'bg-slate-50/70 border-slate-200/70' : 'bg-white border-slate-200 hover:border-slate-300'} transition-all group/step select-none" data-lead-step-id="${escapeHtml(step.id)}">
              <div class="flex items-center gap-2 flex-1 min-w-0">
                <div class="lead-step-drag-handle p-1 text-slate-300 hover:text-slate-600 cursor-grab active:cursor-grabbing shrink-0 transition-colors" title="Drag to reorder">
                  <i data-lucide="grip-vertical" class="w-3.5 h-3.5"></i>
                </div>
                <input type="checkbox" class="lead-step-checkbox w-4 h-4 rounded text-amber-500 focus:ring-amber-400 border-slate-300 cursor-pointer shrink-0" data-lead-step-id="${escapeHtml(step.id)}" data-step-id="${escapeHtml(step.id)}" ${step.completed ? 'checked' : ''}>
                <!-- Inline Editable Lead Step Title Input -->
                <input type="text" class="lead-step-title-input flex-1 min-w-0 bg-transparent border-b border-transparent hover:border-slate-200 focus:border-amber-500 focus:bg-white/80 focus:outline-none px-1.5 py-0.5 text-xs font-medium rounded transition-all ${step.completed ? 'line-through text-slate-400' : 'text-slate-800'}" data-lead-step-id="${escapeHtml(step.id)}" data-step-id="${escapeHtml(step.id)}" value="${escapeHtml(step.title)}" title="Click to edit step title">
              </div>
              <div class="flex items-center gap-2 shrink-0 ml-2">
                <!-- Editable Little Date -->
                ${dateFormatted ? `
                  <div class="lead-step-date-wrapper relative flex items-center shrink-0 cursor-pointer" data-lead-step-id="${escapeHtml(step.id)}" title="Click to change date">
                    <span class="lead-step-date-text text-[10px] text-slate-400 font-mono hover:text-slate-700 hover:underline transition-colors select-none" data-lead-step-id="${escapeHtml(step.id)}">${escapeHtml(dateFormatted)}</span>
                    <input type="date" class="lead-step-date-picker-input absolute inset-0 opacity-0 cursor-pointer w-full h-full" data-lead-step-id="${escapeHtml(step.id)}" value="${escapeHtml(stepDateVal)}" title="Click to change date">
                  </div>
                ` : `
                  <div class="lead-step-date-wrapper relative flex items-center shrink-0 opacity-0 group-hover/step:opacity-100 transition-opacity cursor-pointer" data-lead-step-id="${escapeHtml(step.id)}" title="Schedule date">
                    <span class="lead-step-date-text text-slate-300 hover:text-slate-600 cursor-pointer p-0.5" data-lead-step-id="${escapeHtml(step.id)}">
                      <i data-lucide="calendar" class="w-3 h-3"></i>
                    </span>
                    <input type="date" class="lead-step-date-picker-input absolute inset-0 opacity-0 cursor-pointer w-full h-full" data-lead-step-id="${escapeHtml(step.id)}" value="" title="Schedule date">
                  </div>
                `}
                <!-- Permanently Visible Little "X" for Deletion -->
                <button type="button" class="delete-lead-step-btn text-slate-400 hover:text-rose-600 hover:bg-rose-50 p-1 rounded-md transition-colors cursor-pointer shrink-0" data-lead-step-id="${escapeHtml(step.id)}" title="Delete step">
                  <i data-lucide="x" class="w-3.5 h-3.5"></i>
                </button>
              </div>
            </div>
          `;
        }).join('');
      }
      initSortableLeadSteps();
    }

    // Dynamic Notes Scratchpad (Auto-expanding multi text boxes)
    renderLeadNotes(lead);

    // Update Top Bar Price Offering Button Text
    const poTopBtnText = document.getElementById('leadDetailGeneratePriceOfferingBtnText');
    if (poTopBtnText) {
      poTopBtnText.textContent = lead.priceOffering ? 'Edit Price Quote / Proposal' : 'Generate Price Quote / Proposal';
    }

    // Documents (Quote/Proposal & Client Brief)
    const quoteStatus = document.getElementById('leadDetailQuoteStatusText');
    const quoteActions = document.getElementById('leadDetailQuoteActions');
    const quoteSavedList = document.getElementById('leadDetailQuoteSavedList');
    const quoteExports = Array.isArray(lead.quoteExports) ? lead.quoteExports : [];
    const quoteAttachments = getLeadQuoteAttachmentsList(lead);

    if (quoteStatus && quoteActions) {
      if (lead.priceOffering) {
        const poCur = lead.priceOffering.currency || leadCur;
        const poTot = parseFloat(lead.priceOffering.total) || 0;
        const poRef = lead.priceOffering.refNo ? ` · ${lead.priceOffering.refNo}` : '';
        if (quoteExports.length > 0) {
          const latestVer = quoteExports[0].version || 1;
          const matchesLatest = getPoContentFingerprint(lead.priceOffering) === getPoContentFingerprint(quoteExports[0].data);
          quoteStatus.textContent = matchesLatest
            ? `Editable Doc (${formatMoney(poTot, poCur)}${poRef}) · Saved (v${latestVer})`
            : `Editable Doc (${formatMoney(poTot, poCur)}${poRef}) · Edited since v${latestVer}`;
        } else {
          quoteStatus.textContent = `Editable Doc (${formatMoney(poTot, poCur)}${poRef})`;
        }
        quoteActions.innerHTML = `
          <button type="button" class="open-lead-price-offering-btn px-2.5 py-1 bg-amber-500 hover:bg-amber-600 active:scale-95 text-white rounded-lg text-xs font-semibold shadow-2xs cursor-pointer transition-all" data-id="${escapeHtml(lead.id)}">
            Edit Doc
          </button>
          <button type="button" class="direct-attach-lead-quote-btn px-2 py-1 text-slate-500 hover:text-slate-800 hover:bg-slate-200/60 rounded-lg text-xs font-medium cursor-pointer transition-colors" data-id="${escapeHtml(lead.id)}" title="Attach external quote file">
            + Attach
          </button>
        `;
      } else {
        const savedCount = quoteExports.length + quoteAttachments.length;
        quoteStatus.textContent = savedCount > 0
          ? `${savedCount} saved ${savedCount === 1 ? 'file' : 'files'} below`
          : 'Not created';
        quoteActions.innerHTML = `
          <button type="button" class="open-lead-price-offering-btn px-2.5 py-1 bg-amber-500 hover:bg-amber-600 active:scale-95 text-white rounded-lg text-xs font-semibold shadow-2xs cursor-pointer transition-all" data-id="${escapeHtml(lead.id)}">
            + Generate Doc
          </button>
          <button type="button" class="direct-attach-lead-quote-btn px-2 py-1 text-slate-500 hover:text-slate-800 hover:bg-slate-200/60 rounded-lg text-xs font-medium cursor-pointer transition-colors" data-id="${escapeHtml(lead.id)}" title="Attach file">
            + Attach
          </button>
        `;
      }
    }

    if (quoteSavedList) {
      if (!lead.priceOffering && quoteExports.length === 0 && quoteAttachments.length === 0) {
        quoteSavedList.classList.add('hidden');
        quoteSavedList.innerHTML = '';
      } else {
        quoteSavedList.classList.remove('hidden');
        let draftRowHtml = '';
        if (lead.priceOffering) {
          const poCur = lead.priceOffering.currency || leadCur;
          const poTot = parseFloat(lead.priceOffering.total) || 0;
          const poRef = lead.priceOffering.refNo || lead.priceOffering.docTitle || 'Price Quote';
          const dateLabel = formatFollowupDocTimestamp(lead.priceOffering.updatedAt || lead.createdAt);
          draftRowHtml = `
            <div class="flex items-center justify-between gap-1.5 px-2 py-1.5 bg-white rounded-lg border border-amber-200/90 text-[11px] group/qexp">
              <div class="flex items-center gap-1.5 min-w-0">
                <span class="px-1 py-0.5 rounded bg-amber-50 text-amber-700 border border-amber-200/70 text-[8px] font-bold uppercase tracking-tight leading-none shrink-0">Generator Doc</span>
                <div class="min-w-0">
                  <div class="font-semibold text-slate-800 truncate">${escapeHtml(poRef)} <span class="font-bold text-slate-900">(${formatMoney(poTot, poCur)})</span></div>
                  <div class="text-[10px] text-slate-400 truncate">${escapeHtml(dateLabel || 'Live editable document')}</div>
                </div>
              </div>
              <div class="flex items-center gap-1 shrink-0">
                <button type="button" class="view-followup-export-snapshot-btn px-1.5 py-0.5 bg-amber-50 hover:bg-amber-100 text-amber-700 rounded text-[10px] font-semibold cursor-pointer transition-colors" data-target-type="lead" data-target-id="${escapeHtml(lead.id)}" data-snapshot-id="__draft__" title="Preview live document">
                  View
                </button>
                <button type="button" class="open-lead-price-offering-btn px-1.5 py-0.5 bg-amber-500 hover:bg-amber-600 text-white rounded text-[10px] font-semibold cursor-pointer transition-colors" data-id="${escapeHtml(lead.id)}" title="Open in A4 Editor">
                  Edit
                </button>
                <button type="button" class="delete-lead-price-offering-btn p-1 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded transition-colors cursor-pointer" data-id="${escapeHtml(lead.id)}" title="Delete editable document">
                  <i data-lucide="x" class="w-3 h-3"></i>
                </button>
              </div>
            </div>
          `;
        }
        const draftFp = lead.priceOffering ? getPoContentFingerprint(lead.priceOffering) : '';
        const visibleExports = quoteExports.filter((exp, idx) => !(idx === 0 && draftFp && getPoContentFingerprint(exp.data) === draftFp));
        const exportRowsHtml = visibleExports.map(exp => {
          const expCur = exp.currency || leadCur;
          const expTot = parseFloat(exp.total) || 0;
          const verLabel = exp.label || `v${exp.version || 1} · Exported`;
          const dateLabel = formatFollowupDocTimestamp(exp.exportedAt);
          const refText = exp.refNo || exp.docTitle || 'Price Quote';
          return `
            <div class="flex items-center justify-between gap-1.5 px-2 py-1.5 bg-white rounded-lg border border-slate-200/80 text-[11px] group/qexp">
              <div class="flex items-center gap-1.5 min-w-0">
                <span class="px-1 py-0.5 rounded bg-emerald-50 text-emerald-700 border border-emerald-200/70 text-[8px] font-bold uppercase tracking-tight leading-none shrink-0">${escapeHtml(verLabel)}</span>
                <div class="min-w-0">
                  <div class="font-semibold text-slate-800 truncate">${escapeHtml(refText)} <span class="font-bold text-slate-900">(${formatMoney(expTot, expCur)})</span></div>
                  <div class="text-[10px] text-slate-400 truncate">${escapeHtml(dateLabel || 'Saved snapshot')}</div>
                </div>
              </div>
              <div class="flex items-center gap-1 shrink-0">
                <button type="button" class="view-followup-export-snapshot-btn px-1.5 py-0.5 bg-amber-50 hover:bg-amber-100 text-amber-700 rounded text-[10px] font-semibold cursor-pointer transition-colors" data-target-type="lead" data-target-id="${escapeHtml(lead.id)}" data-snapshot-id="${escapeHtml(exp.id)}" title="View read-only exported snapshot">
                  View
                </button>
                <button type="button" class="restore-followup-export-snapshot-btn px-1.5 py-0.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded text-[10px] font-semibold cursor-pointer transition-colors" data-target-type="lead" data-target-id="${escapeHtml(lead.id)}" data-snapshot-id="${escapeHtml(exp.id)}" title="Load this older version into the editor">
                  Restore
                </button>
                <button type="button" class="delete-followup-export-snapshot-btn p-1 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded transition-colors cursor-pointer" data-target-type="lead" data-target-id="${escapeHtml(lead.id)}" data-snapshot-id="${escapeHtml(exp.id)}" title="Delete version snapshot">
                  <i data-lucide="x" class="w-3 h-3"></i>
                </button>
              </div>
            </div>
          `;
        }).join('');

        const attRowsHtml = quoteAttachments.map(att => {
          const dateLabel = formatFollowupDocTimestamp(att.attachedAt);
          return `
            <div class="flex items-center justify-between gap-1.5 px-2 py-1.5 bg-white rounded-lg border border-slate-200/80 text-[11px] group/qatt">
              <div class="flex items-center gap-1.5 min-w-0">
                <span class="px-1 py-0.5 rounded bg-slate-100 text-slate-700 border border-slate-200/70 text-[8px] font-bold uppercase tracking-tight leading-none shrink-0">Attached File</span>
                <div class="min-w-0">
                  <div class="font-semibold text-slate-800 truncate">${escapeHtml(att.fileName || 'proposal.pdf')}</div>
                  ${dateLabel ? `<div class="text-[10px] text-slate-400 truncate">${escapeHtml(dateLabel)}</div>` : ''}
                </div>
              </div>
              <div class="flex items-center gap-1 shrink-0">
                <button type="button" class="view-lead-quote-btn px-1.5 py-0.5 bg-amber-50 hover:bg-amber-100 text-amber-700 rounded text-[10px] font-semibold cursor-pointer transition-colors" data-id="${escapeHtml(lead.id)}" data-att-key="${escapeHtml(att.attKey || `${lead.id}_quote`)}" data-file-name="${escapeHtml(att.fileName || 'proposal.pdf')}">
                  View
                </button>
                <button type="button" class="remove-lead-doc-btn p-1 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded transition-colors cursor-pointer" data-id="${escapeHtml(lead.id)}" data-type="quote" data-att-id="${escapeHtml(att.id || '')}" title="Remove attached document">
                  <i data-lucide="x" class="w-3 h-3"></i>
                </button>
              </div>
            </div>
          `;
        }).join('');

        quoteSavedList.innerHTML = draftRowHtml + exportRowsHtml + attRowsHtml;
      }
    }

    const briefStatus = document.getElementById('leadDetailBriefStatusText');
    const briefActions = document.getElementById('leadDetailBriefActions');
    if (briefStatus && briefActions) {
      if (lead.hasBriefDoc) {
        briefStatus.textContent = lead.briefDocName || 'brief.pdf';
        briefActions.innerHTML = `
          <button type="button" class="view-lead-brief-btn px-2.5 py-1 bg-sky-50 hover:bg-sky-100 text-sky-700 rounded-lg text-xs font-semibold cursor-pointer transition-colors" data-id="${escapeHtml(lead.id)}" data-att-key="${escapeHtml(lead.briefAttKey || `${lead.id}_brief`)}" data-file-name="${escapeHtml(lead.briefDocName || 'brief.pdf')}">
            View
          </button>
          <button type="button" class="remove-lead-doc-btn p-1 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors cursor-pointer" data-id="${escapeHtml(lead.id)}" data-type="brief" title="Remove document">
            <i data-lucide="x" class="w-3.5 h-3.5"></i>
          </button>
        `;
      } else {
        briefStatus.textContent = 'Not attached';
        briefActions.innerHTML = `
          <button type="button" class="direct-attach-lead-brief-btn px-2 py-1 text-slate-500 hover:text-slate-800 text-xs font-medium cursor-pointer" data-id="${escapeHtml(lead.id)}">
            + Attach
          </button>
        `;
      }
    }

    // Inquiry Links
    renderLeadLinks(lead);

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  // Inquiry Links Helper & Renderer
  function renderLeadLinks(lead) {
    if (!lead) return;
    const links = Array.isArray(lead.links) ? lead.links : [];
    const countEl = document.getElementById('leadDetailLinksCount');
    if (countEl) {
      countEl.textContent = `${links.length} link${links.length === 1 ? '' : 's'}`;
    }

    const container = document.getElementById('leadDetailLinksContainer');
    if (!container) return;

    if (links.length === 0) {
      container.innerHTML = `
        <div class="py-3.5 px-3 text-center text-xs text-slate-400 bg-slate-50/70 rounded-xl border border-dashed border-slate-200">
          No links added yet. Add Figma files, Drive folders, client briefs, or websites below.
        </div>
      `;
      return;
    }

    container.innerHTML = links.map(link => {
      let rawUrl = (link.url || '').trim();
      let safeHref = rawUrl;
      if (rawUrl && !rawUrl.startsWith('http://') && !rawUrl.startsWith('https://')) {
        safeHref = 'https://' + rawUrl;
      }
      let displayUrl = rawUrl.replace(/^https?:\/\//i, '').replace(/^www\./i, '');
      if (displayUrl.length > 36) {
        displayUrl = displayUrl.substring(0, 34) + '…';
      }
      const icon = getLinkIconName(rawUrl, link.title);

      return `
        <div class="flex items-center justify-between p-2.5 bg-slate-50 hover:bg-slate-100/70 rounded-xl border border-slate-200/70 hover:border-amber-300 text-xs transition-all group/link select-none" data-link-id="${escapeHtml(link.id)}">
          <a href="${escapeHtml(safeHref)}" target="_blank" rel="noopener noreferrer" class="flex items-center gap-2.5 min-w-0 flex-1 hover:opacity-85 transition-opacity" title="Open ${escapeHtml(link.title)} in new tab">
            <div class="w-7 h-7 rounded-lg bg-white border border-slate-200/80 flex items-center justify-center shrink-0 text-amber-600 group-hover/link:border-amber-300 group-hover/link:text-amber-700 transition-colors shadow-2xs">
              <i data-lucide="${icon}" class="w-3.5 h-3.5"></i>
            </div>
            <div class="min-w-0 flex-1">
              <div class="font-semibold text-slate-800 truncate flex items-center gap-1.5">
                <span>${escapeHtml(link.title || 'Untitled Link')}</span>
                <i data-lucide="external-link" class="w-2.5 h-2.5 text-slate-400 group-hover/link:text-amber-600 transition-colors shrink-0"></i>
              </div>
              <div class="text-[10px] text-slate-400 truncate font-mono">${escapeHtml(displayUrl || 'No URL')}</div>
            </div>
          </a>

          <div class="flex items-center gap-1 shrink-0 ml-2">
            <button type="button" class="edit-lead-link-btn text-slate-300 hover:text-amber-600 p-1 rounded-lg opacity-0 group-hover/link:opacity-100 transition-opacity cursor-pointer" data-link-id="${escapeHtml(link.id)}" title="Edit link">
              <i data-lucide="pencil" class="w-3.5 h-3.5"></i>
            </button>
            <button type="button" class="delete-lead-link-btn text-slate-300 hover:text-rose-600 p-1 rounded-lg opacity-0 group-hover/link:opacity-100 transition-opacity cursor-pointer" data-link-id="${escapeHtml(link.id)}" title="Delete link">
              <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
            </button>
          </div>
        </div>
      `;
    }).join('');

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function startEditingLeadLink(linkId) {
    const l = (state.budget.leads || []).find(x => x.id === state.activeFollowupLeadId);
    if (!l || !Array.isArray(l.links)) return;
    const link = l.links.find(x => x.id === linkId);
    if (!link) return;

    const row = document.querySelector(`#leadDetailLinksContainer [data-link-id="${linkId}"]`);
    if (!row) return;

    row.className = "p-2.5 bg-amber-50/60 rounded-xl border border-amber-300 text-xs w-full space-y-2";
    row.innerHTML = `
      <div class="grid grid-cols-1 sm:grid-cols-2 gap-2">
        <div>
          <label class="block text-[10px] font-semibold text-amber-800 uppercase mb-0.5">Title</label>
          <input type="text" class="link-edit-title-input w-full px-2 py-1 text-xs bg-white border border-amber-400 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500/20 text-slate-800" value="${escapeHtml(link.title)}">
        </div>
        <div>
          <label class="block text-[10px] font-semibold text-amber-800 uppercase mb-0.5">URL</label>
          <input type="text" class="link-edit-url-input w-full px-2 py-1 text-xs bg-white border border-amber-400 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500/20 text-slate-800" value="${escapeHtml(link.url)}">
        </div>
      </div>
      <div class="flex items-center justify-end gap-1.5 pt-0.5">
        <button type="button" class="cancel-lead-link-edit-btn px-2.5 py-1 text-[11px] font-semibold text-slate-600 hover:text-slate-800 bg-white border border-slate-200 rounded-lg cursor-pointer">
          Cancel
        </button>
        <button type="button" class="save-lead-link-edit-btn px-2.5 py-1 text-[11px] font-semibold text-white bg-amber-600 hover:bg-amber-700 rounded-lg cursor-pointer flex items-center gap-1">
          <i data-lucide="check" class="w-3 h-3"></i> Save
        </button>
      </div>
    `;
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    const titleInput = row.querySelector('.link-edit-title-input');
    const urlInput = row.querySelector('.link-edit-url-input');
    if (titleInput) {
      titleInput.focus();
      titleInput.select();
    }

    const saveChanges = () => {
      const newTitle = titleInput ? titleInput.value.trim() : '';
      let newUrl = urlInput ? urlInput.value.trim() : '';
      if (!newUrl) {
        showToast('Missing URL', 'Please enter a URL.', 'info');
        if (urlInput) urlInput.focus();
        return;
      }
      if (!newUrl.startsWith('http://') && !newUrl.startsWith('https://')) {
        newUrl = 'https://' + newUrl;
      }
      link.title = newTitle || link.title || 'Link';
      link.url = newUrl;
      saveBudget();
      renderLeadLinks(l);
      showToast('Link Saved', `"${link.title}" updated.`, 'success');
    };

    const cancelChanges = () => {
      renderLeadLinks(l);
    };

    const saveBtn = row.querySelector('.save-lead-link-edit-btn');
    if (saveBtn) saveBtn.addEventListener('click', saveChanges);

    const cancelBtn = row.querySelector('.cancel-lead-link-edit-btn');
    if (cancelBtn) cancelBtn.addEventListener('click', cancelChanges);

    [titleInput, urlInput].forEach(inp => {
      if (inp) {
        inp.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') { e.preventDefault(); saveChanges(); }
          else if (e.key === 'Escape') { e.preventDefault(); cancelChanges(); }
        });
      }
    });
  }

  // Sortable Drag & Drop for Lead Steps Checklist
  function initSortableLeadSteps() {
    if (typeof Sortable === 'undefined') return;
    const container = document.getElementById('leadDetailStepsContainer');
    if (!container) return;

    if (state.leadStepsSortableInstance) {
      state.leadStepsSortableInstance.destroy();
    }

    state.leadStepsSortableInstance = new Sortable(container, {
      handle: '.lead-step-drag-handle',
      animation: 150,
      ghostClass: 'bg-amber-50',
      chosenClass: 'shadow-md',
      dragClass: 'opacity-90',
      onEnd: () => {
        const lead = (state.budget.leads || []).find(x => x.id === state.activeFollowupLeadId);
        if (!lead || !Array.isArray(lead.steps)) return;
        const stepElements = Array.from(container.children);
        const newOrderedSteps = [];
        stepElements.forEach(el => {
          const stepId = el.getAttribute('data-lead-step-id');
          if (stepId) {
            const s = lead.steps.find(x => x.id === stepId);
            if (s) newOrderedSteps.push(s);
          }
        });
        lead.steps.forEach(s => {
          if (!newOrderedSteps.find(x => x.id === s.id)) newOrderedSteps.push(s);
        });
        lead.steps = newOrderedSteps;
        saveBudget();
        showToast('Steps Reordered', 'New lead step sequence saved.', 'info');
      }
    });
  }

  // Lead Step Inline Editor
  function startEditingLeadStep(stepId) {
    const lead = (state.budget.leads || []).find(x => x.id === state.activeFollowupLeadId);
    if (!lead || !Array.isArray(lead.steps)) return;
    const step = lead.steps.find(s => s.id === stepId);
    if (!step) return;

    const wrapper = document.querySelector(`.lead-step-title-wrapper[data-lead-step-id="${stepId}"]`);
    if (!wrapper) return;

    wrapper.innerHTML = `
      <div class="flex items-center gap-1.5 w-full">
        <input type="text" class="lead-step-inline-edit-input flex-1 px-2 py-0.5 text-xs font-medium text-slate-900 bg-white border border-amber-400 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500/20" value="${escapeHtml(step.title)}">
        <button type="button" class="save-lead-step-inline-btn p-1 text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50 rounded cursor-pointer" title="Save (Enter)"><i data-lucide="check" class="w-3.5 h-3.5"></i></button>
        <button type="button" class="cancel-lead-step-inline-btn p-1 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded cursor-pointer" title="Cancel (Esc)"><i data-lucide="x" class="w-3.5 h-3.5"></i></button>
      </div>
    `;
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    const input = wrapper.querySelector('.lead-step-inline-edit-input');
    if (input) {
      input.focus();
      input.select();

      const commitChange = () => {
        const newTitle = input.value.trim();
        if (newTitle && newTitle !== step.title) {
          step.title = newTitle;
          saveBudget();
          showToast('Step Updated', `"${newTitle}" saved.`, 'success');
        }
        renderLeadDetailPage(lead, state.displayCurrency);
      };

      const cancelChange = () => {
        renderLeadDetailPage(lead, state.displayCurrency);
      };

      input.addEventListener('keydown', (ev) => {
        if (ev.key === 'Enter') {
          ev.preventDefault();
          commitChange();
        } else if (ev.key === 'Escape') {
          ev.preventDefault();
          cancelChange();
        }
      });

      const saveBtn = wrapper.querySelector('.save-lead-step-inline-btn');
      if (saveBtn) saveBtn.addEventListener('click', commitChange);

      const cancelBtn = wrapper.querySelector('.cancel-lead-step-inline-btn');
      if (cancelBtn) cancelBtn.addEventListener('click', cancelChange);
    }
  }

