  // Multi-Note Inquiry Scratchpad Helpers
  function autoResizeNoteTextarea(el) {
    if (!el) return;
    el.style.height = 'auto';
    const targetHeight = Math.max(72, el.scrollHeight);
    el.style.height = targetHeight + 'px';
  }

  function getLeadNotesList(lead) {
    if (!lead) return [{ id: 'note_' + Date.now(), text: '', date: '' }];
    if (Array.isArray(lead.notesList) && lead.notesList.length > 0) {
      return lead.notesList;
    }
    // Backward compatibility from lead.notes string
    if (typeof lead.notes === 'string' && lead.notes.trim()) {
      const parts = lead.notes.split(/\n\n---\n\n/);
      lead.notesList = parts.map((txt, idx) => ({
        id: 'note_' + (Date.now() + idx),
        text: txt.trim(),
        date: idx === 0 && lead.createdAt ? new Date(lead.createdAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) : ''
      }));
      return lead.notesList;
    }
    lead.notesList = [{ id: 'note_' + Date.now(), text: '', date: '' }];
    return lead.notesList;
  }

  function renderLeadNotes(lead) {
    const container = document.getElementById('leadDetailNotesContainer');
    if (!container || !lead) return;

    const list = getLeadNotesList(lead);

    container.innerHTML = list.map((item) => {
      return `
        <div class="relative group/note" data-note-id="${escapeHtml(item.id)}">
          <textarea class="lead-note-textarea w-full p-3 text-xs bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:outline-none focus:ring-2 focus:ring-amber-500/20 focus:border-amber-500 transition-all font-sans leading-relaxed resize-none overflow-hidden block" rows="4" placeholder="Write anything about this inquiry here (client requests, scope points, email takeaways, quotes discussion)..." data-note-id="${escapeHtml(item.id)}">${escapeHtml(item.text || '')}</textarea>
          ${list.length > 1 ? `
            <button type="button" class="delete-lead-note-btn absolute top-2.5 right-2.5 p-1 text-slate-300 hover:text-rose-600 hover:bg-slate-200/70 rounded-lg transition-all opacity-0 group-hover/note:opacity-100 cursor-pointer" data-note-id="${escapeHtml(item.id)}" title="Delete note">
              <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
            </button>
          ` : ''}
        </div>
      `;
    }).join('');

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    // Auto-expand all textareas immediately so every text box displays the whole text
    container.querySelectorAll('.lead-note-textarea').forEach(ta => {
      autoResizeNoteTextarea(ta);
    });
  }

  function addLeadNoteBox() {
    const lead = (state.budget.leads || []).find(x => x.id === state.activeFollowupLeadId);
    if (!lead) return;
    const list = getLeadNotesList(lead);
    const todayStr = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
    const newNote = {
      id: 'note_' + Date.now(),
      text: '',
      date: todayStr
    };
    list.push(newNote);
    lead.notesList = list;
    saveBudget();
    renderLeadNotes(lead);

    const container = document.getElementById('leadDetailNotesContainer');
    if (container) {
      const textareas = container.querySelectorAll('.lead-note-textarea');
      const last = textareas[textareas.length - 1];
      if (last) {
        last.focus();
        last.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }
    showToast('Note Added', 'New text box added to inquiry notes.', 'info');
  }

  async function deleteLeadNoteBox(noteId) {
    const lead = (state.budget.leads || []).find(x => x.id === state.activeFollowupLeadId);
    if (!lead || !Array.isArray(lead.notesList)) return;
    const target = lead.notesList.find(n => n.id === noteId);
    if (!target) return;

    if (target.text && target.text.trim()) {
      const ok = await confirmAction('Delete this note?');
      if (!ok) return;
    }

    lead.notesList = lead.notesList.filter(n => n.id !== noteId);
    if (lead.notesList.length === 0) {
      lead.notesList = [{ id: 'note_' + Date.now(), text: '', date: '' }];
    }
    lead.notes = lead.notesList.map(n => n.text).filter(t => t && t.trim()).join('\n\n---\n\n');
    saveBudget();
    renderLeadNotes(lead);
    showToast('Note Removed', 'Note deleted.', 'info');
  }

  // Direct Document Attachment for Leads & Project Price Quotes (Quotes & Briefs)
  async function handleDirectLeadDocUpload(file, type, leadId) {
    if (!file || !leadId) return;
    const isProj = (state.budget.projects || []).some(x => x.id === leadId);
    const lead = (state.budget.leads || []).find(x => x.id === leadId)
      || (state.budget.projects || []).find(x => x.id === leadId);
    if (!lead) return;

    const isImage = file.type.startsWith('image/');
    const isPdf = file.type === 'application/pdf' || file.name.endsWith('.pdf');
    const docType = isImage ? 'image' : isPdf ? 'pdf' : 'text';

    const reader = new FileReader();
    reader.onload = async (re) => {
      const att = {
        type: docType,
        fileName: file.name,
        data: re.target.result,
        fileSize: file.size,
        mimeType: file.type
      };

      if (type === 'quote') {
        const existingList = getLeadQuoteAttachmentsList(lead).map(x => Object.assign({}, x));
        // Migrate any legacy single-key item onto its own dedicated key BEFORE updating the shared key
        for (const item of existingList) {
          if (!item.attKey || item.attKey === `${leadId}_quote` || item.attKey === `${leadId}_proforma`) {
            const migId = (item.id && item.id !== 'legacy_quote') ? item.id : ('qatt_mig_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4));
            const migKey = `${leadId}_quote_${migId}`;
            const oldData = await getReceiptAttachment(item.attKey || `${leadId}_quote`);
            if (oldData && oldData.data) {
              await saveReceiptAttachment(migKey, oldData);
            }
            item.id = migId;
            item.attKey = migKey;
          }
        }
        const attId = 'qatt_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4);
        const attKey = `${leadId}_quote_${attId}`;
        await saveReceiptAttachment(attKey, att);
        await saveReceiptAttachment(`${leadId}_quote`, att);
        existingList.unshift({
          id: attId,
          attKey,
          fileName: file.name,
          docType,
          attachedAt: new Date().toISOString()
        });
        lead.quoteAttachments = existingList;
        lead.hasQuoteDoc = true;
        lead.quoteDocName = file.name;
        if (Array.isArray(lead.steps)) {
          const s = lead.steps.find(x => x.title.toLowerCase().includes('quote') || x.title.toLowerCase().includes('proposal'));
          if (s) { s.completed = true; s.completedDate = new Date().toISOString().split('T')[0]; }
        }
        showToast('Document Attached', `${file.name} saved to Price Quote / Proposal files.`, 'success');
      } else if (type === 'brief') {
        lead.hasBriefDoc = true;
        lead.briefDocName = file.name;
        const attId = 'batt_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4);
        const attKey = `${leadId}_brief_${attId}`;
        lead.briefAttKey = attKey;
        await saveReceiptAttachment(attKey, att);
        await saveReceiptAttachment(`${leadId}_brief`, att);
        showToast('Document Attached', `${file.name} saved as Client Brief.`, 'success');
      }

      saveBudget();
      if (isProj) {
        renderProjectDetailPage(lead, state.displayCurrency);
        renderBudgetView();
      } else {
        renderLeadDetailPage(lead, state.displayCurrency);
      }
    };
    reader.readAsDataURL(file);
  }

  async function removeDirectLeadDoc(type, leadId, attId = null) {
    const isProj = (state.budget.projects || []).some(x => x.id === leadId);
    const lead = (state.budget.leads || []).find(x => x.id === leadId)
      || (state.budget.projects || []).find(x => x.id === leadId);
    if (!lead) return;
    if (!await confirmAction('Remove this attached document?')) return;

    if (type === 'quote') {
      const list = getLeadQuoteAttachmentsList(lead);
      if (attId) {
        const target = list.find(x => x.id === attId);
        if (target && target.attKey && target.attKey !== `${leadId}_quote` && target.attKey !== `${leadId}_proforma`) {
          await deleteReceiptAttachment(target.attKey);
        }
        lead.quoteAttachments = list.filter(x => x.id !== attId);
      } else {
        for (const item of list) {
          if (item.attKey) await deleteReceiptAttachment(item.attKey);
        }
        lead.quoteAttachments = [];
      }
      if (!Array.isArray(lead.quoteAttachments) || lead.quoteAttachments.length === 0) {
        lead.quoteAttachments = [];
        lead.hasQuoteDoc = !!(lead.priceOffering || (Array.isArray(lead.quoteExports) && lead.quoteExports.length > 0));
        lead.quoteDocName = lead.priceOffering ? (lead.priceOffering.docTitle || 'Price Quote / Proposal') : null;
        await deleteReceiptAttachment(`${leadId}_quote`);
      } else {
        lead.hasQuoteDoc = true;
        lead.quoteDocName = lead.quoteAttachments[0].fileName || 'proposal.pdf';
        const topAtt = lead.quoteAttachments[0];
        if (topAtt && topAtt.attKey) {
          const topData = await getReceiptAttachment(topAtt.attKey);
          if (topData && topData.data) {
            await saveReceiptAttachment(`${leadId}_quote`, topData);
          }
        }
      }
      showToast('Document Removed', 'Attached quote file removed.', 'info');
    } else if (type === 'brief') {
      lead.hasBriefDoc = false;
      lead.briefDocName = null;
      if (lead.briefAttKey) {
        await deleteReceiptAttachment(lead.briefAttKey);
        delete lead.briefAttKey;
      }
      await deleteReceiptAttachment(`${leadId}_brief`);
      showToast('Document Removed', 'Client brief deleted.', 'info');
    }

    saveBudget();
    if (isProj) {
      renderProjectDetailPage(lead, state.displayCurrency);
      renderBudgetView();
    } else {
      renderLeadDetailPage(lead, state.displayCurrency);
    }
  }

