  const DEPOSIT_PROFORMA_DEFAULT_CONDITIONS_CONTENT = '• This deposit proforma invoice covers the initial 50% project retainer / deposit.\n• Project commencement begins upon receipt of deposit payment.\n• The remaining 50% milestone will be invoiced upon project completion and final deliverables sign-off.';

  function sanitizePoTemplateData(tpl) {
    if (!tpl || typeof tpl !== 'object') return tpl;
    if (tpl.docSubtitle === 'Print & Merch Design Bundle') {
      tpl.docSubtitle = '';
    }
    if (tpl.labels && typeof tpl.labels === 'object') {
      Object.keys(DEFAULT_PO_TEMPLATE.labels).forEach(k => {
        if (tpl.labels[k] === '' || tpl.labels[k] === undefined || tpl.labels[k] === null) {
          tpl.labels[k] = DEFAULT_PO_TEMPLATE.labels[k];
        }
      });
    }
    if (!tpl.elementStyles || typeof tpl.elementStyles !== 'object') {
      tpl.elementStyles = {};
    }
    if (tpl.richText && typeof tpl.richText === 'object') {
      Object.keys(tpl.richText).forEach(rk => {
        const html = tpl.richText[rk];
        if (html && typeof html === 'string') {
          const faceMatch = html.match(/face=["']([^"']+)["']/i);
          if (faceMatch && faceMatch[1]) {
            if (!tpl.elementStyles[rk]) tpl.elementStyles[rk] = {};
            if (!tpl.elementStyles[rk].fontFamily) tpl.elementStyles[rk].fontFamily = faceMatch[1];
          }
        }
        if (/^(item_(desc|qty|rate|amount)_[1-9]\d*|client_name|client_email|client_address|project_title|ref_no|issue_date_val|valid_until_val|subtotal_val|discount_val|tax_val|total_val)$/.test(rk)) {
          delete tpl.richText[rk];
        } else if (rk === 'item_desc_0' && typeof html === 'string') {
          tpl.richText[rk] = poWrapTextWithRichStyle(html, '', true);
          if (!tpl.richText[rk]) delete tpl.richText[rk];
        }
      });
    }
    if (Array.isArray(tpl.sections)) {
      tpl.sections = tpl.sections.filter(s => !(s && s.type === 'text' && s.title === '*' && (!s.content || !String(s.content).replace(/<[^>]*>/g, '').trim())));
      const ovIdx = tpl.sections.findIndex(s => s && s.type === 'overview');
      if (ovIdx !== -1 && (!tpl.sections[ovIdx + 1] || tpl.sections[ovIdx + 1].type !== 'divider')) {
        tpl.sections.splice(ovIdx + 1, 0, { id: 'sec_div_overview', type: 'divider', title: 'Divider Line', content: '' });
      }
      const secIds = new Set(tpl.sections.map(s => s && s.id).filter(Boolean));
      Object.keys(tpl.elementStyles).forEach(ek => {
        if ((ek.startsWith('sec_sec_') || ek.startsWith('title_sec_') || ek.startsWith('content_sec_')) && ek !== 'sec_sec_deliverables' && ek !== 'totals_sec_deliverables') {
          const secId = ek.replace(/^(sec|title|content)_/, '');
          if (!secIds.has(secId)) {
            delete tpl.elementStyles[ek];
          }
        }
      });
    }
    return tpl;
  }

  function buildProformaSectionsFromTemplate(tplSections, existingSections, entity, isDeposit = false) {
    const prevSecs = Array.isArray(existingSections) ? existingSections : [];
    const existingScope = prevSecs.find(s => s && (s.type === 'scope' || (s.type === 'custom' && (s.title || '').toLowerCase() === 'summary')));
    const existingTerms = prevSecs.find(s => s && s.type === 'terms');
    const existingCond = prevSecs.find(s => s && s.type === 'conditions');
    const fallbackScopeText = existingScope?.content || (entity?.notes ? String(entity.notes).split('\n\n---\n\n')[0] : (entity?.title || ''));

    let out = Array.isArray(tplSections) && tplSections.length > 0
      ? JSON.parse(JSON.stringify(tplSections))
      : [];

    // Filter out quote-only sections (acceptance, empty timeline, accidental '*' block)
    out = out.filter(s => {
      if (!s) return false;
      if (s.type === 'acceptance') return false;
      if (s.type === 'text' && s.title === '*' && (!s.content || !String(s.content).replace(/<[^>]*>/g, '').trim())) return false;
      if (s.type === 'timeline' && (!s.content || !String(s.content).replace(/<[^>]*>/g, '').trim())) return false;
      return true;
    });

    // Ensure divider after overview
    const ovIdx = out.findIndex(s => s && s.type === 'overview');
    if (ovIdx !== -1 && (!out[ovIdx + 1] || out[ovIdx + 1].type !== 'divider')) {
      out.splice(ovIdx + 1, 0, { id: 'sec_div_overview', type: 'divider', title: 'Divider Line', content: '' });
    }

    // Preserve scope/summary text if template's scope/summary is empty
    const tplScope = out.find(s => s && (s.type === 'scope' || (s.type === 'custom' && (s.title || '').toLowerCase() === 'summary')));
    if (tplScope && (!tplScope.content || !String(tplScope.content).replace(/<[^>]*>/g, '').trim()) && fallbackScopeText) {
      tplScope.content = fallbackScopeText;
    }

    // Ensure Payment Terms & Bank Details section exists
    let tplTerms = out.find(s => s && s.type === 'terms');
    if (tplTerms) {
      tplTerms.title = 'Payment Terms & Bank Details';
      tplTerms.content = existingTerms?.content || getProformaDefaultTerms();
    } else {
      const delivIdx = out.findIndex(s => s && s.type === 'deliverables');
      const termsBlock = {
        id: existingTerms?.id || ('sec_terms_' + Date.now()),
        type: 'terms',
        title: 'Payment Terms & Bank Details',
        pageBreakBefore: false,
        content: existingTerms?.content || getProformaDefaultTerms()
      };
      if (delivIdx !== -1) out.splice(delivIdx + 1, 0, termsBlock);
      else out.push(termsBlock);
    }

    // Ensure Notice & Invoicing Notes / Deposit Notes section exists
    const defaultConditions = isDeposit ? DEPOSIT_PROFORMA_DEFAULT_CONDITIONS_CONTENT : PROFORMA_DEFAULT_CONDITIONS_CONTENT;
    const condTitle = isDeposit ? 'Deposit Notes & Terms' : 'Notice & Invoicing Notes';
    let tplCond = out.find(s => s && s.type === 'conditions');
    if (tplCond) {
      tplCond.title = condTitle;
      tplCond.content = existingCond?.content || defaultConditions;
    } else {
      out.push({
        id: existingCond?.id || ('sec_conditions_' + Date.now()),
        type: 'conditions',
        title: condTitle,
        pageBreakBefore: false,
        content: existingCond?.content || defaultConditions
      });
    }

    return out;
  }

  function getMasterPoTemplate() {
    let localTpl = null;
    try {
      localTpl = JSON.parse(localStorage.getItem('ft_po_default_template') || 'null');
    } catch (e) {}
    const vaultTpl = (state.budget && state.budget.poDefaultTemplate) ? state.budget.poDefaultTemplate : null;
    const customTpl = sanitizePoTemplateData(JSON.parse(JSON.stringify(vaultTpl || localTpl || {})));
    return {
      id: customTpl.id || 'tpl_price_quote_master',
      docType: 'price_quote',
      name: customTpl.name || 'Price Quote / Proposal Template',
      docTitle: 'Price Quote / Proposal',
      docSubtitle: customTpl.docSubtitle !== undefined ? customTpl.docSubtitle : DEFAULT_PO_TEMPLATE.docSubtitle,
      sender: Object.assign({}, DEFAULT_PO_TEMPLATE.sender, customTpl.sender || {}),
      typography: Object.assign({}, DEFAULT_PO_TEMPLATE.typography, customTpl.typography || {}),
      elementStyles: Object.assign({}, JSON.parse(JSON.stringify(DEFAULT_PO_TEMPLATE.elementStyles)), JSON.parse(JSON.stringify(customTpl.elementStyles || {}))),
      labels: Object.assign({}, DEFAULT_PO_TEMPLATE.labels, customTpl.labels || {}),
      sections: Array.isArray(customTpl.sections) ? JSON.parse(JSON.stringify(customTpl.sections)) : null,
      richText: customTpl.richText ? JSON.parse(JSON.stringify(customTpl.richText)) : {}
    };
  }

