  let activePoTemplateId = null;

  function getAllPoSavedTemplates() {
    let list = (state.budget && Array.isArray(state.budget.poSavedTemplates)) ? state.budget.poSavedTemplates : null;
    if (!list || list.length === 0) {
      try {
        const fromLocal = JSON.parse(localStorage.getItem('ft_po_saved_templates') || 'null');
        if (Array.isArray(fromLocal) && fromLocal.length > 0) list = fromLocal;
      } catch (e) {}
    }
    if (!list || list.length === 0) {
      const masterQuote = getMasterPoTemplate();
      list = [
        Object.assign({}, masterQuote, {
          id: 'tpl_price_quote_master',
          docType: 'price_quote',
          name: 'Price Quote / Proposal Template',
          docTitle: 'Price Quote / Proposal',
          isDefault: true,
          createdAt: new Date().toISOString()
        }),
        getMasterDepositProformaTemplate(),
        getMasterProformaTemplate()
      ];
    }

    // Ensure all items have a valid docType
    list.forEach(t => {
      sanitizePoTemplateData(t);
      if (!t.docType) {
        if (t.docTitle && t.docTitle.includes('DEPOSIT')) t.docType = 'deposit_proforma';
        else if (t.docTitle && t.docTitle.includes('PROFORMA')) t.docType = 'proforma';
        else t.docType = 'price_quote';
      }
    });

    // Ensure dedicated default template exists for deposit_proforma and proforma
    if (!list.some(t => t.docType === 'deposit_proforma')) {
      list.push(getMasterDepositProformaTemplate());
    }
    if (!list.some(t => t.docType === 'proforma')) {
      list.push(getMasterProformaTemplate());
    }
    if (!list.some(t => t.docType === 'price_quote')) {
      const mq = getMasterPoTemplate();
      list.unshift(Object.assign({}, mq, {
        id: 'tpl_price_quote_master',
        docType: 'price_quote',
        name: 'Price Quote Template',
        isDefault: true
      }));
    }

    if (state.budget) state.budget.poSavedTemplates = list;
    return list;
  }

  function getPoSavedTemplates(filterDocType = null) {
    if (!filterDocType) filterDocType = getActiveDocType();
    const all = getAllPoSavedTemplates();
    return all.filter(t => t.docType === filterDocType);
  }

  function savePoSavedTemplates(list, docType = null) {
    if (!docType) docType = getActiveDocType();
    const all = getAllPoSavedTemplates();
    const others = all.filter(t => t.docType !== docType);
    const combined = [...others, ...list];
    if (state.budget) {
      state.budget.poSavedTemplates = combined;
    }
    try {
      localStorage.setItem('ft_po_saved_templates', JSON.stringify(combined));
    } catch (e) {}
    saveBudget();
  }

  function flushLivePoDomToState() {
    const container = document.getElementById('priceOfferingPrintArea');
    if (!container) return;
    container.querySelectorAll('.po-field').forEach(el => {
      poRememberRichText(el);
    });
    container.querySelectorAll('#poItemsTableBody .po-item-desc').forEach(inp => {
      const idx = parseInt(inp.getAttribute('data-index'), 10);
      if (!isNaN(idx) && currentPoItems[idx]) {
        currentPoItems[idx].description = inp.value;
      }
    });
    container.querySelectorAll('#poItemsTableBody tr').forEach((row, idx) => {
      if (!currentPoItems[idx]) return;
      const qtyInput = row.querySelector('.po-item-qty');
      const rateInput = row.querySelector('.po-item-rate');
      if (qtyInput) currentPoItems[idx].qty = parseFloat(qtyInput.value) || 0;
      if (rateInput) currentPoItems[idx].rate = parseFloat(rateInput.value) || 0;
      currentPoItems[idx].amount = (currentPoItems[idx].qty || 0) * (currentPoItems[idx].rate || 0);
    });
    container.querySelectorAll('.po-section-title-input').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.title = inp.value;
    });
    container.querySelectorAll('.po-section-content').forEach(ta => {
      const secId = ta.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.content = poCleanContentHtml(ta);
    });
    container.querySelectorAll('.po-client-sign-title').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.clientTitle = inp.value;
    });
    container.querySelectorAll('.po-provider-sign-title').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.providerTitle = inp.value;
    });
    container.querySelectorAll('.po-sign-seal-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.signSealText = inp.value;
    });
    container.querySelectorAll('.po-sign-date-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.signDateText = inp.value;
    });
    container.querySelectorAll('.po-sign-name-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.signNameText = inp.value;
    });
    container.querySelectorAll('.po-sign-seal-provider-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.signSealProviderText = inp.value;
    });
    container.querySelectorAll('.po-sign-date-provider-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.signDateProviderText = inp.value;
    });
    container.querySelectorAll('.po-sign-name-provider-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.signNameProviderText = inp.value;
    });
  }

  function captureCurrentPoTemplateSnapshot(customName) {
    flushLivePoDomToState();
    const curDocType = getActiveDocType();
    const existingList = getPoSavedTemplates(curDocType);
    const fallbackName = curDocType === 'deposit_proforma'
      ? `Deposit Proforma Template ${existingList.length + 1}`
      : (curDocType === 'proforma' ? `Proforma Template ${existingList.length + 1}` : `Price Quote Template ${existingList.length + 1}`);
    const name = (customName && String(customName).trim()) ? String(customName).trim() : fallbackName;
    const target = getPoEditorTarget();

    let snapDocTitle = 'Price Quote / Proposal';
    let snapDocSubtitle = document.getElementById('poDocSubtitle')?.value || '';
    if (curDocType === 'deposit_proforma') {
      snapDocTitle = 'DEPOSIT PROFORMA INVOICE';
      if (!snapDocSubtitle) snapDocSubtitle = 'PRELIMINARY DEPOSIT / ADVANCE PAYMENT REQUEST';
    } else if (curDocType === 'proforma') {
      snapDocTitle = 'PROFORMA INVOICE';
      if (!snapDocSubtitle) snapDocSubtitle = 'OFFICIAL PROFORMA INVOICE / FINAL PAYMENT REQUEST';
    } else if (curDocType === 'studio') {
      snapDocTitle = document.getElementById('poDocHeading')?.value || '';
    } else {
      snapDocTitle = 'Price Quote / Proposal';
    }

    if (customName !== '__backup__') {
      if (target && target.title && snapDocSubtitle.trim() === String(target.title).trim()) {
        snapDocSubtitle = '';
      }
    }

    const snap = {
      id: 'tpl_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
      docType: curDocType,
      name,
      isDefault: false,
      createdAt: new Date().toISOString(),
      typography: Object.assign({}, activePoTypography),
      elementStyles: JSON.parse(JSON.stringify(poElementStyles || {})),
      richText: JSON.parse(JSON.stringify(poRichText || {})),
      labels: readPoLabels(),
      docTitle: snapDocTitle,
      docSubtitle: snapDocSubtitle,
      sender: {
        name: document.getElementById('poSenderName')?.value || '',
        title: document.getElementById('poSenderTitle')?.value || '',
        contact: document.getElementById('poSenderContact')?.value || '',
        location: document.getElementById('poSenderLocation')?.value || ''
      },
      sections: JSON.parse(JSON.stringify(currentPoSections || []))
    };
    return customName === '__backup__' ? snap : sanitizePoTemplateData(snap);
  }

  let poOpenTemplateMenuId = null;
  let poEditingTemplateNameId = null;
  let poEditingTemplateDesignId = null;
  let poTemplateDesignEditBackup = null;
  let poHoverPreviewBackup = null;
  let poPreviewingTemplateId = null;
  let poDraggingTemplateId = null;

  function resolveActiveStudioDoc(fallbackId) {
    const docs = state.documents || [];
    const poPage = document.getElementById('priceOfferingDocPage');
    const isPoPageOpen = !poPage || !poPage.classList || !poPage.classList.contains('hidden');
    let candId = state.activeStudioDocId || '';
    if (!candId) {
      const rawHash = window.location.hash || '';
      const m = rawHash.match(/studio:([^/&?#]+)/);
      if (m && m[1]) candId = decodeURIComponent(m[1]);
    }
    if (!candId && fallbackId && docs.some(d => d.id === fallbackId)) {
      candId = fallbackId;
    }
    if (!candId && isPoPageOpen && state.activePriceOfferingLeadId && docs.some(d => d.id === state.activePriceOfferingLeadId)) {
      candId = state.activePriceOfferingLeadId;
    }
    if (!candId && isPoPageOpen) {
      const footerEl = document.getElementById('poStudioDocFooterSection');
      const bcClient = document.getElementById('priceOfferingDocClientBreadcrumb')?.textContent?.trim();
      if (footerEl && !footerEl.classList.contains('hidden') && bcClient) {
        const byTitle = docs.find(d => d.kind === 'studio_pdf' && (d.title || '').trim() === bcClient);
        if (byTitle) candId = byTitle.id;
      }
    }
    if (!candId) return null;
    const doc = docs.find(d => d.id === candId) || null;
    if (doc && isPoPageOpen) {
      state.activeStudioDocId = doc.id;
    }
    return doc;
  }

  function getPoEditorTarget(leadId) {
    const studioDoc = resolveActiveStudioDoc(leadId);
    if (studioDoc) {
      if (!studioDoc.studioData) studioDoc.studioData = { _studioDoc: true, _structuralMigrated: true };
      return {
        id: studioDoc.id,
        _isStudioDoc: true,
        _docRef: studioDoc,
        client: studioDoc.subtitle || 'Studio Document',
        title: studioDoc.title || 'Untitled Document',
        amount: 0,
        currency: state.displayCurrency || 'EUR',
        get priceOffering() {
          return studioDoc.studioData;
        },
        set priceOffering(val) {
          if (val && typeof val === 'object') val._studioDoc = true;
          studioDoc.studioData = val;
        }
      };
    }

    const curDocType = getActiveDocType();

    // 1. DEPOSIT PROFORMA (50% Milestone) Target
    if (curDocType === 'deposit_proforma' || state.activeDepositProformaProjectId) {
      const depProjId = state.activeDepositProformaProjectId || (leadId && (state.budget?.projects || []).some(p => p.id === leadId) ? leadId : state.activeFollowupProjectId);
      const proj = (state.budget?.projects || []).find(p => p.id === depProjId);
      if (proj) {
        return {
          id: proj.id,
          _isDepositProforma: true,
          _isProforma: false,
          _projectRef: proj,
          client: proj.client || 'Client',
          title: proj.title || proj.description || 'Project Scope',
          amount: (parseFloat(proj.amount !== undefined ? proj.amount : proj.fee) || 0) * 0.5,
          currency: proj.currency || state.displayCurrency || 'EUR',
          dueDate: proj.dueDate || '',
          notes: proj.notes || '',
          get priceOffering() {
            return proj.depositProforma;
          },
          set priceOffering(val) {
            if (val && typeof val === 'object') {
              val._isDepositProforma = true;
              val._isProforma = false;
            }
            proj.depositProforma = val;
          }
        };
      }
    }

    // 2. PROFORMA INVOICE Target
    if (curDocType === 'proforma' || state.activeProformaProjectId) {
      const profProjId = state.activeProformaProjectId || (leadId && (state.budget?.projects || []).some(p => p.id === leadId) ? leadId : state.activeFollowupProjectId);
      const proj = (state.budget?.projects || []).find(p => p.id === profProjId);
      if (proj) {
        return {
          id: proj.id,
          _isProforma: true,
          _isDepositProforma: false,
          _projectRef: proj,
          client: proj.client || 'Client',
          title: proj.title || proj.description || 'Project Scope',
          amount: parseFloat(proj.amount !== undefined ? proj.amount : proj.fee) || 0,
          currency: proj.currency || state.displayCurrency || 'EUR',
          dueDate: proj.dueDate || '',
          notes: proj.notes || '',
          get priceOffering() {
            return proj.proformaInvoice;
          },
          set priceOffering(val) {
            if (val && typeof val === 'object') {
              val._isProforma = true;
              val._isDepositProforma = false;
            }
            proj.proformaInvoice = val;
          }
        };
      }
    }

    // 3. PRICE QUOTE / PROPOSAL Target (Leads or Projects)
    const targetLeadId = state.activePriceOfferingLeadId || leadId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const isProj = (state.budget?.projects || []).some(p => p.id === targetLeadId);
    if (isProj) {
      const proj = (state.budget?.projects || []).find(p => p.id === targetLeadId);
      if (proj) {
        return {
          id: proj.id,
          _isProforma: false,
          _isDepositProforma: false,
          _projectRef: proj,
          client: proj.client || 'Client',
          title: proj.title || proj.description || 'Project Scope',
          amount: parseFloat(proj.amount !== undefined ? proj.amount : proj.fee) || 0,
          currency: proj.currency || state.displayCurrency || 'EUR',
          dueDate: proj.dueDate || '',
          notes: proj.notes || '',
          get priceOffering() {
            return proj.priceOffering;
          },
          set priceOffering(val) {
            if (val && typeof val === 'object') {
              val._isProforma = false;
              val._isDepositProforma = false;
            }
            proj.priceOffering = val;
          }
        };
      }
    }

    const leadObj = (state.budget?.leads || []).find(l => l.id === targetLeadId);
    return leadObj || null;
  }

  function reorderPoSavedTemplates(draggedId, targetId, placeAfter) {
    if (!draggedId || !targetId || draggedId === targetId) return;
    const list = getPoSavedTemplates();
    const fromIdx = list.findIndex(t => t.id === draggedId);
    const toIdx = list.findIndex(t => t.id === targetId);
    if (fromIdx < 0 || toIdx < 0 || fromIdx === toIdx) return;
    const [moved] = list.splice(fromIdx, 1);
    const newTargetIdx = list.findIndex(t => t.id === targetId);
    const insertIdx = placeAfter ? newTargetIdx + 1 : newTargetIdx;
    list.splice(insertIdx, 0, moved);
    savePoSavedTemplates(list);
    renderPoSavedTemplatesGallery();
  }

  function previewPoTemplateOnHover(tplId) {
    if (poEditingTemplateNameId || poEditingTemplateDesignId || poDraggingTemplateId) return;
    const curDocType = getActiveDocType();
    const list = getPoSavedTemplates(curDocType);
    let tpl = list.find(t => t.id === tplId);
    if (!tpl) {
      const allList = (state.budget && Array.isArray(state.budget.poSavedTemplates)) ? state.budget.poSavedTemplates : [];
      tpl = allList.find(t => t.id === tplId);
    }
    if (!tpl) return;

    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    if (!lead) return;

    if (!poHoverPreviewBackup) {
      const snap = captureCurrentPoTemplateSnapshot('__backup__');
      poHoverPreviewBackup = {
        activePoTemplateId,
        typography: JSON.parse(JSON.stringify(activePoTypography || DEFAULT_PO_TEMPLATE.typography)),
        elementStyles: JSON.parse(JSON.stringify(poElementStyles || {})),
        richText: JSON.parse(JSON.stringify(poRichText || {})),
        sections: JSON.parse(JSON.stringify(snap.sections || currentPoSections || [])),
        items: JSON.parse(JSON.stringify(currentPoItems || [])),
        signatures: JSON.parse(JSON.stringify(currentPoSignatures || [])),
        docTitle: snap.docTitle,
        docSubtitle: snap.docSubtitle,
        sender: JSON.parse(JSON.stringify(snap.sender || {})),
        labels: JSON.parse(JSON.stringify(snap.labels || {})),
        leadPriceOffering: (lead && lead.priceOffering) ? JSON.parse(JSON.stringify(lead.priceOffering)) : null
      };
    }

    if (poPreviewingTemplateId === tplId) return;
    poPreviewingTemplateId = tplId;

    const grid = document.getElementById('poSavedTemplatesGrid');
    if (grid) {
      grid.querySelectorAll('.po-template-btn-row').forEach(row => {
        row.classList.toggle('po-template-previewing', row.getAttribute('data-tpl-id') === tplId);
      });
    }
    const countLabel = document.getElementById('poSavedTemplatesCountLabel');
    if (countLabel) {
      countLabel.textContent = `Preview: ${tpl.name}`;
    }

    poElementStyles = JSON.parse(JSON.stringify(tpl.elementStyles || {}));
    poRichText = JSON.parse(JSON.stringify(tpl.richText || {}));

    if (Array.isArray(tpl.sections) && tpl.sections.length > 0) {
      if (curDocType === 'deposit_proforma' || curDocType === 'proforma') {
        currentPoSections = buildProformaSectionsFromTemplate(tpl.sections, poHoverPreviewBackup.sections || currentPoSections, lead, curDocType === 'deposit_proforma');
      } else {
        const prevSecs = poHoverPreviewBackup.sections || currentPoSections || [];
        let tplSecs = JSON.parse(JSON.stringify(tpl.sections));
        tplSecs.forEach(s => {
          if (!s) return;
          const prevMatch = prevSecs.find(ps => ps && (ps.id === s.id || (ps.type === s.type && s.type !== 'custom' && s.type !== 'text') || ((ps.title || '').toLowerCase() === (s.title || '').toLowerCase() && s.title)));
          if (prevMatch && prevMatch.content && (!s.content || !String(s.content).replace(/<[^>]*>/g, '').trim())) {
            s.content = prevMatch.content;
          }
        });
        currentPoSections = tplSecs;
      }
    }

    const previewTypo = Object.assign({}, DEFAULT_PO_TEMPLATE.typography, tpl.typography || {});
    // Locked docTitle & docSubtitle: NEVER change docTitle on hover!
    const previewDocTitle = poHoverPreviewBackup.docTitle;
    const previewDocSubtitle = poHoverPreviewBackup.docSubtitle;
    const previewLabels = curDocType === 'deposit_proforma'
      ? Object.assign({}, DEFAULT_PO_TEMPLATE.labels, tpl.labels || {}, DEPOSIT_PROFORMA_DEFAULT_LABELS)
      : (curDocType === 'proforma'
          ? Object.assign({}, DEFAULT_PO_TEMPLATE.labels, tpl.labels || {}, PROFORMA_DEFAULT_LABELS)
          : (tpl.labels ? Object.assign({}, DEFAULT_PO_TEMPLATE.labels, tpl.labels) : poHoverPreviewBackup.labels));

    const previewPo = Object.assign({}, poHoverPreviewBackup.leadPriceOffering || {}, {
      templateId: tpl.id,
      typography: previewTypo,
      elementStyles: JSON.parse(JSON.stringify(poElementStyles)),
      richText: JSON.parse(JSON.stringify(poRichText)),
      sender: tpl.sender ? Object.assign({}, tpl.sender) : poHoverPreviewBackup.sender,
      labels: previewLabels,
      docTitle: previewDocTitle,
      docSubtitle: previewDocSubtitle,
      sections: JSON.parse(JSON.stringify(currentPoSections || [])),
      items: JSON.parse(JSON.stringify(poHoverPreviewBackup.items || currentPoItems || [])),
      signatures: JSON.parse(JSON.stringify(poHoverPreviewBackup.signatures || currentPoSignatures || []))
    });

    applyPriceOfferingTypography(previewTypo, false);
    const printArea = document.getElementById('priceOfferingPrintArea');
    if (printArea) printArea.innerHTML = '';
    renderPriceOfferingDocument(lead, previewPo);
  }

  function restorePoTemplateHoverPreview() {
    if (!poHoverPreviewBackup) return;
    const backup = poHoverPreviewBackup;
    poHoverPreviewBackup = null;
    poPreviewingTemplateId = null;

    activePoTemplateId = backup.activePoTemplateId;
    poElementStyles = JSON.parse(JSON.stringify(backup.elementStyles || {}));
    poRichText = JSON.parse(JSON.stringify(backup.richText || {}));
    currentPoSections = JSON.parse(JSON.stringify(backup.sections || []));
    if (Array.isArray(backup.items)) {
      currentPoItems = JSON.parse(JSON.stringify(backup.items));
    }
    if (Array.isArray(backup.signatures)) {
      currentPoSignatures = JSON.parse(JSON.stringify(backup.signatures));
    }

    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    if (lead) {
      lead.priceOffering = Object.assign({}, backup.leadPriceOffering ? JSON.parse(JSON.stringify(backup.leadPriceOffering)) : {}, {
        typography: JSON.parse(JSON.stringify(backup.typography)),
        elementStyles: JSON.parse(JSON.stringify(backup.elementStyles)),
        richText: JSON.parse(JSON.stringify(backup.richText)),
        sections: JSON.parse(JSON.stringify(backup.sections)),
        items: JSON.parse(JSON.stringify(currentPoItems || [])),
        signatures: JSON.parse(JSON.stringify(currentPoSignatures || [])),
        docTitle: backup.docTitle,
        docSubtitle: backup.docSubtitle,
        sender: JSON.parse(JSON.stringify(backup.sender)),
        labels: JSON.parse(JSON.stringify(backup.labels))
      });
    }

    const grid = document.getElementById('poSavedTemplatesGrid');
    if (grid) {
      grid.querySelectorAll('.po-template-btn-row').forEach(row => {
        row.classList.remove('po-template-previewing');
      });
    }
    const countLabel = document.getElementById('poSavedTemplatesCountLabel');
    if (countLabel) {
      countLabel.textContent = 'Hover to preview';
    }

    applyPriceOfferingTypography(backup.typography, false);
    const printArea = document.getElementById('priceOfferingPrintArea');
    if (printArea) printArea.innerHTML = '';
    renderPriceOfferingDocument(lead, lead?.priceOffering);
  }

  function applyPoTemplateToCurrentDoc(tplId, showNotification = true) {
    restorePoTemplateHoverPreview();
    flushLivePoDomToState();
    const curDocType = getActiveDocType();
    const list = getPoSavedTemplates(curDocType);
    let tpl = list.find(t => t.id === tplId);
    if (!tpl) {
      const allList = (state.budget && Array.isArray(state.budget.poSavedTemplates)) ? state.budget.poSavedTemplates : [];
      tpl = allList.find(t => t.id === tplId);
    }
    if (!tpl) return;

    pushPoUndoSnapshot();
    activePoTemplateId = tpl.id;
    poElementStyles = JSON.parse(JSON.stringify(tpl.elementStyles || {}));
    poRichText = JSON.parse(JSON.stringify(tpl.richText || {}));

    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    if (lead) {
      if (!lead.priceOffering) lead.priceOffering = {};
      lead.priceOffering.templateId = tpl.id;
      lead.priceOffering.typography = Object.assign({}, DEFAULT_PO_TEMPLATE.typography, tpl.typography || {});
      lead.priceOffering.elementStyles = JSON.parse(JSON.stringify(poElementStyles));
      lead.priceOffering.richText = JSON.parse(JSON.stringify(poRichText));
      if (tpl.sender) lead.priceOffering.sender = Object.assign({}, tpl.sender);

      // NEVER CHANGE DOCUMENT TYPE OR TITLES ACROSS DIFFERENT DOCS!
      if (curDocType === 'deposit_proforma') {
        lead.priceOffering._isDepositProforma = true;
        lead.priceOffering._isProforma = false;
        lead.priceOffering.docTitle = 'DEPOSIT PROFORMA INVOICE';
        lead.priceOffering.docSubtitle = tpl.docSubtitle || 'PRELIMINARY DEPOSIT / ADVANCE PAYMENT REQUEST';
        lead.priceOffering.labels = Object.assign({}, DEFAULT_PO_TEMPLATE.labels, tpl.labels || {}, DEPOSIT_PROFORMA_DEFAULT_LABELS);
      } else if (curDocType === 'proforma') {
        lead.priceOffering._isProforma = true;
        lead.priceOffering._isDepositProforma = false;
        lead.priceOffering.docTitle = 'PROFORMA INVOICE';
        lead.priceOffering.docSubtitle = tpl.docSubtitle || 'OFFICIAL PROFORMA INVOICE / FINAL PAYMENT REQUEST';
        lead.priceOffering.labels = Object.assign({}, DEFAULT_PO_TEMPLATE.labels, tpl.labels || {}, PROFORMA_DEFAULT_LABELS);
      } else if (curDocType === 'price_quote') {
        lead.priceOffering._isProforma = false;
        lead.priceOffering._isDepositProforma = false;
        lead.priceOffering.docTitle = 'Price Quote / Proposal';
        lead.priceOffering.docSubtitle = tpl.docSubtitle || '';
        lead.priceOffering.labels = Object.assign({}, DEFAULT_PO_TEMPLATE.labels, tpl.labels || {});
      }

      if (Array.isArray(tpl.sections) && tpl.sections.length > 0) {
        let tplSecs;
        if (curDocType === 'deposit_proforma' || curDocType === 'proforma') {
          tplSecs = buildProformaSectionsFromTemplate(tpl.sections, currentPoSections, lead, curDocType === 'deposit_proforma');
        } else {
          const prevSecs = currentPoSections || [];
          tplSecs = JSON.parse(JSON.stringify(tpl.sections));
          tplSecs.forEach(s => {
            if (!s) return;
            const prevMatch = prevSecs.find(ps => ps && (ps.id === s.id || (ps.type === s.type && s.type !== 'custom' && s.type !== 'text') || ((ps.title || '').toLowerCase() === (s.title || '').toLowerCase() && s.title)));
            if (prevMatch && prevMatch.content && (!s.content || !String(s.content).replace(/<[^>]*>/g, '').trim())) {
              s.content = prevMatch.content;
            }
          });
        }
        currentPoSections = tplSecs;
        lead.priceOffering.sections = JSON.parse(JSON.stringify(tplSecs));
      }
    }

    applyPriceOfferingTypography(Object.assign({}, DEFAULT_PO_TEMPLATE.typography, tpl.typography || {}), false);

    // Clear DOM inputs so renderPriceOfferingDocument uses the correct values
    const printArea = document.getElementById('priceOfferingPrintArea');
    if (printArea) printArea.innerHTML = '';

    renderPriceOfferingDocument(lead, lead?.priceOffering);
    savePriceOfferingDoc(false);
    renderPoSavedTemplatesGallery();

    if (showNotification) {
      showToast(`Applied "${tpl.name}" ✓`, 'Document updated to the selected template.', 'success');
    }
  }

  function setPoDefaultTemplateAcrossSite(tplId) {
    restorePoTemplateHoverPreview();
    const list = getPoSavedTemplates();
    const tpl = list.find(t => t.id === tplId);
    if (!tpl) return;

    list.forEach(t => { t.isDefault = (t.id === tpl.id); });
    savePoSavedTemplates(list);

    try {
      localStorage.setItem('ft_po_default_template', JSON.stringify(tpl));
    } catch (e) {}

    if (state.budget) {
      state.budget.poDefaultTemplate = JSON.parse(JSON.stringify(tpl));
      saveBudget();
    }

    renderPoSavedTemplatesGallery();
    showToast(`Default Template Set ★`, `"${tpl.name}" is now the default template for new quote & proposal documents.`, 'success');
  }

  function isCurrentDocModifiedFromTemplate(tpl) {
    if (!tpl) return false;
    try {
      const isProforma = !!(state.activeProformaProjectId || (getPoEditorTarget() && getPoEditorTarget()._isProforma));
      const curTypo = Object.assign({}, DEFAULT_PO_TEMPLATE.typography, activePoTypography || {});
      const tplTypo = Object.assign({}, DEFAULT_PO_TEMPLATE.typography, tpl.typography || {});
      const typoKeys = ['fontFamily', 'fontSize', 'lineHeight', 'sectionGap', 'titleGap', 'titleSize', 'sheetPadding', 'showPageNumbers'];
      for (const k of typoKeys) {
        if (String(curTypo[k] ?? '') !== String(tplTypo[k] ?? '')) return true;
      }

      const normalizeStylesMap = (stylesObj, refTplStyles) => {
        const out = {};
        const src = stylesObj || {};
        Object.keys(src).sort().forEach(k => {
          // Ignore deliverable rows > 0 if they didn't exist in the template and simply inherited row 0's typography
          if (/^item_(desc|qty|rate|amount)_([1-9]\d*)$/.test(k) && !(refTplStyles && refTplStyles[k])) {
            return;
          }
          if (isProforma && k.includes('acceptance')) return;
          const st = src[k];
          if (!st || typeof st !== 'object') return;
          const clean = {};
          Object.keys(st).sort().forEach(prop => {
            const v = st[prop];
            if (v === undefined || v === null || v === '' || v === 'inherit') return;
            if ((prop === 'offsetX' || prop === 'offsetY' || prop === 'marginTop' || prop === 'marginBottom') && (parseFloat(v) || 0) === 0) return;
            clean[prop] = String(v);
          });
          if (Object.keys(clean).length > 0) out[k] = clean;
        });
        return JSON.stringify(out);
      };
      if (normalizeStylesMap(poElementStyles, tpl.elementStyles) !== normalizeStylesMap(tpl.elementStyles, tpl.elementStyles)) return true;

      const normalizeRichMap = (obj, refTplRich) => {
        const out = {};
        Object.keys(obj || {}).sort().forEach(k => {
          if (/^item_(desc|qty|rate|amount)_([1-9]\d*)$/.test(k) && !(refTplRich && refTplRich[k])) {
            return;
          }
          if (isProforma && k.includes('acceptance')) return;
          const skeleton = String(obj[k] || '').replace(/<br\s*\/?>/gi, '').replace(/>[^<]*</g, '><').trim();
          if (skeleton) out[k] = skeleton;
        });
        return JSON.stringify(out);
      };
      if (normalizeRichMap(poRichText, tpl.richText) !== normalizeRichMap(tpl.richText, tpl.richText)) return true;

      const curHeadingEl = document.getElementById('poDocHeading');
      if (!isProforma && curHeadingEl && tpl.docTitle && curHeadingEl.value !== tpl.docTitle) return true;

      let refSecs = Array.isArray(tpl.sections) ? tpl.sections : [];
      let docSecs = Array.isArray(currentPoSections) ? currentPoSections : [];
      if (isProforma) {
        refSecs = refSecs.filter(s => s && s.type !== 'acceptance');
        docSecs = docSecs.filter(s => s && s.type !== 'acceptance');
      }

      if (refSecs.length > 0 && docSecs.length > 0) {
        if (refSecs.length !== docSecs.length) return true;
        for (let i = 0; i < refSecs.length; i++) {
          const a = refSecs[i];
          const b = docSecs[i];
          if (!a || !b || a.type !== b.type) return true;
          if (String(a.title || '') !== String(b.title || '')) {
            if (!isProforma) return true;
          }
          if (JSON.stringify(a.hiddenElements || []) !== JSON.stringify(b.hiddenElements || [])) return true;
          if (JSON.stringify(a.metaCellsOrder || []) !== JSON.stringify(b.metaCellsOrder || [])) return true;
        }
      } else if (docSecs.length > 0) {
        for (const s of docSecs) {
          if (Array.isArray(s.hiddenElements) && s.hiddenElements.length > 0) return true;
          if (Array.isArray(s.metaCellsOrder) && s.metaCellsOrder.length > 0) return true;
        }
      }
      return false;
    } catch (e) {
      return false;
    }
  }

  function setPoSaveDrawerMode(mode) {
    const newTab = document.getElementById('poSaveModeNewTab');
    const ovrTab = document.getElementById('poSaveModeOverrideTab');
    const newPane = document.getElementById('poSaveTemplateNewPane');
    const ovrPane = document.getElementById('poSaveTemplateOverridePane');
    const ovrSelect = document.getElementById('poOverrideTemplateSelect');

    const list = getPoSavedTemplates();
    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    const currentTplId = activePoTemplateId || lead?.priceOffering?.templateId || (list.find(t => t.isDefault) || list[0])?.id;

    if (ovrSelect) {
      const prevVal = ovrSelect.value;
      ovrSelect.innerHTML = list.map(t => `<option value="${escapeHtml(t.id)}">${escapeHtml(t.name)}${t.isDefault ? ' (Default)' : ''}</option>`).join('');
      if (prevVal && list.some(t => t.id === prevVal)) {
        ovrSelect.value = prevVal;
      } else if (currentTplId && list.some(t => t.id === currentTplId)) {
        ovrSelect.value = currentTplId;
      }
    }

    const isOverride = mode === 'override' && list.length > 0;
    if (newTab && ovrTab) {
      if (isOverride) {
        ovrTab.className = 'po-save-mode-tab py-1 px-2 rounded-md text-[10px] font-bold bg-white text-slate-900 shadow-2xs cursor-pointer transition-all';
        newTab.className = 'po-save-mode-tab py-1 px-2 rounded-md text-[10px] font-semibold text-slate-600 hover:text-slate-900 cursor-pointer transition-all';
      } else {
        newTab.className = 'po-save-mode-tab py-1 px-2 rounded-md text-[10px] font-bold bg-white text-slate-900 shadow-2xs cursor-pointer transition-all';
        ovrTab.className = 'po-save-mode-tab py-1 px-2 rounded-md text-[10px] font-semibold text-slate-600 hover:text-slate-900 cursor-pointer transition-all';
      }
    }
    if (newPane) newPane.classList.toggle('hidden', isOverride);
    if (ovrPane) ovrPane.classList.toggle('hidden', !isOverride);
  }

  async function updatePoSavedTemplateWithCurrentDoc(tplId, customName, askConfirm = false) {
    restorePoTemplateHoverPreview();
    const list = getPoSavedTemplates();
    const idx = list.findIndex(t => t.id === tplId);
    if (idx === -1) return false;

    const existing = list[idx];
    const finalName = (customName && String(customName).trim()) ? String(customName).trim() : existing.name;

    if (askConfirm) {
      const confirmed = await confirmAction({
        title: `Save & Override "${finalName}"?`,
        message: `Your current page layout, typography, and styling will replace the "${finalName}" template.`,
        confirmText: `Override "${finalName}"`,
        cancelText: 'Cancel',
        type: 'primary'
      });
      if (!confirmed) return false;
    }

    const snap = captureCurrentPoTemplateSnapshot(finalName);
    snap.id = existing.id;
    snap.name = finalName;
    snap.isDefault = !!existing.isDefault;

    const curDocType = getActiveDocType();
    snap.docType = existing.docType || curDocType;
    if (snap.docType === 'deposit_proforma') {
      snap.docTitle = 'DEPOSIT PROFORMA INVOICE';
      snap.labels = Object.assign({}, DEFAULT_PO_TEMPLATE.labels, snap.labels || {}, DEPOSIT_PROFORMA_DEFAULT_LABELS);
    } else if (snap.docType === 'proforma') {
      snap.docTitle = 'PROFORMA INVOICE';
      snap.labels = Object.assign({}, DEFAULT_PO_TEMPLATE.labels, snap.labels || {}, PROFORMA_DEFAULT_LABELS);
    } else if (snap.docType === 'price_quote') {
      snap.docTitle = 'Price Quote / Proposal';
    }

    list[idx] = snap;
    activePoTemplateId = snap.id;
    poOpenTemplateMenuId = null;
    poEditingTemplateNameId = null;
    poEditingTemplateDesignId = null;
    poTemplateDesignEditBackup = null;
    savePoSavedTemplates(list);

    if (snap.isDefault) {
      setPoDefaultTemplateAcrossSite(snap.id);
    } else {
      savePriceOfferingDoc(false);
      renderPoSavedTemplatesGallery();
      syncPoStatusBadgeRestingState();
      showToast(`Overrode "${snap.name}" ✓`, 'Updated template with your current page changes.', 'success');
    }
    return true;
  }

  function startEditingPoTemplateDesign(tplId) {
    restorePoTemplateHoverPreview();
    const list = getPoSavedTemplates();
    const tpl = list.find(t => t.id === tplId);
    if (!tpl) return;

    if (poEditingTemplateDesignId === tplId) {
      commitEditingPoTemplateDesign(tplId);
      return;
    }

    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    const currentTplId = activePoTemplateId || lead?.priceOffering?.templateId || (list.find(t => t.isDefault) || list[0])?.id;

    poTemplateDesignEditBackup = {
      tplId: tpl.id,
      originalTpl: JSON.parse(JSON.stringify(tpl)),
      prevActiveTemplateId: activePoTemplateId,
      leadDocSnap: getPoDocumentSnapshot()
    };
    poEditingTemplateDesignId = tpl.id;
    poEditingTemplateNameId = null;
    poOpenTemplateMenuId = null;

    // Only replace the page if the user clicked Edit on a DIFFERENT template than the one currently on screen
    if (tpl.id !== currentTplId) {
      applyPoTemplateToCurrentDoc(tpl.id, false);
    } else {
      activePoTemplateId = tpl.id;
    }
    renderPoSavedTemplatesGallery();
    syncPoStatusBadgeRestingState();
    showToast(`Editing Template: "${tpl.name}" ✎`, 'Tweak the page and click Save & Override when ready.', 'info');
  }

  async function commitEditingPoTemplateDesign(tplId) {
    const targetId = tplId || poEditingTemplateDesignId;
    if (!targetId) {
      poEditingTemplateDesignId = null;
      poTemplateDesignEditBackup = null;
      renderPoSavedTemplatesGallery();
      syncPoStatusBadgeRestingState();
      return;
    }
    await updatePoSavedTemplateWithCurrentDoc(targetId, undefined, true);
  }

  function cancelEditingPoTemplateDesign() {
    const backup = poTemplateDesignEditBackup;
    poEditingTemplateDesignId = null;
    poTemplateDesignEditBackup = null;

    if (backup && backup.leadDocSnap) {
      activePoTemplateId = backup.prevActiveTemplateId || backup.tplId;
      applyPoDocumentSnapshot(backup.leadDocSnap);
      savePriceOfferingDoc(false);
    }
    renderPoSavedTemplatesGallery();
    syncPoStatusBadgeRestingState();
    showToast('Template Edit Cancelled · Document Only', 'Template was not modified.', 'info');
  }

  function renamePoSavedTemplate(tplId, newName) {
    restorePoTemplateHoverPreview();
    const trimmed = String(newName || '').trim();
    poEditingTemplateNameId = null;
    if (!trimmed) {
      renderPoSavedTemplatesGallery();
      return;
    }
    const list = getPoSavedTemplates();
    const tpl = list.find(t => t.id === tplId);
    if (!tpl) {
      renderPoSavedTemplatesGallery();
      return;
    }
    if (tpl.name === trimmed) {
      renderPoSavedTemplatesGallery();
      return;
    }
    tpl.name = trimmed;
    if (poTemplateDesignEditBackup && poTemplateDesignEditBackup.tplId === tplId && poTemplateDesignEditBackup.originalTpl) {
      poTemplateDesignEditBackup.originalTpl.name = trimmed;
    }
    if (tpl.isDefault && state.budget?.poDefaultTemplate) {
      state.budget.poDefaultTemplate.name = trimmed;
      try { localStorage.setItem('ft_po_default_template', JSON.stringify(tpl)); } catch (e) {}
    }
    savePoSavedTemplates(list);
    renderPoSavedTemplatesGallery();
    showToast(`Renamed to "${trimmed}" ✓`, 'Template name updated.', 'success');
  }

  async function deletePoSavedTemplate(tplId) {
    restorePoTemplateHoverPreview();
    let list = getPoSavedTemplates();
    const target = list.find(t => t.id === tplId);
    if (!target) return;

    if (list.length <= 1) {
      showToast('Cannot Delete Template', 'You must keep at least one saved template in your gallery.', 'warning');
      return;
    }

    const confirmed = await confirmAction({
      title: `Delete template "${target.name}"?`,
      message: 'Are you sure you want to delete this template? This action cannot be undone.',
      confirmText: 'Delete',
      cancelText: 'Cancel',
      type: 'danger'
    });
    if (!confirmed) return;

    list = getPoSavedTemplates().filter(t => t.id !== tplId);
    poOpenTemplateMenuId = null;
    poEditingTemplateNameId = null;
    if (poEditingTemplateDesignId === tplId) {
      poEditingTemplateDesignId = null;
      poTemplateDesignEditBackup = null;
    }
    if (target.isDefault && list.length > 0) {
      list[0].isDefault = true;
      if (state.budget) state.budget.poDefaultTemplate = JSON.parse(JSON.stringify(list[0]));
      try { localStorage.setItem('ft_po_default_template', JSON.stringify(list[0])); } catch (e) {}
    }
    if (activePoTemplateId === tplId) {
      activePoTemplateId = list[0]?.id || null;
    }
    savePoSavedTemplates(list);
    renderPoSavedTemplatesGallery();
    syncPoStatusBadgeRestingState();
    showToast('Template Deleted ✓', `Deleted "${target.name}".`, 'success');
  }

  function updatePoTemplateScopeBanner() {
    const scopeBanner = document.getElementById('poTemplateScopeBanner');
    if (!scopeBanner) return;

    const list = getPoSavedTemplates();
    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    const currentTplId = activePoTemplateId || lead?.priceOffering?.templateId || (list.find(t => t.isDefault) || list[0])?.id;
    const currentTpl = list.find(t => t.id === currentTplId);

    if (poEditingTemplateDesignId) {
      const editingTpl = list.find(t => t.id === poEditingTemplateDesignId);
      const tplName = editingTpl ? editingTpl.name : 'Template';
      scopeBanner.className = 'bg-slate-900 text-white border border-slate-900 rounded-xl p-2.5 space-y-2 transition-all shadow-xs';
      scopeBanner.innerHTML = `
        <div class="flex items-center justify-between gap-1.5">
          <div class="flex items-center gap-1.5 min-w-0">
            <span class="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse shrink-0"></span>
            <span class="text-[11px] font-bold text-white truncate">Editing Template: &ldquo;${escapeHtml(tplName)}&rdquo;</span>
          </div>
        </div>
        <p class="text-[10px] text-slate-300 leading-snug">Tweak the page, then click Save &amp; Override to update this template.</p>
        <div class="flex items-center gap-1.5 pt-0.5">
          <button type="button" class="po-commit-template-edit-btn flex-1 py-1 px-2 rounded-lg bg-white hover:bg-slate-100 text-slate-900 text-[10px] font-bold flex items-center justify-center gap-1 cursor-pointer transition-colors" data-tpl-id="${escapeHtml(poEditingTemplateDesignId)}">
            <span>Save &amp; Override</span>
          </button>
          <button type="button" class="po-cancel-template-edit-btn py-1 px-2.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-200 text-[10px] font-semibold cursor-pointer transition-colors" data-tpl-id="${escapeHtml(poEditingTemplateDesignId)}">
            <span>Cancel</span>
          </button>
        </div>
      `;
      return;
    }

    const isDocTweaked = currentTpl ? isCurrentDocModifiedFromTemplate(currentTpl) : false;
    scopeBanner.className = 'bg-slate-50 border border-slate-200/80 rounded-xl px-2.5 py-2 transition-all';
    if (isDocTweaked && currentTpl) {
      scopeBanner.innerHTML = `
        <div class="flex items-center justify-between gap-1.5">
          <div class="flex items-center gap-1.5 min-w-0">
            <span class="w-1.5 h-1.5 rounded-full bg-amber-500 shrink-0"></span>
            <span class="text-[11px] font-semibold text-slate-800 truncate">Working on: This Document Only</span>
          </div>
          <span class="text-[9px] font-bold uppercase tracking-wide px-1.5 py-0.5 rounded bg-amber-100/90 text-amber-800 shrink-0">Tweaked</span>
        </div>
        <p class="text-[10px] text-slate-500 mt-0.5 leading-snug">You tweaked this quote &mdash; &ldquo;${escapeHtml(currentTpl.name)}&rdquo; is untouched.</p>
      `;
    } else {
      scopeBanner.innerHTML = `
        <div class="flex items-center justify-between gap-1.5">
          <div class="flex items-center gap-1.5 min-w-0">
            <span class="w-1.5 h-1.5 rounded-full bg-emerald-500 shrink-0"></span>
            <span class="text-[11px] font-semibold text-slate-700 truncate">Working on: This Document Only</span>
          </div>
        </div>
        <p class="text-[10px] text-slate-500 mt-0.5 leading-snug">Page tweaks stay on this quote &mdash; saved templates are untouched.</p>
      `;
    }
  }

  function renderPoSavedTemplatesGallery() {
    const grid = document.getElementById('poSavedTemplatesGrid');
    const countLabel = document.getElementById('poSavedTemplatesCountLabel');
    updatePoTemplateScopeBanner();
    if (!grid) return;

    const list = getPoSavedTemplates();
    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    const currentTplId = activePoTemplateId || lead?.priceOffering?.templateId || (list.find(t => t.isDefault) || list[0])?.id;

    const ovrSelect = document.getElementById('poOverrideTemplateSelect');
    if (ovrSelect) {
      const prevVal = ovrSelect.value;
      ovrSelect.innerHTML = list.map(t => `<option value="${escapeHtml(t.id)}">${escapeHtml(t.name)}${t.isDefault ? ' (Default)' : ''}</option>`).join('');
      if (prevVal && list.some(t => t.id === prevVal)) {
        ovrSelect.value = prevVal;
      } else if (currentTplId && list.some(t => t.id === currentTplId)) {
        ovrSelect.value = currentTplId;
      }
    }

    if (countLabel) {
      if (poEditingTemplateDesignId) {
        const editingTpl = list.find(t => t.id === poEditingTemplateDesignId);
        countLabel.textContent = editingTpl ? `Editing: ${editingTpl.name}` : 'Editing template';
      } else {
        countLabel.textContent = 'Hover to preview';
      }
    }

    if (list.length === 0) {
      grid.innerHTML = `<div class="py-3 px-2 text-center text-[11px] text-slate-400 bg-slate-50/70 rounded-xl border border-dashed border-slate-200">No saved templates yet. Click &ldquo;Save Template&rdquo; above.</div>`;
      return;
    }

    grid.innerHTML = list.map((tpl) => {
      const isActive = tpl.id === currentTplId;
      const isDef = !!tpl.isDefault;
      const isRenaming = poEditingTemplateNameId === tpl.id;
      const isEditingDesign = poEditingTemplateDesignId === tpl.id;
      const isDocTweaked = isActive && !isEditingDesign ? isCurrentDocModifiedFromTemplate(tpl) : false;

      if (isRenaming) {
        return `
          <div class="po-template-btn-row flex items-center justify-between gap-1.5 px-2 py-1 po-template-active" data-tpl-id="${escapeHtml(tpl.id)}">
            <input type="text" class="po-tpl-rename-input flex-1 min-w-0 text-xs font-semibold text-slate-900 bg-white border border-slate-300 rounded-md px-2 py-1 outline-none focus:border-slate-900" data-tpl-id="${escapeHtml(tpl.id)}" value="${escapeHtml(tpl.name)}" placeholder="Template name...">
            <div class="flex items-center gap-0.5 shrink-0">
              <button type="button" class="po-save-rename-template-btn w-6 h-6 rounded-lg bg-slate-900 hover:bg-slate-800 text-white flex items-center justify-center cursor-pointer shrink-0" data-tpl-id="${escapeHtml(tpl.id)}" title="Save name (Enter)">
                <i data-lucide="check" class="w-3.5 h-3.5"></i>
              </button>
              <button type="button" class="po-cancel-rename-template-btn w-6 h-6 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-slate-200/60 flex items-center justify-center cursor-pointer shrink-0" data-tpl-id="${escapeHtml(tpl.id)}" title="Cancel (Esc)">
                <i data-lucide="x" class="w-3.5 h-3.5"></i>
              </button>
            </div>
          </div>
        `;
      }

      if (isEditingDesign) {
        return `
          <div class="po-template-btn-row group/tpl flex items-center justify-between gap-1.5 px-2.5 py-1.5 po-template-active po-template-editing" data-tpl-id="${escapeHtml(tpl.id)}">
            <div class="flex items-center gap-2 min-w-0 flex-1 py-0.5">
              <span class="w-1.5 h-1.5 rounded-full shrink-0 bg-emerald-500 animate-pulse"></span>
              <span class="po-tpl-name-label font-semibold text-xs text-slate-900 truncate cursor-pointer hover:underline decoration-slate-400 underline-offset-2" data-tpl-id="${escapeHtml(tpl.id)}" title="Double-click to rename">${escapeHtml(tpl.name)}</span>
            </div>
            <div class="flex items-center gap-1 shrink-0">
              <button type="button" class="po-commit-template-edit-btn px-2 h-6 rounded-lg bg-slate-900 hover:bg-slate-800 text-white text-[10px] font-semibold flex items-center gap-1 cursor-pointer transition-colors" data-tpl-id="${escapeHtml(tpl.id)}" title="Save & override this template with current page">
                <i data-lucide="check" class="w-3 h-3"></i>
                <span>Save</span>
              </button>
              <button type="button" class="po-cancel-template-edit-btn w-6 h-6 rounded-lg flex items-center justify-center text-slate-400 hover:text-slate-700 hover:bg-slate-200/70 transition-colors cursor-pointer" data-tpl-id="${escapeHtml(tpl.id)}" title="Cancel editing and revert">
                <i data-lucide="x" class="w-3.5 h-3.5"></i>
              </button>
            </div>
          </div>
        `;
      }

      const statusBadgeHtml = isActive
        ? (isDocTweaked
            ? `<span class="text-[9px] font-semibold px-1.5 py-0.5 rounded bg-amber-100/80 text-amber-800 shrink-0" title="You tweaked this document — the saved template is untouched">Tweaked</span>`
            : `<span class="text-[9px] font-semibold px-1.5 py-0.5 rounded bg-slate-200/70 text-slate-600 shrink-0" title="Applied to this document">Applied</span>`)
        : '';

      return `
        <div class="po-template-btn-row group/tpl flex items-center justify-between gap-1.5 px-2 py-1.5 ${isActive ? 'po-template-base' : ''}" draggable="true" data-tpl-id="${escapeHtml(tpl.id)}">
          <!-- Clickable Template Button Area (Drag to reorder, Hover to preview on page, Click to apply, Double-click name to rename) -->
          <div class="po-apply-template-btn flex items-center gap-1.5 min-w-0 flex-1 py-0.5 cursor-pointer" data-tpl-id="${escapeHtml(tpl.id)}" title="Drag to reorder • Hover to preview • Click to apply">
            <span class="po-tpl-drag-grip text-slate-300 group-hover/tpl:text-slate-400 cursor-grab active:cursor-grabbing shrink-0 flex items-center -ml-0.5" title="Drag to rearrange">
              <i data-lucide="grip-vertical" class="w-3.5 h-3.5"></i>
            </span>
            <span class="w-1.5 h-1.5 rounded-full shrink-0 ${isActive ? (isDocTweaked ? 'bg-amber-500' : 'bg-slate-700') : 'bg-slate-300 group-hover/tpl:bg-slate-400'}"></span>
            <span class="po-tpl-name-label font-semibold text-xs ${isActive ? 'text-slate-900' : 'text-slate-700 group-hover/tpl:text-slate-900'} truncate cursor-pointer hover:underline decoration-slate-400 underline-offset-2" data-tpl-id="${escapeHtml(tpl.id)}" title="Click to apply • Double-click to rename">${escapeHtml(tpl.name)}</span>
            ${statusBadgeHtml}
          </div>

          <!-- Inline Icon Buttons: Make Default, Edit Template, Delete -->
          <div class="flex items-center gap-0.5 shrink-0">
            <button type="button" class="po-set-default-template-btn w-6 h-6 rounded-lg flex items-center justify-center transition-colors cursor-pointer ${isDef ? 'text-amber-500 bg-amber-50/90 hover:bg-amber-100/80' : 'text-slate-400 hover:text-amber-500 hover:bg-slate-100'}" data-tpl-id="${escapeHtml(tpl.id)}" title="${isDef ? 'Default template across all leads' : 'Make default template'}">
              <i data-lucide="star" class="w-3.5 h-3.5 ${isDef ? 'fill-amber-400' : ''}"></i>
            </button>
            <button type="button" class="po-edit-template-btn w-6 h-6 rounded-lg flex items-center justify-center text-slate-400 hover:text-slate-800 hover:bg-slate-100 transition-colors cursor-pointer" data-tpl-id="${escapeHtml(tpl.id)}" title="Edit & override this template">
              <i data-lucide="pencil" class="w-3.5 h-3.5"></i>
            </button>
            ${list.length > 1 ? `
              <button type="button" class="po-delete-template-btn w-6 h-6 rounded-lg flex items-center justify-center text-slate-400 hover:text-rose-600 hover:bg-rose-50 transition-colors cursor-pointer" data-tpl-id="${escapeHtml(tpl.id)}" title="Delete template">
                <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
              </button>
            ` : ''}
          </div>
        </div>
      `;
    }).join('');

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    if (poEditingTemplateNameId) {
      const inp = grid.querySelector(`.po-tpl-rename-input[data-tpl-id="${poEditingTemplateNameId}"]`);
      if (inp) {
        setTimeout(() => {
          inp.focus();
          inp.select();
        }, 0);
      }
    }
  }

  let activePoTypography = Object.assign({}, DEFAULT_PO_TEMPLATE.typography);

  // Point (pt) <-> CSS Pixel (px) conversion (1pt = 4/3 px at 96dpi)
  function poPxToPt(px) {
    const n = parseFloat(px);
    if (!n || isNaN(n)) return 10;
    return Math.round(n * 0.75 * 2) / 2;
  }
  function poPtToPx(pt) {
    const n = parseFloat(pt);
    if (!n || isNaN(n)) return 13;
    return Math.round((n * (4 / 3)) * 100) / 100;
  }

  function getPoCurrency() {
    const curInp = document.getElementById('poCurrencyInput') || document.getElementById('poCurrencySelect');
    if (!curInp) return state.displayCurrency || 'EUR';
    const raw = curInp.value.trim().toUpperCase();
    if (raw.includes('EUR') || raw.includes('€')) return 'EUR';
    if (raw.includes('USD') || raw.includes('$')) return 'USD';
    if (raw.includes('ILS') || raw.includes('₪')) return 'ILS';
    return raw.slice(0, 4).trim() || 'EUR';
  }

  function applyPriceOfferingTypography(typo, save = false, propagateToElements = false) {
    if (!typo) return;
    activePoTypography = Object.assign({}, activePoTypography, typo);

    const root = document.documentElement;
    if (activePoTypography.fontFamily) {
      root.style.setProperty('--po-font-family', activePoTypography.fontFamily);
    }
    if (activePoTypography.fontSize) {
      root.style.setProperty('--po-font-size', activePoTypography.fontSize + 'px');
    }
    if (activePoTypography.lineHeight) {
      root.style.setProperty('--po-line-height', String(activePoTypography.lineHeight));
    }
    if (activePoTypography.sectionGap) {
      root.style.setProperty('--po-section-gap', activePoTypography.sectionGap + 'px');
    }
    if (activePoTypography.titleGap) {
      root.style.setProperty('--po-title-gap', activePoTypography.titleGap + 'px');
    }
    if (activePoTypography.titleSize) {
      root.style.setProperty('--po-title-size', activePoTypography.titleSize + 'px');
    }
    if (activePoTypography.sheetPadding) {
      root.style.setProperty('--po-sheet-padding', activePoTypography.sheetPadding);
    }

    if (propagateToElements && poElementStyles && typeof poElementStyles === 'object') {
      if (typo.fontFamily) {
        Object.keys(poElementStyles).forEach(k => {
          if (poElementStyles[k] && poElementStyles[k].fontFamily !== undefined) {
            poElementStyles[k].fontFamily = activePoTypography.fontFamily;
          }
        });
      }
      if (typo.fontSize !== undefined && Array.isArray(currentPoSections)) {
        currentPoSections.forEach(s => {
          if (!s || !s.id) return;
          const ck = 'content_' + s.id;
          if (poElementStyles[ck] && poElementStyles[ck].fontSize !== undefined) {
            poElementStyles[ck].fontSize = activePoTypography.fontSize;
          }
        });
      }
      if (typo.titleSize !== undefined && Array.isArray(currentPoSections)) {
        currentPoSections.forEach(s => {
          if (!s || !s.id) return;
          const tk = 'title_' + s.id;
          if (poElementStyles[tk] && poElementStyles[tk].fontSize !== undefined) {
            poElementStyles[tk].fontSize = activePoTypography.titleSize;
          }
        });
      }
      if (typo.lineHeight !== undefined && Array.isArray(currentPoSections)) {
        currentPoSections.forEach(s => {
          if (!s || !s.id) return;
          const ck = 'content_' + s.id;
          if (poElementStyles[ck] && poElementStyles[ck].lineHeight !== undefined) {
            poElementStyles[ck].lineHeight = String(activePoTypography.lineHeight);
          }
        });
      }
      applySavedElementStyles();
    }

    const fontSelect = document.getElementById('poFontFamilySelect');
    if (fontSelect && fontSelect.value !== activePoTypography.fontFamily) {
      fontSelect.value = activePoTypography.fontFamily;
    }

    const sGap = document.getElementById('poDocSectionGapPtInput');
    if (sGap && document.activeElement !== sGap) sGap.value = poPxToPt(activePoTypography.sectionGap);

    const lHeight = document.getElementById('poDocLineHeightInput');
    if (lHeight && document.activeElement !== lHeight) lHeight.value = activePoTypography.lineHeight;

    const fSize = document.getElementById('poDocBodySizePtInput');
    if (fSize && document.activeElement !== fSize) fSize.value = poPxToPt(activePoTypography.fontSize);

    const tSize = document.getElementById('poDocTitleSizePtInput');
    if (tSize && document.activeElement !== tSize) tSize.value = poPxToPt(activePoTypography.titleSize);

    const pageNumToggle = document.getElementById('poShowPageNumbersToggle');
    if (pageNumToggle) {
      pageNumToggle.checked = activePoTypography.showPageNumbers !== false;
    }
    const sheetEl = document.getElementById('priceOfferingSheet');
    if (sheetEl) {
      sheetEl.classList.toggle('po-hide-page-numbers', activePoTypography.showPageNumbers === false);
    }

    document.querySelectorAll('.po-margin-preset-btn').forEach(btn => {
      const pad = btn.getAttribute('data-padding');
      if (pad === activePoTypography.sheetPadding) {
        btn.className = 'po-margin-preset-btn px-2 py-1 text-[11px] font-medium rounded-lg border border-slate-900 bg-slate-900 text-white cursor-pointer text-center';
      } else {
        btn.className = 'po-margin-preset-btn px-2 py-1 text-[11px] font-medium rounded-lg border border-slate-200 text-slate-700 hover:bg-slate-50 cursor-pointer text-center';
      }
    });

    const marginLabel = document.getElementById('poMarginMmLabel');
    if (marginLabel) {
      const parts = String(activePoTypography.sheetPadding || '36px 40px').trim().split(/\s+/);
      const vPx = parseFloat(parts[0]) || 36;
      const hPx = parseFloat(parts[1] || parts[0]) || 40;
      const vMm = (vPx * 25.4 / 96).toFixed(1);
      const hMm = (hPx * 25.4 / 96).toFixed(1);
      marginLabel.textContent = `${vMm} × ${hMm} mm`;
    }

    autoResizePoTextareas();
    updatePoRightSidebarInspector();
    if (propagateToElements || typo.sectionGap !== undefined || typo.sheetPadding !== undefined) {
      updatePoVisualPageBreakGuides();
    }

    if (save) {
      triggerPriceOfferingAutoSave(true);
    }
  }

  // ==========================================
  // UNDO & REDO SNAPSHOT ENGINE
  // ==========================================
  function getPoDocumentSnapshot() {
    flushLivePoDomToState();
    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    return {
      docHeading: document.getElementById('poDocHeading')?.value || '',
      docSubtitle: document.getElementById('poDocSubtitle')?.value || '',
      senderName: document.getElementById('poSenderName')?.value || '',
      senderTitle: document.getElementById('poSenderTitle')?.value || '',
      senderContact: document.getElementById('poSenderContact')?.value || '',
      senderLocation: document.getElementById('poSenderLocation')?.value || '',
      clientName: document.getElementById('poClientName')?.value || '',
      clientEmail: document.getElementById('poClientEmail')?.value || '',
      clientAddress: document.getElementById('poClientAddress')?.value || '',
      refNo: document.getElementById('poRefNo')?.value || '',
      currency: getPoCurrency(),
      issueDate: document.getElementById('poIssueDate')?.value || '',
      validUntil: document.getElementById('poValidUntil')?.value || '',
      projectTitle: document.getElementById('poProjectTitle')?.value || '',
      labels: JSON.parse(JSON.stringify(readPoLabels(lead?.priceOffering?.labels) || {})),
      sections: JSON.parse(JSON.stringify(currentPoSections || [])),
      items: JSON.parse(JSON.stringify(currentPoItems || [])),
      signatures: JSON.parse(JSON.stringify(currentPoSignatures || [])),
      discountPercent: document.getElementById('poDiscountPercentInput')?.value || '0',
      taxPercent: document.getElementById('poTaxPercentInput')?.value || '0',
      elementStyles: JSON.parse(JSON.stringify(poElementStyles || {})),
      richText: JSON.parse(JSON.stringify(poRichText || {})),
      typography: JSON.parse(JSON.stringify(activePoTypography || {})),
      selectedElementId: poSelectedElementId,
      selectedSectionIndex: selectedPoSectionIndex
    };
  }

  function pushPoUndoSnapshot() {
    if (poIsApplyingUndoRedo) return;
    const snap = getPoDocumentSnapshot();
    if (poUndoStack.length > 0) {
      const last = poUndoStack[poUndoStack.length - 1];
      if (JSON.stringify(last) === JSON.stringify(snap)) return;
    }
    poUndoStack.push(snap);
    if (poUndoStack.length > PO_MAX_HISTORY) {
      poUndoStack.shift();
    }
    poRedoStack = [];
    updatePoUndoRedoUI();
  }

  function updatePoUndoRedoUI() {
    const undoBtn = document.getElementById('poUndoBtn');
    const redoBtn = document.getElementById('poRedoBtn');
    if (undoBtn) {
      const canUndo = poUndoStack.length > 1;
      undoBtn.disabled = !canUndo;
      undoBtn.classList.toggle('opacity-40', !canUndo);
      undoBtn.classList.toggle('pointer-events-none', !canUndo);
    }
    if (redoBtn) {
      const canRedo = poRedoStack.length > 0;
      redoBtn.disabled = !canRedo;
      redoBtn.classList.toggle('opacity-40', !canRedo);
      redoBtn.classList.toggle('pointer-events-none', !canRedo);
    }
  }

  function schedulePoInputSnapshot() {
    if (poIsApplyingUndoRedo) return;
    if (poInputSnapshotTimer) clearTimeout(poInputSnapshotTimer);
    poInputSnapshotTimer = setTimeout(() => {
      pushPoUndoSnapshot();
    }, 600);
  }

  function applyPoDocumentSnapshot(snap) {
    if (!snap) return;
    poIsApplyingUndoRedo = true;
    try {
      const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
      const lead = getPoEditorTarget(leadId);
      const isDepositProforma = !!(lead?._isDepositProforma || state.activeDepositProformaProjectId);
      const isProforma = !isDepositProforma && !!(lead?._isProforma || state.activeProformaProjectId);

      currentPoSections = JSON.parse(JSON.stringify(snap.sections || []));
      currentPoItems = JSON.parse(JSON.stringify(snap.items || []));
      currentPoSignatures = JSON.parse(JSON.stringify(snap.signatures || []));
      poElementStyles = JSON.parse(JSON.stringify(snap.elementStyles || {}));
      poRichText = JSON.parse(JSON.stringify(snap.richText || {}));

      if (snap.typography) {
        applyPriceOfferingTypography(snap.typography, false);
      }

      if (lead) {
        if (!lead.priceOffering) lead.priceOffering = {};
        lead.priceOffering.docTitle = snap.docHeading || (isDepositProforma ? 'DEPOSIT PROFORMA INVOICE' : (isProforma ? 'PROFORMA INVOICE' : 'Price Quote / Proposal'));
        lead.priceOffering.docSubtitle = snap.docSubtitle;
        lead.priceOffering.sender = {
          name: snap.senderName || '',
          title: snap.senderTitle || '',
          contact: snap.senderContact || '',
          location: snap.senderLocation || ''
        };
        lead.priceOffering.client = snap.clientName;
        lead.priceOffering.clientEmail = snap.clientEmail;
        lead.priceOffering.clientAddress = snap.clientAddress;
        lead.priceOffering.refNo = snap.refNo;
        lead.priceOffering.currency = snap.currency || 'EUR';
        lead.priceOffering.issueDate = snap.issueDate;
        lead.priceOffering.validUntil = snap.validUntil;
        lead.priceOffering.projectTitle = snap.projectTitle;
        lead.priceOffering.discountPercent = parseFloat(snap.discountPercent) || 0;
        lead.priceOffering.taxPercent = parseFloat(snap.taxPercent) || 0;
        if (snap.labels) lead.priceOffering.labels = JSON.parse(JSON.stringify(snap.labels));
        lead.priceOffering.sections = currentPoSections;
        lead.priceOffering.items = currentPoItems;
        lead.priceOffering.signatures = currentPoSignatures;
        lead.priceOffering.elementStyles = poElementStyles;
        lead.priceOffering.richText = poRichText;
        lead.priceOffering.typography = activePoTypography;
      }

      // Clear printArea before re-rendering so live() reads from snapshot state instead of pre-undo DOM
      const container = document.getElementById('priceOfferingPrintArea');
      if (container) container.innerHTML = '';

      renderPriceOfferingDocument(lead, lead?.priceOffering);

      if (snap.selectedElementId) {
        selectPoElement(null, snap.selectedElementId);
      } else if (snap.selectedSectionIndex !== null && snap.selectedSectionIndex !== undefined) {
        selectPoSection(snap.selectedSectionIndex);
      } else {
        selectPoElement(null, null);
      }

      syncPoRunningHeaders();
      recalculatePriceOfferingTotals();
      syncPriceOfferingTableMirrors();
      autoResizePoTextareas();

      triggerPriceOfferingAutoSave(true);
    } finally {
      poIsApplyingUndoRedo = false;
    }
  }

  function triggerPoUndo() {
    if (poInputSnapshotTimer) {
      clearTimeout(poInputSnapshotTimer);
      poInputSnapshotTimer = null;
    }
    const current = getPoDocumentSnapshot();
    const top = poUndoStack[poUndoStack.length - 1];
    if (top && JSON.stringify(top) !== JSON.stringify(current)) {
      poUndoStack.push(current);
    }
    if (poUndoStack.length <= 1) {
      showToast('Nothing to Undo', 'At oldest document state.', 'info');
      return;
    }
    const currentState = poUndoStack.pop();
    poRedoStack.push(currentState);
    const targetState = poUndoStack[poUndoStack.length - 1];
    applyPoDocumentSnapshot(targetState);
    updatePoUndoRedoUI();
    showToast('Undo ↺', 'Reverted document change.', 'info');
  }

  function triggerPoRedo() {
    if (poRedoStack.length === 0) return;
    const target = poRedoStack.pop();
    poUndoStack.push(target);
    applyPoDocumentSnapshot(target);
    updatePoUndoRedoUI();
    showToast('Redo ↻', 'Restored document change.', 'info');
  }

  function clearPoActiveWordMarks() {
    document.querySelectorAll('#priceOfferingPrintArea .po-active-word-mark').forEach(el => {
      el.classList.remove('po-active-word-mark');
      if (!el.getAttribute('class')) el.removeAttribute('class');
    });
  }

  // Universal InDesign-Style Element Selection
  function selectPoElement(element, id, name, type) {
    document.querySelectorAll('#priceOfferingPrintArea .po-selected-element').forEach(el => {
      el.classList.remove('po-selected-element');
    });

    if (!id) {
      poSelectedElementId = null;
      poSelectedElementMeta = null;
      selectedPoSectionIndex = null;
      poSavedTextRange = null;
      poLastStyledSpan = null;
      clearPoActiveWordMarks();
      updatePoRightSidebarInspector();
      return;
    }

    // Clear stale highlighted text range if switching to a different element
    if (poSavedTextRange) {
      const host = poRangeHost(poSavedTextRange);
      const targetCheck = element || document.querySelector(`[data-elem-id="${id}"]`);
      if (!host || (targetCheck && host !== targetCheck && !targetCheck.contains(host))) {
        poSavedTextRange = null;
        poLastStyledSpan = null;
        clearPoActiveWordMarks();
      }
    }

    poSelectedElementId = id;
    const targetElem = element || document.querySelector(`[data-elem-id="${id}"]`);
    if (targetElem) {
      targetElem.classList.add('po-selected-element');
    }

    const secEl = targetElem ? targetElem.closest('.po-section') : null;
    if (secEl) {
      const sIdx = parseInt(secEl.getAttribute('data-sec-index'), 10);
      selectedPoSectionIndex = !isNaN(sIdx) ? sIdx : null;
    } else {
      selectedPoSectionIndex = null;
    }

    poSelectedElementMeta = {
      id,
      name: name || targetElem?.getAttribute('data-elem-name') || 'Element',
      type: type || targetElem?.getAttribute('data-elem-type') || 'text'
    };

    updatePoRightSidebarInspector();
  }

  function selectPoSection(idx) {
    if (idx === null || idx === undefined || idx < 0 || idx >= currentPoSections.length) {
      selectedPoSectionIndex = null;
      selectPoElement(null, null);
    } else {
      selectedPoSectionIndex = idx;
      const sec = currentPoSections[idx];
      const secEl = document.querySelector(`.po-section[data-sec-index="${idx}"]`);
      const fallbackName = sec.type === 'divider'
        ? 'Divider Line'
        : (sec.type === 'header' ? 'Document Header' : (sec.type === 'overview' ? 'Client & Project Details' : (sec.title || 'Section')));
      const fallbackType = sec.type === 'divider'
        ? 'divider'
        : (sec.type === 'header' || sec.type === 'overview' ? sec.type : 'section');
      selectPoElement(secEl, `sec_${sec.id}`, fallbackName, fallbackType);
    }
  }

  function poBuildTransform(st) {
    if (!st) return '';
    const x = parseFloat(st.offsetX) || 0;
    const y = parseFloat(st.offsetY) || 0;
    const sy = parseFloat(st.textScaleY);
    const parts = [];
    if (x || y) parts.push(`translate(${x}mm, ${y}mm)`);
    if (!isNaN(sy) && sy > 0 && sy !== 100) parts.push(`scaleY(${+(sy / 100).toFixed(3)})`);
    return parts.join(' ');
  }

  // InDesign-Style Sub-millimeter & Millimeter Precision Nudging (X & Y)
  function setSelectedPoElementOffset(valMm, axis = 'y') {
    if (!poSelectedElementId) return;
    // Accept either (valMm, axis) or ('x'|'y', valMm)
    if (valMm === 'x' || valMm === 'y') {
      const tmp = valMm;
      valMm = axis;
      axis = tmp;
    }
    schedulePoInputSnapshot();
    const next = parseFloat((parseFloat(valMm) || 0).toFixed(2));
    if (poSelectedElementId.indexOf('sig_') === 0) {
      const sig = (currentPoSignatures || []).find(s => s && s.id === poSelectedElementId);
      if (sig) {
        if (axis === 'x') sig.xMm = next;
        else sig.yMm = next;
        const sigEl = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${poSelectedElementId}"]`);
        if (sigEl) {
          sigEl.style.left = `${sig.xMm}mm`;
          sigEl.style.top = `${sig.yMm}mm`;
        }
        updatePoRightSidebarInspector();
        triggerPriceOfferingAutoSave(false);
        return;
      }
    }
    if (!poElementStyles[poSelectedElementId]) {
      poElementStyles[poSelectedElementId] = {};
    }
    const prop = axis === 'x' ? 'offsetX' : 'offsetY';
    poElementStyles[poSelectedElementId][prop] = next;

    const el = document.querySelector(`[data-elem-id="${poSelectedElementId}"]`);
    if (el) {
      el.style.transform = poBuildTransform(poElementStyles[poSelectedElementId]);
    }
    updatePoRightSidebarInspector();
    triggerPriceOfferingAutoSave(false);
  }

  function nudgeSelectedPoElement(deltaMm, axis = 'y') {
    if (!poSelectedElementId) return;
    pushPoUndoSnapshot();
    if (poSelectedElementId.indexOf('sig_') === 0) {
      const sig = (currentPoSignatures || []).find(s => s && s.id === poSelectedElementId);
      if (sig) {
        if (axis === 'x') sig.xMm = parseFloat(((parseFloat(sig.xMm) || 0) + deltaMm).toFixed(2));
        else sig.yMm = parseFloat(((parseFloat(sig.yMm) || 0) + deltaMm).toFixed(2));
        const sigEl = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${poSelectedElementId}"]`);
        if (sigEl) {
          sigEl.style.left = `${sig.xMm}mm`;
          sigEl.style.top = `${sig.yMm}mm`;
        }
        updatePoRightSidebarInspector();
        triggerPriceOfferingAutoSave(false);
        return;
      }
    }
    if (!poElementStyles[poSelectedElementId]) {
      poElementStyles[poSelectedElementId] = {};
    }

    const prop = axis === 'x' ? 'offsetX' : 'offsetY';
    const prev = poElementStyles[poSelectedElementId][prop] || 0;
    const next = parseFloat((prev + deltaMm).toFixed(2));
    poElementStyles[poSelectedElementId][prop] = next;

    const el = document.querySelector(`[data-elem-id="${poSelectedElementId}"]`);
    if (el) {
      el.style.transform = poBuildTransform(poElementStyles[poSelectedElementId]);
    }

    updatePoRightSidebarInspector();
    triggerPriceOfferingAutoSave(false);
  }

  function resetSelectedElementNudge() {
    if (!poSelectedElementId) return;
    pushPoUndoSnapshot();
    if (poSelectedElementId.indexOf('sig_') === 0) {
      const sig = (currentPoSignatures || []).find(s => s && s.id === poSelectedElementId);
      if (sig) {
        const pos = getDefaultPoSignaturePlacement(sig.widthMm || 48, sig.heightMm || 18);
        sig.xMm = pos.xMm;
        sig.yMm = pos.yMm;
        renderPoSignaturesLayer();
        updatePoRightSidebarInspector();
        triggerPriceOfferingAutoSave(false);
        return;
      }
    }
    if (poElementStyles[poSelectedElementId]) {
      poElementStyles[poSelectedElementId].offsetX = 0;
      poElementStyles[poSelectedElementId].offsetY = 0;
    }
    const el = document.querySelector(`[data-elem-id="${poSelectedElementId}"]`);
    if (el) {
      el.style.transform = poBuildTransform(poElementStyles[poSelectedElementId]);
    }
    updatePoRightSidebarInspector();
    triggerPriceOfferingAutoSave(false);
  }

  function resetSelectedElementStyle() {
    const range = getPoActiveTextRange();
    if (range) {
      const host = poRangeHost(range);
      if (host) {
        schedulePoInputSnapshot();
        const text = range.toString();
        range.deleteContents();
        range.insertNode(document.createTextNode(text));
        poSavedTextRange = null;
        poLastStyledSpan = null;
        clearPoActiveWordMarks();
        syncPoSectionContentFromHost(host);
        updatePoRightSidebarInspector();
      }
      return;
    }
    if (!poSelectedElementId) return;
    pushPoUndoSnapshot();
    const prevSt = poElementStyles[poSelectedElementId] || {};
    const curEl = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${poSelectedElementId}"]`);
    if (curEl) {
      Object.keys(prevSt).forEach(p => poApplyStyleProp(curEl, p, null));
      curEl.style.transform = '';
      curEl.style.transformOrigin = '';
      if (curEl.classList.contains('po-section-content')) {
        curEl.innerHTML = formatInitialContent(poFieldText(curEl));
        syncPoSectionContentFromHost(curEl);
      }
    }
    delete poElementStyles[poSelectedElementId];
    delete poRichText[poSelectedElementId];
    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    renderPriceOfferingDocument(lead, lead?.priceOffering);
    triggerPriceOfferingAutoSave(true);
    showToast('Style Reset', 'Element restored to document default styling.', 'info');
  }

  // ==========================================
  // STYLE ENGINE: per-element styles + per-selection (specific words / lines) styles
  // ==========================================
  let poSavedTextRange = null;
  let poLastStyledSpan = null;
  let poPointerInControls = false;

  const PO_STYLE_CSS = {
    fontFamily: 'font-family',
    fontSize: 'font-size',
    fontWeight: 'font-weight',
    fontStyle: 'font-style',
    letterSpacing: 'letter-spacing',
    lineHeight: 'line-height',
    textTransform: 'text-transform',
    color: 'color',
    textAlign: 'text-align',
    textDecoration: 'text-decoration-line',
    marginTop: 'margin-top',
    marginBottom: 'margin-bottom'
  };

  function poCssValue(prop, value) {
    if (value === undefined || value === null || value === '' || value === 'inherit') return '';
    if (prop === 'fontSize' || prop === 'marginTop' || prop === 'marginBottom') return value + 'px';
    if (prop === 'letterSpacing') {
      const s = String(value).trim();
      if (!s || s === '0' || s === '0em' || s === 'normal') return 'normal';
      if (/^-?\d+(\.\d+)?$/.test(s)) return s + 'em';
      return s;
    }
    return String(value);
  }

  // Applies a single stored style property to its element (inputs use !important so they beat theme CSS)
  function poApplyStyleProp(el, prop, value) {
    if (!el) return;
    const isDivider = el.getAttribute('data-elem-type') === 'divider';
    if (prop === 'offsetY' || prop === 'offsetX' || prop === 'textScaleY') {
      const elemId = el.getAttribute('data-elem-id');
      const st = (elemId && poElementStyles[elemId]) ? poElementStyles[elemId] : { [prop]: value };
      el.style.transform = poBuildTransform(st);
      if (st.textScaleY && parseFloat(st.textScaleY) !== 100) {
        el.style.transformOrigin = 'left baseline';
      } else {
        el.style.removeProperty('transform-origin');
      }
      return;
    }
    if (isDivider && (prop === 'lineStyle' || prop === 'lineThickness' || prop === 'lineWidth' || prop === 'color')) {
      const line = el.querySelector('.po-divider-line') || el;
      if (prop === 'lineStyle') {
        line.style.setProperty('border-top-style', value || 'solid', 'important');
        if (value === 'double' && (!poElementStyles[el.getAttribute('data-elem-id')]?.lineThickness || poElementStyles[el.getAttribute('data-elem-id')]?.lineThickness < 3)) {
          line.style.setProperty('border-top-width', '3px', 'important');
        }
      }
      if (prop === 'lineThickness') line.style.setProperty('border-top-width', (value || 1) + 'px', 'important');
      if (prop === 'lineWidth') line.style.setProperty('width', value || '100%', 'important');
      if (prop === 'color') {
        if (value) line.style.setProperty('border-top-color', value, 'important');
        else line.style.removeProperty('border-top-color');
      }
      return;
    }
    if (prop === 'lineStyle' || prop === 'lineThickness' || prop === 'lineWidth') return;
    const cssProp = PO_STYLE_CSS[prop];
    if (!cssProp) return;
    const v = poCssValue(prop, value);
    if (v) el.style.setProperty(cssProp, v, 'important');
    else el.style.removeProperty(cssProp);
  }

  function poRangeHost(range) {
    if (!range) return null;
    let node = range.commonAncestorContainer;
    if (node && node.nodeType !== 1) node = node.parentElement;
    return node ? node.closest('.po-section-content[contenteditable="true"], .po-field[contenteditable="true"]') : null;
  }

  function getPoActiveTextRange() {
    if (!poSavedTextRange || poSavedTextRange.collapsed) return null;
    const host = poRangeHost(poSavedTextRange);
    if (!host || !document.body.contains(host)) return null;
    return poSavedTextRange;
  }

  function syncPoSectionContentFromHost(host) {
    if (!host) return;
    if (host.classList.contains('po-field')) {
      poRememberRichText(host);
      host.dispatchEvent(new Event('input', { bubbles: true }));
      return;
    }
    const secId = host.getAttribute('data-sec-id');
    const sec = currentPoSections.find(s => s.id === secId);
    if (sec) sec.content = poCleanContentHtml(host);
    schedulePoInputSnapshot();
    triggerPriceOfferingAutoSave(false);
    updatePoVisualPageBreakGuides();
  }

  function ensurePoRangeSpan(range) {
    const host = poRangeHost(range);
    if (!host) return null;
    let span = null;
    if (poLastStyledSpan && host.contains(poLastStyledSpan)) {
      const r = document.createRange();
      r.selectNodeContents(poLastStyledSpan);
      if (range.compareBoundaryPoints(Range.START_TO_START, r) === 0 && range.compareBoundaryPoints(Range.END_TO_END, r) === 0) {
        span = poLastStyledSpan;
      }
    }
    if (!span) {
      let startEl = range.startContainer;
      if (startEl && startEl.nodeType !== 1) startEl = startEl.parentElement;
      if (startEl && startEl.tagName === 'SPAN' && startEl !== host && startEl.textContent === range.toString()) {
        span = startEl;
      }
    }
    if (!span) {
      span = document.createElement('span');
      span.appendChild(range.extractContents());
      range.insertNode(span);
    }
    clearPoActiveWordMarks();
    span.classList.add('po-active-word-mark');
    poLastStyledSpan = span;
    const newRange = document.createRange();
    newRange.selectNodeContents(span);
    poSavedTextRange = newRange.cloneRange();
    return { span, host, newRange };
  }

  function applyStyleToPoRange(range, prop, value) {
    const wrapped = ensurePoRangeSpan(range);
    if (!wrapped) return false;
    const { span, host, newRange } = wrapped;

    if (prop === 'textScaleY') {
      const sy = parseFloat(value);
      if (!isNaN(sy) && sy > 0 && sy !== 100) {
        span.style.setProperty('display', 'inline-block');
        span.style.setProperty('transform-origin', 'left baseline');
        span.style.setProperty('transform', `scaleY(${+(sy / 100).toFixed(3)})`);
        span.setAttribute('data-scale-y', String(sy));
      } else {
        span.style.removeProperty('transform');
        span.style.removeProperty('transform-origin');
        span.removeAttribute('data-scale-y');
        if (!span.style.lineHeight) span.style.removeProperty('display');
      }
    } else if (prop === 'lineHeight') {
      const lh = parseFloat(value);
      if (!isNaN(lh) && lh > 0) {
        span.style.setProperty('display', 'inline-block');
        span.style.setProperty('line-height', String(lh));
      } else {
        span.style.removeProperty('line-height');
        if (!span.getAttribute('data-scale-y')) span.style.removeProperty('display');
      }
    } else {
      const cssProp = PO_STYLE_CSS[prop];
      if (!cssProp) return false;
      const v = poCssValue(prop, value);
      if (v) span.style.setProperty(cssProp, v);
      else span.style.removeProperty(cssProp);

      // Clear conflicting inline property on any nested child spans/fonts inside the selected range so the new style wins cleanly
      span.querySelectorAll('[style]').forEach(inner => {
        inner.style.removeProperty(cssProp);
        if (!inner.getAttribute('style') || !inner.getAttribute('style').trim()) inner.removeAttribute('style');
      });
      if (prop === 'fontFamily') {
        span.querySelectorAll('font[face]').forEach(fontEl => {
          if (value && value !== 'inherit') fontEl.setAttribute('face', value);
          else fontEl.removeAttribute('face');
        });
      }
    }

    // If a multi-line selection inside .po-section-content wrapped block <div> lines inside an inline <span>,
    // immediately distribute the span inside each <div> line so every line remains a direct block child for pagination.
    let finalRange = newRange;
    if (host.classList.contains('po-section-content') && span.querySelector('div, p')) {
      normalizePoSectionContentDom(host, { preserveActiveMarks: true });
      const marks = host.querySelectorAll('.po-active-word-mark');
      if (marks.length > 0) {
        const multiRange = document.createRange();
        multiRange.setStartBefore(marks[0]);
        multiRange.setEndAfter(marks[marks.length - 1]);
        finalRange = multiRange;
        poSavedTextRange = multiRange.cloneRange();
        poLastStyledSpan = marks.length === 1 ? marks[0] : null;
      }
    }

    // If the highlighted selection covers the entire text of a .po-field, keep poElementStyles[hostId] in sync so outer element styles never conflict with full-field rich text
    const hostId = host.getAttribute('data-elem-id');
    if (hostId && host.classList.contains('po-field') && (span.textContent || '').trim() === (host.textContent || '').trim()) {
      if (!poElementStyles[hostId]) poElementStyles[hostId] = {};
      poElementStyles[hostId][prop] = value;
      poApplyStyleProp(host, prop, value);
    }

    // Only manipulate native selection if user is not currently typing in a toolbar input
    const active = document.activeElement;
    const isTypingInControl = active && (active.tagName === 'INPUT' || active.tagName === 'SELECT') && active.closest('#priceOfferingTopBar, #poRightSidebar, #poPhotoshopSliderPopover');
    if (!isTypingInControl) {
      const sel = window.getSelection();
      if (sel) {
        sel.removeAllRanges();
        sel.addRange(finalRange);
      }
    }
    syncPoSectionContentFromHost(host);
    return true;
  }

  function poGetRangeLineBlocks(range) {
    const host = poRangeHost(range);
    if (!host || !host.classList.contains('po-section-content')) return [];
    const blocks = Array.from(host.children).filter(ch => ch.tagName === 'DIV' || ch.tagName === 'P');
    return blocks.filter(b => {
      try {
        return range.intersectsNode(b);
      } catch (_) {
        return false;
      }
    });
  }

  function poResolveSectionTypographyTargets(elemId, prop) {
    if (!elemId || elemId.indexOf('sec_') !== 0) return [elemId];
    const layoutProps = ['marginTop', 'marginBottom', 'offsetX', 'offsetY', 'lineStyle', 'lineThickness', 'lineWidth'];
    if (layoutProps.indexOf(prop) >= 0) return [elemId];
    const secEl = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${elemId}"]`);
    if (secEl && secEl.getAttribute('data-elem-type') === 'divider') return [elemId];
    const secId = elemId.slice(4);
    const contentId = `content_${secId}`;
    const titleId = `title_${secId}`;
    const hasContent = !!document.querySelector(`#priceOfferingPrintArea [data-elem-id="${contentId}"]`);
    const hasTitle = !!document.querySelector(`#priceOfferingPrintArea [data-elem-id="${titleId}"]`);
    if (hasContent || hasTitle) {
      const targets = [];
      if (hasContent) targets.push(contentId);
      if (hasTitle && (!hasContent || prop === 'fontFamily' || prop === 'color' || prop === 'textAlign')) {
        targets.push(titleId);
      }
      return targets;
    }
    if (secEl) {
      const childIds = Array.from(secEl.querySelectorAll('.po-field[data-elem-id]'))
        .map(el => el.getAttribute('data-elem-id'))
        .filter(Boolean);
      if (childIds.length > 0) return childIds;
    }
    return [elemId];
  }

  // Per-Element Typography & Line Style Controller
  function setElementTypography(prop, value) {
    // 1. Highlighted text inside a text box → style only that text (or its intersecting paragraph lines for block margin/align)
    const range = getPoActiveTextRange();
    if (range) {
      if (prop === 'marginTop' || prop === 'marginBottom' || prop === 'textAlign') {
        const lineBlocks = poGetRangeLineBlocks(range);
        if (lineBlocks.length > 0) {
          schedulePoInputSnapshot();
          const cssProp = PO_STYLE_CSS[prop];
          const v = poCssValue(prop, value);
          lineBlocks.forEach(b => {
            if (v) b.style.setProperty(cssProp, v);
            else b.style.removeProperty(cssProp);
            if (!b.getAttribute('style') || !b.getAttribute('style').trim()) b.removeAttribute('style');
          });
          syncPoSectionContentFromHost(poRangeHost(range));
          updatePoRightSidebarInspector();
          return;
        }
      } else if (prop !== 'lineStyle' && prop !== 'lineThickness' && prop !== 'lineWidth') {
        schedulePoInputSnapshot();
        applyStyleToPoRange(range, prop, value);
        updatePoRightSidebarInspector();
        return;
      }
    }

    // 2. Otherwise style the whole selected element (or whole document when nothing is selected)
    if (!poSelectedElementId) {
      if (prop === 'fontFamily' && value && value !== 'inherit') {
        schedulePoInputSnapshot();
        applyPriceOfferingTypography({ fontFamily: value }, true, true);
      } else if (prop === 'fontSize' && value) {
        schedulePoInputSnapshot();
        applyPriceOfferingTypography({ fontSize: parseFloat(value) || 13 }, true, true);
      } else if (prop === 'lineHeight' && value) {
        schedulePoInputSnapshot();
        applyPriceOfferingTypography({ lineHeight: parseFloat(value) || 1.6 }, true, true);
      } else if (prop === 'color' || prop === 'fontWeight' || prop === 'textAlign' || prop === 'textTransform' || prop === 'letterSpacing' || prop === 'textScaleY') {
        schedulePoInputSnapshot();
        (currentPoSections || []).forEach(s => {
          if (!s || !s.id || s.type === 'divider') return;
          const ck = `content_${s.id}`;
          if (document.querySelector(`#priceOfferingPrintArea [data-elem-id="${ck}"]`)) {
            if (!poElementStyles[ck]) poElementStyles[ck] = {};
            poElementStyles[ck][prop] = value;
          }
          if (prop === 'color' || prop === 'textAlign') {
            const tk = `title_${s.id}`;
            if (document.querySelector(`#priceOfferingPrintArea [data-elem-id="${tk}"]`)) {
              if (!poElementStyles[tk]) poElementStyles[tk] = {};
              poElementStyles[tk][prop] = value;
            }
          }
        });
        applySavedElementStyles();
        triggerPriceOfferingAutoSave(false);
        updatePoRightSidebarInspector();
        updatePoVisualPageBreakGuides();
      }
      return;
    }

    schedulePoInputSnapshot();
    const targetIds = poResolveSectionTypographyTargets(poSelectedElementId, prop);
    targetIds.forEach(tid => {
      if (!poElementStyles[tid]) {
        poElementStyles[tid] = {};
      }
      if (value === null || value === undefined || value === '') {
        delete poElementStyles[tid][prop];
      } else {
        poElementStyles[tid][prop] = value;
      }

      const el = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${tid}"]`);
      poApplyStyleProp(el, prop, value);

      // If styling a whole rich-text field, clear conflicting inline properties on inner spans/fonts so element-level styling applies cleanly
      if (el && (el.classList.contains('po-field') || el.classList.contains('po-section-content'))) {
        const cssProp = PO_STYLE_CSS[prop];
        if (cssProp) {
          el.querySelectorAll('[style]').forEach(inner => {
            inner.style.removeProperty(cssProp);
            if (!inner.getAttribute('style') || !inner.getAttribute('style').trim()) inner.removeAttribute('style');
          });
        }
        if (prop === 'fontFamily') {
          el.querySelectorAll('font[face]').forEach(fontEl => {
            if (value && value !== 'inherit') fontEl.setAttribute('face', value);
            else fontEl.removeAttribute('face');
          });
        }
        if (el.classList.contains('po-field')) {
          poRememberRichText(el);
        } else {
          const secId = el.getAttribute('data-sec-id');
          const sec = currentPoSections.find(s => s.id === secId);
          if (sec) sec.content = poCleanContentHtml(el);
        }
      }
    });

    if (prop === 'fontSize' || prop === 'fontFamily' || prop === 'lineHeight') poFitFieldMetrics();

    triggerPriceOfferingAutoSave(false);
    updatePoRightSidebarInspector();
    updatePoVisualPageBreakGuides();
  }

  // Bold / Italic / Underline / Strikethrough
  function applyPoTextFormat(cmd) {
    const range = getPoActiveTextRange();
    if (range) {
      const host = poRangeHost(range);
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
      host.focus({ preventScroll: true });
      sel.removeAllRanges();
      sel.addRange(range);
      schedulePoInputSnapshot();
      try { document.execCommand('styleWithCSS', false, false); } catch (e) {}
      document.execCommand(cmd, false, null);
      if (sel.rangeCount) poSavedTextRange = sel.getRangeAt(0).cloneRange();
      poLastStyledSpan = null;
      syncPoSectionContentFromHost(host);
      updatePoRightSidebarInspector();
      return;
    }

    // Focused contenteditable with a caret (no highlight) → toggle for upcoming typing
    const active = document.activeElement;
    if (active && active.isContentEditable && active.closest('#priceOfferingPrintArea')) {
      if (!poSelectedElementId && active.getAttribute('data-elem-id')) {
        selectPoElement(active, active.getAttribute('data-elem-id'));
      }
    }

    if (!poSelectedElementId) {
      showToast('Select text first', 'Highlight words or click any text element to format it.', 'info');
      return;
    }
    const targetIds = poResolveSectionTypographyTargets(poSelectedElementId, cmd === 'bold' ? 'fontWeight' : (cmd === 'italic' ? 'fontStyle' : 'textDecoration'));
    const primaryTargetId = targetIds[0] || poSelectedElementId;
    const st = poElementStyles[primaryTargetId] || poElementStyles[poSelectedElementId] || {};
    if (cmd === 'bold') {
      setElementTypography('fontWeight', (st.fontWeight === '700' || st.fontWeight === '900') ? 'inherit' : '700');
    } else if (cmd === 'italic') {
      setElementTypography('fontStyle', st.fontStyle === 'italic' ? 'inherit' : 'italic');
    } else if (cmd === 'underline' || cmd === 'strikeThrough') {
      const token = cmd === 'underline' ? 'underline' : 'line-through';
      const parts = String(st.textDecoration || '').split(' ').filter(Boolean);
      const idx = parts.indexOf(token);
      if (idx >= 0) parts.splice(idx, 1); else parts.push(token);
      setElementTypography('textDecoration', parts.length ? parts.join(' ') : 'inherit');
    }
    updatePoRightSidebarInspector();
  }

  function poGetMovableUnit(el) {
    if (!el) return null;
    if (el.classList && el.classList.contains('po-section')) return el;
    const metaCell = el.closest && el.closest('.po-meta-cell');
    if (metaCell) return metaCell;
    const totalRow = el.closest && el.closest('.po-total-row');
    if (totalRow) return totalRow;
    if (el.closest && (el.closest('.po-title-wrap') || el.classList.contains('po-section-content') || el.classList.contains('po-section-title-input'))) {
      return el.closest('.po-section');
    }
    return el;
  }

  function poGetUnitOrderKey(unit) {
    if (!unit) return null;
    return unit.getAttribute('data-po-unit-id') || unit.getAttribute('data-elem-id') || unit.id || null;
  }

  function applySavedElementStyles() {
    if (!poElementStyles || typeof poElementStyles !== 'object') poElementStyles = {};

    // Clear previous deleted markers before re-applying
    document.querySelectorAll('#priceOfferingPrintArea [data-po-deleted="1"]').forEach(el => {
      el.style.removeProperty('display');
      el.removeAttribute('data-po-deleted');
    });

    Object.keys(poElementStyles).forEach(elemId => {
      const st = poElementStyles[elemId];
      if (!st) return;
      // Never allow a section body or section title to be hidden via elementStyles.deleted
      if (st.deleted && /^(content|title)_/.test(elemId)) {
        delete st.deleted;
      }
      const el = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${elemId}"], #priceOfferingPrintArea [data-po-unit-id="${elemId}"]`);
      if (!el) return;
      if (st.deleted) {
        el.style.setProperty('display', 'none', 'important');
        el.setAttribute('data-po-deleted', '1');
        return;
      }
      Object.keys(st).forEach(prop => {
        if (prop === 'deleted' || prop === 'domOrder') return;
        poApplyStyleProp(el, prop, st[prop]);
      });
    });

    // Hide any metadata cell or total row whose inner [data-elem-id] children are all deleted
    document.querySelectorAll('#priceOfferingPrintArea .po-meta-cell, #priceOfferingPrintArea .po-total-row').forEach(cell => {
      const unitId = cell.getAttribute('data-po-unit-id');
      if (unitId && poElementStyles[unitId] && poElementStyles[unitId].deleted) {
        cell.style.setProperty('display', 'none', 'important');
        cell.setAttribute('data-po-deleted', '1');
        return;
      }
      const elems = Array.from(cell.querySelectorAll('[data-elem-id]'));
      if (elems.length > 0 && elems.every(ch => poElementStyles[ch.getAttribute('data-elem-id')]?.deleted)) {
        cell.style.setProperty('display', 'none', 'important');
        cell.setAttribute('data-po-deleted', '1');
      }
    });

    // Apply saved custom sibling DOM order inside [data-po-container] containers (never swap section title & body)
    document.querySelectorAll('#priceOfferingPrintArea [data-po-container]').forEach(container => {
      const cid = container.getAttribute('data-po-container') || '';
      if (cid.startsWith('sec_body_')) return;
      const children = Array.from(container.children);
      if (children.length < 2) return;
      let hasCustomOrder = false;
      const keyed = children.map((ch, idx) => {
        const key = poGetUnitOrderKey(ch);
        const ord = (key && poElementStyles[key] && typeof poElementStyles[key].domOrder === 'number')
          ? poElementStyles[key].domOrder
          : null;
        if (ord !== null) hasCustomOrder = true;
        return { ch, idx, ord: ord !== null ? ord : idx * 1000 };
      });
      if (!hasCustomOrder) return;
      keyed.sort((a, b) => (a.ord - b.ord) || (a.idx - b.idx));
      keyed.forEach(item => container.appendChild(item.ch));
    });

    const restoreHiddenBtn = document.getElementById('poRestoreHiddenFieldsBtn');
    const restoreHiddenText = document.getElementById('poRestoreHiddenFieldsBtnText');
    if (restoreHiddenBtn) {
      const hiddenCount = Object.keys(poElementStyles).filter(k => poElementStyles[k] && poElementStyles[k].deleted && !k.startsWith('meta_cell_') && !k.startsWith('row_')).length;
      if (hiddenCount > 0) {
        restoreHiddenBtn.classList.remove('hidden');
        if (restoreHiddenText) restoreHiddenText.textContent = `Restore Hidden Fields (${hiddenCount})`;
      } else {
        restoreHiddenBtn.classList.add('hidden');
      }
    }

    poFitFieldMetrics();
  }

  function rgbToHexColor(rgb) {
    if (!rgb) return '#0f172a';
    if (rgb.startsWith('#')) return rgb.length === 4 ? '#' + rgb[1] + rgb[1] + rgb[2] + rgb[2] + rgb[3] + rgb[3] : rgb;
    const m = rgb.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    if (!m) return '#0f172a';
    const hex = (x) => ('0' + parseInt(x, 10).toString(16)).slice(-2);
    return '#' + hex(m[1]) + hex(m[2]) + hex(m[3]);
  }

  function updatePoRightSidebarInspector() {
    const docPanel = document.getElementById('poDocumentSettingsPanel');
    const card = document.getElementById('poSelectionCard');
    const headerDeselect = document.getElementById('poHeaderDeselectBtn');
    const topDeselect = document.getElementById('poTopDeselectBtn');
    const clearStyleBtn = document.getElementById('poClearElementStyleBtn');
    const sidebarHeaderTitle = document.getElementById('poSidebarHeaderTitle');
    const sidebarHeaderSubtitle = document.getElementById('poSidebarHeaderSubtitle');
    const nameEl = document.getElementById('poSelectedElemName');
    const typeEl = document.getElementById('poSelectedElemType');
    const badgeEl = document.getElementById('poSelectedTypeBadge');
    const offsetXInp = document.getElementById('poElemOffsetXMmInput');
    const offsetYInp = document.getElementById('poElemOffsetYMmInput');
    const nudgeControls = document.getElementById('poNudgeControls');
    const sectionReorder = document.getElementById('poSectionReorderControls');
    const parentBlockLabel = document.getElementById('poParentBlockLabel');
    const deleteBtn = document.getElementById('poDeleteSelectedBtn');
    const dupBtn = document.getElementById('poDuplicateSelectedBtn');
    const dividerPanel = document.getElementById('poDividerControls');
    const sigControls = document.getElementById('poSignatureControls');
    const elemSpacingControls = document.getElementById('poElementSpacingControls');
    const spaceBeforeInp = document.getElementById('poElemSpaceBeforePtInput');
    const spaceAfterInp = document.getElementById('poElemSpaceAfterPtInput');
    const elemLineHeightInp = document.getElementById('poElemLineHeightInput');
    const elemTextHeightInp = document.getElementById('poElemTextHeightInput');
    const elemLetterSpacingInp = document.getElementById('poElemLetterSpacingInput');

    // Top control bar elements
    const topScopeDot = document.getElementById('poTopScopeDot');
    const topScopeText = document.getElementById('poTopScopeText');
    const topFontSelect = document.getElementById('poTopFontFamilySelect');
    const topSizePtInput = document.getElementById('poTopFontSizePtInput');
    const topWeightSelect = document.getElementById('poTopFontWeightSelect');
    const topTextHeightInput = document.getElementById('poTopTextHeightInput');
    const topLineHeightInput = document.getElementById('poTopLineHeightInput');
    const topColorPicker = document.getElementById('poTopColorPicker');
    const topColorHex = document.getElementById('poTopColorHexInput');
    const insertTargetHint = document.getElementById('poInsertSectionTargetHint');
    if (insertTargetHint) {
      if (typeof poPendingCanvasInsertIndex === 'number' && poPendingCanvasInsertIndex !== null) {
        insertTargetHint.textContent = 'At selected line';
      } else if (selectedPoSectionIndex !== null && selectedPoSectionIndex >= 0) {
        insertTargetHint.textContent = 'Below selected block';
      } else {
        insertTargetHint.textContent = 'Click gap on page or add below';
      }
    }

    const range = getPoActiveTextRange();

    if (!poSelectedElementId && !range) {
      if (card) card.classList.add('hidden');
      if (docPanel) docPanel.classList.remove('hidden');
      if (headerDeselect) headerDeselect.classList.add('hidden');
      if (topDeselect) topDeselect.classList.add('hidden');
      if (clearStyleBtn) clearStyleBtn.classList.add('hidden');
      if (sigControls) sigControls.classList.add('hidden');
      if (sidebarHeaderTitle) sidebarHeaderTitle.textContent = state.activeStudioDocId ? 'Page & Layout' : 'Page & Template';
      if (sidebarHeaderSubtitle) sidebarHeaderSubtitle.textContent = 'Global document rhythm, margins & sections';

      // Sync top control bar to Document Defaults
      if (topScopeDot) topScopeDot.className = 'w-1.5 h-1.5 rounded-full bg-slate-400 shrink-0';
      if (topScopeText) topScopeText.textContent = 'Whole Document';
      if (topFontSelect) topFontSelect.value = activePoTypography.fontFamily || 'Inter, sans-serif';
      if (topSizePtInput && document.activeElement !== topSizePtInput) {
        topSizePtInput.value = poPxToPt(activePoTypography.fontSize || 13);
      }
      if (topWeightSelect) topWeightSelect.value = 'inherit';
      if (topTextHeightInput && document.activeElement !== topTextHeightInput) topTextHeightInput.value = 100;
      if (topLineHeightInput && document.activeElement !== topLineHeightInput) topLineHeightInput.value = activePoTypography.lineHeight || 1.6;
      if (topColorPicker) topColorPicker.value = '#0f172a';
      if (topColorHex && document.activeElement !== topColorHex) topColorHex.value = '#0f172a';
      document.querySelectorAll('.po-format-btn').forEach(btn => {
        btn.classList.remove('bg-slate-900', 'text-white');
        btn.classList.add('text-slate-700');
      });
      document.querySelectorAll('.po-case-btn').forEach(btn => {
        btn.classList.remove('bg-slate-900', 'text-white');
        btn.classList.add('text-slate-700');
      });
      document.querySelectorAll('.po-align-btn').forEach(btn => {
        btn.className = 'po-align-btn p-1 text-slate-500 hover:text-slate-900 rounded cursor-pointer';
      });
      return;
    }

    if (card) card.classList.remove('hidden');
    if (docPanel) docPanel.classList.add('hidden');
    if (headerDeselect) headerDeselect.classList.remove('hidden');
    if (topDeselect) topDeselect.classList.remove('hidden');
    if (sidebarHeaderTitle) sidebarHeaderTitle.textContent = 'Element Layout';
    if (sidebarHeaderSubtitle) sidebarHeaderSubtitle.textContent = range
      ? 'Inline spacing & proportions for marked words'
      : 'Spacing, position & block order for selection';

    const meta = poSelectedElementMeta || { id: poSelectedElementId, name: 'Selected Text', type: 'text' };
    const isBlock = poSelectedElementId ? poSelectedElementId.indexOf('sec_') === 0 : false;
    const isSignature = !range && (meta.type === 'signature' || (poSelectedElementId && poSelectedElementId.indexOf('sig_') === 0));
    const typeLabels = { section: 'Section', divider: 'Divider', header: 'Header', overview: 'Details', table: 'Table', signatures: 'Signatures', signature: 'Signature', text: 'Text' };

    if (nameEl) nameEl.textContent = range ? 'Highlighted Words' : meta.name;
    if (typeEl) {
      typeEl.textContent = range
        ? `In ${meta.name} • Top Bar & sliders style marked words`
        : (isSignature ? 'Drag on page to move • Drag corner to scale' : (isBlock ? 'Use buttons below to reorder or style' : 'Use Top Text Bar for font, size, height & color'));
    }
    if (badgeEl) badgeEl.textContent = range ? 'Words' : (typeLabels[meta.type] || meta.type);

    if (topScopeDot) topScopeDot.className = range ? 'w-1.5 h-1.5 rounded-full bg-amber-500 shrink-0' : 'w-1.5 h-1.5 rounded-full bg-slate-900 shrink-0';
    if (topScopeText) topScopeText.textContent = range ? 'Highlighted Words' : meta.name;
    if (clearStyleBtn) clearStyleBtn.classList.toggle('hidden', isSignature || (isBlock && meta.type !== 'divider' && !range));

    const st = (poSelectedElementId && poElementStyles[poSelectedElementId]) || {};
    const selSig = isSignature ? (currentPoSignatures || []).find(s => s && s.id === poSelectedElementId) : null;
    const curX = selSig ? (parseFloat(selSig.xMm) || 0) : (parseFloat(st.offsetX) || 0);
    const curY = selSig ? (parseFloat(selSig.yMm) || 0) : (parseFloat(st.offsetY) || 0);
    if (offsetXInp && document.activeElement !== offsetXInp) offsetXInp.value = curX;
    if (offsetYInp && document.activeElement !== offsetYInp) offsetYInp.value = curY;
    if (nudgeControls) nudgeControls.classList.toggle('hidden', !!range);

    const rangeLineBlocks = range ? poGetRangeLineBlocks(range) : [];
    const paraMarginGroup = document.getElementById('poElemParagraphMarginGroup');
    if (paraMarginGroup) paraMarginGroup.classList.toggle('hidden', isSignature || (!!range && rangeLineBlocks.length === 0));
    const textMetricsGrid = document.getElementById('poElemTextMetricsGrid');
    const spacingHeaderTitle = document.getElementById('poElemSpacingHeaderTitle');
    const hideTextMetrics = !range && (meta.type === 'divider' || meta.type === 'table' || meta.type === 'signatures' || isSignature);
    if (textMetricsGrid) textMetricsGrid.classList.toggle('hidden', hideTextMetrics);
    if (spacingHeaderTitle) spacingHeaderTitle.textContent = hideTextMetrics ? 'Block Spacing' : 'Metrics & Spacing';
    if (elemSpacingControls) elemSpacingControls.classList.toggle('hidden', isSignature);

    if (spaceBeforeInp && document.activeElement !== spaceBeforeInp) {
      const rawMt = (range && rangeLineBlocks[0]) ? parseFloat(rangeLineBlocks[0].style.marginTop) : st.marginTop;
      spaceBeforeInp.value = (rawMt !== undefined && !isNaN(rawMt) && rawMt > 0) ? poPxToPt(rawMt) : 0;
    }
    if (spaceAfterInp && document.activeElement !== spaceAfterInp) {
      const rawMb = (range && rangeLineBlocks[0]) ? parseFloat(rangeLineBlocks[0].style.marginBottom) : st.marginBottom;
      spaceAfterInp.value = (rawMb !== undefined && !isNaN(rawMb) && rawMb > 0) ? poPxToPt(rawMb) : 0;
    }

    // Block & Element Order/Delete actions: available whenever any element inside a block or a block itself is selected (hidden when highlighting inline words)
    const selSec = (!range && selectedPoSectionIndex !== null && currentPoSections[selectedPoSectionIndex])
      ? currentPoSections[selectedPoSectionIndex]
      : null;
    const cannotDuplicateSec = !selSec || selSec.type === 'deliverables' || selSec.type === 'header' || selSec.type === 'overview';
    if (sectionReorder) {
      if (!range && (selSec || poSelectedElementId)) {
        sectionReorder.classList.remove('hidden');
        const primaryOrderTitle = document.getElementById('poPrimaryOrderTitle');
        const primaryOrderTarget = document.getElementById('poPrimaryOrderTarget');
        const deleteBtnText = document.getElementById('poDeleteSelectedBtnText');
        const parentBlockRow = document.getElementById('poParentBlockActionsRow');
        const moveUpBtn = document.getElementById('poMoveSelectedUpBtn');
        const moveDownBtn = document.getElementById('poMoveSelectedDownBtn');
        const moveParentUpBtn = document.getElementById('poMoveParentBlockUpBtn');
        const moveParentDownBtn = document.getElementById('poMoveParentBlockDownBtn');
        const setDisabled = (btn, dis) => {
          if (!btn) return;
          btn.classList.toggle('opacity-40', dis);
          btn.classList.toggle('pointer-events-none', dis);
          if (dis) btn.setAttribute('disabled', 'true'); else btn.removeAttribute('disabled');
        };

        const isItemField = poSelectedElementId && /^item_(desc|qty|rate|amount)_(\d+)$/.test(poSelectedElementId);
        const isSectionTitleOrBody = !!(poSelectedElementId && /^(title|content)_/.test(poSelectedElementId));
        if (isSignature) {
          if (primaryOrderTitle) primaryOrderTitle.textContent = 'Signature Actions';
          if (primaryOrderTarget) primaryOrderTarget.textContent = selSig?.kind === 'image' ? 'PNG Signature' : 'Vector Signature';
          if (deleteBtnText) deleteBtnText.textContent = 'Delete';
          if (deleteBtn) {
            deleteBtn.classList.remove('hidden');
            deleteBtn.title = 'Delete Signature';
          }
          if (parentBlockRow) parentBlockRow.classList.add('hidden');
          setDisabled(moveUpBtn, true);
          setDisabled(moveDownBtn, true);
          if (dupBtn) setDisabled(dupBtn, false);
        } else if (isBlock || isSectionTitleOrBody) {
          if (primaryOrderTitle) primaryOrderTitle.textContent = 'Block Order & Actions';
          if (primaryOrderTarget) primaryOrderTarget.textContent = selSec ? (selSec.title || (selSec.type === 'divider' ? 'Divider Line' : 'Block')) : 'Block';
          if (deleteBtnText) deleteBtnText.textContent = 'Delete';
          if (deleteBtn) {
            deleteBtn.classList.remove('hidden');
            deleteBtn.title = 'Delete Block';
          }
          if (parentBlockRow) parentBlockRow.classList.add('hidden');
          setDisabled(moveUpBtn, !selSec || selectedPoSectionIndex <= 0);
          setDisabled(moveDownBtn, !selSec || selectedPoSectionIndex >= currentPoSections.length - 1);
          if (dupBtn) setDisabled(dupBtn, cannotDuplicateSec);
        } else if (isItemField) {
          const itemIdx = parseInt(poSelectedElementId.split('_').pop(), 10);
          if (primaryOrderTitle) primaryOrderTitle.textContent = 'Row Order & Actions';
          if (primaryOrderTarget) primaryOrderTarget.textContent = `Deliverable Row #${itemIdx + 1}`;
          if (deleteBtnText) deleteBtnText.textContent = 'Delete';
          if (deleteBtn) {
            deleteBtn.classList.remove('hidden');
            deleteBtn.title = 'Delete Row';
          }
          setDisabled(moveUpBtn, itemIdx <= 0);
          setDisabled(moveDownBtn, itemIdx >= currentPoItems.length - 1);
          if (dupBtn) setDisabled(dupBtn, false);
          if (parentBlockRow) parentBlockRow.classList.toggle('hidden', !selSec);
          if (selSec) {
            if (parentBlockLabel) parentBlockLabel.textContent = selSec.title || 'Block';
            setDisabled(moveParentUpBtn, selectedPoSectionIndex === 0);
            setDisabled(moveParentDownBtn, selectedPoSectionIndex === currentPoSections.length - 1);
          }
        } else {
          const shortName = (meta.name || 'Field').length > 22 ? (meta.name || 'Field').slice(0, 20) + '…' : (meta.name || 'Field');
          if (primaryOrderTitle) primaryOrderTitle.textContent = 'Element Order & Actions';
          if (primaryOrderTarget) primaryOrderTarget.textContent = shortName;
          if (deleteBtnText) deleteBtnText.textContent = 'Delete';
          if (deleteBtn) {
            deleteBtn.classList.remove('hidden');
            deleteBtn.title = 'Delete Field';
          }
          if (dupBtn) setDisabled(dupBtn, cannotDuplicateSec);

          const el = poSelectedElementId ? document.querySelector(`#priceOfferingPrintArea [data-elem-id="${poSelectedElementId}"]`) : null;
          const unit = poGetMovableUnit(el);
          const container = unit ? unit.parentElement : null;
          const visibleSiblings = container ? Array.from(container.children).filter(ch => ch.getAttribute('data-po-deleted') !== '1' && window.getComputedStyle(ch).display !== 'none') : [];
          const uIdx = visibleSiblings.indexOf(unit);
          const canMoveUpInContainer = uIdx > 0;
          const canMoveDownInContainer = uIdx >= 0 && uIdx < visibleSiblings.length - 1;
          const canMoveBlockUp = selSec && selectedPoSectionIndex > 0;
          const canMoveBlockDown = selSec && selectedPoSectionIndex < currentPoSections.length - 1;
          setDisabled(moveUpBtn, !canMoveUpInContainer && !canMoveBlockUp);
          setDisabled(moveDownBtn, !canMoveDownInContainer && !canMoveBlockDown);

          if (parentBlockRow) parentBlockRow.classList.toggle('hidden', !selSec);
          if (selSec) {
            if (parentBlockLabel) parentBlockLabel.textContent = selSec.title || (selSec.type === 'divider' ? 'Divider Line' : 'Block');
            setDisabled(moveParentUpBtn, selectedPoSectionIndex === 0);
            setDisabled(moveParentDownBtn, selectedPoSectionIndex === currentPoSections.length - 1);
          }
        }
      } else {
        sectionReorder.classList.add('hidden');
      }
    }

    if (isSignature && selSig) {
      if (dividerPanel) dividerPanel.classList.add('hidden');
      if (sigControls) sigControls.classList.remove('hidden');
      const strokeRow = document.getElementById('poSigStrokeWidthRow');
      if (strokeRow) strokeRow.classList.toggle('hidden', selSig.kind === 'image');
      const origColorBtn = document.getElementById('poSigInspectorOrigColorBtn');
      if (origColorBtn) origColorBtn.classList.toggle('hidden', selSig.kind !== 'image');
      const swRange = document.getElementById('poSigStrokeWidthRange');
      const swVal = document.getElementById('poSigStrokeWidthVal');
      const curSw = parseFloat(selSig.strokeWidth) || 2.25;
      if (swRange) swRange.value = String(curSw);
      if (swVal) swVal.textContent = curSw.toFixed(1) + 'pt';
      const wRange = document.getElementById('poSigWidthMmRange');
      const wVal = document.getElementById('poSigWidthMmVal');
      const curW = Math.round(parseFloat(selSig.widthMm) || 48);
      if (wRange) wRange.value = String(curW);
      if (wVal) wVal.textContent = curW + 'mm';
      document.querySelectorAll('.po-sig-inspector-color').forEach(btn => {
        const c = btn.getAttribute('data-color');
        btn.classList.toggle('ring-2', c === selSig.color);
        btn.classList.toggle('ring-offset-1', c === selSig.color);
        btn.classList.toggle('ring-slate-900', c === selSig.color);
      });
      return;
    }

    if (sigControls) sigControls.classList.add('hidden');

    if (meta.type === 'divider') {
      if (dividerPanel) dividerPanel.classList.remove('hidden');
      if (elemSpacingControls) elemSpacingControls.classList.remove('hidden');

      const lineStyle = st.lineStyle || 'solid';
      document.querySelectorAll('.po-line-style-btn').forEach(btn => {
        const s = btn.getAttribute('data-style');
        btn.className = (s === lineStyle)
          ? 'po-line-style-btn py-1 px-1 text-[10px] font-bold border border-slate-900 bg-slate-900 text-white rounded cursor-pointer'
          : 'po-line-style-btn py-1 px-1 text-[10px] font-medium border border-slate-200 rounded bg-white hover:bg-slate-50 text-slate-700 cursor-pointer';
      });
      const thick = st.lineThickness || 1;
      const thickRange = document.getElementById('poLineThicknessRange');
      if (thickRange) thickRange.value = thick;
      const thickVal = document.getElementById('poLineThicknessVal');
      if (thickVal) thickVal.textContent = thick + 'px';

      const lineWidth = st.lineWidth || '100%';
      document.querySelectorAll('.po-line-width-btn').forEach(btn => {
        const w = btn.getAttribute('data-width');
        btn.className = (w === lineWidth)
          ? 'po-line-width-btn py-1 px-1 text-[10px] font-bold border border-slate-900 bg-slate-900 text-white rounded cursor-pointer'
          : 'po-line-width-btn py-1 px-1 text-[10px] font-medium border border-slate-200 rounded bg-white hover:bg-slate-50 text-slate-700 cursor-pointer';
      });
      const divColor = st.color || '#cbd5e1';
      if (topColorPicker) topColorPicker.value = divColor;
      if (topColorHex && document.activeElement !== topColorHex) topColorHex.value = divColor;
      return;
    }

    if (dividerPanel) dividerPanel.classList.add('hidden');
    if (elemSpacingControls) elemSpacingControls.classList.remove('hidden');
    if (!range && (meta.type === 'table' || meta.type === 'signatures')) return;

    const typoTargets = (!range && poSelectedElementId) ? poResolveSectionTypographyTargets(poSelectedElementId, 'fontSize') : [];
    const typoElemId = typoTargets[0] || poSelectedElementId;
    const typoSt = (typoElemId && poElementStyles[typoElemId]) || st;

    let probe = typoElemId ? document.querySelector(`#priceOfferingPrintArea [data-elem-id="${typoElemId}"]`) : null;
    if (range) {
      if (poLastStyledSpan && document.body.contains(poLastStyledSpan)) {
        probe = poLastStyledSpan;
      } else {
        let n = range.startContainer;
        if (n && n.nodeType !== 1) n = n.parentElement;
        if (n) probe = n;
      }
    } else if (probe) {
      // If whole element was styled via rich-text spans/fonts wrapping its entire content, inspect the inner wrapper so Top Bar reflects actual visible font/size/weight
      let innerProbe = probe;
      while (
        innerProbe.children &&
        innerProbe.children.length === 1 &&
        /^(FONT|SPAN|B|STRONG|I|EM|U)$/i.test(innerProbe.children[0].tagName) &&
        (innerProbe.children[0].textContent || '').trim() === (probe.textContent || '').trim()
      ) {
        innerProbe = innerProbe.children[0];
      }
      probe = innerProbe;
    }
    const comp = probe ? window.getComputedStyle(probe) : null;

    const fontValRaw = range
      ? (probe?.style?.fontFamily || typoSt.fontFamily || (comp && comp.fontFamily) || 'inherit')
      : (typoSt.fontFamily || (comp && comp.fontFamily) || 'inherit');
    if (topFontSelect) {
      const cleanName = (s) => String(s || '').split(',')[0].replace(/['"]/g, '').trim().toLowerCase();
      const targetName = cleanName(fontValRaw);
      const matchedOpt = Array.from(topFontSelect.options).find(o => o.value === fontValRaw || (targetName && cleanName(o.value) === targetName));
      topFontSelect.value = matchedOpt ? matchedOpt.value : 'inherit';
    }

    let fSizePx = (!range && typoSt.fontSize) ? parseFloat(typoSt.fontSize) : (range && probe?.style?.fontSize ? parseFloat(probe.style.fontSize) : 0);
    if (!fSizePx && comp && comp.fontSize) {
      fSizePx = parseFloat(comp.fontSize) || 13;
    }
    if (!fSizePx) fSizePx = 13;
    const fSizePt = poPxToPt(fSizePx);

    if (topSizePtInput && document.activeElement !== topSizePtInput) topSizePtInput.value = fSizePt;

    let weightVal = range
      ? (probe?.style?.fontWeight || (comp && comp.fontWeight) || 'inherit')
      : (typoSt.fontWeight || (comp && comp.fontWeight) || 'inherit');
    if (weightVal === 'bold') weightVal = '700';
    else if (weightVal === 'normal') weightVal = '400';
    if (topWeightSelect) {
      const hasW = Array.from(topWeightSelect.options).some(o => o.value === String(weightVal));
      topWeightSelect.value = hasW ? String(weightVal) : 'inherit';
    }

    // Text Height (%)
    let scaleYVal = 100;
    if (range) {
      const scaleNode = probe?.closest ? probe.closest('[data-scale-y]') : null;
      scaleYVal = parseFloat(scaleNode?.getAttribute('data-scale-y') || probe?.getAttribute?.('data-scale-y')) || 100;
    } else if (typoSt.textScaleY) {
      scaleYVal = parseFloat(typoSt.textScaleY) || 100;
    }
    if (topTextHeightInput && document.activeElement !== topTextHeightInput) topTextHeightInput.value = scaleYVal;
    if (elemTextHeightInp && document.activeElement !== elemTextHeightInp) elemTextHeightInp.value = scaleYVal;

    // Line Height (×)
    let lhVal = activePoTypography.lineHeight || 1.6;
    if (range && probe?.style?.lineHeight) {
      lhVal = parseFloat(probe.style.lineHeight) || lhVal;
    } else if (!range && typoSt.lineHeight) {
      lhVal = parseFloat(typoSt.lineHeight) || lhVal;
    } else if (comp && comp.lineHeight && comp.fontSize) {
      const ratio = parseFloat(comp.lineHeight) / parseFloat(comp.fontSize);
      if (!isNaN(ratio) && ratio >= 0.6 && ratio <= 4) lhVal = Math.round(ratio * 20) / 20;
    }
    if (topLineHeightInput && document.activeElement !== topLineHeightInput) topLineHeightInput.value = lhVal;
    if (elemLineHeightInp && document.activeElement !== elemLineHeightInp) elemLineHeightInp.value = lhVal;

    // Letter Spacing (displayed as % where 5% = 0.05em)
    let trackPct = 0;
    const rawTrack = range ? (probe?.style?.letterSpacing || '') : (typoSt.letterSpacing || '');
    if (rawTrack && rawTrack !== 'inherit' && rawTrack !== 'normal') {
      const num = parseFloat(rawTrack) || 0;
      trackPct = String(rawTrack).includes('em') ? Math.round(num * 100) : Math.round(num);
    }
    if (elemLetterSpacingInp && document.activeElement !== elemLetterSpacingInp) elemLetterSpacingInp.value = trackPct;

    const resolvedHex = (!range && typoSt.color) ? typoSt.color : (comp ? rgbToHexColor(comp.color) : '#0f172a');
    if (topColorPicker) topColorPicker.value = resolvedHex;
    if (topColorHex && document.activeElement !== topColorHex) topColorHex.value = resolvedHex;

    const deco = String((!range && typoSt.textDecoration) || (comp && comp.textDecorationLine) || '');
    const weightNum = parseInt((!range && typoSt.fontWeight) || (comp && comp.fontWeight) || '400', 10);
    const fStyle = (!range && typoSt.fontStyle) || (comp && comp.fontStyle) || 'normal';
    const fmtState = {
      bold: weightNum >= 700 || (range && document.queryCommandState && document.queryCommandState('bold')),
      italic: fStyle === 'italic' || (range && document.queryCommandState && document.queryCommandState('italic')),
      underline: deco.indexOf('underline') >= 0 || (range && document.queryCommandState && document.queryCommandState('underline')),
      strikeThrough: deco.indexOf('line-through') >= 0 || (range && document.queryCommandState && document.queryCommandState('strikeThrough'))
    };
    document.querySelectorAll('.po-format-btn').forEach(btn => {
      const on = !!fmtState[btn.getAttribute('data-cmd')];
      btn.classList.toggle('bg-slate-900', on);
      btn.classList.toggle('text-white', on);
      btn.classList.toggle('text-slate-700', !on);
    });

    const curCase = (range ? probe?.style?.textTransform : typoSt.textTransform) || (comp && comp.textTransform) || 'none';
    document.querySelectorAll('.po-case-btn').forEach(btn => {
      const on = btn.getAttribute('data-case') === curCase;
      btn.classList.toggle('bg-slate-900', on);
      btn.classList.toggle('text-white', on);
      btn.classList.toggle('text-slate-700', !on);
    });

    const align = (range && rangeLineBlocks[0]?.style?.textAlign) || typoSt.textAlign || (comp && comp.textAlign) || 'left';
    document.querySelectorAll('.po-align-btn').forEach(btn => {
      const a = btn.getAttribute('data-align');
      const isMatch = (a === align) || (a === 'left' && align === 'start') || (a === 'right' && align === 'end');
      btn.classList.toggle('bg-slate-900', isMatch);
      btn.classList.toggle('text-white', isMatch);
      btn.classList.toggle('text-slate-500', !isMatch);
    });
  }

  function duplicatePoSectionAt(idx) {
    if (poSelectedElementId && poSelectedElementId.indexOf('sig_') === 0) {
      const origSig = (currentPoSignatures || []).find(s => s && s.id === poSelectedElementId);
      if (origSig) {
        pushPoUndoSnapshot();
        const newSig = JSON.parse(JSON.stringify(origSig));
        newSig.id = 'sig_' + Date.now() + '_' + Math.random().toString(36).slice(2, 5);
        newSig.xMm = parseFloat(((parseFloat(origSig.xMm) || 120) + 4).toFixed(1));
        newSig.yMm = parseFloat(((parseFloat(origSig.yMm) || 220) + 4).toFixed(1));
        currentPoSignatures.push(newSig);
        renderPoSignaturesLayer();
        const sigEl = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${newSig.id}"]`);
        selectPoElement(sigEl, newSig.id, newSig.kind === 'image' ? 'PNG Signature' : 'Vector Signature', 'signature');
        triggerPriceOfferingAutoSave(true);
        showToast('Signature Duplicated ✨', 'Drag the copy to position it.', 'success');
        return;
      }
    }
    const itemMatch = poSelectedElementId ? poSelectedElementId.match(/^item_(desc|qty|rate|amount)_(\d+)$/) : null;
    if (itemMatch) {
      const fieldType = itemMatch[1];
      const itemIdx = parseInt(itemMatch[2], 10);
      if (!isNaN(itemIdx) && currentPoItems[itemIdx]) {
        flushLivePoDomToState();
        pushPoUndoSnapshot();
        const insertIdx = itemIdx + 1;
        const cloneItem = JSON.parse(JSON.stringify(currentPoItems[itemIdx]));
        cloneItem.id = 'po_item_' + Date.now() + '_' + Math.random().toString(36).slice(2, 5);
        // Shift item_* keys in poElementStyles and poRichText from end down to insertIdx
        for (let r = currentPoItems.length - 1; r >= insertIdx; r--) {
          ['desc', 'qty', 'rate', 'amount'].forEach(f => {
            const oldK = `item_${f}_${r}`;
            const newK = `item_${f}_${r + 1}`;
            if (poElementStyles[oldK] !== undefined) poElementStyles[newK] = JSON.parse(JSON.stringify(poElementStyles[oldK]));
            else delete poElementStyles[newK];
            if (poRichText[oldK] !== undefined) poRichText[newK] = poRichText[oldK];
            else delete poRichText[newK];
          });
        }
        // Copy row itemIdx's styles and richText into insertIdx
        ['desc', 'qty', 'rate', 'amount'].forEach(f => {
          const srcK = `item_${f}_${itemIdx}`;
          const dstK = `item_${f}_${insertIdx}`;
          if (poElementStyles[srcK] !== undefined) poElementStyles[dstK] = JSON.parse(JSON.stringify(poElementStyles[srcK]));
          else delete poElementStyles[dstK];
          if (poRichText[srcK] !== undefined) poRichText[dstK] = poRichText[srcK];
          else delete poRichText[dstK];
        });
        currentPoItems.splice(insertIdx, 0, cloneItem);
        renderPriceOfferingItemsTable();
        recalculatePriceOfferingTotals();
        const newElemId = `item_${fieldType}_${insertIdx}`;
        const newEl = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${newElemId}"]`);
        if (newEl) {
          selectPoElement(newEl, newElemId, newEl.getAttribute('data-elem-name') || `Deliverable Row #${insertIdx + 1}`, 'text');
        }
        triggerPriceOfferingAutoSave(true);
        showToast('Row Duplicated ✨', `Duplicated deliverable row #${itemIdx + 1}.`, 'success');
        return;
      }
    }
    if (idx === null || idx === undefined || isNaN(idx)) {
      idx = selectedPoSectionIndex;
    }
    if (idx === null || idx === undefined || isNaN(idx) || !currentPoSections[idx]) return;
    const orig = currentPoSections[idx];
    if (orig.type === 'deliverables' || orig.type === 'header' || orig.type === 'overview') {
      showToast('Cannot Duplicate', 'This structural block can only appear once.', 'info');
      return;
    }

    flushLivePoDomToState();
    pushPoUndoSnapshot();
    const newId = orig.type + '_copy_' + Date.now();
    const clone = JSON.parse(JSON.stringify(orig));
    const oldId = orig.id;
    clone.id = newId;

    // Copy any element styles & rich text associated with the original block
    Object.keys(poElementStyles).forEach(k => {
      if (k.endsWith(oldId)) {
        const nk = k.slice(0, k.length - oldId.length) + newId;
        poElementStyles[nk] = JSON.parse(JSON.stringify(poElementStyles[k]));
      }
    });
    Object.keys(poRichText).forEach(k => {
      if (k.endsWith(oldId)) {
        const nk = k.slice(0, k.length - oldId.length) + newId;
        poRichText[nk] = poRichText[k];
      }
    });

    const insertAt = idx + 1;
    currentPoSections.splice(insertAt, 0, clone);
    selectedPoSectionIndex = insertAt;

    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    if (lead && lead.priceOffering) {
      lead.priceOffering.sections = currentPoSections;
    }
    renderPriceOfferingDocument(lead, lead?.priceOffering);
    selectPoSection(insertAt);
    savePriceOfferingDoc(false);
    showToast('Duplicated ✨', `Duplicated "${orig.title || 'block'}".`, 'success');
  }

  function movePoSection(idx, dir) {
    if (idx === null || idx === undefined || isNaN(idx)) idx = selectedPoSectionIndex;
    if ((idx === null || idx === undefined || isNaN(idx)) && poSelectedElementId) {
      const el = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${poSelectedElementId}"]`);
      const secEl = el ? el.closest('.po-section') : null;
      if (secEl) {
        const sIdx = parseInt(secEl.getAttribute('data-sec-index'), 10);
        if (!isNaN(sIdx)) idx = sIdx;
      }
    }
    if (idx === null || idx === undefined || isNaN(idx)) return;
    let newIdx = idx + dir;
    if (newIdx < 0 || newIdx >= currentPoSections.length) return;

    // When moving a content section across an adjacent divider, swap with the content section on the other side of the divider so dividers stay between sections
    const curSec = currentPoSections[idx];
    const adjSec = currentPoSections[newIdx];
    const acrossIdx = idx + (2 * dir);
    if (
      curSec && curSec.type !== 'divider' && curSec.type !== 'header' &&
      adjSec && adjSec.type === 'divider' &&
      acrossIdx >= 0 && acrossIdx < currentPoSections.length &&
      currentPoSections[acrossIdx] && currentPoSections[acrossIdx].type !== 'divider' && currentPoSections[acrossIdx].type !== 'header'
    ) {
      newIdx = acrossIdx;
    }

    flushLivePoDomToState();
    pushPoUndoSnapshot();

    const prevSelectedElemId = poSelectedElementId;
    const prevSelectedMeta = poSelectedElementMeta ? Object.assign({}, poSelectedElementMeta) : null;

    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);

    const temp = currentPoSections[idx];
    currentPoSections[idx] = currentPoSections[newIdx];
    currentPoSections[newIdx] = temp;

    selectedPoSectionIndex = newIdx;
    if (lead && lead.priceOffering) {
      lead.priceOffering.sections = currentPoSections;
    }
    renderPriceOfferingDocument(lead, lead?.priceOffering);

    if (prevSelectedElemId && /^(title|content)_/.test(prevSelectedElemId)) {
      const movedField = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${prevSelectedElemId}"]`);
      if (movedField) {
        selectPoElement(movedField, prevSelectedElemId, prevSelectedMeta?.name || 'Section', prevSelectedMeta?.type || 'text');
        selectedPoSectionIndex = newIdx;
        updatePoRightSidebarInspector();
      } else {
        selectPoSection(newIdx);
      }
    } else {
      selectPoSection(newIdx);
    }

    // Keep the moved section visible inside #poCanvasViewport without jumping to top
    const viewport = document.getElementById('poCanvasViewport');
    const targetEl = document.querySelector(`.po-section[data-sec-index="${newIdx}"]`);
    if (viewport && targetEl) {
      const vpRect = viewport.getBoundingClientRect();
      const tRect = targetEl.getBoundingClientRect();
      if (tRect.bottom > vpRect.bottom - 24) {
        viewport.scrollTop += (tRect.bottom - (vpRect.bottom - 24));
      } else if (tRect.top < vpRect.top + 24) {
        viewport.scrollTop -= ((vpRect.top + 24) - tRect.top);
      }
    }

    savePriceOfferingDoc(false);
  }

  async function deletePoSectionAt(idx) {
    if (idx === null || idx === undefined || isNaN(idx)) {
      idx = selectedPoSectionIndex;
    }
    if (idx === null || idx === undefined || isNaN(idx)) {
      if (poSelectedElementId) {
        const el = document.querySelector(`[data-elem-id="${poSelectedElementId}"]`);
        const secEl = el ? el.closest('.po-section') : null;
        if (secEl) {
          const sIdx = parseInt(secEl.getAttribute('data-sec-index'), 10);
          if (!isNaN(sIdx)) idx = sIdx;
        }
      }
    }
    if (idx === null || idx === undefined || isNaN(idx) || !currentPoSections || !currentPoSections[idx]) return;

    const sec = currentPoSections[idx];
    const secName = sec.title || (sec.type === 'divider' ? 'Divider Line' : (sec.type === 'header' ? 'Document Header' : (sec.type === 'overview' ? 'Client Details' : 'Section')));
    const isDivider = sec.type === 'divider';
    const isEmpty = sec.type === 'text' && (!sec.content || sec.content.trim() === '');

    if (!isDivider && !isEmpty) {
      const confirmed = await confirmAction({
        title: `Delete "${secName}"?`,
        message: `Are you sure you want to remove this block from the document? (You can undo with Cmd/Ctrl+Z)`,
        confirmText: 'Delete Block',
        danger: true
      });
      if (!confirmed) return;
    }

    flushLivePoDomToState();
    pushPoUndoSnapshot();

    currentPoSections.splice(idx, 1);
    poSelectedElementId = null;
    poSelectedElementMeta = null;
    selectedPoSectionIndex = null;

    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    if (lead) {
      if (!lead.priceOffering) lead.priceOffering = {};
      lead.priceOffering.sections = currentPoSections;
      lead.priceOffering._structuralMigrated = true;
    }

    renderPriceOfferingDocument(lead, lead?.priceOffering);
    updatePoRightSidebarInspector();
    savePriceOfferingDoc(false);
    showToast('Removed', `"${secName}" removed. (Cmd/Ctrl+Z to Undo)`, 'info');
  }

  function poShiftItemStyleKeysOnDelete(deletedIdx, totalAfterDelete) {
    ['desc', 'qty', 'rate', 'amount'].forEach(f => {
      delete poElementStyles[`item_${f}_${deletedIdx}`];
      delete poRichText[`item_${f}_${deletedIdx}`];
      for (let i = deletedIdx; i < totalAfterDelete; i++) {
        const fromKey = `item_${f}_${i + 1}`;
        const toKey = `item_${f}_${i}`;
        if (poElementStyles[fromKey]) {
          poElementStyles[toKey] = poElementStyles[fromKey];
          delete poElementStyles[fromKey];
        } else {
          delete poElementStyles[toKey];
        }
        if (poRichText[fromKey]) {
          poRichText[toKey] = poRichText[fromKey];
          delete poRichText[fromKey];
        } else {
          delete poRichText[toKey];
        }
      }
    });
  }

  function poSwapItemStyleKeys(idxA, idxB) {
    ['desc', 'qty', 'rate', 'amount'].forEach(f => {
      const kA = `item_${f}_${idxA}`;
      const kB = `item_${f}_${idxB}`;
      const tmpStyle = poElementStyles[kA];
      if (poElementStyles[kB] !== undefined) poElementStyles[kA] = poElementStyles[kB];
      else delete poElementStyles[kA];
      if (tmpStyle !== undefined) poElementStyles[kB] = tmpStyle;
      else delete poElementStyles[kB];

      const tmpRich = poRichText[kA];
      if (poRichText[kB] !== undefined) poRichText[kA] = poRichText[kB];
      else delete poRichText[kA];
      if (tmpRich !== undefined) poRichText[kB] = tmpRich;
      else delete poRichText[kB];
    });
  }

  function deleteSelectedPoElementOrSection() {
    if (!poSelectedElementId) {
      if (selectedPoSectionIndex !== null) deletePoSectionAt(selectedPoSectionIndex);
      return;
    }
    if (poSelectedElementId.indexOf('sig_') === 0) {
      const sigIdx = (currentPoSignatures || []).findIndex(s => s && s.id === poSelectedElementId);
      if (sigIdx !== -1) {
        pushPoUndoSnapshot();
        currentPoSignatures.splice(sigIdx, 1);
        selectPoElement(null, null);
        renderPoSignaturesLayer();
        triggerPriceOfferingAutoSave(true);
        showToast('Signature Removed', 'Signature removed from document. (Cmd/Ctrl+Z to Undo)', 'info');
      }
      return;
    }
    if (/^(sec|title|content)_/.test(poSelectedElementId)) {
      deletePoSectionAt(selectedPoSectionIndex);
      return;
    }
    const itemMatch = poSelectedElementId.match(/^item_(desc|qty|rate|amount)_(\d+)$/);
    if (itemMatch) {
      const itemIdx = parseInt(itemMatch[2], 10);
      if (!isNaN(itemIdx) && currentPoItems[itemIdx]) {
        pushPoUndoSnapshot();
        flushLivePoDomToState();
        currentPoItems.splice(itemIdx, 1);
        poShiftItemStyleKeysOnDelete(itemIdx, currentPoItems.length);
        poSelectedElementId = null;
        poSelectedElementMeta = null;
        renderPriceOfferingItemsTable();
        recalculatePriceOfferingTotals();
        updatePoRightSidebarInspector();
        triggerPriceOfferingAutoSave(true);
        showToast('Removed', `Deliverable row #${itemIdx + 1} removed. (Cmd/Ctrl+Z to Undo)`, 'info');
      }
      return;
    }

    const el = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${poSelectedElementId}"]`);
    const elemName = poSelectedElementMeta?.name || el?.getAttribute('data-elem-name') || 'Element';
    pushPoUndoSnapshot();

    if (!poElementStyles[poSelectedElementId]) poElementStyles[poSelectedElementId] = {};
    poElementStyles[poSelectedElementId].deleted = true;

    // If deleting a primary metadata value or total value, or if all items in its cell are deleted, clean up the cell
    const metaValueIds = ['ref_no', 'cur_input', 'issue_date_val', 'valid_until_val'];
    const cell = el ? el.closest('.po-meta-cell, .po-total-row') : null;
    if (cell && metaValueIds.includes(poSelectedElementId)) {
      const unitId = cell.getAttribute('data-po-unit-id');
      if (unitId) {
        if (!poElementStyles[unitId]) poElementStyles[unitId] = {};
        poElementStyles[unitId].deleted = true;
      }
      cell.querySelectorAll('[data-elem-id]').forEach(ch => {
        const cid = ch.getAttribute('data-elem-id');
        if (cid) {
          if (!poElementStyles[cid]) poElementStyles[cid] = {};
          poElementStyles[cid].deleted = true;
        }
      });
    }

    applySavedElementStyles();
    selectPoElement(null, null);
    updatePoVisualPageBreakGuides();
    triggerPriceOfferingAutoSave(true);
    showToast('Removed', `"${elemName}" removed. (Cmd/Ctrl+Z to Undo)`, 'info');
  }

  function moveSelectedPoElementOrSection(dir) {
    if (!poSelectedElementId || /^(sec|title|content)_/.test(poSelectedElementId)) {
      movePoSection(selectedPoSectionIndex, dir);
      return;
    }
    const itemMatch = poSelectedElementId.match(/^item_(desc|qty|rate|amount)_(\d+)$/);
    if (itemMatch) {
      const field = itemMatch[1];
      const idx = parseInt(itemMatch[2], 10);
      const newIdx = idx + dir;
      if (newIdx < 0 || newIdx >= currentPoItems.length) return;
      pushPoUndoSnapshot();
      flushLivePoDomToState();
      const tmp = currentPoItems[idx];
      currentPoItems[idx] = currentPoItems[newIdx];
      currentPoItems[newIdx] = tmp;
      poSwapItemStyleKeys(idx, newIdx);
      renderPriceOfferingItemsTable();
      recalculatePriceOfferingTotals();
      const newId = `item_${field}_${newIdx}`;
      const newEl = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${newId}"]`);
      if (newEl) {
        selectPoElement(newEl, newId, newEl.getAttribute('data-elem-name') || 'Item', 'text');
      }
      triggerPriceOfferingAutoSave(true);
      return;
    }

    const el = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${poSelectedElementId}"]`);
    const unit = poGetMovableUnit(el);
    const container = unit ? unit.parentElement : null;
    if (unit && container) {
      const visibleSiblings = Array.from(container.children).filter(ch =>
        ch.getAttribute('data-po-deleted') !== '1' && window.getComputedStyle(ch).display !== 'none'
      );
      const curIdx = visibleSiblings.indexOf(unit);
      const targetIdx = curIdx + dir;
      if (curIdx !== -1 && targetIdx >= 0 && targetIdx < visibleSiblings.length) {
        pushPoUndoSnapshot();
        const targetSibling = visibleSiblings[targetIdx];
        if (dir < 0) {
          container.insertBefore(unit, targetSibling);
        } else {
          container.insertBefore(unit, targetSibling.nextSibling);
        }
        Array.from(container.children).forEach((child, orderIdx) => {
          const key = poGetUnitOrderKey(child);
          if (key) {
            if (!poElementStyles[key]) poElementStyles[key] = {};
            poElementStyles[key].domOrder = orderIdx + 1;
          }
        });
        updatePoRightSidebarInspector();
        updatePoVisualPageBreakGuides();
        triggerPriceOfferingAutoSave(true);
        return;
      }
    }

    // Fallback: if element is at the edge of its container, move the parent section block
    if (selectedPoSectionIndex !== null) {
      movePoSection(selectedPoSectionIndex, dir);
    }
  }

  function copyPoStyleWithoutPosition(srcStyle, opts = {}) {
    if (!srcStyle || typeof srcStyle !== 'object') return null;
    const copy = JSON.parse(JSON.stringify(srcStyle));
    delete copy.offsetX;
    delete copy.offsetY;
    delete copy.deleted;
    delete copy.domOrder;
    if (!opts.keepMargins) {
      delete copy.marginTop;
      delete copy.marginBottom;
    }
    return Object.keys(copy).length > 0 ? copy : null;
  }

  function findNearestPoReferenceSection(type, insertIdx, opts = {}) {
    if (!Array.isArray(currentPoSections) || currentPoSections.length === 0) return null;
    const isBodyDividerCandidate = (sec, idx) => {
      if (!sec || sec.type !== 'divider') return false;
      if (insertIdx > 1 && idx === 1 && currentPoSections[0] && currentPoSections[0].type === 'header') {
        return false;
      }
      return true;
    };
    const hasCompleteTitleStyle = (sec) => {
      if (!sec || !poElementStyles) return false;
      const ts = poElementStyles['title_' + sec.id];
      return !!(ts && ts.lineHeight && ts.fontSize);
    };
    const isPrecededByDivider = (idx) => idx > 0 && currentPoSections[idx - 1] && currentPoSections[idx - 1].type === 'divider';
    if (type === 'text') {
      // First pass: nearest text section that has complete title styling (fontSize + lineHeight)
      for (let d = 0; d < currentPoSections.length; d++) {
        const prevIdx = insertIdx - 1 - d;
        if (prevIdx >= 0 && currentPoSections[prevIdx] && currentPoSections[prevIdx].type === 'text' && hasCompleteTitleStyle(currentPoSections[prevIdx])) {
          if (typeof opts.preferAfterDivider !== 'boolean' || isPrecededByDivider(prevIdx) === opts.preferAfterDivider) {
            return currentPoSections[prevIdx];
          }
        }
        const nextIdx = insertIdx + d;
        if (nextIdx >= 0 && nextIdx < currentPoSections.length && currentPoSections[nextIdx] && currentPoSections[nextIdx].type === 'text' && hasCompleteTitleStyle(currentPoSections[nextIdx])) {
          if (typeof opts.preferAfterDivider !== 'boolean' || isPrecededByDivider(nextIdx) === opts.preferAfterDivider) {
            return currentPoSections[nextIdx];
          }
        }
      }
      // Second pass: any text section with complete title styling regardless of divider
      for (let d = 0; d < currentPoSections.length; d++) {
        const prevIdx = insertIdx - 1 - d;
        if (prevIdx >= 0 && currentPoSections[prevIdx] && currentPoSections[prevIdx].type === 'text' && hasCompleteTitleStyle(currentPoSections[prevIdx])) {
          return currentPoSections[prevIdx];
        }
        const nextIdx = insertIdx + d;
        if (nextIdx >= 0 && nextIdx < currentPoSections.length && currentPoSections[nextIdx] && currentPoSections[nextIdx].type === 'text' && hasCompleteTitleStyle(currentPoSections[nextIdx])) {
          return currentPoSections[nextIdx];
        }
      }
    }
    const matchesType = (sec, idx) => {
      if (!sec) return false;
      if (type === 'divider') return isBodyDividerCandidate(sec, idx);
      if (type === 'text') return sec.type === 'text';
      return sec.type === type;
    };
    for (let d = 0; d < currentPoSections.length; d++) {
      const prevIdx = insertIdx - 1 - d;
      if (prevIdx >= 0 && matchesType(currentPoSections[prevIdx], prevIdx)) {
        return currentPoSections[prevIdx];
      }
      const nextIdx = insertIdx + d;
      if (nextIdx >= 0 && nextIdx < currentPoSections.length && matchesType(currentPoSections[nextIdx], nextIdx)) {
        return currentPoSections[nextIdx];
      }
    }
    if (type === 'divider') {
      return currentPoSections.find(s => s && s.type === 'divider') || null;
    }
    return null;
  }

  function insertPoSectionAtIndex(type, insertIdx) {
    if (insertIdx === null || insertIdx === undefined || isNaN(insertIdx)) {
      insertIdx = currentPoSections.length;
    }
    if (insertIdx < 0) insertIdx = 0;
    if (insertIdx > currentPoSections.length) insertIdx = currentPoSections.length;

    let newSec = null;
    const stamp = Date.now();
    if (type === 'divider') {
      newSec = {
        id: 'sec_div_' + stamp,
        type: 'divider',
        title: 'Divider Line',
        content: ''
      };
    } else if (type === 'deliverables') {
      newSec = {
        id: 'sec_deliv_' + stamp,
        type: 'deliverables',
        title: 'Deliverables & Investment'
      };
    } else if (type === 'terms') {
      newSec = {
        id: 'sec_terms_' + stamp,
        type: 'terms',
        title: 'Timeline & Payment Terms',
        content: '• Estimated timeline: 2–3 weeks from kickoff.\n• 50% upfront deposit upon contract signing.\n• 50% upon final delivery & sign-off.\n• Includes up to 2 rounds of design revisions.'
      };
    } else if (type === 'conditions') {
      newSec = {
        id: 'sec_cond_' + stamp,
        type: 'conditions',
        title: 'Terms & Conditions',
        content: '• Work commences upon receipt of deposit.\n• Out-of-scope requests will be quoted separately.\n• Client provides all required assets and feedback promptly.'
      };
    } else if (type === 'acceptance') {
      newSec = {
        id: 'sec_acc_' + stamp,
        type: 'acceptance',
        title: 'Authorization & Acceptance',
        clientTitle: 'Authorized Client Signature',
        providerTitle: 'Service Provider Signature'
      };
    } else {
      newSec = {
        id: 'sec_text_' + stamp,
        type: 'text',
        title: state.activeStudioDocId ? 'SECTION TITLE' : 'New Section',
        content: ''
      };
    }

    flushLivePoDomToState();
    pushPoUndoSnapshot();

    // Inherit section spacing & typography from nearest matching section and normalize spacing around dividers
    if (poElementStyles && typeof poElementStyles === 'object') {
      if (newSec.type === 'text') {
        const prevSec = insertIdx > 0 ? currentPoSections[insertIdx - 1] : null;
        const isAfterDivider = !!(prevSec && prevSec.type === 'divider');
        const refSec = findNearestPoReferenceSection('text', insertIdx, { preferAfterDivider: isAfterDivider });
        if (refSec) {
          const secStyle = copyPoStyleWithoutPosition(poElementStyles['sec_' + refSec.id]);
          const titleStyle = copyPoStyleWithoutPosition(poElementStyles['title_' + refSec.id]) || {};
          const contentStyle = copyPoStyleWithoutPosition(poElementStyles['content_' + refSec.id]);
          if (isAfterDivider) {
            delete titleStyle.marginTop;
          } else {
            // When placed directly after another text section without a divider, ensure comfortable breathing room above title
            const refNoDivStyle = poElementStyles['title_' + refSec.id];
            if (refNoDivStyle && typeof refNoDivStyle.marginTop === 'number' && refNoDivStyle.marginTop > 0) {
              titleStyle.marginTop = refNoDivStyle.marginTop;
            } else if (!titleStyle.lineHeight || parseFloat(titleStyle.lineHeight) < 1.8) {
              titleStyle.lineHeight = '2.2';
            }
          }
          if (secStyle) poElementStyles['sec_' + newSec.id] = secStyle;
          if (Object.keys(titleStyle).length > 0) poElementStyles['title_' + newSec.id] = titleStyle;
          if (contentStyle) poElementStyles['content_' + newSec.id] = contentStyle;
        }
      } else if (newSec.type === 'divider') {
        const refSec = findNearestPoReferenceSection('divider', insertIdx);
        if (refSec) {
          const divStyle = copyPoStyleWithoutPosition(poElementStyles['sec_' + refSec.id], { keepMargins: true });
          if (divStyle) poElementStyles['sec_' + newSec.id] = divStyle;
        }
        // If this new divider is inserted immediately above a text section, normalize that text section's top spacing to match divider-preceded sections
        const nextSec = currentPoSections[insertIdx];
        if (nextSec && nextSec.type === 'text') {
          const refAfterDiv = findNearestPoReferenceSection('text', insertIdx, { preferAfterDivider: true });
          const nextTitleKey = 'title_' + nextSec.id;
          const nextSecKey = 'sec_' + nextSec.id;
          if (poElementStyles[nextSecKey] && poElementStyles[nextSecKey].marginTop) {
            delete poElementStyles[nextSecKey].marginTop;
          }
          if (poElementStyles[nextTitleKey] && poElementStyles[nextTitleKey].marginTop) {
            delete poElementStyles[nextTitleKey].marginTop;
          }
          if (refAfterDiv && poElementStyles['title_' + refAfterDiv.id] && poElementStyles['title_' + refAfterDiv.id].lineHeight) {
            if (!poElementStyles[nextTitleKey]) poElementStyles[nextTitleKey] = {};
            poElementStyles[nextTitleKey].lineHeight = poElementStyles['title_' + refAfterDiv.id].lineHeight;
          }
        }
      }
    }

    currentPoSections.splice(insertIdx, 0, newSec);
    selectedPoSectionIndex = insertIdx;

    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    if (lead && lead.priceOffering) {
      lead.priceOffering.sections = currentPoSections;
    }

    renderPriceOfferingDocument(lead, lead?.priceOffering);
    selectPoSection(insertIdx);
    savePriceOfferingDoc(false);

    const newEl = document.querySelector(`.po-section[data-sec-index="${insertIdx}"]`);
    if (newEl) {
      newEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      if (type === 'text') {
        const titleInp = newEl.querySelector('.po-section-title-input');
        if (titleInp) {
          titleInp.focus();
          if (typeof titleInp.select === 'function') {
            titleInp.select();
          } else if (titleInp.isContentEditable && window.getSelection && document.createRange) {
            try {
              const r = document.createRange();
              r.selectNodeContents(titleInp);
              const sel = window.getSelection();
              if (sel) {
                sel.removeAllRanges();
                sel.addRange(r);
              }
            } catch (_) {}
          }
        }
      }
    }
  }

  function addPoSectionFromSidebar(type, explicitInsertIdx = null) {
    let insertIdx = currentPoSections.length;
    if (explicitInsertIdx !== null && explicitInsertIdx !== undefined && !isNaN(explicitInsertIdx)) {
      insertIdx = explicitInsertIdx;
    } else if (poPendingCanvasInsertIndex !== null && !isNaN(poPendingCanvasInsertIndex)) {
      insertIdx = poPendingCanvasInsertIndex;
    } else if (selectedPoSectionIndex !== null && selectedPoSectionIndex >= 0 && selectedPoSectionIndex < currentPoSections.length) {
      insertIdx = selectedPoSectionIndex + 1;
    }
    insertPoSectionAtIndex(type, insertIdx);
  }

  function getDefaultPoSections(po, lead) {
    if (Array.isArray(po?.sections) && po.sections.length > 0) {
      return JSON.parse(JSON.stringify(po.sections));
    }

    if (po?._isDepositProforma || lead?._isDepositProforma || state.activeDepositProformaProjectId) {
      const depMaster = getMasterDepositProformaTemplate();
      if (depMaster && Array.isArray(depMaster.sections) && depMaster.sections.length > 0) {
        return JSON.parse(JSON.stringify(depMaster.sections));
      }
    }

    if (po?._isProforma || lead?._isProforma || state.activeProformaProjectId) {
      const profMaster = getMasterProformaTemplate();
      if (profMaster && Array.isArray(profMaster.sections) && profMaster.sections.length > 0) {
        return JSON.parse(JSON.stringify(profMaster.sections));
      }
    }

    const masterTpl = getMasterPoTemplate();
    if (masterTpl && Array.isArray(masterTpl.sections) && masterTpl.sections.length > 0) {
      const clonedSecs = JSON.parse(JSON.stringify(masterTpl.sections));
      const scopeSec = clonedSecs.find(s => s && (s.type === 'scope' || (s.type === 'custom' && (s.title || '').toLowerCase() === 'summary')));
      const leadNoteText = po?.scope !== undefined ? po.scope : (lead?.notes ? String(lead.notes).split('\n\n---\n\n')[0] : '');
      if (scopeSec && (!scopeSec.content || !String(scopeSec.content).replace(/<[^>]*>/g, '').trim()) && leadNoteText) {
        scopeSec.content = leadNoteText;
      }
      return clonedSecs;
    }

    return [
      {
        id: 'sec_header',
        type: 'header',
        title: 'Document Header'
      },
      {
        id: 'sec_overview',
        type: 'overview',
        title: 'Client & Project Details'
      },
      {
        id: 'sec_div_overview',
        type: 'divider',
        title: 'Divider Line',
        content: ''
      },
      {
        id: 'sec_custom_summary',
        type: 'custom',
        title: 'summary',
        pageBreakBefore: false,
        content: po?.scope !== undefined ? po.scope : (lead?.notes ? String(lead.notes).split('\n\n---\n\n')[0] : '')
      },
      {
        id: 'sec_deliverables',
        type: 'deliverables',
        title: 'Deliverables & Investment',
        pageBreakBefore: false
      },
      {
        id: 'sec_timeline',
        type: 'timeline',
        title: 'Project Timeline & Delivery',
        pageBreakBefore: false,
        content: po?.timeline || ''
      },
      {
        id: 'sec_conditions',
        type: 'conditions',
        title: 'Terms & Conditions',
        pageBreakBefore: false,
        content: po?.conditions || ''
      },
      {
        id: 'sec_acceptance',
        type: 'acceptance',
        title: '',
        clientTitle: 'Authorized Client Signature',
        providerTitle: 'Service Provider Signature',
        pageBreakBefore: false,
        signSealText: 'Signature & Seal',
        signDateText: 'Date: _________________',
        signNameText: 'Name: _________________',
        signSealProviderText: 'Signature & Seal',
        signDateProviderText: 'Date: _________________',
        signNameProviderText: 'Name: _________________'
      }
    ];
  }

  // ==========================================
  // GOOGLE DOCS STYLE PAGINATION (real consecutive A4 pages on screen)
  // ==========================================
  const PO_PAGE_GAP_PX = 28;
  let poPaginateTimer = null;

  // Kept for backwards compatibility: every caller now triggers real pagination
  function updatePoVisualPageBreakGuides() {
    if (poPaginateTimer) return;
    const raf = (typeof window !== 'undefined' && window.requestAnimationFrame) ? window.requestAnimationFrame.bind(window) : (fn) => setTimeout(fn, 16);
    poPaginateTimer = raf(() => {
      poPaginateTimer = null;
      paginatePoDocument();
    });
  }

  const PO_MM_PX = 96 / 25.4;              // CSS px per millimetre
  const PO_PAGE_W_PX = 210 * PO_MM_PX;      // A4 width
  const PO_PAGE_H_PX = 297 * PO_MM_PX;      // A4 height
  let poPrintLayoutActive = false;          // true while the document is laid out for PDF/print

  // Normalizes .po-section-content so every line is a direct block <div> child (unwrapping multi-line inline spans)
  function normalizePoSectionContentDom(contentEl, opts = {}) {
    if (!contentEl) return;
    let guard = 0;
    while (guard++ < 60) {
      const inlineWithBlocks = Array.from(contentEl.querySelectorAll('span, font, b, strong, i, em, u')).filter(el => el.querySelector('div, p'));
      if (inlineWithBlocks.length === 0) break;
      const target = inlineWithBlocks[inlineWithBlocks.length - 1];
      const parent = target.parentNode;
      if (!parent) break;
      const children = Array.from(target.childNodes);
      children.forEach(node => {
        if (node.nodeType === 1 && (node.tagName === 'DIV' || node.tagName === 'P')) {
          const hasText = (node.textContent || '').trim().length > 0;
          const hasBr = !!node.querySelector('br');
          if (!hasText && !hasBr) return;
          const wrapper = target.cloneNode(false);
          wrapper.removeAttribute('id');
          while (node.firstChild) wrapper.appendChild(node.firstChild);
          node.appendChild(wrapper);
          parent.insertBefore(node, target);
        } else if (
          (node.nodeType === 3 && (node.nodeValue || '').trim().length > 0) ||
          (node.nodeType === 1 && (node.tagName === 'BR' || (node.textContent || '').trim().length > 0 || (node.querySelector && node.querySelector('br'))))
        ) {
          const wrapper = target.cloneNode(false);
          wrapper.removeAttribute('id');
          wrapper.appendChild(node);
          if (parent === contentEl) {
            const div = document.createElement('div');
            div.appendChild(wrapper);
            parent.insertBefore(div, target);
          } else {
            parent.insertBefore(wrapper, target);
          }
        }
      });
      target.remove();
    }

    // Ensure direct inline nodes mixed with block <div> children are wrapped in their own <div>
    if (contentEl.querySelector('div, p')) {
      const directNodes = Array.from(contentEl.childNodes);
      let inlineRun = [];
      const flushRun = (beforeNode) => {
        if (inlineRun.length === 0) return;
        const hasContent = inlineRun.some(n =>
          (n.nodeType === 3 && (n.nodeValue || '').trim().length > 0) ||
          (n.nodeType === 1 && (n.tagName === 'BR' || (n.textContent || '').trim().length > 0 || (n.querySelector && n.querySelector('br'))))
        );
        if (hasContent) {
          const d = document.createElement('div');
          inlineRun.forEach(n => d.appendChild(n));
          contentEl.insertBefore(d, beforeNode);
        } else {
          inlineRun.forEach(n => n.remove());
        }
        inlineRun = [];
      };
      directNodes.forEach(n => {
        if (n.nodeType === 1 && (n.tagName === 'DIV' || n.tagName === 'P')) {
          flushRun(n);
        } else {
          inlineRun.push(n);
        }
      });
      flushRun(null);
    }

    // Flatten redundant single-child nested spans (<span style="..."><span style="...">...</span></span>)
    Array.from(contentEl.querySelectorAll('span')).forEach(sp => {
      if (!sp.parentNode) return;
      while (
        sp.childNodes.length === 1 &&
        sp.firstElementChild &&
        sp.firstElementChild.tagName === 'SPAN' &&
        !sp.firstElementChild.getAttribute('data-po-push')
      ) {
        const inner = sp.firstElementChild;
        const innerStyle = inner.getAttribute('style') || '';
        if (innerStyle) {
          innerStyle.split(';').forEach(rule => {
            const colon = rule.indexOf(':');
            if (colon > 0) {
              const p = rule.slice(0, colon).trim();
              const v = rule.slice(colon + 1).trim();
              if (p && v) sp.style.setProperty(p, v.replace(/\s*!important\s*$/i, ''));
            }
          });
        }
        if (inner.classList.contains('po-active-word-mark')) sp.classList.add('po-active-word-mark');
        while (inner.firstChild) sp.insertBefore(inner.firstChild, inner);
        inner.remove();
      }
    });

    const isFocusedHere = (typeof document !== 'undefined' && document.activeElement === contentEl);
    const directBlocks = Array.from(contentEl.children).filter(ch => ch.tagName === 'DIV' || ch.tagName === 'P');
    let consecutiveBlanks = 0;
    directBlocks.forEach(d => {
      const txt = (d.textContent || '').replace(/\u200B/g, '').trim();
      const hasBr = !!d.querySelector('br');
      // Remove empty non-br artifact divs (e.g. <div><b></b></div>) or stray manual gap-jumper "\" div
      if ((!txt && !hasBr) || txt === '\\') {
        d.remove();
        return;
      }
      if (!txt && hasBr) {
        consecutiveBlanks++;
        const maxBlanks = isFocusedHere ? 2 : 1;
        if (consecutiveBlanks > maxBlanks) {
          d.remove();
        }
      } else {
        consecutiveBlanks = 0;
      }
    });

    if (!isFocusedHere && !opts.preserveActiveMarks) {
      while (contentEl.firstElementChild && (contentEl.firstElementChild.textContent || '').trim() === '' && contentEl.children.length > 1) {
        contentEl.firstElementChild.remove();
      }
      while (contentEl.lastElementChild && (contentEl.lastElementChild.textContent || '').trim() === '' && contentEl.children.length > 1) {
        contentEl.lastElementChild.remove();
      }
    }
  }

  // Removes transient pagination markers and active word highlights so they never get saved into the document
  function poCleanContentHtml(el) {
    if (!el) return '';
    const clone = el.cloneNode(true);
    clone.querySelectorAll('[data-po-push]').forEach(n => {
      n.style.removeProperty('padding-top');
      n.style.removeProperty('break-before');
      n.style.removeProperty('display');
      n.removeAttribute('data-po-push');
      if (!n.getAttribute('style')) n.removeAttribute('style');
    });
    clone.querySelectorAll('.po-active-word-mark').forEach(n => {
      n.classList.remove('po-active-word-mark');
      if (!n.getAttribute('class')) n.removeAttribute('class');
    });
    if (el.classList && el.classList.contains('po-section-content')) {
      normalizePoSectionContentDom(clone);
    }
    return clone.innerHTML;
  }

  // Lines inside a block that may move to the next page on their own (Google Docs style flow)
  function poBlockLines(block) {
    const lines = [];
    const content = block.querySelector('.po-section-content');
    if (content) {
      const isFocusedInside = (typeof document !== 'undefined' && document.activeElement && (document.activeElement === content || content.contains(document.activeElement)));
      const sel = (typeof window !== 'undefined' && window.getSelection) ? window.getSelection() : null;
      const hasLiveSelectionInside = sel && sel.rangeCount > 0 && content.contains(sel.getRangeAt(0).commonAncestorContainer);
      if ((!isFocusedInside && !hasLiveSelectionInside) || poPrintLayoutActive) {
        normalizePoSectionContentDom(content, { preserveActiveMarks: true });
      }
      Array.from(content.children).forEach(ch => lines.push({ el: ch, kind: 'margin' }));
    }
    const tbody = block.querySelector('#poItemsTableBody');
    if (tbody) {
      Array.from(tbody.children).forEach(tr => {
        if (tr.tagName === 'TR' && !tr.classList.contains('po-row-spacer')) lines.push({ el: tr, kind: 'row' });
      });
      const totals = block.querySelector('[data-elem-id^="totals_"]');
      if (totals) lines.push({ el: totals, kind: 'margin' });
    }
    const sigs = block.querySelector('.po-signatures-grid');
    if (sigs) lines.push({ el: sigs, kind: 'margin' });
    return lines;
  }

  let poScrollBeforePrint = null;
  function capturePoScrollPositions() {
    const vp = document.getElementById('poCanvasViewport');
    const page = document.getElementById('priceOfferingDocPage');
    const mainEl = document.querySelector('main');
    return {
      vpTop: vp ? vp.scrollTop : 0,
      vpLeft: vp ? vp.scrollLeft : 0,
      pageTop: page ? page.scrollTop : 0,
      mainTop: mainEl ? mainEl.scrollTop : 0,
      winY: typeof window.scrollY === 'number' ? window.scrollY : 0
    };
  }

  function restorePoScrollPositions(saved) {
    if (!saved) return;
    const vp = document.getElementById('poCanvasViewport');
    if (vp) {
      vp.scrollTop = saved.vpTop;
      vp.scrollLeft = saved.vpLeft;
    }
    const page = document.getElementById('priceOfferingDocPage');
    if (page) page.scrollTop = saved.pageTop;
    const mainEl = document.querySelector('main');
    if (mainEl) mainEl.scrollTop = saved.mainTop;
    if (typeof window.scrollTo === 'function' && saved.winY) {
      window.scrollTo(0, saved.winY);
    }
  }

  function paginatePoDocument() {
    const sheet = document.getElementById('priceOfferingSheet');
    const flow = document.getElementById('poSectionsFlowContainer');
    const area = document.getElementById('priceOfferingPrintArea');
    if (!sheet || !flow || !sheet.offsetWidth || typeof window.getComputedStyle !== 'function') return;

    const savedScroll = capturePoScrollPositions();
    if (area && !poPrintLayoutActive && area.offsetHeight > 0) {
      area.style.minHeight = area.offsetHeight + 'px';
    }

    // 1. Reset previous pagination
    sheet.querySelectorAll('.po-page-spacer, .po-row-spacer').forEach(el => el.remove());
    sheet.querySelectorAll('[data-po-push]').forEach(el => {
      el.style.removeProperty('padding-top');
      el.style.removeProperty('break-before');
      el.style.removeProperty('display');
      el.removeAttribute('data-po-push');
      if (!el.getAttribute('style')) el.removeAttribute('style');
    });
    sheet.querySelectorAll('.po-last-block').forEach(el => el.classList.remove('po-last-block'));
    sheet.style.height = '';

    const gap = poPrintLayoutActive ? 0 : PO_PAGE_GAP_PX;
    const cs = window.getComputedStyle(sheet);
    const padTop = parseFloat(cs.paddingTop) || 0;
    const padBottom = parseFloat(cs.paddingBottom) || 0;
    const pageH = PO_PAGE_H_PX;
    const stride = pageH + gap;
    const contentH = pageH - padTop - padBottom;
    const EPS = 0.5;

    // Measurements are taken in visual px and converted back to unzoomed document px
    const z = (sheet.getBoundingClientRect().width / PO_PAGE_W_PX) || 1;
    const measure = (el) => {
      const sTop = sheet.getBoundingClientRect().top;
      const r = el.getBoundingClientRect();
      return { top: (r.top - sTop) / z, h: r.height / z };
    };
    const pageOf = (y) => Math.max(0, Math.floor(y / stride));
    const nextContentTop = (y) => (pageOf(y) + 1) * stride + padTop;

    // Where must something starting at `top` with height `h` move to? (0 = stays)
    const shiftFor = (top, h) => {
      const page = pageOf(top);
      const cTop = page * stride + padTop;
      const cBottom = page * stride + pageH - padBottom;
      if (top >= cBottom - EPS) return nextContentTop(top) - top;          // starts in bottom margin / gap
      if (page > 0 && top < cTop - EPS) return cTop - top;                  // starts in top margin
      if (top + h > cBottom + EPS && h <= contentH) return nextContentTop(top) - top; // would be cut
      return 0;
    };

    // Every push is recorded so the print layout can turn "moves to next page" into a real page break
    // (Chrome truncates margins at page breaks, so plain spacing would drift in the PDF).
    const pushes = [];
    const isPageMove = (top, px) => pageOf(top + px) > pageOf(top);

    const insertSpacer = (before, px, top) => {
      const spacer = document.createElement('div');
      spacer.className = 'po-page-spacer';
      spacer.style.height = px + 'px';
      before.parentNode.insertBefore(spacer, before);
      pushes.push({ kind: 'spacer', el: spacer, move: isPageMove(top, px) });
    };

    const pushLine = (line, px, top) => {
      if (line.kind === 'row') {
        const tr = document.createElement('tr');
        tr.className = 'po-row-spacer';
        tr.innerHTML = `<td colspan="5" style="height:${px}px;padding:0;border:0;"></td>`;
        line.el.parentNode.insertBefore(tr, line.el);
        pushes.push({ kind: 'row', el: tr, move: isPageMove(top, px) });
      } else {
        const base = parseFloat(window.getComputedStyle(line.el).paddingTop) || 0;
        line.el.style.setProperty('display', 'block');
        line.el.style.setProperty('padding-top', (base + px) + 'px');
        line.el.setAttribute('data-po-push', String(base));
        pushes.push({ kind: 'pad', el: line.el, base, move: isPageMove(top, px) });
      }
    };

    const blocks = Array.from(flow.children).filter(el => el.classList.contains('po-section'));
    let lastBottom = padTop;

    blocks.forEach(block => {
      const lines = poBlockLines(block);
      let { top, h } = measure(block);
      const page = pageOf(top);
      const cTop = page * stride + padTop;
      const cBottom = page * stride + pageH - padBottom;

      if (lines.length === 0) {
        const sh = shiftFor(top, h);
        if (sh > 0) insertSpacer(block, sh, top);
      } else {
        // 1. Check if the section header + very first line need to move together to the next page
        const first = measure(lines[0].el);
        const headerAndFirstH = (first.top + first.h) - top;
        let blockStartShift = 0;
        if (page > 0 && top < cTop - EPS) {
          blockStartShift = cTop - top;
        } else if (top >= cBottom - EPS || (first.top + first.h > cBottom + EPS && headerAndFirstH <= contentH)) {
          blockStartShift = nextContentTop(top) - top;
        }
        if (blockStartShift > 0) {
          insertSpacer(block, blockStartShift, top);
        }

        // 2. Flow all lines inside the block across page boundaries (even if the block was shifted or spans multiple pages)
        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          const m = measure(line.el);
          let sh = shiftFor(m.top, m.h);

          // If a blank spacer line (<br>) would get pushed across a page break in print layout, collapse it so the next page starts cleanly at padTop
          if (sh > 0 && line.kind === 'margin' && poPrintLayoutActive && (line.el.textContent || '').trim() === '') {
            line.el.setAttribute('data-po-push', '0');
            line.el.style.setProperty('display', 'none');
            continue;
          }

          // Keep bold subheadings (e.g. "2019–2022 — Private Instructor...") together with their first bullet line
          if (sh === 0 && line.kind === 'margin' && i + 1 < lines.length) {
            const txt = (line.el.textContent || '').trim();
            if (txt.length > 0 && txt.length < 150 && !/^[•\-*]/.test(txt)) {
              const boldEl = line.el.querySelector('b, strong');
              const boldTxt = boldEl ? (boldEl.textContent || '').trim() : '';
              const fw = parseInt(window.getComputedStyle(line.el).fontWeight, 10) || 400;
              const isSubheading = (boldTxt.length > 0 && boldTxt.length >= txt.length * 0.7) || fw >= 600;
              if (isSubheading) {
                const mNext = measure(lines[i + 1].el);
                const linePage = pageOf(m.top);
                const lineCBottom = linePage * stride + pageH - padBottom;
                if (mNext.top >= lineCBottom - EPS || mNext.top + mNext.h > lineCBottom + EPS) {
                  sh = nextContentTop(m.top) - m.top;
                }
              }
            }
          }

          if (sh > 0) {
            pushLine(line, sh, m.top);
          }
        }
      }
      const after = measure(block);
      lastBottom = after.top + after.h;
    });

    const totalPages = Math.max(1, Math.floor((lastBottom + padBottom - 1) / stride) + 1);
    poCurrentPageCount = totalPages;
    if (blocks.length) blocks[blocks.length - 1].classList.add('po-last-block');

    if (!poPrintLayoutActive) {
      sheet.style.height = (totalPages * stride - gap) + 'px';
    } else {
      // Convert page moves into forced page breaks that start exactly at the top page margin
      pushes.forEach(pu => {
        if (!pu.move) return;
        if (pu.kind === 'spacer') {
          pu.el.style.height = padTop + 'px';
          pu.el.style.setProperty('break-before', 'page');
        } else if (pu.kind === 'row') {
          pu.el.style.setProperty('break-before', 'page');
          const td = pu.el.querySelector('td');
          if (td) td.style.height = padTop + 'px';
        } else {
          pu.el.style.setProperty('padding-top', (pu.base + padTop) + 'px');
          pu.el.style.setProperty('break-before', 'page');
        }
      });
    }

    let bgLayer = sheet.querySelector('.po-page-bg-layer');
    if (!bgLayer) {
      bgLayer = document.createElement('div');
      bgLayer.className = 'po-page-bg-layer no-print';
      sheet.insertBefore(bgLayer, sheet.firstChild);
    }
    let bgHtml = '';
    for (let p = 0; p < totalPages; p++) {
      bgHtml += `
        <div class="po-page-bg" style="top:${p * stride}px;height:${pageH}px;">
          <div class="po-page-bg-number" style="bottom:${Math.max(10, Math.round(padBottom / 2) - 6)}px;">Page ${p + 1} of ${totalPages}</div>
        </div>`;
    }
    bgLayer.innerHTML = bgHtml;
    syncPoZoomBox();
    if (area) area.style.minHeight = '';
    updatePoZoomUI();

    if (!poPrintLayoutActive) {
      restorePoScrollPositions(savedScroll);
    }
  }

  // ==========================================
  // ZOOM (view only – never affects the PDF)
  // ==========================================
  const PO_ZOOM_STEPS = [0.25, 0.33, 0.5, 0.67, 0.75, 0.85, 1, 1.1, 1.25, 1.5, 1.75, 2, 2.5, 3];
  let poZoom = (() => {
    try {
      const z = parseFloat(localStorage.getItem('ft_po_zoom'));
      return (z >= 0.25 && z <= 3) ? z : 1;
    } catch (e) { return 1; }
  })();
  let poCurrentPageCount = 1;

  // Size the print area to the scaled sheet (transform scaling doesn't affect layout size)
  function syncPoZoomBox() {
    const area = document.getElementById('priceOfferingPrintArea');
    const sheet = document.getElementById('priceOfferingSheet');
    if (!area || !sheet) return;
    area.classList.add('po-zoom-box');
    if (poPrintLayoutActive) return;
    area.style.width = (PO_PAGE_W_PX * poZoom) + 'px';
    area.style.height = (sheet.offsetHeight * poZoom) + 'px';
  }

  function updatePoZoomUI() {
    const label = document.getElementById('poZoomLabel');
    if (label) label.textContent = Math.round(poZoom * 100) + '%';
    const pages = document.getElementById('poPageCountLabel');
    if (pages) pages.textContent = poCurrentPageCount === 1 ? '1 page' : `${poCurrentPageCount} pages`;
  }

  function setPoZoom(z, anchor) {
    z = Math.min(3, Math.max(0.25, Math.round(z * 100) / 100));
    const viewport = document.getElementById('poCanvasViewport');
    const old = poZoom;
    let ax = 0.5, ay = 0, docX = 0, docY = 0;
    if (viewport) {
      const vr = viewport.getBoundingClientRect();
      ax = anchor ? (anchor.x - vr.left) / vr.width : 0.5;
      ay = anchor ? (anchor.y - vr.top) / vr.height : 0.5;
      docX = (viewport.scrollLeft + ax * viewport.clientWidth) / old;
      docY = (viewport.scrollTop + ay * viewport.clientHeight) / old;
    }
    poZoom = z;
    document.documentElement.style.setProperty('--po-zoom', String(z));
    try { localStorage.setItem('ft_po_zoom', String(z)); } catch (e) {}
    syncPoZoomBox();
    if (viewport) {
      viewport.scrollLeft = Math.max(0, docX * z - ax * viewport.clientWidth);
      viewport.scrollTop = Math.max(0, docY * z - ay * viewport.clientHeight);
    }
    updatePoZoomUI();
    closePoZoomMenu();
  }

  function stepPoZoom(dir, anchor) {
    const cur = poZoom;
    let next;
    if (dir > 0) next = PO_ZOOM_STEPS.find(s => s > cur + 0.001) || 3;
    else next = [...PO_ZOOM_STEPS].reverse().find(s => s < cur - 0.001) || 0.25;
    setPoZoom(next, anchor);
  }

  function fitPoZoom(mode) {
    const viewport = document.getElementById('poCanvasViewport');
    if (!viewport) return;
    const availW = viewport.clientWidth - 112;  // room for drag handles on both sides
    const availH = viewport.clientHeight - 64;
    let z = availW / PO_PAGE_W_PX;
    if (mode === 'page') z = Math.min(z, availH / PO_PAGE_H_PX);
    setPoZoom(z);
    viewport.scrollTop = 0;
  }

  function closePoZoomMenu() {
    document.getElementById('poZoomMenu')?.classList.add('hidden');
  }

  // Lay the document out exactly as it will print (zoom 1, no page gaps) and restore afterwards
  let poZoomBeforePrint = null;
  function preparePoPrintLayout() {
    if (poPrintLayoutActive) return;
    if (!document.getElementById('priceOfferingSheet')) return;
    poScrollBeforePrint = capturePoScrollPositions();
    poZoomBeforePrint = poZoom;
    document.documentElement.style.setProperty('--po-zoom', '1');
    poPrintLayoutActive = true;
    document.body.classList.add('po-print-layout');
    // Adjust signatures on Page 2+ so removing the 28px screen page gap doesn't shift them down in print/PDF
    const screenStridePx = PO_PAGE_H_PX + PO_PAGE_GAP_PX;
    const gapMm = PO_PAGE_GAP_PX * 25.4 / 96;
    document.querySelectorAll('#poSignaturesLayer .po-signature-vector').forEach(sigEl => {
      const sigId = sigEl.getAttribute('data-sig-id');
      const sigObj = (currentPoSignatures || []).find(s => s && s.id === sigId);
      const yMm = sigObj ? (Number(sigObj.yMm) || 0) : (parseFloat(sigEl.style.top) || 0);
      const yPx = yMm * 96 / 25.4;
      const pageIdx = Math.max(0, Math.floor(yPx / screenStridePx));
      if (pageIdx >= 1) {
        sigEl.style.top = `${+(yMm - pageIdx * gapMm).toFixed(2)}mm`;
      }
    });
    paginatePoDocument();
  }

  function restorePoScreenLayout() {
    if (!poPrintLayoutActive) return;
    const savedScroll = poScrollBeforePrint;
    poScrollBeforePrint = null;
    poPrintLayoutActive = false;
    document.body.classList.remove('po-print-layout');
    document.documentElement.style.setProperty('--po-zoom', String(poZoomBeforePrint || poZoom));
    document.querySelectorAll('#poSignaturesLayer .po-signature-vector').forEach(sigEl => {
      const sigId = sigEl.getAttribute('data-sig-id');
      const sigObj = (currentPoSignatures || []).find(s => s && s.id === sigId);
      if (sigObj && sigObj.yMm !== undefined) {
        sigEl.style.top = `${Number(sigObj.yMm)}mm`;
      }
    });
    paginatePoDocument();
    if (savedScroll) {
      restorePoScrollPositions(savedScroll);
      requestAnimationFrame(() => restorePoScrollPositions(savedScroll));
    }
  }

  if (typeof window !== 'undefined') {
    document.documentElement && document.documentElement.style && document.documentElement.style.setProperty('--po-zoom', String(poZoom));
    window.poPrintPreview = { prepare: preparePoPrintLayout, restore: restorePoScreenLayout };
  }

  // ==========================================
  // RICH TEXT FIELDS: every text on the page is a rich-text field (per-word fonts, sizes, colors…)
  // Inputs are rendered as before and then converted in place, keeping ids / classes / data-* so the
  // whole document keeps its exact look. Each field exposes .value / .select() like an input did,
  // so all existing save / totals / undo code keeps working. Formatting lives in poRichText.
  // ==========================================
  let poRichText = {};

  function poHtmlToText(html, multiline) {
    const tmp = document.createElement('div');
    tmp.innerHTML = html || '';
    if (!multiline) return (tmp.textContent || '').replace(/\u00a0/g, ' ');
    let out = '';
    const walk = (node, isFirst) => {
      node.childNodes.forEach((ch, i) => {
        if (ch.nodeType === 3) out += ch.nodeValue;
        else if (ch.nodeName === 'BR') out += '\n';
        else {
          const block = /^(DIV|P|LI)$/.test(ch.nodeName);
          if (block && out && !out.endsWith('\n')) out += '\n';
          walk(ch, false);
        }
      });
    };
    walk(tmp, true);
    return out.replace(/\u00a0/g, ' ').replace(/\n$/, '');
  }

  function poTextToHtml(text, multiline) {
    const t = String(text == null ? '' : text);
    if (!multiline) return escapeHtml(t);
    return t.split('\n').map(escapeHtml).join('<br>');
  }

  function poFieldText(el) {
    return poHtmlToText(el.innerHTML, el.getAttribute('data-multiline') === '1');
  }

  function poRememberRichText(el) {
    const id = el.getAttribute('data-elem-id');
    if (!id) return;
    if (el.innerHTML === '<br>' || el.textContent === '') {
      if (el.innerHTML !== '') el.innerHTML = '';
      delete poRichText[id];
      return;
    }
    const html = poCleanContentHtml(el);
    if (/<(?!br\s*\/?>)[a-z]/i.test(html)) poRichText[id] = html;   // only keep real formatting
    else delete poRichText[id];
  }

  function poWrapTextWithRichStyle(templateRichHtml, plainText, multiline) {
    const innerHtml = poTextToHtml(plainText, multiline);
    if (!templateRichHtml) return innerHtml;
    const probe = document.createElement('div');
    probe.innerHTML = templateRichHtml;
    const wrappers = [];
    let cur = probe;
    while (
      cur.children &&
      cur.children.length === 1 &&
      /^(FONT|SPAN|B|STRONG|I|EM|U)$/i.test(cur.children[0].tagName)
    ) {
      const child = cur.children[0];
      const clone = child.cloneNode(false);
      wrappers.push(clone);
      cur = child;
    }
    if (wrappers.length === 0) return innerHtml;
    for (let i = 0; i < wrappers.length - 1; i++) {
      wrappers[i].appendChild(wrappers[i + 1]);
    }
    wrappers[wrappers.length - 1].innerHTML = innerHtml;
    const out = document.createElement('div');
    out.appendChild(wrappers[0]);
    return out.innerHTML;
  }

  function poSyncElementStyleFromWrapperChain(id, richHtml) {
    if (!id || !richHtml) return;
    const probe = document.createElement('div');
    probe.innerHTML = richHtml;
    const fullText = (probe.textContent || '').trim();
    if (!fullText) return;
    let cur = probe;
    const chain = [];
    while (
      cur.children &&
      cur.children.length === 1 &&
      /^(FONT|SPAN|B|STRONG|I|EM|U)$/i.test(cur.children[0].tagName) &&
      (cur.children[0].textContent || '').trim() === fullText
    ) {
      cur = cur.children[0];
      chain.push(cur);
    }
    if (chain.length === 0) return;
    if (!poElementStyles[id]) poElementStyles[id] = {};
    chain.forEach(node => {
      const face = node.getAttribute && node.getAttribute('face');
      if (face) poElementStyles[id].fontFamily = face;
      if (node.style) {
        if (node.style.fontFamily) poElementStyles[id].fontFamily = node.style.fontFamily;
        if (node.style.fontSize) {
          const fs = parseFloat(node.style.fontSize);
          if (!isNaN(fs) && fs > 0) poElementStyles[id].fontSize = fs;
        }
        if (node.style.fontWeight) poElementStyles[id].fontWeight = node.style.fontWeight;
      }
    });
  }

  function poRenderRichFieldHtml(id, value, multiline) {
    let rich = id ? poRichText[id] : null;
    if (rich) {
      poSyncElementStyleFromWrapperChain(id, rich);
      const richPlain = poHtmlToText(rich, multiline);
      if (richPlain === value) return rich;
      const normalizeWs = (s) => String(s || '').replace(/\s+/g, ' ').trim();
      if (normalizeWs(richPlain) === normalizeWs(value)) {
        return rich;
      }
      const wrapped = poWrapTextWithRichStyle(rich, value, multiline);
      if (wrapped !== poTextToHtml(value, multiline) && id) {
        poRichText[id] = wrapped;
        return wrapped;
      }
    }
    // If this is a deliverable description row (item_desc_N where N > 0) with no rich styling yet, inherit row 0's outer style wrapper & element style so all deliverable rows share consistent typography
    const descMatch = id && id.match(/^item_desc_(\d+)$/);
    if (descMatch) {
      const idx = parseInt(descMatch[1], 10);
      if (idx > 0 && !rich) {
        if (poRichText['item_desc_0']) {
          poSyncElementStyleFromWrapperChain('item_desc_0', poRichText['item_desc_0']);
        }
        if (poElementStyles['item_desc_0']) {
          if (!poElementStyles[id]) poElementStyles[id] = {};
          const typoProps = ['fontFamily', 'fontSize', 'fontWeight', 'fontStyle', 'textDecoration', 'color', 'lineHeight', 'letterSpacing', 'textTransform', 'textAlign', 'textScaleY'];
          typoProps.forEach(p => {
            if (poElementStyles['item_desc_0'][p] !== undefined && poElementStyles[id][p] === undefined) {
              poElementStyles[id][p] = poElementStyles['item_desc_0'][p];
            }
          });
        }
        if (poRichText['item_desc_0']) {
          const inherited = poWrapTextWithRichStyle(poRichText['item_desc_0'], value, multiline);
          if (inherited !== poTextToHtml(value, multiline)) {
            poRichText[id] = inherited;
            return inherited;
          }
        }
      }
    }
    return poTextToHtml(value, multiline);
  }

  function poInstallFieldApi(el) {
    if (el.__poField) return;
    el.__poField = true;
    Object.defineProperty(el, 'value', {
      configurable: true,
      get() { return poFieldText(el); },
      set(v) {
        const next = String(v == null ? '' : v);
        const curText = poFieldText(el);
        const normalizeWs = (s) => String(s || '').replace(/\s+/g, ' ').trim();
        if (curText === next || normalizeWs(curText) === normalizeWs(next)) return;
        const id = el.getAttribute('data-elem-id');
        const multiline = el.getAttribute('data-multiline') === '1';
        const existingRich = id ? poRichText[id] : null;
        if (existingRich) {
          const wrapped = poWrapTextWithRichStyle(existingRich, next, multiline);
          el.innerHTML = wrapped;
          poRememberRichText(el);
        } else {
          el.innerHTML = poTextToHtml(next, multiline);
          if (id) delete poRichText[id];
        }
      }
    });
    el.select = () => {
      const r = document.createRange();
      r.selectNodeContents(el);
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(r);
    };
  }

  // Readable names for elements that never had one
  const PO_FIELD_NAMES = {
    'po-client-sign-title': 'Client Signature Title',
    'po-provider-sign-title': 'Provider Signature Title',
    'po-sign-seal-label': 'Client Signature Line',
    'po-sign-date-label': 'Client Date Line',
    'po-sign-name-label': 'Client Name Line',
    'po-sign-seal-provider-label': 'Provider Signature Line',
    'po-sign-date-provider-label': 'Provider Date Line',
    'po-sign-name-provider-label': 'Provider Name Line'
  };

  function poConvertInputsToFields(root) {
    if (!root) return;
    const inputs = root.querySelectorAll('input[type="text"], input[type="number"].po-item-qty, input[type="number"].po-item-rate, textarea.po-item-desc');
    inputs.forEach(inp => {
      const multiline = inp.tagName === 'TEXTAREA';
      const div = document.createElement('div');
      Array.from(inp.attributes).forEach(a => {
        if (['type', 'value', 'placeholder', 'rows', 'step', 'min', 'max'].includes(a.name)) return;
        div.setAttribute(a.name, a.value);
      });
      div.classList.add('po-field');
      if (multiline) div.setAttribute('data-multiline', '1');
      const cs = window.getComputedStyle(inp);
      if (cs.display === 'inline-block' && (inp.classList.contains('po-item-qty') || inp.classList.contains('po-item-rate'))) {
        div.classList.add('po-field-inline');
      }
      div.setAttribute('contenteditable', 'true');
      div.setAttribute('spellcheck', 'false');
      div.setAttribute('data-placeholder', inp.getAttribute('placeholder') || '');

      // Stable ids for elements that weren't individually selectable yet
      if (!div.getAttribute('data-elem-id')) {
        const idx = inp.getAttribute('data-index');
        const secId = inp.getAttribute('data-sec-id');
        let id = null, name = null;
        if (inp.classList.contains('po-item-qty')) { id = `item_qty_${idx}`; name = `Item ${+idx + 1} Qty`; }
        else if (inp.classList.contains('po-item-rate')) { id = `item_rate_${idx}`; name = `Item ${+idx + 1} Rate`; }
        else {
          const key = Object.keys(PO_FIELD_NAMES).find(k => inp.classList.contains(k));
          if (key) { id = `${key}_${secId || ''}`; name = PO_FIELD_NAMES[key]; }
        }
        if (id) {
          div.setAttribute('data-elem-id', id);
          div.setAttribute('data-elem-name', name);
          div.setAttribute('data-elem-type', 'text');
          div.classList.add('po-selectable');
        }
      }

      const value = inp.value;
      const id = div.getAttribute('data-elem-id');
      div.innerHTML = poRenderRichFieldHtml(id, value, multiline);
      inp.replaceWith(div);
      poInstallFieldApi(div);
    });
    root.querySelectorAll('.po-field').forEach(poInstallFieldApi);
  }

  // Inputs grew to fit large fonts; plain blocks don't. Keep identical metrics when a font is larger than its line height.
  function poFitFieldMetrics(root) {
    (root || document).querySelectorAll('#priceOfferingPrintArea .po-field').forEach(el => {
      const elemId = el.getAttribute('data-elem-id');
      if (elemId && poElementStyles[elemId] && poElementStyles[elemId].lineHeight) return;
      el.style.removeProperty('line-height');
      const cs = window.getComputedStyle(el);
      const fs = parseFloat(cs.fontSize) || 0;
      const lh = parseFloat(cs.lineHeight);
      if (fs && lh && fs * 1.2 > lh + 0.5) el.style.setProperty('line-height', 'normal', 'important');
    });
  }

  function formatInitialContent(content) {
    if (!content) return '';
    if (content.includes('<') && (content.includes('</') || content.includes('<br'))) return content;
    return content.split('\n').map(line => {
      const trimmed = line.trim();
      if (!trimmed) return '<div><br></div>';
      return `<div>${escapeHtml(line)}</div>`;
    }).join('');
  }

  // No hover-only insertion pills between blocks on the document canvas
  function poInsertZoneHtml() {
    return '';
  }

  // Delete button (right gutter), shown on hover
  function poBlockChromeHtml(idx, canDelete, label) {
    return `
      ${canDelete ? `
      <button type="button" class="po-delete-section-direct-btn po-block-delete no-print" data-sec-index="${idx}" title="Delete ${escapeHtml(label)}">
        <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
      </button>` : ''}
    `;
  }

  function renderPoHeaderBlockHtml(ctx) {
    const { docTitle, docSubtitle, sender } = ctx;
    return `
      <div class="po-header-grid flex flex-col sm:flex-row sm:items-start justify-between gap-6" data-po-container="header_grid">
        <div class="space-y-1 flex-1 min-w-0" data-po-unit-id="header_col_left" data-po-container="header_left">
          <input type="text" id="poDocHeading" class="po-selectable po-doc-title-input text-2xl sm:text-3xl font-black text-slate-900 tracking-tight bg-transparent border-none outline-none rounded px-0 py-0.5 w-full transition-colors" data-elem-id="doc_heading" data-elem-name="Document Title" data-elem-type="text" value="${escapeHtml(docTitle)}" placeholder="PRICE QUOTE / PROPOSAL">
          <input type="text" id="poDocSubtitle" class="po-selectable text-xs font-semibold uppercase tracking-wider text-slate-400 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full transition-colors" data-elem-id="doc_subtitle" data-elem-name="Document Subtitle" data-elem-type="text" value="${escapeHtml(docSubtitle)}" placeholder="Add subtitle or project reference...">
        </div>
        <div class="text-left sm:text-right space-y-0.5 shrink-0 text-xs" data-po-unit-id="header_col_right" data-po-container="header_right">
          <input type="text" id="poSenderName" class="po-selectable font-bold text-slate-900 sm:text-right bg-transparent border-none outline-none rounded px-0 py-0.5 w-full sm:w-60 block sm:ml-auto transition-colors" data-elem-id="sender_name" data-elem-name="Sender Name" data-elem-type="text" value="${escapeHtml(sender.name || '')}" placeholder="Your Name / Studio">
          <input type="text" id="poSenderTitle" class="po-selectable text-slate-500 sm:text-right bg-transparent border-none outline-none rounded px-0 py-0.5 w-full sm:w-60 block sm:ml-auto text-[11px] transition-colors" data-elem-id="sender_title" data-elem-name="Sender Title" data-elem-type="text" value="${escapeHtml(sender.title || '')}" placeholder="Role / Discipline">
          <input type="text" id="poSenderContact" class="po-selectable text-slate-500 sm:text-right bg-transparent border-none outline-none rounded px-0 py-0.5 w-full sm:w-60 block sm:ml-auto text-[11px] transition-colors" data-elem-id="sender_contact" data-elem-name="Sender Contact" data-elem-type="text" value="${escapeHtml(sender.contact || '')}" placeholder="email@domain.com • +1 234 567">
          <input type="text" id="poSenderLocation" class="po-selectable text-slate-400 sm:text-right bg-transparent border-none outline-none rounded px-0 py-0.5 w-full sm:w-60 block sm:ml-auto text-[10px] transition-colors" data-elem-id="sender_location" data-elem-name="Sender Location" data-elem-type="text" value="${escapeHtml(sender.location || '')}" placeholder="City, Country">
        </div>
      </div>
    `;
  }

  function renderPoOverviewBlockHtml(ctx) {
    const { labels, client, clientEmail, clientAddress, refNo, cur, issueDate, validUntil } = ctx;
    const labelInput = (elemId, name, val, ph) => `<input type="text" class="po-selectable po-meta-label text-[10px] font-bold uppercase tracking-wider text-slate-400 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full transition-colors" data-elem-id="${elemId}" data-elem-name="${name}" data-elem-type="text" value="${escapeHtml(val)}" placeholder="${ph}">`;
    return `
      <div class="po-overview-grid grid grid-cols-1 sm:grid-cols-2 gap-8 text-xs" data-po-container="overview_grid">
        <div class="space-y-1 min-w-0" data-po-unit-id="overview_col_left" data-po-container="overview_left">
          ${labelInput('label_client', 'Client Label', labels.client, 'CLIENT / RECIPIENT')}
          <input type="text" id="poClientName" class="po-selectable font-bold text-slate-900 text-base bg-transparent border-none outline-none rounded px-0 py-0.5 w-full transition-colors" data-elem-id="client_name" data-elem-name="Client Name" data-elem-type="text" value="${escapeHtml(client)}" placeholder="Client Name / Organization">
          <input type="text" id="poClientEmail" class="po-selectable text-slate-600 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full text-xs transition-colors" data-elem-id="client_email" data-elem-name="Client Email" data-elem-type="text" value="${escapeHtml(clientEmail)}" placeholder="client@company.com">
          <input type="text" id="poClientAddress" class="po-selectable text-slate-500 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full text-[11px] transition-colors" data-elem-id="client_address" data-elem-name="Client Address" data-elem-type="text" value="${escapeHtml(clientAddress)}" placeholder="Billing Address / City / Tax ID">
        </div>
        <div class="grid grid-cols-2 gap-3 text-[11px] content-start" data-po-unit-id="overview_col_right" data-po-container="overview_right">
          <div class="po-meta-cell" data-po-unit-id="cell_ref" data-po-container="cell_ref">
            ${labelInput('label_ref', 'Reference Label', labels.reference, 'REFERENCE')}
            <input type="text" id="poRefNo" class="po-selectable font-mono font-semibold text-slate-800 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full transition-colors" data-elem-id="ref_no" data-elem-name="Reference Number" data-elem-type="text" value="${escapeHtml(refNo)}">
          </div>
          <div class="po-meta-cell" data-po-unit-id="cell_cur" data-po-container="cell_cur">
            ${labelInput('label_cur', 'Currency Label', labels.currency, 'CURRENCY')}
            <input type="text" id="poCurrencyInput" class="po-selectable font-bold text-slate-800 bg-transparent border-none outline-none rounded px-0 py-0.5 text-xs w-full uppercase transition-colors" data-elem-id="cur_input" data-elem-name="Currency Code" data-elem-type="text" value="${escapeHtml(cur)}" placeholder="EUR">
          </div>
          <div class="po-meta-cell" data-po-unit-id="cell_issue_date" data-po-container="cell_issue_date">
            ${labelInput('label_issue_date', 'Date Issued Label', labels.issueDate, 'DATE ISSUED')}
            <input type="text" id="poIssueDate" class="po-selectable text-slate-700 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full text-xs font-medium transition-colors" data-elem-id="issue_date_val" data-elem-name="Date Issued" data-elem-type="text" value="${escapeHtml(issueDate)}" placeholder="Date Issued">
          </div>
          <div class="po-meta-cell" data-po-unit-id="cell_valid_until" data-po-container="cell_valid_until">
            ${labelInput('label_valid_until', 'Valid Until Label', labels.validUntil, 'VALID UNTIL')}
            <input type="text" id="poValidUntil" class="po-selectable text-slate-700 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full text-xs font-medium transition-colors" data-elem-id="valid_until_val" data-elem-name="Valid Until Date" data-elem-type="text" value="${escapeHtml(validUntil)}" placeholder="Valid Until Date">
          </div>
        </div>
      </div>
    `;
  }

  function renderPoSectionHtml(sec, idx, totalSections, labels = {}, cur = 'EUR', ctx = {}) {
    const insertZoneBeforeHtml = poInsertZoneHtml(idx);
    const isSelected = poSelectedElementId === `sec_${sec.id}`;
    const selCls = isSelected ? 'po-selected-element' : '';
    const sid = escapeHtml(sec.id);

    if (sec.type === 'header' || sec.type === 'overview') {
      const label = sec.type === 'header' ? 'Document Header' : 'Client & Project Details';
      const inner = sec.type === 'header' ? renderPoHeaderBlockHtml(ctx) : renderPoOverviewBlockHtml(ctx);
      return `
        ${insertZoneBeforeHtml}
        <div class="po-section po-block-${sec.type} po-selectable ${selCls}" data-sec-id="${sid}" data-sec-index="${idx}" data-elem-id="sec_${sid}" data-elem-name="${label}" data-elem-type="${sec.type}">
          ${poBlockChromeHtml(idx, true, label)}
          ${inner}
        </div>
      `;
    }

    if (sec.type === 'divider') {
      return `
        ${insertZoneBeforeHtml}
        <div class="po-section po-divider-block po-selectable ${selCls}" data-sec-id="${sid}" data-sec-index="${idx}" data-elem-id="sec_${sid}" data-elem-name="Divider Line" data-elem-type="divider">
          ${poBlockChromeHtml(idx, true, 'Divider Line')}
          <div class="po-divider-line"></div>
        </div>
      `;
    }

    let bodyHtml = '';
    if (sec.type === 'deliverables') {
      bodyHtml = `
        <div class="po-selectable overflow-x-auto rounded-xl border border-slate-200 mt-2" data-elem-id="table_${sid}" data-elem-name="Pricing Table" data-elem-type="table">
          <table class="po-table w-full text-left border-collapse text-xs">
            <thead>
              <tr class="bg-slate-50 border-b border-slate-200 text-[11px] font-bold uppercase tracking-wider text-slate-500">
                <th class="po-col-desc py-2.5 px-3">
                  <input type="text" class="po-selectable po-th-label w-full text-[11px] font-bold uppercase tracking-wider text-slate-600 bg-transparent border-none outline-none rounded px-0 py-0.5 transition-colors" data-elem-id="th_desc" data-elem-name="Header: Description" data-elem-type="text" value="${escapeHtml(labels.thDesc || 'Deliverable / Description')}" placeholder="DELIVERABLE / DESCRIPTION">
                </th>
                <th class="po-col-qty py-2.5 px-3 text-center w-20">
                  <input type="text" class="po-selectable po-th-label w-full text-center text-[11px] font-bold uppercase tracking-wider text-slate-600 bg-transparent border-none outline-none rounded px-0 py-0.5 transition-colors" data-elem-id="th_qty" data-elem-name="Header: Qty" data-elem-type="text" value="${escapeHtml(labels.thQty || 'Qty')}" placeholder="QTY">
                </th>
                <th class="po-col-rate py-2.5 px-3 text-right w-28">
                  <input type="text" class="po-selectable po-th-label w-full text-right text-[11px] font-bold uppercase tracking-wider text-slate-600 bg-transparent border-none outline-none rounded px-0 py-0.5 transition-colors" data-elem-id="th_rate" data-elem-name="Header: Rate" data-elem-type="text" value="${escapeHtml(labels.thRate || 'Rate')}" placeholder="RATE">
                </th>
                <th class="po-col-amount py-2.5 px-3 text-right w-28">
                  <input type="text" class="po-selectable po-th-label w-full text-right text-[11px] font-bold uppercase tracking-wider text-slate-600 bg-transparent border-none outline-none rounded px-0 py-0.5 transition-colors" data-elem-id="th_amount" data-elem-name="Header: Amount" data-elem-type="text" value="${escapeHtml(labels.thAmount || 'Amount')}" placeholder="AMOUNT">
                </th>
                <th class="py-2.5 px-2 w-10 text-center po-edit-cell"></th>
              </tr>
            </thead>
            <tbody id="poItemsTableBody" class="divide-y divide-slate-100 bg-white">
              <!-- Dynamically rendered rows -->
            </tbody>
          </table>
        </div>

        <div class="po-float-anchor">
          <div class="po-table-add-bar no-print">
            <button type="button" id="poAddItemBtn" class="cursor-pointer inline-flex items-center gap-1 px-2.5 py-1 text-[11px] font-semibold text-slate-700 hover:text-slate-900 bg-slate-100/90 hover:bg-slate-200/80 border border-slate-200/70 rounded-lg transition-colors">
              <i data-lucide="plus" class="w-3 h-3 text-slate-500"></i>
              <span>Add Deliverable</span>
            </button>
            <div id="poAddDiscountTaxBar" class="flex items-center gap-1.5 text-[11px]">
              <button type="button" id="poAddDiscountTriggerBtn" class="cursor-pointer inline-flex items-center px-2 py-1 rounded-lg bg-emerald-50/80 hover:bg-emerald-100/80 border border-emerald-200/70 text-emerald-700 font-semibold transition-colors">+ Discount</button>
              <button type="button" id="poAddTaxTriggerBtn" class="cursor-pointer inline-flex items-center px-2 py-1 rounded-lg bg-slate-50 hover:bg-slate-100 border border-slate-200/70 text-slate-600 font-semibold transition-colors">+ Tax</button>
            </div>
          </div>
        </div>

        <!-- Financial Totals Summary Box -->
        <div class="po-selectable flex justify-end pt-4" data-elem-id="totals_${sid}" data-elem-name="Financial Totals" data-elem-type="table">
          <div class="w-full max-w-xs space-y-1.5 text-xs" data-po-container="totals_rows">
            <div class="po-total-row flex items-center justify-between py-1 text-slate-600" data-po-unit-id="row_subtotal">
              <input type="text" class="po-selectable po-total-label font-medium text-xs text-slate-600 bg-transparent border-none outline-none rounded px-0 py-0.5 w-28 transition-colors" data-elem-id="label_subtotal" data-elem-name="Subtotal Label" data-elem-type="text" value="${escapeHtml(labels.subtotal || 'Subtotal')}" placeholder="Subtotal">
              <span id="poSubtotalDisplay" class="po-selectable font-mono font-semibold text-slate-900 rounded px-0.5 cursor-pointer" data-elem-id="subtotal_val" data-elem-name="Subtotal Amount" data-elem-type="text">${formatMoney(0, cur)}</span>
            </div>

            <!-- Discount Row -->
            <div id="poDiscountRow" class="po-total-row hidden items-center justify-between py-1 text-emerald-700" data-po-unit-id="row_discount">
              <div class="flex items-center gap-1.5">
                <input type="text" class="po-selectable po-total-label po-field-inline font-medium text-xs text-emerald-700 bg-transparent border-none outline-none rounded px-0 py-0.5 w-auto transition-colors" data-elem-id="label_discount" data-elem-name="Discount Label" data-elem-type="text" value="${escapeHtml(labels.discount || 'Discount')}" placeholder="Discount">
                <div class="inline-flex items-baseline gap-0">
                  <input type="number" id="poDiscountPercentInput" step="1" min="0" max="100" class="po-percent-input text-right text-xs font-mono font-bold bg-white border border-emerald-300 rounded px-0 py-0.5" style="width: 2ch;" value="0">
                  <span class="text-xs font-mono font-bold leading-none">%</span>
                  <button type="button" id="poRemoveDiscountBtn" class="no-print ml-1 text-slate-300 hover:text-rose-500 cursor-pointer p-0.5 self-center" title="Remove discount">
                    <i data-lucide="x" class="w-3 h-3"></i>
                  </button>
                </div>
              </div>
              <span id="poDiscountAmountDisplay" class="po-selectable font-mono font-semibold rounded px-0.5 cursor-pointer" data-elem-id="discount_val" data-elem-name="Discount Amount" data-elem-type="text">-${formatMoney(0, cur)}</span>
            </div>

            <!-- Tax Row -->
            <div id="poTaxRow" class="po-total-row hidden items-center justify-between py-1 text-slate-600" data-po-unit-id="row_tax">
              <div class="flex items-center gap-1.5">
                <input type="text" class="po-selectable po-total-label po-field-inline font-medium text-xs text-slate-600 bg-transparent border-none outline-none rounded px-0 py-0.5 w-auto transition-colors" data-elem-id="label_tax" data-elem-name="Tax Label" data-elem-type="text" value="${escapeHtml(labels.tax || 'VAT / Tax')}" placeholder="VAT / Tax">
                <div class="inline-flex items-baseline gap-0">
                  <input type="number" id="poTaxPercentInput" step="1" min="0" max="100" class="po-percent-input text-right text-xs font-mono font-bold bg-white border border-slate-300 rounded px-0 py-0.5" style="width: 2ch;" value="0">
                  <span class="text-xs font-mono font-bold leading-none">%</span>
                  <button type="button" id="poRemoveTaxBtn" class="no-print ml-1 text-slate-300 hover:text-rose-500 cursor-pointer p-0.5 self-center" title="Remove tax">
                    <i data-lucide="x" class="w-3 h-3"></i>
                  </button>
                </div>
              </div>
              <span id="poTaxAmountDisplay" class="po-selectable font-mono font-semibold rounded px-0.5 cursor-pointer" data-elem-id="tax_val" data-elem-name="Tax Amount" data-elem-type="text">+${formatMoney(0, cur)}</span>
            </div>

            <!-- Grand Total Bar -->
            <div class="po-total-row flex items-center justify-between py-2 border-t-2 border-slate-900 text-sm font-bold text-slate-900 mt-2" data-po-unit-id="row_grand_total">
              <input type="text" class="po-selectable po-total-label uppercase tracking-wider font-bold text-xs text-slate-900 bg-transparent border-none outline-none rounded px-0 py-0.5 w-36 transition-colors" data-elem-id="label_total_investment" data-elem-name="Total Investment Label" data-elem-type="text" value="${escapeHtml(labels.totalInvestment || 'Total Investment')}" placeholder="TOTAL INVESTMENT">
              <span id="poTotalAmountDisplay" class="po-selectable text-base font-black font-mono text-slate-900 rounded px-0.5 cursor-pointer" data-elem-id="total_val" data-elem-name="Grand Total Amount" data-elem-type="text">${formatMoney(0, cur)}</span>
            </div>
          </div>
        </div>
      `;
    } else if (sec.type === 'acceptance') {
      const clientTitle = sec.clientTitle || 'Authorized Client Signature';
      const providerTitle = sec.providerTitle || 'Service Provider Signature';
      bodyHtml = `
        <div class="po-selectable po-signatures-grid grid grid-cols-1 sm:grid-cols-2 gap-8 pt-4" data-elem-id="signatures_${sid}" data-elem-name="Signatures Block" data-elem-type="signatures" data-po-container="signatures_grid">
          <div class="space-y-3" data-po-unit-id="sig_col_client" data-po-container="sig_client">
            <input type="text" class="po-client-sign-title font-bold text-xs uppercase tracking-wider text-slate-800 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full" data-sec-id="${sid}" value="${escapeHtml(clientTitle)}" placeholder="AUTHORIZED CLIENT SIGNATURE">
            <div class="h-16 border-b border-slate-300 flex items-end pb-1">
              <input type="text" class="po-sign-seal-label text-[11px] text-slate-400 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full print-keep" data-sec-id="${sid}" value="${escapeHtml(sec.signSealText || 'Signature & Seal')}" placeholder="Signature & Seal">
            </div>
            <div class="flex items-center justify-between text-[11px] text-slate-500 pt-1 gap-2">
              <input type="text" class="po-sign-date-label text-[11px] text-slate-500 bg-transparent border-none outline-none rounded px-0 py-0.5 w-1/2 print-keep" data-sec-id="${sid}" value="${escapeHtml(sec.signDateText || 'Date: _________________')}" placeholder="Date: _________">
              <input type="text" class="po-sign-name-label text-[11px] text-slate-500 text-right bg-transparent border-none outline-none rounded px-0 py-0.5 w-1/2 print-keep" data-sec-id="${sid}" value="${escapeHtml(sec.signNameText || 'Name: _________________')}" placeholder="Name: _________">
            </div>
          </div>
          <div class="space-y-3" data-po-unit-id="sig_col_provider" data-po-container="sig_provider">
            <input type="text" class="po-provider-sign-title font-bold text-xs uppercase tracking-wider text-slate-800 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full" data-sec-id="${sid}" value="${escapeHtml(providerTitle)}" placeholder="SERVICE PROVIDER SIGNATURE">
            <div class="h-16 border-b border-slate-300 flex items-end pb-1">
              <input type="text" class="po-sign-seal-provider-label text-[11px] text-slate-400 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full print-keep" data-sec-id="${sid}" value="${escapeHtml(sec.signSealProviderText || 'Signature & Seal')}" placeholder="Signature & Seal">
            </div>
            <div class="flex items-center justify-between text-[11px] text-slate-500 pt-1 gap-2">
              <input type="text" class="po-sign-date-provider-label text-[11px] text-slate-500 bg-transparent border-none outline-none rounded px-0 py-0.5 w-1/2 print-keep" data-sec-id="${sid}" value="${escapeHtml(sec.signDateProviderText || 'Date: _________________')}" placeholder="Date: _________">
              <input type="text" class="po-sign-name-provider-label text-[11px] text-slate-500 text-right bg-transparent border-none outline-none rounded px-0 py-0.5 w-1/2 print-keep" data-sec-id="${sid}" value="${escapeHtml(sec.signNameProviderText || 'Name: _________________')}" placeholder="Name: _________">
            </div>
          </div>
        </div>
      `;
    } else {
      const placeholderText = sec.type === 'scope'
        ? 'Describe project scope, deliverables, and goals...'
        : sec.type === 'timeline'
        ? 'Estimated duration, delivery phases, and milestone schedules...'
        : sec.type === 'terms'
        ? 'Payment schedules, deposits, milestone releases, invoice terms...'
        : sec.type === 'conditions'
        ? 'Terms, validity, revision rounds, out-of-scope policies...'
        : 'Type here…';

      bodyHtml = `
        <div contenteditable="true" class="po-selectable po-section-content po-doc-text w-full text-xs text-slate-700 leading-relaxed bg-transparent border-none outline-none rounded px-0 py-0.5 min-h-[24px] mt-1 transition-colors" data-sec-id="${sid}" data-elem-id="content_${sid}" data-elem-name="Text: ${escapeHtml(sec.title || 'Section')}" data-elem-type="text" data-placeholder="${placeholderText}">${formatInitialContent(sec.content)}</div>
      `;
    }

    return `
      ${insertZoneBeforeHtml}
      <div class="po-section po-selectable ${selCls}" data-sec-id="${sid}" data-sec-index="${idx}" data-elem-id="sec_${sid}" data-elem-name="${escapeHtml(sec.title || 'Section')}" data-elem-type="section">
        ${poBlockChromeHtml(idx, true, sec.title || 'Section')}
        <div class="po-title-wrap mb-1">
          <input type="text" class="po-selectable po-section-title-input text-xs font-bold uppercase tracking-wider text-slate-900 bg-transparent border-none outline-none rounded px-0 py-0.5 w-full transition-colors" data-sec-id="${sid}" data-elem-id="title_${sid}" data-elem-name="Title: ${escapeHtml(sec.title || 'Untitled')}" data-elem-type="text" value="${escapeHtml(sec.title || '')}" placeholder="SECTION TITLE">
        </div>
        ${bodyHtml}
      </div>
    `;
  }

  // ==========================================
  // SIGNATURE STUDIO: PEN VECTOR & PNG UPLOAD + MOVABLE CANVAS LAYER
  // ==========================================
  const PO_SAVED_SIG_KEY = 'ft_po_saved_signature_v1';
  let poSigModalActiveTab = 'draw'; // 'draw' | 'upload'
  let poSigPadStrokes = []; // Array of { points: [{x, y}], color, strokeWidth }
  let poSigCurrentStroke = null;
  let poSigInkColor = '#0f172a';
  let poSigStrokeWidth = 2.4;
  let poSigUploadRawDataUrl = null;
  let poSigUploadProcessedDataUrl = null;
  let poSigUploadAspect = 2.8;
  let poSigUploadTintColor = 'original'; // 'original' | hex color
  let poSigEditingId = null; // If set, replaces existing signature in place

  function getSavedPoSignaturePreset() {
    try {
      const raw = localStorage.getItem(PO_SAVED_SIG_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (parsed && (parsed.svgData || parsed.imageDataUrl)) return parsed;
    } catch (e) {}
    return null;
  }

  function savePoSignaturePreset(sigData) {
    try {
      localStorage.setItem(PO_SAVED_SIG_KEY, JSON.stringify(sigData));
    } catch (e) {}
  }

  function getDefaultPoSignaturePlacement(widthMm = 48, heightMm = 18) {
    const sheet = document.getElementById('priceOfferingSheet');
    const pxPerMm = 96 / 25.4;
    if (sheet) {
      const sheetRect = sheet.getBoundingClientRect();
      const z = poZoom || 1;
      const provLine = sheet.querySelector('.po-sign-seal-provider-label');
      if (provLine) {
        const lineContainer = provLine.parentElement || provLine;
        const r = lineContainer.getBoundingClientRect();
        const relLeftPx = (r.left - sheetRect.left) / z;
        const relBottomPx = (r.bottom - sheetRect.top) / z;
        const xMm = Math.max(10, Math.min(210 - widthMm - 10, Math.round((relLeftPx / pxPerMm + 2) * 2) / 2));
        const yMm = Math.max(10, Math.round(((relBottomPx / pxPerMm) - heightMm - 2) * 2) / 2);
        return { xMm, yMm };
      }
      const sigGrid = sheet.querySelector('.po-signatures-grid');
      if (sigGrid) {
        const r = sigGrid.getBoundingClientRect();
        const relTopPx = (r.top - sheetRect.top) / z;
        const xMm = Math.round((210 - 15 - widthMm) * 2) / 2;
        const yMm = Math.max(15, Math.round(((relTopPx / pxPerMm) + 6) * 2) / 2);
        return { xMm, yMm };
      }
      const sheetHeightMm = (sheet.offsetHeight || PO_PAGE_H_PX) / pxPerMm;
      return {
        xMm: Math.round((210 - 20 - widthMm) * 2) / 2,
        yMm: Math.max(20, Math.round((sheetHeightMm - 42 - heightMm) * 2) / 2)
      };
    }
    return { xMm: 132, yMm: 235 };
  }

  function buildPoSignatureInnerSvg(sig) {
    if (!sig) return '';
    if (sig.kind === 'image' && sig.imageDataUrl) {
      return `<img src="${sig.imageDataUrl}" alt="Signature" draggable="false" />`;
    }
    if (sig.svgPaths && Array.isArray(sig.svgPaths) && sig.svgPaths.length > 0) {
      const vb = sig.viewBox || '0 0 240 90';
      const sw = sig.strokeWidth || 2.4;
      const col = sig.color || '#0f172a';
      const pathsHtml = sig.svgPaths.map(d =>
        `<path d="${escapeHtml(d)}" fill="none" stroke="${escapeHtml(col)}" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke" />`
      ).join('');
      return `<svg viewBox="${escapeHtml(vb)}" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid meet">${pathsHtml}</svg>`;
    }
    if (sig.svgMarkup) {
      return sig.svgMarkup;
    }
    return '';
  }

  function renderPoSignaturesLayer() {
    const layer = document.getElementById('poSignaturesLayer');
    if (!layer) return;
    if (!Array.isArray(currentPoSignatures) || currentPoSignatures.length === 0) {
      layer.innerHTML = '';
      return;
    }
    layer.innerHTML = currentPoSignatures.map((sig, i) => {
      const id = sig.id || ('sig_' + i);
      const isSelected = poSelectedElementId === id;
      const xMm = Number(sig.xMm || 130);
      const yMm = Number(sig.yMm || 230);
      const wMm = Math.max(12, Number(sig.widthMm || 48));
      const hMm = Math.max(6, Number(sig.heightMm || 18));
      const inner = buildPoSignatureInnerSvg(sig);
      return `
        <div class="po-signature-vector po-selectable ${isSelected ? 'po-selected-element' : ''}"
             data-sig-id="${escapeHtml(id)}"
             data-elem-id="${escapeHtml(id)}"
             data-elem-name="Signature"
             data-elem-type="signature"
             style="left:${xMm}mm;top:${yMm}mm;width:${wMm}mm;height:${hMm}mm;">
          ${inner}
          <button type="button" class="po-sig-delete-btn no-print" data-sig-id="${escapeHtml(id)}" title="Remove signature">&times;</button>
          <div class="po-sig-resize-handle no-print" data-sig-id="${escapeHtml(id)}" title="Drag to resize signature"></div>
        </div>
      `;
    }).join('');
  }

  function poPointsToSmoothSvgPath(pts) {
    if (!pts || pts.length === 0) return '';
    if (pts.length === 1) {
      const p = pts[0];
      return `M ${p.x.toFixed(1)} ${p.y.toFixed(1)} L ${(p.x + 0.2).toFixed(1)} ${(p.y + 0.2).toFixed(1)}`;
    }
    let d = `M ${pts[0].x.toFixed(1)} ${pts[0].y.toFixed(1)}`;
    for (let i = 1; i < pts.length - 1; i++) {
      const xc = (pts[i].x + pts[i + 1].x) / 2;
      const yc = (pts[i].y + pts[i + 1].y) / 2;
      d += ` Q ${pts[i].x.toFixed(1)} ${pts[i].y.toFixed(1)}, ${xc.toFixed(1)} ${yc.toFixed(1)}`;
    }
    const last = pts[pts.length - 1];
    d += ` L ${last.x.toFixed(1)} ${last.y.toFixed(1)}`;
    return d;
  }

  function renderPoSigPadStrokes() {
    const g = document.getElementById('poSigPadStrokesGroup');
    const hint = document.getElementById('poSigPadEmptyHint');
    if (!g) return;
    const allStrokes = poSigCurrentStroke ? [...poSigPadStrokes, poSigCurrentStroke] : poSigPadStrokes;
    if (hint) hint.classList.toggle('hidden', allStrokes.length > 0);
    g.innerHTML = allStrokes.map(st => {
      const d = poPointsToSmoothSvgPath(st.points);
      return `<path d="${d}" fill="none" stroke="${escapeHtml(poSigInkColor)}" stroke-width="${poSigStrokeWidth * 1.4}" stroke-linecap="round" stroke-linejoin="round" />`;
    }).join('');
  }

  function computeCroppedPoVectorSignature() {
    if (!poSigPadStrokes.length) return null;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    poSigPadStrokes.forEach(st => {
      st.points.forEach(p => {
        if (p.x < minX) minX = p.x;
        if (p.y < minY) minY = p.y;
        if (p.x > maxX) maxX = p.x;
        if (p.y > maxY) maxY = p.y;
      });
    });
    if (!isFinite(minX)) return null;
    const pad = 8;
    const vbX = Math.floor(minX - pad);
    const vbY = Math.floor(minY - pad);
    const vbW = Math.max(40, Math.ceil((maxX - minX) + pad * 2));
    const vbH = Math.max(20, Math.ceil((maxY - minY) + pad * 2));
    const svgPaths = poSigPadStrokes.map(st => poPointsToSmoothSvgPath(st.points)).filter(Boolean);
    const aspect = Math.max(1.2, Math.min(5.5, vbW / vbH));
    const widthMm = 46;
    const heightMm = Math.max(10, Math.round((widthMm / aspect) * 10) / 10);
    return {
      kind: 'vector',
      viewBox: `${vbX} ${vbY} ${vbW} ${vbH}`,
      svgPaths,
      color: poSigInkColor,
      strokeWidth: poSigStrokeWidth,
      widthMm,
      heightMm
    };
  }

  function processUploadedSignatureImage(rawDataUrl, removeWhiteBg = true, tintColor = 'original') {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        const maxDim = 900;
        let w = img.naturalWidth || img.width || 400;
        let h = img.naturalHeight || img.height || 160;
        if (w > maxDim || h > maxDim) {
          const scale = maxDim / Math.max(w, h);
          w = Math.max(1, Math.round(w * scale));
          h = Math.max(1, Math.round(h * scale));
        }
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);

        const imgData = ctx.getImageData(0, 0, w, h);
        const data = imgData.data;

        let tintRgb = null;
        if (tintColor && tintColor !== 'original' && /^#[0-9a-fA-F]{6}$/.test(tintColor)) {
          tintRgb = [
            parseInt(tintColor.slice(1, 3), 16),
            parseInt(tintColor.slice(3, 5), 16),
            parseInt(tintColor.slice(5, 7), 16)
          ];
        }

        let minX = w, minY = h, maxX = 0, maxY = 0, foundInk = false;

        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            const idx = (y * w + x) * 4;
            let r = data[idx];
            let g = data[idx + 1];
            let b = data[idx + 2];
            let a = data[idx + 3];

            if (a < 10) {
              data[idx + 3] = 0;
              continue;
            }

            const lum = 0.299 * r + 0.587 * g + 0.114 * b;
            if (removeWhiteBg) {
              if (lum > 242) {
                a = 0;
              } else if (lum > 185) {
                const factor = (242 - lum) / (242 - 185);
                a = Math.round(a * Math.max(0, Math.min(1, factor)));
              }
            }

            if (a > 12) {
              if (tintRgb) {
                r = tintRgb[0];
                g = tintRgb[1];
                b = tintRgb[2];
              }
              data[idx] = r;
              data[idx + 1] = g;
              data[idx + 2] = b;
              data[idx + 3] = a;
              if (x < minX) minX = x;
              if (y < minY) minY = y;
              if (x > maxX) maxX = x;
              if (y > maxY) maxY = y;
              foundInk = true;
            } else {
              data[idx + 3] = 0;
            }
          }
        }

        ctx.putImageData(imgData, 0, 0);

        if (!foundInk) {
          resolve({ dataUrl: canvas.toDataURL('image/png'), aspect: w / Math.max(1, h) });
          return;
        }

        const pad = 8;
        const cx = Math.max(0, minX - pad);
        const cy = Math.max(0, minY - pad);
        const cw = Math.min(w - cx, (maxX - minX + 1) + pad * 2);
        const ch = Math.min(h - cy, (maxY - minY + 1) + pad * 2);

        const outCanvas = document.createElement('canvas');
        outCanvas.width = Math.max(1, cw);
        outCanvas.height = Math.max(1, ch);
        const outCtx = outCanvas.getContext('2d');
        outCtx.drawImage(canvas, cx, cy, cw, ch, 0, 0, cw, ch);

        resolve({
          dataUrl: outCanvas.toDataURL('image/png'),
          aspect: Math.max(1.1, Math.min(6, cw / Math.max(1, ch)))
        });
      };
      img.onerror = () => resolve({ dataUrl: rawDataUrl, aspect: 2.8 });
      img.src = rawDataUrl;
    });
  }

  async function refreshPoUploadedSignaturePreview() {
    if (!poSigUploadRawDataUrl) return;
    const removeBg = document.getElementById('poSigRemoveWhiteBgToggle')?.checked !== false;
    const res = await processUploadedSignatureImage(poSigUploadRawDataUrl, removeBg, poSigUploadTintColor);
    poSigUploadProcessedDataUrl = res.dataUrl;
    poSigUploadAspect = res.aspect || 2.8;
    const previewImg = document.getElementById('poSigUploadPreviewImg');
    const previewWrap = document.getElementById('poSigUploadPreviewWrap');
    const emptyWrap = document.getElementById('poSigUploadEmptyState');
    if (previewImg) previewImg.src = poSigUploadProcessedDataUrl;
    if (previewWrap) {
      previewWrap.classList.remove('hidden');
      previewWrap.classList.add('flex');
    }
    if (emptyWrap) emptyWrap.classList.add('hidden');
  }

  function switchPoSigModalTab(tab) {
    poSigModalActiveTab = tab === 'upload' ? 'upload' : 'draw';
    const drawBtn = document.getElementById('poSigTabDrawBtn');
    const uploadBtn = document.getElementById('poSigTabUploadBtn');
    const drawPane = document.getElementById('poSigDrawPane');
    const uploadPane = document.getElementById('poSigUploadPane');
    if (drawBtn && uploadBtn) {
      if (poSigModalActiveTab === 'draw') {
        drawBtn.className = 'flex-1 h-8 rounded-lg text-xs font-bold flex items-center justify-center gap-1.5 bg-white text-slate-900 shadow-xs transition-all cursor-pointer whitespace-nowrap';
        uploadBtn.className = 'flex-1 h-8 rounded-lg text-xs font-bold flex items-center justify-center gap-1.5 text-slate-500 hover:text-slate-800 transition-all cursor-pointer whitespace-nowrap';
      } else {
        uploadBtn.className = 'flex-1 h-8 rounded-lg text-xs font-bold flex items-center justify-center gap-1.5 bg-white text-slate-900 shadow-xs transition-all cursor-pointer whitespace-nowrap';
        drawBtn.className = 'flex-1 h-8 rounded-lg text-xs font-bold flex items-center justify-center gap-1.5 text-slate-500 hover:text-slate-800 transition-all cursor-pointer whitespace-nowrap';
      }
    }
    if (drawPane) drawPane.classList.toggle('hidden', poSigModalActiveTab !== 'draw');
    if (uploadPane) uploadPane.classList.toggle('hidden', poSigModalActiveTab !== 'upload');
  }

  function updateSavedPoSignatureBannerUI() {
    const banner = document.getElementById('poSavedSignatureBanner');
    const previewBox = document.getElementById('poSavedSignaturePreviewBox');
    if (!banner || !previewBox) return;
    const saved = getSavedPoSignaturePreset();
    if (!saved) {
      banner.classList.add('hidden');
      banner.classList.remove('flex');
      return;
    }
    banner.classList.remove('hidden');
    banner.classList.add('flex');
    previewBox.innerHTML = buildPoSignatureInnerSvg(saved);
  }

  function openPoSignatureModal(editSigId = null, initialTab = 'draw') {
    const modal = document.getElementById('poSignaturePadModal');
    if (!modal) return;
    poSigEditingId = editSigId || null;
    poSigPadStrokes = [];
    poSigCurrentStroke = null;
    renderPoSigPadStrokes();
    updateSavedPoSignatureBannerUI();
    switchPoSigModalTab(initialTab);
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function closePoSignatureModal() {
    const modal = document.getElementById('poSignaturePadModal');
    if (!modal) return;
    modal.classList.add('hidden');
    modal.classList.remove('flex');
    poSigEditingId = null;
  }

  function placePoSignatureDataOnDocument(sigPayload) {
    if (!sigPayload) return;
    pushPoUndoSnapshot();

    if (poSigEditingId) {
      const existing = (currentPoSignatures || []).find(s => s.id === poSigEditingId);
      if (existing) {
        Object.assign(existing, sigPayload, {
          id: existing.id,
          xMm: existing.xMm,
          yMm: existing.yMm
        });
        savePoSignaturePreset(sigPayload);
        renderPoSignaturesLayer();
        selectPoElement(document.querySelector(`.po-signature-vector[data-sig-id="${existing.id}"]`), existing.id, 'Signature', 'signature');
        triggerPriceOfferingAutoSave(true);
        closePoSignatureModal();
        showToast('Signature Updated ✓', 'Updated your signature on the document.', 'success');
        return;
      }
    }

    const wMm = sigPayload.widthMm || 48;
    const hMm = sigPayload.heightMm || 18;
    const pos = getDefaultPoSignaturePlacement(wMm, hMm);
    const newSig = Object.assign({}, sigPayload, {
      id: 'sig_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
      xMm: pos.xMm,
      yMm: pos.yMm,
      widthMm: wMm,
      heightMm: hMm
    });
    if (!Array.isArray(currentPoSignatures)) currentPoSignatures = [];
    currentPoSignatures.push(newSig);
    savePoSignaturePreset(sigPayload);
    renderPoSignaturesLayer();
    const el = document.querySelector(`.po-signature-vector[data-sig-id="${newSig.id}"]`);
    if (el) {
      selectPoElement(el, newSig.id, 'Signature', 'signature');
    }
    triggerPriceOfferingAutoSave(true);
    closePoSignatureModal();
    showToast('Signature Placed ✓', 'Drag anywhere on the page or resize from the corner.', 'success');
  }

  function initPoSignatureStudioListeners() {
    const modal = document.getElementById('poSignaturePadModal');
    if (!modal || modal._poSigInitialized) return;
    modal._poSigInitialized = true;

    document.getElementById('poCloseSignatureModalBtn')?.addEventListener('click', closePoSignatureModal);
    document.getElementById('poCancelSignatureModalBtn')?.addEventListener('click', closePoSignatureModal);
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closePoSignatureModal();
    });

    document.getElementById('poSigTabDrawBtn')?.addEventListener('click', () => switchPoSigModalTab('draw'));
    document.getElementById('poSigTabUploadBtn')?.addEventListener('click', () => switchPoSigModalTab('upload'));

    document.getElementById('poInsertSavedSignatureBtn')?.addEventListener('click', () => {
      const saved = getSavedPoSignaturePreset();
      if (saved) placePoSignatureDataOnDocument(saved);
    });

    // Pen Pad SVG Pointer Events
    const svgPad = document.getElementById('poSigPadSvg');
    if (svgPad) {
      const getPt = (e) => {
        const rect = svgPad.getBoundingClientRect();
        const scaleX = 560 / Math.max(1, rect.width);
        const scaleY = 200 / Math.max(1, rect.height);
        return {
          x: (e.clientX - rect.left) * scaleX,
          y: (e.clientY - rect.top) * scaleY
        };
      };

      svgPad.addEventListener('pointerdown', (e) => {
        if (e.button !== 0 && e.pointerType === 'mouse') return;
        e.preventDefault();
        try { svgPad.setPointerCapture(e.pointerId); } catch (_) {}
        poSigCurrentStroke = {
          points: [getPt(e)],
          color: poSigInkColor,
          strokeWidth: poSigStrokeWidth
        };
        renderPoSigPadStrokes();
      });

      svgPad.addEventListener('pointermove', (e) => {
        if (!poSigCurrentStroke) return;
        e.preventDefault();
        const pt = getPt(e);
        const pts = poSigCurrentStroke.points;
        const last = pts[pts.length - 1];
        if (!last || Math.hypot(pt.x - last.x, pt.y - last.y) > 1.2) {
          pts.push(pt);
          renderPoSigPadStrokes();
        }
      });

      const finishStroke = (e) => {
        if (!poSigCurrentStroke) return;
        try { svgPad.releasePointerCapture(e.pointerId); } catch (_) {}
        poSigPadStrokes.push(poSigCurrentStroke);
        poSigCurrentStroke = null;
        renderPoSigPadStrokes();
      };
      svgPad.addEventListener('pointerup', finishStroke);
      svgPad.addEventListener('pointercancel', finishStroke);
    }

    document.getElementById('poSigUndoStrokeBtn')?.addEventListener('click', () => {
      poSigPadStrokes.pop();
      renderPoSigPadStrokes();
    });

    document.getElementById('poSigClearPadBtn')?.addEventListener('click', () => {
      poSigPadStrokes = [];
      poSigCurrentStroke = null;
      renderPoSigPadStrokes();
    });

    document.querySelectorAll('.po-sig-pad-color').forEach(btn => {
      btn.addEventListener('click', () => {
        poSigInkColor = btn.getAttribute('data-color') || '#0f172a';
        document.querySelectorAll('.po-sig-pad-color').forEach(b => {
          b.classList.toggle('ring-2', b === btn);
          b.classList.toggle('ring-slate-300', b === btn);
        });
        renderPoSigPadStrokes();
      });
    });

    const padWeightRange = document.getElementById('poSigPadWeightRange');
    if (padWeightRange) {
      padWeightRange.addEventListener('input', (e) => {
        poSigStrokeWidth = parseFloat(e.target.value) || 2.4;
        renderPoSigPadStrokes();
      });
    }

    // Upload PNG / Image Handlers
    const dropzone = document.getElementById('poSigUploadDropzone');
    const fileInput = document.getElementById('poSigUploadInput');
    const handleFile = (file) => {
      if (!file || !file.type.startsWith('image/')) {
        showToast('Image Required', 'Please select a PNG, JPG, or WebP signature image.', 'error');
        return;
      }
      const reader = new FileReader();
      reader.onload = async (ev) => {
        poSigUploadRawDataUrl = ev.target.result;
        await refreshPoUploadedSignaturePreview();
      };
      reader.readAsDataURL(file);
    };

    if (dropzone && fileInput) {
      dropzone.addEventListener('click', () => fileInput.click());
      fileInput.addEventListener('change', (e) => {
        if (e.target.files && e.target.files[0]) {
          handleFile(e.target.files[0]);
          e.target.value = '';
        }
      });
      dropzone.addEventListener('dragover', (e) => {
        e.preventDefault();
        dropzone.classList.add('border-slate-900', 'bg-slate-100/70');
      });
      dropzone.addEventListener('dragleave', () => {
        dropzone.classList.remove('border-slate-900', 'bg-slate-100/70');
      });
      dropzone.addEventListener('drop', (e) => {
        e.preventDefault();
        dropzone.classList.remove('border-slate-900', 'bg-slate-100/70');
        if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0]) {
          handleFile(e.dataTransfer.files[0]);
        }
      });
    }

    document.getElementById('poSigRemoveWhiteBgToggle')?.addEventListener('change', () => {
      refreshPoUploadedSignaturePreview();
    });

    document.querySelectorAll('.po-sig-upload-tint').forEach(btn => {
      btn.addEventListener('click', () => {
        poSigUploadTintColor = btn.getAttribute('data-tint') || 'original';
        document.querySelectorAll('.po-sig-upload-tint').forEach(b => {
          if (b === btn) {
            b.classList.add('ring-2', 'ring-slate-400');
          } else {
            b.classList.remove('ring-2', 'ring-slate-400');
          }
        });
        refreshPoUploadedSignaturePreview();
      });
    });

    // Place Signature onto Document Button
    document.getElementById('poPlaceSignatureBtn')?.addEventListener('click', () => {
      if (poSigModalActiveTab === 'draw') {
        const vecData = computeCroppedPoVectorSignature();
        if (!vecData) {
          showToast('Draw Signature First', 'Draw your signature on the pad or switch to Upload Signature PNG.', 'info');
          return;
        }
        placePoSignatureDataOnDocument(vecData);
      } else {
        if (!poSigUploadProcessedDataUrl) {
          showToast('Upload Signature First', 'Select or drop a PNG/JPG image of your signature first.', 'info');
          return;
        }
        const widthMm = 48;
        const heightMm = Math.max(10, Math.round((widthMm / (poSigUploadAspect || 2.8)) * 10) / 10);
        placePoSignatureDataOnDocument({
          kind: 'image',
          imageDataUrl: poSigUploadProcessedDataUrl,
          rawImageDataUrl: poSigUploadRawDataUrl,
          color: poSigUploadTintColor,
          removeWhiteBg: document.getElementById('poSigRemoveWhiteBgToggle')?.checked !== false,
          aspect: poSigUploadAspect || 2.8,
          widthMm,
          heightMm
        });
      }
    });
  }

  // Make sure legacy documents without structural blocks get them once, while allowing deliberate deletion
  function ensurePoStructuralBlocks(po) {
    if (!Array.isArray(currentPoSections)) currentPoSections = [];
    if ((po && po._structuralMigrated) || (po && po._studioDoc) || (po && (po._isProforma || po._isDepositProforma)) || state.activeStudioDocId || state.activeProformaProjectId || state.activeDepositProformaProjectId) {
      if (po) po._structuralMigrated = true;
      return;
    }
    if (currentPoSections.some(s => s.type === 'header' || s.type === 'overview')) {
      if (po) po._structuralMigrated = true;
      return;
    }
    const startsWithDivider = currentPoSections[0] && currentPoSections[0].type === 'divider';
    const blocks = [
      { id: 'sec_header', type: 'header', title: 'Document Header' },
      { id: 'sec_overview', type: 'overview', title: 'Client & Project Details' }
    ];
    if (!startsWithDivider) {
      blocks.push({ id: 'sec_div_overview', type: 'divider', title: 'Divider Line', content: '' });
    }
    currentPoSections.unshift(...blocks);
    if (po) po._structuralMigrated = true;
  }

  function renderPriceOfferingDocument(lead, po) {
    const container = document.getElementById('priceOfferingPrintArea');
    if (!container) return;

    const savedRenderScroll = capturePoScrollPositions();
    const prevContainerH = container.offsetHeight;
    if (prevContainerH > 0) {
      container.style.minHeight = prevContainerH + 'px';
    }

    if (container.querySelector('#priceOfferingSheet') && !poHoverPreviewBackup) {
      flushLivePoDomToState();
    }

    if (!lead) {
      const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
      lead = getPoEditorTarget(leadId);
    }
    if (!lead) return;
    if (!po) po = lead.priceOffering || {};

    // Values currently typed in the document win over stale saved values
    const live = (id, fallback) => {
      const el = document.getElementById(id);
      return (el && container.contains(el)) ? el.value : fallback;
    };

    const isStudioDoc = !!(lead._isStudioDoc || po._studioDoc);
    const isDepositProforma = !!(lead._isDepositProforma || po._isDepositProforma || state.activeDepositProformaProjectId);
    const isProforma = !isDepositProforma && !!(lead._isProforma || po._isProforma || state.activeProformaProjectId);

    const masterTpl = isDepositProforma
      ? getMasterDepositProformaTemplate()
      : (isProforma ? getMasterProformaTemplate() : getMasterPoTemplate());

    let savedSender = null;
    if (!isStudioDoc) {
      try {
        savedSender = JSON.parse(localStorage.getItem('ft_po_sender_info') || 'null');
      } catch (e) {}
    }

    const hasCustomSender = po.sender && (po.sender.name || po.sender.title || po.sender.contact || po.sender.location) && po.sender.name !== 'Your Name / Studio';
    const baseSender = isStudioDoc
      ? (po.sender || masterTpl.sender)
      : (hasCustomSender ? po.sender : (savedSender && savedSender.name !== 'Your Name / Studio' ? savedSender : masterTpl.sender));
    const sender = {
      name: live('poSenderName', baseSender.name !== undefined ? baseSender.name : masterTpl.sender.name),
      title: live('poSenderTitle', baseSender.title !== undefined ? baseSender.title : masterTpl.sender.title),
      contact: live('poSenderContact', baseSender.contact !== undefined ? baseSender.contact : masterTpl.sender.contact),
      location: live('poSenderLocation', baseSender.location !== undefined ? baseSender.location : masterTpl.sender.location)
    };

    let defaultHeading = 'Price Quote / Proposal';
    let defaultSub = '';
    if (isDepositProforma) {
      defaultHeading = 'DEPOSIT PROFORMA INVOICE';
      defaultSub = 'PRELIMINARY DEPOSIT / ADVANCE PAYMENT REQUEST';
    } else if (isProforma) {
      defaultHeading = 'PROFORMA INVOICE';
      defaultSub = 'OFFICIAL PROFORMA INVOICE / FINAL PAYMENT REQUEST';
    } else if (isStudioDoc) {
      defaultHeading = '';
      defaultSub = '';
    }

    let defaultDocTitle = defaultHeading;
    if (isStudioDoc) {
      defaultDocTitle = po.docTitle || '';
    } else if (isDepositProforma) {
      defaultDocTitle = (po.docTitle && !po.docTitle.includes('Price Quote') && !po.docTitle.includes('Proposal') && po.docTitle !== 'PROFORMA INVOICE') ? po.docTitle : 'DEPOSIT PROFORMA INVOICE';
    } else if (isProforma) {
      defaultDocTitle = (po.docTitle && !po.docTitle.includes('Price Quote') && !po.docTitle.includes('Proposal') && !po.docTitle.includes('DEPOSIT')) ? po.docTitle : 'PROFORMA INVOICE';
    } else {
      defaultDocTitle = (po.docTitle && !po.docTitle.includes('PROFORMA')) ? po.docTitle : 'Price Quote / Proposal';
    }

    const rawLiveHeading = live('poDocHeading', defaultDocTitle);
    let docTitle = defaultDocTitle;
    if (rawLiveHeading) {
      if (isDepositProforma) {
        docTitle = (!rawLiveHeading.includes('Price Quote') && !rawLiveHeading.includes('Proposal') && rawLiveHeading !== 'PROFORMA INVOICE') ? rawLiveHeading : 'DEPOSIT PROFORMA INVOICE';
      } else if (isProforma) {
        docTitle = (!rawLiveHeading.includes('Price Quote') && !rawLiveHeading.includes('Proposal') && !rawLiveHeading.includes('DEPOSIT')) ? rawLiveHeading : 'PROFORMA INVOICE';
      } else if (isStudioDoc) {
        docTitle = rawLiveHeading;
      } else {
        docTitle = (!rawLiveHeading.includes('PROFORMA')) ? rawLiveHeading : 'Price Quote / Proposal';
      }
    }

    const docSubtitle = live('poDocSubtitle', po.docSubtitle !== undefined ? po.docSubtitle : defaultSub);

    const curYear = new Date().getFullYear();
    const refPrefix = isDepositProforma ? 'DPI' : (isProforma ? 'PI' : 'PO');
    const refNo = live('poRefNo', po.refNo || `${refPrefix}-${curYear}-${String(lead.id || '').replace(/\D/g, '').slice(-3) || '001'}`);
    const todayStr = new Date().toISOString().split('T')[0];
    const twoWeeksStr = new Date(Date.now() + 14 * 86400000).toISOString().split('T')[0];
    const issueDate = live('poIssueDate', po.issueDate || todayStr);
    const validUntil = live('poValidUntil', po.validUntil || (lead.dueDate || twoWeeksStr));
    const cur = (live('poCurrencyInput', po.currency || lead.currency || state.displayCurrency || 'EUR') || 'EUR').toUpperCase();

    const client = live('poClientName', po.client !== undefined ? po.client : (lead.client || ''));
    const clientEmail = live('poClientEmail', po.clientEmail || '');
    const clientAddress = live('poClientAddress', po.clientAddress || '');
    const projectTitle = live('poProjectTitle', po.projectTitle !== undefined ? po.projectTitle : (lead.title || lead.description || ''));

    const labels = readPoLabels(po.labels);
    if ((isProforma || isDepositProforma) && (!po.labels || Object.keys(po.labels).length === 0)) {
      if (!labels.client || labels.client === 'Client / Recipient') labels.client = 'Bill To / Client';
      if (!labels.reference || labels.reference === 'Reference') labels.reference = isDepositProforma ? 'Deposit Invoice #' : 'Proforma Invoice #';
      if (!labels.issueDate || labels.issueDate === 'Date Issued') labels.issueDate = 'Invoice Date';
      if (!labels.validUntil || labels.validUntil === 'Valid Until') labels.validUntil = 'Payment Due';
      if (!labels.totalInvestment || labels.totalInvestment === 'Total Investment') labels.totalInvestment = isDepositProforma ? 'Deposit Amount Due' : 'Total Amount Due';
    }
    const discountLive = live('poDiscountPercentInput', po.discountPercent);
    const taxLive = live('poTaxPercentInput', po.taxPercent);

    // Collect in-flight section edits if present
    container.querySelectorAll('.po-section-title-input').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.title = inp.value;
    });
    container.querySelectorAll('.po-section-content').forEach(ta => {
      const secId = ta.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.content = poCleanContentHtml(ta);
    });

    if (!currentPoSections || currentPoSections.length === 0) {
      currentPoSections = getDefaultPoSections(po, lead);
    }
    currentPoSections.forEach(s => {
      if (s && typeof s.title === 'string' && s.title.trim().toUpperCase() === 'UNTITLED SECTION') {
        s.title = '';
      }
    });
    ensurePoStructuralBlocks(po);

    const ctx = { docTitle, docSubtitle, sender, labels, client, clientEmail, clientAddress, refNo, cur, issueDate, validUntil, projectTitle };

    const sectionsHtml = currentPoSections.map((sec, idx) =>
      renderPoSectionHtml(sec, idx, currentPoSections.length, labels, cur, ctx)
    ).join('');

    const bottomInsertZoneHtml = `
      <div class="po-bottom-add no-print" data-insert-index="${currentPoSections.length}">
        <button type="button" class="po-quick-add-btn" data-type="text" data-insert-index="${currentPoSections.length}">
          <i data-lucide="type" class="w-3.5 h-3.5"></i><span>Add text box</span>
        </button>
        <button type="button" class="po-quick-add-btn" data-type="divider" data-insert-index="${currentPoSections.length}">
          <i data-lucide="minus" class="w-3.5 h-3.5"></i><span>Add divider</span>
        </button>
      </div>
    `;

    container.innerHTML = `
      <div id="priceOfferingSheet" class="po-page-sheet po-document-sheet price-offering-sheet po-paged relative">
        <div id="poSectionsFlowContainer">
          ${sectionsHtml}
          ${bottomInsertZoneHtml}
        </div>
        <div id="poSignaturesLayer"></div>
        <div id="poDropIndicator" class="po-drop-indicator no-print hidden"></div>
      </div>
    `;
    if (Array.isArray(po.signatures) && (!Array.isArray(currentPoSignatures) || currentPoSignatures.length === 0)) {
      currentPoSignatures = JSON.parse(JSON.stringify(po.signatures));
    }
    renderPoSignaturesLayer();
    poConvertInputsToFields(container);
    container.querySelectorAll('.po-section-content').forEach(contentEl => {
      normalizePoSectionContentDom(contentEl);
      const secId = contentEl.getAttribute('data-sec-id');
      const sec = (currentPoSections || []).find(s => s.id === secId);
      if (sec) sec.content = poCleanContentHtml(contentEl);
    });

    // Render deliverables table items and totals if deliverables section exists
    const hasDeliverables = currentPoSections.some(s => s.type === 'deliverables');
    if (hasDeliverables) {
      const discInput = document.getElementById('poDiscountPercentInput');
      if (discInput && discountLive !== undefined && discountLive !== null) {
        discInput.value = discountLive;
      }
      const taxInput = document.getElementById('poTaxPercentInput');
      if (taxInput && taxLive !== undefined && taxLive !== null) {
        taxInput.value = taxLive;
      }

      renderPriceOfferingItemsTable();
      recalculatePriceOfferingTotals();
    }

    applySavedElementStyles();
    autoResizePoTextareas();

    if (poSelectedElementId) {
      selectPoElement(null, poSelectedElementId, poSelectedElementMeta?.name, poSelectedElementMeta?.type);
    } else {
      updatePoRightSidebarInspector();
    }

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    // Synchronously paginate before releasing minHeight so the canvas never collapses or jumps
    paginatePoDocument();
    container.style.minHeight = '';
    restorePoScrollPositions(savedRenderScroll);
    setTimeout(() => {
      const s = capturePoScrollPositions();
      updatePoVisualPageBreakGuides();
      restorePoScrollPositions(s);
    }, 120);
    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(() => {
        const s = capturePoScrollPositions();
        updatePoVisualPageBreakGuides();
        restorePoScrollPositions(s);
      });
    }
  }

  function fitPoTextarea(ta) {
    if (!ta) return;
    const scrollContainer = document.getElementById('poCanvasViewport') || document.getElementById('priceOfferingDocPage') || window;
    const prevScroll = scrollContainer === window ? window.scrollY : scrollContainer.scrollTop;

    ta.style.height = 'auto';
    const newHeight = Math.max(26, ta.scrollHeight);
    ta.style.height = newHeight + 'px';

    if (scrollContainer === window) {
      window.scrollTo({ top: prevScroll });
    } else {
      scrollContainer.scrollTop = prevScroll;
    }
  }

  function autoResizePoTextareas() {
    const textareas = document.querySelectorAll('#priceOfferingPrintArea textarea');
    textareas.forEach(ta => fitPoTextarea(ta));
    updatePoVisualPageBreakGuides();
  }

  function handlePoTextareaKeydown(e) {
    const ta = e.target;
    if (!ta) return;

    // Contenteditable rich multiline fields (.po-section-content & .po-item-desc)
    if (ta.isContentEditable && (ta.classList.contains('po-section-content') || ta.classList.contains('po-item-desc'))) {
      if (e.key === 'Tab') {
        e.preventDefault();
        if (!e.shiftKey) {
          document.execCommand('insertText', false, '  ');
        }
        return;
      }
      if (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
        const sel = window.getSelection();
        if (sel && sel.rangeCount > 0 && sel.isCollapsed) {
          const range = sel.getRangeAt(0);
          const node = range.startContainer;
          if (node && node.nodeType === 3) {
            const textBefore = node.nodeValue.slice(0, range.startOffset);
            const lastNl = textBefore.lastIndexOf('\n');
            const currentLine = lastNl >= 0 ? textBefore.slice(lastNl + 1) : textBefore;
            const bulletMatch = currentLine.match(/^(\s*)(•|-|\*)\s+(.*)$/);
            const emptyBulletMatch = currentLine.match(/^(\s*)(•|-|\*)\s*$/);
            if (emptyBulletMatch && currentLine.trim().length <= 1) {
              // Pressing Enter on an empty bullet clears the bullet and exits list
              e.preventDefault();
              const delStart = lastNl >= 0 ? lastNl + 1 : 0;
              node.nodeValue = node.nodeValue.slice(0, delStart) + node.nodeValue.slice(range.startOffset);
              const nr = document.createRange();
              nr.setStart(node, delStart);
              nr.collapse(true);
              sel.removeAllRanges();
              sel.addRange(nr);
              ta.dispatchEvent(new Event('input', { bubbles: true }));
              return;
            } else if (bulletMatch) {
              e.preventDefault();
              const indent = bulletMatch[1];
              const bullet = bulletMatch[2];
              if (ta.classList.contains('po-item-desc')) {
                document.execCommand('insertLineBreak');
                document.execCommand('insertText', false, `${indent}${bullet} `);
              } else {
                document.execCommand('insertParagraph');
                document.execCommand('insertText', false, `${indent}${bullet} `);
              }
              return;
            }
          }
        }
        // In deliverable item descriptions (.po-item-desc), always insert an inline <br> inside the current styled span/font so pressing Enter never breaks out of the rich-text typography wrapper
        if (ta.classList.contains('po-item-desc')) {
          e.preventDefault();
          if (document.queryCommandSupported && document.queryCommandSupported('insertLineBreak')) {
            document.execCommand('insertLineBreak');
          } else if (sel && sel.rangeCount > 0) {
            const range = sel.getRangeAt(0);
            range.deleteContents();
            const br = document.createElement('br');
            range.insertNode(br);
            range.setStartAfter(br);
            range.collapse(true);
            sel.removeAllRanges();
            sel.addRange(range);
          }
          poRememberRichText(ta);
          ta.dispatchEvent(new Event('input', { bubbles: true }));
          return;
        }
      }
      return;
    }

    if (ta.tagName !== 'TEXTAREA') return;

    // Smart Bullet list continuation on Enter
    if (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
      if (ta.classList.contains('po-section-content') || ta.classList.contains('po-item-desc')) {
        const val = ta.value;
        const selStart = ta.selectionStart;
        const lineStart = val.lastIndexOf('\n', selStart - 1) + 1;
        const lineEnd = val.indexOf('\n', selStart);
        const currentLine = val.substring(lineStart, lineEnd === -1 ? val.length : lineEnd);

        const bulletMatch = currentLine.match(/^(\s*)(•|-|\*)\s*/);
        if (bulletMatch) {
          e.preventDefault();
          const indent = bulletMatch[1];
          const bullet = bulletMatch[2];

          // If current line only contains the bullet/whitespace, pressing Enter clears the bullet (exits list)
          const lineTrimmed = currentLine.trim();
          if (lineTrimmed === '•' || lineTrimmed === '-' || lineTrimmed === '*') {
            const before = val.substring(0, lineStart);
            const after = val.substring(selStart);
            ta.value = before + after;
            ta.selectionStart = ta.selectionEnd = lineStart;
            fitPoTextarea(ta);
            updatePoVisualPageBreakGuides();
            triggerPriceOfferingAutoSave(false);
            schedulePoInputSnapshot();
            return;
          }

          // Otherwise continue bullet on next line
          const nextBullet = `\n${indent}${bullet} `;
          const before = val.substring(0, selStart);
          const after = val.substring(selStart);
          ta.value = before + nextBullet + after;
          const nextPos = selStart + nextBullet.length;
          ta.selectionStart = ta.selectionEnd = nextPos;
          fitPoTextarea(ta);
          updatePoVisualPageBreakGuides();
          triggerPriceOfferingAutoSave(false);
          schedulePoInputSnapshot();
          return;
        }
      }
    }

    // Tab key indent/unindent
    if (e.key === 'Tab') {
      if (ta.classList.contains('po-section-content')) {
        e.preventDefault();
        const selStart = ta.selectionStart;
        const selEnd = ta.selectionEnd;
        const val = ta.value;
        if (!e.shiftKey) {
          ta.value = val.substring(0, selStart) + '  ' + val.substring(selEnd);
          ta.selectionStart = ta.selectionEnd = selStart + 2;
        } else {
          const lineStart = val.lastIndexOf('\n', selStart - 1) + 1;
          if (val.substring(lineStart, lineStart + 2) === '  ') {
            ta.value = val.substring(0, lineStart) + val.substring(lineStart + 2);
            ta.selectionStart = ta.selectionEnd = Math.max(lineStart, selStart - 2);
          }
        }
        fitPoTextarea(ta);
        updatePoVisualPageBreakGuides();
        triggerPriceOfferingAutoSave(false);
        schedulePoInputSnapshot();
        return;
      }
    }
  }

  function formatPoDisplayDate(dateStr) {
    if (!dateStr) return '';
    try {
      const parts = dateStr.split('-');
      if (parts.length === 3) {
        const d = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
        if (!isNaN(d.getTime())) {
          return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
        }
      }
    } catch (e) {}
    return dateStr;
  }

  function syncPoRunningHeaders() {
    const docTitle = document.getElementById('poDocHeading')?.value || 'Price Quote / Proposal';
    const clientName = document.getElementById('poClientName')?.value || 'Client';
    const refNo = document.getElementById('poRefNo')?.value || '';

    document.querySelectorAll('.po-running-title').forEach(el => el.textContent = docTitle);
    document.querySelectorAll('.po-running-client').forEach(el => el.textContent = clientName);
    document.querySelectorAll('.po-running-ref').forEach(el => el.textContent = refNo);
  }

  function syncPriceOfferingTableMirrors() {
    const rows = document.querySelectorAll('#poItemsTableBody tr');
    const cur = getPoCurrency();

    rows.forEach((row, idx) => {
      const descInput = row.querySelector('.po-item-desc');
      const descPrint = row.querySelector('.po-item-desc-print');
      if (descInput && descPrint) descPrint.textContent = descInput.value;

      const qtyInput = row.querySelector('.po-item-qty');
      const qtyPrint = row.querySelector('.po-item-qty-print');
      if (qtyInput && qtyPrint) qtyPrint.textContent = qtyInput.value;

      const rateInput = row.querySelector('.po-item-rate');
      const ratePrint = row.querySelector('.po-item-rate-print');
      if (rateInput && ratePrint) {
        const r = parseFloat(rateInput.value) || 0;
        ratePrint.textContent = formatMoney(r, cur);
      }
    });

    const issueDateInput = document.getElementById('poIssueDate');
    const issueDatePrint = document.querySelector('.po-issue-date-print');
    if (issueDateInput && issueDatePrint) {
      issueDatePrint.textContent = issueDateInput.value;
    }

    const validDateInput = document.getElementById('poValidUntil');
    const validDatePrint = document.querySelector('.po-valid-date-print');
    if (validDateInput && validDatePrint) {
      validDatePrint.textContent = validDateInput.value;
    }

    const curPrint = document.querySelector('.po-cur-print');
    if (curPrint) {
      const symbol = CURRENCY_SYMBOLS[cur] || cur;
      curPrint.textContent = `${cur} (${symbol})`;
    }

    document.querySelectorAll('#priceOfferingPrintArea .po-section-content').forEach(ta => {
      const parent = ta.parentElement;
      const printDiv = parent ? parent.querySelector('.po-section-content-print') : null;
      if (printDiv) {
        printDiv.textContent = ta.value;
      }
    });
  }

  function renderPriceOfferingItemsTable() {
    const tbody = document.getElementById('poItemsTableBody');
    if (!tbody) return;

    const cur = getPoCurrency();

    if (currentPoItems.length === 0) {
      tbody.innerHTML = `
        <tr class="no-print">
          <td colspan="5" class="py-4 text-center text-xs text-slate-400 select-none">
            No items added yet. Click &quot;Add Deliverable / Item&quot; below.
          </td>
        </tr>
      `;
      autoResizePoTextareas();
      return;
    }

    tbody.innerHTML = currentPoItems.map((item, idx) => {
      const q = parseFloat(item.qty) || 1;
      const r = parseFloat(item.rate) || 0;
      const amt = q * r;
      item.amount = amt;

      return `
        <tr class="hover:bg-slate-50/50 transition-colors group/row" data-item-id="${escapeHtml(item.id)}">
          <td class="po-col-desc py-2 px-3">
            <textarea rows="1" class="po-selectable po-item-desc po-doc-text text-xs font-medium text-slate-800 placeholder-slate-400" data-elem-id="item_desc_${idx}" data-elem-name="Item ${idx + 1} Description" data-elem-type="text" placeholder="Deliverable / Milestone description..." data-index="${idx}">${escapeHtml(item.description || '')}</textarea>
          </td>
          <td class="po-col-qty py-2 px-3 text-center">
            <input type="number" step="any" min="0" class="po-item-qty w-16 text-center font-mono text-xs text-slate-700 bg-transparent border-none outline-none focus:outline-none" value="${q}" data-index="${idx}">
          </td>
          <td class="po-col-rate py-2 px-3 text-right">
            <input type="number" step="any" min="0" class="po-item-rate w-24 text-right font-mono text-xs text-slate-700 bg-transparent border-none outline-none focus:outline-none" placeholder="0" value="${r > 0 ? r : ''}" data-index="${idx}">
          </td>
          <td class="po-col-amount py-2 px-3 text-right font-mono font-semibold text-slate-900 po-item-amount-display po-selectable cursor-pointer" data-elem-id="item_amount_${idx}" data-elem-name="Item ${idx + 1} Amount" data-elem-type="text">
            ${formatMoney(amt, cur)}
          </td>
          <td class="py-2 px-2 text-center po-edit-cell">
            <button type="button" class="po-delete-item-btn text-slate-300 hover:text-rose-600 hover:bg-rose-50 p-1 rounded-lg opacity-0 group-hover/row:opacity-100 transition-opacity cursor-pointer" data-index="${idx}" title="Delete item">
              <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
            </button>
          </td>
        </tr>
      `;
    }).join('');

    poConvertInputsToFields(tbody);
    applySavedElementStyles();
    autoResizePoTextareas();

    if (poSelectedElementId) {
      const selEl = tbody.querySelector(`[data-elem-id="${poSelectedElementId}"]`);
      if (selEl) selEl.classList.add('po-selected-element');
    }

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function addPriceOfferingItem() {
    pushPoUndoSnapshot();
    flushLivePoDomToState();
    const newIdx = currentPoItems.length;
    currentPoItems.push({
      id: 'po_item_' + Date.now(),
      description: '',
      qty: 1,
      rate: 0,
      amount: 0
    });
    // Inherit deliverable row 0 element styles so new deliverable rows match existing typography
    ['desc', 'qty', 'rate', 'amount'].forEach(f => {
      const baseStyle = poElementStyles[`item_${f}_0`];
      if (baseStyle && !poElementStyles[`item_${f}_${newIdx}`]) {
        poElementStyles[`item_${f}_${newIdx}`] = JSON.parse(JSON.stringify(baseStyle));
      }
    });
    renderPriceOfferingItemsTable();
    recalculatePriceOfferingTotals();
    triggerPriceOfferingAutoSave(true);
    const rows = document.querySelectorAll('#poItemsTableBody .po-item-desc');
    if (rows.length > 0) {
      const last = rows[rows.length - 1];
      last.focus();
    }
  }

  function recalculatePriceOfferingTotals() {
    const cur = getPoCurrency();

    document.querySelectorAll('.poTableCurrencyLabel').forEach(el => el.textContent = cur);

    let subtotal = 0;
    const rows = document.querySelectorAll('#poItemsTableBody tr');
    rows.forEach((row, idx) => {
      const qtyInput = row.querySelector('.po-item-qty');
      const rateInput = row.querySelector('.po-item-rate');
      const amtDisplay = row.querySelector('.po-item-amount-display');

      const q = parseFloat(qtyInput?.value) || 0;
      const r = parseFloat(rateInput?.value) || 0;
      const amt = q * r;
      subtotal += amt;

      if (amtDisplay) amtDisplay.textContent = formatMoney(amt, cur);
      if (currentPoItems[idx]) {
        currentPoItems[idx].qty = q;
        currentPoItems[idx].rate = r;
        currentPoItems[idx].amount = amt;
      }
    });

    const discInput = document.getElementById('poDiscountPercentInput');
    if (discInput) {
      discInput.style.width = `${Math.max(1, String(discInput.value || '0').trim().length)}ch`;
    }
    const discPercent = parseFloat(discInput?.value) || 0;
    const discAmt = (subtotal * discPercent) / 100;
    const afterDisc = Math.max(0, subtotal - discAmt);

    const taxInput = document.getElementById('poTaxPercentInput');
    if (taxInput) {
      taxInput.style.width = `${Math.max(1, String(taxInput.value || '0').trim().length)}ch`;
    }
    const taxPercent = parseFloat(taxInput?.value) || 0;
    const taxAmt = (afterDisc * taxPercent) / 100;

    const total = afterDisc + taxAmt;

    const subtotalEl = document.getElementById('poSubtotalDisplay');
    if (subtotalEl) subtotalEl.textContent = formatMoney(subtotal, cur);

    const discAmtEl = document.getElementById('poDiscountAmountDisplay');
    if (discAmtEl) discAmtEl.textContent = `-${formatMoney(discAmt, cur)}`;

    const taxAmtEl = document.getElementById('poTaxAmountDisplay');
    if (taxAmtEl) taxAmtEl.textContent = `+${formatMoney(taxAmt, cur)}`;

    const totalEl = document.getElementById('poTotalAmountDisplay');
    if (totalEl) totalEl.textContent = formatMoney(total, cur);

    // Hide or format discount row
    const discRow = document.getElementById('poDiscountRow');
    const discPrint = document.getElementById('poDiscountPercentPrint');
    const addDiscTrigger = document.getElementById('poAddDiscountTriggerBtn');
    const addTaxTrigger = document.getElementById('poAddTaxTriggerBtn');
    const addDiscTaxBar = document.getElementById('poAddDiscountTaxBar');

    if (discRow) {
      if (discPercent > 0) {
        discRow.classList.remove('hidden');
        discRow.classList.add('flex');
        if (discPrint) discPrint.textContent = ` (${discPercent}%)`;
        if (addDiscTrigger) addDiscTrigger.classList.add('hidden');
      } else {
        discRow.classList.add('hidden');
        discRow.classList.remove('flex');
        if (discPrint) discPrint.textContent = '';
        if (addDiscTrigger) addDiscTrigger.classList.remove('hidden');
      }
    }

    // Hide or format tax row
    const taxRow = document.getElementById('poTaxRow');
    const taxPrint = document.getElementById('poTaxPercentPrint');
    if (taxRow) {
      if (taxPercent > 0) {
        taxRow.classList.remove('hidden');
        taxRow.classList.add('flex');
        if (taxPrint) taxPrint.textContent = ` (${taxPercent}%)`;
        if (addTaxTrigger) addTaxTrigger.classList.add('hidden');
      } else {
        taxRow.classList.add('hidden');
        taxRow.classList.remove('flex');
        if (taxPrint) taxPrint.textContent = '';
        if (addTaxTrigger) addTaxTrigger.classList.remove('hidden');
      }
    }

    if (addDiscTaxBar) {
      if (discPercent > 0 && taxPercent > 0) {
        addDiscTaxBar.classList.add('hidden');
      } else {
        addDiscTaxBar.classList.remove('hidden');
      }
    }

    syncPriceOfferingTableMirrors();

    return { subtotal, discPercent, discAmt, taxPercent, taxAmt, total, currency: cur };
  }

  function triggerPriceOfferingAutoSave(immediate = false) {
    if (poHoverPreviewBackup) return;
    const poPage = document.getElementById('priceOfferingDocPage');
    if (poPage && poPage.classList && poPage.classList.contains('hidden')) return;
    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    if (!leadId) return;

    clearTimeout(poAutoSaveTimeout);
    poAutoSaveTimeout = null;

    if (!poStatusBadgeFlashTimer && !poEditingTemplateDesignId) {
      const statusBadgeText = document.getElementById('priceOfferingSaveStatusText');
      const statusDot = document.getElementById('priceOfferingSaveStatusDot');
      if (statusBadgeText) statusBadgeText.textContent = 'Saving...';
      if (statusDot) statusDot.className = 'w-1.5 h-1.5 rounded-full bg-amber-400 animate-pulse shrink-0';
    }

    if (immediate) {
      savePriceOfferingDoc(false);
      return;
    }

    poAutoSaveTimeout = setTimeout(() => {
      poAutoSaveTimeout = null;
      savePriceOfferingDoc(false);
    }, 500);
  }

  const PO_LABEL_ELEM_MAP = {
    client: ['label_client', 'Client / Recipient'],
    reference: ['label_ref', 'Reference'],
    currency: ['label_cur', 'Currency'],
    issueDate: ['label_issue_date', 'Date Issued'],
    validUntil: ['label_valid_until', 'Valid Until'],
    project: ['label_project', 'Project / Assignment'],
    thDesc: ['th_desc', 'Deliverable / Description'],
    thQty: ['th_qty', 'Qty'],
    thRate: ['th_rate', 'Rate'],
    thAmount: ['th_amount', 'Amount'],
    subtotal: ['label_subtotal', 'Subtotal'],
    discount: ['label_discount', 'Discount'],
    tax: ['label_tax', 'VAT / Tax'],
    totalInvestment: ['label_total_investment', 'Total Investment']
  };

  // Reads every editable label from the document (falls back to previously saved values, then defaults)
  function readPoLabels(prev) {
    const out = {};
    Object.keys(PO_LABEL_ELEM_MAP).forEach(key => {
      const [elemId, def] = PO_LABEL_ELEM_MAP[key];
      const el = document.querySelector(`#priceOfferingPrintArea [data-elem-id="${elemId}"]`);
      if (el && typeof el.value === 'string' && el.value.trim() !== '') {
        out[key] = el.value;
      } else if (prev && prev[key] !== undefined && String(prev[key]).trim() !== '') {
        out[key] = prev[key];
      } else {
        out[key] = def;
      }
    });
    return out;
  }

  function isPlaceholderClientName(name) {
    if (!name || typeof name !== 'string') return true;
    const trimmed = name.trim();
    if (!trimmed) return true;
    if (/^\[.*\]$/.test(trimmed)) return true;
    const lower = trimmed.toLowerCase();
    return lower === 'client' || lower === 'client name' || lower === 'client / recipient' || lower === 'recipient' || lower === 'bill to / client' || lower.includes('[client');
  }

  function savePriceOfferingDoc(showNotification = true) {
    clearTimeout(poAutoSaveTimeout);
    poAutoSaveTimeout = null;
    if (poHoverPreviewBackup) return null;
    const poPage = document.getElementById('priceOfferingDocPage');
    if (poPage && poPage.classList && poPage.classList.contains('hidden')) return null;
    const leadId = state.activePriceOfferingLeadId || state.activeDepositProformaProjectId || state.activeProformaProjectId || state.activeFollowupLeadId || state.activeFollowupProjectId;
    const lead = getPoEditorTarget(leadId);
    if (!lead) return null;

    // Ensure any in-flight rich text edits inside .po-field elements are synced to poRichText
    document.querySelectorAll('#priceOfferingPrintArea .po-field').forEach(el => poRememberRichText(el));

    // Collect in-flight item descriptions
    const descInputs = document.querySelectorAll('#poItemsTableBody .po-item-desc');
    descInputs.forEach((inp) => {
      const idx = parseInt(inp.getAttribute('data-index'), 10);
      if (!isNaN(idx) && currentPoItems[idx]) {
        currentPoItems[idx].description = inp.value;
      }
    });

    // Collect in-flight section titles & content
    document.querySelectorAll('#priceOfferingPrintArea .po-section-title-input').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = currentPoSections.find(s => s.id === secId);
      if (sec) sec.title = inp.value;
    });

    document.querySelectorAll('#priceOfferingPrintArea .po-section-content').forEach(ta => {
      const secId = ta.getAttribute('data-sec-id');
      const sec = currentPoSections.find(s => s.id === secId);
      if (sec) sec.content = poCleanContentHtml(ta);
    });

    document.querySelectorAll('#priceOfferingPrintArea .po-client-sign-title').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = currentPoSections.find(s => s.id === secId);
      if (sec) sec.clientTitle = inp.value;
    });

    document.querySelectorAll('#priceOfferingPrintArea .po-provider-sign-title').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = currentPoSections.find(s => s.id === secId);
      if (sec) sec.providerTitle = inp.value;
    });

    // Collect in-flight signature block labels
    document.querySelectorAll('#priceOfferingPrintArea .po-sign-seal-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = currentPoSections.find(s => s.id === secId);
      if (sec) sec.signSealText = inp.value;
    });
    document.querySelectorAll('#priceOfferingPrintArea .po-sign-date-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = currentPoSections.find(s => s.id === secId);
      if (sec) sec.signDateText = inp.value;
    });
    document.querySelectorAll('#priceOfferingPrintArea .po-sign-name-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = currentPoSections.find(s => s.id === secId);
      if (sec) sec.signNameText = inp.value;
    });
    document.querySelectorAll('#priceOfferingPrintArea .po-sign-seal-provider-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = currentPoSections.find(s => s.id === secId);
      if (sec) sec.signSealProviderText = inp.value;
    });
    document.querySelectorAll('#priceOfferingPrintArea .po-sign-date-provider-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = currentPoSections.find(s => s.id === secId);
      if (sec) sec.signDateProviderText = inp.value;
    });
    document.querySelectorAll('#priceOfferingPrintArea .po-sign-name-provider-label').forEach(inp => {
      const secId = inp.getAttribute('data-sec-id');
      const sec = currentPoSections.find(s => s.id === secId);
      if (sec) sec.signNameProviderText = inp.value;
    });

    const labelsObj = readPoLabels(lead.priceOffering?.labels);

    const totals = recalculatePriceOfferingTotals();

    const senderObj = {
      name: document.getElementById('poSenderName')?.value || '',
      title: document.getElementById('poSenderTitle')?.value || '',
      contact: document.getElementById('poSenderContact')?.value || '',
      location: document.getElementById('poSenderLocation')?.value || ''
    };

    if (!lead._isStudioDoc) {
      try {
        localStorage.setItem('ft_po_sender_info', JSON.stringify(senderObj));
      } catch (e) {}
    }

    let finalDocTitle = document.getElementById('poDocHeading')?.value || '';
    if (lead._isDepositProforma || state.activeDepositProformaProjectId) {
      if (!finalDocTitle || finalDocTitle.includes('Price Quote') || finalDocTitle.includes('Proposal') || finalDocTitle === 'PROFORMA INVOICE') {
        finalDocTitle = 'DEPOSIT PROFORMA INVOICE';
      }
    } else if (lead._isProforma || state.activeProformaProjectId) {
      if (!finalDocTitle || finalDocTitle.includes('Price Quote') || finalDocTitle.includes('Proposal') || finalDocTitle.includes('DEPOSIT')) {
        finalDocTitle = 'PROFORMA INVOICE';
      }
    } else if (!lead._isStudioDoc) {
      if (!finalDocTitle || finalDocTitle.includes('PROFORMA')) {
        finalDocTitle = 'Price Quote / Proposal';
      }
    }

    const curRefPrefix = (lead._isDepositProforma || state.activeDepositProformaProjectId) ? 'DPI' : ((lead._isProforma || state.activeProformaProjectId) ? 'PI' : 'PO');

    const offeringData = {
      templateId: activePoTemplateId || lead.priceOffering?.templateId || 'tpl_studio_master',
      docTitle: finalDocTitle,
      docSubtitle: document.getElementById('poDocSubtitle')?.value || '',
      accentColor: currentPoAccentColor,
      refNo: document.getElementById('poRefNo')?.value || `${curRefPrefix}-2026-001`,
      issueDate: document.getElementById('poIssueDate')?.value || '',
      validUntil: document.getElementById('poValidUntil')?.value || '',
      currency: totals.currency,
      sender: senderObj,
      labels: labelsObj,
      typography: Object.assign({}, activePoTypography),
      elementStyles: Object.assign({}, poElementStyles),
      richText: JSON.parse(JSON.stringify(poRichText || {})),
      client: document.getElementById('poClientName')?.value || lead.client || '',
      clientEmail: document.getElementById('poClientEmail')?.value || '',
      clientAddress: document.getElementById('poClientAddress')?.value || '',
      projectTitle: document.getElementById('poProjectTitle')?.value || lead.title || '',
      items: currentPoItems,
      sections: currentPoSections,
      signatures: JSON.parse(JSON.stringify(currentPoSignatures || [])),
      subtotal: totals.subtotal,
      discountPercent: totals.discPercent,
      taxPercent: totals.taxPercent,
      total: totals.total,
      scope: (currentPoSections.find(s => s.type === 'scope') || {}).content || '',
      timeline: (currentPoSections.find(s => s.type === 'timeline') || {}).content || '',
      terms: (currentPoSections.find(s => s.type === 'terms') || {}).content || '',
      conditions: (currentPoSections.find(s => s.type === 'conditions') || {}).content || '',
      _studioDoc: !!lead._isStudioDoc,
      _isDepositProforma: !!lead._isDepositProforma,
      _isProforma: !!lead._isProforma,
      _structuralMigrated: true,
      updatedAt: new Date().toISOString()
    };

    const prevOfferingSnapshot = lead.priceOffering ? JSON.parse(JSON.stringify(lead.priceOffering)) : null;
    const prevQuoteTotal = (prevOfferingSnapshot && !isNaN(parseFloat(prevOfferingSnapshot.total))) ? parseFloat(prevOfferingSnapshot.total) : null;
    const prevQuoteCur = (prevOfferingSnapshot && prevOfferingSnapshot.currency) ? prevOfferingSnapshot.currency : null;
    lead.priceOffering = offeringData;

    if (lead._isStudioDoc && lead._docRef) {
      const doc = lead._docRef;
      let persistedStudioJson = '';
      let persistedUpdatedAt = doc.studioData && doc.studioData.updatedAt ? doc.studioData.updatedAt : doc.updatedAt;
      try {
        const rawStored = localStorage.getItem(STORAGE_KEYS.DOCUMENTS);
        if (rawStored) {
          const parsedStored = JSON.parse(rawStored);
          if (Array.isArray(parsedStored)) {
            const latestDoc = parsedStored.find(d => d && d.id === doc.id);
            if (latestDoc) {
              if (latestDoc.isDraft !== undefined) doc.isDraft = latestDoc.isDraft;
              if (latestDoc.pinned !== undefined) doc.pinned = latestDoc.pinned;
              if (latestDoc.title) doc.title = latestDoc.title;
              if (latestDoc.subtitle !== undefined) doc.subtitle = latestDoc.subtitle;
              if (latestDoc.category) doc.category = latestDoc.category;
              if (latestDoc.expiryDate !== undefined) doc.expiryDate = latestDoc.expiryDate;
              if (latestDoc.createdAt) doc.createdAt = latestDoc.createdAt;
              if (latestDoc.studioData) {
                persistedStudioJson = JSON.stringify(Object.assign({}, latestDoc.studioData, { updatedAt: undefined }));
                if (latestDoc.studioData.updatedAt) persistedUpdatedAt = latestDoc.studioData.updatedAt;
              }
            }
          }
        }
      } catch (e) {}
      const prevStudioJson = persistedStudioJson || (doc.studioData ? JSON.stringify(Object.assign({}, doc.studioData, { updatedAt: undefined })) : '');
      const nextStudioJson = JSON.stringify(Object.assign({}, offeringData, { updatedAt: undefined }));
      const hasContentChange = prevStudioJson !== nextStudioJson;
      if (!hasContentChange && persistedUpdatedAt) {
        offeringData.updatedAt = persistedUpdatedAt;
      }
      doc.studioData = offeringData;
      if (hasContentChange || showNotification) {
        doc.updatedAt = offeringData.updatedAt;
        doc.isEdited = true;
      }
      const bcClient = document.getElementById('priceOfferingDocClientBreadcrumb');
      if (bcClient) bcClient.textContent = doc.title || 'Document';
      const typeLabelEl = document.getElementById('priceOfferingDocTypeLabel');
      if (typeLabelEl) {
        const catMeta = DOC_CATEGORY_META[doc.category || 'other'] || DOC_CATEGORY_META.other || { label: 'Document' };
        typeLabelEl.textContent = `${catMeta.label} · A4 Studio Editor`;
      }
      saveDocuments(doc.id);
      if (!poStatusBadgeFlashTimer) {
        syncPoStatusBadgeRestingState();
      }
      if (showNotification) {
        showToast('Saved ✓', `"${doc.title}" saved.`, 'success');
      }
      return offeringData;
    }

    if (lead._isDepositProforma && lead._projectRef) {
      const proj = lead._projectRef;
      const prevDraftFp = prevOfferingSnapshot ? getPoContentFingerprint(prevOfferingSnapshot) : '';
      const prevUpdatedAt = prevOfferingSnapshot && prevOfferingSnapshot.updatedAt ? prevOfferingSnapshot.updatedAt : null;
      offeringData._isDepositProforma = true;
      offeringData._isProforma = false;
      if (!showNotification && prevUpdatedAt && prevDraftFp && getPoContentFingerprint(offeringData) === prevDraftFp) {
        offeringData.updatedAt = prevUpdatedAt;
      }
      proj.depositProforma = offeringData;
      proj.hasDepositProformaDoc = true;

      if (offeringData.client && offeringData.client.trim() && !isPlaceholderClientName(offeringData.client)) {
        proj.client = offeringData.client.trim();
      }
      const bcClient = document.getElementById('priceOfferingDocClientBreadcrumb');
      if (bcClient) bcClient.textContent = proj.client || offeringData.client || 'Project';

      if (!proj.title && offeringData.projectTitle && offeringData.projectTitle.trim()) {
        proj.title = offeringData.projectTitle.trim();
        proj.description = proj.title;
      }
      if (offeringData.validUntil) {
        proj.paymentDueDate = offeringData.validUntil;
      }

      saveBudget();

      if (!poEditingTemplateNameId && !poPreviewingTemplateId) {
        renderPoSavedTemplatesGallery();
      } else {
        updatePoTemplateScopeBanner();
      }

      if (!poStatusBadgeFlashTimer) {
        syncPoStatusBadgeRestingState();
      }

      renderPoVersionsDropdown();

      if (showNotification) {
        showToast('Deposit Proforma Saved ✓', `Deposit proforma for "${proj.client || 'Project'}" saved.`, 'success');
      }

      return offeringData;
    }

    if (lead._isProforma && lead._projectRef) {
      const proj = lead._projectRef;
      const prevDraftFp = prevOfferingSnapshot ? getPoContentFingerprint(prevOfferingSnapshot) : '';
      const prevUpdatedAt = prevOfferingSnapshot && prevOfferingSnapshot.updatedAt ? prevOfferingSnapshot.updatedAt : null;
      offeringData._isProforma = true;
      if (!showNotification && prevUpdatedAt && prevDraftFp && getPoContentFingerprint(offeringData) === prevDraftFp) {
        offeringData.updatedAt = prevUpdatedAt;
      }
      proj.proformaInvoice = offeringData;
      proj.hasProformaDoc = true;

      if (offeringData.client && offeringData.client.trim() && !isPlaceholderClientName(offeringData.client)) {
        proj.client = offeringData.client.trim();
      }
      const bcClient = document.getElementById('priceOfferingDocClientBreadcrumb');
      if (bcClient) bcClient.textContent = proj.client || offeringData.client || 'Project';

      if (!proj.title && offeringData.projectTitle && offeringData.projectTitle.trim()) {
        proj.title = offeringData.projectTitle.trim();
        proj.description = proj.title;
      }
      if (offeringData.validUntil) {
        proj.paymentDueDate = offeringData.validUntil;
      }
      const hasQuoteTotal = proj.priceOffering && !isNaN(parseFloat(proj.priceOffering.total)) && parseFloat(proj.priceOffering.total) > 0;
      const isPlaceholderItem = currentPoItems.some(it =>
        it && it.description && /\[PROJECT TITLE|COMPLETED CREATIVE SCOPE|DPI REFERENCE\]/i.test(it.description)
      );
      const prevProformaTotal = (prevOfferingSnapshot && !isNaN(parseFloat(prevOfferingSnapshot.total))) ? parseFloat(prevOfferingSnapshot.total) : null;
      const proformaTotalChanged = prevProformaTotal !== null && Math.abs(totals.total - prevProformaTotal) > 0.005;
      const hasEstablishedFee = (parseFloat(proj.fee !== undefined ? proj.fee : proj.amount) || 0) > 0;

      if (!isPlaceholderItem && currentPoItems.length > 0 && !isNaN(totals.total) && totals.total >= 0) {
        if ((!hasEstablishedFee && !hasQuoteTotal) || (proformaTotalChanged && !hasQuoteTotal)) {
          proj.amount = totals.total;
          proj.fee = totals.total;
          proj.currency = totals.currency;
        }
      }

      saveBudget();

      if (!poEditingTemplateNameId && !poPreviewingTemplateId) {
        renderPoSavedTemplatesGallery();
      } else {
        updatePoTemplateScopeBanner();
      }

      if (!poStatusBadgeFlashTimer) {
        syncPoStatusBadgeRestingState();
      }

      renderPoVersionsDropdown();

      if (showNotification) {
        showToast('Proforma Invoice Saved ✓', `Proforma invoice for "${proj.client || 'Project'}" saved.`, 'success');
      }

      return offeringData;
    }

    const prevLeadDraftFp = lead._prevPriceOfferingFp || (prevOfferingSnapshot ? getPoContentFingerprint(prevOfferingSnapshot) : '');
    const prevLeadUpdatedAt = lead._prevPriceOfferingUpdatedAt || (prevOfferingSnapshot && prevOfferingSnapshot.updatedAt ? prevOfferingSnapshot.updatedAt : null);
    if (!showNotification && prevLeadUpdatedAt && prevLeadDraftFp && getPoContentFingerprint(offeringData) === prevLeadDraftFp) {
      offeringData.updatedAt = prevLeadUpdatedAt;
    }
    lead._prevPriceOfferingFp = getPoContentFingerprint(offeringData);
    lead._prevPriceOfferingUpdatedAt = offeringData.updatedAt;

    // Automatically keep ledger values in sync in background
    if (offeringData.client && offeringData.client.trim() && !isPlaceholderClientName(offeringData.client)) {
      lead.client = offeringData.client.trim();
      if (lead._projectRef) lead._projectRef.client = offeringData.client.trim();
    }
    const bcClient = document.getElementById('priceOfferingDocClientBreadcrumb');
    if (bcClient) bcClient.textContent = lead.client || offeringData.client || 'Client';
    if (!lead.title && offeringData.projectTitle && offeringData.projectTitle.trim() && !isPlaceholderClientName(offeringData.projectTitle)) {
      lead.title = offeringData.projectTitle.trim();
    }
    const isOngoingProjEntity = (state.budget?.projects || []).some(p => p.id === lead.id);
    if (currentPoItems.length > 0 && !isNaN(totals.total) && totals.total >= 0) {
      if (!isOngoingProjEntity) {
        lead.amount = totals.total;
        if (lead.fee !== undefined) lead.fee = totals.total;
        lead.currency = totals.currency;
      } else if (!lead.proformaInvoice) {
        const projFeeVal = parseFloat(lead.fee !== undefined ? lead.fee : lead.amount) || 0;
        const quoteTotalChanged = prevQuoteTotal !== null && Math.abs(totals.total - prevQuoteTotal) > 0.005;
        const quoteCurChanged = prevQuoteCur !== null && totals.currency !== prevQuoteCur;
        if (projFeeVal === 0 || quoteTotalChanged || quoteCurChanged) {
          lead.amount = totals.total;
          lead.fee = totals.total;
          lead.currency = totals.currency;
        }
      }
      if (lead._projectRef && !lead._projectRef.proformaInvoice) {
        lead._projectRef.amount = totals.total;
        lead._projectRef.fee = totals.total;
        lead._projectRef.currency = totals.currency;
      }
    }

    saveBudget();

    if (!poEditingTemplateNameId && !poPreviewingTemplateId) {
      renderPoSavedTemplatesGallery();
    } else {
      updatePoTemplateScopeBanner();
    }

    if (!poStatusBadgeFlashTimer) {
      syncPoStatusBadgeRestingState();
    }

    renderPoVersionsDropdown();

    if (showNotification) {
      showToast('Price Offering Saved ✓', `Proposal for ${lead.client || 'lead'} saved to your ledger.`, 'success');
    }

    return offeringData;
  }

  function syncPoEditorModeUI(isStudioDoc) {
    const quoteOnlyTypes = ['deliverables', 'terms', 'conditions', 'acceptance'];
    document.querySelectorAll('.po-sidebar-add-choice').forEach(btn => {
      const t = btn.getAttribute('data-type');
      if (quoteOnlyTypes.includes(t)) {
        btn.classList.toggle('hidden', !!isStudioDoc);
      }
    });
    document.getElementById('poTemplatesSidebarSection')?.classList.toggle('hidden', !!isStudioDoc);
    document.getElementById('poStudioDocFooterSection')?.classList.toggle('hidden', !isStudioDoc);
    document.getElementById('poVersionsDropdownWrapper')?.classList.toggle('hidden', !!isStudioDoc);
    document.getElementById('poVersionsDropdownMenu')?.classList.add('hidden');
    if (!isStudioDoc) {
      renderPoVersionsDropdown();
    }
    const sidebarHeaderTitle = document.getElementById('poSidebarHeaderTitle');
    if (sidebarHeaderTitle && !poSelectedElementId) {
      sidebarHeaderTitle.textContent = isStudioDoc ? 'Page & Layout' : 'Page & Template';
    }
    const copyBtn = document.getElementById('copyPriceOfferingSummaryBtn');
    if (copyBtn) {
      copyBtn.title = isStudioDoc ? 'Copy Document Text' : 'Copy Proposal Summary';
    }
    updatePoDocTypeSwitcherPills();
  }

  function getActiveDocType() {
    if (typeof poEditingMasterTemplateType !== 'undefined' && poEditingMasterTemplateType) return poEditingMasterTemplateType;
    if (state.activeDepositProformaProjectId) return 'deposit_proforma';
    if (state.activeProformaProjectId) return 'proforma';
    const target = typeof getPoEditorTarget === 'function' ? getPoEditorTarget() : null;
    if (target?._isDepositProforma || target?.priceOffering?._isDepositProforma) return 'deposit_proforma';
    if (target?._isProforma || target?.priceOffering?._isProforma) return 'proforma';
    if (target?._isStudioDoc || target?.priceOffering?._studioDoc) return 'studio';
    return 'price_quote';
  }

  function updatePoDocTypeSwitcherPills() {
    const pills = document.getElementById('poDocTypeSwitcherPills');
    if (!pills) return;
    pills.classList.add('hidden');
    pills.classList.remove('inline-flex');
  }

  function openPriceOfferingDocPage(leadId) {
    if (!leadId) leadId = state.activeFollowupLeadId || state.activeFollowupProjectId;
    if (!leadId) return;

    const isProj = (state.budget?.projects || []).some(p => p.id === leadId);
    const lead = (state.budget?.leads || []).find(l => l.id === leadId)
      || (state.budget?.projects || []).find(p => p.id === leadId);
    if (!lead) return;

    clearTimeout(poAutoSaveTimeout);
    poAutoSaveTimeout = null;
    state.activeStudioDocId = null;
    state.activeProformaProjectId = null;
    state.activePriceOfferingLeadId = leadId;
    if (isProj) {
      state.activeFollowupProjectId = leadId;
      state.activeFollowupLeadId = null;
    } else {
      state.activeFollowupLeadId = leadId;
    }
    poEditingTemplateDesignId = null;
    poTemplateDesignEditBackup = null;
    poEditingTemplateNameId = null;

    syncPoEditorModeUI(false);
    const typeLabel = document.getElementById('priceOfferingDocTypeLabel');
    if (typeLabel) typeLabel.textContent = 'Price Quote · A4 Editor';

    try {
      const offeringRoute = isProj
        ? ('#project_followup/' + leadId + '/offering')
        : ('#project_followup/lead:' + leadId + '/offering');
      history.replaceState(null, '', offeringRoute);
      recordFinlandRoute(offeringRoute);
    } catch (e) {}

    // Switch view
    document.getElementById('projectFollowupOverview')?.classList.add('hidden');
    document.getElementById('projectDetailPage')?.classList.add('hidden');
    document.getElementById('leadDetailPage')?.classList.add('hidden');
    const poPage = document.getElementById('priceOfferingDocPage');
    if (poPage) poPage.classList.remove('hidden');

    // Breadcrumb
    const bcClient = document.getElementById('priceOfferingDocClientBreadcrumb');
    if (bcClient) bcClient.textContent = lead.client || 'Client';

    const statusBadgeText = document.getElementById('priceOfferingSaveStatusText');
    const statusDot = document.getElementById('priceOfferingSaveStatusDot');
    if (statusBadgeText) statusBadgeText.textContent = lead.priceOffering ? 'Document Only · Saved' : 'Document Only · Draft';
    if (statusDot) {
      statusDot.className = lead.priceOffering ? 'w-1.5 h-1.5 rounded-full bg-emerald-500' : 'w-1.5 h-1.5 rounded-full bg-slate-300';
    }

    const po = lead.priceOffering || {};
    const masterTpl = getMasterPoTemplate();

    // Restore per-element InDesign-style styles (deep-merging master template with lead overrides so all leads match)
    const baseElementStyles = JSON.parse(JSON.stringify(masterTpl.elementStyles || {}));
    const leadElementStyles = (po.elementStyles && typeof po.elementStyles === 'object') ? JSON.parse(JSON.stringify(po.elementStyles)) : {};
    poElementStyles = {};
    const allElemKeys = new Set([...Object.keys(baseElementStyles), ...Object.keys(leadElementStyles)]);
    allElemKeys.forEach(k => {
      poElementStyles[k] = Object.assign({}, baseElementStyles[k] || {}, leadElementStyles[k] || {});
    });
    poRichText = Object.assign(
      {},
      JSON.parse(JSON.stringify(masterTpl.richText || {})),
      (po.richText && typeof po.richText === 'object') ? JSON.parse(JSON.stringify(po.richText)) : {}
    );
    poSelectedElementId = null;
    poSelectedElementMeta = null;

    const defaultTypography = Object.assign({}, DEFAULT_PO_TEMPLATE.typography, masterTpl.typography || {});
    const initialTypography = po.typography ? Object.assign({}, defaultTypography, po.typography) : defaultTypography;

    if (!po.labels) {
      po.labels = Object.assign({}, masterTpl.labels || DEFAULT_PO_TEMPLATE.labels);
    } else {
      Object.keys(DEFAULT_PO_TEMPLATE.labels).forEach(lk => {
        if (po.labels[lk] === '' || po.labels[lk] === undefined || po.labels[lk] === null) {
          po.labels[lk] = DEFAULT_PO_TEMPLATE.labels[lk];
        }
      });
    }
    if (!po.docTitle) {
      po.docTitle = masterTpl.docTitle || DEFAULT_PO_TEMPLATE.docTitle;
    }
    const isBuzzerClient = /buzzer/i.test(String(lead.client || po.client || ''));
    if (po.docSubtitle === 'Print & Merch Design Bundle' && lead.title !== 'Print & Merch Design Bundle' && !isBuzzerClient) {
      po.docSubtitle = '';
      if (po.richText) delete po.richText.doc_subtitle;
    }
    if (po.docSubtitle === undefined) {
      po.docSubtitle = masterTpl.docSubtitle !== undefined ? masterTpl.docSubtitle : DEFAULT_PO_TEMPLATE.docSubtitle;
    }
    if (!po.sender || po.sender.name === 'Your Name / Studio') {
      po.sender = Object.assign({}, masterTpl.sender || DEFAULT_PO_TEMPLATE.sender);
    }

    applyPriceOfferingTypography(initialTypography, false);

    // Sections
    currentPoSections = getDefaultPoSections(po, lead).filter(s => !(s && s.type === 'text' && s.title === '*' && (!s.content || !String(s.content).replace(/<[^>]*>/g, '').trim())));
    const leadOvIdx = currentPoSections.findIndex(s => s && s.type === 'overview');
    if (leadOvIdx !== -1 && (!currentPoSections[leadOvIdx + 1] || currentPoSections[leadOvIdx + 1].type !== 'divider')) {
      currentPoSections.splice(leadOvIdx + 1, 0, { id: 'sec_div_overview', type: 'divider', title: 'Divider Line', content: '' });
    }

    // Items
    const initLeadAmount = parseFloat(lead.amount) || 0;
    if (Array.isArray(po.items) && po.items.length > 0) {
      currentPoItems = JSON.parse(JSON.stringify(po.items));
      if (currentPoItems.length === 1 && (parseFloat(currentPoItems[0].amount) || 0) === 0 && initLeadAmount > 0) {
        currentPoItems[0].rate = initLeadAmount;
        currentPoItems[0].amount = (parseFloat(currentPoItems[0].qty) || 1) * initLeadAmount;
      }
    } else {
      currentPoItems = [
        {
          id: 'po_item_' + Date.now(),
          description: lead.title || 'Project Scope & Deliverables',
          qty: 1,
          rate: initLeadAmount,
          amount: initLeadAmount
        }
      ];
    }
    Object.keys(poRichText).forEach(rk => {
      const m = rk.match(/^item_(desc|qty|rate|amount)_(\d+)$/);
      if (m && parseInt(m[2], 10) >= currentPoItems.length) {
        delete poRichText[rk];
      }
    });

    selectedPoSectionIndex = null;
    currentPoSignatures = Array.isArray(po.signatures) ? JSON.parse(JSON.stringify(po.signatures)) : [];
    activePoTemplateId = po.templateId || masterTpl.id || 'tpl_studio_master';
    const printAreaEl = document.getElementById('priceOfferingPrintArea');
    if (printAreaEl) printAreaEl.innerHTML = '';
    renderPriceOfferingDocument(lead, po);
    if (!lead.priceOffering) {
      savePriceOfferingDoc(false);
    }
    renderPoSavedTemplatesGallery();
    renderPoVersionsDropdown();
    if (typeof window.scrollTo === 'function') window.scrollTo({ top: 0, behavior: 'smooth' });

    setTimeout(() => {
      poUndoStack = [getPoDocumentSnapshot()];
      poRedoStack = [];
      updatePoUndoRedoUI();
    }, 60);
  }

  function openProjectProformaDocPage(projectId) {
    if (!projectId) projectId = state.activeFollowupProjectId;
    if (!projectId) return;

    const proj = (state.budget?.projects || []).find(p => p.id === projectId);
    if (!proj) return;

    clearTimeout(poAutoSaveTimeout);
    poAutoSaveTimeout = null;
    state.activeStudioDocId = null;
    state.activePriceOfferingLeadId = null;
    state.activeFollowupLeadId = null;
    state.activeProformaProjectId = projectId;
    state.activeFollowupProjectId = projectId;
    poEditingTemplateDesignId = null;
    poTemplateDesignEditBackup = null;
    poEditingTemplateNameId = null;

    syncPoEditorModeUI(false);
    const typeLabel = document.getElementById('priceOfferingDocTypeLabel');
    if (typeLabel) typeLabel.textContent = 'Proforma Invoice · A4 Editor';

    try {
      history.replaceState(null, '', '#project_followup/' + projectId + '/proforma');
      recordFinlandRoute('#project_followup/' + projectId + '/proforma');
    } catch (e) {}

    // Switch view
    document.getElementById('projectFollowupOverview')?.classList.add('hidden');
    document.getElementById('projectDetailPage')?.classList.add('hidden');
    document.getElementById('leadDetailPage')?.classList.add('hidden');
    const poPage = document.getElementById('priceOfferingDocPage');
    if (poPage) poPage.classList.remove('hidden');

    // Breadcrumb
    const bcClient = document.getElementById('priceOfferingDocClientBreadcrumb');
    if (bcClient) bcClient.textContent = proj.client || 'Client';

    const statusBadgeText = document.getElementById('priceOfferingSaveStatusText');
    const statusDot = document.getElementById('priceOfferingSaveStatusDot');
    if (statusBadgeText) statusBadgeText.textContent = proj.proformaInvoice ? 'Proforma Invoice · Saved' : 'Proforma Invoice · Draft';
    if (statusDot) {
      statusDot.className = proj.proformaInvoice ? 'w-1.5 h-1.5 rounded-full bg-purple-600' : 'w-1.5 h-1.5 rounded-full bg-slate-300';
    }

    const masterTpl = getMasterPoTemplate();
    const curYear = new Date().getFullYear();
    const curProjNum = String(proj.id || '').replace(/\D/g, '').slice(-3) || '001';
    const hadExistingProforma = !!proj.proformaInvoice;

    if (!proj.proformaInvoice) {
      const projAmount = parseFloat(proj.amount !== undefined ? proj.amount : proj.fee) || 0;
      const projCur = proj.currency || state.displayCurrency || 'EUR';
      const todayStr = new Date().toISOString().split('T')[0];
      const dueStr = proj.paymentDueDate || proj.dueDate || new Date(Date.now() + 14 * 86400000).toISOString().split('T')[0];
      const srcQuote = proj.priceOffering || (Array.isArray(proj.quoteExports) && proj.quoteExports[0] && proj.quoteExports[0].data ? proj.quoteExports[0].data : null);

      let initialItems = [
        {
          id: 'po_item_' + Date.now(),
          description: proj.title || 'Project Scope & Deliverables',
          qty: 1,
          rate: projAmount,
          amount: projAmount
        }
      ];
      let initDiscPct = 0;
      let initTaxPct = 0;
      let initSubtotal = projAmount;
      let initTotal = projAmount;
      const initElementStyles = {};
      const initRichText = {};

      if (srcQuote && Array.isArray(srcQuote.items) && srcQuote.items.length > 0) {
        initialItems = JSON.parse(JSON.stringify(srcQuote.items));
        initDiscPct = parseFloat(srcQuote.discountPercent) || 0;
        initTaxPct = parseFloat(srcQuote.taxPercent) || 0;
        if (initialItems.length === 1 && projAmount > 0 && Math.abs((parseFloat(srcQuote.total) || 0) - projAmount) > 0.01) {
          const q = parseFloat(initialItems[0].qty) || 1;
          initialItems[0].rate = projAmount;
          initialItems[0].amount = q * projAmount;
        }
        initSubtotal = initialItems.reduce((acc, it) => acc + (parseFloat(it.amount) || 0), 0);
        const afterDisc = Math.max(0, initSubtotal - initSubtotal * (initDiscPct / 100));
        initTotal = afterDisc + afterDisc * (initTaxPct / 100);
        if (srcQuote.elementStyles && typeof srcQuote.elementStyles === 'object') {
          Object.keys(srcQuote.elementStyles).forEach(k => {
            if (/^item_(desc|qty|rate|amount)_\d+$/.test(k)) {
              initElementStyles[k] = JSON.parse(JSON.stringify(srcQuote.elementStyles[k]));
            }
          });
        }
        if (srcQuote.richText && typeof srcQuote.richText === 'object') {
          Object.keys(srcQuote.richText).forEach(k => {
            if (/^item_(desc|qty|rate|amount)_\d+$/.test(k)) {
              initRichText[k] = srcQuote.richText[k];
            }
          });
        }
      }

      const srcScopeSec = srcQuote && Array.isArray(srcQuote.sections) ? srcQuote.sections.find(s => s && s.type === 'scope') : null;
      const initScopeContent = (srcScopeSec && srcScopeSec.content)
        ? srcScopeSec.content
        : (srcQuote && srcQuote.scope ? srcQuote.scope : (proj.notes ? proj.notes.split('\n\n---\n\n')[0] : (proj.title || '')));

      proj.proformaInvoice = {
        _isProforma: true,
        templateId: (srcQuote && srcQuote.templateId) || masterTpl.id || 'tpl_studio_master',
        docTitle: 'PROFORMA INVOICE',
        docSubtitle: 'Preliminary Invoice / Advance Payment Request',
        refNo: `PI-${curYear}-${curProjNum}`,
        issueDate: todayStr,
        validUntil: dueStr,
        currency: projCur,
        client: proj.client || (srcQuote && srcQuote.client) || '',
        clientEmail: (srcQuote && srcQuote.clientEmail) || '',
        clientAddress: (srcQuote && srcQuote.clientAddress) || '',
        projectTitle: proj.title || proj.description || (srcQuote && srcQuote.projectTitle) || '',
        elementStyles: initElementStyles,
        richText: initRichText,
        labels: {
          client: 'Bill To / Client',
          reference: 'Proforma Invoice #',
          currency: 'Currency',
          issueDate: 'Invoice Date',
          validUntil: 'Payment Due',
          project: 'Project / Assignment',
          thDesc: 'Description / Deliverables',
          thQty: 'Qty / Hrs',
          thRate: 'Rate',
          thAmount: 'Amount',
          subtotal: 'Subtotal',
          discount: 'Discount',
          tax: 'VAT / Tax',
          totalInvestment: 'Total Amount Due'
        },
        items: initialItems,
        sections: [
          { id: 'sec_header', type: 'header', title: 'Document Header' },
          { id: 'sec_overview', type: 'overview', title: 'Client & Project Details' },
          { id: 'sec_div_overview', type: 'divider', title: 'Divider Line', content: '' },
          {
            id: 'sec_scope_' + Date.now(),
            type: 'scope',
            title: (srcScopeSec && srcScopeSec.title) || 'Project Scope & Objective',
            pageBreakBefore: false,
            content: initScopeContent
          },
          { id: 'sec_deliverables', type: 'deliverables', title: 'Deliverables & Fees', pageBreakBefore: false },
          {
            id: 'sec_terms_' + Date.now(),
            type: 'terms',
            title: 'Payment Terms & Bank Details',
            pageBreakBefore: false,
            content: getProformaDefaultTerms()
          },
          {
            id: 'sec_conditions_' + Date.now(),
            type: 'conditions',
            title: 'Notice & Invoicing Notes',
            pageBreakBefore: false,
            content: '• This proforma invoice is an advance estimation issued prior to delivery or receipt of payment.\n• An official VAT tax invoice / receipt will be issued upon receipt of payment.\n• All project work remains the property of the provider until payment is completed.'
          }
        ],
        subtotal: initSubtotal,
        discountPercent: initDiscPct,
        taxPercent: initTaxPct,
        total: initTotal,
        _structuralMigrated: true,
        updatedAt: new Date().toISOString()
      };
    }

    const po = proj.proformaInvoice;
    po._isProforma = true;

    // Ensure Proforma sections have Payment Terms & Bank Details, Notice & Invoicing Notes, and no quote-only blocks
    if (Array.isArray(po.sections) && po.sections.length > 0) {
      po.sections = buildProformaSectionsFromTemplate(po.sections, po.sections, proj);
      const termsSec = po.sections.find(s => s && s.type === 'terms');
      if (termsSec && (termsSec.content.includes('[Your Bank Name]') || termsSec.content.includes('within 14 days') || termsSec.content.includes('Address: Wise'))) {
        termsSec.content = getProformaDefaultTerms();
      }
    }

    // Restore per-element InDesign-style styles
    const baseElementStyles = JSON.parse(JSON.stringify(masterTpl.elementStyles || {}));
    const projElementStyles = (po.elementStyles && typeof po.elementStyles === 'object') ? JSON.parse(JSON.stringify(po.elementStyles)) : {};
    poElementStyles = {};
    const allElemKeys = new Set([...Object.keys(baseElementStyles), ...Object.keys(projElementStyles)]);
    allElemKeys.forEach(k => {
      poElementStyles[k] = Object.assign({}, baseElementStyles[k] || {}, projElementStyles[k] || {});
    });
    poRichText = Object.assign(
      {},
      JSON.parse(JSON.stringify(masterTpl.richText || {})),
      (po.richText && typeof po.richText === 'object') ? JSON.parse(JSON.stringify(po.richText)) : {}
    );
    poSelectedElementId = null;
    poSelectedElementMeta = null;

    const defaultTypography = Object.assign({}, DEFAULT_PO_TEMPLATE.typography, masterTpl.typography || {});
    const initialTypography = po.typography ? Object.assign({}, defaultTypography, po.typography) : defaultTypography;

    po.labels = Object.assign({}, DEFAULT_PO_TEMPLATE.labels, masterTpl.labels || {}, PROFORMA_DEFAULT_LABELS, po.labels || {});
    if (!po.docTitle || po.docTitle === 'Price Quote / Proposal') {
      po.docTitle = 'PROFORMA INVOICE';
    }
    if (!po.docSubtitle || (po.docSubtitle === 'Print & Merch Design Bundle' && proj.title !== 'Print & Merch Design Bundle')) {
      po.docSubtitle = 'Preliminary Invoice / Advance Payment Request';
    }
    if (!po.sender || po.sender.name === 'Your Name / Studio') {
      po.sender = Object.assign({}, masterTpl.sender || DEFAULT_PO_TEMPLATE.sender);
    }

    applyPriceOfferingTypography(initialTypography, false);

    // Sections
    currentPoSections = Array.isArray(po.sections) && po.sections.length > 0
      ? JSON.parse(JSON.stringify(po.sections))
      : getDefaultPoSections(po, proj);

    // Items
    const initProjAmount = parseFloat(proj.amount !== undefined ? proj.amount : proj.fee) || 0;
    if (Array.isArray(po.items) && po.items.length > 0) {
      currentPoItems = JSON.parse(JSON.stringify(po.items));
      if (currentPoItems.length === 1 && (parseFloat(currentPoItems[0].amount) || 0) === 0 && initProjAmount > 0) {
        currentPoItems[0].rate = initProjAmount;
        currentPoItems[0].amount = (parseFloat(currentPoItems[0].qty) || 1) * initProjAmount;
      }
    } else {
      currentPoItems = [
        {
          id: 'po_item_' + Date.now(),
          description: proj.title || 'Project Scope & Deliverables',
          qty: 1,
          rate: initProjAmount,
          amount: initProjAmount
        }
      ];
    }
    Object.keys(poRichText).forEach(rk => {
      const m = rk.match(/^item_(desc|qty|rate|amount)_(\d+)$/);
      if (m && parseInt(m[2], 10) >= currentPoItems.length) {
        delete poRichText[rk];
      }
    });

    selectedPoSectionIndex = null;
    currentPoSignatures = Array.isArray(po.signatures) ? JSON.parse(JSON.stringify(po.signatures)) : [];
    activePoTemplateId = po.templateId || masterTpl.id || 'tpl_studio_master';

    const targetProxy = getPoEditorTarget(projectId);
    const printAreaEl = document.getElementById('priceOfferingPrintArea');
    if (printAreaEl) printAreaEl.innerHTML = '';
    renderPriceOfferingDocument(targetProxy, po);
    if (!hadExistingProforma) {
      savePriceOfferingDoc(false);
    }
    renderPoSavedTemplatesGallery();
    renderPoVersionsDropdown();
    if (typeof window.scrollTo === 'function') window.scrollTo({ top: 0, behavior: 'smooth' });

    setTimeout(() => {
      poUndoStack = [getPoDocumentSnapshot()];
      poRedoStack = [];
      updatePoUndoRedoUI();
    }, 60);
  }

