  const DEFAULT_DOC_CATEGORIES = [
    { id: 'cv', label: 'CV & Bio', color: 'emerald', icon: 'user-check', sortOrder: 1 },
    { id: 'pitch', label: 'Pitch', color: 'amber', icon: 'presentation', sortOrder: 2 },
    { id: 'visa', label: 'Identity & Visa', color: 'sky', icon: 'id-card', sortOrder: 3 },
    { id: 'degree', label: 'Education', color: 'purple', icon: 'graduation-cap', sortOrder: 4 },
    { id: 'tax', label: 'Tax & Official', color: 'rose', icon: 'shield-check', sortOrder: 5 },
    { id: 'other', label: 'Other', color: 'indigo', icon: 'folder', sortOrder: 999 }
  ];

  const DOC_CATEGORY_META = {};
  const DOC_CATEGORY_SORT_ORDER = {};

  function buildDocCategoryMetaEntry(cat) {
    const colorKey = (cat && cat.color && DOC_COLOR_THEMES[cat.color]) ? cat.color : 'indigo';
    const theme = DOC_COLOR_THEMES[colorKey];
    const iconName = (cat && cat.icon) ? cat.icon : 'folder';
    return {
      id: cat.id,
      label: cat.label || 'Category',
      color: colorKey,
      icon: iconName,
      sortOrder: typeof cat.sortOrder === 'number' ? cat.sortOrder : 50,
      badgeCls: theme.badgeCls,
      iconBoxCls: theme.iconBoxCls,
      iconCls: theme.iconCls,
      pillIconCls: theme.pillIconCls
    };
  }

  function syncDocCategoryRuntimeTables(catList) {
    Object.keys(DOC_CATEGORY_META).forEach(k => delete DOC_CATEGORY_META[k]);
    Object.keys(DOC_CATEGORY_SORT_ORDER).forEach(k => delete DOC_CATEGORY_SORT_ORDER[k]);
    const list = (Array.isArray(catList) && catList.length > 0)
      ? catList
      : ((Array.isArray(state.documentCategories) && state.documentCategories.length > 0)
          ? state.documentCategories
          : DEFAULT_DOC_CATEGORIES);
    list.forEach((cat, idx) => {
      if (!cat || !cat.id) return;
      const orderNum = cat.id === 'other' ? 999 : (idx + 1);
      const entry = buildDocCategoryMetaEntry(Object.assign({}, cat, { sortOrder: orderNum }));
      DOC_CATEGORY_META[cat.id] = entry;
      DOC_CATEGORY_SORT_ORDER[cat.id] = orderNum;
    });
    if (!DOC_CATEGORY_META.other) {
      const otherDef = DEFAULT_DOC_CATEGORIES.find(c => c.id === 'other') || { id: 'other', label: 'Other', color: 'indigo', icon: 'folder', sortOrder: 999 };
      DOC_CATEGORY_META.other = buildDocCategoryMetaEntry(otherDef);
      DOC_CATEGORY_SORT_ORDER.other = 999;
    }
  }

  // Initialize synchronously with defaults before localStorage loads
  syncDocCategoryRuntimeTables(DEFAULT_DOC_CATEGORIES);

  function loadDocumentCategories() {
    try {
      const raw = localStorage.getItem(STORAGE_KEYS.DOCUMENT_CATEGORIES);
      if (raw) {
        const parsed = JSON.parse(raw);
        const rawList = Array.isArray(parsed)
          ? parsed
          : (parsed && Array.isArray(parsed.categories) ? parsed.categories : null);
        const deletedDefaultIds = new Set(parsed && Array.isArray(parsed.deletedIds) ? parsed.deletedIds : []);
        if (Array.isArray(rawList) && rawList.length > 0) {
          const byId = new Map();
          const orderedIds = [];
          rawList.forEach(c => {
            if (c && c.id && c.label && !byId.has(c.id)) {
              byId.set(c.id, Object.assign({}, c));
              if (c.id !== 'other') orderedIds.push(c.id);
            }
          });
          DEFAULT_DOC_CATEGORIES.forEach(defCat => {
            if (!byId.has(defCat.id) && !deletedDefaultIds.has(defCat.id)) {
              byId.set(defCat.id, Object.assign({}, defCat));
              if (defCat.id !== 'other') orderedIds.push(defCat.id);
            }
          });
          if (byId.has('other')) {
            orderedIds.push('other');
          }
          const merged = orderedIds.map((id, idx) => {
            const cat = byId.get(id);
            cat.sortOrder = id === 'other' ? 999 : (idx + 1);
            return cat;
          });
          state.documentCategories = merged;
          state.deletedDocumentCategoryIds = Array.from(deletedDefaultIds);
          syncDocCategoryRuntimeTables(merged);
          populateDocCategorySelects();
          return merged;
        }
      }
    } catch (e) {}
    state.documentCategories = JSON.parse(JSON.stringify(DEFAULT_DOC_CATEGORIES));
    state.deletedDocumentCategoryIds = [];
    syncDocCategoryRuntimeTables(state.documentCategories);
    populateDocCategorySelects();
    return state.documentCategories;
  }

  function saveDocumentCategories() {
    try {
      const list = Array.isArray(state.documentCategories) ? state.documentCategories : DEFAULT_DOC_CATEGORIES;
      const payload = {
        categories: list,
        deletedIds: Array.isArray(state.deletedDocumentCategoryIds) ? state.deletedDocumentCategoryIds : [],
        updatedAt: new Date().toISOString()
      };
      localStorage.setItem(STORAGE_KEYS.DOCUMENT_CATEGORIES, JSON.stringify(payload));
      syncDocCategoryRuntimeTables(list);
      populateDocCategorySelects();
      triggerSafeVaultPush();
    } catch (e) {
      console.warn('Failed to save document categories:', e);
    }
  }

  function getOrderedDocCategoryKeys() {
    if (!Array.isArray(state.documentCategories) || state.documentCategories.length === 0) {
      loadDocumentCategories();
    }
    const keys = Object.keys(DOC_CATEGORY_META);
    return keys.sort((a, b) => (DOC_CATEGORY_SORT_ORDER[a] || 99) - (DOC_CATEGORY_SORT_ORDER[b] || 99));
  }

  function syncDocModalCategoryPreview(selectId, btnId, iconId) {
    const sel = document.getElementById(selectId);
    const btn = document.getElementById(btnId);
    const iconEl = document.getElementById(iconId);
    if (!sel || !btn || !iconEl) return;
    const catKey = (sel.value && DOC_CATEGORY_META[sel.value]) ? sel.value : 'other';
    const meta = DOC_CATEGORY_META[catKey] || DOC_CATEGORY_META.other;
    btn.className = `w-10 h-10 rounded-xl border flex items-center justify-center shrink-0 transition-all cursor-pointer hover:scale-105 ${meta.iconBoxCls}`;
    btn.title = `Customize "${meta.label}" icon & color`;
    iconEl.setAttribute('data-lucide', meta.icon || 'folder');
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function syncDocModalCategoryPreviews() {
    syncDocModalCategoryPreview('docUploadCategorySelect', 'docUploadCatPreviewBtn', 'docUploadCatPreviewIcon');
    syncDocModalCategoryPreview('docNewStudioCategorySelect', 'docNewStudioCatPreviewBtn', 'docNewStudioCatPreviewIcon');
  }

  function populateDocCategorySelects(selectedValueOverride = null) {
    const keys = getOrderedDocCategoryKeys();
    ['docUploadCategorySelect', 'docNewStudioCategorySelect'].forEach(selId => {
      const sel = document.getElementById(selId);
      if (!sel) return;
      const prevVal = selectedValueOverride || sel.value;
      const optionsHtml = keys.map(k => {
        const meta = DOC_CATEGORY_META[k];
        return `<option value="${escapeHtml(k)}">${escapeHtml(meta ? meta.label : k)}</option>`;
      }).join('');
      sel.innerHTML = optionsHtml + `<option value="__new_category__">+ Add New Category…</option>`;
      if (prevVal && DOC_CATEGORY_META[prevVal]) {
        sel.value = prevVal;
      } else if (keys.length > 0) {
        sel.value = keys[0];
      }
    });
    syncDocModalCategoryPreviews();
  }

  function inferDocumentCategoryFromFilename(fileName) {
    const lower = String(fileName || '').toLowerCase();
    // Check custom user categories by label match first
    const customKeys = getOrderedDocCategoryKeys();
    for (const k of customKeys) {
      if (!['cv', 'pitch', 'visa', 'degree', 'tax', 'other'].includes(k)) {
        const lbl = String(DOC_CATEGORY_META[k]?.label || '').toLowerCase().trim();
        if (lbl && lbl.length >= 3 && lower.includes(lbl)) return k;
      }
    }
    if (DOC_CATEGORY_META.tax && /tax|finanzamt|steuer|steuernummer|ksk|elster|ust|vat|invoice|official|bescheid|abgaben|מס|מסים|חובות|היעדר חובות|ביטוח לאומי|עוסק|שומה|ניכוי|אישור|רואה חשבון/i.test(lower)) return 'tax';
    if (DOC_CATEGORY_META.visa && /visa|aufenthalt|residency|passport|id|ausweis|permit|anmeldung|meldebescheinigung|bürgeramt|buergeramt|דרכון|תעודת זהות|ויזה|אשרה|תושבות|ספח/i.test(lower)) return 'visa';
    if (DOC_CATEGORY_META.degree && /degree|bezalel|diploma|certificate|award|iasa|university|bachelor|master|transcript|בצלאל|תואר|תעודה|לימודים|גיליון ציונים|מלגה/i.test(lower)) return 'degree';
    if (DOC_CATEGORY_META.pitch && /pitch|deck|capabilities|portfolio|presentation|מצגת|תיק עבודות|פיץ/i.test(lower)) return 'pitch';
    if (DOC_CATEGORY_META.cv && /cv|resume|curriculum|statement|bio|artist statement|קורות חיים|הצהרת אמן|ביוגרפיה/i.test(lower)) return 'cv';
    return DOC_CATEGORY_META.visa ? 'visa' : (customKeys[0] || 'other');
  }

  function getActiveDefaultDocCategory(fileName) {
    const activeFilter = state.documentsFilter || 'all';
    if (activeFilter !== 'all' && DOC_CATEGORY_META[activeFilter]) {
      return activeFilter;
    }
    return inferDocumentCategoryFromFilename(fileName);
  }

  function sortDocumentsList(list) {
    return (list || []).slice().sort((a, b) => {
      const pinDiff = (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0);
      if (pinDiff !== 0) return pinDiff;
      const hasExplicitOrder = typeof a.sortOrder === 'number' || typeof b.sortOrder === 'number';
      if ((state.documentsFilter || 'all') === 'all' && !hasExplicitOrder) {
        const catA = DOC_CATEGORY_SORT_ORDER[a.category] || 99;
        const catB = DOC_CATEGORY_SORT_ORDER[b.category] || 99;
        if (catA !== catB) return catA - catB;
      }
      if (hasExplicitOrder) {
        const orderA = typeof a.sortOrder === 'number' ? a.sortOrder : 999999;
        const orderB = typeof b.sortOrder === 'number' ? b.sortOrder : 999999;
        if (orderA !== orderB) return orderA - orderB;
      }
      const catA = DOC_CATEGORY_SORT_ORDER[a.category] || 99;
      const catB = DOC_CATEGORY_SORT_ORDER[b.category] || 99;
      if (catA !== catB) return catA - catB;
      const timeA = a.updatedAt ? new Date(a.updatedAt).getTime() : 0;
      const timeB = b.updatedAt ? new Date(b.updatedAt).getTime() : 0;
      return timeB - timeA;
    });
  }

  function loadDocuments() {
    try {
      const raw = localStorage.getItem(STORAGE_KEYS.DOCUMENTS);
      const deletedIdsSet = getDeletedDocIdsSet();
      let parsed = raw ? JSON.parse(raw) : null;
      if (!Array.isArray(parsed)) {
        parsed = JSON.parse(JSON.stringify(DEFAULT_STUDIO_DOCUMENTS)).filter(d => d && d.id && !deletedIdsSet.has(d.id));
        if (raw !== null) {
          localStorage.setItem(STORAGE_KEYS.DOCUMENTS, JSON.stringify(parsed));
        }
      } else {
        let updatedDefault = false;
        const beforeFilterLen = parsed.length;
        parsed = parsed.filter(d => d && d.id && !deletedIdsSet.has(d.id));
        if (parsed.length !== beforeFilterLen) updatedDefault = true;
        DEFAULT_STUDIO_DOCUMENTS.forEach(defDoc => {
          const existing = parsed.find(d => d.id === defDoc.id);
          if (!existing && !deletedIdsSet.has(defDoc.id)) {
            parsed.unshift(JSON.parse(JSON.stringify(defDoc)));
            updatedDefault = true;
          }
        });
        if (updatedDefault) {
          localStorage.setItem(STORAGE_KEYS.DOCUMENTS, JSON.stringify(parsed));
        }
      }
      state.documents = parsed;
    } catch (e) {
      console.warn('Failed to load documents:', e);
      state.documents = JSON.parse(JSON.stringify(DEFAULT_STUDIO_DOCUMENTS));
    }
  }

  function saveDocuments(changedDocId = null) {
    try {
      const deletedIds = getDeletedDocIdsSet();
      if (Array.isArray(state.documents)) {
        state.documents = state.documents.filter(d => d && d.id && !deletedIds.has(d.id));
      }
      // Reconcile with localStorage so another open browser tab cannot be clobbered by stale in-memory state
      const rawExisting = localStorage.getItem(STORAGE_KEYS.DOCUMENTS);
      if (rawExisting) {
        try {
          const parsedExisting = JSON.parse(rawExisting);
          if (Array.isArray(parsedExisting) && Array.isArray(state.documents)) {
            const existingById = new Map();
            parsedExisting.forEach(item => {
              if (item && item.id && !deletedIds.has(item.id)) existingById.set(item.id, item);
            });

            state.documents = state.documents.map(doc => {
              if (!doc || !doc.id) return doc;
              if (changedDocId && doc.id === changedDocId) return doc;
              const stored = existingById.get(doc.id);
              if (!stored) return doc;
              const memTime = Math.max(Date.parse(doc.updatedAt || '') || 0, Date.parse(doc._orderUpdatedAt || '') || 0);
              const storedTime = Math.max(Date.parse(stored.updatedAt || '') || 0, Date.parse(stored._orderUpdatedAt || '') || 0);
              if (storedTime > memTime) {
                return stored;
              }
              return doc;
            });

            const currentIds = new Set(state.documents.map(d => d && d.id));
            parsedExisting.forEach(item => {
              if (item && item.id && !currentIds.has(item.id) && !deletedIds.has(item.id)) {
                if (!changedDocId || item.id !== changedDocId) {
                  state.documents.unshift(item);
                  currentIds.add(item.id);
                }
              }
            });
          }
        } catch (mergeErr) {}
      }
      localStorage.setItem(STORAGE_KEYS.DOCUMENTS, JSON.stringify(state.documents || []));
      triggerSafeVaultPush();
    } catch (e) {
      console.warn('Failed to save documents:', e);
    }
  }

  let docVaultThumbCache = {};
  let activeViewerBlobUrl = null;

  function dataUrlToUint8Array(dataUrl) {
    if (!dataUrl || typeof dataUrl !== 'string') return null;
    const base64Idx = dataUrl.indexOf('base64,');
    if (base64Idx === -1) return null;
    const rawBin = atob(dataUrl.slice(base64Idx + 7).replace(/\s+/g, ''));
    const bytes = new Uint8Array(rawBin.length);
    for (let i = 0; i < rawBin.length; i++) {
      bytes[i] = rawBin.charCodeAt(i);
    }
    return bytes;
  }

  function dataUrlToBlobUrl(dataUrl, fallbackMime = 'application/pdf') {
    try {
      const bytes = dataUrlToUint8Array(dataUrl);
      if (!bytes) return dataUrl;
      const mimeMatch = String(dataUrl).match(/^data:([^;,]+)/i);
      const mime = (mimeMatch && mimeMatch[1]) ? mimeMatch[1] : fallbackMime;
      const blob = new Blob([bytes], { type: mime });
      return URL.createObjectURL(blob);
    } catch (e) {
      return dataUrl;
    }
  }

  let docVaultThumbPending = {};
  let pdfThumbRenderChain = Promise.resolve();

  async function getLocalCachedDocThumb(docId) {
    if (!docId || typeof indexedDB === 'undefined') return null;
    try {
      const db = await openReceiptDB();
      const rec = await new Promise((resolve) => {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const req = tx.objectStore(STORE_NAME).get(`doc_thumb_${docId}`);
        req.onsuccess = () => resolve(req.result || null);
        req.onerror = () => resolve(null);
      });
      if (rec && typeof rec.data === 'string' && rec.data.startsWith('data:image/')) {
        return rec.data;
      }
    } catch (e) {}
    return null;
  }

  async function saveLocalCachedDocThumb(docId, thumbDataUrl) {
    if (!docId || !thumbDataUrl || typeof thumbDataUrl !== 'string' || !thumbDataUrl.startsWith('data:image/') || typeof indexedDB === 'undefined') return;
    try {
      const db = await openReceiptDB();
      await new Promise((resolve) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        tx.objectStore(STORE_NAME).put({
          expenseId: `doc_thumb_${docId}`,
          type: 'thumb',
          mimeType: 'image/jpeg',
          data: thumbDataUrl,
          savedAt: new Date().toISOString()
        });
        tx.oncomplete = () => resolve(true);
        tx.onerror = () => resolve(false);
      });
    } catch (e) {}
  }

  async function deleteLocalCachedDocThumb(docId) {
    if (!docId || typeof indexedDB === 'undefined') return;
    try {
      const db = await openReceiptDB();
      await new Promise((resolve) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        tx.objectStore(STORE_NAME).delete(`doc_thumb_${docId}`);
        tx.oncomplete = () => resolve(true);
        tx.onerror = () => resolve(false);
      });
    } catch (e) {}
  }

  function createDownscaledImageThumbUrl(dataUrl, maxDim = 440) {
    return new Promise((resolve) => {
      try {
        if (!dataUrl || typeof dataUrl !== 'string' || dataUrl.length < 90000) {
          resolve(dataUrl);
          return;
        }
        const img = new Image();
        img.onload = () => {
          try {
            const w = img.naturalWidth || img.width || 1;
            const h = img.naturalHeight || img.height || 1;
            if (w <= maxDim && h <= maxDim && dataUrl.length < 180000) {
              resolve(dataUrl);
              return;
            }
            const ratio = Math.min(1, maxDim / w, maxDim / h);
            const cw = Math.max(1, Math.round(w * ratio));
            const ch = Math.max(1, Math.round(h * ratio));
            const canvas = document.createElement('canvas');
            canvas.width = cw;
            canvas.height = ch;
            const ctx = canvas.getContext('2d');
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, cw, ch);
            ctx.drawImage(img, 0, 0, cw, ch);
            resolve(canvas.toDataURL('image/jpeg', 0.85));
          } catch (e) {
            resolve(dataUrl);
          }
        };
        img.onerror = () => resolve(dataUrl);
        img.src = dataUrl;
      } catch (e) {
        resolve(dataUrl);
      }
    });
  }

  async function hydrateDocVaultThumbnail(docId, imgEl) {
    if (!docId || !imgEl) return;
    const showThumb = (thumbUrl) => {
      const currentEl = document.querySelector(`#viewDocuments img[data-doc-thumb-id="${docId}"]`) || imgEl;
      if (!currentEl) return;
      if (currentEl.getAttribute('src') !== thumbUrl) {
        currentEl.src = thumbUrl;
      }
      currentEl.classList.remove('hidden');
      const fallback = currentEl.parentElement?.querySelector('.doc-thumb-fallback');
      if (fallback) fallback.classList.add('hidden');
    };
    if (docVaultThumbCache[docId]) {
      showThumb(docVaultThumbCache[docId]);
      return;
    }
    if (docVaultThumbPending[docId]) {
      const cached = await docVaultThumbPending[docId];
      if (cached) showThumb(cached);
      return;
    }

    docVaultThumbPending[docId] = (async () => {
      try {
        // 1. Check lightweight persistent IndexedDB thumbnail cache first (~15-25 KB vs multi-MB PDF/scan)
        const persistedThumb = await getLocalCachedDocThumb(docId);
        if (persistedThumb) {
          docVaultThumbCache[docId] = persistedThumb;
          return persistedThumb;
        }

        // 2. Fallback: load full attachment once, generate compact JPEG thumbnail, and cache it persistently
        const att = await getReceiptAttachment(`doc_vault_${docId}`);
        if (!att || !att.data) return null;

        const isImg = att.type === 'image' || String(att.mimeType || '').startsWith('image/') || String(att.data).startsWith('data:image/');
        if (isImg) {
          const thumbUrl = await createDownscaledImageThumbUrl(att.data, 440);
          docVaultThumbCache[docId] = thumbUrl;
          await saveLocalCachedDocThumb(docId, thumbUrl);
          return thumbUrl;
        }

        const isPdf = att.type === 'pdf' || String(att.mimeType || '').includes('pdf') || String(att.data).startsWith('data:application/pdf');
        if (isPdf && window.pdfjsLib) {
          const jpgUrl = await new Promise((resolvePdf) => {
            pdfThumbRenderChain = pdfThumbRenderChain.then(async () => {
              try {
                const bytes = dataUrlToUint8Array(att.data);
                if (!bytes) {
                  resolvePdf(null);
                  return;
                }
                const pdfDoc = await window.pdfjsLib.getDocument({
                  data: bytes,
                  cMapUrl: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/cmaps/',
                  cMapPacked: true,
                  standardFontDataUrl: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/standard_fonts/'
                }).promise;
                const page = await pdfDoc.getPage(1);
                const viewport = page.getViewport({ scale: 0.75 });
                const canvas = document.createElement('canvas');
                canvas.width = viewport.width;
                canvas.height = viewport.height;
                const ctx = canvas.getContext('2d');
                ctx.fillStyle = '#ffffff';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                await page.render({ canvasContext: ctx, viewport }).promise;
                const dataUrl = canvas.toDataURL('image/jpeg', 0.84);
                try { pdfDoc.destroy(); } catch (e) {}
                resolvePdf(dataUrl);
              } catch (e) {
                resolvePdf(null);
              }
            });
          });
          if (jpgUrl) {
            docVaultThumbCache[docId] = jpgUrl;
            await saveLocalCachedDocThumb(docId, jpgUrl);
            return jpgUrl;
          }
        }
      } catch (err) {
        console.warn('Thumbnail render skipped:', err);
      } finally {
        delete docVaultThumbPending[docId];
      }
      return null;
    })();

    const finalUrl = await docVaultThumbPending[docId];
    if (finalUrl) showThumb(finalUrl);
  }

  function formatDocUpdatedDate(iso) {
    if (!iso) return 'Recently';
    try {
      const d = new Date(iso);
      if (isNaN(d.getTime())) return 'Recently';
      return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    } catch (e) {
      return 'Recently';
    }
  }

  function formatDocExpiryDate(dateStr) {
    if (!dateStr) return '';
    const s = String(dateStr).trim();
    const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (m) {
      const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
      const day = m[3];
      const mon = months[parseInt(m[2], 10) - 1] || m[2];
      return `${day} ${mon} ${m[1]}`;
    }
    try {
      const d = new Date(s);
      if (!isNaN(d.getTime())) {
        return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
      }
    } catch (e) {}
    return s;
  }

  function wasDocumentEdited(doc) {
    if (!doc) return false;
    if (typeof doc.isEdited === 'boolean') return doc.isEdited;
    const updMs = Date.parse(doc.updatedAt || '') || 0;
    const creMs = Date.parse(doc.createdAt || '') || 0;
    if (creMs && updMs) return Math.abs(updMs - creMs) > 5000;
    const idMatch = String(doc.id || '').match(/^doc_(?:scan|studio)_(\d{10,15})/);
    if (idMatch && updMs) {
      return Math.abs(updMs - Number(idMatch[1])) > 5000;
    }
    if (doc.kind === 'studio_pdf' && updMs) {
      const seedMs = Date.parse('2026-03-01T10:00:00.000Z') || 0;
      return Math.abs(updMs - seedMs) > 5000;
    }
    return false;
  }

  function formatDocCardStatusLine(doc) {
    if (!doc) return '';
    if (doc.expiryDate && String(doc.expiryDate).trim()) {
      return `Exp: ${formatDocExpiryDate(doc.expiryDate)}`;
    }
    const prefix = wasDocumentEdited(doc) ? 'Last Edited' : 'Logged';
    return `${prefix}: ${formatDocUpdatedDate(doc.updatedAt || doc.createdAt)}`;
  }

  function buildRealA4PreviewHtml(doc) {
    const po = doc.studioData || {};
    const typo = Object.assign({
      fontFamily: "'Plus Jakarta Sans', -apple-system, sans-serif",
      fontSize: 12.5,
      lineHeight: 1.5,
      sectionGap: 16,
      titleGap: 5,
      titleSize: 11,
      sheetPadding: '36px 40px'
    }, po.typography || {});
    const elStyles = po.elementStyles || {};
    const rich = po.richText || {};
    const sender = po.sender || getMasterPoTemplate().sender || {
      name: '',
      title: '',
      contact: '',
      location: ''
    };

    const headingSt = Object.assign({ fontSize: 22, fontWeight: '800', letterSpacing: '-0.02em', color: '#0f172a' }, elStyles.doc_heading || {});
    const subSt = Object.assign({ fontSize: 10.5, fontWeight: '700', letterSpacing: '0.08em', color: '#475569' }, elStyles.doc_subtitle || {});

    const sections = Array.isArray(po.sections) ? po.sections : [];
    const sectionsInnerHtml = sections.map(sec => {
      if (!sec) return '';
      if (sec.type === 'header') {
        const headingInner = rich.doc_heading || escapeHtml(po.docTitle || 'DOCUMENT');
        const subtitleInner = rich.doc_subtitle || escapeHtml(po.docSubtitle || '');
        const senderNameInner = rich.sender_name || escapeHtml(sender.name || '');
        const senderTitleInner = rich.sender_title || escapeHtml(sender.title || '');
        const senderContactInner = rich.sender_contact || escapeHtml(sender.contact || '');
        const senderLocationInner = rich.sender_location || escapeHtml(sender.location || '');
        return `
          <div style="display:flex; align-items:flex-start; justify-content:space-between; gap:20px;">
            <div style="flex:1; min-width:0;">
              <div style="font-size:${Number(headingSt.fontSize) || 22}px; font-weight:${headingSt.fontWeight || '800'}; letter-spacing:${headingSt.letterSpacing || '-0.02em'}; color:${headingSt.color || '#0f172a'}; line-height:1.15;">${headingInner}</div>
              ${(po.docSubtitle || rich.doc_subtitle) ? `<div style="font-size:${Number(subSt.fontSize) || 10.5}px; font-weight:${subSt.fontWeight || '700'}; letter-spacing:${subSt.letterSpacing || '0.08em'}; color:${subSt.color || '#475569'}; text-transform:uppercase; margin-top:4px; line-height:1.3;">${subtitleInner}</div>` : ''}
            </div>
            <div style="text-align:right; flex-shrink:0; font-size:10.5px; line-height:1.38; color:#64748b;">
              ${(sender.name || rich.sender_name) ? `<div style="font-weight:700; color:#0f172a; font-size:11px;">${senderNameInner}</div>` : ''}
              ${(sender.title || rich.sender_title) ? `<div>${senderTitleInner}</div>` : ''}
              ${(sender.contact || rich.sender_contact) ? `<div>${senderContactInner}</div>` : ''}
              ${(sender.location || rich.sender_location) ? `<div style="color:#94a3b8; font-size:10px;">${senderLocationInner}</div>` : ''}
            </div>
          </div>
        `;
      }
      if (sec.type === 'divider') {
        return `<div style="height:1.5px; background:#cbd5e1; width:100%; margin:1px 0;"></div>`;
      }
      const titleSt = Object.assign({
        fontSize: Number(typo.titleSize) || 11,
        fontWeight: '800',
        letterSpacing: '0.06em',
        color: '#0f172a',
        lineHeight: 1.25,
        textAlign: 'left'
      }, elStyles['title_' + sec.id] || {});
      const contentSt = Object.assign({
        fontSize: Number(typo.fontSize) || 12.2,
        lineHeight: Number(typo.lineHeight) || 1.5,
        color: '#334155',
        textAlign: 'left'
      }, elStyles['content_' + sec.id] || {});
      const secTitleInner = rich['title_' + sec.id] || escapeHtml(sec.title || '');
      const titleHtml = (sec.title || rich['title_' + sec.id])
        ? `<div style="font-size:${Number(titleSt.fontSize) || 11}px; font-weight:${titleSt.fontWeight || '800'}; text-transform:uppercase; letter-spacing:${titleSt.letterSpacing || '0.06em'}; color:${titleSt.color || '#0f172a'}; margin-bottom:${Number(typo.titleGap) || 5}px; line-height:${Number(titleSt.lineHeight) || 1.25}; text-align:${titleSt.textAlign || 'left'};">${secTitleInner}</div>`
        : '';
      const rawRich = rich['content_' + sec.id];
      const bodyHtml = rawRich || formatInitialContent(sec.content || '');
      return `
        <div>
          ${titleHtml}
          <div style="font-size:${Number(contentSt.fontSize) || 12.2}px; line-height:${Number(contentSt.lineHeight) || 1.5}; color:${contentSt.color || '#334155'}; text-align:${contentSt.textAlign || 'left'};">${bodyHtml}</div>
        </div>
      `;
    }).join('');

    return `
      <div class="w-[246px] h-[204px] bg-white rounded-t-lg shadow-[0_6px_20px_-4px_rgba(15,23,42,0.14),0_0_0_1px_rgba(15,23,42,0.07)] overflow-hidden shrink-0 group-hover:-translate-y-0.5 transition-transform duration-200 relative">
        <div style="width:794px; min-height:680px; transform:scale(0.3098); transform-origin:top left; padding:${escapeHtml(typo.sheetPadding || '36px 40px')}; font-family:${escapeHtml(typo.fontFamily || "'Plus Jakarta Sans', -apple-system, sans-serif")}; background:#ffffff; color:#1e293b; box-sizing:border-box; pointer-events:none; user-select:none; display:flex; flex-direction:column; gap:${Number(typo.sectionGap) || 16}px;">
          ${sectionsInnerHtml}
        </div>
        <div class="pointer-events-none absolute inset-x-0 bottom-0 h-5 bg-gradient-to-t from-white/95 to-transparent"></div>
      </div>
    `;
  }

  function renderDocCategoryFilterBar(activeFilter, docs) {
    const bar = document.getElementById('docCategoryFilterBar');
    if (!bar) return;
    const nonDraftDocs = (docs || []).filter(d => !d.isDraft);
    const totalCount = nonDraftDocs.length;
    const catKeys = getOrderedDocCategoryKeys();

    const allIsActive = activeFilter === 'all';
    const allPillHtml = `
      <button type="button" data-doc-filter="all" class="doc-filter-pill ${allIsActive ? 'active bg-slate-900 text-white border-slate-900 shadow-2xs font-semibold' : 'bg-white text-slate-600 border-slate-200/90 hover:border-slate-300 hover:text-slate-900 hover:bg-slate-50/80 font-medium'} inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs border transition-all duration-150 cursor-pointer whitespace-nowrap shrink-0">
        <i data-lucide="layers" class="w-3.5 h-3.5 ${allIsActive ? 'text-white' : 'text-slate-500'} shrink-0"></i>
        <span>All</span>
        <span class="text-[10px] font-bold px-1.5 py-0.2 rounded-full ${allIsActive ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'}">${totalCount}</span>
      </button>
    `;

    const catPillsHtml = catKeys.map(catId => {
      const meta = DOC_CATEGORY_META[catId] || DOC_CATEGORY_META.other;
      const isActive = activeFilter === catId;
      const count = nonDraftDocs.filter(d => (d.category || 'other') === catId).length;
      return `
        <div class="group/catpill relative inline-flex items-center shrink-0">
          <button type="button" data-doc-filter="${escapeHtml(catId)}" class="doc-filter-pill ${isActive ? 'active bg-slate-900 text-white border-slate-900 shadow-2xs font-semibold pr-6' : 'bg-white text-slate-600 border-slate-200/90 hover:border-slate-300 hover:text-slate-900 hover:bg-slate-50/80 font-medium group-hover/catpill:pr-6'} inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs border transition-all duration-150 cursor-pointer whitespace-nowrap shrink-0">
            <i data-lucide="${escapeHtml(meta.icon)}" class="w-3.5 h-3.5 ${isActive ? 'text-white' : (meta.iconCls || 'text-slate-500')} shrink-0"></i>
            <span>${escapeHtml(meta.label)}</span>
            ${count > 0 ? `<span class="text-[10px] font-bold px-1.5 py-0.2 rounded-full ${isActive ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'}">${count}</span>` : ''}
          </button>
          <button type="button" data-edit-doc-cat="${escapeHtml(catId)}" class="${isActive ? 'opacity-80 hover:opacity-100 text-white/80 hover:text-white' : 'opacity-0 group-hover/catpill:opacity-100 text-slate-400 hover:text-slate-700'} absolute right-1.5 top-1/2 -translate-y-1/2 w-4 h-4 rounded-md flex items-center justify-center transition-opacity cursor-pointer" title="Customize ${escapeHtml(meta.label)} category">
            <i data-lucide="settings-2" class="w-2.5 h-2.5"></i>
          </button>
        </div>
      `;
    }).join('');

    bar.innerHTML = allPillHtml + catPillsHtml;
  }

  function renderDocumentsView() {
    document.getElementById('earlyTabRestoreStyle')?.remove();
    if (document.querySelector('#viewDocuments .doc-inline-rename-input')) {
      return;
    }
    loadDocumentCategories();
    setupDocumentsListeners();
    if (!Array.isArray(state.documents) || state.documents.length === 0) {
      loadDocuments();
    }
    const docs = state.documents || [];
    if (state.documentsFilter === 'studio_pdf') state.documentsFilter = 'all';
    if (state.documentsFilter && state.documentsFilter !== 'all' && !DOC_CATEGORY_META[state.documentsFilter]) {
      state.documentsFilter = 'all';
    }
    const activeFilter = state.documentsFilter || 'all';
    const query = (state.documentsSearch || '').trim().toLowerCase();

    const setTxt = (id, val) => {
      const el = document.getElementById(id);
      if (el) el.textContent = String(val);
    };

    renderDocCategoryFilterBar(activeFilter, docs);

    const matchesSearchOnly = (doc) => {
      if (!query) return true;
      const hay = [
        doc.title,
        doc.subtitle,
        doc.notes,
        doc.fileName,
        doc.studioData?.docTitle,
        doc.studioData?.docSubtitle,
        ...(doc.studioData?.sections || []).map(s => `${s.title || ''} ${s.content || ''}`)
      ].filter(Boolean).join(' ').toLowerCase();
      return hay.includes(query);
    };

    const matchesQueryAndFilter = (doc) => {
      if (activeFilter === 'studio_pdf' && doc.kind !== 'studio_pdf') return false;
      if (activeFilter !== 'all' && DOC_CATEGORY_META[activeFilter] && (doc.category || 'other') !== activeFilter) return false;
      return matchesSearchOnly(doc);
    };

    const activeDocs = sortDocumentsList(
      docs.filter(d => !d.isDraft && matchesQueryAndFilter(d))
    );

    const draftDocs = sortDocumentsList(
      docs.filter(d => !!d.isDraft && matchesQueryAndFilter(d))
    );

    setTxt('docFilterCountAll', activeFilter === 'all' && !query ? docs.filter(d => !d.isDraft).length : activeDocs.length);

    const grid = document.getElementById('documentsGridContainer');
    if (!grid) return;

    const buildDocumentCardHtml = (doc) => {
      const catMeta = DOC_CATEGORY_META[doc.category] || DOC_CATEGORY_META.other;
      const effectiveIcon = catMeta.icon;
      const isDraft = !!doc.isDraft;
      const draftActionBtnHtml = isDraft
        ? `<button type="button" class="doc-toggle-draft-btn h-6 px-2 rounded-lg bg-amber-50/95 hover:bg-emerald-50 border border-amber-200 hover:border-emerald-200 text-amber-700 hover:text-emerald-700 text-[10px] font-semibold shadow-2xs inline-flex items-center gap-1 transition-colors cursor-pointer" data-doc-id="${escapeHtml(doc.id)}" title="Mark as Finalized (Move to Documents)">
             <i data-lucide="arrow-up-right" class="w-3 h-3"></i>
             <span>Finalize</span>
           </button>`
        : `<button type="button" class="doc-toggle-draft-btn h-6 px-2 rounded-lg bg-white/95 hover:bg-amber-50 border border-slate-200/90 hover:border-amber-200 text-slate-500 hover:text-amber-700 text-[10px] font-semibold shadow-2xs inline-flex items-center gap-1 transition-colors cursor-pointer" data-doc-id="${escapeHtml(doc.id)}" title="Move to Drafts">
             <i data-lucide="file-clock" class="w-3 h-3"></i>
             <span>Draft</span>
           </button>`;

      const categoryBadgeBtnHtml = `
        <button type="button" class="doc-change-category-btn inline-flex items-center gap-1 text-[10px] font-semibold px-2 py-0.5 rounded-md border shadow-2xs backdrop-blur-xs pointer-events-auto cursor-pointer hover:brightness-95 transition-all ${catMeta.badgeCls}" data-doc-id="${escapeHtml(doc.id)}" title="Click to change category (${escapeHtml(catMeta.label)})">
          <i data-lucide="${escapeHtml(effectiveIcon)}" class="w-3 h-3 ${catMeta.iconCls || ''} shrink-0"></i>
          <span>${escapeHtml(catMeta.label)}</span>
          <i data-lucide="chevron-down" class="w-2.5 h-2.5 opacity-70 shrink-0"></i>
        </button>
      `;

      if (doc.kind === 'studio_pdf') {
        const a4PreviewHtml = buildRealA4PreviewHtml(doc);
        const studioStatusLine = escapeHtml(formatDocCardStatusLine(doc));
        return `
          <div draggable="true" data-doc-card-id="${escapeHtml(doc.id)}" class="group bg-white border ${isDraft ? 'border-amber-200/80 hover:border-amber-300' : 'border-slate-200/85 hover:border-slate-300'} rounded-2xl overflow-hidden shadow-2xs hover:shadow-md transition-all flex flex-col">
            <!-- Top Miniature A4 Document Preview Stage -->
            <div class="doc-open-studio-btn h-[218px] bg-slate-100/85 border-b border-slate-200/75 relative overflow-hidden flex items-start justify-center pt-3.5 px-4 cursor-pointer select-none" data-doc-id="${escapeHtml(doc.id)}">
              <div class="absolute top-2.5 left-2.5 z-10 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-150">
                ${categoryBadgeBtnHtml}
              </div>

              <div class="absolute top-2.5 right-2.5 z-10 flex items-center gap-1 ${doc.pinned ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'} transition-opacity duration-150">
                ${draftActionBtnHtml}
                <button type="button" class="doc-toggle-pin-btn w-6 h-6 rounded-lg border shadow-2xs flex items-center justify-center transition-colors cursor-pointer ${doc.pinned ? 'bg-amber-50 border-amber-200 text-amber-500' : 'bg-white/95 hover:bg-white border-slate-200/90 text-slate-400 hover:text-amber-500'}" data-doc-id="${escapeHtml(doc.id)}" title="${doc.pinned ? 'Unpin' : 'Pin to top'}">
                  <i data-lucide="pin" class="w-3 h-3 ${doc.pinned ? 'fill-amber-400' : ''}"></i>
                </button>
                <button type="button" class="doc-duplicate-studio-btn w-6 h-6 rounded-lg bg-white/95 hover:bg-white border border-slate-200/90 text-slate-400 hover:text-slate-700 shadow-2xs flex items-center justify-center transition-colors cursor-pointer" data-doc-id="${escapeHtml(doc.id)}" title="Duplicate">
                  <i data-lucide="copy" class="w-3 h-3"></i>
                </button>
                <button type="button" class="doc-delete-btn w-6 h-6 rounded-lg bg-white/95 hover:bg-white border border-slate-200/90 text-slate-400 hover:text-rose-600 shadow-2xs flex items-center justify-center transition-colors cursor-pointer" data-doc-id="${escapeHtml(doc.id)}" title="Delete">
                  <i data-lucide="trash-2" class="w-3 h-3"></i>
                </button>
              </div>

              ${a4PreviewHtml}
            </div>

            <!-- Bottom Metadata & Actions Bar -->
            <div class="p-3.5 bg-white flex items-center justify-between gap-2.5">
              <div class="flex items-center gap-2.5 min-w-0 flex-1">
                <button type="button" class="doc-change-category-btn w-8 h-8 rounded-xl border flex items-center justify-center shrink-0 cursor-pointer hover:scale-105 transition-all ${catMeta.iconBoxCls}" data-doc-id="${escapeHtml(doc.id)}" title="Category: ${escapeHtml(catMeta.label)} — Click to change">
                  <i data-lucide="${escapeHtml(effectiveIcon)}" class="w-4 h-4"></i>
                </button>
                <div class="min-w-0 flex-1">
                  <div class="flex items-center gap-1 min-w-0">
                    <h4 class="doc-card-title font-semibold text-sm text-slate-900 truncate cursor-pointer hover:text-indigo-600 transition-colors" data-doc-id="${escapeHtml(doc.id)}" title="${escapeHtml(doc.title)}">${escapeHtml(doc.title)}</h4>
                    <button type="button" class="doc-rename-btn opacity-0 group-hover:opacity-100 p-1 rounded-md text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-all cursor-pointer shrink-0" data-doc-id="${escapeHtml(doc.id)}" title="Rename">
                      <i data-lucide="pencil" class="w-3 h-3"></i>
                    </button>
                    <button type="button" class="doc-edit-details-btn opacity-0 group-hover:opacity-100 p-1 rounded-md text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 transition-all cursor-pointer shrink-0" data-doc-id="${escapeHtml(doc.id)}" title="Edit category, icon, title & details">
                      <i data-lucide="sliders-horizontal" class="w-3 h-3"></i>
                    </button>
                  </div>
                  <p class="doc-card-subtitle text-[11px] text-slate-400 hover:text-slate-600 truncate mt-0.5 cursor-pointer transition-colors" data-doc-id="${escapeHtml(doc.id)}" title="Click to edit details">${studioStatusLine}</p>
                </div>
              </div>

              <div class="flex items-center gap-1.5 shrink-0">
                <button type="button" class="doc-quick-export-pdf-btn px-2.5 py-1.5 rounded-lg bg-slate-100 hover:bg-slate-200/80 text-slate-700 text-xs font-semibold inline-flex items-center gap-1 transition-colors cursor-pointer whitespace-nowrap shrink-0" data-doc-id="${escapeHtml(doc.id)}" title="Export PDF">
                  <i data-lucide="printer" class="w-3 h-3 shrink-0"></i>
                  <span>PDF</span>
                </button>
                <button type="button" class="doc-open-studio-btn px-3 py-1.5 rounded-lg bg-slate-900 hover:bg-slate-800 text-white text-xs font-semibold inline-flex items-center gap-1 transition-colors cursor-pointer whitespace-nowrap shrink-0" data-doc-id="${escapeHtml(doc.id)}">
                  <i data-lucide="pen-line" class="w-3 h-3 shrink-0"></i>
                  <span>Edit</span>
                </button>
              </div>
            </div>
          </div>
        `;
      }

      // Uploaded Scan / File Card
      const isImage = doc.fileType === 'image' || String(doc.mimeType || '').startsWith('image/');
      const isPdf = doc.fileType === 'pdf' || String(doc.mimeType || '').includes('pdf');
      const scanStatusLine = escapeHtml(formatDocCardStatusLine(doc));
      return `
        <div draggable="true" data-doc-card-id="${escapeHtml(doc.id)}" class="group bg-white border ${isDraft ? 'border-amber-200/80 hover:border-amber-300' : 'border-slate-200/85 hover:border-slate-300'} rounded-2xl overflow-hidden shadow-2xs hover:shadow-md transition-all flex flex-col">
          <!-- Top Visual Scan / PDF Preview Stage -->
          <div class="doc-open-viewer-btn h-[218px] bg-slate-100/85 border-b border-slate-200/75 relative overflow-hidden flex items-center justify-center p-3.5 cursor-pointer select-none" data-doc-id="${escapeHtml(doc.id)}">
            <div class="absolute top-2.5 left-2.5 z-10 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-150">
              ${categoryBadgeBtnHtml}
            </div>

            <div class="absolute top-2.5 right-2.5 z-10 flex items-center gap-1 ${doc.pinned ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'} transition-opacity duration-150">
              ${draftActionBtnHtml}
              <button type="button" class="doc-toggle-pin-btn w-6 h-6 rounded-lg border shadow-2xs flex items-center justify-center transition-colors cursor-pointer ${doc.pinned ? 'bg-amber-50 border-amber-200 text-amber-500' : 'bg-white/95 hover:bg-white border-slate-200/90 text-slate-400 hover:text-amber-500'}" data-doc-id="${escapeHtml(doc.id)}" title="${doc.pinned ? 'Unpin' : 'Pin to top'}">
                <i data-lucide="pin" class="w-3 h-3 ${doc.pinned ? 'fill-amber-400' : ''}"></i>
              </button>
              <button type="button" class="doc-delete-btn w-6 h-6 rounded-lg bg-white/95 hover:bg-white border border-slate-200/90 text-slate-400 hover:text-rose-600 shadow-2xs flex items-center justify-center transition-colors cursor-pointer" data-doc-id="${escapeHtml(doc.id)}" title="Delete">
                <i data-lucide="trash-2" class="w-3 h-3"></i>
              </button>
            </div>

            <img data-doc-thumb-id="${escapeHtml(doc.id)}" draggable="false" data-pin-nopin="true" nopin="nopin" alt="${escapeHtml(doc.title)}" class="hidden max-w-[88%] max-h-[186px] object-contain rounded-lg shadow-[0_6px_20px_-4px_rgba(15,23,42,0.14),0_0_0_1px_rgba(15,23,42,0.08)] bg-white group-hover:-translate-y-0.5 transition-transform duration-200">

            <div class="doc-thumb-fallback w-[156px] h-[188px] bg-white rounded-lg shadow-[0_6px_20px_-4px_rgba(15,23,42,0.12),0_0_0_1px_rgba(15,23,42,0.07)] flex flex-col items-center justify-center p-3 text-center group-hover:-translate-y-0.5 transition-transform duration-200">
              <div class="w-9 h-9 rounded-xl border flex items-center justify-center mb-2 ${catMeta.iconBoxCls}">
                <i data-lucide="${escapeHtml(effectiveIcon)}" class="w-4 h-4"></i>
              </div>
              <span class="text-[11px] font-semibold text-slate-700 line-clamp-2 leading-tight">${escapeHtml(doc.title)}</span>
              <span class="text-[9px] font-medium uppercase tracking-wider text-slate-400 mt-1">${isPdf ? 'PDF Document' : 'Scanned Image'}</span>
            </div>
          </div>

          <!-- Bottom Metadata & Actions Bar -->
          <div class="p-3.5 bg-white flex items-center justify-between gap-2.5">
            <div class="flex items-center gap-2.5 min-w-0 flex-1">
              <button type="button" class="doc-change-category-btn w-8 h-8 rounded-xl border flex items-center justify-center shrink-0 cursor-pointer hover:scale-105 transition-all ${catMeta.iconBoxCls}" data-doc-id="${escapeHtml(doc.id)}" title="Category: ${escapeHtml(catMeta.label)} — Click to change">
                <i data-lucide="${escapeHtml(effectiveIcon)}" class="w-4 h-4"></i>
              </button>
              <div class="min-w-0 flex-1">
                <div class="flex items-center gap-1 min-w-0">
                  <h4 class="doc-card-title font-semibold text-sm text-slate-900 truncate cursor-pointer hover:text-indigo-600 transition-colors" data-doc-id="${escapeHtml(doc.id)}" title="${escapeHtml(doc.title)}">${escapeHtml(doc.title)}</h4>
                  <button type="button" class="doc-rename-btn opacity-0 group-hover:opacity-100 p-1 rounded-md text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-all cursor-pointer shrink-0" data-doc-id="${escapeHtml(doc.id)}" title="Rename">
                    <i data-lucide="pencil" class="w-3 h-3"></i>
                  </button>
                  <button type="button" class="doc-edit-details-btn opacity-0 group-hover:opacity-100 p-1 rounded-md text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 transition-all cursor-pointer shrink-0" data-doc-id="${escapeHtml(doc.id)}" title="Edit category, icon, title & details">
                    <i data-lucide="sliders-horizontal" class="w-3 h-3"></i>
                  </button>
                </div>
                <p class="doc-card-subtitle text-[11px] text-slate-400 hover:text-slate-600 truncate mt-0.5 cursor-pointer transition-colors" data-doc-id="${escapeHtml(doc.id)}" title="Click to edit details">${scanStatusLine}</p>
              </div>
            </div>

            <div class="flex items-center gap-1.5 shrink-0">
              <button type="button" class="doc-download-vault-btn px-2.5 py-1.5 rounded-lg bg-slate-100 hover:bg-slate-200/80 text-slate-700 text-xs font-semibold inline-flex items-center gap-1 transition-colors cursor-pointer whitespace-nowrap shrink-0" data-doc-id="${escapeHtml(doc.id)}" title="Download">
                <i data-lucide="download" class="w-3 h-3 shrink-0"></i>
                <span>Save</span>
              </button>
              <button type="button" class="doc-open-viewer-btn px-3 py-1.5 rounded-lg bg-slate-900 hover:bg-slate-800 text-white text-xs font-semibold inline-flex items-center gap-1 transition-colors cursor-pointer whitespace-nowrap shrink-0" data-doc-id="${escapeHtml(doc.id)}">
                <i data-lucide="eye" class="w-3 h-3 shrink-0"></i>
                <span>View</span>
              </button>
            </div>
          </div>
        </div>
      `;
    };

    const cardsHtml = activeDocs.map(buildDocumentCardHtml).join('');

    // End-of-grid Add / Drop Document card (context-aware to active category tab)
    const activeCatMeta = (activeFilter !== 'all' && DOC_CATEGORY_META[activeFilter])
      ? DOC_CATEGORY_META[activeFilter]
      : null;
    const dropzoneTitle = activeCatMeta
      ? `Drop scan or PDF into ${activeCatMeta.label}`
      : 'Drop scan or PDF here';
    const dropzoneSub = activeCatMeta
      ? `Automatically tagged as ${activeCatMeta.label}, or drag any card onto the top bar`
      : 'Drag any card onto a category tab above to move & sort it automatically';

    const addCardHtml = `
      <div id="docVaultDropzone" class="doc-drop-card border-2 border-dashed border-slate-200/90 hover:border-indigo-400 bg-slate-50/35 hover:bg-indigo-50/20 rounded-2xl p-5 transition-all flex flex-col items-center justify-center gap-3 min-h-[282px] text-center group cursor-pointer">
        <div class="w-10 h-10 rounded-2xl ${activeCatMeta ? activeCatMeta.iconBoxCls : 'bg-slate-100 group-hover:bg-indigo-100/80 text-slate-400 group-hover:text-indigo-600'} flex items-center justify-center transition-colors">
          <i data-lucide="${activeCatMeta ? activeCatMeta.icon : 'upload-cloud'}" class="w-5 h-5"></i>
        </div>
        <div>
          <p class="text-xs font-semibold text-slate-700 group-hover:text-indigo-700 transition-colors">${escapeHtml(dropzoneTitle)}</p>
          <p class="text-[11px] text-slate-400 mt-0.5">${escapeHtml(dropzoneSub)}</p>
        </div>
        <div class="flex items-center gap-2 pt-1">
          <span class="doc-trigger-upload-btn px-3 py-1.5 rounded-lg bg-white border border-slate-200/90 hover:border-slate-300 text-slate-700 text-xs font-semibold shadow-2xs transition-all whitespace-nowrap">Upload File</span>
          <span class="doc-trigger-new-pdf-btn px-3 py-1.5 rounded-lg bg-slate-900 hover:bg-slate-800 text-white text-xs font-semibold shadow-2xs transition-all whitespace-nowrap">+ New PDF</span>
        </div>
      </div>
    `;

    grid.innerHTML = cardsHtml + addCardHtml;
    grid.dataset.renderedSig = JSON.stringify({
      cats: (state.documentCategories || []).map(c => `${c.id}:${c.label}:${c.icon}:${c.color}`).join('|'),
      docs: (state.documents || []).map(d => [d.id, d.title, d.subtitle, d.category, d.customIcon || '', d.pinned, !!d.isDraft, d.sortOrder, d.expiryDate || '', !!d.isEdited, d.updatedAt, d._orderUpdatedAt || '', d.studioData?.docTitle, d.studioData?.richText?.doc_heading, (d.studioData?.sections || []).map(s => s.id).join(',')])
    });

    // Render Drafts Section at the bottom (scoped to the active category filter)
    const draftsGrid = document.getElementById('documentsDraftsGridContainer');
    const draftCountBadge = document.getElementById('documentsDraftCountBadge');
    const toggleDraftsText = document.getElementById('toggleDocumentsDraftsText');
    const toggleDraftsIcon = document.getElementById('toggleDocumentsDraftsIcon');
    const categoryDraftsCount = docs.filter(d => !!d.isDraft && (activeFilter === 'all' || (d.category || 'other') === activeFilter)).length;
    if (draftCountBadge) {
      draftCountBadge.textContent = activeCatMeta
        ? `${categoryDraftsCount} in ${activeCatMeta.label}`
        : `${categoryDraftsCount} ${categoryDraftsCount === 1 ? 'draft' : 'drafts'}`;
    }
    if (draftsGrid) {
      if (state.documentsDraftsCollapsed) {
        draftsGrid.classList.add('hidden');
        if (toggleDraftsText) toggleDraftsText.textContent = 'Show';
        if (toggleDraftsIcon) toggleDraftsIcon.setAttribute('data-lucide', 'chevron-down');
      } else {
        draftsGrid.classList.remove('hidden');
        if (toggleDraftsText) toggleDraftsText.textContent = 'Hide';
        if (toggleDraftsIcon) toggleDraftsIcon.setAttribute('data-lucide', 'chevron-up');
      }

      if (draftDocs.length > 0) {
        draftsGrid.innerHTML = draftDocs.map(buildDocumentCardHtml).join('');
      } else {
        const emptyDraftTitle = activeCatMeta
          ? `No ${activeCatMeta.label} documents in Drafts`
          : 'No documents in Drafts';
        draftsGrid.innerHTML = `
          <div class="col-span-full border-2 border-dashed border-slate-200/80 bg-slate-50/40 rounded-2xl py-6 px-4 text-center flex flex-col items-center justify-center gap-1.5">
            <div class="w-8 h-8 rounded-xl bg-amber-50 border border-amber-200/70 text-amber-600 flex items-center justify-center">
              <i data-lucide="file-clock" class="w-4 h-4"></i>
            </div>
            <p class="text-xs font-semibold text-slate-600">${escapeHtml(emptyDraftTitle)}</p>
            <p class="text-[11px] text-slate-400">Drag any unfinalized document card here or click <span class="font-semibold text-slate-600">Draft</span> on the top-right of a card</p>
          </div>
        `;
      }
    }

    // Hydrate image & PDF thumbnails asynchronously from IndexedDB / server across both grids
    document.querySelectorAll('#viewDocuments img[data-doc-thumb-id]').forEach(imgEl => {
      const id = imgEl.getAttribute('data-doc-thumb-id');
      hydrateDocVaultThumbnail(id, imgEl);
    });

    if (!vaultBackupSweepDoneOnce) {
      vaultBackupSweepDoneOnce = true;
      setTimeout(() => ensureAllVaultDocumentsBackedUp(), 3500);
    }

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  let vaultBackupSweepDoneOnce = false;
  let vaultBackupSweepRunning = false;
  async function ensureAllVaultDocumentsBackedUp() {
    if (vaultBackupSweepRunning) return;
    vaultBackupSweepRunning = true;
    try {
      const vaultDocs = (state.documents || []).filter(d => d && d.kind === 'vault_file' && d.id);
      const unverified = vaultDocs.filter(doc => {
        try {
          return localStorage.getItem('vault_att_verified_doc_vault_' + doc.id) !== '1';
        } catch (e) {
          return true;
        }
      });
      if (unverified.length === 0) return;

      const serverIds = await fetchServerAttachmentIdsSet();
      for (const doc of unverified) {
        const attId = `doc_vault_${doc.id}`;
        if (serverIds && serverIds.has(attId)) {
          try { localStorage.setItem('vault_att_verified_' + attId, '1'); } catch (e) {}
          continue;
        }
        const att = await getReceiptAttachment(attId);
        if (att && isValidAttachmentPayload(att)) {
          const ok = await postAttachmentToServer(attId, att);
          if (ok) {
            try { localStorage.setItem('vault_att_verified_' + attId, '1'); } catch (e) {}
          }
        }
      }
    } catch (e) {
    } finally {
      vaultBackupSweepRunning = false;
    }
  }

  function openStudioDocumentEditor(docId) {
    document.getElementById('earlyTabRestoreStyle')?.remove();
    loadDocuments();
    const doc = (state.documents || []).find(d => d.id === docId);
    if (!doc || doc.kind !== 'studio_pdf') return;

    clearTimeout(poAutoSaveTimeout);
    poAutoSaveTimeout = null;
    state.activeStudioDocId = doc.id;
    state.activePriceOfferingLeadId = doc.id;
    poEditingTemplateDesignId = null;
    poTemplateDesignEditBackup = null;
    poEditingTemplateNameId = null;

    try {
      history.replaceState(null, '', '#documents/studio:' + doc.id);
      recordFinlandRoute('#documents/studio:' + doc.id);
    } catch (e) {}

    // Hide Documents overview, show shared A4 WYSIWYG editor
    document.getElementById('viewDocuments')?.classList.add('hidden');
    document.getElementById('viewProjectFollowup')?.classList.add('hidden');
    const poPage = document.getElementById('priceOfferingDocPage');
    if (poPage) poPage.classList.remove('hidden');

    // Hide Templates & Price-Quote-only blocks in right sidebar for Studio Documents
    syncPoEditorModeUI(true);

    const catMeta = DOC_CATEGORY_META[doc.category] || DOC_CATEGORY_META.other;
    const bcClient = document.getElementById('priceOfferingDocClientBreadcrumb');
    if (bcClient) bcClient.textContent = doc.title || 'Document';
    const typeLabel = document.getElementById('priceOfferingDocTypeLabel');
    if (typeLabel) typeLabel.textContent = catMeta.label;

    const statusBadgeText = document.getElementById('priceOfferingSaveStatusText');
    const statusDot = document.getElementById('priceOfferingSaveStatusDot');
    if (statusBadgeText) statusBadgeText.textContent = 'Saved';
    if (statusDot) statusDot.className = 'w-1.5 h-1.5 rounded-full bg-emerald-500';

    if (!doc.studioData) {
      doc.studioData = { _studioDoc: true, _structuralMigrated: true, sections: [] };
    }
    const po = doc.studioData;
    po._studioDoc = true;
    po._structuralMigrated = true;

    if (doc.id === 'doc_cv_ori_gold') {
      const overwrittenCvHeadings = new Set(['', 'CV', 'Curriculum Vitae']);
      const curDocTitle = String(po.docTitle || '').trim();
      if (overwrittenCvHeadings.has(curDocTitle)) {
        po.docTitle = DEFAULT_CV_DOC_HEADING_TEXT;
      }
      if (!po.richText || typeof po.richText !== 'object') {
        po.richText = {};
      }
      const curRichHeading = String(po.richText.doc_heading || '').trim();
      if (!curRichHeading || curRichHeading === 'CV' || curRichHeading === 'Curriculum Vitae') {
        po.richText.doc_heading = DEFAULT_CV_DOC_HEADING_RICH;
      }
    }

    poElementStyles = (po.elementStyles && typeof po.elementStyles === 'object')
      ? JSON.parse(JSON.stringify(po.elementStyles))
      : {};
    poRichText = (po.richText && typeof po.richText === 'object')
      ? JSON.parse(JSON.stringify(po.richText))
      : {};
    poSelectedElementId = null;
    poSelectedElementMeta = null;

    const initialTypography = Object.assign({}, DEFAULT_PO_TEMPLATE.typography, po.typography || {});
    applyPriceOfferingTypography(initialTypography, false);

    currentPoSections = Array.isArray(po.sections) ? JSON.parse(JSON.stringify(po.sections)) : [];
    currentPoItems = Array.isArray(po.items) ? JSON.parse(JSON.stringify(po.items)) : [];
    selectedPoSectionIndex = null;

    const proxyTarget = getPoEditorTarget(doc.id);
    const printAreaEl = document.getElementById('priceOfferingPrintArea');
    if (printAreaEl) printAreaEl.innerHTML = '';
    renderPriceOfferingDocument(proxyTarget, po);
    if (typeof window.scrollTo === 'function') window.scrollTo({ top: 0, behavior: 'smooth' });

    setTimeout(() => {
      poUndoStack = [getPoDocumentSnapshot()];
      poRedoStack = [];
      updatePoUndoRedoUI();
    }, 60);
  }

  function exportStudioDocumentPdfQuick(docId) {
    poCloseToDocsAfterPrint = true;
    openStudioDocumentEditor(docId);
    setTimeout(() => {
      exportPriceOfferingPdf();
    }, 180);
  }

  function buildNewStudioDocumentFromPreset(presetType, customTitle, customSubtitle, customCategory, customIcon = '') {
    const nowIso = new Date().toISOString();
    const id = 'doc_studio_' + Date.now();
    const masterSender = getMasterPoTemplate().sender || {};
    const baseSender = {
      name: masterSender.name || 'Studio',
      title: masterSender.title || '',
      contact: masterSender.contact || '',
      location: masterSender.location || ''
    };
    const allDocs = Array.isArray(state.documents) ? state.documents : [];

    if (presetType === 'cv') {
      const cvRef = allDocs.find(d => d && (d.id === 'doc_cv_ori_gold' || d.category === 'cv'));
      if (cvRef && cvRef.studioData) {
        const cloneData = JSON.parse(JSON.stringify(cvRef.studioData));
        return {
          id,
          kind: 'studio_pdf',
          category: customCategory || 'cv',
          customIcon: customIcon || '',
          pinned: false,
          title: customTitle || 'CV',
          subtitle: customSubtitle || cvRef.subtitle || 'Curriculum Vitae',
          notes: '',
          createdAt: nowIso,
          updatedAt: nowIso,
          isEdited: false,
          studioData: cloneData
        };
      }
    }

    if (presetType === 'pitch') {
      const pitchRef = allDocs.find(d => d && (d.id === 'doc_pitch_ori_gold' || d.category === 'pitch'));
      if (pitchRef && pitchRef.studioData) {
        const cloneData = JSON.parse(JSON.stringify(pitchRef.studioData));
        return {
          id,
          kind: 'studio_pdf',
          category: customCategory || 'pitch',
          customIcon: customIcon || '',
          pinned: false,
          title: customTitle || 'Client Pitch',
          subtitle: customSubtitle || pitchRef.subtitle || 'Capabilities & Selected Work',
          notes: '',
          createdAt: nowIso,
          updatedAt: nowIso,
          isEdited: false,
          studioData: cloneData
        };
      }
    }

    if (presetType === 'statement') {
      const stmtRef = allDocs.find(d => d && d.id === 'doc_statement_ori_gold');
      if (stmtRef && stmtRef.studioData) {
        const cloneData = JSON.parse(JSON.stringify(stmtRef.studioData));
        return {
          id,
          kind: 'studio_pdf',
          category: customCategory || 'cv',
          customIcon: customIcon || '',
          pinned: false,
          title: customTitle || 'Artist Statement',
          subtitle: customSubtitle || stmtRef.subtitle || 'Bio & Practice Statement',
          notes: '',
          createdAt: nowIso,
          updatedAt: nowIso,
          isEdited: false,
          studioData: cloneData
        };
      }
    }

    // Blank Page
    const titleFinal = customTitle || 'Untitled Document';
    const subFinal = customSubtitle || '';
    const activeCatFallback = (state.documentsFilter && state.documentsFilter !== 'all' && DOC_CATEGORY_META[state.documentsFilter])
      ? state.documentsFilter
      : 'other';
    return {
      id,
      kind: 'studio_pdf',
      category: customCategory || activeCatFallback,
      customIcon: customIcon || '',
      pinned: false,
      title: titleFinal,
      subtitle: subFinal,
      notes: '',
      createdAt: nowIso,
      updatedAt: nowIso,
      isEdited: false,
      studioData: {
        _studioDoc: true,
        _structuralMigrated: true,
        templateId: 'tpl_studio_master',
        docTitle: titleFinal.toUpperCase(),
        docSubtitle: subFinal ? subFinal.toUpperCase() : '',
        sender: baseSender,
        typography: {
          fontFamily: "'Plus Jakarta Sans', -apple-system, sans-serif",
          fontSize: 12.5,
          lineHeight: 1.55,
          sectionGap: 18,
          titleGap: 6,
          titleSize: 11,
          sheetPadding: '36px 40px',
          showPageNumbers: true
        },
        elementStyles: {
          doc_heading: { fontSize: 22, fontWeight: '800', letterSpacing: '-0.02em' },
          doc_subtitle: { fontSize: 10.5, fontWeight: '700', letterSpacing: '0.09em', color: '#475569' }
        },
        richText: {},
        items: [],
        sections: [
          { id: 'sec_header', type: 'header', title: 'Document Header' },
          { id: 'sec_div_' + Date.now(), type: 'divider', title: 'Divider Line', content: '' },
          {
            id: 'sec_text_' + (Date.now() + 1),
            type: 'text',
            title: 'SECTION',
            content: 'Click here to edit text.'
          }
        ]
      }
    };
  }

