  // DOCUMENT & SCAN BANK UPLOAD + VIEWER MODAL
  // ==========================================
  let pendingVaultUploadFiles = [];
  let editingVaultDocId = null;
  let selectedDocUploadIcon = '';
  let selectedNewStudioIcon = '';
  let editingDocCategoryId = null;
  let selectedDocCategoryColor = 'indigo';
  let selectedDocCategoryIcon = 'folder';
  let docCategoryModalSavedCallback = null;
  let initialDocCategorySnapshot = null;
  let initialVaultUploadSnapshot = null;
  let activeCategoryPopoverDocId = null;
  let activeViewerDocId = null;
  let activeViewerZoom = 1;
  let activeViewerRotation = 0;
