  function renderDocCustomIconPicker(gridId, selectedIcon, fallbackCategory, onSelect) {
    const grid = document.getElementById(gridId);
    if (!grid) return;
    const catMeta = DOC_CATEGORY_META[fallbackCategory] || DOC_CATEGORY_META.other;
    const isAuto = !selectedIcon;

    const autoBtnHtml = `
      <button type="button" data-pick-doc-icon="" class="col-span-2 h-8 px-2 rounded-lg border text-[11px] font-semibold inline-flex items-center justify-center gap-1.5 transition-all cursor-pointer ${isAuto ? 'border-slate-900 bg-slate-900 text-white shadow-2xs' : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300 hover:bg-slate-50'}" title="Use category default icon (${escapeHtml(catMeta.label)})">
        <i data-lucide="${escapeHtml(catMeta.icon)}" class="w-3.5 h-3.5 shrink-0"></i>
        <span>Category Icon</span>
      </button>
    `;

    const iconsHtml = DOC_ICON_OPTIONS.map(opt => {
      const isSelected = selectedIcon === opt.id;
      return `
        <button type="button" data-pick-doc-icon="${escapeHtml(opt.id)}" class="h-8 rounded-lg border flex items-center justify-center transition-all cursor-pointer ${isSelected ? 'border-indigo-600 bg-indigo-50 text-indigo-700 ring-2 ring-indigo-500/20' : 'border-slate-200/90 bg-white text-slate-600 hover:border-slate-300 hover:text-slate-900 hover:bg-slate-50'}" title="${escapeHtml(opt.label)}">
          <i data-lucide="${escapeHtml(opt.id)}" class="w-3.5 h-3.5"></i>
        </button>
      `;
    }).join('');

    grid.innerHTML = autoBtnHtml + iconsHtml;
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    grid.onclick = (e) => {
      const btn = e.target.closest('[data-pick-doc-icon]');
      if (!btn) return;
      const iconId = btn.getAttribute('data-pick-doc-icon') || '';
      if (typeof onSelect === 'function') onSelect(iconId);
      renderDocCustomIconPicker(gridId, iconId, fallbackCategory, onSelect);
    };
  }

  function renderDocCategoryModalPickers() {
    const activeTheme = DOC_COLOR_THEMES[selectedDocCategoryColor] || DOC_COLOR_THEMES.indigo;
    const activeIconMeta = DOC_ICON_OPTIONS.find(o => o.id === selectedDocCategoryIcon) || { id: selectedDocCategoryIcon || 'folder', label: 'Folder' };

    const previewBox = document.getElementById('docCategoryModalPreviewBox');
    const previewIcon = document.getElementById('docCategoryModalPreviewIcon');
    if (previewBox) {
      previewBox.className = `w-10 h-10 rounded-2xl border flex items-center justify-center shadow-xs transition-colors ${activeTheme.iconBoxCls}`;
    }
    if (previewIcon) {
      previewIcon.setAttribute('data-lucide', activeIconMeta.id);
    }

    const selectedIconLbl = document.getElementById('docSelectedIconLabel');
    if (selectedIconLbl) selectedIconLbl.textContent = activeIconMeta.label;

    const selectedColorLbl = document.getElementById('docSelectedColorLabel');
    if (selectedColorLbl) selectedColorLbl.textContent = activeTheme.label;

    const colorGrid = document.getElementById('docCategoryColorGrid');
    if (colorGrid) {
      colorGrid.innerHTML = Object.keys(DOC_COLOR_THEMES).map(colorKey => {
        const theme = DOC_COLOR_THEMES[colorKey];
        const isSelected = selectedDocCategoryColor === colorKey;
        return `
          <button type="button" data-pick-cat-color="${escapeHtml(colorKey)}" class="w-7 h-7 rounded-full ${theme.swatchCls} shrink-0 inline-flex items-center justify-center transition-all cursor-pointer ${isSelected ? 'ring-2 ring-offset-2 ring-slate-900 scale-110 shadow-sm' : 'opacity-80 hover:opacity-100 hover:scale-105'}" title="${escapeHtml(theme.label)}">
            ${isSelected ? '<i data-lucide="check" class="w-3.5 h-3.5 text-white stroke-[2.75] shrink-0"></i>' : ''}
          </button>
        `;
      }).join('');
      colorGrid.onclick = (e) => {
        const btn = e.target.closest('[data-pick-cat-color]');
        if (!btn) return;
        selectedDocCategoryColor = btn.getAttribute('data-pick-cat-color') || 'indigo';
        renderDocCategoryModalPickers();
      };
    }

    const iconGrid = document.getElementById('docCategoryIconGrid');
    if (iconGrid) {
      iconGrid.innerHTML = DOC_ICON_OPTIONS.map(opt => {
        const isSelected = selectedDocCategoryIcon === opt.id;
        return `
          <button type="button" data-pick-cat-icon="${escapeHtml(opt.id)}" class="h-10 rounded-xl border flex items-center justify-center transition-all cursor-pointer ${isSelected ? `${activeTheme.iconBoxCls} ring-2 ring-slate-900/15 scale-105 shadow-2xs` : 'border-slate-200/90 bg-white text-slate-600 hover:border-slate-300 hover:text-slate-900 hover:bg-slate-50'}" title="${escapeHtml(opt.label)}">
            <i data-lucide="${escapeHtml(opt.id)}" class="w-4 h-4"></i>
          </button>
        `;
      }).join('');
      iconGrid.onclick = (e) => {
        const btn = e.target.closest('[data-pick-cat-icon]');
        if (!btn) return;
        selectedDocCategoryIcon = btn.getAttribute('data-pick-cat-icon') || 'folder';
        renderDocCategoryModalPickers();
      };
    }

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  }

  function getDocCategoryModalSnapshot() {
    const nameInp = document.getElementById('docCategoryNameInput');
    return JSON.stringify({
      name: (nameInp?.value || '').trim(),
      color: selectedDocCategoryColor || 'indigo',
      icon: selectedDocCategoryIcon || 'folder'
    });
  }

  function isDocCategoryModalDirty() {
    const modal = document.getElementById('docCategoryModal');
    if (!modal || modal.classList.contains('hidden')) return false;
    if (!initialDocCategorySnapshot) return false;
    return getDocCategoryModalSnapshot() !== initialDocCategorySnapshot;
  }

  function openDocCategoryModal(editCatId = null, onSavedCallback = null) {
    loadDocumentCategories();
    editingDocCategoryId = editCatId || null;
    docCategoryModalSavedCallback = typeof onSavedCallback === 'function' ? onSavedCallback : null;

    const modal = document.getElementById('docCategoryModal');
    const titleEl = document.getElementById('docCategoryModalTitle');
    const nameInp = document.getElementById('docCategoryNameInput');
    const delBtn = document.getElementById('docDeleteCategoryModalBtn');

    const existing = editCatId
      ? (state.documentCategories || []).find(c => c.id === editCatId)
      : null;

    if (existing) {
      if (titleEl) titleEl.textContent = `Customize "${existing.label}"`;
      if (nameInp) nameInp.value = existing.label || '';
      selectedDocCategoryColor = existing.color || 'indigo';
      selectedDocCategoryIcon = existing.icon || 'folder';
      if (delBtn) {
        if ((state.documentCategories || []).length > 1 && existing.id !== 'other') {
          delBtn.classList.remove('hidden');
          delBtn.classList.add('inline-flex');
        } else {
          delBtn.classList.add('hidden');
          delBtn.classList.remove('inline-flex');
        }
      }
    } else {
      if (titleEl) titleEl.textContent = 'New Category';
      if (nameInp) nameInp.value = '';
      selectedDocCategoryColor = 'indigo';
      selectedDocCategoryIcon = 'folder';
      if (delBtn) {
        delBtn.classList.add('hidden');
        delBtn.classList.remove('inline-flex');
      }
    }

    renderDocCategoryModalPickers();
    initialDocCategorySnapshot = getDocCategoryModalSnapshot();

    if (modal) {
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
    setTimeout(() => nameInp && nameInp.focus(), 40);
  }

  function closeDocCategoryModal() {
    const modal = document.getElementById('docCategoryModal');
    if (modal) {
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }
    editingDocCategoryId = null;
    docCategoryModalSavedCallback = null;
    initialDocCategorySnapshot = null;

    // Ensure any category select dropdown that triggered "+ Add New Category…" restores a valid selection if cancelled
    ['docUploadCategorySelect', 'docNewStudioCategorySelect'].forEach(selId => {
      const sel = document.getElementById(selId);
      if (sel && sel.value === '__new_category__') {
        const fallbackCat = (state.documentsFilter && state.documentsFilter !== 'all' && DOC_CATEGORY_META[state.documentsFilter])
          ? state.documentsFilter
          : (selId === 'docNewStudioCategorySelect' ? 'pitch' : 'other');
        sel.value = DOC_CATEGORY_META[fallbackCat] ? fallbackCat : (getOrderedDocCategoryKeys()[0] || 'other');
      }
    });
    syncDocModalCategoryPreviews();
  }

  function requestCloseDocCategoryModal() {
    if (!isDocCategoryModalDirty()) {
      closeDocCategoryModal();
      return;
    }
    openSettingsCancelConfirmModal(
      () => {
        saveDocCategoryFromModal();
      },
      () => {
        closeDocCategoryModal();
      }
    );
  }

  function saveDocCategoryFromModal() {
    const nameInp = document.getElementById('docCategoryNameInput');
    const label = (nameInp?.value || '').trim();
    if (!label) {
      showToast('Category Name Required', 'Please enter a name for the category.', 'error');
      nameInp?.focus();
      return;
    }

    loadDocumentCategories();
    let savedCatId = editingDocCategoryId;

    if (editingDocCategoryId) {
      const cat = (state.documentCategories || []).find(c => c.id === editingDocCategoryId);
      if (cat) {
        cat.label = label;
        cat.color = selectedDocCategoryColor || 'indigo';
        cat.icon = selectedDocCategoryIcon || 'folder';
      }
    } else {
      const slugBase = label.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 20) || 'cat';
      savedCatId = `cat_${slugBase}_${Date.now().toString(36).slice(-4)}`;
      const otherIdx = (state.documentCategories || []).findIndex(c => c.id === 'other');
      const newCatObj = {
        id: savedCatId,
        label,
        icon: selectedDocCategoryIcon || 'folder',
        color: selectedDocCategoryColor || 'indigo'
      };
      if (otherIdx >= 0) {
        state.documentCategories.splice(otherIdx, 0, newCatObj);
      } else {
        state.documentCategories.push(newCatObj);
      }
    }

    saveDocumentCategories();
    const cb = docCategoryModalSavedCallback;
    const wasEdit = Boolean(editingDocCategoryId);
    closeDocCategoryModal();
    renderDocumentsView();
    if (typeof cb === 'function' && savedCatId) {
      cb(savedCatId);
    }
    showToast(wasEdit ? 'Category Updated ✓' : 'Category Added ✓', `"${label}" is ready in the top bar.`, 'success');
  }

  async function deleteDocCategoryFromModal() {
    if (!editingDocCategoryId || editingDocCategoryId === 'other') return;
    const cat = (state.documentCategories || []).find(c => c.id === editingDocCategoryId);
    if (!cat) return;

    const affectedCount = (state.documents || []).filter(d => d.category === editingDocCategoryId).length;
    const confirmed = await confirmAction({
      title: `Delete "${cat.label}" Category?`,
      message: affectedCount > 0
        ? `${affectedCount} document(s) in "${cat.label}" will be moved to "Other".`
        : `Remove "${cat.label}" from the Documents category bar?`,
      confirmText: 'Delete Category',
      danger: true
    });
    if (!confirmed) return;

    if (!Array.isArray(state.deletedDocumentCategoryIds)) {
      state.deletedDocumentCategoryIds = [];
    }
    if (!state.deletedDocumentCategoryIds.includes(editingDocCategoryId)) {
      state.deletedDocumentCategoryIds.push(editingDocCategoryId);
    }
    state.documentCategories = (state.documentCategories || []).filter(c => c.id !== editingDocCategoryId);
    if (!state.documentCategories.some(c => c.id === 'other')) {
      state.documentCategories.push({ id: 'other', label: 'Other', icon: 'folder', color: 'indigo', sortOrder: 99 });
    }
    const nowIso = new Date().toISOString();
    (state.documents || []).forEach(d => {
      if (d.category === editingDocCategoryId) {
        d.category = 'other';
        d.updatedAt = nowIso;
      }
    });
    if (state.documentsFilter === editingDocCategoryId) {
      state.documentsFilter = 'all';
    }
    saveDocumentCategories();
    saveDocuments();
    closeDocCategoryModal();
    renderDocumentsView();
    showToast('Category Removed', `"${cat.label}" was deleted.`, 'info');
  }

  function closeDocCategoryPopover() {
    const pop = document.getElementById('docCategoryPickerPopover');
    if (pop) {
      pop.classList.add('hidden');
      pop.innerHTML = '';
    }
    activeCategoryPopoverDocId = null;
  }

  function updateDocumentCategoryAndResort(docId, newCategory, opts = {}) {
    const doc = (state.documents || []).find(d => d.id === docId);
    if (!doc || !DOC_CATEGORY_META[newCategory]) return;
    const prevCat = doc.category;
    const wasDraft = Boolean(doc.isDraft);
    doc.category = newCategory;
    if (opts && opts.unmarkDraft) {
      doc.isDraft = false;
    }
    if (prevCat !== newCategory) {
      doc.isEdited = true;
    }
    doc.updatedAt = new Date().toISOString();
    saveDocuments(doc.id);
    closeDocCategoryPopover();
    renderDocumentsView();

    // Update open viewer modal header if this document is currently open
    if (activeViewerDocId === doc.id) {
      const catMeta = DOC_CATEGORY_META[doc.category] || DOC_CATEGORY_META.other;
      const subEl = document.getElementById('docViewerSubtitle');
      if (subEl) {
        const statusLine = formatDocCardStatusLine(doc);
        subEl.textContent = statusLine ? `${catMeta.label} · ${statusLine}` : catMeta.label;
      }
      const catBtnLabel = document.getElementById('docViewerCategoryBtnLabel');
      if (catBtnLabel) catBtnLabel.textContent = catMeta.label;
    }

    if (prevCat !== newCategory || (wasDraft && !doc.isDraft)) {
      const catMeta = DOC_CATEGORY_META[newCategory] || DOC_CATEGORY_META.other;
      showToast(`Moved to ${catMeta.label} ✓`, `"${doc.title}" sorted into ${catMeta.label}`, 'success');
    }
  }

  function openDocCategoryPopover(docId, anchorEl) {
    const doc = (state.documents || []).find(d => d.id === docId);
    const pop = document.getElementById('docCategoryPickerPopover');
    if (!doc || !pop || !anchorEl) return;

    if (!pop.classList.contains('hidden') && activeCategoryPopoverDocId === docId) {
      closeDocCategoryPopover();
      return;
    }
    activeCategoryPopoverDocId = docId;

    const categoryKeys = getOrderedDocCategoryKeys();
    const itemsHtml = categoryKeys.map(catKey => {
      const meta = DOC_CATEGORY_META[catKey] || DOC_CATEGORY_META.other;
      const isSelected = (doc.category || 'other') === catKey;
      return `
        <button type="button" data-pick-doc-cat="${escapeHtml(catKey)}" class="w-full px-2.5 py-1.5 rounded-xl text-left text-xs font-semibold flex items-center justify-between gap-2 transition-colors cursor-pointer ${isSelected ? 'bg-slate-900 text-white' : 'text-slate-700 hover:bg-slate-100'}">
          <span class="inline-flex items-center gap-2 min-w-0">
            <span class="w-5 h-5 rounded-md border flex items-center justify-center shrink-0 ${isSelected ? 'bg-white/15 border-white/20 text-white' : meta.iconBoxCls}">
              <i data-lucide="${escapeHtml(meta.icon)}" class="w-3 h-3"></i>
            </span>
            <span class="truncate">${escapeHtml(meta.label)}</span>
          </span>
          ${isSelected ? '<i data-lucide="check" class="w-3.5 h-3.5 text-emerald-400 shrink-0"></i>' : ''}
        </button>
      `;
    }).join('');

    const currentCatMeta = DOC_CATEGORY_META[doc.category] || DOC_CATEGORY_META.other;
    pop.innerHTML = `
      <div class="px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider text-slate-400 flex items-center justify-between">
        <span>Move to Category</span>
        <button type="button" data-pick-doc-action="new-category" class="text-indigo-600 hover:text-indigo-700 font-semibold normal-case tracking-normal cursor-pointer">+ New</button>
      </div>
      <div class="space-y-0.5 max-h-[240px] overflow-y-auto">${itemsHtml}</div>
      <div class="my-1 border-t border-slate-100"></div>
      <button type="button" data-pick-doc-action="customize-category" class="w-full px-2.5 py-1.5 rounded-xl text-left text-xs font-medium text-slate-600 hover:bg-slate-100 flex items-center gap-2 transition-colors cursor-pointer">
        <i data-lucide="palette" class="w-3.5 h-3.5 text-indigo-600 shrink-0"></i>
        <span class="truncate">Customize "${escapeHtml(currentCatMeta.label)}" Icon & Color…</span>
      </button>
      <button type="button" data-pick-doc-action="toggle-draft" class="w-full px-2.5 py-1.5 rounded-xl text-left text-xs font-medium text-slate-600 hover:bg-slate-100 flex items-center gap-2 transition-colors cursor-pointer">
        <i data-lucide="${doc.isDraft ? 'arrow-up-right' : 'file-clock'}" class="w-3.5 h-3.5 text-amber-600 shrink-0"></i>
        <span>${doc.isDraft ? 'Finalize to Documents' : 'Move to Drafts'}</span>
      </button>
      <button type="button" data-pick-doc-action="edit-details" class="w-full px-2.5 py-1.5 rounded-xl text-left text-xs font-medium text-slate-600 hover:bg-slate-100 flex items-center gap-2 transition-colors cursor-pointer">
        <i data-lucide="sliders-horizontal" class="w-3.5 h-3.5 text-slate-500 shrink-0"></i>
        <span>Edit Document Details…</span>
      </button>
    `;

    pop.classList.remove('hidden');
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }

    const rect = anchorEl.getBoundingClientRect();
    const popWidth = 220;
    const popHeight = pop.offsetHeight || 290;
    let left = rect.left;
    let top = rect.bottom + 6;
    if (left + popWidth > window.innerWidth - 12) {
      left = Math.max(12, window.innerWidth - popWidth - 12);
    }
    if (top + popHeight > window.innerHeight - 12) {
      top = Math.max(12, rect.top - popHeight - 6);
    }
    pop.style.left = `${Math.round(left)}px`;
    pop.style.top = `${Math.round(top)}px`;

    pop.onclick = (ev) => {
      ev.stopPropagation();
      const catBtn = ev.target.closest('[data-pick-doc-cat]');
      if (catBtn) {
        const chosenCat = catBtn.getAttribute('data-pick-doc-cat');
        updateDocumentCategoryAndResort(docId, chosenCat);
        return;
      }
      const actBtn = ev.target.closest('[data-pick-doc-action]');
      if (actBtn) {
        const act = actBtn.getAttribute('data-pick-doc-action');
        closeDocCategoryPopover();
        if (act === 'toggle-draft') {
          doc.isDraft = !doc.isDraft;
          doc.updatedAt = new Date().toISOString();
          if (doc.isDraft) state.documentsDraftsCollapsed = false;
          saveDocuments(doc.id);
          renderDocumentsView();
          showToast(doc.isDraft ? 'Moved to Drafts' : 'Finalized ✓', `"${doc.title}"`, doc.isDraft ? 'info' : 'success');
        } else if (act === 'edit-details') {
          openVaultEditModal(docId);
        } else if (act === 'customize-category') {
          openDocCategoryModal(doc.category || 'other', () => {
            renderDocumentsView();
          });
        } else if (act === 'new-category') {
          openDocCategoryModal(null, (newCatId) => {
            updateDocumentCategoryAndResort(docId, newCatId);
          });
        }
      }
    };
  }

  function openVaultUploadModalWithFiles(fileList, forcedCategory = null, forcedDraft = false) {
    const files = Array.from(fileList || []).filter(Boolean);
    if (files.length === 0) return;
    pendingVaultUploadFiles = files;
    editingVaultDocId = null;
    selectedDocUploadIcon = '';

    populateDocCategorySelects();

    const modal = document.getElementById('docVaultUploadModal');
    const modalTitleEl = document.getElementById('docVaultUploadModalTitle');
    const summaryRowEl = document.getElementById('docUploadFileSummaryRow');
    const summaryEl = document.getElementById('docUploadFileSummary');
    const titleInp = document.getElementById('docUploadTitleInput');
    const catSelect = document.getElementById('docUploadCategorySelect');
    const expiryInp = document.getElementById('docUploadExpiryInput');
    const pinCheck = document.getElementById('docUploadPinCheckbox');
    const draftCheck = document.getElementById('docUploadDraftCheckbox');

    const first = files[0];
    const cleanBaseName = first.name.replace(/\.[^.]+$/, '').replace(/[_-]+/g, ' ').trim();
    const sizeKb = Math.max(1, Math.round(first.size / 1024));

    if (modalTitleEl) modalTitleEl.textContent = 'Upload File';
    if (summaryRowEl) summaryRowEl.classList.remove('hidden');
    if (summaryEl) {
      summaryEl.textContent = files.length === 1
        ? `${first.name} (${sizeKb} KB)`
        : `${files.length} files (${first.name} + ${files.length - 1} more)`;
    }
    if (titleInp) {
      if (files.length === 1) {
        titleInp.value = cleanBaseName;
        titleInp.placeholder = 'Document title...';
      } else {
        titleInp.value = '';
        titleInp.placeholder = "Keep each file's own name (or type shared title)";
      }
    }

    // Automatically match active category filter when uploading inside a specific category tab,
    // or smart-detect from filename (English / German / Hebrew) when on "All"
    const targetCategory = (forcedCategory && DOC_CATEGORY_META[forcedCategory])
      ? forcedCategory
      : getActiveDefaultDocCategory(first.name);
    if (catSelect) {
      catSelect.value = targetCategory;
    }
    syncDocModalCategoryPreviews();

    if (expiryInp) expiryInp.value = '';
    if (pinCheck) pinCheck.checked = false;
    if (draftCheck) draftCheck.checked = !!forcedDraft;
    initialVaultUploadSnapshot = getVaultUploadModalSnapshot();

    if (modal) {
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }
    if (window.lucide) window.lucide.createIcons();
    setTimeout(() => titleInp && titleInp.focus(), 40);
  }

  function getVaultUploadModalSnapshot() {
    return JSON.stringify({
      title: (document.getElementById('docUploadTitleInput')?.value || '').trim(),
      category: document.getElementById('docUploadCategorySelect')?.value || '',
      expiryDate: (document.getElementById('docUploadExpiryInput')?.value || '').trim(),
      pinned: !!document.getElementById('docUploadPinCheckbox')?.checked,
      isDraft: !!document.getElementById('docUploadDraftCheckbox')?.checked
    });
  }

  function isVaultUploadModalDirty() {
    const modal = document.getElementById('docVaultUploadModal');
    if (!modal || modal.classList.contains('hidden')) return false;
    if (!initialVaultUploadSnapshot) return false;
    return getVaultUploadModalSnapshot() !== initialVaultUploadSnapshot;
  }

  function requestCloseVaultUploadModal() {
    if (!isVaultUploadModalDirty()) {
      closeVaultUploadModal();
      return;
    }
    openSettingsCancelConfirmModal(
      () => {
        savePendingVaultUploadFiles();
      },
      () => {
        closeVaultUploadModal();
      }
    );
  }

  function openVaultEditModal(docId) {
    const doc = (state.documents || []).find(d => d.id === docId);
    if (!doc) return;
    editingVaultDocId = doc.id;
    pendingVaultUploadFiles = [];
    selectedDocUploadIcon = doc.customIcon || '';

    populateDocCategorySelects();

    const modal = document.getElementById('docVaultUploadModal');
    const modalTitleEl = document.getElementById('docVaultUploadModalTitle');
    const summaryRowEl = document.getElementById('docUploadFileSummaryRow');
    const titleInp = document.getElementById('docUploadTitleInput');
    const catSelect = document.getElementById('docUploadCategorySelect');
    const expiryInp = document.getElementById('docUploadExpiryInput');
    const pinCheck = document.getElementById('docUploadPinCheckbox');
    const draftCheck = document.getElementById('docUploadDraftCheckbox');

    if (modalTitleEl) modalTitleEl.textContent = 'Edit Document';
    if (summaryRowEl) {
      summaryRowEl.classList.add('hidden');
    }
    if (titleInp) {
      titleInp.value = doc.title || '';
      titleInp.placeholder = 'Document title...';
    }
    const resolvedCat = DOC_CATEGORY_META[doc.category] ? doc.category : 'other';
    if (catSelect) {
      catSelect.value = resolvedCat;
    }
    syncDocModalCategoryPreviews();

    if (expiryInp) expiryInp.value = doc.expiryDate || '';
    if (pinCheck) pinCheck.checked = !!doc.pinned;
    if (draftCheck) draftCheck.checked = !!doc.isDraft;
    initialVaultUploadSnapshot = getVaultUploadModalSnapshot();

    if (modal) {
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }
    if (window.lucide) window.lucide.createIcons();
    setTimeout(() => titleInp && titleInp.focus(), 40);
  }

  function closeVaultUploadModal() {
    const modal = document.getElementById('docVaultUploadModal');
    if (modal) {
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }
    pendingVaultUploadFiles = [];
    editingVaultDocId = null;
    selectedDocUploadIcon = '';
    initialVaultUploadSnapshot = null;
    const fileInp = document.getElementById('docFileInput');
    if (fileInp) fileInp.value = '';
  }

  function readFileAsDataUrl(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => reject(reader.error);
      reader.readAsDataURL(file);
    });
  }

  async function savePendingVaultUploadFiles() {
    const customTitle = document.getElementById('docUploadTitleInput')?.value.trim() || '';
    const category = document.getElementById('docUploadCategorySelect')?.value || 'visa';
    const expiryDate = document.getElementById('docUploadExpiryInput')?.value.trim() || '';
    const pinned = !!document.getElementById('docUploadPinCheckbox')?.checked;
    const isDraft = !!document.getElementById('docUploadDraftCheckbox')?.checked;

    loadDocuments();

    if (editingVaultDocId) {
      const doc = (state.documents || []).find(d => d.id === editingVaultDocId);
      if (doc) {
        if (customTitle) doc.title = customTitle;
        doc.category = category;
        doc.customIcon = selectedDocUploadIcon || '';
        doc.expiryDate = expiryDate;
        doc.pinned = pinned;
        doc.isDraft = isDraft;
        if (isDraft) state.documentsDraftsCollapsed = false;
        doc.isEdited = true;
        doc.updatedAt = new Date().toISOString();
        saveDocuments(doc.id);
      }
      closeVaultUploadModal();
      renderDocumentsView();
      showToast('Updated ✓', 'Document details & category saved.', 'success');
      return;
    }

    if (!pendingVaultUploadFiles || pendingVaultUploadFiles.length === 0) {
      closeVaultUploadModal();
      return;
    }

    for (let i = 0; i < pendingVaultUploadFiles.length; i++) {
      const file = pendingVaultUploadFiles[i];
      const nowIso = new Date().toISOString();
      const docId = 'doc_scan_' + Date.now() + '_' + i;
      const isPdf = file.type === 'application/pdf' || /\.pdf$/i.test(file.name);
      const isImage = file.type.startsWith('image/') || /\.(jpe?g|png|webp|heic|gif)$/i.test(file.name);
      const dataUrl = await readFileAsDataUrl(file);
      if (!dataUrl || typeof dataUrl !== 'string' || !dataUrl.startsWith('data:') || dataUrl.length < 32) {
        showToast('Upload Error', `Could not read ${file.name}. Please try again.`, 'error');
        continue;
      }

      await saveReceiptAttachment(`doc_vault_${docId}`, {
        type: isPdf ? 'pdf' : (isImage ? 'image' : 'other'),
        mimeType: file.type || (isPdf ? 'application/pdf' : 'image/jpeg'),
        fileName: file.name,
        data: dataUrl
      });

      if (isImage) {
        const thumbUrl = await createDownscaledImageThumbUrl(dataUrl, 440);
        docVaultThumbCache[docId] = thumbUrl;
        await saveLocalCachedDocThumb(docId, thumbUrl);
      }

      const defaultFileTitle = file.name.replace(/\.[^.]+$/, '').replace(/[_-]+/g, ' ').trim() || file.name;
      const fileTitle = (pendingVaultUploadFiles.length === 1 && customTitle)
        ? customTitle
        : (customTitle ? `${customTitle} (${i + 1})` : defaultFileTitle);

      const newDoc = {
        id: docId,
        kind: 'vault_file',
        category,
        customIcon: selectedDocUploadIcon || '',
        pinned,
        isDraft,
        title: fileTitle,
        subtitle: '',
        notes: '',
        expiryDate,
        fileName: file.name,
        fileType: isPdf ? 'pdf' : (isImage ? 'image' : 'other'),
        mimeType: file.type || (isPdf ? 'application/pdf' : 'image/jpeg'),
        fileSize: file.size || 0,
        createdAt: nowIso,
        updatedAt: nowIso,
        isEdited: false
      };

      state.documents.unshift(newDoc);
    }

    if (isDraft) {
      state.documentsDraftsCollapsed = false;
    } else if (state.documentsFilter && state.documentsFilter !== 'all' && state.documentsFilter !== category) {
      // If user explicitly picked another category in the dropdown while filtered, switch to that category so they see their uploaded file immediately
      state.documentsFilter = category;
    }

    const catLabel = DOC_CATEGORY_META[category]?.label || 'Documents';
    saveDocuments();
    closeVaultUploadModal();
    renderDocumentsView();
    showToast('Saved ✓', isDraft ? 'Saved to Drafts.' : `Added to ${catLabel}.`, 'success');
  }

  function applyDocViewerTransforms() {
    const img = document.getElementById('docScanViewerImg');
    const pdfStage = document.getElementById('docScanViewerPdfPages');
    const zoomLabel = document.getElementById('docViewerZoomLabel');
    const bwBtn = document.getElementById('docViewerBwFilterBtn');
    if (zoomLabel) zoomLabel.textContent = `${Math.round(activeViewerZoom * 100)}%`;
    if (bwBtn) {
      bwBtn.classList.toggle('bg-slate-900', activeViewerBwFilter);
      bwBtn.classList.toggle('text-white', activeViewerBwFilter);
      bwBtn.classList.toggle('border-slate-900', activeViewerBwFilter);
    }
    if (img) {
      img.style.transform = `scale(${activeViewerZoom}) rotate(${activeViewerRotation}deg)`;
      img.classList.toggle('doc-scan-bw-filter', activeViewerBwFilter);
    }
    if (pdfStage) {
      pdfStage.querySelectorAll('.doc-scan-pdf-page-img').forEach(pageImg => {
        pageImg.style.width = `${Math.round(760 * activeViewerZoom)}px`;
        pageImg.style.maxWidth = activeViewerZoom > 1 ? 'none' : '100%';
        pageImg.style.transform = activeViewerRotation ? `rotate(${activeViewerRotation}deg)` : '';
        pageImg.classList.toggle('doc-scan-bw-filter', activeViewerBwFilter);
      });
    }
  }

  async function openDocScanViewerModal(docId) {
    const doc = (state.documents || []).find(d => d.id === docId);
    if (!doc) return;

    if (activeViewerBlobUrl) {
      try { URL.revokeObjectURL(activeViewerBlobUrl); } catch (e) {}
      activeViewerBlobUrl = null;
    }

    activeViewerDocId = doc.id;
    activeViewerZoom = 1;
    activeViewerRotation = 0;
    activeViewerBwFilter = false;
    activeViewerAttachment = null;

    const modal = document.getElementById('docScanViewerModal');
    const titleEl = document.getElementById('docViewerTitle');
    const subEl = document.getElementById('docViewerSubtitle');
    const catBtnLabel = document.getElementById('docViewerCategoryBtnLabel');
    const stageEl = document.getElementById('docScanViewerStage');
    const catMeta = DOC_CATEGORY_META[doc.category] || DOC_CATEGORY_META.other;

    if (titleEl) titleEl.textContent = doc.title || 'Document';
    if (catBtnLabel) catBtnLabel.textContent = catMeta.label;
    if (subEl) {
      const statusLine = formatDocCardStatusLine(doc);
      subEl.textContent = statusLine ? `${catMeta.label} · ${statusLine}` : catMeta.label;
    }
    if (stageEl) {
      stageEl.innerHTML = `<div class="text-xs text-slate-400 font-medium">Loading…</div>`;
    }
    if (modal) {
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }
    applyDocViewerTransforms();

    const att = await getReceiptAttachment(`doc_vault_${doc.id}`);
    activeViewerAttachment = att;

    if (!stageEl) return;
    if (!att || !att.data) {
      stageEl.innerHTML = `<div class="text-xs text-rose-500 font-semibold">File not found on this device.</div>`;
      return;
    }

    const isPdf = att.type === 'pdf' || String(att.mimeType || '').includes('pdf') || String(att.data).startsWith('data:application/pdf');
    if (isPdf) {
      let renderedViaPdfJs = false;
      if (window.pdfjsLib) {
        try {
          const bytes = dataUrlToUint8Array(att.data);
          if (bytes) {
            const pdfDoc = await window.pdfjsLib.getDocument({
              data: bytes,
              cMapUrl: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/cmaps/',
              cMapPacked: true,
              standardFontDataUrl: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/standard_fonts/'
            }).promise;
            if (activeViewerDocId !== doc.id) return;

            stageEl.innerHTML = `
              <div id="docScanViewerPdfPages" class="w-full h-[74vh] overflow-auto flex flex-col items-center gap-4 py-2 px-3"></div>
            `;
            const pagesContainer = document.getElementById('docScanViewerPdfPages');
            renderedViaPdfJs = true;

            for (let pageNum = 1; pageNum <= pdfDoc.numPages; pageNum++) {
              if (activeViewerDocId !== doc.id || !pagesContainer) break;
              const page = await pdfDoc.getPage(pageNum);
              const viewport = page.getViewport({ scale: 2.0 });
              const canvas = document.createElement('canvas');
              canvas.width = viewport.width;
              canvas.height = viewport.height;
              const ctx = canvas.getContext('2d');
              ctx.fillStyle = '#ffffff';
              ctx.fillRect(0, 0, canvas.width, canvas.height);
              await page.render({ canvasContext: ctx, viewport }).promise;
              const pageDataUrl = canvas.toDataURL('image/png');
              if (pageNum === 1 && !docVaultThumbCache[doc.id]) {
                docVaultThumbCache[doc.id] = pageDataUrl;
                const gridThumb = document.querySelector(`img[data-doc-thumb-id="${doc.id}"]`);
                if (gridThumb) hydrateDocVaultThumbnail(doc.id, gridThumb);
              }
              const pageImg = document.createElement('img');
              pageImg.src = pageDataUrl;
              pageImg.alt = `${doc.title || 'Document'} — Page ${pageNum}`;
              pageImg.setAttribute('data-pin-nopin', 'true');
              pageImg.setAttribute('nopin', 'nopin');
              pageImg.className = 'doc-scan-pdf-page-img rounded-lg shadow-xl bg-white transition-all duration-150 shrink-0';
              pageImg.style.width = `${Math.round(760 * activeViewerZoom)}px`;
              pageImg.style.maxWidth = activeViewerZoom > 1 ? 'none' : '100%';
              pagesContainer.appendChild(pageImg);
              applyDocViewerTransforms();
            }
          }
        } catch (pdfErr) {
          console.warn('PDF.js viewer render fallback to Blob iframe:', pdfErr);
        }
      }

      if (!renderedViaPdfJs) {
        const rawPdfUrl = `/api/attachments/${encodeURIComponent('doc_vault_' + doc.id)}/raw`;
        activeViewerBlobUrl = dataUrlToBlobUrl(att.data, 'application/pdf');
        const iframeSrc = (activeViewerBlobUrl && activeViewerBlobUrl.startsWith('blob:')) ? activeViewerBlobUrl : rawPdfUrl;
        stageEl.innerHTML = `
          <iframe src="${iframeSrc}" class="w-full h-[72vh] rounded-xl border border-stone-200 bg-white shadow-md"></iframe>
        `;
      }
    } else {
      const rawImgFallbackUrl = `/api/attachments/${encodeURIComponent('doc_vault_' + doc.id)}/raw`;
      stageEl.innerHTML = `
        <div class="overflow-hidden max-w-full max-h-[72vh] flex items-center justify-center p-4">
          <img id="docScanViewerImg" data-pin-nopin="true" nopin="nopin" src="${att.data}" onerror="if(this.src!==location.origin+'${rawImgFallbackUrl}')this.src='${rawImgFallbackUrl}';" alt="${escapeHtml(doc.title)}" class="max-w-full max-h-[68vh] object-contain rounded-lg shadow-md transition-transform duration-150 bg-white">
        </div>
      `;
      applyDocViewerTransforms();
    }
    if (window.lucide) window.lucide.createIcons();
  }

  function closeDocScanViewerModal() {
    const modal = document.getElementById('docScanViewerModal');
    if (modal) {
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }
    if (activeViewerBlobUrl) {
      try { URL.revokeObjectURL(activeViewerBlobUrl); } catch (e) {}
      activeViewerBlobUrl = null;
    }
    activeViewerDocId = null;
    activeViewerAttachment = null;
  }

  async function downloadVaultDocument(docId) {
    const doc = (state.documents || []).find(d => d.id === docId);
    if (!doc) return;
    const att = (activeViewerDocId === docId && activeViewerAttachment)
      ? activeViewerAttachment
      : await getReceiptAttachment(`doc_vault_${doc.id}`);

    const inferExt = () => {
      if (doc.fileName && /\.[a-z0-9]{2,5}$/i.test(doc.fileName)) {
        return doc.fileName.match(/(\.[a-z0-9]{2,5})$/i)[1];
      }
      const mime = String((att && att.mimeType) || doc.mimeType || '').toLowerCase();
      if (mime.includes('pdf') || doc.fileType === 'pdf') return '.pdf';
      if (mime.includes('png')) return '.png';
      if (mime.includes('webp')) return '.webp';
      return '.jpg';
    };
    const ext = inferExt();
    let dlFileName = (doc.title || 'document').trim();
    if (!/\.[a-z0-9]{2,5}$/i.test(dlFileName)) {
      dlFileName += ext;
    }

    if (!att || !att.data) {
      // Fallback to direct raw streaming endpoint on server
      const a = document.createElement('a');
      a.href = `/api/attachments/${encodeURIComponent('doc_vault_' + doc.id)}/raw?download=1`;
      a.download = dlFileName;
      document.body.appendChild(a);
      a.click();
      a.remove();
      return;
    }
    const dlUrl = dataUrlToBlobUrl(att.data, att.mimeType || (doc.fileType === 'pdf' ? 'application/pdf' : 'image/jpeg'));
    const a = document.createElement('a');
    a.href = dlUrl;
    a.download = dlFileName;
    document.body.appendChild(a);
    a.click();
    a.remove();
    if (dlUrl && dlUrl.startsWith('blob:')) {
      setTimeout(() => {
        try { URL.revokeObjectURL(dlUrl); } catch (e) {}
      }, 5000);
    }
  }

  async function printScanAsA4Pdf() {
    const doc = (state.documents || []).find(d => d.id === activeViewerDocId);
    if (!doc || !activeViewerAttachment || !activeViewerAttachment.data) return;

    const isPdf = activeViewerAttachment.type === 'pdf' || String(activeViewerAttachment.mimeType || '').includes('pdf');
    if (isPdf) {
      downloadVaultDocument(doc.id);
      return;
    }

    const filterCss = activeViewerBwFilter ? 'grayscale(1) contrast(1.65) brightness(1.06)' : 'none';
    const rot = activeViewerRotation || 0;
    const w = window.open('', '_blank', 'width=900,height=1100');
    if (!w) {
      showToast('Popup Blocked', 'Allow popups to export PDF.', 'error');
      return;
    }
    w.document.write(`<!DOCTYPE html>
      <html>
      <head>
        <title>${escapeHtml(doc.title || 'Document')}</title>
        <style>
          @page { size: A4 portrait; margin: 12mm; }
          html, body { margin: 0; padding: 0; background: #fff; font-family: -apple-system, BlinkMacSystemFont, sans-serif; }
          .page { width: 100%; height: 94vh; display: flex; flex-direction: column; align-items: center; justify-content: center; box-sizing: border-box; }
          img { max-width: 100%; max-height: 88vh; object-fit: contain; filter: ${filterCss}; transform: rotate(${rot}deg); }
          .meta { margin-top: 10px; font-size: 9pt; color: #64748b; text-align: center; }
        </style>
      </head>
      <body>
        <div class="page">
          <img src="${activeViewerAttachment.data}" onload="setTimeout(function(){ window.print(); }, 180);" />
          <div class="meta">${escapeHtml(doc.title)}${doc.expiryDate ? ' • ' + escapeHtml(doc.expiryDate) : ''}</div>
        </div>
      </body>
      </html>`);
    w.document.close();
  }

  function setupDocumentsListeners() {
    const viewDocs = document.getElementById('viewDocuments');
    if (!viewDocs) return;
    if (viewDocs.dataset.docListenersBound === '1') return;
    viewDocs.dataset.docListenersBound = '1';

    let selectedStudioPreset = 'pitch';
    const syncStudioPresetCardsUI = () => {
      document.querySelectorAll('#docNewStudioModal .doc-preset-card').forEach(btn => {
        const p = btn.getAttribute('data-studio-preset');
        if (p === selectedStudioPreset) {
          btn.className = 'doc-preset-card text-left px-3 py-2.5 rounded-xl border-2 border-indigo-600 bg-indigo-50/40 ring-2 ring-indigo-500/20 cursor-pointer transition-all flex items-center justify-between';
        } else {
          btn.className = 'doc-preset-card text-left px-3 py-2.5 rounded-xl border-2 border-slate-200 hover:border-slate-300 bg-white cursor-pointer transition-all flex items-center justify-between';
        }
      });
    };

    const openNewStudioModal = () => {
      populateDocCategorySelects();
      const activeCat = (state.documentsFilter && state.documentsFilter !== 'all' && DOC_CATEGORY_META[state.documentsFilter])
        ? state.documentsFilter
        : 'pitch';
      selectedStudioPreset = activeCat === 'cv' ? 'cv' : 'pitch';
      selectedNewStudioIcon = '';
      syncStudioPresetCardsUI();
      const catSel = document.getElementById('docNewStudioCategorySelect');
      if (catSel) catSel.value = activeCat;
      syncDocModalCategoryPreviews();
      const titleInp = document.getElementById('docNewStudioTitleInput');
      if (titleInp) titleInp.value = '';
      const modal = document.getElementById('docNewStudioModal');
      if (modal) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
      }
      if (window.lucide) window.lucide.createIcons();
    };

    const closeNewStudioModal = () => {
      const modal = document.getElementById('docNewStudioModal');
      if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
      }
      selectedNewStudioIcon = '';
    };

    document.getElementById('docNewStudioDocBtn')?.addEventListener('click', openNewStudioModal);
    document.getElementById('docCloseNewStudioModalBtn')?.addEventListener('click', closeNewStudioModal);
    document.getElementById('docCancelNewStudioBtn')?.addEventListener('click', closeNewStudioModal);

    document.getElementById('docNewStudioCategorySelect')?.addEventListener('change', (e) => {
      if (e.target.value === '__new_category__') {
        syncDocModalCategoryPreviews();
        openDocCategoryModal(null, (newCatId) => {
          populateDocCategorySelects(newCatId);
          e.target.value = newCatId;
          syncDocModalCategoryPreviews();
        });
        return;
      }
      syncDocModalCategoryPreviews();
    });

    document.getElementById('docUploadCategorySelect')?.addEventListener('change', (e) => {
      if (e.target.value === '__new_category__') {
        syncDocModalCategoryPreviews();
        openDocCategoryModal(null, (newCatId) => {
          populateDocCategorySelects(newCatId);
          e.target.value = newCatId;
          syncDocModalCategoryPreviews();
        });
        return;
      }
      syncDocModalCategoryPreviews();
    });

    document.querySelectorAll('#docNewStudioModal .doc-preset-card').forEach(btn => {
      btn.addEventListener('click', () => {
        selectedStudioPreset = btn.getAttribute('data-studio-preset') || 'pitch';
        syncStudioPresetCardsUI();
        const catSel = document.getElementById('docNewStudioCategorySelect');
        if (catSel && (!state.documentsFilter || state.documentsFilter === 'all')) {
          catSel.value = selectedStudioPreset === 'cv' ? 'cv' : 'pitch';
          syncDocModalCategoryPreviews();
        }
      });
    });

    document.getElementById('docConfirmNewStudioBtn')?.addEventListener('click', () => {
      const customTitle = document.getElementById('docNewStudioTitleInput')?.value.trim() || '';
      const customCat = document.getElementById('docNewStudioCategorySelect')?.value || '';
      const newDoc = buildNewStudioDocumentFromPreset(selectedStudioPreset, customTitle, '', customCat, '');
      state.documents.unshift(newDoc);
      saveDocuments(newDoc.id);
      closeNewStudioModal();
      renderDocumentsView();
      openStudioDocumentEditor(newDoc.id);
    });

    // Add / Customize Category Modal Listeners
    document.getElementById('docAddCategoryBtn')?.addEventListener('click', () => {
      openDocCategoryModal(null, (newCatId) => {
        state.documentsFilter = newCatId;
        renderDocumentsView();
      });
    });
    const openUploadCustomizeCat = () => {
      const catSel = document.getElementById('docUploadCategorySelect');
      const curCat = (catSel && DOC_CATEGORY_META[catSel.value]) ? catSel.value : 'other';
      openDocCategoryModal(curCat, (savedCatId) => {
        populateDocCategorySelects(savedCatId);
        if (catSel) catSel.value = savedCatId;
        syncDocModalCategoryPreviews();
      });
    };
    document.getElementById('docUploadEditCatBtn')?.addEventListener('click', openUploadCustomizeCat);
    document.getElementById('docUploadCatPreviewBtn')?.addEventListener('click', openUploadCustomizeCat);
    document.getElementById('docUploadAddCatBtn')?.addEventListener('click', () => {
      openDocCategoryModal(null, (newCatId) => {
        populateDocCategorySelects(newCatId);
        const catSel = document.getElementById('docUploadCategorySelect');
        if (catSel) catSel.value = newCatId;
        syncDocModalCategoryPreviews();
      });
    });

    const openNewStudioCustomizeCat = () => {
      const catSel = document.getElementById('docNewStudioCategorySelect');
      const curCat = (catSel && DOC_CATEGORY_META[catSel.value]) ? catSel.value : 'pitch';
      openDocCategoryModal(curCat, (savedCatId) => {
        populateDocCategorySelects(savedCatId);
        if (catSel) catSel.value = savedCatId;
        syncDocModalCategoryPreviews();
      });
    };
    document.getElementById('docNewStudioEditCatBtn')?.addEventListener('click', openNewStudioCustomizeCat);
    document.getElementById('docNewStudioCatPreviewBtn')?.addEventListener('click', openNewStudioCustomizeCat);
    document.getElementById('docNewStudioAddCatBtn')?.addEventListener('click', () => {
      openDocCategoryModal(null, (newCatId) => {
        populateDocCategorySelects(newCatId);
        const catSel = document.getElementById('docNewStudioCategorySelect');
        if (catSel) catSel.value = newCatId;
        syncDocModalCategoryPreviews();
      });
    });
    document.getElementById('docBackCategoryModalBtn')?.addEventListener('click', requestCloseDocCategoryModal);
    document.getElementById('docCloseCategoryModalBtn')?.addEventListener('click', requestCloseDocCategoryModal);
    document.getElementById('docCancelCategoryModalBtn')?.addEventListener('click', requestCloseDocCategoryModal);
    document.getElementById('docConfirmCategoryModalBtn')?.addEventListener('click', saveDocCategoryFromModal);
    document.getElementById('docDeleteCategoryModalBtn')?.addEventListener('click', deleteDocCategoryFromModal);
    document.getElementById('docCategoryModal')?.addEventListener('click', (e) => {
      if (e.target && e.target.id === 'docCategoryModal') {
        requestCloseDocCategoryModal();
      }
    });
    document.getElementById('docCategoryNameInput')?.addEventListener('keydown', (ke) => {
      if (ke.key === 'Enter') {
        ke.preventDefault();
        saveDocCategoryFromModal();
      }
    });

    // Duplicate & Reset buttons inside the Studio Editor right sidebar
    document.getElementById('poStudioResetDefaultBtn')?.addEventListener('click', () => {
      document.getElementById('poResetLayoutBtn')?.click();
    });
    document.getElementById('poDuplicateStudioDocBtn')?.addEventListener('click', () => {
      if (!state.activeStudioDocId) return;
      savePriceOfferingDoc(false);
      const orig = (state.documents || []).find(d => d.id === state.activeStudioDocId);
      if (!orig) return;
      const nowIso = new Date().toISOString();
      const copy = JSON.parse(JSON.stringify(orig));
      copy.id = 'doc_studio_' + Date.now();
      copy.title = `${orig.title} (Copy)`;
      copy.createdAt = nowIso;
      copy.updatedAt = nowIso;
      copy.isEdited = false;
      state.documents.unshift(copy);
      saveDocuments(copy.id);
      openStudioDocumentEditor(copy.id);
      showToast('Duplicated ✓', `"${copy.title}"`, 'success');
    });

    // Search input
    const searchInp = document.getElementById('docSearchInput');
    if (searchInp) {
      searchInp.addEventListener('input', () => {
        state.documentsSearch = searchInp.value;
        renderDocumentsView();
      });
    }

    // Upload Scan / File triggers & whole-page / card drag-and-drop
    const fileInput = document.getElementById('docFileInput');
    document.getElementById('docUploadFileBtn')?.addEventListener('click', () => fileInput?.click());
    let draggedDocCardId = null;

    // Category filter bar (click to filter + drag-and-drop document card or files onto a category pill!)
    const filterBar = document.getElementById('docCategoryFilterBar');
    if (filterBar) {
      filterBar.addEventListener('click', (e) => {
        const editBtn = e.target.closest('[data-edit-doc-cat]');
        if (editBtn) {
          e.preventDefault();
          e.stopPropagation();
          const catId = editBtn.getAttribute('data-edit-doc-cat');
          if (catId) openDocCategoryModal(catId);
          return;
        }
        const pill = e.target.closest('.doc-filter-pill');
        if (!pill) return;
        closeDocCategoryPopover();
        state.documentsFilter = pill.getAttribute('data-doc-filter') || 'all';
        renderDocumentsView();
      });

      filterBar.addEventListener('dragover', (e) => {
        const pill = e.target.closest('.doc-filter-pill');
        filterBar.querySelectorAll('.doc-filter-pill.doc-pill-drop-target').forEach(el => {
          if (el !== pill) el.classList.remove('doc-pill-drop-target');
        });
        if (!pill) return;
        const targetFilter = pill.getAttribute('data-doc-filter') || 'all';
        const hasExternalFiles = !draggedDocCardId && e.dataTransfer && Array.from(e.dataTransfer.types || []).includes('Files');
        if (!draggedDocCardId && !hasExternalFiles) return;
        e.preventDefault();
        e.stopPropagation();
        if (e.dataTransfer) e.dataTransfer.dropEffect = draggedDocCardId ? 'move' : 'copy';
        if (targetFilter !== 'all' || draggedDocCardId) {
          pill.classList.add('doc-pill-drop-target');
        }
      });

      filterBar.addEventListener('dragleave', (e) => {
        const pill = e.target.closest('.doc-filter-pill');
        if (pill && !pill.contains(e.relatedTarget)) {
          pill.classList.remove('doc-pill-drop-target');
        }
        if (!filterBar.contains(e.relatedTarget)) {
          filterBar.querySelectorAll('.doc-filter-pill.doc-pill-drop-target').forEach(el => el.classList.remove('doc-pill-drop-target'));
        }
      });

      filterBar.addEventListener('drop', (e) => {
        const pill = e.target.closest('.doc-filter-pill');
        filterBar.querySelectorAll('.doc-filter-pill.doc-pill-drop-target').forEach(el => el.classList.remove('doc-pill-drop-target'));
        filterBar.classList.remove('doc-dragging-active');
        if (!pill) return;
        const targetFilter = pill.getAttribute('data-doc-filter') || 'all';

        // Case 1: Dragging an existing document card onto a top-bar category pill
        if (draggedDocCardId) {
          e.preventDefault();
          e.stopPropagation();
          const id = draggedDocCardId;
          draggedDocCardId = null;
          const doc = (state.documents || []).find(d => d.id === id);
          if (!doc) return;
          if (targetFilter === 'all') {
            if (doc.isDraft) {
              doc.isDraft = false;
              doc.updatedAt = new Date().toISOString();
              saveDocuments(doc.id);
              state.documentsFilter = 'all';
              renderDocumentsView();
              showToast('Finalized ✓', `"${doc.title}" moved to All Documents`, 'success');
            } else {
              state.documentsFilter = 'all';
              renderDocumentsView();
            }
            return;
          }
          if (DOC_CATEGORY_META[targetFilter]) {
            updateDocumentCategoryAndResort(id, targetFilter, { unmarkDraft: Boolean(doc.isDraft) });
          }
          return;
        }

        // Case 2: Dragging external files from Finder directly onto a category pill
        if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
          e.preventDefault();
          e.stopPropagation();
          document.getElementById('docVaultDropzone')?.classList.remove('drag-over');
          const forcedCat = (targetFilter !== 'all' && DOC_CATEGORY_META[targetFilter]) ? targetFilter : null;
          if (forcedCat) {
            state.documentsFilter = forcedCat;
            renderDocumentsView();
          }
          openVaultUploadModalWithFiles(e.dataTransfer.files, forcedCat, false);
        }
      });
    }

    viewDocs.addEventListener('dragstart', (e) => {
      if (e.target.closest('.doc-inline-rename-input')) {
        e.preventDefault();
        return;
      }
      const card = e.target.closest('[data-doc-card-id]');
      if (!card) return;
      closeDocCategoryPopover();
      draggedDocCardId = card.getAttribute('data-doc-card-id');
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = 'move';
        try { e.dataTransfer.setData('text/plain', draggedDocCardId || ''); } catch (err) {}
      }
      document.getElementById('docCategoryFilterBar')?.classList.add('doc-dragging-active');
      setTimeout(() => card.classList.add('opacity-50'), 0);
    });

    viewDocs.addEventListener('dragend', (e) => {
      const card = e.target.closest('[data-doc-card-id]');
      if (card) card.classList.remove('opacity-50');
      draggedDocCardId = null;
      const bar = document.getElementById('docCategoryFilterBar');
      if (bar) {
        bar.classList.remove('doc-dragging-active');
        bar.querySelectorAll('.doc-filter-pill.doc-pill-drop-target').forEach(el => el.classList.remove('doc-pill-drop-target'));
      }
      viewDocs.querySelectorAll('[data-doc-card-id].doc-card-drop-target').forEach(el => el.classList.remove('doc-card-drop-target'));
      document.getElementById('documentsDraftsSection')?.classList.remove('ring-2', 'ring-amber-300', 'bg-amber-50/30');
      document.getElementById('documentsGridContainer')?.classList.remove('ring-2', 'ring-indigo-300', 'rounded-2xl');
    });

    // Card-to-card drag reordering & automatic section matching
    viewDocs.addEventListener('dragover', (e) => {
      if (!draggedDocCardId) return;
      const overCard = e.target.closest('[data-doc-card-id]');
      viewDocs.querySelectorAll('[data-doc-card-id].doc-card-drop-target').forEach(el => {
        if (el !== overCard) el.classList.remove('doc-card-drop-target');
      });
      if (overCard && overCard.getAttribute('data-doc-card-id') !== draggedDocCardId) {
        e.preventDefault();
        if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
        overCard.classList.add('doc-card-drop-target');
      }
    });

    viewDocs.addEventListener('drop', (e) => {
      if (!draggedDocCardId) return;
      const overCard = e.target.closest('[data-doc-card-id]');
      viewDocs.querySelectorAll('[data-doc-card-id].doc-card-drop-target').forEach(el => el.classList.remove('doc-card-drop-target'));
      if (!overCard) return;
      const targetId = overCard.getAttribute('data-doc-card-id');
      if (!targetId || targetId === draggedDocCardId) return;
      e.preventDefault();
      e.stopPropagation();
      const draggedId = draggedDocCardId;
      draggedDocCardId = null;
      document.getElementById('docCategoryFilterBar')?.classList.remove('doc-dragging-active');
      document.getElementById('documentsDraftsSection')?.classList.remove('ring-2', 'ring-amber-300', 'bg-amber-50/30');
      document.getElementById('documentsGridContainer')?.classList.remove('ring-2', 'ring-indigo-300', 'rounded-2xl');

      const docs = state.documents || [];
      const draggedDoc = docs.find(d => d.id === draggedId);
      const targetDoc = docs.find(d => d.id === targetId);
      if (!draggedDoc || !targetDoc) return;

      const nowIso = new Date().toISOString();
      const movedBetweenDrafts = Boolean(draggedDoc.isDraft) !== Boolean(targetDoc.isDraft);
      draggedDoc.isDraft = Boolean(targetDoc.isDraft);
      // Match pinned status so sortDocumentsList respects the dropped visual position
      draggedDoc.pinned = Boolean(targetDoc.pinned);
      // Only change category if moving across sections while filtered by a specific category
      if (movedBetweenDrafts && state.documentsFilter && state.documentsFilter !== 'all' && DOC_CATEGORY_META[state.documentsFilter]) {
        draggedDoc.category = state.documentsFilter;
      }

      // Compute clean sortOrder sequence for the section (handling both forward and backward drags)
      const peerList = sortDocumentsList(docs.filter(d => Boolean(d.isDraft) === Boolean(targetDoc.isDraft)));
      const fromIdx = peerList.findIndex(d => d.id === draggedId);
      const toIdx = peerList.findIndex(d => d.id === targetId);
      if (fromIdx >= 0 && toIdx >= 0 && fromIdx !== toIdx) {
        peerList.splice(fromIdx, 1);
        peerList.splice(toIdx, 0, draggedDoc);
      } else {
        const filtered = peerList.filter(d => d.id !== draggedId);
        const targetIndex = filtered.findIndex(d => d.id === targetId);
        filtered.splice(targetIndex >= 0 ? targetIndex : filtered.length, 0, draggedDoc);
        peerList.length = 0;
        peerList.push(...filtered);
      }
      peerList.forEach((d, idx) => {
        d.sortOrder = (idx + 1) * 10;
        d._orderUpdatedAt = nowIso;
      });
      if (movedBetweenDrafts) {
        draggedDoc.updatedAt = nowIso;
      }
      saveDocuments();
      renderDocumentsView();
      if (movedBetweenDrafts) {
        showToast(draggedDoc.isDraft ? 'Moved to Drafts' : 'Finalized ✓', `"${draggedDoc.title}"`, 'success');
      }
    });

    const draftsSection = document.getElementById('documentsDraftsSection');
    if (draftsSection) {
      draftsSection.addEventListener('dragover', (e) => {
        const hasExternalFiles = !draggedDocCardId && e.dataTransfer && Array.from(e.dataTransfer.types || []).includes('Files');
        if (!draggedDocCardId && !hasExternalFiles) return;
        const overCard = draggedDocCardId ? e.target.closest('[data-doc-card-id]') : null;
        if (overCard && overCard.getAttribute('data-doc-card-id') !== draggedDocCardId) {
          // Let card-to-card dragover on viewDocs highlight the individual card
          draftsSection.classList.remove('ring-2', 'ring-amber-300', 'bg-amber-50/30');
          return;
        }
        e.preventDefault();
        e.stopPropagation();
        if (e.dataTransfer) e.dataTransfer.dropEffect = draggedDocCardId ? 'move' : 'copy';
        draftsSection.classList.add('ring-2', 'ring-amber-300', 'bg-amber-50/30');
      });
      draftsSection.addEventListener('dragleave', (e) => {
        if (!draftsSection.contains(e.relatedTarget)) {
          draftsSection.classList.remove('ring-2', 'ring-amber-300', 'bg-amber-50/30');
        }
      });
      draftsSection.addEventListener('drop', (e) => {
        draftsSection.classList.remove('ring-2', 'ring-amber-300', 'bg-amber-50/30');
        if (draggedDocCardId) {
          const overCard = e.target.closest('[data-doc-card-id]');
          if (overCard && overCard.getAttribute('data-doc-card-id') !== draggedDocCardId) {
            // Let card-to-card drop on viewDocs handle exact ordering
            return;
          }
          e.preventDefault();
          e.stopPropagation();
          const id = draggedDocCardId;
          draggedDocCardId = null;
          const doc = (state.documents || []).find(d => d.id === id);
          if (doc && !doc.isDraft) {
            doc.isDraft = true;
            doc.updatedAt = new Date().toISOString();
            state.documentsDraftsCollapsed = false;
            saveDocuments(doc.id);
            renderDocumentsView();
            showToast('Moved to Drafts', `"${doc.title}"`, 'info');
          }
          return;
        }
        if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
          e.preventDefault();
          e.stopPropagation();
          document.getElementById('docVaultDropzone')?.classList.remove('drag-over');
          openVaultUploadModalWithFiles(e.dataTransfer.files, null, true);
        }
      });
    }

    const mainDocsGrid = document.getElementById('documentsGridContainer');
    if (mainDocsGrid) {
      mainDocsGrid.addEventListener('dragover', (e) => {
        if (!draggedDocCardId) return;
        const overCard = e.target.closest('[data-doc-card-id]');
        if (overCard && overCard.getAttribute('data-doc-card-id') !== draggedDocCardId) {
          // Let card-to-card dragover on viewDocs highlight the individual card
          mainDocsGrid.classList.remove('ring-2', 'ring-indigo-300', 'rounded-2xl');
          return;
        }
        e.preventDefault();
        e.stopPropagation();
        if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
        mainDocsGrid.classList.add('ring-2', 'ring-indigo-300', 'rounded-2xl');
      });
      mainDocsGrid.addEventListener('dragleave', (e) => {
        if (!mainDocsGrid.contains(e.relatedTarget)) {
          mainDocsGrid.classList.remove('ring-2', 'ring-indigo-300', 'rounded-2xl');
        }
      });
      mainDocsGrid.addEventListener('drop', (e) => {
        if (!draggedDocCardId) return;
        const overCard = e.target.closest('[data-doc-card-id]');
        if (overCard && overCard.getAttribute('data-doc-card-id') !== draggedDocCardId) {
          // Let card-to-card drop on viewDocs handle exact ordering
          mainDocsGrid.classList.remove('ring-2', 'ring-indigo-300', 'rounded-2xl');
          return;
        }
        e.preventDefault();
        e.stopPropagation();
        mainDocsGrid.classList.remove('ring-2', 'ring-indigo-300', 'rounded-2xl');
        const id = draggedDocCardId;
        draggedDocCardId = null;
        const doc = (state.documents || []).find(d => d.id === id);
        if (!doc) return;
        if (doc.isDraft) {
          doc.isDraft = false;
          if (state.documentsFilter && state.documentsFilter !== 'all' && DOC_CATEGORY_META[state.documentsFilter]) {
            doc.category = state.documentsFilter;
          }
          doc.updatedAt = new Date().toISOString();
          saveDocuments(doc.id);
          renderDocumentsView();
          showToast('Finalized ✓', `"${doc.title}" moved to Documents`, 'success');
        } else {
          // Dropped on empty grid space or the Add Document card at the end -> move to end of active list
          const nowIso = new Date().toISOString();
          const activePeers = sortDocumentsList((state.documents || []).filter(d => !d.isDraft && d.id !== doc.id));
          if (activePeers.length > 0) {
            doc.pinned = Boolean(activePeers[activePeers.length - 1].pinned);
          }
          activePeers.push(doc);
          activePeers.forEach((d, idx) => {
            d.sortOrder = (idx + 1) * 10;
            d._orderUpdatedAt = nowIso;
          });
          saveDocuments();
          renderDocumentsView();
        }
      });
    }

    document.getElementById('toggleDocumentsDraftsBtn')?.addEventListener('click', () => {
      state.documentsDraftsCollapsed = !state.documentsDraftsCollapsed;
      renderDocumentsView();
    });

    viewDocs.addEventListener('dragover', (e) => {
      if (draggedDocCardId) return;
      e.preventDefault();
      document.getElementById('docVaultDropzone')?.classList.add('drag-over');
    });
    viewDocs.addEventListener('dragleave', (e) => {
      if (draggedDocCardId) return;
      if (!viewDocs.contains(e.relatedTarget)) {
        document.getElementById('docVaultDropzone')?.classList.remove('drag-over');
      }
    });
    viewDocs.addEventListener('drop', (e) => {
      if (draggedDocCardId) return;
      e.preventDefault();
      document.getElementById('docVaultDropzone')?.classList.remove('drag-over');
      if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
        openVaultUploadModalWithFiles(e.dataTransfer.files);
      }
    });
    if (fileInput) {
      fileInput.addEventListener('change', () => {
        if (fileInput.files && fileInput.files.length > 0) {
          openVaultUploadModalWithFiles(fileInput.files);
        }
      });
    }

    document.getElementById('docCloseUploadModalBtn')?.addEventListener('click', requestCloseVaultUploadModal);
    document.getElementById('docCancelUploadModalBtn')?.addEventListener('click', requestCloseVaultUploadModal);
    document.getElementById('docConfirmUploadModalBtn')?.addEventListener('click', savePendingVaultUploadFiles);
    document.getElementById('docVaultUploadModal')?.addEventListener('click', (e) => {
      if (e.target && e.target.id === 'docVaultUploadModal') {
        requestCloseVaultUploadModal();
      }
    });
    ['docUploadTitleInput', 'docUploadExpiryInput'].forEach(inpId => {
      document.getElementById(inpId)?.addEventListener('keydown', (ke) => {
        if (ke.key === 'Enter') {
          ke.preventDefault();
          savePendingVaultUploadFiles();
        }
      });
    });

    // Close category popover on outside click or Escape, and handle Escape with unsaved-changes check on Document modals
    document.addEventListener('click', (e) => {
      const pop = document.getElementById('docCategoryPickerPopover');
      if (!pop || pop.classList.contains('hidden')) return;
      if (pop.contains(e.target) || e.target.closest('.doc-change-category-btn') || e.target.closest('#docViewerCategoryBtn')) return;
      closeDocCategoryPopover();
    });
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      const cancelConfirmModal = document.getElementById('settingsCancelConfirmModal');
      if (cancelConfirmModal && !cancelConfirmModal.classList.contains('hidden')) return;
      const globalConfirmModal = document.getElementById('globalConfirmModal');
      if (globalConfirmModal && !globalConfirmModal.classList.contains('hidden')) return;

      const catModal = document.getElementById('docCategoryModal');
      if (catModal && !catModal.classList.contains('hidden')) {
        e.preventDefault();
        e.stopPropagation();
        requestCloseDocCategoryModal();
        return;
      }
      const uploadModal = document.getElementById('docVaultUploadModal');
      if (uploadModal && !uploadModal.classList.contains('hidden')) {
        e.preventDefault();
        e.stopPropagation();
        requestCloseVaultUploadModal();
        return;
      }
      closeDocCategoryPopover();
    });

    // Delegated actions on #viewDocuments
    viewDocs.addEventListener('click', async (e) => {
      if (e.target.closest('.doc-inline-rename-input')) {
        e.stopPropagation();
        return;
      }
      if (e.target.closest('.doc-trigger-new-pdf-btn')) {
        e.stopPropagation();
        openNewStudioModal();
        return;
      }
      if (e.target.closest('.doc-trigger-upload-btn') || e.target.closest('#docVaultDropzone')) {
        e.stopPropagation();
        fileInput?.click();
        return;
      }

      const changeCatBtn = e.target.closest('.doc-change-category-btn');
      if (changeCatBtn) {
        e.preventDefault();
        e.stopPropagation();
        const id = changeCatBtn.getAttribute('data-doc-id');
        if (id) openDocCategoryPopover(id, changeCatBtn);
        return;
      }

      const editDetailsBtn = e.target.closest('.doc-edit-details-btn') || e.target.closest('.doc-card-subtitle');
      if (editDetailsBtn) {
        e.preventDefault();
        e.stopPropagation();
        const id = editDetailsBtn.getAttribute('data-doc-id');
        if (id) openVaultEditModal(id);
        return;
      }

      const renameBtn = e.target.closest('.doc-rename-btn');
      if (renameBtn) {
        e.preventDefault();
        e.stopPropagation();
        const id = renameBtn.getAttribute('data-doc-id');
        const doc = (state.documents || []).find(d => d.id === id);
        if (!doc) return;
        const card = renameBtn.closest('.group') || renameBtn.parentElement;
        const titleEl = card?.querySelector('.doc-card-title');
        if (!titleEl) return;

        const inp = document.createElement('input');
        inp.type = 'text';
        inp.value = doc.title || '';
        inp.className = 'doc-inline-rename-input w-full px-2 py-0.5 text-sm font-semibold text-slate-900 bg-white border border-indigo-400 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500/20';
        inp.addEventListener('click', (ie) => ie.stopPropagation());
        titleEl.replaceWith(inp);
        renameBtn.classList.add('hidden');
        inp.focus();
        inp.select();

        let committed = false;
        const commit = (save) => {
          if (committed) return;
          committed = true;
          if (save) {
            const nextVal = inp.value.trim();
            if (nextVal && nextVal !== doc.title) {
              doc.title = nextVal;
              doc.isEdited = true;
              doc.updatedAt = new Date().toISOString();
              saveDocuments(doc.id);
            }
          }
          inp.remove();
          renderDocumentsView();
        };
        inp.addEventListener('keydown', (ke) => {
          if (ke.key === 'Enter') {
            ke.preventDefault();
            commit(true);
          } else if (ke.key === 'Escape') {
            ke.preventDefault();
            commit(false);
          }
        });
        setTimeout(() => {
          inp.addEventListener('blur', () => commit(true));
        }, 60);
        return;
      }

      const draftBtn = e.target.closest('.doc-toggle-draft-btn');
      if (draftBtn) {
        e.preventDefault();
        e.stopPropagation();
        const id = draftBtn.getAttribute('data-doc-id');
        const doc = (state.documents || []).find(d => d.id === id);
        if (doc) {
          doc.isDraft = !doc.isDraft;
          doc.updatedAt = new Date().toISOString();
          if (doc.isDraft) state.documentsDraftsCollapsed = false;
          saveDocuments(doc.id);
          renderDocumentsView();
          if (doc.isDraft) {
            showToast('Moved to Drafts', `"${doc.title}"`, 'info');
          } else {
            showToast('Finalized ✓', `"${doc.title}" moved to Documents`, 'success');
          }
        }
        return;
      }

      const pinBtn = e.target.closest('.doc-toggle-pin-btn');
      if (pinBtn) {
        e.preventDefault();
        e.stopPropagation();
        const id = pinBtn.getAttribute('data-doc-id');
        const doc = (state.documents || []).find(d => d.id === id);
        if (doc) {
          doc.pinned = !doc.pinned;
          doc.updatedAt = new Date().toISOString();
          saveDocuments(doc.id);
          renderDocumentsView();
        }
        return;
      }

      const dupBtn = e.target.closest('.doc-duplicate-studio-btn');
      if (dupBtn) {
        e.preventDefault();
        e.stopPropagation();
        const id = dupBtn.getAttribute('data-doc-id');
        const orig = (state.documents || []).find(d => d.id === id);
        if (orig) {
          const nowIso = new Date().toISOString();
          const copy = JSON.parse(JSON.stringify(orig));
          copy.id = 'doc_studio_' + Date.now();
          copy.title = `${orig.title} (Copy)`;
          copy.createdAt = nowIso;
          copy.updatedAt = nowIso;
          copy.isEdited = false;
          state.documents.unshift(copy);
          saveDocuments(copy.id);
          renderDocumentsView();
        }
        return;
      }

      const delBtn = e.target.closest('.doc-delete-btn');
      if (delBtn) {
        e.preventDefault();
        e.stopPropagation();
        const id = delBtn.getAttribute('data-doc-id');
        const doc = (state.documents || []).find(d => d.id === id);
        if (!doc) return;
        const confirmed = await confirmAction({
          title: `Delete "${doc.title}"?`,
          message: `Remove "${doc.title}" from Documents?`,
          confirmText: 'Delete',
          danger: true
        });
        if (!confirmed) return;

        markDocIdDeleted(id);
        state.documents = (state.documents || []).filter(d => d.id !== id);
        if (doc.kind !== 'studio_pdf') {
          delete docVaultThumbCache[id];
          deleteLocalCachedDocThumb(id);
          deleteSubReceiptAttachment(`doc_vault_${id}`);
        }
        saveDocuments(id);
        renderDocumentsView();
        return;
      }

      const quickPdfBtn = e.target.closest('.doc-quick-export-pdf-btn');
      if (quickPdfBtn) {
        e.preventDefault();
        e.stopPropagation();
        const id = quickPdfBtn.getAttribute('data-doc-id');
        if (id) exportStudioDocumentPdfQuick(id);
        return;
      }

      const dlBtn = e.target.closest('.doc-download-vault-btn');
      if (dlBtn) {
        e.preventDefault();
        e.stopPropagation();
        const id = dlBtn.getAttribute('data-doc-id');
        if (id) downloadVaultDocument(id);
        return;
      }

      const cardTitleEl = e.target.closest('.doc-card-title');
      if (cardTitleEl) {
        const id = cardTitleEl.getAttribute('data-doc-id');
        const doc = (state.documents || []).find(d => d.id === id);
        if (doc) {
          if (doc.kind === 'studio_pdf') openStudioDocumentEditor(doc.id);
          else openDocScanViewerModal(doc.id);
        }
        return;
      }

      const openStudioBtn = e.target.closest('.doc-open-studio-btn');
      if (openStudioBtn) {
        const id = openStudioBtn.getAttribute('data-doc-id');
        if (id) openStudioDocumentEditor(id);
        return;
      }

      const openViewerBtn = e.target.closest('.doc-open-viewer-btn');
      if (openViewerBtn) {
        const id = openViewerBtn.getAttribute('data-doc-id');
        if (id) openDocScanViewerModal(id);
        return;
      }
    });

    // Scan Viewer Modal Controls
    document.getElementById('docViewerCloseBtn')?.addEventListener('click', closeDocScanViewerModal);
    document.getElementById('docViewerCategoryBtn')?.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (activeViewerDocId) {
        openDocCategoryPopover(activeViewerDocId, e.currentTarget);
      }
    });
    document.getElementById('docViewerZoomInBtn')?.addEventListener('click', () => {
      activeViewerZoom = Math.min(3, +(activeViewerZoom + 0.25).toFixed(2));
      applyDocViewerTransforms();
    });
    document.getElementById('docViewerZoomOutBtn')?.addEventListener('click', () => {
      activeViewerZoom = Math.max(0.5, +(activeViewerZoom - 0.25).toFixed(2));
      applyDocViewerTransforms();
    });
    document.getElementById('docViewerZoomResetBtn')?.addEventListener('click', () => {
      activeViewerZoom = 1;
      activeViewerRotation = 0;
      applyDocViewerTransforms();
    });
    document.getElementById('docViewerRotateBtn')?.addEventListener('click', () => {
      activeViewerRotation = (activeViewerRotation + 90) % 360;
      applyDocViewerTransforms();
    });
    document.getElementById('docViewerBwFilterBtn')?.addEventListener('click', () => {
      activeViewerBwFilter = !activeViewerBwFilter;
      applyDocViewerTransforms();
    });
    document.getElementById('docViewerDownloadBtn')?.addEventListener('click', () => {
      if (activeViewerDocId) downloadVaultDocument(activeViewerDocId);
    });
    document.getElementById('docViewerPrintPdfBtn')?.addEventListener('click', () => {
      printScanAsA4Pdf();
    });
    document.getElementById('docViewerCopyImgBtn')?.addEventListener('click', async () => {
      if (!activeViewerAttachment || !activeViewerAttachment.data) return;
      try {
        const srcImg = document.getElementById('docScanViewerImg') || document.querySelector('#docScanViewerPdfPages .doc-scan-pdf-page-img');
        if (srcImg && srcImg.complete && srcImg.naturalWidth > 0) {
          const canvas = document.createElement('canvas');
          canvas.width = srcImg.naturalWidth;
          canvas.height = srcImg.naturalHeight;
          const ctx = canvas.getContext('2d');
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(srcImg, 0, 0);
          const pngBlob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
          if (pngBlob) {
            await navigator.clipboard.write([new ClipboardItem({ 'image/png': pngBlob })]);
            showToast('Copied to Clipboard ✓', 'Document image copied — ready to paste.', 'success');
            return;
          }
        }
        const res = await fetch(activeViewerAttachment.data);
        const blob = await res.blob();
        await navigator.clipboard.write([new ClipboardItem({ [blob.type]: blob })]);
        showToast('Copied to Clipboard ✓', 'Document image copied — ready to paste.', 'success');
      } catch (err) {
        showToast('Copy Note', 'Use Download or Export as A4 PDF for this file format.', 'info');
      }
    });
  }

  // ==========================================
  // 17B. CALENDAR & PLAN ENGINE (Two-Way Google Calendar, Project Followup & Sticky Notes)
  // ==========================================
  const INITIAL_GCAL_SEED_EVENTS = [];

  const DEFAULT_CAL_PLAN_SOURCES = {
    projects: {
      id: 'projects',
      label: 'Projects',
      icon: 'folder-kanban',
      color: '#0284c7',
      showOnMain: true,
      showOnMiniCal: true,
      mainStyle: 'highlight',
      miniStyle: 'bold-number',
      paymentColor: '#0284c7',
      sharePaymentColor: true,
      paymentShowOnMain: true,
      paymentShowOnMiniCal: true,
      paymentMainStyle: 'framed',
      paymentMiniStyle: 'bottom-arc'
    },
    leads: {
      id: 'leads',
      label: 'Leads',
      icon: 'sparkles',
      color: '#d97706',
      showOnMain: true,
      showOnMiniCal: true,
      mainStyle: 'highlight',
      miniStyle: 'star'
    },
    notes: {
      id: 'notes',
      label: 'Notes',
      icon: 'sticky-note',
      color: '#f59e0b',
      showOnMain: true,
      showOnMiniCal: true, // Notes in Sidebar Mini-Calendar are ALWAYS untouched category-colored dots
      mainStyle: 'sticky',
      miniStyle: 'dot'
    },
    my_plan: {
      id: 'my_plan',
      label: 'My Plan',
      icon: 'check-square',
      color: '#0d9488',
      showOnMain: true,
      showOnMiniCal: true,
      miniCalScope: 'week', // 'week' (Show only respective week) | 'all' (Show all items in sidebar mini-calendar)
      mainStyle: 'framed',
      miniStyle: 'dashed'
    },
    meetings: {
      id: 'meetings',
      label: 'Meetings',
      icon: 'calendar-clock',
      color: '#2563eb',
      showOnMain: true,
      showOnMiniCal: true,
      mainStyle: 'highlight',
      miniStyle: 'side-pill'
    },
    bills: {
      id: 'bills',
      label: 'Bills',
      icon: 'credit-card',
      color: '#9333ea',
      showOnMain: false,
      showOnMiniCal: true,
      mainStyle: 'highlight',
      miniStyle: 'highlight'
    }
  };

  const CAL_STYLE_MODES = [
    { id: 'dot', label: 'Dot' },
    { id: 'highlight', label: 'Soft Highlight' },
    { id: 'framed', label: 'Framed Outline' },
    { id: 'dashed', label: 'Dashed Frame' },
    { id: 'underline', label: 'Accent Bar' },
    { id: 'gradient', label: 'Soft Gradient' },
    { id: 'badge', label: 'Solid Badge' }
  ];

  // Non-overlapping Sidebar Mini-Calendar display styles (13 distinct styles rendered as "10" calendar-day previews in one row)
  const MINI_CAL_STYLE_MODES = [
    { id: 'dot', label: 'Dot' },
    { id: 'star', label: 'Call' },
    { id: 'bold-number', label: 'Bold' },
    { id: 'circle', label: 'Gradient' },
    { id: 'highlight', label: 'Fill' },
    { id: 'soft-frame', label: 'Frame' },
    { id: 'dashed', label: 'Dashed' },
    { id: 'underline', label: 'Bracket' },
    { id: 'bottom-arc', label: 'Star' },
    { id: 'side-pill', label: 'Fold' },
    { id: 'corner-pip', label: 'Corner' },
    { id: 'double-ring', label: 'Halo' },
    { id: 'glass-tint', label: 'Glass' }
  ];

  function ensureUniqueMiniCalStyles(sources) {
    if (!sources || typeof sources !== 'object') return;
    delete sources.gcal;
    const validIds = MINI_CAL_STYLE_MODES.map(m => m.id);
    const configurableKeys = ['bills', 'projects', 'leads', 'my_plan', 'meetings'];
    const used = new Set();
    configurableKeys.forEach(k => {
      const src = sources[k];
      if (!src) return;
      if (src.mainStyle === 'framed-highlight') src.mainStyle = 'highlight';
      if (src.miniStyle === 'badge') src.miniStyle = 'highlight';
      if (src.miniStyle === 'framed' || src.miniStyle === 'framed-highlight') src.miniStyle = 'soft-frame';
      if (src.miniStyle === 'gradient') src.miniStyle = 'circle';
      if (src.miniStyle === 'triangle') src.miniStyle = 'star';
      if (src.miniStyle === 'diamond') src.miniStyle = 'bold-number';
      if (src.miniStyle === 'star-bg') src.miniStyle = 'bottom-arc';
      // Dot is the universal shareable default; all other styles must be unique
      if (!validIds.includes(src.miniStyle) || (src.miniStyle !== 'dot' && used.has(src.miniStyle))) {
        const preferred = DEFAULT_CAL_PLAN_SOURCES[k]?.miniStyle;
        if (preferred && validIds.includes(preferred) && (preferred === 'dot' || !used.has(preferred))) {
          src.miniStyle = preferred;
        } else {
          src.miniStyle = 'dot';
        }
      }
      if (src.miniStyle !== 'dot') {
        used.add(src.miniStyle);
      }
    });
    if (sources.projects) {
      const projSrc = sources.projects;
      if (!projSrc.paymentMainStyle || projSrc.paymentMainStyle === 'framed-highlight') {
        projSrc.paymentMainStyle = DEFAULT_CAL_PLAN_SOURCES.projects.paymentMainStyle || 'framed';
      }
      if (!projSrc.paymentColor) {
        projSrc.paymentColor = projSrc.color || '#0284c7';
      }
      if (projSrc.sharePaymentColor === undefined) {
        projSrc.sharePaymentColor = true;
      }
      if (projSrc.paymentShowOnMain === undefined) {
        projSrc.paymentShowOnMain = projSrc.showOnMain !== false;
      }
      if (projSrc.paymentShowOnMiniCal === undefined) {
        projSrc.paymentShowOnMiniCal = projSrc.showOnMiniCal !== false;
      }
      if (projSrc.paymentMiniStyle === 'star-bg') {
        projSrc.paymentMiniStyle = 'bottom-arc';
      }
      // Note: Payment Due Date and Work Milestones CAN share 'dot', while other styles remain unique
      if (!validIds.includes(projSrc.paymentMiniStyle) || (projSrc.paymentMiniStyle !== 'dot' && used.has(projSrc.paymentMiniStyle))) {
        const preferredPay = DEFAULT_CAL_PLAN_SOURCES.projects.paymentMiniStyle || 'bottom-arc';
        if (validIds.includes(preferredPay) && (preferredPay === 'dot' || !used.has(preferredPay))) {
          projSrc.paymentMiniStyle = preferredPay;
        } else {
          projSrc.paymentMiniStyle = 'dot';
        }
      }
      if (projSrc.paymentMiniStyle !== 'dot') {
        used.add(projSrc.paymentMiniStyle);
      }
    }
  }

  const CAL_STUDIO_SWATCHES = [
    '#0d9488', '#2563eb', '#0284c7', '#4f46e5', '#9333ea',
    '#db2777', '#e11d48', '#d97706', '#059669', '#475569'
  ];

  function getDefaultCalendarPlanData() {
    return {
      _styleSchemaVersion: 5,
      viewMode: 'weekly', // 'weekly' | 'monthly'
      weekStart: 'sunday', // 'sunday' (Sun–Sat) | 'monday' (Mon–Sun)
      anchorDate: new Date().toISOString().split('T')[0],
      activeSourceFilter: 'all',
      activeSubFilter: 'all',
      weeklyFocus: {}, // weekKey -> string
      weeklyFocusColors: {}, // weekKey -> hex string
      monthlyFocus: {}, // YYYY-MM -> string
      dayStyles: {},   // YYYY-MM-DD -> { color, style, label }
      customPalettes: {
        projects: [...CAL_STUDIO_SWATCHES],
        projects_payment: [...CAL_STUDIO_SWATCHES],
        leads: [...CAL_STUDIO_SWATCHES],
        my_plan: [...CAL_STUDIO_SWATCHES],
        meetings: [...CAL_STUDIO_SWATCHES],
        bills: [...CAL_STUDIO_SWATCHES]
      },
      customPaletteColors: [],
      deletedPaletteColors: {},
      itemOrderByDate: {}, // YYYY-MM-DD -> [entryId, ...]
      taskAppearance: {
        style: 'framed',
        completedMode: 'strikethrough'
      },
      sources: JSON.parse(JSON.stringify(DEFAULT_CAL_PLAN_SOURCES)),
      items: JSON.parse(JSON.stringify(INITIAL_GCAL_SEED_EVENTS)),
      gcalAccount: 'calendar@finland.local',
      gcalLastSynced: new Date().toISOString()
    };
  }

  function syncGcalAccountLabels() {
    try {
      const acct = (state.calendarPlan && state.calendarPlan.gcalAccount) ? state.calendarPlan.gcalAccount : 'calendar@finland.local';
      const emailEl = document.getElementById('calPlanGcalAccountEmail');
      if (emailEl) emailEl.textContent = acct;
      const codeEl = document.getElementById('calPlanGcalAccountCode');
      if (codeEl) codeEl.textContent = acct;
      const syncTextEl = document.getElementById('calPlanGcalLastSyncText');
      if (syncTextEl) syncTextEl.textContent = `Events from ${acct} are synced with your Finland Calendar.`;
      const openBtnEl = document.getElementById('calPlanOpenGcalModalBtn');
      if (openBtnEl) openBtnEl.setAttribute('title', `Two-Way Google Calendar Sync (${acct})`);
    } catch (e) {}
  }

  function ensureSavedCustomColorsInPalettes(cp) {
    if (!cp || !cp.sources) return;
    if (!cp.customPalettes || typeof cp.customPalettes !== 'object') cp.customPalettes = {};
    if (!cp.deletedPaletteColors || typeof cp.deletedPaletteColors !== 'object') cp.deletedPaletteColors = {};

    const savedList = Array.isArray(cp.customPaletteColors) ? [...cp.customPaletteColors] : [];
    if (cp.sources.projects?.color) savedList.push(cp.sources.projects.color);
    if (cp.sources.projects?.paymentColor) savedList.push(cp.sources.projects.paymentColor);
    Object.keys(cp.sources).forEach(k => {
      if (cp.sources[k]?.color) savedList.push(cp.sources[k].color);
    });

    const uniqueCustom = Array.from(new Set(savedList)).filter(
      c => c && typeof c === 'string' && !CAL_STUDIO_SWATCHES.some(s => s.toLowerCase() === c.toLowerCase())
    );

    cp.customPaletteColors = uniqueCustom;

    const keys = ['projects', 'projects_payment', 'leads', 'my_plan', 'meetings', 'bills'];
    keys.forEach(k => {
      if (!Array.isArray(cp.customPalettes[k])) {
        cp.customPalettes[k] = [...CAL_STUDIO_SWATCHES];
      }
      const deletedForK = Array.isArray(cp.deletedPaletteColors[k]) ? cp.deletedPaletteColors[k] : [];
      uniqueCustom.forEach(hex => {
        const hexNorm = hex.toLowerCase();
        const isDeleted = deletedForK.some(d => d.toLowerCase() === hexNorm);
        const alreadyIn = cp.customPalettes[k].some(p => p.toLowerCase() === hexNorm);
        if (!alreadyIn && !isDeleted) {
          cp.customPalettes[k].push(hex);
        }
      });
    });
  }

  function loadCalendarPlanData() {
    if (state._isCalStylePreviewOpen && state.calendarPlan) return;
    try {
      let raw = localStorage.getItem(STORAGE_KEYS.CALENDAR_PLAN);
      if ((!raw || raw === '{}') && window._lastVaultPayload && window._lastVaultPayload[STORAGE_KEYS.CALENDAR_PLAN]) {
        raw = window._lastVaultPayload[STORAGE_KEYS.CALENDAR_PLAN];
        try { localStorage.setItem(STORAGE_KEYS.CALENDAR_PLAN, raw); } catch (e) {}
      }
      const defaults = getDefaultCalendarPlanData();
      if (!raw || raw === '{}') {
        if (!state.calendarPlan) {
          state.calendarPlan = defaults;
          localStorage.setItem(STORAGE_KEYS.CALENDAR_PLAN, JSON.stringify(state.calendarPlan));
        }
        return;
      }
      const parsed = JSON.parse(raw);
      const mergedSources = {};
      Object.keys(defaults.sources).forEach(k => {
        mergedSources[k] = { ...defaults.sources[k], ...(parsed.sources && parsed.sources[k] ? parsed.sources[k] : {}) };
      });
      if (parsed.sources && typeof parsed.sources === 'object') {
        Object.keys(parsed.sources).forEach(k => {
          if (!mergedSources[k]) mergedSources[k] = { ...(parsed.sources[k] || {}) };
        });
      }
      delete mergedSources.gcal;
      let needsMigrationSave = false;
      if (!mergedSources.meetings) {
        mergedSources.meetings = JSON.parse(JSON.stringify(DEFAULT_CAL_PLAN_SOURCES.meetings));
        needsMigrationSave = true;
      }
      if (mergedSources.notes && mergedSources.notes.label && /sticky/i.test(mergedSources.notes.label)) {
        mergedSources.notes.label = 'Notes';
        needsMigrationSave = true;
      }
      if (mergedSources.my_plan && !mergedSources.my_plan.miniCalScope) {
        mergedSources.my_plan.miniCalScope = 'week';
      }
      if (parsed._styleSchemaVersion !== 5) {
        if (!parsed._styleSchemaVersion || parsed._styleSchemaVersion < 4) {
          if (mergedSources.leads) {
            mergedSources.leads.showOnMiniCal = true;
            mergedSources.leads.miniStyle = 'star';
          }
          if (mergedSources.my_plan) {
            mergedSources.my_plan.showOnMiniCal = true;
            mergedSources.my_plan.miniStyle = 'dashed';
          }
          if (mergedSources.bills) {
            mergedSources.bills.showOnMiniCal = true;
            mergedSources.bills.miniStyle = 'highlight';
          }
        }
        if (mergedSources.projects) {
          mergedSources.projects.showOnMiniCal = true;
          if (!mergedSources.projects.miniStyle || mergedSources.projects.miniStyle === 'circle') {
            mergedSources.projects.miniStyle = 'bold-number';
          }
          if (!mergedSources.projects.paymentMainStyle) {
            mergedSources.projects.paymentMainStyle = 'framed';
          }
          if (!mergedSources.projects.paymentMiniStyle || mergedSources.projects.paymentMiniStyle === 'dot') {
            mergedSources.projects.paymentMiniStyle = 'bottom-arc';
          }
          if (!mergedSources.projects.paymentColor) {
            mergedSources.projects.paymentColor = mergedSources.projects.color || '#0284c7';
          }
          if (mergedSources.projects.sharePaymentColor === undefined) {
            mergedSources.projects.sharePaymentColor = true;
          }
          if (mergedSources.projects.paymentShowOnMain === undefined) {
            mergedSources.projects.paymentShowOnMain = mergedSources.projects.showOnMain !== false;
          }
          if (mergedSources.projects.paymentShowOnMiniCal === undefined) {
            mergedSources.projects.paymentShowOnMiniCal = mergedSources.projects.showOnMiniCal !== false;
          }
        }
        needsMigrationSave = true;
      }
      state.calendarPlan = {
        ...defaults,
        ...parsed,
        _styleSchemaVersion: 5,
        weekStart: parsed.weekStart === 'monday' ? 'monday' : 'sunday',
        activeSourceFilter: parsed.activeSourceFilter === 'gcal' ? 'all' : (parsed.activeSourceFilter || 'all'),
        sources: mergedSources,
        taskAppearance: { ...defaults.taskAppearance, ...(parsed.taskAppearance || {}) },
        dayStyles: {
          ...(state.calendarPlan && state.calendarPlan.dayStyles ? state.calendarPlan.dayStyles : {}),
          ...((parsed.dayStyles && typeof parsed.dayStyles === 'object') ? parsed.dayStyles : {})
        },
        customPalettes: (parsed.customPalettes && typeof parsed.customPalettes === 'object') ? parsed.customPalettes : {},
        customPaletteColors: Array.from(new Set([
          ...(Array.isArray(state.calendarPlan?.customPaletteColors) ? state.calendarPlan.customPaletteColors : []),
          ...(Array.isArray(parsed.customPaletteColors) ? parsed.customPaletteColors : [])
        ])),
        deletedPaletteColors: {
          ...(state.calendarPlan && state.calendarPlan.deletedPaletteColors ? state.calendarPlan.deletedPaletteColors : {}),
          ...((parsed.deletedPaletteColors && typeof parsed.deletedPaletteColors === 'object') ? parsed.deletedPaletteColors : {})
        },
        weeklyFocus: {
          ...(state.calendarPlan && state.calendarPlan.weeklyFocus ? state.calendarPlan.weeklyFocus : {}),
          ...((parsed.weeklyFocus && typeof parsed.weeklyFocus === 'object') ? parsed.weeklyFocus : {})
        },
        weeklyFocusColors: {
          ...(state.calendarPlan && state.calendarPlan.weeklyFocusColors ? state.calendarPlan.weeklyFocusColors : {}),
          ...((parsed.weeklyFocusColors && typeof parsed.weeklyFocusColors === 'object') ? parsed.weeklyFocusColors : {})
        },
        monthlyFocus: {
          ...(state.calendarPlan && state.calendarPlan.monthlyFocus ? state.calendarPlan.monthlyFocus : {}),
          ...((parsed.monthlyFocus && typeof parsed.monthlyFocus === 'object') ? parsed.monthlyFocus : {})
        },
        itemOrderByDate: {
          ...(state.calendarPlan && state.calendarPlan.itemOrderByDate ? state.calendarPlan.itemOrderByDate : {}),
          ...((parsed.itemOrderByDate && typeof parsed.itemOrderByDate === 'object') ? parsed.itemOrderByDate : {})
        },
        items: Array.isArray(parsed.items) ? parsed.items : defaults.items
      };
      ensureUniqueMiniCalStyles(state.calendarPlan.sources);
      ensureSavedCustomColorsInPalettes(state.calendarPlan);
      if (needsMigrationSave) {
        try {
          localStorage.setItem(STORAGE_KEYS.CALENDAR_PLAN, JSON.stringify(state.calendarPlan));
        } catch (e) {}
      }
      // Ensure initial Google Calendar seed events are present unless explicitly deleted
      const deletedGcalIds = new Set(state.calendarPlan.deletedGcalIds || []);
      const existingIds = new Set(state.calendarPlan.items.map(i => i.id));
      INITIAL_GCAL_SEED_EVENTS.forEach(seedEv => {
        if (!existingIds.has(seedEv.id) && !deletedGcalIds.has(seedEv.id)) {
          state.calendarPlan.items.push({ ...seedEv });
        }
      });
      syncGcalAccountLabels();
    } catch (e) {
      console.warn('loadCalendarPlanData warning:', e);
      if (!state.calendarPlan) {
        state.calendarPlan = getDefaultCalendarPlanData();
      }
    }
  }

  function saveCalendarPlanData() {
    try {
      if (!state.calendarPlan) state.calendarPlan = getDefaultCalendarPlanData();
      localStorage.setItem(STORAGE_KEYS.CALENDAR_PLAN, JSON.stringify(state.calendarPlan));
      if (typeof triggerSafeVaultPush === 'function') {
        triggerSafeVaultPush();
      }
    } catch (e) {}
  }

  function formatLocalYMD(dateObj) {
    const y = dateObj.getFullYear();
    const m = String(dateObj.getMonth() + 1).padStart(2, '0');
    const d = String(dateObj.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }

  function parseLocalYMD(ymdStr) {
    if (!ymdStr || typeof ymdStr !== 'string') return new Date();
    const parts = ymdStr.split('-');
    if (parts.length !== 3) return new Date();
    return new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
  }

  function getStartOfWeekDate(dateObj) {
    if (!state.calendarPlan) loadCalendarPlanData();
    const weekStart = (state.calendarPlan && state.calendarPlan.weekStart === 'monday') ? 'monday' : 'sunday';
    const d = new Date(dateObj.getFullYear(), dateObj.getMonth(), dateObj.getDate());
    const day = d.getDay();
    const diff = weekStart === 'monday' ? (day === 0 ? -6 : 1 - day) : -day;
    d.setDate(d.getDate() + diff);
    return d;
  }

  function collectAllCalendarAndPlanEntriesForDate(ymdStr) {
    if (!state.calendarPlan) loadCalendarPlanData();
    const cp = state.calendarPlan;
    const srcCfg = cp.sources || DEFAULT_CAL_PLAN_SOURCES;
    const calendarEntries = [];
    const planEntries = [];

    const parts = ymdStr.split('-');
    const yNum = parseInt(parts[0], 10);
    const mNum = parseInt(parts[1], 10) - 1;
    const dNum = parseInt(parts[2], 10);

    // 1. Custom Plan, Meetings & Calendar Items (automatically synced with Google Calendar)
    (cp.items || []).forEach(item => {
      if (!item || item.date !== ymdStr) return;
      const isMeeting = item.source === 'meetings' || item.subType === 'meetings' || item.kind === 'meeting' || (item.source === 'gcal' && (item.subType === 'meetings' || !item.subType));
      const srcKey = isMeeting ? 'meetings' : 'my_plan';
      const sCfg = (srcCfg && srcCfg[srcKey]) || DEFAULT_CAL_PLAN_SOURCES[srcKey] || DEFAULT_CAL_PLAN_SOURCES.my_plan;
      const entry = {
        ...item,
        source: srcKey,
        sourceLabel: isMeeting ? (sCfg.label || 'Meeting') : sCfg.label,
        badgeLabel: isMeeting ? 'Meeting' : 'Plan',
        color: item.customColor || sCfg.color,
        displayStyle: sCfg.mainStyle || (isMeeting ? 'highlight' : 'framed'),
        miniStyle: sCfg.miniStyle || (isMeeting ? 'side-pill' : 'framed'),
        showOnMain: sCfg.showOnMain !== false,
        showOnMiniCal: !!sCfg.showOnMiniCal
      };
      if (item.kind === 'calendar' || item.source === 'gcal' || isMeeting || item.subType === 'events') {
        calendarEntries.push(entry);
      } else {
        planEntries.push(entry);
      }
    });

    // 2. Project Followup Integration: Project Work Deadlines, Payment Due Dates (Calendar) & Project Stepstones (Plan)
    const projects = (state.budget && Array.isArray(state.budget.projects)) ? state.budget.projects : [];
    const projCfg = srcCfg.projects || DEFAULT_CAL_PLAN_SOURCES.projects;
    const workColor = projCfg.color || '#0284c7';
    const payColor = projCfg.sharePaymentColor === false ? (projCfg.paymentColor || workColor) : workColor;
    const workMiniStyle = projCfg.miniStyle || 'bold-number';
    const payMiniStyle = projCfg.paymentMiniStyle || 'bottom-arc';
    const payMainStyle = projCfg.paymentMainStyle || 'framed';
    const payShowMain = projCfg.paymentShowOnMain !== false && projCfg.showOnMain !== false;
    const payShowMini = projCfg.paymentShowOnMiniCal !== false && !!projCfg.showOnMiniCal;

    projects.forEach(proj => {
      if (!proj || isProjectDone(proj)) return;
      const projDate = proj.dueDate || proj.expectedDate || '';
      const projDisplayName = proj.title || proj.name || proj.client || 'Project';
      const workIsDone = isProjectWorkDone(proj);
      const totalAmt = parseFloat(proj.amount !== undefined ? proj.amount : proj.fee) || 0;
      const paidAmt = parseFloat(proj.paidAmount) || 0;
      const isPaidInFull = proj.status === 'paid' || (paidAmt >= totalAmt && totalAmt > 0);
      const payDue = proj.paymentDueDate || (proj.proformaInvoice && proj.proformaInvoice.validUntil) || '';

      if (projDate === ymdStr) {
        calendarEntries.push({
          id: `proj_deadline_${proj.id}`,
          projectId: proj.id,
          title: `Deadline: ${projDisplayName}`,
          projectName: proj.client || '',
          clientName: proj.client || '',
          date: ymdStr,
          time: 'Deadline',
          completed: workIsDone,
          kind: 'calendar',
          source: 'projects',
          subType: 'deadlines',
          projectFilterId: `proj_${proj.id}`,
          sourceLabel: projDisplayName,
          badgeLabel: 'Work Deadline',
          color: workColor,
          displayStyle: projCfg.mainStyle || 'highlight',
          miniStyle: workMiniStyle,
          showOnMain: projCfg.showOnMain !== false,
          showOnMiniCal: !!projCfg.showOnMiniCal && !workIsDone
        });
      }
      if (payDue && payDue === ymdStr && !isPaidInFull) {
        calendarEntries.push({
          id: `proj_payment_due_${proj.id}`,
          projectId: proj.id,
          title: `Payment Due: ${projDisplayName}`,
          projectName: proj.client || '',
          clientName: proj.client || '',
          date: ymdStr,
          time: 'Payment Due',
          completed: false,
          kind: 'calendar',
          source: 'projects',
          subType: 'payment_deadlines',
          projectFilterId: `proj_${proj.id}`,
          sourceLabel: projDisplayName,
          badgeLabel: 'Payment Due',
          color: payColor,
          displayStyle: payMainStyle,
          miniStyle: payMiniStyle,
          showOnMain: payShowMain,
          showOnMiniCal: payShowMini
        });
      }
      if (Array.isArray(proj.steps)) {
        proj.steps.forEach((step, sIdx) => {
          if (!step) return;
          const stepDate = step.dueDate || step.plannedDate || '';
          if (stepDate === ymdStr) {
            planEntries.push({
              id: `proj_step_${proj.id}_${step.id || sIdx}`,
              projectId: proj.id,
              stepId: step.id,
              stepIdx: sIdx,
              title: step.title || step.text || 'Project Step',
              projectName: projDisplayName,
              date: ymdStr,
              completed: !!(step.completed || step.done),
              kind: 'plan',
              source: 'projects',
              subType: 'stepstones',
              projectFilterId: `proj_${proj.id}`,
              sourceLabel: projDisplayName,
              badgeLabel: projDisplayName,
              color: workColor,
              displayStyle: projCfg.mainStyle || 'highlight',
              miniStyle: workMiniStyle,
              showOnMain: projCfg.showOnMain !== false,
              showOnMiniCal: !!projCfg.showOnMiniCal
            });
          }
        });
      }
    });

    // 3. Project Followup Leads Integration
    const leads = (state.budget && Array.isArray(state.budget.leads)) ? state.budget.leads : [];
    const leadCfg = srcCfg.leads || DEFAULT_CAL_PLAN_SOURCES.leads;
    leads.forEach(lead => {
      if (!lead || lead.status === 'archived' || lead.status === 'lost') return;
      const leadDate = lead.targetDate || lead.followUpDate || lead.dueDate || lead.expectedDate || '';
      const leadDisplayTitle = lead.title || lead.name || lead.client || 'Inquiry';
      const hasQuote = !!(lead.priceOfferingData || lead.quoteSent);
      if (leadDate === ymdStr) {
        planEntries.push({
          id: `lead_followup_${lead.id}`,
          leadId: lead.id,
          title: `Lead: ${leadDisplayTitle}`,
          projectName: (lead.title && lead.client && lead.title !== lead.client) ? lead.client : '',
          clientName: lead.client || '',
          date: ymdStr,
          completed: lead.status === 'won',
          kind: 'plan',
          source: 'leads',
          subType: hasQuote ? 'offerings' : 'lead_followups',
          sourceLabel: 'Lead Follow-Up',
          badgeLabel: 'Lead Follow-Up',
          color: leadCfg.color || '#d97706',
          displayStyle: leadCfg.mainStyle || 'highlight',
          miniStyle: leadCfg.miniStyle || 'underline',
          showOnMain: leadCfg.showOnMain !== false,
          showOnMiniCal: !!leadCfg.showOnMiniCal
        });
      }
      if (Array.isArray(lead.steps)) {
        lead.steps.forEach((step, sIdx) => {
          if (!step) return;
          const stepDate = step.dueDate || step.plannedDate || '';
          if (stepDate === ymdStr) {
            planEntries.push({
              id: `lead_step_${lead.id}_${step.id || sIdx}`,
              leadId: lead.id,
              stepId: step.id,
              stepIdx: sIdx,
              title: step.title || step.text || 'Lead Step',
              projectName: leadDisplayTitle,
              clientName: lead.client || '',
              date: ymdStr,
              completed: !!(step.completed || step.done),
              kind: 'plan',
              source: 'leads',
              subType: hasQuote ? 'offerings' : 'lead_followups',
              sourceLabel: leadDisplayTitle,
              badgeLabel: leadDisplayTitle,
              color: leadCfg.color || '#d97706',
              displayStyle: leadCfg.mainStyle || 'highlight',
              miniStyle: leadCfg.miniStyle || 'underline',
              showOnMain: leadCfg.showOnMain !== false,
              showOnMiniCal: !!leadCfg.showOnMiniCal
            });
          }
        });
      }
    });

    // 4. Notes Integration (Rendered as actual little Post-it Sticky Notes in their Note Category Color!)
    const notesCfg = srcCfg.notes || DEFAULT_CAL_PLAN_SOURCES.notes;
    const rawDayNotes = (state.notes || []).filter(note => note && note.dueDate === ymdStr);
    const stickyOrder = (cp.stickyOrderByDate && Array.isArray(cp.stickyOrderByDate[ymdStr])) ? cp.stickyOrderByDate[ymdStr] : [];
    if (stickyOrder.length > 0) {
      rawDayNotes.sort((a, b) => {
        const ia = stickyOrder.indexOf(a.id);
        const ib = stickyOrder.indexOf(b.id);
        if (ia === -1 && ib === -1) return 0;
        if (ia === -1) return 1;
        if (ib === -1) return -1;
        return ia - ib;
      });
    }
    rawDayNotes.forEach(note => {
      const catColor = (typeof getNoteCategoryColor === 'function') ? getNoteCategoryColor(note) : '#f59e0b';
      const catIcon = (typeof getNoteCategoryIcon === 'function') ? getNoteCategoryIcon(note) : 'sticky-note';
      const bodyStr = note.body || (Array.isArray(note.bodyBlocks) ? note.bodyBlocks.filter(Boolean).join(' ') : '') || note.content || '';
      planEntries.push({
        id: `note_sticky_${note.id}`,
        noteId: note.id,
        title: note.title || 'Untitled Note',
        content: bodyStr,
        noteLabel: note.label || 'General',
        date: ymdStr,
        completed: !!(note.isDone || note.completed),
        kind: 'sticky_note',
        source: 'notes',
        subType: `label_${(note.label || 'General').toLowerCase()}`,
        sourceLabel: note.label || 'Note',
        badgeLabel: note.label || 'Note',
        color: catColor,
        icon: catIcon,
        displayStyle: 'sticky',
        miniStyle: 'dot',
        showOnMain: true,
        showOnMiniCal: false // Notes already render natively via notesByDay in renderSidebarSubscriptionCalendar
      });
    });

    // 5. Optional Bills & Subscriptions on Main Calendar
    const billsCfg = srcCfg.bills || DEFAULT_CAL_PLAN_SOURCES.bills;
    const calYearMonthStr = ymdStr.substring(0, 7);
    (state.subscriptions || []).forEach(sub => {
      if (!sub || sub.isFrozen) return;
      const nameLower = (sub.name || '').toLowerCase();
      if (nameLower.includes('proforma') || nameLower.includes('price offering') || nameLower.includes('tax receipt') || nameLower.includes('deposit / upfront') || nameLower.includes('project deliverables')) {
        return;
      }
      let bDay = sub.billingDay ? parseInt(sub.billingDay, 10) : (sub.lastBilledDate ? parseInt(sub.lastBilledDate.split('-')[2], 10) : null);
      if (bDay === dNum) {
        if (sub.billingCycle === 'yearly' && sub.lastBilledDate) {
          const subMonth = parseInt(sub.lastBilledDate.split('-')[1], 10) - 1;
          if (subMonth !== mNum) return;
        }
        const isPaid = (typeof isSubscriptionPaidInMonth === 'function')
          ? isSubscriptionPaidInMonth(sub, calYearMonthStr)
          : false;
        calendarEntries.push({
          id: `bill_cal_${sub.id}_${ymdStr}`,
          subId: sub.id,
          title: `${sub.name} (${formatMoney(sub.amount, sub.currency)})`,
          date: ymdStr,
          time: 'Bill',
          completed: isPaid,
          isPaid: isPaid,
          kind: 'calendar',
          source: 'bills',
          subType: 'subscriptions',
          sourceLabel: 'Monthly Bill',
          badgeLabel: 'Monthly Bill',
          color: billsCfg.color || '#9333ea',
          displayStyle: billsCfg.mainStyle || 'highlight',
          miniStyle: billsCfg.miniStyle || 'badge',
          showOnMain: !!billsCfg.showOnMain,
          showOnMiniCal: false // Already rendered natively by billsByDay in sidebar mini-calendar
        });
      }
    });

    return { calendarEntries, planEntries };
  }

  function getSortedDayEntriesForDate(ymd, filteredCal, filteredPlan) {
    if (!state.calendarPlan) loadCalendarPlanData();
    const cp = state.calendarPlan;
    const allEntries = [...filteredCal, ...filteredPlan];
    const dayOrder = (cp && cp.itemOrderByDate && Array.isArray(cp.itemOrderByDate[ymd])) ? cp.itemOrderByDate[ymd] : null;

    if (dayOrder && dayOrder.length > 0) {
      return [...allEntries].sort((a, b) => {
        const ia = dayOrder.indexOf(a.id);
        const ib = dayOrder.indexOf(b.id);
        if (ia !== -1 && ib !== -1) return ia - ib;
        if (ia !== -1) return -1;
        if (ib !== -1) return 1;
        return 0;
      });
    }

    const legacyStickyOrder = (cp && cp.stickyOrderByDate && Array.isArray(cp.stickyOrderByDate[ymd])) ? cp.stickyOrderByDate[ymd] : null;
    if (legacyStickyOrder && legacyStickyOrder.length > 0) {
      const stickyNotes = filteredPlan.filter(e => e.kind === 'sticky_note');
      const regularPlan = filteredPlan.filter(e => e.kind !== 'sticky_note');
      stickyNotes.sort((a, b) => {
        const ia = legacyStickyOrder.indexOf(a.noteId || a.id);
        const ib = legacyStickyOrder.indexOf(b.noteId || b.id);
        if (ia !== -1 && ib !== -1) return ia - ib;
        if (ia !== -1) return -1;
        if (ib !== -1) return 1;
        return 0;
      });
      return [...filteredCal, ...stickyNotes, ...regularPlan];
    }

    const stickyNotes = filteredPlan.filter(e => e.kind === 'sticky_note');
    const regularPlan = filteredPlan.filter(e => e.kind !== 'sticky_note');
    return [...filteredCal, ...stickyNotes, ...regularPlan];
  }

  function getMiniCalendarExtraItemsByDay(year, month) {
    if (!state.calendarPlan) loadCalendarPlanData();
    if (state.calendarPlan && state.calendarPlan.sources) {
      ensureUniqueMiniCalStyles(state.calendarPlan.sources);
    }

    const myPlanCfg = (state.calendarPlan && state.calendarPlan.sources && state.calendarPlan.sources.my_plan) || DEFAULT_CAL_PLAN_SOURCES.my_plan;
    const showMyPlanMini = myPlanCfg.showOnMiniCal !== false;
    const myPlanMiniScope = myPlanCfg.miniCalScope || 'week'; // 'week' (default: respective week) | 'all' (all month)

    // Calculate the respective week boundary for 'week' scope matching Calendar & Plan
    let weekStartYmd = '';
    let weekEndYmd = '';
    if (showMyPlanMini && myPlanMiniScope === 'week') {
      const now = new Date();
      let refDate = now;
      const anchor = (state.calendarPlan && state.calendarPlan.anchorDate) ? parseLocalYMD(state.calendarPlan.anchorDate) : null;
      if (anchor) {
        const anchorStart = getStartOfWeekDate(anchor);
        const anchorEnd = new Date(anchorStart.getFullYear(), anchorStart.getMonth(), anchorStart.getDate() + 6);
        if ((anchorStart.getFullYear() === year && anchorStart.getMonth() === month) || (anchorEnd.getFullYear() === year && anchorEnd.getMonth() === month)) {
          refDate = anchor;
        } else if (now.getFullYear() === year && now.getMonth() === month) {
          refDate = now;
        } else {
          const nowStart = getStartOfWeekDate(now);
          const nowEnd = new Date(nowStart.getFullYear(), nowStart.getMonth(), nowStart.getDate() + 6);
          if ((nowStart.getFullYear() === year && nowStart.getMonth() === month) || (nowEnd.getFullYear() === year && nowEnd.getMonth() === month)) {
            refDate = now;
          } else {
            refDate = new Date(year, month, 1);
          }
        }
      } else if (now.getFullYear() === year && now.getMonth() === month) {
        refDate = now;
      }
      const startD = getStartOfWeekDate(refDate);
      const endD = new Date(startD.getFullYear(), startD.getMonth(), startD.getDate() + 6);
      weekStartYmd = formatLocalYMD(startD);
      weekEndYmd = formatLocalYMD(endD);
    }

    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const map = {};
    for (let day = 1; day <= daysInMonth; day++) {
      const ymd = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      const { calendarEntries, planEntries } = collectAllCalendarAndPlanEntriesForDate(ymd);
      const extras = [...calendarEntries, ...planEntries].filter(e => {
        if (!e.showOnMiniCal || e.source === 'notes' || e.source === 'bills') return false;
        if (e.completed || e.done || e.isDone) return false; // Marked done tasks/plans disappear from sidebar calendar
        if (e.source === 'my_plan') {
          if (!showMyPlanMini) return false;
          if (myPlanMiniScope === 'week') {
            if (ymd < weekStartYmd || ymd > weekEndYmd) return false;
          }
        }
        return true;
      });
      if (extras.length > 0) {
        map[day] = extras;
      }
    }
    return map;
  }

  function jumpCalendarPlanToDate(ymdStr) {
    if (!state.calendarPlan) loadCalendarPlanData();
    state.calendarPlan.anchorDate = ymdStr;
    saveCalendarPlanData();
    if (state.currentTab === 'calendar_plan') {
      renderCalendarPlanView();
    }
  }

  function openMonthlyPlanForMonth(ymStr) {
    if (!ymStr || !/^\d{4}-\d{2}$/.test(ymStr)) return;
    if (!state.calendarPlan) loadCalendarPlanData();
    state._calPlanEditingWeeklyFocus = false;
    state.calendarPlan.viewMode = 'monthly';
    state.calendarPlan.anchorDate = `${ymStr}-01`;
    state.calendarPlan.activeSourceFilter = 'all';
    state.calendarPlan.activeSubFilter = 'all';
    state.calPlanSearch = '';
    saveCalendarPlanData();
    if (typeof setSelectedMonthPeriod === 'function') {
      setSelectedMonthPeriod(ymStr);
    } else {
      state.selectedMonth = ymStr;
      state.budgetMonth = ymStr;
      const select = document.getElementById('monthFilter');
      if (select) select.value = ymStr;
      try { populateMonthFilterOptions(); } catch (e) {}
    }
    if (window._ftSetActiveTab) {
      window._ftSetActiveTab('calendar_plan');
    } else {
      renderCalendarPlanView();
    }
  }

  function openMonthlyPlanAndFlashDay(ymdStr) {
    if (!ymdStr || !/^\d{4}-\d{2}-\d{2}$/.test(ymdStr)) return;
    const ymStr = ymdStr.substring(0, 7);
    if (!state.calendarPlan) loadCalendarPlanData();
    state._calPlanEditingWeeklyFocus = false;
    state.calendarPlan.viewMode = 'monthly';
    state.calendarPlan.anchorDate = ymdStr;
    saveCalendarPlanData();
    if (typeof setSelectedMonthPeriod === 'function') {
      setSelectedMonthPeriod(ymStr);
      state.calendarPlan.anchorDate = ymdStr;
      saveCalendarPlanData();
    } else {
      state.selectedMonth = ymStr;
      state.budgetMonth = ymStr;
      const select = document.getElementById('monthFilter');
      if (select) select.value = ymStr;
      try { populateMonthFilterOptions(); } catch (e) {}
    }
    if (window._ftSetActiveTab) {
      window._ftSetActiveTab('calendar_plan');
    } else {
      renderCalendarPlanView();
    }

    setTimeout(() => {
      const monthlyEl = document.getElementById('calPlanMonthlyContainer');
      if (!monthlyEl) return;
      monthlyEl.querySelectorAll('.cal-day-gentle-flash').forEach(el => {
        el.classList.remove('cal-day-gentle-flash');
      });
      const safeYmd = (typeof CSS !== 'undefined' && CSS.escape) ? CSS.escape(ymdStr) : ymdStr;
      const cellEl = monthlyEl.querySelector(`.cal-day-drop-zone[data-day-ymd="${safeYmd}"]`);
      if (!cellEl) return;
      if (cellEl._flashTimer) {
        clearTimeout(cellEl._flashTimer);
      }
      void cellEl.offsetWidth;
      cellEl.classList.add('cal-day-gentle-flash');
      try {
        cellEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      } catch (e) {}
      cellEl._flashTimer = setTimeout(() => {
        cellEl.classList.remove('cal-day-gentle-flash');
        cellEl._flashTimer = null;
      }, 1500);
    }, 45);
  }

  function filterCalendarPlanEntry(entry) {
    if (!entry.showOnMain && state.calendarPlan.activeSourceFilter === 'all') return false;
    const activeSrc = state.calendarPlan.activeSourceFilter || 'all';
    const activeSub = state.calendarPlan.activeSubFilter || 'all';
    if (activeSrc !== 'all' && entry.source !== activeSrc) return false;
    if (activeSrc !== 'all' && activeSub !== 'all') {
      if (entry.subType !== activeSub && entry.projectFilterId !== activeSub) return false;
    }
    const q = (state.calPlanSearch || '').toLowerCase();
    if (q) {
      const hay = `${entry.title || ''} ${entry.sourceLabel || ''} ${entry.location || ''} ${entry.projectName || ''} ${entry.noteLabel || ''}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  }

  function renderCalEntryStyledPill(entry, isCompact = false) {
    const isPaidBill = !!(entry.source === 'bills' && entry.isPaid);
    const isDone = !!(entry.completed || entry.done || entry.isDone);
    const color = entry.color || '#0d9488';
    const styleMode = (entry.displayStyle === 'framed-highlight' || !entry.displayStyle) ? 'highlight' : entry.displayStyle;
    let boxStyle = '';
    let textStyle = `color: #0f172a;`;
    let borderClass = 'border border-slate-200/80 bg-white';

    // Soft Highlight on the Main Calendar has a clean soft fill with no frame
    if (isPaidBill) {
      boxStyle = `background-color: #f1f5f9; border: 1px solid #cbd5e1;`;
      borderClass = '';
      textStyle = `color: #64748b;`;
    } else if (isDone) {
      boxStyle = `background-color: #f8fafc; border: 1px solid #e2e8f0;`;
      borderClass = '';
      textStyle = `color: #94a3b8;`;
    } else if (styleMode === 'highlight') {
      boxStyle = `background-color: ${color}16; border: 1px solid transparent;`;
    } else if (styleMode === 'framed') {
      boxStyle = `background-color: #ffffff; border: 1px solid ${color}45;`;
    } else if (styleMode === 'dashed') {
      boxStyle = `background-color: #ffffff; border: 1px dashed ${color}65;`;
    } else if (styleMode === 'underline') {
      boxStyle = `background-color: #f8fafc; border-left: 3px solid ${color}; border-top-color: transparent; border-right-color: transparent; border-bottom-color: transparent;`;
    } else if (styleMode === 'gradient') {
      boxStyle = `background: linear-gradient(90deg, ${color}24 0%, ${color}08 65%, #ffffff 100%); border: 1px solid ${color}35;`;
    } else if (styleMode === 'badge') {
      boxStyle = `background-color: ${color}; border-color: ${color};`;
      textStyle = `color: #ffffff;`;
    } else if (styleMode === 'dot') {
      boxStyle = `background-color: #ffffff; border: 1px solid #e2e8f0;`;
    }

    const isRedundantTimeLabel = (entry.time === 'Deadline' || entry.time === 'Payment Due' || entry.time === 'Bill');
    const timeBadge = (entry.time && !isRedundantTimeLabel)
      ? `<span class="text-[9px] font-mono font-bold ${isCompact ? 'px-1 py-0' : 'px-1.5 py-0.2'} rounded shrink-0" style="${isDone ? 'background:#f1f5f9;color:#94a3b8;' : (styleMode === 'badge' ? 'background:rgba(255,255,255,0.2);color:#fff;' : `background:${color}18;color:${color};`)}">${escapeHtml(entry.time)}</span>`
      : '';

    const bulletColor = isPaidBill ? '#94a3b8' : (isDone ? '#cbd5e1' : (styleMode === 'badge' ? '#ffffff' : color));

    return `
      <div class="cal-plan-entry-card group relative rounded-xl ${isCompact ? 'px-2 py-1' : 'px-2.5 py-1.5'} ${borderClass} transition-all cursor-grab active:cursor-grabbing flex items-center justify-between gap-1.5 ${isPaidBill ? '' : (isDone ? 'opacity-80' : '')}"
           style="${boxStyle}"
           draggable="true"
           data-entry-id="${escapeHtml(entry.id)}"
           data-entry-kind="${escapeHtml(entry.kind || '')}"
           data-entry-source="${escapeHtml(entry.source)}"
           data-day-ymd="${escapeHtml(entry.date || '')}"
           data-project-id="${escapeHtml(entry.projectId || '')}"
           data-step-id="${escapeHtml(entry.stepId || '')}"
           data-step-idx="${entry.stepIdx !== undefined ? entry.stepIdx : ''}"
           data-lead-id="${escapeHtml(entry.leadId || '')}"
           data-note-id="${escapeHtml(entry.noteId || '')}">
        <div class="flex items-center gap-1.5 min-w-0 flex-1">
          ${(entry.kind === 'plan' && (entry.source === 'my_plan' || ((entry.source === 'projects' || entry.source === 'leads') && entry.stepIdx !== undefined))) ? `
            <input type="checkbox" class="cal-plan-toggle-check cursor-pointer shrink-0"
                   data-entry-id="${escapeHtml(entry.id)}"
                   data-entry-source="${escapeHtml(entry.source)}"
                   data-project-id="${escapeHtml(entry.projectId || '')}"
                   data-step-id="${escapeHtml(entry.stepId || '')}"
                   data-step-idx="${entry.stepIdx !== undefined ? entry.stepIdx : ''}"
                   data-lead-id="${escapeHtml(entry.leadId || '')}"
                   ${isDone ? 'checked' : ''}
                   ${isDone ? '' : 'title="Mark as done"'}>
          ` : `<span class="w-2 h-2 rounded-full shrink-0" style="background-color: ${bulletColor};"></span>`}
          <div class="min-w-0 flex-1">
            <div class="text-[11px] font-semibold leading-snug break-words ${isCompact ? 'truncate' : 'line-clamp-2'}" style="${isPaidBill ? 'color: #64748b;' : (isDone ? 'color: #94a3b8; text-decoration: line-through; text-decoration-color: #64748b;' : textStyle)}">${escapeHtml(entry.title)}</div>
            ${(entry.projectName || (!isCompact && entry.location)) ? `
              <div class="text-[9px] truncate ${isCompact ? 'mt-0' : 'mt-0.5'}" style="${isDone ? 'color: #94a3b8; text-decoration: line-through; text-decoration-color: #64748b;' : (styleMode === 'badge' ? 'color:rgba(255,255,255,0.85);' : 'color:#64748b;')}">
                ${escapeHtml(entry.projectName || entry.location)}
              </div>
            ` : ''}
          </div>
        </div>
        ${timeBadge}
      </div>
    `;
  }

  function renderStickyNoteOnCalendar(entry, isCompact = false) {
    const isDone = !!(entry.completed || entry.done || entry.isDone);
    const c = entry.color || '#f59e0b';
    const foldSize = isCompact ? 10 : 12;
    const foldW = foldSize + 2;
    const foldH = foldSize + 2;

    const cardStyle = isDone
      ? 'background-color: #f8fafc; border: 1px solid #e2e8f0; border-top: 2px solid #e2e8f0;'
      : `background-color: ${c}14; border: 1px solid ${c}35; border-top: 2.5px solid ${c};`;

    const creaseColor = isDone ? '#e2e8f0' : c;
    const flapFill = isDone ? '#cbd5e1' : c;
    const flapFillOpacity = isDone ? '0.12' : '0.32';
    const flapStroke = isDone ? '#e2e8f0' : c;
    const flapStrokeOpacity = isDone ? '0.45' : '0.5';
    const labelColor = isDone ? '#94a3b8' : c;

    return `
      <div class="cal-sticky-note group ${isCompact ? 'p-2' : 'p-2.5'} cursor-grab active:cursor-grabbing transition-all ${isDone ? 'opacity-80' : ''}"
           style="${cardStyle}"
           draggable="true"
           data-entry-id="${escapeHtml(entry.id)}"
           data-entry-source="notes"
           data-note-id="${escapeHtml(entry.noteId || '')}"
           data-day-ymd="${escapeHtml(entry.date || '')}"
           ${isDone ? '' : 'title="Click to highlight in Notes • Drag to reorder or move between days"'}>
        <svg class="cal-sticky-fold pointer-events-none" width="${foldW}" height="${foldH}" viewBox="0 0 ${foldW} ${foldH}" fill="none">
          <polygon points="0,0 ${foldW},0 ${foldW},${foldH}" fill="var(--cal-day-col-bg, #ffffff)" />
          <line x1="0" y1="0" x2="${foldW}" y2="${foldH}" stroke="${creaseColor}" stroke-width="1.2" stroke-opacity="0.45" />
          <polygon points="0,0 0,${foldH} ${foldW},${foldH}" fill="${flapFill}" fill-opacity="${flapFillOpacity}" stroke="${flapStroke}" stroke-width="0.8" stroke-opacity="${flapStrokeOpacity}" style="filter: drop-shadow(-1px 1px 1px rgba(15, 23, 42, 0.08));" />
        </svg>
        <div class="flex items-start justify-between gap-1.5 pr-2.5">
          <div class="flex items-center gap-1.5 min-w-0">
            <input type="checkbox" class="cal-sticky-note-check cursor-pointer shrink-0"
                   data-note-id="${escapeHtml(entry.noteId || '')}"
                   ${isDone ? 'checked' : ''}
                   ${isDone ? '' : 'title="Mark note as done"'}>
            <span class="text-[9px] font-bold uppercase tracking-wider truncate" style="color: ${labelColor};">${escapeHtml(entry.noteLabel || 'Note')}</span>
          </div>
        </div>
        <div class="mt-1 text-[11px] font-bold leading-snug break-words ${isCompact ? 'truncate' : 'line-clamp-2'}" style="${isDone ? 'color: #94a3b8; text-decoration: line-through; text-decoration-color: #64748b;' : 'color: #0f172a;'}">
          ${escapeHtml(entry.title)}
        </div>
        ${(!isCompact && entry.content) ? `
          <div class="mt-0.5 text-[10px] line-clamp-2 leading-relaxed break-words" style="${isDone ? 'color: #94a3b8; text-decoration: line-through; text-decoration-color: #64748b;' : 'color: #475569;'}">${escapeHtml(entry.content)}</div>
        ` : ''}
      </div>
    `;
  }

  function renderCalendarPlanSourcesFilterBar() {
    const barEl = document.getElementById('calPlanSourcesFilterBar');
    const subBarEl = document.getElementById('calPlanSubFilterContainer');
    if (!barEl) return;

    const cp = state.calendarPlan;
    const activeSrc = (cp.activeSourceFilter && cp.activeSourceFilter !== 'gcal') ? cp.activeSourceFilter : 'all';
    const activeSub = cp.activeSubFilter || 'all';
    const sourcesList = [
      { id: 'all', label: 'All', icon: 'layers', color: '#0f172a' },
      cp.sources.projects || DEFAULT_CAL_PLAN_SOURCES.projects,
      cp.sources.leads || DEFAULT_CAL_PLAN_SOURCES.leads,
      cp.sources.notes || DEFAULT_CAL_PLAN_SOURCES.notes,
      cp.sources.my_plan || DEFAULT_CAL_PLAN_SOURCES.my_plan,
      cp.sources.meetings || DEFAULT_CAL_PLAN_SOURCES.meetings,
      cp.sources.bills || DEFAULT_CAL_PLAN_SOURCES.bills
    ];

    barEl.innerHTML = sourcesList.map(src => {
      const isActive = activeSrc === src.id;
      const activeClass = isActive
        ? 'bg-slate-900 text-white border-slate-900 shadow-2xs font-bold'
        : 'bg-slate-50/80 hover:bg-slate-100 text-slate-600 hover:text-slate-900 border-slate-200/80 font-medium';
      return `
        <button type="button" data-cal-source="${escapeHtml(src.id)}" class="cal-source-filter-pill inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl text-xs border transition-all cursor-pointer whitespace-nowrap">
          <span class="w-2 h-2 rounded-full shrink-0" style="background-color: ${isActive ? '#ffffff' : escapeHtml(src.color || '#0d9488')};"></span>
          <span>${escapeHtml(src.id === 'notes' ? 'Notes' : src.label)}</span>
        </button>
      `;
    }).join('').replace(/class="cal-source-filter-pill/g, (m, offset, str) => m);

    // Apply active class cleanly
    barEl.querySelectorAll('.cal-source-filter-pill').forEach(btn => {
      const sid = btn.getAttribute('data-cal-source');
      if (sid === activeSrc) {
        btn.classList.add('bg-slate-900', 'text-white', 'border-slate-900', 'shadow-2xs', 'font-bold');
      } else {
        btn.classList.add('bg-slate-50/80', 'hover:bg-slate-100', 'text-slate-600', 'hover:text-slate-900', 'border-slate-200/80', 'font-medium');
      }
    });

    if (!subBarEl) return;
    if (activeSrc === 'all') {
      subBarEl.classList.add('hidden');
      subBarEl.classList.remove('flex');
      subBarEl.innerHTML = '';
      return;
    }

    let subOptions = [{ id: 'all', label: 'All ' + (cp.sources[activeSrc]?.label || '') }];
    if (activeSrc === 'gcal') {
      subOptions.push({ id: 'meetings', label: 'Meetings & Calls' }, { id: 'events', label: 'Events & Stays' }, { id: 'time_blocks', label: 'Time Blocks' });
    } else if (activeSrc === 'projects') {
      subOptions.push({ id: 'deadlines', label: 'Project Deadlines' }, { id: 'stepstones', label: 'Project Stepstones' });
      ((state.budget && state.budget.projects) || []).filter(p => p && p.status !== 'completed').forEach(p => {
        subOptions.push({ id: `proj_${p.id}`, label: p.name || p.title || 'Project' });
      });
    } else if (activeSrc === 'leads') {
      subOptions.push({ id: 'lead_followups', label: 'Lead Follow-Ups' }, { id: 'offerings', label: 'Price Offerings' });
    } else if (activeSrc === 'notes') {
      const seenLabels = new Set();
      (state.notes || []).forEach(n => {
        const lbl = (n && n.label) ? n.label.trim() : 'General';
        if (!seenLabels.has(lbl.toLowerCase())) {
          seenLabels.add(lbl.toLowerCase());
          subOptions.push({ id: `label_${lbl.toLowerCase()}`, label: lbl });
        }
      });
    } else if (activeSrc === 'meetings') {
      subOptions.push(
        { id: 'all_meetings', label: 'All Meetings' },
        { id: 'meetings', label: 'Meetings & Calls' },
        { id: 'events', label: 'Calendar Events' }
      );
    } else if (activeSrc === 'my_plan') {
      subOptions.push(
        { id: 'daily_tasks', label: 'Daily Tasks' },
        { id: 'weekly_goals', label: 'Weekly Goals' },
        { id: 'time_blocks', label: 'Focus Time Blocks' }
      );
    } else if (activeSrc === 'bills') {
      subOptions.push({ id: 'subscriptions', label: 'Subscriptions' });
    }

    subBarEl.classList.remove('hidden');
    subBarEl.classList.add('flex');
    subBarEl.innerHTML = `<span class="text-[10px] font-bold uppercase tracking-wider text-slate-400 mr-1">Sub-Filter:</span>` + subOptions.map(opt => {
      const isSubActive = activeSub === opt.id;
      return `
        <button type="button" data-cal-subfilter="${escapeHtml(opt.id)}" class="cal-sub-filter-pill px-2.5 py-1 rounded-lg text-[11px] border transition-all cursor-pointer ${isSubActive ? 'bg-teal-600 text-white border-teal-600 font-bold' : 'bg-white hover:bg-slate-50 text-slate-600 border-slate-200 font-medium'}">
          ${escapeHtml(opt.label)}
        </button>
      `;
    }).join('');
  }

  function renderCalPlanUnscheduledQueue() {
    const badgeEl = document.getElementById('calPlanQueueCountBadge');
    const listEl = document.getElementById('calPlanUnscheduledList');
    const unscheduled = [];

    const projects = (state.budget && Array.isArray(state.budget.projects)) ? state.budget.projects : [];
    projects.forEach(proj => {
      if (!proj || isProjectDone(proj)) return;
      (proj.steps || []).forEach((step, idx) => {
        if (!step || step.completed || step.done) return;
        if (!step.dueDate && !step.plannedDate) {
          unscheduled.push({
            kind: 'project_step',
            projectId: proj.id,
            stepId: step.id || '',
            stepIdx: idx,
            title: step.title || step.text || 'Step',
            subtitle: proj.title || proj.name || proj.client || 'Project',
            color: '#0284c7'
          });
        }
      });
    });

    const leads = (state.budget && Array.isArray(state.budget.leads)) ? state.budget.leads : [];
    leads.forEach(lead => {
      if (!lead || lead.status === 'archived' || lead.status === 'lost' || lead.status === 'won') return;
      const leadTitle = lead.title || lead.name || lead.client || 'Lead Inquiry';
      if (!lead.targetDate && !lead.followUpDate && !lead.dueDate && !lead.expectedDate) {
        unscheduled.push({
          kind: 'lead',
          leadId: lead.id,
          title: leadTitle,
          subtitle: 'Lead Follow-Up',
          color: '#d97706'
        });
      }
      (lead.steps || []).forEach((step, idx) => {
        if (!step || step.completed || step.done) return;
        if (!step.dueDate && !step.plannedDate) {
          unscheduled.push({
            kind: 'lead_step',
            leadId: lead.id,
            stepId: step.id || '',
            stepIdx: idx,
            title: step.title || step.text || 'Step',
            subtitle: leadTitle,
            color: '#d97706'
          });
        }
      });
    });

    if (badgeEl) badgeEl.textContent = String(unscheduled.length);
    if (!listEl) return;

    if (unscheduled.length === 0) {
      listEl.innerHTML = `<div class="col-span-full py-4 text-center text-xs text-slate-400">All active project stepstones and leads are scheduled on your Calendar &amp; Plan! ✨</div>`;
      return;
    }

    const todayStr = formatLocalYMD(new Date());
    listEl.innerHTML = unscheduled.map(item => `
      <div class="p-2.5 rounded-xl bg-slate-50/90 border border-slate-200/80 flex items-center justify-between gap-2 hover:border-sky-300 transition-all"
           draggable="true"
           data-queue-kind="${escapeHtml(item.kind)}"
           data-project-id="${escapeHtml(item.projectId || '')}"
           data-step-id="${escapeHtml(item.stepId || '')}"
           data-step-idx="${item.stepIdx !== undefined ? item.stepIdx : ''}"
           data-lead-id="${escapeHtml(item.leadId || '')}">
        <div class="min-w-0 flex-1">
          <div class="flex items-center gap-1.5">
            <span class="w-2 h-2 rounded-full shrink-0" style="background-color: ${item.color};"></span>
            <span class="text-[10px] font-bold uppercase tracking-wider text-slate-400 truncate">${escapeHtml(item.subtitle)}</span>
          </div>
          <div class="text-xs font-semibold text-slate-800 truncate mt-0.5">${escapeHtml(item.title)}</div>
        </div>
        <input type="date" class="cal-queue-assign-date bg-white border border-slate-200 rounded-lg px-2 py-1 text-[10px] font-mono text-slate-700 cursor-pointer shrink-0"
               value=""
               min="2024-01-01"
               title="Pick a date to schedule on your Plan"
               data-queue-kind="${escapeHtml(item.kind)}"
               data-project-id="${escapeHtml(item.projectId || '')}"
               data-step-id="${escapeHtml(item.stepId || '')}"
               data-step-idx="${item.stepIdx !== undefined ? item.stepIdx : ''}"
               data-lead-id="${escapeHtml(item.leadId || '')}">
      </div>
    `).join('');
  }

  function renderCalendarPlanView() {
    if (!state.calendarPlan) loadCalendarPlanData();
    if (typeof healFollowupLiveData === 'function') healFollowupLiveData();
    const cp = state.calendarPlan;

    renderCalendarPlanSourcesFilterBar();
    renderCalPlanUnscheduledQueue();

    const modeWeeklyBtn = document.getElementById('calPlanModeWeeklyBtn');
    const modeMonthlyBtn = document.getElementById('calPlanModeMonthlyBtn');
    const periodNavBox = document.getElementById('calPlanPeriodNavBox');
    const weeklyFocusBar = document.getElementById('calPlanWeeklyFocusBar');
    const weeklyContainer = document.getElementById('calPlanWeeklyContainer');
    const monthlyContainer = document.getElementById('calPlanMonthlyContainer');
    const periodLabel = document.getElementById('calPlanCurrentPeriodLabel');

    const activeModeClass = 'px-2.5 py-1.5 rounded-lg bg-white text-slate-900 shadow-2xs transition-all cursor-pointer flex items-center gap-1.5 font-bold whitespace-nowrap';
    const inactiveModeClass = 'px-2.5 py-1.5 rounded-lg text-slate-600 hover:text-slate-900 transition-all cursor-pointer flex items-center gap-1.5 font-semibold whitespace-nowrap';

    if (modeWeeklyBtn) modeWeeklyBtn.className = cp.viewMode === 'weekly' ? activeModeClass : inactiveModeClass;
    if (modeMonthlyBtn) modeMonthlyBtn.className = cp.viewMode === 'monthly' ? activeModeClass : inactiveModeClass;

    const anchor = parseLocalYMD(cp.anchorDate);
    const todayStr = formatLocalYMD(new Date());
    const dayNamesShort = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const dayNamesFull = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

    const parseHexRgb = (hexStr) => {
      const clean = String(hexStr || '').trim().replace(/^#/, '');
      if (clean.length === 3) {
        return [
          parseInt(clean[0] + clean[0], 16) || 13,
          parseInt(clean[1] + clean[1], 16) || 148,
          parseInt(clean[2] + clean[2], 16) || 136
        ];
      }
      if (clean.length === 6) {
        return [
          parseInt(clean.slice(0, 2), 16) || 0,
          parseInt(clean.slice(2, 4), 16) || 0,
          parseInt(clean.slice(4, 6), 16) || 0
        ];
      }
      return [13, 148, 136];
    };

    const renderWeeklyFocusBarForAnchor = (focusAnchorDate) => {
      if (!weeklyFocusBar) return;
      const focusWeekStart = getStartOfWeekDate(focusAnchorDate);
      const focusWeekKey = formatLocalYMD(focusWeekStart);
      // Pair Sunday & Monday start keys of the same week so switching Week Format never loses the weekly goal
      const focusAltWeekStart = cp.weekStart === 'monday'
        ? new Date(focusWeekStart.getFullYear(), focusWeekStart.getMonth(), focusWeekStart.getDate() - 1)
        : new Date(focusWeekStart.getFullYear(), focusWeekStart.getMonth(), focusWeekStart.getDate() + 1);
      const focusAltWeekKey = formatLocalYMD(focusAltWeekStart);

      const rawVal = cp.weeklyFocus[focusWeekKey] || cp.weeklyFocus[focusAltWeekKey] || '';
      const focusVal = rawVal.trim();
      const weekAccent = (cp.weeklyFocusColors && (cp.weeklyFocusColors[focusWeekKey] || cp.weeklyFocusColors[focusAltWeekKey])) || '#0d9488';
      weeklyFocusBar.className = 'flex items-center gap-2 min-w-0 flex-1 h-7 select-none';
      weeklyFocusBar.removeAttribute('title');
      weeklyFocusBar.innerHTML = `
        <i data-lucide="target" class="w-4 h-4 shrink-0" style="color: ${escapeHtml(weekAccent)};"></i>
        <label for="calPlanWeeklyFocusInput" class="text-xs font-bold uppercase tracking-wider shrink-0 whitespace-nowrap cursor-pointer" style="color: ${escapeHtml(weekAccent)};">Weekly Goal:</label>
        <input type="text" id="calPlanWeeklyFocusInput" name="calPlanWeeklyGoal" data-goal-scope="weekly" data-week-key="${escapeHtml(focusWeekKey)}" data-alt-week-key="${escapeHtml(focusAltWeekKey)}" value="${escapeHtml(rawVal)}" placeholder="Main goal for this week..." enterkeyhint="done" class="${focusVal ? '' : 'is-empty '}flex-1 max-w-xs min-w-0 text-[15px] font-bold text-slate-900 tracking-tight placeholder:text-xs placeholder:font-medium placeholder:text-slate-400" style="--goal-line-color: ${escapeHtml(weekAccent)};">
      `;
    };

    const renderMonthlyGoalBarForMonth = (yearNum, monthZeroIdx) => {
      if (!weeklyFocusBar) return;
      const monthKey = `${yearNum}-${String(monthZeroIdx + 1).padStart(2, '0')}`;
      const rawVal = (cp.monthlyFocus && cp.monthlyFocus[monthKey]) || '';
      const goalVal = rawVal.trim();
      weeklyFocusBar.className = 'flex items-center gap-2 min-w-0 flex-1 h-7 select-none';
      weeklyFocusBar.removeAttribute('title');
      weeklyFocusBar.innerHTML = `
        <i data-lucide="target" class="w-4 h-4 text-teal-600 shrink-0"></i>
        <label for="calPlanWeeklyFocusInput" class="text-xs font-bold uppercase tracking-wider text-teal-700 shrink-0 whitespace-nowrap cursor-pointer">Monthly Goal:</label>
        <input type="text" id="calPlanWeeklyFocusInput" name="calPlanMonthlyGoal" data-goal-scope="monthly" data-month-key="${escapeHtml(monthKey)}" value="${escapeHtml(rawVal)}" placeholder="Main goal for this month..." enterkeyhint="done" class="${goalVal ? '' : 'is-empty '}flex-1 max-w-xs min-w-0 text-[15px] font-bold text-slate-900 tracking-tight placeholder:text-xs placeholder:font-medium placeholder:text-slate-400" style="--goal-line-color: #0d9488;">
      `;
    };

    if (cp.viewMode === 'weekly') {
      if (periodNavBox) {
        periodNavBox.classList.remove('hidden');
        periodNavBox.classList.add('inline-flex');
      }
      if (weeklyFocusBar) weeklyFocusBar.classList.remove('hidden');
      if (weeklyContainer) weeklyContainer.classList.remove('hidden');
      if (monthlyContainer) monthlyContainer.classList.add('hidden');

      const weekStart = getStartOfWeekDate(anchor);
      const weekDays = [];
      for (let i = 0; i < 7; i++) {
        const d = new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate() + i);
        weekDays.push(d);
      }
      const weekEnd = weekDays[6];

      if (periodLabel) {
        const sMonth = monthNames[weekStart.getMonth()].slice(0, 3);
        const eMonth = monthNames[weekEnd.getMonth()].slice(0, 3);
        periodLabel.textContent = sMonth === eMonth
          ? `${sMonth} ${weekStart.getDate()} – ${weekEnd.getDate()}, ${weekEnd.getFullYear()}`
          : `${sMonth} ${weekStart.getDate()} – ${eMonth} ${weekEnd.getDate()}, ${weekEnd.getFullYear()}`;
      }

      renderWeeklyFocusBarForAnchor(anchor);

      if (weeklyContainer) {
        const renderDayColumn = (d) => {
          const ymd = formatLocalYMD(d);
          const isToday = ymd === todayStr;
          const dayCustom = (cp.dayStyles && cp.dayStyles[ymd]) || null;
          const { calendarEntries, planEntries } = collectAllCalendarAndPlanEntriesForDate(ymd);
          const filteredCal = calendarEntries.filter(filterCalendarPlanEntry);
          const filteredPlan = planEntries.filter(filterCalendarPlanEntry);
          const sortedEntries = getSortedDayEntriesForDate(ymd, filteredCal, filteredPlan);
          const totalCount = sortedEntries.length;

          let headerStyle = '';
          let colStyle = '';
          if (dayCustom && dayCustom.color) {
            if (dayCustom.style === 'highlight') {
              headerStyle = `background-color: ${dayCustom.color}16;`;
            } else if (dayCustom.style === 'framed' || dayCustom.style === 'framed-highlight') {
              headerStyle = `background-color: ${dayCustom.color}14; border-bottom: 1px solid ${dayCustom.color}35;`;
              colStyle = `background-color: ${dayCustom.color}06; --cal-day-col-bg: ${dayCustom.color}06;`;
            } else if (dayCustom.style === 'badge') {
              headerStyle = `background-color: ${dayCustom.color}; color: #ffffff;`;
            } else {
              headerStyle = `border-top: 2px solid ${dayCustom.color};`;
            }
          } else if (isToday) {
            colStyle = `background-color: rgba(240, 253, 250, 0.22); --cal-day-col-bg: #f8fdfc;`;
          }

          return `
            <div class="cal-day-drop-zone group/day bg-white flex flex-col justify-between min-h-[420px] transition-colors overflow-hidden" style="${colStyle}" data-day-ymd="${escapeHtml(ymd)}">
              <div class="flex-1 flex flex-col min-w-0">
                <!-- Compact Seamless Day Header -->
                <div class="cal-day-header cursor-pointer px-2.5 py-2 border-b border-slate-100 flex items-center justify-between gap-1 ${isToday ? 'bg-teal-50/50' : 'bg-slate-50/50'}" style="${headerStyle}" title="Click to add plan task or event to ${escapeHtml(ymd)}">
                  <div class="flex items-center gap-1.5 min-w-0">
                    <span class="text-[11px] font-bold uppercase tracking-wider ${isToday ? 'text-teal-700' : 'text-slate-400'}">${dayNamesShort[d.getDay()]}</span>
                    <span class="w-6 h-6 rounded-full text-xs font-extrabold flex items-center justify-center shrink-0 ${isToday ? 'bg-teal-600 text-white shadow-2xs' : 'text-slate-900'}">${d.getDate()}</span>
                    ${dayCustom && dayCustom.label ? `<span class="text-[9px] font-bold px-1.5 py-0.2 rounded-full truncate" style="background:${dayCustom.color || '#0d9488'}18;color:${dayCustom.color || '#0d9488'};border:1px solid ${dayCustom.color || '#0d9488'}35;">${escapeHtml(dayCustom.label)}</span>` : ''}
                  </div>
                  <div class="flex items-center gap-0.5 shrink-0">
                    ${totalCount > 0 ? `<span class="text-[10px] font-mono font-bold text-slate-400 px-1.5 py-0.2 rounded-full bg-white/80 border border-slate-200/60 group-hover/day:hidden">${totalCount}</span>` : ''}
                    <div class="hidden group-hover/day:flex items-center gap-0.5">
                      <button type="button" class="cal-day-color-btn p-1 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-white cursor-pointer" data-day-ymd="${escapeHtml(ymd)}" title="Customize day color">
                        <i data-lucide="palette" class="w-3 h-3"></i>
                      </button>
                      <button type="button" class="cal-day-add-btn p-1 rounded-lg text-slate-400 hover:text-teal-600 hover:bg-white cursor-pointer" data-day-ymd="${escapeHtml(ymd)}" title="Add event or plan to ${escapeHtml(ymd)}">
                        <i data-lucide="plus" class="w-3.5 h-3.5"></i>
                      </button>
                    </div>
                  </div>
                </div>

                <!-- Unified Streamlined Day Body (Maximum text width, zero redundant headers) -->
                <div class="cal-day-items-list cursor-pointer p-2 space-y-1.5 flex-1 flex flex-col min-w-0" data-day-ymd="${escapeHtml(ymd)}" title="Click to add plan task or event to ${escapeHtml(ymd)}">
                  ${sortedEntries.map(e => (e.kind === 'sticky_note' ? renderStickyNoteOnCalendar(e, false) : renderCalEntryStyledPill(e, false))).join('')}
                </div>
              </div>

              <!-- Subtle Inline Quick-Add Input -->
              <div class="px-2 py-1.5 border-t border-slate-100/80 bg-slate-50/25">
                <input type="text" class="cal-inline-quick-add w-full bg-transparent hover:bg-white focus:bg-white border border-transparent hover:border-slate-200/80 focus:border-teal-500 rounded-lg px-2 py-1 text-[11px] text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-teal-500/15 transition-all"
                       placeholder="+ Add plan..."
                       data-day-ymd="${escapeHtml(ymd)}">
              </div>
            </div>
          `;
        };

        weeklyContainer.innerHTML = `
          <div class="grid grid-cols-1 lg:grid-cols-7 divide-y lg:divide-y-0 lg:divide-x divide-slate-100">
            ${weekDays.map(renderDayColumn).join('')}
          </div>
        `;
      }
    } else {
      // MONTHLY PLAN VIEW (Uses Top Bar Month Picker; hides duplicate period nav box)
      if (periodNavBox) {
        periodNavBox.classList.add('hidden');
        periodNavBox.classList.remove('inline-flex');
      }
      if (weeklyFocusBar) weeklyFocusBar.classList.remove('hidden');
      if (weeklyContainer) weeklyContainer.classList.add('hidden');
      if (monthlyContainer) monthlyContainer.classList.remove('hidden');

      let year = anchor.getFullYear();
      let month = anchor.getMonth();
      if (state.selectedMonth && state.selectedMonth !== 'ALL' && /^\d{4}-\d{2}$/.test(state.selectedMonth)) {
        const [selY, selM] = state.selectedMonth.split('-');
        year = parseInt(selY, 10);
        month = parseInt(selM, 10) - 1;
      }
      if (periodLabel) {
        periodLabel.textContent = `${monthNames[month]} ${year}`;
      }

      renderMonthlyGoalBarForMonth(year, month);

      const weekStart = cp.weekStart === 'monday' ? 'monday' : 'sunday';
      const headers = weekStart === 'monday'
        ? ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
        : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

      const firstDayIdx = new Date(year, month, 1).getDay();
      const firstOffset = weekStart === 'monday' ? (firstDayIdx + 6) % 7 : firstDayIdx;
      const daysInMonth = new Date(year, month + 1, 0).getDate();
      const totalWeeks = Math.ceil((firstOffset + daysInMonth) / 7);

      const activeSrc = (cp.activeSourceFilter && cp.activeSourceFilter !== 'gcal') ? cp.activeSourceFilter : 'all';
      const activeSub = cp.activeSubFilter || 'all';
      const myPlanCfg = (cp.sources && cp.sources.my_plan) || DEFAULT_CAL_PLAN_SOURCES.my_plan;
      const myPlanColor = myPlanCfg.color || '#0d9488';
      const canShowWeeklyGoalBanners =
        (activeSrc === 'all' && myPlanCfg.showOnMain !== false) ||
        (activeSrc === 'my_plan' && (activeSub === 'all' || activeSub === 'weekly_goals'));
      const searchQuery = (state.calPlanSearch || '').trim().toLowerCase();

      let gridHtml = `
        <div class="grid grid-cols-7 border-b border-slate-200/80 bg-slate-50/70 text-center text-[11px] font-bold uppercase tracking-wider text-slate-400 py-2">
          ${headers.map(h => `<div>${h}</div>`).join('')}
        </div>
        <div class="divide-y divide-slate-100">
      `;

      for (let w = 0; w < totalWeeks; w++) {
        const rowStartDate = new Date(year, month, 1 - firstOffset + (w * 7));
        const rowWeekKey = formatLocalYMD(rowStartDate);
        const rowAltDate = weekStart === 'monday'
          ? new Date(rowStartDate.getFullYear(), rowStartDate.getMonth(), rowStartDate.getDate() - 1)
          : new Date(rowStartDate.getFullYear(), rowStartDate.getMonth(), rowStartDate.getDate() + 1);
        const rowAltWeekKey = formatLocalYMD(rowAltDate);
        const rawWeekGoal = ((cp.weeklyFocus && (cp.weeklyFocus[rowWeekKey] || cp.weeklyFocus[rowAltWeekKey])) || '').trim();
        const showWeekGoalBanner = !!(
          canShowWeeklyGoalBanners &&
          rawWeekGoal &&
          (!searchQuery || rawWeekGoal.toLowerCase().includes(searchQuery) || 'weekly goal'.includes(searchQuery))
        );

        let weekAnchorYmd = rowWeekKey;
        for (let c = 0; c < 7; c++) {
          const dCandidate = (w * 7 + c) - firstOffset + 1;
          if (dCandidate >= 1 && dCandidate <= daysInMonth) {
            weekAnchorYmd = `${year}-${String(month + 1).padStart(2, '0')}-${String(dCandidate).padStart(2, '0')}`;
            break;
          }
        }

        gridHtml += `<div class="cal-month-week-row ${showWeekGoalBanner ? 'has-weekly-goal' : ''}">`;

        for (let c = 0; c < 7; c++) {
          const col = c + 1;
          const day = (w * 7 + c) - firstOffset + 1;

          if (day < 1 || day > daysInMonth) {
            if (showWeekGoalBanner) {
              gridHtml += `<div class="cal-month-day-cell min-h-[135px] bg-slate-50/40 border-r border-slate-100 last:border-r-0" style="grid-column: ${col};"></div>`;
            } else {
              gridHtml += `<div class="cal-month-day-cell min-h-[130px] bg-slate-50/40 p-2 border-r border-slate-100 last:border-r-0"></div>`;
            }
            continue;
          }

          const ymd = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
          const isToday = ymd === todayStr;
          const dayCustom = (cp.dayStyles && cp.dayStyles[ymd]) || null;
          const { calendarEntries, planEntries } = collectAllCalendarAndPlanEntriesForDate(ymd);
          const filteredCal = calendarEntries.filter(filterCalendarPlanEntry);
          const filteredPlan = planEntries.filter(filterCalendarPlanEntry);
          const sortedEntries = getSortedDayEntriesForDate(ymd, filteredCal, filteredPlan);

          let cellCustomStyle = '';
          if (dayCustom && dayCustom.color) {
            cellCustomStyle = `background-color: ${dayCustom.color}12; box-shadow: inset 0 0 0 1px ${dayCustom.color}35;`;
          }

          const dayHeaderHtml = `
            <span class="cal-monthly-day-num w-6 h-6 rounded-full text-xs font-bold flex items-center justify-center transition-transform ${isToday ? 'bg-teal-600 text-white shadow-2xs' : 'text-slate-700'}">${day}</span>
            <div class="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
              <button type="button" class="cal-day-color-btn p-1 rounded text-slate-400 hover:text-slate-700 cursor-pointer" data-day-ymd="${escapeHtml(ymd)}" title="Customize day color">
                <i data-lucide="palette" class="w-3 h-3"></i>
              </button>
              <button type="button" class="cal-day-add-btn p-1 rounded text-slate-400 hover:text-teal-600 cursor-pointer" data-day-ymd="${escapeHtml(ymd)}" title="Add item">
                <i data-lucide="plus" class="w-3 h-3"></i>
              </button>
            </div>
          `;
          const dayEntriesHtml = sortedEntries
            .slice(0, 4)
            .map(e => (e.kind === 'sticky_note' ? renderStickyNoteOnCalendar(e, true) : renderCalEntryStyledPill(e, true)))
            .join('');

          if (showWeekGoalBanner) {
            gridHtml += `
              <div class="cal-month-day-cell cal-day-drop-zone min-h-[135px] bg-white hover:bg-slate-50/40 border-r border-slate-100 last:border-r-0 transition-colors group cursor-pointer" style="grid-column: ${col}; ${cellCustomStyle}" data-day-ymd="${escapeHtml(ymd)}" title="Click to add plan task or event to ${escapeHtml(ymd)}">
                <div class="p-2 space-y-1.5 min-w-0" style="grid-row: 1;">
                  <div class="flex items-center justify-between">
                    ${dayHeaderHtml}
                  </div>
                  <div class="space-y-1 min-w-0">
                    ${dayEntriesHtml}
                  </div>
                </div>
              </div>
            `;
          } else {
            gridHtml += `
              <div class="cal-month-day-cell cal-day-drop-zone min-h-[135px] p-2 bg-white hover:bg-slate-50/40 border-r border-slate-100 last:border-r-0 transition-colors flex flex-col justify-between group cursor-pointer" style="${cellCustomStyle}" data-day-ymd="${escapeHtml(ymd)}" title="Click to add plan task or event to ${escapeHtml(ymd)}">
                <div class="space-y-1.5 min-w-0">
                  <div class="flex items-center justify-between">
                    ${dayHeaderHtml}
                  </div>
                  <div class="space-y-1 min-w-0">
                    ${dayEntriesHtml}
                  </div>
                </div>
              </div>
            `;
          }
        }

        if (showWeekGoalBanner) {
          const weekGoalColor = (cp.weeklyFocusColors && (cp.weeklyFocusColors[rowWeekKey] || cp.weeklyFocusColors[rowAltWeekKey])) || myPlanColor;
          const [wgR, wgG, wgB] = parseHexRgb(weekGoalColor);
          gridHtml += `
            <div role="button"
                 tabindex="0"
                 class="cal-monthly-weekly-goal-bar relative w-full pt-2.5 pb-1.5 px-3 flex items-center justify-between gap-2 text-left cursor-pointer transition-all group/wg min-w-0 select-none"
                 style="grid-column: 1 / -1; grid-row: 2; z-index: 20; background: linear-gradient(to bottom var(--in-oklab), rgba(${wgR}, ${wgG}, ${wgB}, 0) 0%, rgba(${wgR}, ${wgG}, ${wgB}, 0.03) 35%, rgba(${wgR}, ${wgG}, ${wgB}, 0.09) 72%, rgba(${wgR}, ${wgG}, ${wgB}, 0.18) 100%); border-bottom: 1px solid rgba(${wgR}, ${wgG}, ${wgB}, 0.28);"
                 data-week-anchor-ymd="${escapeHtml(weekAnchorYmd)}"
                 title="Open this week in Weekly Plan">
              <span class="flex items-center gap-1.5 min-w-0 flex-1">
                <i data-lucide="target" class="w-3.5 h-3.5 shrink-0" style="color: ${escapeHtml(weekGoalColor)};"></i>
                <span class="text-xs font-semibold uppercase tracking-wider shrink-0" style="color: ${escapeHtml(weekGoalColor)};">Weekly Goal:</span>
                <span class="text-xs font-semibold uppercase tracking-wider text-slate-900 truncate min-w-0">${escapeHtml(rawWeekGoal)}</span>
              </span>
              <div class="flex items-center gap-0.5 opacity-0 group-hover/wg:opacity-100 focus-within:opacity-100 transition-opacity shrink-0">
                <button type="button"
                        class="cal-weekly-goal-color-btn p-1 rounded text-slate-400 hover:text-slate-700 hover:bg-white/75 cursor-pointer transition-colors"
                        data-week-key="${escapeHtml(rowWeekKey)}"
                        data-alt-week-key="${escapeHtml(rowAltWeekKey)}"
                        title="Customize weekly goal color">
                  <i data-lucide="palette" class="w-3 h-3"></i>
                </button>
              </div>
            </div>
          `;
        }

        gridHtml += `</div>`;
      }

      gridHtml += `</div>`;
      if (monthlyContainer) monthlyContainer.innerHTML = gridHtml;
    }

    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      try { window.lucide.createIcons(); } catch (e) {}
    }
  }

  function openCalPlanItemModal(defaultDate = null, editItemId = null) {
    if (!state.calendarPlan) loadCalendarPlanData();
    const modal = document.getElementById('calPlanItemModal');
    if (!modal) return;

    const projSelect = document.getElementById('calPlanItemProjectSelect');
    if (projSelect) {
      let opts = `<option value="">None (Personal)</option>`;
      ((state.budget && state.budget.projects) || []).filter(p => p && p.status !== 'completed').forEach(p => {
        opts += `<option value="proj:${escapeHtml(p.id)}">Project: ${escapeHtml(p.title || p.name || 'Project')}</option>`;
      });
      ((state.budget && state.budget.leads) || []).filter(l => l && l.status !== 'archived').forEach(l => {
        opts += `<option value="lead:${escapeHtml(l.id)}">Lead: ${escapeHtml(l.name || l.client || 'Lead')}</option>`;
      });
      projSelect.innerHTML = opts;
    }

    const existing = editItemId ? (state.calendarPlan.items || []).find(i => i.id === editItemId) : null;
    document.getElementById('calPlanItemId').value = existing ? existing.id : '';
    document.getElementById('calPlanItemTitleInput').value = existing ? existing.title : '';
    document.getElementById('calPlanItemDateInput').value = existing ? existing.date : (defaultDate || state.calendarPlan.anchorDate || formatLocalYMD(new Date()));
    document.getElementById('calPlanItemTimeInput').value = existing ? (existing.time || '') : '';
    
    let defaultSubType = 'daily_tasks';
    if (existing) {
      defaultSubType = existing.subType || (existing.source === 'meetings' ? 'meetings' : 'daily_tasks');
    }
    document.getElementById('calPlanItemSubTypeSelect').value = defaultSubType;
    document.getElementById('calPlanItemLocationInput').value = existing ? (existing.location || '') : '';
    document.getElementById('calPlanItemSyncGcalCheck').checked = existing ? !!existing.syncGcal : true;

    const delBtn = document.getElementById('deleteCalPlanItemBtn');
    if (delBtn) delBtn.classList.toggle('hidden', !existing);

    const initialKind = existing
      ? (existing.kind || (existing.source === 'meetings' || existing.subType === 'meetings' ? 'calendar' : 'plan'))
      : 'plan';
    setCalPlanModalKind(initialKind);

    modal.classList.remove('hidden');
    modal.classList.add('flex');
    const modalTitle = document.getElementById('calPlanItemModalTitle');
    if (modalTitle) {
      modalTitle.textContent = existing ? 'Edit Plan or Calendar Event' : 'New Plan or Calendar Event';
    }
    const titleInput = document.getElementById('calPlanItemTitleInput');
    if (titleInput) {
      setTimeout(() => { try { titleInput.focus(); } catch (e) {} }, 50);
    }
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      try { window.lucide.createIcons(); } catch (e) {}
    }
  }

  function setCalPlanModalKind(kind) {
    document.getElementById('calPlanItemKind').value = kind;
    const planBtn = document.getElementById('calPlanKindPlanBtn');
    const evBtn = document.getElementById('calPlanKindEventBtn');
    const activeCls = 'py-1.5 px-3 rounded-xl bg-white text-slate-900 shadow-2xs transition-all flex items-center justify-center gap-1.5 cursor-pointer font-bold';
    const inactiveCls = 'py-1.5 px-3 rounded-xl text-slate-600 hover:text-slate-900 transition-all flex items-center justify-center gap-1.5 cursor-pointer font-semibold';
    if (planBtn) planBtn.className = kind === 'plan' ? activeCls : inactiveCls;
    if (evBtn) evBtn.className = kind === 'calendar' ? activeCls : inactiveCls;
  }

  function closeCalPlanItemModal() {
    const modal = document.getElementById('calPlanItemModal');
    if (!modal) return;
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }

  function getCalStudioPalette(sourceKey) {
    if (!state.calendarPlan) loadCalendarPlanData();
    ensureSavedCustomColorsInPalettes(state.calendarPlan);
    if (!state.calendarPlan.customPalettes || typeof state.calendarPlan.customPalettes !== 'object') {
      state.calendarPlan.customPalettes = {};
    }
    if (!Array.isArray(state.calendarPlan.customPalettes[sourceKey])) {
      state.calendarPlan.customPalettes[sourceKey] = [...CAL_STUDIO_SWATCHES];
    }
    return state.calendarPlan.customPalettes[sourceKey];
  }

  function buildCalStudioColorChooserHtml(sourceKey, currentColor) {
    const normColor = (currentColor || '#0d9488').toLowerCase();
    const palette = getCalStudioPalette(sourceKey);
    const isPresetSelected = palette.some(hex => hex.toLowerCase() === normColor);
    const isCustomized = palette.length !== CAL_STUDIO_SWATCHES.length ||
      !palette.every((c, i) => c.toLowerCase() === CAL_STUDIO_SWATCHES[i]?.toLowerCase());

    const swatchesHtml = palette.map(hex => {
      const isSelected = hex.toLowerCase() === normColor;
      const ringCls = isSelected ? 'ring-2 ring-slate-900 shadow-xs scale-110' : 'border-white/80 hover:scale-105';
      return `
        <div class="cal-studio-color-item relative group shrink-0 inline-flex items-center justify-center">
          <button type="button"
                  class="cal-studio-color-swatch w-5 h-5 rounded-full border ${ringCls} cursor-pointer transition-transform shrink-0"
                  style="background-color: ${hex};"
                  data-source-key="${escapeHtml(sourceKey)}"
                  data-color="${hex}"
                  title="${hex}"></button>
          <button type="button"
                  class="cal-studio-delete-color-btn absolute -top-1 -right-1 w-3.5 h-3.5 rounded-full bg-slate-900 text-white hover:bg-rose-600 flex items-center justify-center text-[10px] leading-none font-bold shadow-xs cursor-pointer z-10"
                  data-source-key="${escapeHtml(sourceKey)}"
                  data-color="${hex}"
                  title="Remove ${hex} from palette">&times;</button>
        </div>
      `;
    }).join('');

    const wheelRingCls = !isPresetSelected ? 'ring-2 ring-slate-900 shadow-xs scale-110' : 'border-white/80 hover:scale-105';

    const wheelHtml = `
      <label class="cal-studio-wheel-label relative w-5 h-5 rounded-full shrink-0 transition-all cursor-pointer shadow-2xs flex items-center justify-center border ${wheelRingCls}"
             style="background: conic-gradient(from 0deg, #ef4444, #f97316, #eab308, #22c55e, #06b6d4, #3b82f6, #a855f7, #ec4899, #ef4444);"
             title="Custom Color Wheel (${escapeHtml(currentColor)})">
        <input type="color" class="cal-studio-color-wheel-input sr-only" data-source-key="${escapeHtml(sourceKey)}" value="${escapeHtml(currentColor)}">
        ${!isPresetSelected ? `<span class="w-2 h-2 rounded-full border border-white shadow-2xs pointer-events-none" style="background-color: ${escapeHtml(currentColor)};"></span>` : ''}
      </label>
    `;

    const resetHtml = isCustomized ? `
      <button type="button"
              class="cal-studio-reset-palette-btn text-[11px] text-slate-400 hover:text-slate-700 transition-colors cursor-pointer px-1 py-0.5 rounded hover:bg-slate-100"
              data-source-key="${escapeHtml(sourceKey)}"
              title="Reset palette to default 10 colors">↺</button>
    ` : '';

    return `
      <div class="flex items-center gap-1.5 flex-wrap">
        ${swatchesHtml}
        ${wheelHtml}
        ${resetHtml}
      </div>
    `;
  }

  function buildVisualStylePreviewPill(modeId, label, color, isSelected, targetKind, sourceKey, takenByLabel = null) {
    const effColor = color;
    const titleAttr = isSelected
      ? `title="Active: ${escapeHtml(label)}"`
      : (takenByLabel ? `title="${escapeHtml(label)} (currently used by ${escapeHtml(takenByLabel)} — click to select)"` : `title="${escapeHtml(label)}"`);

    // Sidebar Mini-Calendar Display Style: render each option like an actual calendar day tile with the number "10"
    if (targetKind === 'mini') {
      const isTaken = !isSelected && !!takenByLabel;
      let dayBoxStyle = isTaken
        ? 'background-color:#f1f5f9; border:1px solid #cbd5e1; opacity:0.45;'
        : 'background-color:#ffffff; border:1px solid #e2e8f0;';
      let numStyle = isTaken
        ? 'color:#94a3b8; font-weight:400;'
        : 'color:#334155; font-weight:400;';
      let innerDecorationHtml = '';

      if (modeId === 'dot') {
        innerDecorationHtml = `<span style="position:absolute;bottom:2.5px;left:50%;transform:translateX(-50%);width:4.5px;height:4.5px;border-radius:9999px;background-color:${effColor};"></span>`;
      } else if (modeId === 'star') {
        innerDecorationHtml = `<svg width="7.5" height="7.5" viewBox="0 0 512 512" shape-rendering="geometricPrecision" style="position:absolute;top:1.5px;right:1.5px;display:block;pointer-events:none;"><path d="M164.9 24.6c-7.7-18.6-28-28.5-47.4-23.2l-88 24C12.1 30.2 0 46 0 64C0 311.4 200.6 512 448 512c18 0 33.8-12.1 38.6-29.5l24-88c5.3-19.4-4.6-39.7-23.2-47.4l-96-40c-16.3-6.8-35.2-2.1-46.3 11.6L304.7 368C234.3 334.7 177.3 277.7 144 207.3L193.3 167c13.7-11.2 18.4-30 11.6-46.3l-40-96z" fill="${effColor}"/></svg>`;
      } else if (modeId === 'bold-number') {
        numStyle = isTaken ? 'color:#94a3b8; font-weight:700;' : `color:${effColor}; font-weight:800;`;
      } else if (modeId === 'circle') {
        innerDecorationHtml = `<span style="position:absolute;width:21px;height:21px;border-radius:9999px;background:radial-gradient(circle closest-side at 50% 50%, ${effColor}55 0%, ${effColor}38 26%, ${effColor}1c 52%, ${effColor}08 74%, ${effColor}00 92%, transparent 100%);pointer-events:none;"></span>`;
      } else if (modeId === 'highlight') {
        dayBoxStyle = isTaken ? 'background-color:#f1f5f9; border:1px solid #cbd5e1; opacity:0.45;' : `background-color:${effColor}18; border:1px solid ${effColor}38;`;
        numStyle = isTaken ? 'color:#94a3b8; font-weight:600;' : `color:${effColor}; font-weight:700;`;
      } else if (modeId === 'soft-frame') {
        dayBoxStyle = isTaken ? 'background-color:#f1f5f9; border:1px solid #cbd5e1; opacity:0.45;' : `background-color:#ffffff; border:1px solid ${effColor}38;`;
        numStyle = isTaken ? 'color:#94a3b8; font-weight:400;' : `color:#334155; font-weight:400;`;
      } else if (modeId === 'dashed') {
        dayBoxStyle = isTaken ? 'background-color:#f1f5f9; border:1px dashed #cbd5e1; opacity:0.45;' : `background-color:#ffffff; border:1px dashed ${effColor}80;`;
        numStyle = isTaken ? 'color:#94a3b8; font-weight:600;' : `color:${effColor}; font-weight:700;`;
      } else if (modeId === 'underline') {
        innerDecorationHtml = `<span style="position:absolute;inset:1.5px;pointer-events:none;"><span style="position:absolute;top:0;left:0;width:5px;height:5px;border-top:1.5px solid ${effColor};border-left:1.5px solid ${effColor};border-top-left-radius:3px;"></span><span style="position:absolute;bottom:0;right:0;width:5px;height:5px;border-bottom:1.5px solid ${effColor};border-right:1.5px solid ${effColor};border-bottom-right-radius:3px;"></span></span>`;
      } else if (modeId === 'bottom-arc' || modeId === 'star-bg') {
        // Star behind the calendar number taking over the entire day square and framing the number
        innerDecorationHtml = `<svg class="cal-mini-star-bg" viewBox="0 0 24 24" shape-rendering="geometricPrecision" style="position:absolute;top:48%;left:50%;transform:translate(-50%, -50%);width:112%;height:112%;pointer-events:none;z-index:0;opacity:${isTaken ? '0.2' : '0.58'};"><polygon points="12,1.5 15.3,7.9 22.3,9 17.2,14.1 18.4,21.2 12,17.8 5.6,21.2 6.8,14.1 1.7,9 8.7,7.9" fill="${effColor}"/></svg>`;
        numStyle = isTaken ? 'color:#94a3b8; font-weight:500;' : `color:#1e293b; font-weight:600;`;
      } else if (modeId === 'side-pill') {
        innerDecorationHtml = `<svg width="8" height="8" viewBox="0 0 8 8" shape-rendering="geometricPrecision" style="position:absolute;top:0;left:0;display:block;pointer-events:none;"><polygon points="0,0 8,0 0,8" fill="${effColor}"/></svg>`;
      } else if (modeId === 'corner-pip') {
        innerDecorationHtml = `<span style="position:absolute;top:2.5px;right:2.5px;width:5px;height:5px;border-radius:9999px;background-color:${effColor};box-shadow:0 0 0 1px #ffffff;"></span>`;
      } else if (modeId === 'double-ring') {
        innerDecorationHtml = `<span style="position:absolute;width:21px;height:21px;border-radius:9999px;background:radial-gradient(circle closest-side at 50% 50%, transparent 0%, transparent 32%, ${effColor}14 48%, ${effColor}42 64%, ${effColor}18 80%, ${effColor}00 94%, transparent 100%);pointer-events:none;"></span>`;
      } else if (modeId === 'glass-tint') {
        dayBoxStyle = isTaken ? 'background-color:#f1f5f9; border:1px solid #cbd5e1; opacity:0.45;' : `background:linear-gradient(135deg, ${effColor}32 0%, ${effColor}10 55%, #ffffff 100%); border:1px solid ${effColor}40;`;
        numStyle = isTaken ? 'color:#94a3b8; font-weight:600;' : `color:${effColor}; font-weight:700;`;
      }

      let wrapperStateCls = '';
      if (isSelected) {
        wrapperStateCls = 'bg-white ring-2 ring-slate-900 shadow-xs scale-[1.03] font-bold text-slate-900';
      } else if (isTaken) {
        wrapperStateCls = 'bg-slate-100/60 text-slate-400 hover:text-slate-600 cursor-pointer border border-dashed border-slate-200/90 shadow-none opacity-60 hover:opacity-90';
      } else {
        wrapperStateCls = 'bg-white/80 hover:bg-white text-slate-600 hover:text-slate-900 cursor-pointer border border-slate-200/80 hover:border-slate-300 shadow-2xs hover:scale-[1.02]';
      }

      return `
        <button type="button"
                class="cal-studio-mini-style-pill flex-1 min-w-0 py-1.5 px-0.5 rounded-xl transition-all flex flex-col items-center justify-center gap-1 ${wrapperStateCls}"
                data-source-key="${escapeHtml(sourceKey)}"
                data-style-mode="${escapeHtml(modeId)}"
                ${titleAttr}>
          <div class="relative w-6 h-6 rounded-[6px] flex items-center justify-center text-[10px] leading-none shrink-0" style="${dayBoxStyle}">
            ${innerDecorationHtml}
            <span class="relative z-[1]" style="${numStyle}">10</span>
          </div>
          <span class="text-[9px] font-semibold leading-tight truncate max-w-full px-0.5">${escapeHtml(label)}</span>
        </button>
      `;
    }

    let previewCss = '';
    if (modeId === 'highlight') {
      previewCss = targetKind === 'main'
        ? `background-color:${effColor}18; border:1px solid transparent; color:${effColor};`
        : `background-color:${effColor}18; border:1px solid ${effColor}35; color:${effColor};`;
    } else if (modeId === 'framed') {
      previewCss = `background-color:#ffffff; border:1px solid ${effColor}45; color:${effColor};`;
    } else if (modeId === 'dashed') {
      previewCss = `background-color:#ffffff; border:1px dashed ${effColor}70; color:${effColor};`;
    } else if (modeId === 'underline') {
      previewCss = `background-color:#f8fafc; border:1px solid #e2e8f0; border-bottom:2px solid ${effColor}; color:#0f172a;`;
    } else if (modeId === 'gradient') {
      previewCss = `background:linear-gradient(90deg, ${effColor}28 0%, ${effColor}08 65%, #ffffff 100%); border:1px solid ${effColor}35; color:${effColor};`;
    } else if (modeId === 'bold-number') {
      previewCss = `background-color:#ffffff; border:1px solid #e2e8f0; color:${effColor}; font-weight:800;`;
    } else if (modeId === 'circle') {
      previewCss = `background:radial-gradient(circle at 50% 50%, ${effColor}36 0%, ${effColor}10 68%, #ffffff 100%); border:1px solid #e2e8f0; color:#334155;`;
    } else if (modeId === 'badge') {
      previewCss = `background-color:${effColor}; border:1px solid ${effColor}; color:#ffffff;`;
    } else {
      previewCss = `background-color:#ffffff; border:1px solid #e2e8f0; color:#334155;`;
    }

    const activeRing = isSelected
      ? 'ring-2 ring-slate-900 shadow-2xs scale-[1.01]'
      : 'opacity-85 hover:opacity-100 cursor-pointer';
    const btnClass = targetKind === 'main' ? 'cal-studio-main-style-pill' : 'cal-studio-mini-style-pill';

    let shapeIconHtml = '';
    if (modeId === 'dot') {
      shapeIconHtml = `<span class="w-2 h-2 rounded-full shrink-0" style="background-color:${effColor};"></span>`;
    } else if (modeId === 'star') {
      shapeIconHtml = `<svg width="8.5" height="8.5" viewBox="0 0 10 10" class="shrink-0" style="display:block;"><polygon points="5,0.4 6.35,3.3 9.5,3.7 7.15,5.9 7.78,9.05 5,7.45 2.22,9.05 2.85,5.9 0.5,3.7 3.65,3.3" fill="${effColor}"/></svg>`;
    } else if (modeId === 'circle') {
      shapeIconHtml = `<span class="w-3 h-3 rounded-full shrink-0" style="background:radial-gradient(circle, ${effColor} 0%, ${effColor}d9 48%, ${effColor}45 76%, transparent 100%);"></span>`;
    }

    return `
      <button type="button"
              class="${btnClass} relative flex-1 justify-center px-2 py-1 rounded-lg text-[10.5px] font-semibold transition-all flex items-center gap-1 whitespace-nowrap ${activeRing}"
              style="${previewCss}"
              data-source-key="${escapeHtml(sourceKey)}"
              data-style-mode="${escapeHtml(modeId)}"
              ${titleAttr}>
        ${shapeIconHtml}
        <span>${escapeHtml(label)}</span>
      </button>
    `;
  }

  function renderCalPlanStyleStudio() {
    const bodyEl = document.getElementById('calPlanStyleStudioBody');
    if (!bodyEl) return;
    if (!state.calendarPlan) loadCalendarPlanData();
    const cp = state.calendarPlan;
    ensureUniqueMiniCalStyles(cp.sources);

    const sourceKeys = ['projects', 'leads', 'my_plan', 'meetings', 'bills'];
    const findMiniTakenByLabel = (modeId, currentOwnerKey) => {
      if (modeId === 'dot') return null; // Dot is universal and can be shared by all segments
      if (currentOwnerKey !== 'projects' && cp.sources.projects?.miniStyle === modeId) {
        return 'Work Milestones';
      }
      if (currentOwnerKey !== 'projects_payment' && cp.sources.projects?.paymentMiniStyle === modeId) {
        return 'Payment Due Date';
      }
      for (const otherKey of sourceKeys) {
        if (otherKey !== 'projects' && otherKey !== currentOwnerKey && (cp.sources[otherKey]?.miniStyle) === modeId) {
          return cp.sources[otherKey]?.label || otherKey;
        }
      }
      return null;
    };

    const rowsHtml = sourceKeys.map(key => {
      const src = cp.sources[key] || DEFAULT_CAL_PLAN_SOURCES[key];
      const effMainStyle = src.mainStyle === 'framed-highlight' ? 'highlight' : (src.mainStyle || 'highlight');

      if (key === 'projects') {
        const shareColor = src.sharePaymentColor !== false;
        const payColor = shareColor ? src.color : (src.paymentColor || src.color || '#0284c7');
        const effPayMainStyle = (src.paymentMainStyle === 'framed-highlight' || !src.paymentMainStyle) ? 'framed' : src.paymentMainStyle;
        const effPayMiniStyle = src.paymentMiniStyle || 'bottom-arc';

        return `
          <div class="p-4 rounded-2xl bg-slate-50/70 border border-slate-200/80 space-y-3">
            <!-- Top Row: Projects Header & Master Toggles -->
            <div class="flex flex-wrap items-center justify-between gap-2">
              <div class="flex items-center gap-2">
                <span class="w-3 h-3 rounded-full shrink-0" style="background-color: ${escapeHtml(src.color)};"></span>
                <span class="text-xs font-bold text-slate-900">${escapeHtml(src.label)}</span>
              </div>
              <div class="flex items-center gap-3 text-xs flex-wrap">
                <label class="inline-flex items-center gap-1.5 cursor-pointer select-none text-slate-700 font-medium">
                  <input type="checkbox" class="cal-studio-show-main rounded border-slate-300 text-teal-600" data-source-key="projects" ${src.showOnMain !== false ? 'checked' : ''}>
                  <span>Show on Main Calendar</span>
                </label>
                <label class="inline-flex items-center gap-1.5 cursor-pointer select-none text-slate-700 font-medium">
                  <input type="checkbox" class="cal-studio-show-mini rounded border-slate-300 text-teal-600" data-source-key="projects" ${src.showOnMiniCal !== false ? 'checked' : ''}>
                  <span>Sidebar Mini-Calendar</span>
                </label>
              </div>
            </div>

            <!-- Sub-Area 1: Work Deadline & Milestones -->
            <div class="p-3.5 rounded-xl bg-white border border-slate-200/80 space-y-2.5 shadow-2xs">
              <div class="flex flex-wrap items-center justify-between gap-2">
                <div class="flex items-center gap-1.5">
                  <span class="w-2.5 h-2.5 rounded-full shrink-0" style="background-color: ${escapeHtml(src.color)};"></span>
                  <span class="text-[11px] font-bold text-slate-800">Work Deadline &amp; Milestones</span>
                </div>
                ${buildCalStudioColorChooserHtml('projects', src.color)}
              </div>

              <div class="space-y-1">
                <span class="block text-[10px] font-bold uppercase tracking-wider text-slate-400">Main Calendar Display Style</span>
                <div class="flex items-center justify-between gap-1.5 w-full">
                  ${CAL_STYLE_MODES.map(m => buildVisualStylePreviewPill(m.id, m.label, src.color, effMainStyle === m.id, 'main', 'projects', null)).join('')}
                </div>
              </div>

              <div class="space-y-1">
                <span class="block text-[10px] font-bold uppercase tracking-wider text-slate-400">Sidebar Mini-Calendar Display Style</span>
                <div class="grid grid-cols-13 gap-1 w-full" style="grid-template-columns: repeat(13, minmax(0, 1fr));">
                  ${MINI_CAL_STYLE_MODES.map(m => {
                    const takenByLabel = findMiniTakenByLabel(m.id, 'projects');
                    return buildVisualStylePreviewPill(m.id, m.label, src.color, src.miniStyle === m.id, 'mini', 'projects', takenByLabel);
                  }).join('')}
                </div>
              </div>
            </div>

            <!-- Sub-Area 2: Payment Due Date -->
            <div class="p-3.5 rounded-xl bg-white border border-slate-200/80 space-y-2.5 shadow-2xs">
              <div class="flex flex-wrap items-center justify-between gap-2">
                <div class="flex items-center gap-2">
                  <span class="w-2.5 h-2.5 rounded-full shrink-0" style="background-color: ${escapeHtml(payColor)};"></span>
                  <span class="text-[11px] font-bold text-slate-800">Payment Due Date</span>
                  ${!shareColor ? `
                    <button type="button" class="cal-studio-proj-sync-color-btn px-2 py-0.5 rounded-md text-[10px] font-semibold border border-slate-200/80 bg-slate-100 text-slate-600 hover:bg-slate-200/70 transition-colors cursor-pointer" title="Re-sync with Work Milestones color">
                      Match Work Color
                    </button>
                  ` : `
                    <span class="px-2 py-0.5 rounded-md text-[10px] font-medium text-slate-500 bg-slate-100/70 border border-slate-200/60">Using Work Color</span>
                  `}
                </div>
                ${buildCalStudioColorChooserHtml('projects_payment', payColor)}
              </div>

              <div class="space-y-1">
                <span class="block text-[10px] font-bold uppercase tracking-wider text-slate-400">Main Calendar Display Style</span>
                <div class="flex items-center justify-between gap-1.5 w-full">
                  ${CAL_STYLE_MODES.map(m => buildVisualStylePreviewPill(m.id, m.label, payColor, effPayMainStyle === m.id, 'main', 'projects_payment', null)).join('')}
                </div>
              </div>

              <div class="space-y-1">
                <span class="block text-[10px] font-bold uppercase tracking-wider text-slate-400">Sidebar Mini-Calendar Display Style</span>
                <div class="grid grid-cols-13 gap-1 w-full" style="grid-template-columns: repeat(13, minmax(0, 1fr));">
                  ${MINI_CAL_STYLE_MODES.map(m => {
                    const takenByLabel = findMiniTakenByLabel(m.id, 'projects_payment');
                    return buildVisualStylePreviewPill(m.id, m.label, payColor, effPayMiniStyle === m.id, 'mini', 'projects_payment', takenByLabel);
                  }).join('')}
                </div>
              </div>
            </div>
          </div>
        `;
      }

      return `
        <div class="p-4 rounded-2xl bg-slate-50/70 border border-slate-200/80 space-y-3">
          <!-- Top Row: Source Name, Color Swatches & Visibility Toggles -->
          <div class="flex flex-wrap items-center justify-between gap-2">
            <div class="flex items-center gap-2">
              <span class="w-3 h-3 rounded-full shrink-0" style="background-color: ${escapeHtml(src.color)};"></span>
              <span class="text-xs font-bold text-slate-900">${escapeHtml(src.label)}</span>
            </div>
            <div class="flex items-center gap-3 text-xs flex-wrap">
              <label class="inline-flex items-center gap-1.5 cursor-pointer select-none text-slate-700 font-medium">
                <input type="checkbox" class="cal-studio-show-main rounded border-slate-300 text-teal-600" data-source-key="${escapeHtml(key)}" ${src.showOnMain !== false ? 'checked' : ''}>
                <span>Show on Main Calendar</span>
              </label>
              ${key === 'my_plan' ? `
                <div class="inline-flex items-center gap-1.5">
                  <label for="calStudioMyPlanMiniScope" class="text-slate-600 font-medium text-xs">Sidebar Mini-Calendar:</label>
                  <select id="calStudioMyPlanMiniScope" class="cal-studio-mini-scope bg-white border border-slate-200/90 hover:border-slate-300 rounded-xl px-2.5 py-1 text-xs font-semibold text-slate-700 shadow-2xs focus:outline-hidden focus:ring-1 focus:ring-teal-500 cursor-pointer transition-all" data-source-key="my_plan">
                    <option value="week" ${(src.showOnMiniCal !== false && (src.miniCalScope || 'week') === 'week') ? 'selected' : ''}>Show only respective week</option>
                    <option value="all" ${(src.showOnMiniCal !== false && src.miniCalScope === 'all') ? 'selected' : ''}>Show all items in sidebar mini-calendar</option>
                    <option value="none" ${src.showOnMiniCal === false ? 'selected' : ''}>Don't show in sidebar mini-calendar</option>
                  </select>
                </div>
              ` : `
                <label class="inline-flex items-center gap-1.5 cursor-pointer select-none text-slate-700 font-medium">
                  <input type="checkbox" class="cal-studio-show-mini rounded border-slate-300 text-teal-600" data-source-key="${escapeHtml(key)}" ${src.showOnMiniCal !== false ? 'checked' : ''}>
                  <span>Sidebar Mini-Calendar</span>
                </label>
              `}
            </div>
          </div>

          <!-- Interactive Visual Style Pills & Swatches -->
          <div class="space-y-2.5 pt-2.5 border-t border-slate-200/60">
            <div class="flex flex-wrap items-center justify-between gap-2">
              <span class="text-[10px] font-bold uppercase tracking-wider text-slate-400">Accent Color</span>
              ${buildCalStudioColorChooserHtml(key, src.color)}
            </div>

            <div class="space-y-1">
              <span class="block text-[10px] font-bold uppercase tracking-wider text-slate-400">Main Calendar Display Style</span>
              <div class="flex items-center justify-between gap-1.5 w-full">
                ${CAL_STYLE_MODES.map(m => buildVisualStylePreviewPill(m.id, m.label, src.color, effMainStyle === m.id, 'main', key, null)).join('')}
              </div>
            </div>

            <div class="space-y-1">
              <span class="block text-[10px] font-bold uppercase tracking-wider text-slate-400">Sidebar Mini-Calendar Display Style</span>
              <div class="grid grid-cols-13 gap-1 w-full" style="grid-template-columns: repeat(13, minmax(0, 1fr));">
                ${MINI_CAL_STYLE_MODES.map(m => {
                  const takenByLabel = findMiniTakenByLabel(m.id, key);
                  return buildVisualStylePreviewPill(m.id, m.label, src.color, src.miniStyle === m.id, 'mini', key, takenByLabel);
                }).join('')}
              </div>
            </div>
          </div>
        </div>
      `;
    }).join('');

    const currentWeekStart = cp.weekStart === 'monday' ? 'monday' : 'sunday';
    const weekStartToggleHtml = `
      <div class="p-3.5 rounded-2xl bg-slate-50/70 border border-slate-200/80 flex flex-wrap items-center justify-between gap-3">
        <div class="flex items-center gap-2">
          <i data-lucide="calendar-range" class="w-4 h-4 text-teal-600 shrink-0"></i>
          <div>
            <div class="text-xs font-bold text-slate-900">Week Format</div>
            <div class="text-[11px] text-slate-500">Applies only to Calendar &amp; Plan (Sidebar Mini-Calendar is unchanged)</div>
          </div>
        </div>
        <div class="inline-flex items-center p-0.5 bg-white border border-slate-200/90 rounded-xl text-xs font-semibold shadow-2xs shrink-0">
          <button type="button"
                  class="cal-studio-week-start-btn px-3 py-1.5 rounded-lg transition-all cursor-pointer flex items-center gap-1.5 whitespace-nowrap ${currentWeekStart === 'sunday' ? 'bg-slate-900 text-white font-bold shadow-2xs' : 'text-slate-600 hover:text-slate-900'}"
                  data-week-start="sunday">
            <span>Sunday – Saturday</span>
          </button>
          <button type="button"
                  class="cal-studio-week-start-btn px-3 py-1.5 rounded-lg transition-all cursor-pointer flex items-center gap-1.5 whitespace-nowrap ${currentWeekStart === 'monday' ? 'bg-slate-900 text-white font-bold shadow-2xs' : 'text-slate-600 hover:text-slate-900'}"
                  data-week-start="monday">
            <span>Monday – Sunday</span>
          </button>
        </div>
      </div>
    `;

    bodyEl.innerHTML = `
      <div class="space-y-3">
        ${weekStartToggleHtml}
        ${rowsHtml}
      </div>
    `;
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      try { window.lucide.createIcons(); } catch (e) {}
    }
  }

  function openCalPlanStyleStudioModal() {
    if (!state.calendarPlan) loadCalendarPlanData();
    state._calStyleStudioSavedSources = JSON.parse(JSON.stringify(state.calendarPlan.sources || DEFAULT_CAL_PLAN_SOURCES));
    state._calStyleStudioSavedDayStyles = JSON.parse(JSON.stringify(state.calendarPlan.dayStyles || {}));
    state._calStyleStudioSavedPalettes = JSON.parse(JSON.stringify(state.calendarPlan.customPalettes || {}));
    state._calStyleStudioSavedDeletedColors = JSON.parse(JSON.stringify(state.calendarPlan.deletedPaletteColors || {}));
    state._calStyleStudioSavedCustomColors = JSON.parse(JSON.stringify(state.calendarPlan.customPaletteColors || []));
    state._calStyleStudioSavedWeekStart = state.calendarPlan.weekStart === 'monday' ? 'monday' : 'sunday';
    state._calStyleStudioSavedAnchorDate = state.calendarPlan.anchorDate;
    state._isCalStylePreviewOpen = true;
    renderCalPlanStyleStudio();
    const modal = document.getElementById('calPlanStyleStudioModal');
    if (!modal) return;
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      try { window.lucide.createIcons(); } catch (e) {}
    }
  }

  function closeCalPlanStyleStudioModal(commitChanges = false) {
    const modal = document.getElementById('calPlanStyleStudioModal');
    if (!modal) return;
    state._isCalStylePreviewOpen = false;
    if (commitChanges) {
      state._calStyleStudioSavedSources = null;
      state._calStyleStudioSavedDayStyles = null;
      state._calStyleStudioSavedPalettes = null;
      state._calStyleStudioSavedDeletedColors = null;
      state._calStyleStudioSavedCustomColors = null;
      state._calStyleStudioSavedWeekStart = null;
      state._calStyleStudioSavedAnchorDate = null;
      saveCalendarPlanData();
      renderCalendarPlanView();
      renderSidebarSubscriptionCalendar();
      showToast('Appearance Saved ✓', 'Calendar & Plan styles updated.', 'success');
    } else if (state._calStyleStudioSavedSources) {
      state.calendarPlan.sources = JSON.parse(JSON.stringify(state._calStyleStudioSavedSources));
      if (state._calStyleStudioSavedDayStyles) {
        state.calendarPlan.dayStyles = JSON.parse(JSON.stringify(state._calStyleStudioSavedDayStyles));
      }
      if (state._calStyleStudioSavedPalettes) {
        state.calendarPlan.customPalettes = JSON.parse(JSON.stringify(state._calStyleStudioSavedPalettes));
      }
      if (state._calStyleStudioSavedDeletedColors) {
        state.calendarPlan.deletedPaletteColors = JSON.parse(JSON.stringify(state._calStyleStudioSavedDeletedColors));
      }
      if (state._calStyleStudioSavedCustomColors) {
        state.calendarPlan.customPaletteColors = JSON.parse(JSON.stringify(state._calStyleStudioSavedCustomColors));
      }
      if (state._calStyleStudioSavedWeekStart) {
        state.calendarPlan.weekStart = state._calStyleStudioSavedWeekStart;
      }
      if (state._calStyleStudioSavedAnchorDate) {
        state.calendarPlan.anchorDate = state._calStyleStudioSavedAnchorDate;
      }
      state._calStyleStudioSavedSources = null;
      state._calStyleStudioSavedDayStyles = null;
      state._calStyleStudioSavedPalettes = null;
      state._calStyleStudioSavedDeletedColors = null;
      state._calStyleStudioSavedCustomColors = null;
      state._calStyleStudioSavedWeekStart = null;
      state._calStyleStudioSavedAnchorDate = null;
      renderCalendarPlanView();
      renderSidebarSubscriptionCalendar();
    }
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }

  function spotlightNoteInNotesView(noteId) {
    if (!noteId) return;
    // Clear any active search or label filter in Notes so the target note is guaranteed visible
    if (state.notesLabelFilter && state.notesLabelFilter !== 'ALL') {
      state.notesLabelFilter = 'ALL';
    }
    if (state.notesSearch) {
      state.notesSearch = '';
      const sInput = document.getElementById('notesSearchInput');
      if (sInput) sInput.value = '';
    }
    const targetNote = (state.notes || []).find(n => n && n.id === noteId);
    if (targetNote && (targetNote.isDone || targetNote.completed)) {
      state.notesArchiveCollapsed = false;
    }

    if (window._ftSetActiveTab) {
      window._ftSetActiveTab('notes');
    }
    if (typeof renderNotesView === 'function') {
      renderNotesView();
    }

    setTimeout(() => {
      const cardEl = document.querySelector(`.note-card[data-note-id="${CSS.escape ? CSS.escape(noteId) : noteId}"]`);
      if (!cardEl) return;
      const nColor = targetNote && typeof getNoteCategoryColor === 'function' ? getNoteCategoryColor(targetNote) : '#0d9488';
      cardEl.style.setProperty('--spotlight-note-color', nColor);
      cardEl.style.setProperty('--spotlight-note-ring', `${nColor}38`);
      cardEl.style.setProperty('--spotlight-note-tint', `${nColor}12`);
      cardEl.classList.remove('note-card-spotlight-pop');
      void cardEl.offsetWidth; // trigger reflow for animation replay
      cardEl.classList.add('note-card-spotlight-pop');
      try {
        cardEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      } catch (e) {
        cardEl.scrollIntoView();
      }
      setTimeout(() => {
        cardEl.classList.remove('note-card-spotlight-pop');
      }, 2600);
    }, 60);
  }

  function exportCalendarPlanToIcs() {
    if (!state.calendarPlan) loadCalendarPlanData();
    const lines = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//Finland//Calendar and Plan//EN',
      'CALSCALE:GREGORIAN',
      'METHOD:PUBLISH'
    ];
    // Helper to format ISO or YYYY-MM-DD + HH:mm for ICS
    function formatIcsDateTime(dateStr, timeStr) {
      const dtClean = (dateStr || '').replace(/-/g, '');
      if (!timeStr) {
        return { isAllDay: true, val: dtClean };
      }
      const parts = timeStr.split(':');
      const hh = (parts[0] || '00').padStart(2, '0');
      const mm = (parts[1] || '00').padStart(2, '0');
      return { isAllDay: false, val: `${dtClean}T${hh}${mm}00` };
    }

    // Include both custom calendar items/meetings and active Project Deadlines
    (state.calendarPlan.items || []).forEach(item => {
      if (!item || !item.date) return;
      const startDt = formatIcsDateTime(item.date, item.time);
      lines.push('BEGIN:VEVENT');
      lines.push(`UID:${item.id}@finland.local`);
      lines.push(`SUMMARY:${(item.title || 'Event').replace(/\n/g, ' ')}`);
      if (startDt.isAllDay) {
        lines.push(`DTSTART;VALUE=DATE:${startDt.val}`);
        lines.push(`DTEND;VALUE=DATE:${startDt.val}`);
      } else {
        lines.push(`DTSTART:${startDt.val}`);
        // Default 1 hour end if timed
        const parts = (item.time || '10:00').split(':');
        const endH = String((parseInt(parts[0] || '10', 10) + 1) % 24).padStart(2, '0');
        const endMm = (parts[1] || '00').padStart(2, '0');
        lines.push(`DTEND:${item.date.replace(/-/g, '')}T${endH}${endMm}00`);
      }
      if (item.location) lines.push(`LOCATION:${item.location.replace(/\n/g, ' ')}`);
      if (item.source === 'meetings' || item.subType === 'meetings') lines.push('CATEGORIES:MEETING');
      lines.push('END:VEVENT');
    });
    ((state.budget && state.budget.projects) || []).forEach(proj => {
      if (!proj || proj.status === 'completed' || proj.status === 'paid' || !proj.dueDate) return;
      const dtClean = proj.dueDate.replace(/-/g, '');
      const pTitle = `Deadline: ${proj.title || proj.name || 'Project'}${proj.client ? ' (' + proj.client + ')' : ''}`;
      lines.push('BEGIN:VEVENT');
      lines.push(`UID:proj_deadline_${proj.id}@finland.local`);
      lines.push(`SUMMARY:${pTitle.replace(/\n/g, ' ')}`);
      lines.push(`DTSTART;VALUE=DATE:${dtClean}`);
      lines.push(`DTEND;VALUE=DATE:${dtClean}`);
      lines.push('END:VEVENT');
    });
    lines.push('END:VCALENDAR');
    const blob = new Blob([lines.join('\r\n')], { type: 'text/calendar;charset=utf-8' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `finland-calendar-plan-${formatLocalYMD(new Date())}.ics`;
    a.click();
    showToast('Exported .ics Calendar', 'Includes Meetings, Calendar events & active Project Deadlines.', 'success');
  }

  async function pushEventToGoogleCalendarApi({ title, date, time, location, gcalToken }) {
    if (!gcalToken || !title || !date) return false;
    try {
      const cleanDt = date.replace(/-/g, '');
      let startObj = { date: date };
      let endObj = { date: date };
      if (time) {
        const parts = time.split(':');
        const hh = (parts[0] || '10').padStart(2, '0');
        const mm = (parts[1] || '00').padStart(2, '0');
        const endH = String((parseInt(hh, 10) + 1) % 24).padStart(2, '0');
        startObj = { dateTime: `${date}T${hh}:${mm}:00Z` };
        endObj = { dateTime: `${date}T${endH}:${mm}:00Z` };
      }
      const payload = {
        summary: title,
        location: location || '',
        description: 'Scheduled via Finland Calendar & Plan',
        start: startObj,
        end: endObj
      };
      const res = await fetch('https://www.googleapis.com/calendar/v3/calendars/primary/events', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${gcalToken}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(payload)
      });
      return res.ok;
    } catch (err) {
      console.warn('Google Calendar API push error:', err);
      return false;
    }
  }

